using System.Diagnostics;
using System.IO;
using System.IO.MemoryMappedFiles;
using System.Net;
using System.Net.Sockets;
using Microsoft.Win32;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Runtime.Loader;
using System.Linq.Expressions;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Collections.Concurrent;
using System.Threading.Channels;
using System.Windows.Threading;

namespace YeManFanHost;

internal static class Program
{
    /**
     * 920 §8.0-B：区分三类证据，不互相冒充。
     * - assemblyMvid：加载进本进程的模块版本 id = **实际加载证据**；事后替换磁盘
     *   文件不会改变它，因此能证明"当时运行的是哪一份程序集"。
     * - assemblyFileSha256：启动时刻该路径上的文件哈希 = **启动时磁盘证据**；
     *   之后磁盘可能被替换，故与 MVID 分开记录。
     * - payloadManifestSha256 / payloadDeclaredDllSha256：本 Host 目录内 payload
     *   清单身份及其声明的业务 DLL 哈希；assemblyMatchesPayload 给出自洽判定。
     */
    private static object CollectHostIdentityEvidence()
    {
        var assemblyPath = string.Empty;
        var assemblyMvid = "unknown";
        var assemblyFileSha256 = "unknown";
        try
        {
            var assembly = Assembly.GetExecutingAssembly();
            assemblyPath = assembly.Location ?? string.Empty;
            assemblyMvid = Convert.ToHexString(assembly.ManifestModule.ModuleVersionId.ToByteArray()).ToLowerInvariant();
            if (assemblyPath.Length > 0 && File.Exists(assemblyPath))
                assemblyFileSha256 = Sha256FileOrUnknown(assemblyPath);
        }
        catch (Exception ex)
        {
            assemblyMvid = "error:" + ex.GetType().Name;
        }

        var payloadManifestPath = Path.Combine(AppContext.BaseDirectory, "YeManFanHost.payload.json");
        var payloadManifestSha256 = "missing";
        var payloadDeclaredDllSha256 = "missing";
        if (File.Exists(payloadManifestPath))
        {
            payloadManifestSha256 = Sha256FileOrUnknown(payloadManifestPath);
            try
            {
                using var document = JsonDocument.Parse(File.ReadAllText(payloadManifestPath));
                if (document.RootElement.TryGetProperty("files", out var files) && files.ValueKind == JsonValueKind.Array)
                {
                    foreach (var entry in files.EnumerateArray())
                    {
                        if (entry.TryGetProperty("path", out var path) &&
                            string.Equals(path.GetString(), "YeManFanHost.dll", StringComparison.OrdinalIgnoreCase) &&
                            entry.TryGetProperty("sha256", out var hash))
                        {
                            payloadDeclaredDllSha256 = (hash.GetString() ?? string.Empty).ToLowerInvariant();
                            break;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                payloadDeclaredDllSha256 = "error:" + ex.GetType().Name;
            }
        }

        // 未知不捏造成成功：只有三类证据都真实取到才给出自洽判定。
        var assemblyMatchesPayload = "unknown";
        if (assemblyFileSha256.Length == 64 && payloadDeclaredDllSha256.Length == 64)
        {
            assemblyMatchesPayload = string.Equals(assemblyFileSha256, payloadDeclaredDllSha256, StringComparison.OrdinalIgnoreCase)
                ? "true"
                : "false";
        }

        return new
        {
            assemblyPath,
            assemblyMvid,
            assemblyFileSha256,
            payloadManifestPath,
            payloadManifestSha256,
            payloadDeclaredDllSha256,
            assemblyMatchesPayload,
            // 显式声明该事件的证据范围，避免下游把磁盘哈希当成加载时哈希。
            evidenceScope = "assemblyMvid=load-time; assemblyFileSha256/payload*=startup-disk",
        };
    }

    private static string Sha256FileOrUnknown(string path)
    {
        try
        {
            return Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant();
        }
        catch (Exception ex)
        {
            return "error:" + ex.GetType().Name;
        }
    }

    public static async Task<int> Main(string[] args)
    {
        #if YEMAN_ASYNC_BOUNDARY_TEST
        // 920-v1.5 §17.1-5：故意崩溃的探针**只存在于测试专用构建**
        // （dotnet build -p:YemanAsyncBoundaryTest=true）。正式构建里这两个
        // 分支在编译期就不存在，因此正常生产启动不会被环境变量或开关改道。
        if (args.Any(arg => string.Equals(arg, "--async-boundary-crash-probe", StringComparison.Ordinal)))
        {
            var crashProbeChecks = RealHcBackend.RunHcAsyncBoundaryChildThrowProbe();
            Console.WriteLine(JsonSerializer.Serialize(new { ok = true, checks = crashProbeChecks }, JsonDefaults.Options));
            return 0;
        }
#endif

        // §17.4-C：strict 模式把"旧工作改变关闭后/新会话状态"升级为**失败断言**。
        RealHcBackend.HcAsyncBoundaryStrict = args.Any(arg =>
            string.Equals(arg, "--async-boundary-strict", StringComparison.Ordinal));
        // 该开关是本测试套件专有，不进入 HostOptions 的正式参数表。
        var hostArgs = RealHcBackend.HcAsyncBoundaryStrict
            ? args.Where(arg => !string.Equals(arg, "--async-boundary-strict", StringComparison.Ordinal)).ToArray()
            : args;
        var options = HostOptions.Parse(hostArgs);
        if (options.ShowHelp)
        {
            HostOptions.PrintHelp();
            return 0;
        }

        // FAN-936 §1：微星**只读**开机取证采样。必须处理在"取得生命周期互斥"与
        // "自测日志隔离"**之前**：
        //  ① 本条路径零硬件写入（只调用 HC 的只读采样，绝不调用会改变状态的 Open()），
        //     因此不需要 owner 互斥，也不应因此拒停日常 Host；
        //  ② 它要采集的正是"下次开机时硬件真实保留了哪些位/表"的现场，绝不能落进
        //     自测隔离根污染生产账本。
        // 失败不静默：异常由调用方以非零码暴露（失败也不得写成一次"成功采样"）。
        if (options.MsiReadOnlySample)
        {
            using var msiProbe = new RealHcBackend(options);
            var (msiSnapshot, msiExitCode) = msiProbe.CaptureMsiReadOnlySnapshot();
            Console.WriteLine(JsonSerializer.Serialize(msiSnapshot, JsonDefaults.Options));
            // 采样失败不得以 exit0 冒充成功：只有真正完成一次只读采样才返回 0。
            return msiExitCode;
        }

        // 2026-09-24 裁决卡 §6-A（取证隔离）：自测 / 故障注入 / 模拟器一律落到
        // run 级隔离日志根，避免夹具内容污染生产账本。此后所有无参
        // `new HostDiagnosticLog()`（含 Section18/19 候选自测、嵌套引擎、后台重试）
        // 与自测拉起的子进程都会自动继承该根。
        if (options.SelfTest) HostDiagnosticLog.EnterSelfTestLogIsolation("fanhost");

        // The listener port is not an ownership primitive: a resident Host
        // can temporarily lose and recreate its listener while it still owns
        // an HC session. Keep an OS-owned lifetime handle so a second Host
        // never overlaps the first one's hardware lifecycle.
        // §4.1（FAN-926 P2）：受控更换的**后继实例**改为有界等待（拿到互斥 = 旧实例确已退出，
        // 那时才允许它开始 HC 操作）；其它启动保持"已有实例即退出 2"的既有语义不变。
        // §4.1（FAN-926 P2）：后继实例等待旧实例释放互斥的有界预算（远小于 60 s 周期预算）。
        const int SuccessorTakeoverWaitMs = 15000;
        // D6（FAN-926R 裁决 §3）：前置停止、后继等待与接管恢复**共用同一个截止时间**。
        // 前置实例按本周期剩余预算分配后经 `--successor-budget-ms` 传入；缺省（人工/其它启动）
        // 保持旧常量语义。上限仍受旧常量约束，避免把余量全部花在等待上。
        var successorWaitMs = options.SuccessorBudgetMs is int inheritedBudget and > 0
            ? Math.Min(inheritedBudget, SuccessorTakeoverWaitMs)
            : SuccessorTakeoverWaitMs;
        // 仅沙箱：延后注入 UI-free 故障，使夹具能先通过真实 API 建立控制意图。
        const int MockUiFreeEscalationDelayMs = 8000;
        var instance = options.SuccessorTakeover
            ? HostInstanceLease.TryAcquireBounded(successorWaitMs)
            : HostInstanceLease.TryAcquire();
        if (instance is null)
        {
            Console.Error.WriteLine(options.SuccessorTakeover
                ? "YeManFanHost successor takeover: the predecessor did not free the lifetime mutex within the bounded wait."
                : "YeManFanHost is already running in this Windows session.");
            return options.SuccessorTakeover ? 4 : 2;
        }
        using var instanceScope = instance;

        if (options.MockZeroHardwareEvidence)
        {
            // Keep explicit AI sessions out of the real fan logs/recovery ledger.
            if (string.IsNullOrWhiteSpace(options.SessionTokenPath) || options.ParentPid is null)
                throw new ArgumentException("AI_MOCK_SESSION_PATH_AND_PARENT_REQUIRED");
            var tokenFile = Path.GetFullPath(options.SessionTokenPath);
            var tokenDirectory = Path.GetDirectoryName(tokenFile)!;
            var directory = new DirectoryInfo(tokenDirectory);
            if (Path.GetFileName(tokenFile) != "YeManFanHost.session" || directory.Name != "fan-host" ||
                directory.Parent is null || !Guid.TryParseExact(directory.Parent.Name, "D", out _) ||
                directory.Parent.Parent?.Name != "ai-fan-sessions")
                throw new ArgumentException("AI_MOCK_SESSION_NAMESPACE_REQUIRED");
            Environment.SetEnvironmentVariable(HostDiagnosticLog.SelfTestLogRootEnvVar, Path.Combine(tokenDirectory, "logs"));
        }
        var diagnostics = new HostDiagnosticLog();
        // 仅沙箱负例构型（默认 false）：把 P-3 目标 A 的变异开关落到判定实现上（生产路径不变）。
        RealHcBackend.MockLoopStopSkipSettleForTest = options.MockLoopStopSkipSettle;
        RealHcBackend.MockLoopStopClaimVerifiedForTest = options.MockLoopStopClaimVerified;
        diagnostics.Write("host.starting", new { options.Port, options.RealBackend, options.AllowHardwareWrites, diagnosticsPath = diagnostics.Path });
        // 920 §8.0-B：每次启动写入自带身份证据，使日志能绑定到"实际运行的那份
        // 二进制"。历史会话只关联其自身启动证据，不能被事后磁盘采样或 apphost
        // EXE 哈希补贴（EXE 相同不能证明业务 DLL 相同）。
        diagnostics.Write("host.identity", CollectHostIdentityEvidence());
        // §4.1（FAN-926 P2）：受控更换的后继实例**必须先自证**它是在旧实例真退出之后才取得
        // 写权——证据是内核对象生命周期（命名互斥可重建），不是端口/PID/超时推断。
        if (options.SuccessorTakeover)
        {
            diagnostics.Write("recovery.host-replacement-took-over", new
            {
                predecessorInstanceId = options.PredecessorInstanceId ?? "absent",
                successorInstanceId = diagnostics.HostInstanceId,
                proof = "lifetime-mutex-recreated-only-after-predecessor-handles-closed",
                // D6：实际使用的等待预算 + 它是否来自前置实例的同周期剩余预算。
                waitBudgetMs = successorWaitMs,
                waitBudgetSource = options.SuccessorBudgetMs is int b and > 0
                    ? $"inherited-from-predecessor-remaining-cycle;requested={b}"
                    : "legacy-default-no-inherited-budget",
                hcWriteAuthorityAcquiredAfterExitProof = true,
            });
        }
        // §5.1（FAN-925B）：实例启动 + 凭据加载结果（**脱敏**：只写非秘密版本标识与格式结果，
        // 不写凭据值/前缀，也不写命令行原文 —— 命令行可能含 --confirm 等令牌）。
        var credentialSource = string.IsNullOrWhiteSpace(options.SessionTokenPath) ? "argument" : "file";
        var credentialFormatOk = options.SessionToken is { Length: 64 } candidate &&
            candidate.All(Uri.IsHexDigit);
        diagnostics.Write("host.instance-started", new
        {
            options.Port,
            options.RealBackend,
            parentPid = options.ParentPid,
            parentProcess = options.ParentProcessName,
            parentStartTimeUtc = HostDiagnosticLog.ParentStartTimeUtc(options.ParentPid ?? 0),
            credentialSource,
            credentialVersionId = HostDiagnosticLog.CredentialVersionId(options.SessionToken),
            credentialLength = options.SessionToken?.Length ?? 0,
            credentialFormatOk,
            instanceIdentityIsNotCredential = true,
            credentialIsNotInstanceIdentity = true,
        });
        diagnostics.Write("auth.credential-loaded", new
        {
            credentialSource,
            credentialPathKind = options.SessionTokenPath is { Length: > 0 } path ? Path.GetFileName(path) : "none",
            readResult = credentialSource == "file" ? "file-read-ok" : "argument-supplied",
            credentialVersionId = HostDiagnosticLog.CredentialVersionId(options.SessionToken),
            credentialLength = options.SessionToken?.Length ?? 0,
            credentialFormatOk,
        });
        using var engine = new FanHostEngine(options, diagnostics);
        if (options.SelfTest)
        {
            var result = await FanHostSelfTest.RunAsync(engine);
            Console.WriteLine(JsonSerializer.Serialize(result, JsonDefaults.Options));
            return result.Ok ? 0 : 1;
        }

        using var host = new LocalFanHostServer(engine, options, diagnostics);
        // §4.1（FAN-926 P2）：受控更换时由本实例请求**有序**退出——后继实例只有在本实例
        // 真退出、生命周期互斥可重建之后才取得写权。绝不由外部强杀来"制造"这个证明。
        engine.RequestHostExit = host.Stop;
        if (options.MockUiFreeEscalation)
        {
            // 仅沙箱（必须 --mock-handshake）：注入一次"UI 永久不可用"的 route-lost episode，
            // 让 Fan 自有进程门端到端跑通"必须更换 Host 才恢复 + 继承周期预算 + 恢复原控制意图"。
            // **延后**注入：真实故障发生在用户已在控制风扇之后，夹具必须能在注入前先建立控制意图。
            FanHostEngine.ReopenBridgeWaitBudgetMsForSelfTest = 500;
            diagnostics.Write("recovery.mock-ui-free-escalation-armed", new
            {
                bridgeWaitBudgetMs = 500,
                delayMs = MockUiFreeEscalationDelayMs,
                scope = "sandbox-only; proves the automatic controlled replacement end to end",
            });
            _ = Task.Run(async () =>
            {
                await Task.Delay(MockUiFreeEscalationDelayMs).ConfigureAwait(false);
                diagnostics.Write("recovery.mock-ui-free-escalation-fired", new { delayMs = MockUiFreeEscalationDelayMs });
                engine.MarkReopenRequiredForSelfTest("mock-ui-free-escalation");
                engine.EnterFaultLockedAndScheduleRecoveryForSelfTest();
            });
        }
        if (options.SuccessorTakeover)
        {
            // §4.1（FAN-926 P2）：后继实例先开新 HC 会话，再把原控制意图恢复回来。
            engine.RunTakeoverRecovery();
        }
        Console.CancelKeyPress += (_, e) =>
        {
            e.Cancel = true;
            host.Stop();
        };
        AppDomain.CurrentDomain.ProcessExit += (_, _) => host.Stop();

        try
        {
            await host.RunAsync();
            return 0;
        }
        catch (Exception ex)
        {
            diagnostics.Write("host.fatal", new { error = ExceptionText(ex) });
            Console.Error.WriteLine($"YeManFanHost stopped: {ex.GetType().Name}: {ex.Message}");
            return 1;
        }
    }

    private static string ExceptionText(Exception ex) => string.Join(" -> ", Unwrap(ex).Select(e => e.GetType().Name + ": " + e.Message));
    private static IEnumerable<Exception> Unwrap(Exception ex)
    {
        for (Exception? current = ex; current is not null; current = current.InnerException) yield return current;
    }
}

/**
 * A named mutex is used only as a process-lifetime uniqueness handle.  It is
 * deliberately not acquired with WaitOne: async Main may resume on a
 * different thread, whereas the Windows object itself remains alive until
 * this process disposes its handle.  If a process crashes, Windows releases
 * the handle automatically and the next Host may start its recovery path.
 */
internal sealed class HostInstanceLease : IDisposable
{
    private const string Name = "Local\\YeManFanHost-v2";
    private readonly Mutex mutex;

    private HostInstanceLease(Mutex mutex) => this.mutex = mutex;

    public static HostInstanceLease? TryAcquire()
    {
        var candidate = new Mutex(initiallyOwned: false, Name, out var createdNew);
        if (!createdNew)
        {
            candidate.Dispose();
            return null;
        }
        return new HostInstanceLease(candidate);
    }

    /**
     * §4.1（FAN-926 P2）：**有界等待**获取实例互斥——仅受控更换的后继实例使用。
     * "能重建这个命名互斥" = 旧实例最后一个句柄已关闭 = **旧实例确已退出**；这是内核对象
     * 生命周期给出的证据，**不是**端口空 / PID 查不到 / 超时的推断。到期仍拿不到 ⇒ null，
     * 后继实例**不得**开始任何 HC 操作。
     */
    public static HostInstanceLease? TryAcquireBounded(int timeoutMs, int pollMs = 100)
    {
        var deadline = Environment.TickCount64 + Math.Max(0, timeoutMs);
        while (true)
        {
            var candidate = new Mutex(initiallyOwned: false, Name, out var createdNew);
            if (createdNew) return new HostInstanceLease(candidate);
            candidate.Dispose();
            if (Environment.TickCount64 >= deadline) return null;
            Thread.Sleep(Math.Max(10, pollMs));
        }
    }

    public void Dispose() => mutex.Dispose();
}

/**
 * HC SystemManager changes its published power status only on an edge. The
 * Windows callback can have more than one observer (and can deliver a late
 * duplicate), so the Host must apply the same edge rule before a transition
 * reaches the serialized worker. This class is independent of HC and performs
 * no hardware work; it only owns the notification boundary.
 */
internal enum PowerIngressTarget
{
    Ready = 0,
    Suspended = 1,
}

internal enum PowerPublishResult
{
    Queued = 0,
    Suppressed = 1,
    Rejected = 2,
    Closed = 3,
    Stale = 4,
}

/**
 * 第十八/二十轮返修（admission/commit）：不可变的 ingress 边沿身份——target /
 * generation / source / claimId 作为单一实例整体发布与读取（消除三字段分别读写的
 * 撕裂与 generation 回退）。引用替换一律经 Interlocked CAS。
 * claimId：建立本身份的那次 claim 的原子标识（随身份对象一起被 CAS 发布；
 * 失败重试可能烧号——id 为唯一标识、不承担全序；归属全序由 generation 承担）。
 */
internal sealed record PowerEdgeIdentity(PowerIngressTarget Target, long Generation, string Source, long ClaimId);

/**
 * 第十八轮返修：不可变接受记录——在 claim 成功瞬间铸造（acceptanceId + 完整
 * 边沿身份 + claim 时刻的"保护提交边界"）。随已接纳回调的接受上下文传递：
 * 即使线程在 claim 与回调之间被抢占，回调携带的仍是 claim 那一刻的边界，
 * 而不是回调开始时的现场读数。
 */
internal readonly record struct PowerEdgeAcceptance(
    long AcceptanceId,
    PowerIngressTarget Target,
    long Generation,
    string Source,
    long ProtectionBoundaryStamp);

/**
 * 第十九轮返修（admission/commit）：不可变的睡眠保护记录——token 值与发布归属
 * 一体（读取即一致快照，杜绝 token/归属撕裂）。OwnerGeneration = 铸造该保护的
 * 接受 claim 的 generation：ingress 的 Stale 检查保证 announced generation 在
 * 成功 claim 上单调 ⇒ 代次即 claim 顺序；0 = 直调发布（Mark/外部回调，无接受归属）。
 * 第二十二轮返修（P1#2）：owner=0 **不再阻断**合法的当前接受——后者以"合并"方式
 * （保留 Value、推进 OwnerGeneration）使旧授权失效；同级/更新的接受提交仍使迟到
 * 回调 no-op（代次比较），另加提交序号 CAS 作为第二层守卫。
 */
internal sealed record SuspendProtectionToken(long Value, long OwnerGeneration);

/**
 * 第二十二轮返修（P1#2，保护授权）：`SuspendProtectionToken` 的两个字段各有独立语义——
 * - `Value` = **睡眠周期编号**（每次"新发布"铸新值；值唯一，跨周期单调）；
 * - `OwnerGeneration` = **消费授权归属**（铸造/更新该保护的接受 claim 代次；0 = 直调
 *   发布，无接受归属）。
 * 恢复侧消费必须同时匹配 (Value, OwnerGeneration)；只比值会让"新睡眠沿用旧 token"
 * 的旧授权继续生效（R22 复现）。合法接受不再被 owner=0 阻断，而是**合并**：保留
 * Value（保护对象不变、DirectOwner 语义不变），只把 OwnerGeneration 推进到本次接受
 * ⇒ 此前已发出的 (值, 旧归属) 授权立即失效。合并是单次原子引用交换；提交序号 CAS
 * 是另一层守卫——两者都不构成"整体事务"（如实定性）。
 */
internal readonly record struct SuspendProtectionAuthorization(long Value, long Stamp);

/**
 * 第二十一/二十二轮返修（P1，等待者隔离）：恢复入口的"接受裁决"——本次恢复调用
 * （在单一队列 worker 上串行执行）到底产生了什么。API 等待者据此只报告**本操作**
 * 的终态，杜绝"旧 waiter 观察到后续新操作的 completed"的跨等待者结果串扰。
 * Kind 取值：
 * - "attempt"    ：本次调用创建并启动了该 attempt（AttemptId 有效）；
 * - "deferred"   ：本次调用登记为接续（并入既有运行中的 worker；ContinuationId =
 *                  登记时铸造的稳定登记身份；本调用自身没有 attempt）；
 * - "superseded" ：接受点绑定的睡眠待办已被新睡眠取代（CAS 消费失败），本次调用
 *                  没有产生任何 attempt；
 * - "noop"       ：未进入接受边界（不在 Suspended / 已停止 / 故障锁定）；
 * - "unknown"    ：动作未执行（去重 Suppressed / 关闭期跳过等）——等待者须绑定
 *                  原操作（attempt + 代次），不得退回全局状态。
 */
internal readonly record struct ResumeAdmission(
    HostState? Snapshot, long AttemptId, long ObservedAttempt, string Kind, long ContinuationId)
{
    public static ResumeAdmission Unknown => new(null, 0, 0, "unknown", 0);
}

/**
 * 第二十一/二十二轮返修（P1）：等待者绑定——"我要等的是哪一个操作"。
 * - Legacy（默认）：全局语义（引擎级调用方/既有夹具保持不变；**生产 API 不再使用**）；
 * - Pinned(attemptId)：只报告该 attempt 的终态（本请求自己创建/执行的 attempt）；
 * - Chained(observedAttempt, cycleValue, continuationId, cycleStamp)：deferred 请求——
 *   按**登记身份**（continuationId > 0 时精确匹配）或**睡眠周期身份**
 *   (Value, Stamp) 定位自己的接续，禁止用"最新 attempt 比我观察的大"或
 *   "当前 token 是否还在"推定归属；无法证明时显式过期（fail-closed）。
 *   `ObservedAttempt` 仅作诊断/兼容保留，不参与归属判定。
 */
internal readonly record struct ResumeWaitBinding(
    long AttemptId, long AcceptedEpoch, bool Chain, long ContinuationId = 0, long AcceptedStamp = -1)
{
    public static ResumeWaitBinding Legacy => new(-1, 0, false);
    public static ResumeWaitBinding Pinned(long attemptId) => new(attemptId, 0, false);
    public static ResumeWaitBinding Chained(long observedAttempt, long cycleValue, long continuationId = 0, long cycleStamp = -1) =>
        new(observedAttempt, cycleValue, true, continuationId, cycleStamp);
}

internal readonly record struct PowerEventMetadata(long Generation, string Source)
{
    public bool IsValid => Generation > 0 && !string.IsNullOrWhiteSpace(Source);
}

/**
 * HC SystemManager publishes lifecycle effects only on a state edge. This
 * ingress is intentionally lock-free: the Windows callback uses only
 * Volatile/Interlocked operations plus Channel.TryWrite, and never performs
 * diagnostics, waits, HC calls, or a monitor acquisition.
 */
internal sealed class PowerTransitionIngress
{
    // 第十八轮返修：边沿身份 = 单一不可变实例（整体 CAS 替换；读取即一致快照，
    // 不再分别读写 target/generation/source 三个 volatile 字段）。
    private PowerEdgeIdentity announced = new(PowerIngressTarget.Ready, 0, "none", 0);
    private int closing;
    private int deferredTarget = -1;
    private long deferredGeneration;
    private long acceptanceCounter;

    public bool IsClosing => Volatile.Read(ref closing) != 0;
    /**
     * 第二十轮返修：边沿身份的唯一读取接口——**整体取快照**（单次读取，
     * target/generation/source/claimId 同源一致）。任何安全归属判定必须用它。
     */
    public PowerEdgeIdentity AnnouncedEdge => Volatile.Read(ref announced);

    // 诊断兼容用途的逐字段读取：**禁止**用于组合判定——两次独立读取之间可能发生
    // 身份替换，组合出的 (generation, source) 可能对应两个不同事件。
    [Obsolete("用 AnnouncedEdge 整体快照；禁止分别读取三字段再做组合判定")]
    public PowerIngressTarget AnnouncedTarget => Volatile.Read(ref announced).Target;
    [Obsolete("用 AnnouncedEdge 整体快照；禁止分别读取三字段再做组合判定")]
    public long AnnouncedGeneration => Volatile.Read(ref announced).Generation;
    [Obsolete("用 AnnouncedEdge 整体快照；禁止分别读取三字段再做组合判定")]
    public string AnnouncedSource => Volatile.Read(ref announced).Source;
    public PowerIngressTarget? DeferredTarget
    {
        get
        {
            var value = Volatile.Read(ref deferredTarget);
            return value < 0 ? null : (PowerIngressTarget)value;
        }
    }

    /** 兼容入口（无接受记录需求的自测/压力夹具）：等价于丢弃接受记录。 */
    public PowerPublishResult TryPublish(PowerIngressTarget target, PowerEventMetadata metadata, Func<bool> writer) =>
        TryPublish(target, metadata, writer, null, out _);

    /**
     * Claim and enqueue one edge. A rejected writer restores the announced
     * state and retains a lock-free deferred target so a later same-state
     * notification can retry instead of silently losing the system state.
     *
     * 第十八轮返修：① 身份整体 CAS（一致快照；generation 只增不减——同级升级
     * 走 UpgradeIdentity 的 max 循环，claim 路径由 Stale 检查保证不回退）；
     * ② claim 成功瞬间铸造不可变接受记录（acceptanceId + 完整身份 + 保护提交
     * 边界），由 out 参数交给队列侧随"已接纳"回调传递。
     */
    public PowerPublishResult TryPublish(
        PowerIngressTarget target,
        PowerEventMetadata metadata,
        Func<bool> writer,
        Func<long>? claimBoundaryProvider,
        out PowerEdgeAcceptance? acceptance)
    {
        acceptance = null;
        if (!metadata.IsValid) return PowerPublishResult.Rejected;
        if (Volatile.Read(ref closing) != 0) return PowerPublishResult.Closed;
        while (true)
        {
            if (Volatile.Read(ref closing) != 0) return PowerPublishResult.Closed;
            var previous = Volatile.Read(ref announced);
            var deferred = Volatile.Read(ref deferredTarget);
            var deferredGenerationValue = Volatile.Read(ref deferredGeneration);
            if (previous.Generation == 0 &&
                previous.Target == PowerIngressTarget.Ready &&
                target == PowerIngressTarget.Ready)
            {
                // Ready is the initial Host state, not a transition. Record
                // the first source identity without enqueueing HC work.
                UpgradeIdentity(PowerIngressTarget.Ready, metadata.Generation, metadata.Source, requireInitialReady: true);
                return PowerPublishResult.Suppressed;
            }
            if (metadata.Generation < previous.Generation ||
                (metadata.Generation == previous.Generation &&
                 previous.Target == PowerIngressTarget.Ready && target == PowerIngressTarget.Suspended))
                return PowerPublishResult.Stale;
            if (deferred >= 0 && deferred != (int)target)
            {
                Interlocked.CompareExchange(ref deferredTarget, -1, deferred);
                Interlocked.CompareExchange(ref deferredGeneration, 0, deferredGenerationValue);
            }
            if (previous.Target == target &&
                Volatile.Read(ref deferredTarget) != (int)target)
            {
                // A native generation can arrive after the unversioned Host
                // observer already admitted the same physical edge. Upgrade
                // the identity for diagnostics (generation 只增不减), but never
                // enqueue a second SystemPending/SystemReady operation for the
                // same target.
                UpgradeIdentity(target, metadata.Generation, metadata.Source, requireInitialReady: false);
                return PowerPublishResult.Suppressed;
            }
            // 第十九/二十轮返修：保护边界读数（claim 前的保守下界）+ **claimId 与 claim
            // 原子化**——id 在构造"即将被 CAS 发布"的身份对象时就地铸入（随整体
            // CAS 一起发布），接受记录直接引用该 id（不再是 CAS 之后再补号）。
            // 第二十一轮返修（如实描述，禁止越界声明）：**接受 claim、保护边界与入队
            // 不是单一线性化事务**——此处读到的边界只是 claim 之前的**保守下界**
            // （在 claim 之前取，故其后的任何新提交都必然使下级 CAS 失败）；真正的
            // 安全性由**分层守卫**共同保证：
            //   ① 目标探针（SuspendEdgeCurrentProbe：边沿仍当前）；
            //   ② OwnerGeneration 代次归属（保护提交只允许"可证明更早"的接受更新）；
            //   ③ 边界下界 CAS（AnnounceSuspendPending 的"检查并取得提交权"）。
            // 任何文档/汇报不得把它描述成"保护边界与 ingress claim 的单一原子提交"。
            var boundaryStamp = claimBoundaryProvider?.Invoke() ?? 0;
            var claimed = new PowerEdgeIdentity(target, metadata.Generation, metadata.Source,
                Interlocked.Increment(ref acceptanceCounter));
            if (!ReferenceEquals(Interlocked.CompareExchange(ref announced, claimed, previous), previous))
                continue;
            // 第十八/十九/二十轮返修：接受记录 = claim 成功瞬间的不可变身份 + 该
            // claim 的原子 id（ClaimId 与身份同一次 CAS 发布）+ claim 代次（归属
            // 线性化证据）+ 保护边界下界。
            var claimedAcceptance = new PowerEdgeAcceptance(
                claimed.ClaimId,
                target,
                metadata.Generation,
                metadata.Source,
                boundaryStamp);
            if (Volatile.Read(ref closing) != 0)
            {
                Interlocked.CompareExchange(ref announced, previous, claimed);
                return PowerPublishResult.Closed;
            }
            bool accepted;
            try { accepted = writer(); }
            catch
            {
                Interlocked.CompareExchange(ref announced, previous, claimed);
                throw;
            }
            if (accepted)
            {
                Interlocked.CompareExchange(ref deferredTarget, -1, (int)target);
                Volatile.Write(ref deferredGeneration, 0);
                acceptance = claimedAcceptance;
                return PowerPublishResult.Queued;
            }
            Volatile.Write(ref deferredTarget, (int)target);
            Volatile.Write(ref deferredGeneration, metadata.Generation);
            Interlocked.CompareExchange(ref announced, previous, claimed);
            return PowerPublishResult.Rejected;
        }
    }

    /**
     * 身份整体升级（generation 只增不减）：CAS 循环，保证不撕裂、不回退；
     * requireInitialReady=true 时仅在"初始 Ready（generation==0）"窗口内生效。
     *
     * 第二十一轮返修（语义钉死，禁止混用）：**升级 = 同一条边沿的元数据更新，
     * 不是一次新事件、不是一次新 claim** ——因此 generation/source 可以整体刷新，
     * ClaimId 原样保留。所以"新 generation + 旧 ClaimId"是**预期语义**而非身份
     * 混乱：ClaimId 只标识"当前 announced 边沿最近一次被 claim（准入）时的原子
     * 身份"，不代表 generation 序号，也从不参与全序。边界（必须遵守）：
     * ① 只有"同一 target 的同一边沿"才允许升级（见上面的 target 守卫）；真正的新
     *   事件必须走 claim 路径（TryPublish 主循环）铸造新 ClaimId；
     * ② 禁止把 ClaimId 用于安全归属/全序判定——边沿全序由 generation 承担，
     *   保护归属由 SuspendProtectionToken.OwnerGeneration 承担；
     * ③ 初始 Ready 身份（requireInitialReady）从未被 claim ⇒ ClaimId 保持 0
     *   （"无 claim 归属"，与直调保护的 owner=0 同义）。
     */
    private void UpgradeIdentity(PowerIngressTarget target, long generation, string source, bool requireInitialReady)
    {
        while (true)
        {
            var current = Volatile.Read(ref announced);
            if (current.Target != target) return;
            if (requireInitialReady && current.Generation != 0) return;
            // 第十九轮返修：禁止 Math.Max + 新 source 拼接（会合成从未存在的
            // (generation, source) 组合）。只允许两类整体替换：
            // ① 同代次来源更新（generation == current.Generation）；
            // ② 代次严格增加（整组身份 = 本事件自己的 generation+source）。
            // 代次更低 ⇒ 整体忽略（不回退、不拼接）。
            if (generation < current.Generation) return;
            // 身份升级沿用本条边的 claimId（升级 = 同一边沿元数据更新，见方法头语义钉死）。
            var next = new PowerEdgeIdentity(target, generation, source, current.ClaimId);
            if (ReferenceEquals(Interlocked.CompareExchange(ref announced, next, current), current)) return;
        }
    }

    public void BeginClose() => Volatile.Write(ref closing, 1);
    public void ReopenAfterFailedClose() => Volatile.Write(ref closing, 0);
    public void CompleteClose() => Volatile.Write(ref closing, 1);

    public static IReadOnlyList<string> RunSelfTest()
    {
        static PowerEventMetadata Event(long generation, string source = "self-test") => new(generation, source);
        var checks = new List<string>();
        var ingress = new PowerTransitionIngress();
        var writes = 0;
        bool Publish(PowerIngressTarget target, long generation, bool accept = true) => ingress.TryPublish(target, Event(generation), () =>
        {
            Interlocked.Increment(ref writes);
            return accept;
        }) == PowerPublishResult.Queued;

        if (ingress.TryPublish(PowerIngressTarget.Ready, Event(1), () => true) != PowerPublishResult.Suppressed ||
            !Publish(PowerIngressTarget.Suspended, 2) ||
            ingress.TryPublish(PowerIngressTarget.Suspended, Event(2), () => true) != PowerPublishResult.Suppressed ||
            !Publish(PowerIngressTarget.Ready, 2) ||
            ingress.TryPublish(PowerIngressTarget.Ready, Event(2), () => true) != PowerPublishResult.Suppressed)
            throw new InvalidOperationException("forward/duplicate edge rule failed");
        if (writes != 2) throw new InvalidOperationException("forward edge count was not exactly two");
        checks.Add("forward-and-duplicate-edge-dedup");

        var reverse = new PowerTransitionIngress();
        if (reverse.TryPublish(PowerIngressTarget.Ready, Event(1), () => true) != PowerPublishResult.Suppressed ||
            reverse.TryPublish(PowerIngressTarget.Suspended, Event(2), () => true) != PowerPublishResult.Queued ||
            reverse.TryPublish(PowerIngressTarget.Ready, Event(2), () => true) != PowerPublishResult.Queued ||
            reverse.TryPublish(PowerIngressTarget.Suspended, Event(3), () => true) != PowerPublishResult.Queued)
            throw new InvalidOperationException("reverse edge sequence was not preserved");
        checks.Add("reverse-edge-preserved");

        if (reverse.TryPublish(PowerIngressTarget.Suspended, Event(2, "late-observer"), () => true) != PowerPublishResult.Stale)
            throw new InvalidOperationException("late cross-generation suspend was not rejected");
        checks.Add("late-cross-generation-edge-rejected");

        var rejected = new PowerTransitionIngress();
        if (rejected.TryPublish(PowerIngressTarget.Suspended, Event(2), () => false) != PowerPublishResult.Rejected ||
            rejected.DeferredTarget != PowerIngressTarget.Suspended ||
            rejected.TryPublish(PowerIngressTarget.Suspended, Event(2), () => true) != PowerPublishResult.Queued ||
            rejected.DeferredTarget is not null)
            throw new InvalidOperationException("failed queue publish did not retain/retry its edge");
        checks.Add("writer-failure-retain-and-retry");

        var close = new PowerTransitionIngress();
        close.BeginClose();
        if (close.TryPublish(PowerIngressTarget.Suspended, Event(2), () => true) != PowerPublishResult.Closed)
            throw new InvalidOperationException("close gate accepted a late suspend");
        close.ReopenAfterFailedClose();
        if (close.TryPublish(PowerIngressTarget.Suspended, Event(2), () => true) != PowerPublishResult.Queued)
            throw new InvalidOperationException("failed close did not reopen retry ingress");
        close.CompleteClose();
        if (close.TryPublish(PowerIngressTarget.Ready, Event(2), () => true) != PowerPublishResult.Closed)
            throw new InvalidOperationException("confirmed close accepted a late resume");
        checks.Add("close-gate-and-retry-boundary");

        var race = new PowerTransitionIngress();
        var raceWrites = 0;
        var raceTasks = Enumerable.Range(0, 64).Select(index => Task.Run(() =>
        {
            if (index == 32) { race.BeginClose(); return; }
            var target = index % 2 == 0 ? PowerIngressTarget.Suspended : PowerIngressTarget.Ready;
            var result = race.TryPublish(target, Event(index + 2), () =>
            {
                Interlocked.Increment(ref raceWrites);
                return true;
            });
            if (result == PowerPublishResult.Closed) return;
        })).ToArray();
        Task.WaitAll(raceTasks);
        if (raceWrites < 0 || !race.IsClosing)
            throw new InvalidOperationException("suspend-resume-close competition did not end at close");
        checks.Add("suspend-resume-close-competition");
        return checks;
    }
}

/**
 * Safe, hardware-free lifecycle oracle used by the R1/R4 regression matrix.
 * The order strings are copied from the frozen HC MainWindow lifecycle
 * boundaries; this class never loads HC and never stands in for a physical
 * OEM acknowledgement. Fan-only Host tests compare their observable subset
 * against this oracle and explicitly keep non-fan ManagerFactory ownership
 * isolated.
 */
internal sealed class FanLifecycleSequenceMock
{
    private readonly List<string> events = new();
    private bool resumeInProgress;
    private bool closeInProgress;
    private string publishedState = "Booting";

    public bool ManagersInitializing { get; set; }
    public bool ReadyAfterTenSecondBudget { get; set; } = true;
    public bool OpenSucceeds { get; set; } = true;
    public bool OpenEventsSucceeds { get; set; } = true;
    public bool CloseSucceeds { get; set; } = true;
    public int InitializingPolls { get; private set; }
    public bool ResumeInProgressForSelfTest => resumeInProgress;
    public IReadOnlyList<string> Events => events;

    private void Add(string value) => events.Add(value);
    private int IndexOf(string value) => events.IndexOf(value);

    public void SystemPending()
    {
        if (closeInProgress)
        {
            Add("SystemPending.ignored-close-owner");
            return;
        }
        if (publishedState == "Pending")
        {
            Add("SystemPending.duplicate-suppressed");
            return;
        }
        publishedState = "Pending";
        Add("SystemPending.ManagerFactory.Suspend");
        Add("SystemPending.VirtualManager.Sleep");
        Add("SystemPending.ControllerManager.Suspend");
        Add("SystemPending.TimerManager.Stop");
        Add("SystemPending.SensorsManager.Suspend");
        Add("SystemPending.LibreHardware.Stop");
        Add("SystemPending.CurrentDevice.Close");
    }

    public bool SystemReady()
    {
        if (closeInProgress)
        {
            Add("SystemReady.ignored-close-owner");
            return false;
        }
        if (publishedState == "Ready")
        {
            Add("SystemReady.duplicate-suppressed");
            return true;
        }
        resumeInProgress = true;
        Add("SystemReady.TimerManager.Start");
        Add("SystemReady.PerformanceManager.Resume");
        Add("SystemReady.ManagerFactory.Resume");
        Add("SystemReady.LibreHardware.Start");
        Add("SystemReady.VirtualManager.Wake");
        Add("SystemReady.ControllerManager.Resume");
        Add("SystemReady.SensorsManager.Resume");
        if (!ReadyAfterTenSecondBudget)
        {
            for (var poll = 0; poll < 40; poll++)
            {
                InitializingPolls++;
                Add("SystemReady.IsReady.Poll");
                Thread.Sleep(1);
            }
            Add("SystemReady.IsReady.Timeout");
        }
        Add("SystemReady.CurrentDevice.Open");
        if (!OpenSucceeds)
        {
            Add("SystemReady.Open.Failed");
            resumeInProgress = false;
            return false;
        }
        Add("SystemReady.CurrentDevice.OpenEvents");
        if (!OpenEventsSucceeds)
        {
            Add("SystemReady.OpenEvents.Failed");
            resumeInProgress = false;
            return false;
        }
        Add("SystemReady.Ready");
        publishedState = "Ready";
        resumeInProgress = false;
        return true;
    }

    // HC parity: SystemPending closes synchronously even while the background
    // SystemReady Open task is in flight (MainWindow has no sleep gate on the
    // background Open). The mock models the tolerated race: the Close sequence
    // runs immediately, and the in-flight SystemReady boundary may still append
    // its Open/OpenEvents afterwards, exactly as HC's background task can.
    public void SuspendDuringResume()
    {
        SystemPending();
    }

    public void BeginCloseDuringResume()
    {
        if (resumeInProgress)
        {
            closeInProgress = true;
            Add("Window_Closed.close-deferred-until-resume-boundary");
        }
    }

    public bool WindowClosed(TimeSpan hostBoundary)
    {
        closeInProgress = true;
        Add("Window_Closed.WaitInitializing");
        var started = Stopwatch.GetTimestamp();
        while (ManagersInitializing && Stopwatch.GetElapsedTime(started) < hostBoundary)
        {
            InitializingPolls++;
            Thread.Sleep(10);
        }
        if (ManagersInitializing)
        {
            Add("Window_Closed.HostBoundaryTimedOut.ManagerStillInitializing");
            closeInProgress = false;
            return false;
        }
        Add("Window_Closed.CurrentDevice.Close");
        if (!CloseSucceeds)
        {
            Add("Window_Closed.CurrentDevice.Close.Failed");
            closeInProgress = false;
            return false;
        }
        Add("Window_Closed.Events.Unbind");
        Add("Window_Closed.ManagerFactory.Managers.Stop");
        Add("Window_Closed.NonFanManagers.Stop");
        closeInProgress = false;
        return true;
    }

    public void ResumeDuringClose() => Add(closeInProgress
        ? "SystemReady.ignored-close-owner"
        : "SystemReady.resume-requested");

    public static IReadOnlyList<string> RunSelfTest()
    {
        var checks = new List<string>();

        var pending = new FanLifecycleSequenceMock();
        pending.SystemPending();
        var expectedPending = new[]
        {
            "SystemPending.ManagerFactory.Suspend",
            "SystemPending.VirtualManager.Sleep",
            "SystemPending.ControllerManager.Suspend",
            "SystemPending.TimerManager.Stop",
            "SystemPending.SensorsManager.Suspend",
            "SystemPending.LibreHardware.Stop",
            "SystemPending.CurrentDevice.Close",
        };
        if (!pending.Events.SequenceEqual(expectedPending))
            throw new InvalidOperationException("HC SystemPending order mismatch");
        checks.Add("r1-hc-system-pending-order");

        var ready = new FanLifecycleSequenceMock();
        if (!ready.SystemReady()) throw new InvalidOperationException("HC SystemReady success path failed");
        var openIndex = ready.IndexOf("SystemReady.CurrentDevice.Open");
        var openEventsIndex = ready.IndexOf("SystemReady.CurrentDevice.OpenEvents");
        if (openIndex < 0 || openEventsIndex <= openIndex ||
            ready.IndexOf("SystemReady.ManagerFactory.Resume") < 0 ||
            ready.IndexOf("SystemReady.SensorsManager.Resume") < 0)
            throw new InvalidOperationException("HC SystemReady order mismatch");
        checks.Add("r1-hc-system-ready-order");

        var closed = new FanLifecycleSequenceMock();
        if (!closed.WindowClosed(TimeSpan.FromMilliseconds(100)))
            throw new InvalidOperationException("HC Window_Closed normal path failed");
        var closeIndex = closed.IndexOf("Window_Closed.CurrentDevice.Close");
        var unbindIndex = closed.IndexOf("Window_Closed.Events.Unbind");
        var stopIndex = closed.IndexOf("Window_Closed.ManagerFactory.Managers.Stop");
        if (closeIndex < 0 || unbindIndex <= closeIndex || stopIndex <= unbindIndex)
            throw new InvalidOperationException("HC Window_Closed order mismatch");
        checks.Add("r4-hc-window-closed-order");

        var suspendResume = new FanLifecycleSequenceMock();
        suspendResume.SystemPending();
        if (!suspendResume.SystemReady()) throw new InvalidOperationException("suspend-resume mock failed");
        checks.Add("r1-suspend-resume-mock");

        var suspendWhileResume = new FanLifecycleSequenceMock();
        // The mock is intentionally held in the HC SystemReady boundary.
        suspendWhileResume.ReadyAfterTenSecondBudget = false;
        var resumeTask = Task.Run(() => suspendWhileResume.SystemReady());
        for (var attempt = 0; attempt < 100 && !suspendWhileResume.ResumeInProgressForSelfTest; attempt++)
            Thread.SpinWait(1000);
        if (!suspendWhileResume.ResumeInProgressForSelfTest)
            throw new InvalidOperationException("resume mock did not enter its serialized boundary");
        suspendWhileResume.SuspendDuringResume();
        _ = resumeTask.GetAwaiter().GetResult();
        // HC parity: SystemPending Close is synchronous even while the resume
        // boundary is in flight; no deferral event may exist. The stale resume
        // boundary may still append its Open/OpenEvents after the Close — the
        // exact race HC tolerates (no sleep gate on the background Open).
        if (!suspendWhileResume.Events.Contains("SystemPending.CurrentDevice.Close") ||
            suspendWhileResume.Events.Contains("SystemPending.deferred-until-resume-boundary"))
            throw new InvalidOperationException("suspend-during-resume did not close synchronously (HC parity)");
        checks.Add("r1-resume-during-suspend-mock");

        var closeDuringResume = new FanLifecycleSequenceMock();
        closeDuringResume.ReadyAfterTenSecondBudget = false;
        var closeResumeTask = Task.Run(() => closeDuringResume.SystemReady());
        for (var attempt = 0; attempt < 100 && !closeDuringResume.ResumeInProgressForSelfTest; attempt++)
            Thread.SpinWait(1000);
        if (!closeDuringResume.ResumeInProgressForSelfTest)
            throw new InvalidOperationException("close/resume mock did not enter its serialized boundary");
        closeDuringResume.BeginCloseDuringResume();
        closeDuringResume.ResumeDuringClose();
        // The resume boundary is still the only owner; no second Open is
        // manufactured by the observer. The close mock then owns Window_Closed.
        _ = closeResumeTask.GetAwaiter().GetResult();
        if (!closeDuringResume.WindowClosed(TimeSpan.FromMilliseconds(100)))
            throw new InvalidOperationException("close-during-resume did not reach Window_Closed owner");
        if (!closeDuringResume.Events.Contains("SystemReady.CurrentDevice.Open") ||
            closeDuringResume.Events.Count(value => value == "SystemReady.CurrentDevice.Open") != 1)
            throw new InvalidOperationException("close-during-resume created a duplicate Open");
        checks.Add("r4-close-during-resume-mock");

        var readyTimeout = new FanLifecycleSequenceMock { ReadyAfterTenSecondBudget = false };
        if (!readyTimeout.SystemReady() ||
            !readyTimeout.Events.Contains("SystemReady.IsReady.Timeout") ||
            !readyTimeout.Events.Contains("SystemReady.CurrentDevice.Open"))
            throw new InvalidOperationException("HC IsReady timeout did not continue to Open");
        checks.Add("r1-isready-10s-timeout-open");

        var openFailure = new FanLifecycleSequenceMock { OpenSucceeds = false };
        if (openFailure.SystemReady() ||
            !openFailure.Events.Contains("SystemReady.Open.Failed") ||
            openFailure.Events.Contains("SystemReady.CurrentDevice.OpenEvents"))
            throw new InvalidOperationException("Open failure incorrectly entered OpenEvents");
        checks.Add("r1-open-failure-no-openevents");

        var eventsFailure = new FanLifecycleSequenceMock { OpenEventsSucceeds = false };
        if (eventsFailure.SystemReady() ||
            !eventsFailure.Events.Contains("SystemReady.OpenEvents.Failed") ||
            eventsFailure.Events.Contains("SystemReady.Ready"))
            throw new InvalidOperationException("OpenEvents failure incorrectly reached Ready");
        checks.Add("r1-openevents-failure-no-ready");

        var initializing = new FanLifecycleSequenceMock { ManagersInitializing = true };
        if (initializing.WindowClosed(TimeSpan.FromMilliseconds(80)) ||
            !initializing.Events.Contains("Window_Closed.HostBoundaryTimedOut.ManagerStillInitializing") ||
            initializing.InitializingPolls < 2 || initializing.InitializingPolls > 20)
            throw new InvalidOperationException("permanent Initializing boundary was not bounded");
        checks.Add("r4-manager-initializing-boundary");
        checks.Add("r4-exit-boundary-no-busy-loop");

        var closeFailed = new FanLifecycleSequenceMock { CloseSucceeds = false };
        if (closeFailed.WindowClosed(TimeSpan.FromMilliseconds(100)) ||
            !closeFailed.Events.Contains("Window_Closed.CurrentDevice.Close.Failed"))
            throw new InvalidOperationException("close failure path was not retained");
        closeFailed.CloseSucceeds = true;
        if (!closeFailed.WindowClosed(TimeSpan.FromMilliseconds(100)))
            throw new InvalidOperationException("close failure recovery entry was not retryable");
        checks.Add("r4-close-failure-reopen-entry");

        var duplicate = new FanLifecycleSequenceMock();
        duplicate.SystemPending();
        duplicate.SystemPending();
        duplicate.SystemReady();
        duplicate.SystemReady();
        if (duplicate.Events.Count(value => value == "SystemPending.CurrentDevice.Close") != 1 ||
            duplicate.Events.Count(value => value == "SystemReady.CurrentDevice.Open") != 1 ||
            !duplicate.Events.Contains("SystemPending.duplicate-suppressed") ||
            !duplicate.Events.Contains("SystemReady.duplicate-suppressed"))
            throw new InvalidOperationException("mock duplicate event edge count mismatch");
        checks.Add("r4-duplicate-power-events");

        return checks;
    }
}

internal sealed record HostOptions(
    int Port,
    int? ParentPid,
    string? ParentProcessName,
    bool SelfTest,
    bool AllowHardwareWrites,
    string? HcAssemblyPath,
    string? HcRuntimeRoot,
    string? ConfigPath,
    bool ShowHelp,
    bool RealBackend,
    // 2026-09-23：测试专用开关（--mock-handshake，仅 AI 代码/模拟器使用）
    bool MockHandshake,
    /**
     * 2026-09-23（FAN-204 s31 补充裁决 C）：**仅沙箱**的慢重建注入——把真机观测到的
     * HC 重建耗时（≈10.2 s）注入 mock 后台重建，使 AC15 能覆盖"宿主忙"过渡窗。
     * 只在 `--mock-handshake` 同时存在时生效（用户路径永不触达；无 mock 时恒 0）。
     */
    int MockResumeRebuildDelayMs,
    /**
     * 2026-09-23（FAN-204 Q1-b）：**仅沙箱**的"引擎锁被 HC 打开占用"注入——把真实 HC
     * `Open()` 的就绪等待（真机实测 **10.22 s**，且发生在引擎唯一 `gate` 之内）如实复现，
     * 使 api_contract 能在沙箱里判定"过渡期每次探针/接受响应/诊断行是否仍可判定"。
     * 只在 `--mock-handshake` 同时存在时生效（用户路径永不触达；无 mock 时恒 0）。
     */
    int MockHcOpenHoldMs,
    /**
     * 2026-09-23（FAN-204 Q1-b 裁决）：**仅沙箱的负例开关**——禁用"已发布快照"，让读路径
     * 退回阻塞读（修复前的旧行为）。AC15c 负例必须因此失败，用以证明该判定不空转。
     * 只在 `--mock-handshake` 同时存在时生效（用户路径永不触达）。
     */
    bool MockNoPublishedSnapshot,
    /**
     * 2026-09-24（FAN-204 Q1-c / HB-RESUME-BLOCKED 裁决）：**仅沙箱的负例开关**——把
     * `/api/heartbeat` 重新接回 gate（修复前的旧行为：排队等 HC 长操作持锁 ≈10 s 才 409）。
     * AC15d 的"取锁前快速判定"断言必须因此失败，用以证明该判定不空转。
     * 只在 `--mock-handshake` 同时存在时生效（用户路径永不触达）。
     */
    bool MockHeartbeatLegacyGate,
    /**
     * 2026-09-24（FAN-204 Q1-c 裁决）：**仅沙箱的负例开关**——在快速拒绝路径上**错误延长
     * 旧 lease**（真实地把 `state.Lease` 续期 15 s 并重排 leaseTimer）。AC15d 的
     * "leaseRenewed=false / leaseExtensionMs=0"断言必须因此失败。
     * 只在 `--mock-handshake` 同时存在时生效（用户路径永不触达）。
     */
    bool MockHeartbeatRenewLease,
    /**
     * 2026-09-24（FAN-204 §31 R4 阶段 2）：**仅沙箱的负例开关**——把用户控制端点
     * （open / open-events / acquire-control / enable）的过渡期快速拒绝退回"直接进 gate"的旧行为
     * （修复前：排队等 HC 长操作持锁 ≈10 s）。AC16 的"取锁前快速判定"断言必须因此失败，
     * 用以证明统一判定不空转。只在 `--mock-handshake` 同时存在时生效（用户路径永不触达）。
     */
    bool MockUserControlLegacyGate,
    /**
     * 2026-09-24（FAN-204 §31 R4 阶段 2）：**仅沙箱负例构型开关**（默认 false；用户路径永不设置）——
     * 让 P-3 目标 A 的三段判定分别在 settle / 复核处变异，使 RunHcLoopTargetASelfTest **必失败**。
     */
    bool MockLoopStopSkipSettle,
    bool MockLoopStopClaimVerified,
    string? AuthorizationPath,
    string? Confirmation,
    string? SessionToken,
    string? SessionTokenPath,
    // 920-v1.6 §18.2：隔离候选无硬件联调专用（不影响冻结默认值）。
    string? HcCandidateAssembly,
    string? HcExpectedSha256,
    string? HcDeviceType,
    /**
     * §18.2-C：自动 restore/close 必经路径上的**可选** ASUS 默认表读回。
     * 默认**不发起**（同步链无内建时限，可选观察不得占住主收尾链）；
     * `--asus-readback` 显式开启，供诊断/联调。
     */
    bool AsusReadbackEnabled,
    /**
     * §4.1（FAN-926 P2）：**受控更换的后继实例**。为 true 时启动不因"已有实例"直接退出，
     * 而是**有界等待**进程生命周期互斥；"重建互斥成功"本身就是**旧实例句柄已关闭**的证明
     * （不是端口空 / PID 查不到 / 超时的推断），拿到之后才允许开始 HC 操作。
     */
    bool SuccessorTakeover = false,
    /** 仅证据用：被替换的前一实例 id（非秘密，不是凭据）。 */
    string? PredecessorInstanceId = null,
    /**
     * D6（FAN-926R 裁决 §3）：前置实例按**同一恢复周期**剩余预算分配后经
     * `--successor-budget-ms` 传入的接管等待预算。缺省（人工/其它启动）保持旧常量语义。
     */
    int? SuccessorBudgetMs = null,
    /**
     * §4.1（FAN-926 P2）：**仅沙箱**（必须同时 `--mock-handshake`）——启动即注入一次
     * "UI 永久不可用的 route-lost"故障 episode，使 Fan 自有进程门能端到端跑通
     * "必须更换 Host 才恢复"。用户路径永不传本开关。
     */
    bool MockUiFreeEscalation = false,
    /**
     * FAN-936 §1：微星专项**只读**开机取证采样（`--msi-readonly-sample`）。
     * 加载 HC 设备后调用 HC 侧 `ReadMsiFanStateReadOnly()`——该路径**绝不调用会改变状态的
     * HC Open()**，零硬件写入；输出风扇表 1/2、`Get_Data(152)`、`Get_AP(1)`、`Get_AP(0)`、
     * 机型/固件/Host 实例/启动身份的结构化 JSON，供 A/B 冷启动取证卡使用。用户路径永不传本开关。
     */
    bool MsiReadOnlySample = false,
    /**
     * HC-SLIM-01 R3 §6.2②：风扇写入 provider 的**内部**选路（不新增用户 UI）。
     * null/空 = 发布默认 "hc"（现有 HC 回调路径，行为与既有发布完全一致）；
     * "hc" / "backend" 显式固定本次会话的 provider。非法值由 RealHcBackend 构造函数
     * fail-closed 拒绝（不静默回退到第二 writer）。首次硬件动作前冻结并记录 provider/组件版本。
     */
    string? FanProvider = null)
{
    public bool MockZeroHardwareEvidence { get; init; }

    public static HostOptions Parse(string[] args)
    {
        var port = 8765;
        int? parentPid = null;
        string? parentName = null;
        string? hcPath = null;
        string? hcRuntimeRoot = null;
        string? configPath = null;
        var selfTest = false;
        var allowWrites = false;
        var help = false;
        var realBackend = false;
        // 2026-09-23 operator 裁决：测试模式（mock 伪装握手）只允许 AI 代码调用；
        // 用户路径（App 的 fanHost.ts）永远不传本开关 ⇒ 永远不可到达 mock。
        var mockHandshake = false;
        var mockZeroHardwareEvidence = false;
        var mockResumeRebuildDelayMs = 0;
        var mockHcOpenHoldMs = 0;
        var mockNoPublishedSnapshot = false;
        var mockHeartbeatLegacyGate = false;
        var mockHeartbeatRenewLease = false;
        var mockUserControlLegacyGate = false;
        var mockLoopStopSkipSettle = false;
        var mockLoopStopClaimVerified = false;
        // §4.1（FAN-926 P2）：受控更换的后继实例身份。
        var successorTakeover = false;
        string? predecessorInstanceId = null;
        // D6（FAN-926R 裁决 §3）：前置实例按**同一恢复周期**的剩余预算分配后传入的接管等待预算。
        int? successorBudgetMs = null;
        var mockUiFreeEscalation = false;
        string? authorizationPath = null;
        string? confirmation = null;
        string? sessionToken = null;
        string? sessionTokenPath = null;
        string? hcCandidateAssembly = null;
        string? hcExpectedSha256 = null;
        string? hcDeviceType = null;
        var asusReadback = false;
        // FAN-936 §1：只读微星开机取证采样（不调 Open、零写入）。
        var msiReadOnlySample = false;
        // HC-SLIM-01 R3 §6.2②：风扇写入 provider 内部选路（缺省 null ⇒ 发布默认 hc）。
        string? fanProvider = null;

        for (var i = 0; i < args.Length; i++)
        {
            switch (args[i].ToLowerInvariant())
            {
                case "--port":
                    port = int.Parse(Next(args, ref i));
                    break;
                case "--parent-pid":
                    parentPid = int.Parse(Next(args, ref i));
                    break;
                case "--parent-process":
                    parentName = Next(args, ref i);
                    break;
                case "--hc-assembly":
                    hcPath = Next(args, ref i);
                    break;
                case "--hc-runtime-root":
                    hcRuntimeRoot = Next(args, ref i);
                    break;
                case "--hc-candidate-assembly":
                    // §18 隔离候选（无硬件联调）：只用于自测组，不改变生产加载路径。
                    hcCandidateAssembly = Next(args, ref i);
                    break;
                case "--hc-expected-sha256":
                    hcExpectedSha256 = Next(args, ref i);
                    break;
                case "--hc-device-type":
                    // §18 诊断：无 ROG 硬件的开发机上按类型名构造候选设备实例。
                    hcDeviceType = Next(args, ref i);
                    break;
                case "--asus-readback":
                    // §18.2-C：显式开启可选的 ASUS 默认表读回（默认不发起）。
                    asusReadback = true;
                    break;
                case "--msi-readonly-sample":
                    // FAN-936 §1：微星只读开机取证采样——不取互斥、不调 Open、零硬件写入。
                    msiReadOnlySample = true;
                    break;
                case "--config":
                    configPath = Next(args, ref i);
                    break;
                case "--protocol-version":
                    var protocolVersion = int.Parse(Next(args, ref i));
                    if (protocolVersion != 2) throw new ArgumentException("Only Fan API protocol version 2 is supported");
                    break;
                case "--self-test":
                    selfTest = true;
                    break;
                case "--allow-hardware-writes":
                    // This switch is intentionally insufficient on its own. A
                    // separately reviewed authorization file is also required.
                    allowWrites = true;
                    break;
                case "--real-backend":
                    realBackend = true;
                    break;
                case "--mock-zero-hardware-evidence":
                    mockZeroHardwareEvidence = true;
                    break;
                case "--mock-handshake":
                    // 测试专用（AI 代码/模拟器）；App 的用户路径不传本开关。
                    mockHandshake = true;
                    break;
                case "--successor-takeover":
                    // §4.1（FAN-926 P2）：本进程是受控更换的**后继实例**——有界等待生命周期
                    // 互斥（拿到即证明旧实例已退出），而不是"已有实例就退出 2"。
                    successorTakeover = true;
                    break;
                case "--predecessor-instance":
                    predecessorInstanceId = Next(args, ref i);
                    break;
                case "--successor-budget-ms":
                    // D6：接管等待上限来自**同一剩余周期预算**，不再用固定 15 s 覆盖前置合法停止期。
                    if (int.TryParse(Next(args, ref i), out var parsedSuccessorBudget) && parsedSuccessorBudget > 0)
                        successorBudgetMs = parsedSuccessorBudget;
                    break;
                case "--mock-ui-free-escalation":
                    // 仅沙箱：启动即注入一次 UI 永久不可用的 route-lost episode（见 Main，仅 mock 下生效）。
                    mockUiFreeEscalation = true;
                    break;
                case "--mock-resume-rebuild-delay-ms":
                    // 仅沙箱：慢重建注入（只在 --mock-handshake 同时存在时生效，见 CompleteAutomaticResume）。
                    mockResumeRebuildDelayMs = (int)Math.Clamp(long.Parse(Next(args, ref i)), 0, 30000);
                    break;
                case "--mock-hc-open-hold-ms":
                    // 仅沙箱：把真实 HC `Open()` 的就绪等待（真机 10.22 s，在引擎 gate 内）如实注入
                    // （只在 --mock-handshake 同时存在时生效，见 FanHostEngine.Open）。
                    mockHcOpenHoldMs = (int)Math.Clamp(long.Parse(Next(args, ref i)), 0, 30000);
                    break;
                case "--mock-no-published-snapshot":
                    // 仅沙箱负例：禁用已发布快照（读路径退回阻塞读），证明 AC15c 判定非空转。
                    mockNoPublishedSnapshot = true;
                    break;
                case "--mock-heartbeat-legacy-gate":
                    // 仅沙箱负例（Q1-c）：heartbeat 退回"直接进 gate"的旧行为，证明 AC15d 判定非空转。
                    mockHeartbeatLegacyGate = true;
                    break;
                case "--mock-heartbeat-renew-lease":
                    // 仅沙箱负例（Q1-c）：快速拒绝路径上错误延长旧 lease，证明 AC15d 的"不续租"断言非空转。
                    mockHeartbeatRenewLease = true;
                    break;
                case "--mock-user-control-legacy-gate":
                    // 仅沙箱负例（R4 阶段 2）：用户控制端点退回"直接进 gate"的旧行为，证明 AC16 判定非空转。
                    mockUserControlLegacyGate = true;
                    break;
                case "--mock-loopstop-skip-settle":
                    // 仅沙箱负例（R4 阶段 2）：settle 恒判"已 settle"，P-3 目标 A 自测必须失败。
                    mockLoopStopSkipSettle = true;
                    break;
                case "--mock-loopstop-claim-verified":
                    // 仅沙箱负例（R4 阶段 2）：复核恒报"已结束"，P-3 目标 A 自测必须失败。
                    mockLoopStopClaimVerified = true;
                    break;
                case "--authorization":
                    authorizationPath = Next(args, ref i);
                    break;
                case "--confirm":
                    confirmation = Next(args, ref i);
                    break;
                case "--session-token":
                    sessionToken = Next(args, ref i);
                    break;
                case "--session-token-file":
                    sessionTokenPath = Next(args, ref i);
                    break;
                case "--fan-provider":
                    // HC-SLIM-01 R3 §6.2②：内部 provider 选路（不新增用户 UI）。
                    // 只接受 hc/backend；非法值由 RealHcBackend 构造函数 fail-closed 拒绝。
                    fanProvider = Next(args, ref i);
                    break;
                case "--help":
                case "-h":
                    help = true;
                    break;
                default:
                    throw new ArgumentException($"Unknown argument: {args[i]}");
            }
        }

        if (mockZeroHardwareEvidence && (!mockHandshake || realBackend || allowWrites))
            throw new ArgumentException("MOCK_ZERO_HARDWARE_REQUIRES_MOCK_ONLY");
        if (port is < 1024 or > 65535) throw new ArgumentOutOfRangeException(nameof(port));
        if (string.IsNullOrWhiteSpace(sessionToken) && !string.IsNullOrWhiteSpace(sessionTokenPath))
        {
            if (!File.Exists(sessionTokenPath))
                throw new FileNotFoundException("Fan Host 会话令牌文件不存在", sessionTokenPath);
            sessionToken = File.ReadAllText(sessionTokenPath, Encoding.UTF8).Trim();
            if (sessionToken.Length == 0) throw new ArgumentException("Fan Host 会话令牌文件为空", nameof(sessionTokenPath));
        }
        sessionToken ??= Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();
        return new HostOptions(port, parentPid, parentName, selfTest, allowWrites, hcPath, hcRuntimeRoot, configPath, help, realBackend, mockHandshake, mockHandshake ? mockResumeRebuildDelayMs : 0, mockHandshake ? mockHcOpenHoldMs : 0, mockHandshake && mockNoPublishedSnapshot, mockHandshake && mockHeartbeatLegacyGate, mockHandshake && mockHeartbeatRenewLease, mockHandshake && mockUserControlLegacyGate, mockLoopStopSkipSettle, mockLoopStopClaimVerified, authorizationPath, confirmation, sessionToken, sessionTokenPath, hcCandidateAssembly, hcExpectedSha256, hcDeviceType, asusReadback, successorTakeover, predecessorInstanceId, successorBudgetMs, mockHandshake && mockUiFreeEscalation, msiReadOnlySample, fanProvider) { MockZeroHardwareEvidence = mockZeroHardwareEvidence };
    }

    private static string Next(string[] args, ref int index)
    {
        if (++index >= args.Length) throw new ArgumentException($"Missing value for {args[index - 1]}");
        return args[index];
    }

    public static void PrintHelp()
    {
        Console.WriteLine("YeManFanHost - resident local Fan API host");
        Console.WriteLine("Default mode is safe/no-hardware: HC is not loaded and writes are disabled.");
        Console.WriteLine("  --port <n>                 Local loopback port (default 8765)");
        Console.WriteLine("  --parent-pid <pid>         Stop when the parent exits");
        Console.WriteLine("  --parent-process <name>    Stop when the named parent exits");
        Console.WriteLine("  --hc-assembly <path>       Staged HC assembly path (not loaded by default)");
        Console.WriteLine("  --hc-runtime-root <path>   Shared HC runtime directory");
        Console.WriteLine("  --hc-candidate-assembly <path>  §18 isolated candidate HC DLL for hardware-free self-test");
        Console.WriteLine("  --hc-expected-sha256 <hash>     Diagnostic override for a candidate HC DLL (default: frozen payload hash)");
        Console.WriteLine("  --hc-device-type <typeName>     Diagnostic: instantiate this HC device type instead of IDevice.GetCurrent");
        Console.WriteLine("  --asus-readback                 Opt in to the optional ASUS default-table readback (not attempted by default)");
        Console.WriteLine("  --msi-readonly-sample      FAN-936 read-only MSI boot evidence sample: loads HC but never calls Open(), performs zero hardware writes, prints fan tables 1/2, Get_Data(152), Get_AP(1), Get_AP(0), model/firmware/host-instance/boot-identity as JSON, then exits");
        Console.WriteLine("  --config <path>            Host configuration file");
        Console.WriteLine("  --self-test                Run side-effect-free host self-test");
        Console.WriteLine("  --real-backend             Load staged HC and perform factory-only handshake");
        Console.WriteLine("  --mock-zero-hardware-evidence TEST-ONLY: requires mock-handshake without real backend/write authorization; exports physical writes=false and separate simulated control evidence");
        Console.WriteLine("  --mock-handshake           TEST-ONLY (AI tooling/simulator): fake HC fan readiness, realBackend forced null, zero hardware writes; never used by the product app");
        Console.WriteLine("  --mock-resume-rebuild-delay-ms <n>  TEST-ONLY (sandbox): inject an n-ms slow automatic-resume rebuild (needs --mock-handshake; real machine measured ~10200) so AC15 covers the busy transition window");
        Console.WriteLine("  --mock-hc-open-hold-ms <n>  TEST-ONLY (sandbox): hold the engine gate for n ms inside Open() to reproduce the real HC device-open readiness wait (needs --mock-handshake; real machine measured ~10220 held inside the lock) so AC15c can decide probe/accept decidability");
        Console.WriteLine("  --mock-no-published-snapshot  TEST-ONLY negative control (needs --mock-handshake): disable the published read snapshot so read paths fall back to the blocking gate (AC15c negative control must then fail)");
        Console.WriteLine("  --mock-heartbeat-legacy-gate  TEST-ONLY negative control (needs --mock-handshake): route /api/heartbeat straight into the engine gate again (pre-Q1-c behaviour) so AC15d's lock-free fast-reject assertions must fail");
        Console.WriteLine("  --mock-heartbeat-renew-lease  TEST-ONLY negative control (needs --mock-handshake): wrongly extend the old lease inside the heartbeat fast-reject path so AC15d's leaseRenewed=false assertion must fail");
        Console.WriteLine("  --mock-user-control-legacy-gate  TEST-ONLY negative control (needs --mock-handshake): route /api/open, /api/open-events, /api/acquire-control and /api/enable straight into the engine gate again (pre-R4 behaviour) so AC16's lock-free fast-reject assertions must fail");
        Console.WriteLine("  --mock-loopstop-skip-settle  TEST-ONLY negative control (self-test mutated variant): make the P-3 settle probe always report settled so RunHcLoopTargetASelfTest must fail");
        Console.WriteLine("  --mock-loopstop-claim-verified  TEST-ONLY negative control (self-test mutated variant): make the P-3 verify probe always report ended so RunHcLoopTargetASelfTest must fail");
        Console.WriteLine("  --authorization <path>     Explicit hardware authorization record");
        Console.WriteLine("  --confirm <token>          Explicit operator confirmation for real writes");
        Console.WriteLine("  --session-token <token>    Per-process loopback API session token");
        Console.WriteLine("  --session-token-file <p>   Read loopback API token from a protected sidecar file");
        Console.WriteLine("  --fan-provider <hc|backend>  INTERNAL (no user UI): fix the fan-write provider for this session; null/empty keeps the shipped default 'hc'");
    }
}

internal static class JsonDefaults
{
    public static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web)
    {
        WriteIndented = false,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        NumberHandling = JsonNumberHandling.Strict,
    };
}

/**
 * Host-owned, append-only diagnostic trail.  It contains state transitions and
 * sanitized API outcomes, never API session/lease secrets.  Logging failures
 * are deliberately non-fatal: they must not interfere with OEM recovery.
 */
internal sealed class HostDiagnosticLog
{
    public const int SchemaVersion = 2;
    public const int DiagnosticSchemaVersion = 1;
    private readonly object gate = new();
    private readonly string path;
    private readonly string faultPath;
    private readonly string enabledFlagPath;
    private readonly string hostInstanceId = Guid.NewGuid().ToString("N");

    /**
     * §5.1（FAN-925B）：本进程的**非秘密实例标识**（与每条日志记录同一身份）。
     * 它用于"这次请求/这次交接由哪个实例处理"，**不是**认证凭据、不能独立授权操作。
     */
    internal string HostInstanceId => hostInstanceId;

    private readonly int runtimeMaxBytes;
    private readonly Dictionary<string, (long TickMs, string State)> pollingSuccessLastWrite = new(StringComparer.Ordinal);
    private long runtimeBytes = -1;
    private bool rotationWarningEmitted;
    private Func<object?>? contextProvider;

    /**
     * 裁决 H5（2026-09-19）：**免门**白名单故障事件。日志门是逐次读 flag，门开启前的
     * 故障整段没有证据（N17）；这三类"卡死态"事件是唯一的现场，必须无条件落盘。
     * 白名单刻意极小且全是终态/低频事件（每进程至多几次）⇒ 不构成高频日志，
     * 也不恢复全量高频写入。
     */
    private static readonly HashSet<string> GateFreeFaultEvents = new(StringComparer.Ordinal)
    {
        "power.fault-locked",
        "power.awaiting-close-cleanup",
        "recovery.retry-terminal",
        // D1/D3（FAN-926R 裁决 §3·V5）：睡眠边界的**责任判定**必须常开——"是否发起默认模式
        // 恢复"与三轴分列是责任链本身，详细日志被关掉时不能整段失踪（每次睡眠一条，低频）。
        "power.suspend-preclose-release-decision",
        "restore.release-unproven-no-live-session",
        "restore.not-applicable-no-write-history",
        // §5.1（FAN-925B）：**最小责任事件必须常开**。详细日志被显式关闭时，责任链
        // （实例启动 / 凭据加载 / 认证拒绝 / 交接接受 / 恢复终态）也必须留下证据，
        // 否则关闭详细日志会让整条交接与认证链在事后完全失踪。
        // 这些事件都是低频（每次进程生命周期几条），不构成日志开销。
        "host.instance-started",
        "auth.credential-loaded",
        "auth.rejected",
        "parent-exit-handoff.accepted",
        // §3/§5.1（FAN-926 P1）：CP-07 的**真实受理链**必须常开——受理建立/未绑定、
        // 关联既有 Close owner、已完成幂等、重复请求同责任、worker 执行与结算/失败。
        // 全部是每进程几次的低频事件；不带凭据、不带高频采样。
        "parent-exit-handoff.bound",
        "parent-exit-handoff.unbound",
        "parent-exit-handoff.existing-close-observed",
        "parent-exit-handoff.already-settled",
        "parent-exit-handoff.duplicate-observed",
        "parent-exit-handoff.recovery-begin",
        "parent-exit-handoff.recovery-confirmed",
        "parent-exit-handoff.recovery-deferred",
        // §4.2（FAN-926 P2）：同一未结算 episode 的预算耗尽 ⇒ 失败终态（不得静默新开周期）。
        "recovery.cycle-exhausted-without-settlement",
        // §4.1（FAN-926 P2）：UI 不可用时的同进程恢复尝试——每故障周期恰好一次，
        // "有没有真试过"与"收据是否被接受"必须在默认门关闭时可事后核对。
        "recovery.ui-free-same-process-begin",
        "recovery.ui-free-same-process-receipt",
        "recovery.ui-free-same-process-confirmed",
        "recovery.ui-free-same-process-fault",
        // §4.1（FAN-926 P2）：受控更换的两端证据必须常开——**恰好一次**的拉起请求，
        // 以及后继实例"在旧实例真退出之后才取得写权"的那一条自证。
        "recovery.host-replacement-spawned",
        "recovery.host-replacement-took-over",
        "recovery.host-replacement-unavailable",
        "recovery.host-replacement-fault",
        "recovery.host-replacement-predecessor-exit",
        "recovery.host-replacement-predecessor-exit-unavailable",
        "recovery.cycle-handoff-unsettled",
        "recovery.mock-ui-free-escalation-armed",
        "recovery.mock-ui-free-escalation-fired",
        // §4.1（FAN-926 P2）：后继实例"有没有把原控制意图恢复回来"必须常开可核对。
        "recovery.control-intent-restored",
        "recovery.control-intent-unusable",
        "recovery.control-intent-read-failed",
        "recovery.takeover-open-failed",
        "recovery.takeover-recovery-finished",
        // R1（FAN-926R 唤醒租约裁决 §3.2.9）：恢复 worker 的**临时租约**创建/撤销/保留，
        // 以及"宿主持有已恢复意图"这一控制责任类型，必须常开——详细日志关闭时也要能事后
        // 核对"唤醒后是谁在持有控制、有没有被自己撤销"。每次唤醒至多两条，低频、不含 token。
        "power.resume-placeholder-lease-created",
        "power.resume-placeholder-lease-revoked",
        "power.resume-placeholder-lease-kept",
    };

    /**
     * §5.1（FAN-925B）：凭据的**非秘密版本标识** = SHA-256 前 8 位十六进制。
     * 只用于"这次请求用的是哪一版凭据"，**绝不**输出凭据值、前缀或任何密钥材料。
     * 亦**不得**把它当作认证凭据或实例身份（实例身份单独记录）。
     */
    internal static string CredentialVersionId(string? credential)
    {
        if (string.IsNullOrEmpty(credential)) return "absent";
        var hash = System.Security.Cryptography.SHA256.HashData(
            System.Text.Encoding.UTF8.GetBytes(credential));
        return Convert.ToHexString(hash).ToLowerInvariant()[..8];
    }

    /**
     * §5.1：父实例的创建时间（辅助判代；**不**声称能单独查明拉起因果）。
     * 读不到返回 "unknown"，绝不影响启动。
     */
    internal static string ParentStartTimeUtc(int parentPid)
    {
        if (parentPid <= 0) return "unknown";
        try
        {
            using var parent = System.Diagnostics.Process.GetProcessById(parentPid);
            return parent.StartTime.ToUniversalTime().ToString("O");
        }
        catch
        {
            return "unknown";
        }
    }

    /**
     * 裁决 P-4（2026-09-23）：runtime 详细日志（默认门关闭，仅 operator 开启时写
     * yeman-fan-host-runtime.log）独立轮转。active 上限 2 MiB；超限时在同一写锁内
     * 原子改名为 yeman-fan-host-runtime.<n>.log（n 递增），至少保留 RuntimeArchiveKeep
     * 个归档，最旧的先删。轮转/写盘失败一律吞掉，绝不影响 FanHost/HC 安全路径。
     */
    internal const int DefaultRuntimeMaxBytes = 2 * 1024 * 1024;
    private const int RuntimeArchiveKeep = 3;
    /** P-4 C（2026-09-24）：归档保留数对自测可见（判据用，不改变行为）。 */
    internal const int RuntimeArchiveKeepForSelfTest = RuntimeArchiveKeep;

    /**
     * 裁决 P-4：高频幂等成功轮询降采样。只有下面白名单 endpoint 的**成功**轮询
     * （/api/state、/health、heartbeat）按 endpoint+status+state 做键采样：首次记录、
     * 状态变化记录，同键其余成功至少 PollingSuccessMinIntervalMs 才记录一次。
     * 其余一切事件——enable/restore/resume/close/identity、生命周期、失败/超时、
     * 免门白名单故障——绝不进入采样路径（降采样只作用于 runtime 详细日志）。
     */
    internal const int PollingSuccessMinIntervalMs = 30_000;
    private static readonly HashSet<string> PollingSuccessEndpoints = new(StringComparer.Ordinal)
    {
        "/api/state",
        "/health",
        "/api/heartbeat",
    };

    /**
     * 自测负例开关（裁决 P-4 第 ⑥ 项）：生产恒为 true，无任何生产路径写它。
     * 负例在 **scratch 副本** 里把本行改成 false（等价"降采样守卫 if(false)"），
     * 使降采样失效，从而让 RunRuntimeLogRotationSelfTest 的降采样断言失败。
     */
    internal static bool PollingSuccessDownsampleEnabled { get; set; } = true;

    /**
     * 自测负例开关（裁决 P-4 C 第 3 项）：生产恒为 true，无任何生产路径写它。
     * 负例在 **scratch 副本** 里把本行改成 false（等价"归档淘汰守卫 if(false)"），
     * 使最旧归档不再被删除，从而让 RunRuntimeLogRotationProductionCapSelfTest 的
     * "归档数 == 保留上限"与"已淘汰最旧"两条断言失败。
     */
    internal static bool RuntimeArchiveEvictionEnabled { get; set; } = true;

    /**
     * 裁决交付要求：自测必须产出**原始输出**。本内存记录器只在 --self-test 打开
     * （默认关闭 ⇒ 生产仅一次 bool 读取，零写盘/零分配变化），不改变任何写盘行为。
     */
    private static readonly List<(string Event, string Details)> SelfTestSink = new();
    internal static bool SelfTestCaptureEnabled { get; set; }
    internal static IReadOnlyList<(string Event, string Details)> SelfTestCaptured
    {
        get { lock (SelfTestSink) return SelfTestSink.ToArray(); }
    }
    internal static void ResetSelfTestCapture()
    {
        lock (SelfTestSink) SelfTestSink.Clear();
    }

    /**
     * 2026-09-24 裁决卡 §6-A（取证隔离，**必须修**）：自测 / 故障注入 / 模拟器
     * **不得**写入生产日志目录。
     * 历史缺陷：自测路径大量使用无参 `new HostDiagnosticLog()`（= 默认生产目录），
     * 使夹具注入内容（例：`device-release:fake-aura:injected-release-failure`）
     * 污染真实账本，并被误当成现场故障证据（R5 跨机器归因错误的根因之一）。
     * 修法：由自测派发点设置一次 **run 级隔离根**，此后任何无参构造（含嵌套引擎、
     * 后台重试）自动落到隔离根；同时经**环境变量**传播，使自测拉起的子进程同样继承，
     * 不漏回默认目录。**生产路径（未进入自测）行为完全不变。**
     */
    internal const string SelfTestLogRootEnvVar = "YEMANCC_SELFTEST_LOG_ROOT";
    private static string? selfTestLogRootOverride;

    internal static void EnterSelfTestLogIsolation(string label)
    {
        var root = System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "yemancc-selftest-" + label + "-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        selfTestLogRootOverride = root;
        Environment.SetEnvironmentVariable(SelfTestLogRootEnvVar, root);
    }

    /** 隔离根解析：显式参数 > run 级覆盖 > 子进程继承的环境变量；全空 ⇒ 生产目录。 */
    private static string? ResolveSelfTestLogRoot(string? logDirectoryForSelfTest) =>
        logDirectoryForSelfTest
        ?? selfTestLogRootOverride
        ?? Environment.GetEnvironmentVariable(SelfTestLogRootEnvVar);

    public HostDiagnosticLog(string? logDirectoryForSelfTest = null, int runtimeMaxBytesForSelfTest = 0)
    {
        runtimeMaxBytes = runtimeMaxBytesForSelfTest > 0
            ? runtimeMaxBytesForSelfTest
            : DefaultRuntimeMaxBytes;
        // Runtime diagnostics are mutable user state. Keep them outside the
        // immutable Host payload so log rotation can never weaken the ACL of
        // the executable and HC dependency directory.
        // 隔离根（自测）优先于生产目录，避免夹具污染真实账本。
        var isolatedRoot = ResolveSelfTestLogRoot(logDirectoryForSelfTest);
        var directory = isolatedRoot ?? System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "YeManCC", "fan-host", "logs");
        Directory.CreateDirectory(directory);
        path = System.IO.Path.Combine(directory, "yeman-fan-host-runtime.log");
        // 免门故障账本：与 runtime 日志同目录 ⇒ 既有导出器对 *.log 的全量收集会自动带上。
        faultPath = System.IO.Path.Combine(directory, "fan-host-fault.log");
        enabledFlagPath = isolatedRoot is null
            ? System.IO.Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "YeManCC", "fan-host", "fan-logging-enabled.flag")
            // 自测覆写：门 flag 一并落到隔离目录，使 T8 可确定地开关日志门而**不触碰**
            // 用户真实 %LOCALAPPDATA% 状态（生产路径恒走上面的真实 flag）。
            : System.IO.Path.Combine(isolatedRoot, "fan-logging-enabled.flag");
    }

    public string Path => path;

    public void SetContextProvider(Func<object?> provider) => contextProvider = provider;

    /** 日志门当前是否开启（flag 缺失/内容非显式真值 ⇒ 关）。 */
    private bool IsGateEnabledUnlocked()
    {
        if (!File.Exists(enabledFlagPath)) return false;
        // Native owns the shared switch and writes "enabled".  Keep
        // "1" readable for existing installs so diagnostics never
        // disappear merely because the two processes use different
        // representations of the same explicit user choice.
        var enabledValue = File.ReadAllText(enabledFlagPath).Trim();
        return string.Equals(enabledValue, "enabled", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(enabledValue, "1", StringComparison.Ordinal);
    }

    /**
     * FAN-931 P1.2：**普通成功/无变化**事件不再构造完整诊断上下文。
     * 现场实测（FAN-929B 轮转日志）：`hc-operation.begin/return`、`api.request-success`
     * 这类例行记录里 `context` 占单条字节约 **80%**（60+ 字段 + 管理器状态字典拷贝），
     * 而它们本身几乎不含需要跨事件关联的信息。需要关联的事件（错误/超时/身份或代际变化/
     * 真实写收据/睡眠·退出·恢复责任）继续带完整上下文。
     * 判据是**事件名白名单**（与免门白名单同思路：极小、明确、只放例行高频成功事件），
     * 不是"日志门是否开启"——门开启时普通事件的轻量行仍然落盘。
     */
    private static readonly HashSet<string> LightweightContextEvents = new(StringComparer.Ordinal)
    {
        "hc-operation.begin",
        "hc-operation.return",
        "hc-operation.phase",
        "api.request-success",
        "host.runtime-sample",
    };

    /** FAN-931 P1.2：供 30 s 采样判定"这条记录是否会落盘"，避免为注定不写的记录取数。 */
    internal bool IsRuntimeGateEnabled()
    {
        lock (gate) return IsGateEnabledUnlocked();
    }

    public void Write(string eventName, object? details = null)
    {
        try
        {
            // 自测捕获必须先于日志门判定：门关闭时的事件同样要被测试看到（否则
            // "门关时无证据"这一 N17 场景无法断言）。默认关闭 ⇒ 生产零成本。
            if (SelfTestCaptureEnabled)
            {
                var captured = details is null ? "{}" : JsonSerializer.Serialize(details, JsonDefaults.Options);
                lock (SelfTestSink) SelfTestSink.Add((eventName, captured));
            }
            lock (gate)
            {
                var gateEnabled = IsGateEnabledUnlocked();
                var gateFreeFault = GateFreeFaultEvents.Contains(eventName);
                // 免门白名单：门关闭时也必须留下这一条；门开启时照常进 runtime 日志
                // （同时留一份在故障账本，便于"卡死态"单独取证）。
                if (!gateEnabled && !gateFreeFault) return;
                // 裁决 P-4：高频幂等成功轮询降采样（仅作用于 runtime 详细日志；
                // 免门故障账本不受影响，其余事件也不进入本判定）。
                if (gateEnabled && !gateFreeFault &&
                    PollingSuccessDownsampleEnabled && ShouldSkipPollingSuccess(eventName, details))
                    return;
                object? context = null;
                // FAN-931 P1.2：例行成功事件跳过完整上下文构造（实测占这类记录约 80% 字节）。
                if (!LightweightContextEvents.Contains(eventName))
                {
                    try { context = contextProvider?.Invoke(); }
                    catch (Exception ex) { context = new { contextError = ex.GetType().Name }; }
                }
                var timestampUtc = DateTimeOffset.UtcNow;
                var detailElement = details is null
                    ? (JsonElement?)null
                    : JsonSerializer.SerializeToElement(details, JsonDefaults.Options);
                static string Evidence(JsonElement? element, string name)
                {
                    if (element is not JsonElement value || value.ValueKind != JsonValueKind.Object ||
                        !value.TryGetProperty(name, out var property)) return "not-observed";
                    return property.ValueKind switch
                    {
                        JsonValueKind.String => property.GetString() ?? "not-observed",
                        JsonValueKind.True => "true",
                        JsonValueKind.False => "false",
                        JsonValueKind.Number => property.GetRawText(),
                        _ => "observed",
                    };
                }
                var phase = Evidence(detailElement, "phase");
                var source = Evidence(detailElement, "source");
                var operation = Evidence(detailElement, "operation");
                var deviceType = Evidence(detailElement, "deviceType");
                var sku = Evidence(detailElement, "sku");
                var provider = Evidence(detailElement, "provider");
                var protocolResult = Evidence(detailElement, "protocolResult");
                var transportResult = Evidence(detailElement, "transportResult");
                var callbackResult = Evidence(detailElement, "callbackResult");
                var readback = Evidence(detailElement, "readback");
                var readbackMatch = Evidence(detailElement, "readbackMatch");
                var physicalObservation = Evidence(detailElement, "physicalObservation");
                var physicalWindow = Evidence(detailElement, "physicalWindow");
                var owner = Evidence(detailElement, "owner");
                var ownerPid = Evidence(detailElement, "ownerPid");
                var error = Evidence(detailElement, "error");
                var timeout = Evidence(detailElement, "timeout");
                var generation = Evidence(detailElement, "generation");
                var record = new
                {
                    schemaVersion = SchemaVersion,
                    diagnosticSchemaVersion = DiagnosticSchemaVersion,
                    hostInstanceId,
                    processId = Environment.ProcessId,
                    threadId = Environment.CurrentManagedThreadId,
                    runId = $"fan-host:{Environment.ProcessId}:{hostInstanceId}",
                    atUtc = timestampUtc,
                    timestampUtc,
                    timestampLocal = timestampUtc.ToLocalTime(),
                    eventName,
                    source,
                    phase,
                    operation = operation == "not-observed" ? eventName : operation,
                    deviceType,
                    sku,
                    provider,
                    protocolResult,
                    transportResult,
                    callbackResult,
                    readback,
                    readbackMatch,
                    physicalObservation,
                    physicalWindow,
                    owner,
                    ownerPid,
                    generation,
                    error,
                    timeout,
                    context,
                    details = details ?? new { },
                };
                var line = JsonSerializer.Serialize(record, JsonDefaults.Options) + Environment.NewLine;
                if (gateFreeFault) File.AppendAllText(faultPath, line, Encoding.UTF8);
                if (gateEnabled) AppendRuntimeWithRotation(line, Encoding.UTF8.GetByteCount(line));
            }
        }
        catch { /* Diagnostics must never affect the hardware safety path. */ }
    }

    /**
     * 裁决 P-4：仅"成功轮询"事件进入采样。键 = endpoint + status；命中同键同 state
     * 且距上次记录不足 PollingSuccessMinIntervalMs 才吞掉；首次/状态变化/超时后必记录。
     * 任何解析异常都按"不采样"处理（宁多写一条，绝不吞证据）。
     */
    private bool ShouldSkipPollingSuccess(string eventName, object? details)
    {
        if (!string.Equals(eventName, "api.request-success", StringComparison.Ordinal)) return false;
        if (details is null) return false;
        string? endpoint = null;
        var status = "n/a";
        var state = "n/a";
        try
        {
            var element = JsonSerializer.SerializeToElement(details, JsonDefaults.Options);
            if (element.ValueKind != JsonValueKind.Object) return false;
            if (element.TryGetProperty("path", out var pathProperty) && pathProperty.ValueKind == JsonValueKind.String)
                endpoint = pathProperty.GetString();
            if (element.TryGetProperty("httpStatus", out var statusProperty))
                status = statusProperty.GetRawText();
            if (element.TryGetProperty("state", out var stateProperty))
                state = stateProperty.ValueKind == JsonValueKind.String
                    ? stateProperty.GetString() ?? "n/a"
                    : stateProperty.GetRawText();
        }
        catch { return false; }
        if (endpoint is null || !PollingSuccessEndpoints.Contains(endpoint)) return false;
        var key = endpoint + "|" + status;
        var now = Environment.TickCount64;
        if (pollingSuccessLastWrite.TryGetValue(key, out var last) &&
            string.Equals(last.State, state, StringComparison.Ordinal) &&
            now - last.TickMs < PollingSuccessMinIntervalMs)
            return true;
        pollingSuccessLastWrite[key] = (now, state);
        return false;
    }

    /**
     * 裁决 P-4：active runtime 日志独立轮转。在同一写锁内先判上限、超限即原子改名归档，
     * 再追加当前行。任何异常都被吞掉并只记一条尽力而为的告警——
     * 诊断写盘绝不反向影响 FanHost/HC 安全路径。
     */
    private void AppendRuntimeWithRotation(string line, int byteCount)
    {
        try
        {
            if (runtimeBytes < 0) runtimeBytes = File.Exists(path) ? new FileInfo(path).Length : 0;
            if (runtimeBytes > 0 && runtimeBytes + byteCount > runtimeMaxBytes) RotateRuntimeUnlocked();
            File.AppendAllText(path, line, Encoding.UTF8);
            runtimeBytes += byteCount;
        }
        catch
        {
            runtimeBytes = -1;
            EmitRotationWarning();
        }
    }

    /** active → yeman-fan-host-runtime.<n>.log（n = 现有最大序号 + 1，跨会话单调递增）。 */
    private void RotateRuntimeUnlocked()
    {
        var directory = System.IO.Path.GetDirectoryName(path)!;
        var prefix = System.IO.Path.GetFileNameWithoutExtension(path) + ".";
        var archives = new List<int>();
        var next = 1;
        foreach (var file in Directory.EnumerateFiles(directory, prefix + "*.log"))
        {
            var name = System.IO.Path.GetFileNameWithoutExtension(file);
            if (!name.StartsWith(prefix, StringComparison.Ordinal)) continue;
            if (int.TryParse(name.Substring(prefix.Length), System.Globalization.NumberStyles.None,
                    System.Globalization.CultureInfo.InvariantCulture, out var index) && index > 0)
            {
                archives.Add(index);
                if (index >= next) next = index + 1;
            }
        }
        var archivePath = System.IO.Path.Combine(
            directory,
            prefix + next.ToString(System.Globalization.CultureInfo.InvariantCulture) + ".log");
        File.Move(path, archivePath);
        runtimeBytes = 0;
        archives.Add(next);
        archives.Sort();
        // 裁决 P-4 C 第 3 项（"负例能真实失败"）：淘汰守卫。生产恒为 true；
        // 负例在 **scratch 副本**里把它改成 false（等价"淘汰守卫 if(false)"），使最旧归档不再被删，
        // 从而让 RunRuntimeLogRotationProductionCapSelfTest 的"归档数 == 保留上限 / 已淘汰"断言失败。
        if (!RuntimeArchiveEvictionEnabled) return;
        for (var i = 0; i < archives.Count - RuntimeArchiveKeep; i++)
        {
            try
            {
                File.Delete(System.IO.Path.Combine(
                    directory,
                    prefix + archives[i].ToString(System.Globalization.CultureInfo.InvariantCulture) + ".log"));
            }
            catch { /* 归档清理失败不影响安全路径。 */ }
        }
    }

    /** 轮转/写盘失败：每进程只记一条尽力而为的告警，绝不再抛。 */
    private void EmitRotationWarning()
    {
        if (rotationWarningEmitted) return;
        rotationWarningEmitted = true;
        try
        {
            var line = JsonSerializer.Serialize(new
            {
                schemaVersion = SchemaVersion,
                diagnosticSchemaVersion = DiagnosticSchemaVersion,
                hostInstanceId,
                atUtc = DateTimeOffset.UtcNow,
                eventName = "host.log-write-failed",
                details = new { bestEffort = true, cause = "runtime-append-or-rotation" },
            }, JsonDefaults.Options) + Environment.NewLine;
            File.AppendAllText(path, line, Encoding.UTF8);
        }
        catch { /* 尽力而为：告警本身失败也绝不外抛。 */ }
    }
}

internal sealed record FanLease(string LeaseId, long Generation, long ExpiresAtMonoMs, string Owner);

/**
 * FAN-931 P0：**有限、固定字段**的请求入口与重复工作计数（只诊断）。
 * 刻意做成静态、定长数组 + Interlocked：无字符串键增长、无锁、无分配；单条事件几次自增，
 * 远低于它替代的"每心跳落一条大日志"。用途是回答"哪一类调用者在驱动这些重复工作"，
 * **不是**认证依据，也不含 token/lease 秘密。经 `GET /api/perf-counters` 只读导出。
 */
internal static class FanPerfCounters
{
    /** 已知请求路径槽位（下标 0 固定为 other）；路径字符串只在启动时用于建索引。 */
    private static readonly string[] KnownPaths =
    {
        "/health", "/api/state", "/api/heartbeat", "/api/enable", "/api/preset", "/api/disable",
        "/api/restore", "/api/release-control", "/api/open", "/api/open-events", "/api/acquire-control",
        "/api/close", "/api/suspend", "/api/resume", "/api/parent-exit", "/api/shutdown",
        "/api/perf-counters",
    };
    /** 调用者归类槽位：0=bridge(WebView2/Edg UA)、1=native(自建 WinHTTP UA)、2=other、3=unknown。 */
    private static readonly string[] ClientKinds = { "bridge", "native", "other", "unknown" };

    private static readonly long[] pathTotals = new long[KnownPaths.Length + 1];
    private static readonly long[] clientTotals = new long[ClientKinds.Length];
    private static readonly long[] pathByClient = new long[(KnownPaths.Length + 1) * ClientKinds.Length];

    internal static long DiagnosticContextBuilds;
    internal static long StaVerifyRequests;
    internal static long ParentIdentityReads;
    internal static long LoopStopAttempts;
    internal static long LoopStopRequests;
    internal static long LoopStopAlreadyPending;
    internal static long RuntimeSamplesRecorded;
    internal static long RuntimeSamplesSkipped;
    internal static long RuntimeStatusReads;

    private static int PathSlot(string path)
    {
        for (var i = 0; i < KnownPaths.Length; i++)
            if (string.Equals(KnownPaths[i], path, StringComparison.Ordinal)) return i + 1;
        return 0;
    }

    /**
     * 调用者归类**只是启发式诊断**（native 自建 UA 含 `Chrome/131.0` 而无 `Edg/`；
     * WebView2 渲染器的 UA 含 `Edg/` 或 `WebView2`）。绝不可作为认证或授权依据。
     */
    private static int ClientSlot(string? userAgent)
    {
        if (string.IsNullOrEmpty(userAgent)) return 3;
        if (userAgent.Contains("Edg/", StringComparison.OrdinalIgnoreCase) ||
            userAgent.Contains("WebView2", StringComparison.OrdinalIgnoreCase)) return 0;
        if (userAgent.Contains("Chrome/131.0", StringComparison.OrdinalIgnoreCase)) return 1;
        return 2;
    }

    internal static void RecordRequest(string path, string? userAgent)
    {
        var p = PathSlot(path);
        var c = ClientSlot(userAgent);
        Interlocked.Increment(ref pathTotals[p]);
        Interlocked.Increment(ref clientTotals[c]);
        Interlocked.Increment(ref pathByClient[p * ClientKinds.Length + c]);
    }

    /** 只读快照（定长、扁平、无秘密）。 */
    internal static object Snapshot()
    {
        object[] paths = new object[KnownPaths.Length + 1];
        for (var p = 0; p < paths.Length; p++)
        {
            var byClient = new Dictionary<string, long>(StringComparer.Ordinal);
            for (var c = 0; c < ClientKinds.Length; c++)
            {
                var value = Interlocked.Read(ref pathByClient[p * ClientKinds.Length + c]);
                if (value != 0) byClient[ClientKinds[c]] = value;
            }
            paths[p] = new
            {
                path = p == 0 ? "other" : KnownPaths[p - 1],
                total = Interlocked.Read(ref pathTotals[p]),
                byClient,
            };
        }
        object[] clients = new object[ClientKinds.Length];
        for (var c = 0; c < clients.Length; c++)
            clients[c] = new { kind = ClientKinds[c], total = Interlocked.Read(ref clientTotals[c]) };
        return new
        {
            note = "diagnostic-only counters; caller kind is a UA heuristic, never an authentication signal",
            paths,
            clients,
            diagnosticContextBuilds = Interlocked.Read(ref DiagnosticContextBuilds),
            staVerifyRequests = Interlocked.Read(ref StaVerifyRequests),
            parentIdentityReads = Interlocked.Read(ref ParentIdentityReads),
            loopStopAttempts = Interlocked.Read(ref LoopStopAttempts),
            loopStopRequests = Interlocked.Read(ref LoopStopRequests),
            loopStopAlreadyPending = Interlocked.Read(ref LoopStopAlreadyPending),
            runtimeSamplesRecorded = Interlocked.Read(ref RuntimeSamplesRecorded),
            runtimeSamplesSkipped = Interlocked.Read(ref RuntimeSamplesSkipped),
            runtimeStatusReads = Interlocked.Read(ref RuntimeStatusReads),
        };
    }
}

internal sealed class HostState
{
    public string State { get; set; } = "Stopped";
    public string PowerState { get; set; } = "Unknown";
    // 跨进程恢复确认（第一批，Host 侧操作记录）：
    // pending=已接收待执行 / executing=执行中 / completed / failed / superseded（被新睡眠取代）。
    // completed 时 Outcome 区分 restored（已恢复控制）与 await-user（无曲线、等待接管）。
    public long PowerOperationGeneration { get; set; }
    public string? PowerOperationStatus { get; set; }
    public string? PowerOperationOutcome { get; set; }
    public int PowerOperationAttempt { get; set; }
    public bool HardwareCapable { get; set; }
    public bool HardwareWriteAuthorizationGranted { get; set; }
    public bool HardwareWritesEnabled { get; set; }
    public bool HardwareWritesObserved { get; set; }
    public bool HardwareWrites => HardwareWritesEnabled && HardwareWritesObserved;
    // Separate simulated control from physical hardware evidence in explicit AI sessions.
    public bool MockZeroHardwareEvidence { get; set; }
    public bool MockControlEnabled { get; set; }
    public bool MockCloseCompleted { get; set; }
    public bool MockWritesObserved { get; set; }
    public long MockControlSequence { get; set; }
    public string? FactoryType { get; set; }
    public string? FanRoute { get; set; }
    public bool FanRouteWriteReady { get; set; }
    public Dictionary<string, string>? DeviceIdentity { get; set; }
    // Optional, source-qualified version evidence.  A missing value is not an
    // error: HC exposes firmware/EC data only on selected device routes.
    public HardwareVersionEvidence? EcEvidence { get; set; }
    public HardwareVersionEvidence? ControllerFirmwareEvidence { get; set; }
    public bool OpenCalled { get; set; }
    public bool OpenEventsCalled { get; set; }
    public bool HcManagerFactoryStarted { get; set; }
    public bool HcManagerFactoryIsolated { get; set; } = true;
    public string HcManagerFactoryLifecycle { get; set; } = "Unknown";
    // Manager status is observed only after the real HC OpenEvents boundary.
    // Before that point this remains an explicit Unknown, never an inferred
    // isolated state.
    public Dictionary<string, string>? HcManagerStatuses { get; set; }
    // Diagnostic-only: the currently executing HC lifecycle phase. This is
    // deliberately not used as a control gate; it lets a real-machine log
    // distinguish the virtual device Close() path from manager cleanup.
    public string? HcOperationPhase { get; set; }
    // Fan-only profile context evidence. These fields do not claim that the
    // isolated Host has a full HC ProfileManager subscription; they show the
    // exact AC/DC selection/fingerprint used for the current callback.
    public bool? ProfilePowerLineOnline { get; set; }
    public string? ProfileSelectionSource { get; set; }
    public string? ProfileTemplateFingerprint { get; set; }
    public string? LastUpdateSource { get; set; }
    public bool ExternalProfileEventsSubscribed { get; set; }
    public string? LastExternalProfileSource { get; set; }
    public string HcEventMode { get; set; } = "safe-no-hardware";
    public bool SetFanControlRestoreAttempted { get; set; }
    // §3.1 (FAN-925B) compatibility field. It is a **software action contract**
    // marker, not physical ownership: it may be true while the release action
    // itself was never transmitted. Consumers must read `OemReleaseActionKind`
    // instead. Never describe this field as "OEM/EC physically took over".
    public bool OemRestoreConfirmed { get; set; }
    // Audit-only callback evidence (the HC Hardware callback merely returned).
    // Deliberately separate from both the release-action authority below and
    // any physical observation.
    public bool HcRestoreCallbackReturned { get; set; }
    // §3.1 单一权威（FAN-925B）：本周期**释放动作**的证据，按当次、对应路由的收据分类。
    // 三类消费一致：释放动作证据 / HC 资源清理状态 / 可选物理观察。任何出口
    // （HTTP 状态、native 安全判据、收尾判据、route-lost 结算）都只看这一份，
    // 不得各自添加 cleanup 捷径，也不得把 cleanup 或回调返回顶替本项。
    //   not-applicable-no-write-history / proven-by-scope-receipts /
    //   proven-by-host-hc-acpi-fallback / unknown-* / failed-* /
    //   compat-route-without-scope / not-attempted
    public string OemReleaseActionKind { get; set; } = "not-attempted";
    public string OemReleaseActionEvidence { get; set; } = "none";
    // Optional physical observation. Diagnostic only; never a gate on its own.
    public bool OemPhysicalOwnershipObserved { get; set; }
    public string OemRestoreEvidence { get; set; } = "none";
    public string OemOwnershipStatus { get; set; } = "unknown-no-hc-contract";
    // OEM handoff is already safe when the HC resource-only Close call times
    // out. Keep this diagnostic separate from the fan ownership proof: a
    // pending disposal must never turn a confirmed OEM restore into a false
    // FaultLocked state or permit another fan write.
    public bool HcCloseCleanupPending { get; set; }
    // Lifecycle evidence is deliberately separate from OEM ownership.  HC's
    // virtual Close() is void, so a returned call proves the HC boundary
    // completed but cannot prove a universal physical EC/ACPI handoff.
    public bool HcVirtualCloseReturned { get; set; }
    // Compatibility only: this does NOT mean DeviceManager.Stop() was called.
    // It means CurrentDevice.Close() returned and the post-close HC manager
    // observation found no Active manager. Keep the old field for existing
    // parent gates, but pair it with the explicit evidence fields below.
    public bool HcDeviceManagerStopCompleted { get; set; } = true;
    public bool HcDeviceManagerStopInvoked { get; set; }
    public string HcManagerCleanupEvidence { get; set; } = "not-observed";
    // Fan-only sessions deliberately do not own HC DeviceManager.  Keep an
    // explicit lifecycle outcome so observers cannot confuse "no stop was
    // required" with a failed or pending manager cleanup.
    public string HcDeviceManagerLifecycle { get; set; } = "Unknown";
    public bool OemPhysicalOwnershipConfirmed { get; set; }
    public bool CloseCalled { get; set; }
    public bool UnknownState { get; set; }
    public FanLease? Lease { get; set; }
    // Safe telemetry identity for the active lease. The reusable token itself
    // is intentionally removed from Snapshot(); generation is non-secret and
    // lets the UI detect a stale remote owner without exposing credentials.
    public long? LeaseGeneration { get; set; }
    public string HostMode { get; set; } = "safe-no-hardware";
    public string ProtocolVersion { get; set; } = "2";
    // Listener lifecycle is a Host transport state, separate from HC device
    // ownership. ListenerFaultLocked remains visible even after a safe close
    // has moved the device state to Stopped.
    public string ListenerState { get; set; } = "Starting";
    public string? LastError { get; set; }
    public double? LastTemperatureC { get; set; }
    public double? CurrentDutyPercent { get; set; }
    public IReadOnlyList<FanNode>? ActiveCurve { get; set; }
    public bool ApiSessionProtected { get; set; }
    public bool RecoveryReadbackRequired { get; set; }
    // Q1（FAN-204 s31 补充裁决 2026-09-23）：恢复阶段真值。**由现有生命周期字段在
    // SnapshotUnlocked 派生**（单一真值源，不新增独立可变状态）。四态语义
    // Ready / Resuming / Suspended / FaultLocked；其余状态（AwaitingControl/Stopped/
    // Suspending/AwaitingCloseCleanup/…）按名透传，不得伪装成四态。
    public string ResumePhase { get; set; } = "Suspended";
    public long ResumePhaseGeneration { get; set; }
    /** 过渡期建议轮询间隔（ms）：调用方按同一 generation 有界观察（native ≤15 s）。 */
    public int ResumeRetryAfterMs { get; set; } = ResumePollRetryAfterMs;
    /** 当前是否允许重新发送控制（未在过渡、未故障/未知、无待清理、未关闭）。 */
    public bool ControlAccepting { get; set; }
    /**
     * 最近一次控制写入的收据口径（enable/restore 同一映射）：partial 通道证据必须
     * 与"完全成功"可区分——`partial-channel-evidence-not-success` 绝不可显示成成功。
     */
    public string LastControlWriteEvidence { get; set; } = "none";

    /** 过渡期建议轮询间隔（Host 只给建议，不强制调用方节拍）。 */
    internal const int ResumePollRetryAfterMs = 250;
}

internal sealed record FanNode(double TempC, double DutyPercent);

/**
 * Version evidence is deliberately descriptive rather than a guessed scalar.
 * `source` and `method` must point to an HC-proven device-specific mechanism;
 * raw EC port/register reads are never treated as a revision probe.
 */
internal sealed record HardwareVersionEvidence(
    string Status,
    string Kind,
    string? Source,
    string? Method,
    string? Revision,
    int? Major,
    int? Minor,
    bool Verified,
    bool ReadOnly,
    string Reason);

internal sealed record RealHandshakeResult(
    bool Supported,
    string? FactoryType,
    string? FanRoute,
    Dictionary<string, string>? DeviceIdentity,
    HardwareVersionEvidence? EcEvidence,
    HardwareVersionEvidence? ControllerFirmwareEvidence,
    string Reason,
    bool HardwareCapable,
    bool HardwareWriteAuthorizationGranted);

internal enum FanRouteKind
{
    GenericDuty,
    GenericRpmTarget,
    ProfileCurve,
}

internal enum FanRestoreStrategy
{
    None,
    GenericEcControl,
    GenericEcDutyRegister,
    AyanEOCEiiModeRegister,
    OneXAcpiFanMode,
    GpdWin4HcRelease,
    GpdWin5HcAutoRelease,
    AynLokiMode,
    MsiHcDefaultRelease,
    LenovoHcDefaultTable,
    LegionGo2EcRpmOverride,
    AsusAcpiCurves,
}

/**
 * §4.A（FAN-934，2026-09-29 裁决）：**路线证据适用性** —— 一次控制/释放操作应当用什么证据结算。
 *
 * 事故根因（GPD Win5／MSI 258V）：Host 把 ASUS 专属的"操作作用域收据"要求套到了所有机型。
 * `HandheldCompanion.Devices.ASUS.AsusAcpiObservations` 类型在**整个 HC 程序集**中都存在
 * （不随当前机型缺失），所以旧判据 `begin is null` 对 GPD/MSI 恒为 false ⇒ 永远走
 * `no-receipts` ⇒ `Unknown` ⇒ FaultLocked。本枚举把"该路线该操作期望什么证据"显式化，
 * 由生产调用点与测试共用，不再由"类型是否存在"隐式决定。
 *
 * fail-closed：默认值 `UnsupportedNoScope`，未显式声明的路线不会被当成"兼容通过"。
 */
internal enum FanEvidenceMode
{
    /**
     * ASUS 专属：本操作期望 ASUS 操作作用域收据。API 缺失/取收据异常/空收据/零通道失败
     * 一律按既有 real-failure/unknown 处理，**不得**退化成"无 scope 兼容成功"。
     */
    AsusScopeReceipts,
    /**
     * 已逐族源码审阅的非 ASUS HC 路线：本操作**不期望** ASUS 收据。在"当前正确实例/会话/路线、
     * Open/资源前提成立、真实回调执行并返回"后产出 `compat-route-without-scope`（等价软件回调
     * 合同证据）。任一前提不成立 ⇒ 未证/失败，不得凭历史收据或空收据通过。
     */
    CompatCallbackNoScope,
    /**
     * 未审阅/不支持：既无 scope 期望，也不取得回调合同证据 ⇒ 不构成成功（保底，不当作兼容通过）。
     */
    UnsupportedNoScope,
}

/**
 * FAN-934 R2 §3-A.2：某条已审阅 HC 路线在**开始一次操作前**必须成立的真实前提。
 * 取证来源（只读 HC runtime 源码，不按厂商一刀切）：
 * - `OpenLibHandleOpen`：设备走 OpenLib 句柄，写路径全部 `if (!UseOpenLib || !IsOpen) return;`
 *   （`IDevice.cs:1001+`；`UseOpenLib=true` 见 GPD/GPDWinMini|Win5|Win4|WinMax2、OneXAOKZOE、
 *   AYANEODevice、AynLoki、LegionGoTablet2、GamingZone）。这些设备**会静默 return**：仅
 *   "反射 Invoke 未抛异常"不足以证明回调真的执行，故必须要求 `UseOpenLib==true && IsOpen==true`。
 * - `DeviceOpenAndSupported`：SteamDeck `IsOpen => inpOut is not null`、`IsSupported => SupportedDevice
 *   非空且 Firmware!=0`，两条都需成立。
 * - `DeviceOpen`：MSI ClawA1M（`IsOpen => DeviceOpen && ClawOpen`）与 Lenovo LegionGo SZ1/SZ2/Tablet
 *   （WMI 表路径）。`WMI.Set(...)` 参数不可得时**只记日志并返回 null，不抛异常** ⇒ 必须另核设备 `IsOpen`。
 * - `Undeclared`（fail-closed 默认）：任何未显式声明前提的路线**不得**凭未审阅前提通过。
 */
internal enum FanRoutePrecondition
{
    Undeclared = 0,
    DeviceOpen,
    OpenLibHandleOpen,
    DeviceOpenAndSupported,
}

internal sealed record FanRoute(
    FanRouteKind Kind,
    string Description,
    bool WriteReadyByDefault = false,
    bool HcCallbackReady = false,
    FanRestoreStrategy RestoreStrategy = FanRestoreStrategy.None,
    FanEvidenceMode Evidence = FanEvidenceMode.UnsupportedNoScope,
    FanRoutePrecondition Precondition = FanRoutePrecondition.Undeclared);

/**
 * §3.1/§3.2（FAN-925B）：释放动作的**唯一权威分类**。文件作用域 —— RealHcBackend
 * （收据生产方）、FanHostEngine（判据消费方）与退出收尾（LocalFanHostServer）必须
 * 消费同一份定义，不允许任一处各自添加 cleanup 捷径。
 */
internal enum OemReleaseAction
{
    /** 本周期确无写入历史 ⇒ 不适用释放（诚实对照；不得由提前清位/切代/skipOemRestore 伪造）。 */
    NotApplicable,
    /** 本次释放动作有有效传输收据（transported，或 partial：至少一通道送达）。 */
    Proven,
    /** scope 支持但无收据/取收据异常/仅未知 ⇒ 未证：既不判成功，也不默认"物理写入零次"。 */
    Unknown,
    /** 明确失败/零通道送达。 */
    Failed,
    /** 该已评审路由确实不具备 scope 能力 ⇒ 保留其原有路线合同（标兼容，不当成功证据）。 */
    CompatRouteWithoutScope,
}

/**
 * Reflection boundary for the pinned HC assembly.  The safe build contains
 * this code but never constructs it unless --real-backend is supplied.  This
 * keeps the normal desktop binary from resolving HC or native dependencies.
 */
internal sealed partial class RealHcBackend : IDisposable
{
    // 920 v1.15 §26.3（2026-09-21 裁决：隔离发布候选晋级）：锁定的 HC 程序集重基线到
    // 候选 HandheldCompanion.dll（0c5132a9…，FAN-936 单一闭包：ASUS FAN-925B/S22-S23 + MSI FAN-936）。
    // 此处必须与发布载荷实际携带的 HC 一致
    // （PowerControl/fan-host/YeManFanHost.authorization.md 的 approvedHcSha256）。
    // FAN-927 §2.2（2026-09-27 用户批准）：这个内容哈希**不再**在每次 HC 加载时重算——
    // 完整文件校验归部署边界（安装/更新/回滚/修复），运行期只核对小"部署记录"。
    // 该常量保留为部署/修复与校验器（verify-r5v9-fan-host-payload.ps1、build-fan-host-payload.ps1）
    // 的权威锁定值，任何未获准的 HC 仍会在部署边界被拒绝。
    private const string ExpectedHcSha256 = "0c5132a9d13aebfc5add2aa7c9ac54e8daaa8ebc816a0c68d099bb9685dc2e49";

    /**
     * 920-v1.6 §18.2 的诊断覆盖保持不变：`--hc-expected-sha256` 只用于隔离/无硬件联调，
     * 生产默认值即上面的锁定常量。
     */
    private string EffectiveExpectedHcSha256 =>
