    /** 仅自测：注入 `HcCoreWarning` 以断言 E-1 读数把它带出（生产路径不调用）。 */
    internal void SetHcCoreWarningForSelfTest(string? value) => HcCoreWarning = value;

    /**
     * Detached HC ProfileManager event queue.  Applied/Discarded callbacks may
     * run while HC owns its profile lock, so this type deliberately contains no
     * HC calls and no hardware gate.  A snapshot is retained until the
     * serialized watchdog completes the clone -> build -> callback transaction;
     * a failed transaction gets a bounded retry instead of being silently
     * consumed.  Every snapshot is tied to the generation captured by the
     * event delegate, so a late callback from a closed session cannot enter a
     * later Open/Resume session.
     */
    private sealed class ExternalProfilePendingQueue
    {
        internal const int MaxRetryAttempts = 3;

        internal sealed class Snapshot
        {
            internal Snapshot(object profile, string source, long generation, long sequence)
            {
                Profile = profile;
                Source = source;
                Generation = generation;
                Sequence = sequence;
            }

            internal object Profile { get; }
            internal string Source { get; }
            internal long Generation { get; }
            internal long Sequence { get; }
            internal int RetryAttempts { get; set; }
        }

        private readonly object gate = new();
        private long generation;
        private long sequence;
        private bool accepting;
        private Snapshot? pending;
        private bool discarded;
        private DateTimeOffset? discardedAtUtc;
        private bool discardedTimeoutReported;

        internal long CurrentGeneration
        {
            get { lock (gate) return generation; }
        }

        /**
         * FAN-931 P1.5：discard→Applied 截止点是否仍需**一次有界复核**。
         * 返回 -1 = 无需复核（没有丢弃边界，或该截止点已报告）；0 = 已到点。
         * 只有在截止时刻**之后**跑的那一拍才可能报出 noAppliedAfterDiscard，因此
         * FAN-929 的一次性武装必须为此按需再排一次（而不是恢复常驻轮询）。
         */
        internal int DiscardedAppliedDeadlineRemainingMs(DateTimeOffset now, TimeSpan timeout)
        {
            lock (gate)
            {
                if (discardedAtUtc is null || discardedTimeoutReported) return -1;
                var remaining = timeout.TotalMilliseconds - (now - discardedAtUtc.Value).TotalMilliseconds;
                return remaining <= 0 ? 0 : (int)Math.Ceiling(remaining);
            }
        }

        /** FAN-931 P1.5：是否还有**已被记过一次失败**的待采纳快照（存在 ⇒ 需要一次有界重试拍）。 */
        internal bool HasRetryPending()
        {
            lock (gate) return accepting && pending is not null && pending.RetryAttempts > 0;
        }

        internal long BeginSession()
        {
            lock (gate)
            {
                generation++;
                accepting = false;
                pending = null;
                discarded = false;
                discardedAtUtc = null;
                discardedTimeoutReported = false;
                return generation;
            }
        }

        internal bool ActivateSession(long expectedGeneration)
        {
            lock (gate)
            {
                if (generation != expectedGeneration) return false;
                accepting = true;
                return true;
            }
        }

        internal long InvalidateSession()
        {
            lock (gate)
            {
                generation++;
                accepting = false;
                pending = null;
                discarded = false;
                discardedAtUtc = null;
                discardedTimeoutReported = false;
                return generation;
            }
        }

        internal bool TryAcceptApplied(
            long callbackGeneration,
            object? profile,
            string source,
            out Snapshot? accepted,
            out string reason)
        {
            lock (gate)
            {
                if (profile is null)
                {
                    accepted = null;
                    reason = "null-profile";
                    return false;
                }
                if (!accepting)
                {
                    accepted = null;
                    reason = "session-inactive";
                    return false;
                }
                if (callbackGeneration != generation)
                {
                    accepted = null;
                    reason = "stale-session-generation";
                    return false;
                }
                accepted = new Snapshot(profile, source, generation, ++sequence);
                pending = accepted;
                discarded = false;
                discardedAtUtc = null;
                discardedTimeoutReported = false;
                reason = "accepted";
                return true;
            }
        }

        internal bool TryAcceptDiscarded(
            long callbackGeneration,
            DateTimeOffset observedAtUtc,
            out string reason)
        {
            lock (gate)
            {
                if (!accepting)
                {
                    reason = "session-inactive";
                    return false;
                }
                if (callbackGeneration != generation)
                {
                    reason = "stale-session-generation";
                    return false;
                }
                pending = null;
                discarded = true;
                discardedAtUtc = observedAtUtc;
                discardedTimeoutReported = false;
                sequence++;
                reason = "accepted";
                return true;
            }
        }

        internal bool TryGetPending(out Snapshot? snapshot)
        {
            lock (gate)
            {
                snapshot = pending;
                return snapshot is not null && accepting;
            }
        }

        internal bool IsCurrent(Snapshot snapshot)
        {
            lock (gate)
            {
                return accepting && generation == snapshot.Generation &&
                    ReferenceEquals(pending, snapshot);
            }
        }

        internal bool Complete(Snapshot snapshot)
        {
            lock (gate)
            {
                if (!ReferenceEquals(pending, snapshot) || generation != snapshot.Generation)
                    return false;
                pending = null;
                return true;
            }
        }

        internal bool RecordFailure(
            Snapshot snapshot,
            out int attempt,
            out bool exhausted)
        {
            lock (gate)
            {
                attempt = snapshot.RetryAttempts;
                exhausted = false;
                if (!ReferenceEquals(pending, snapshot) || generation != snapshot.Generation || !accepting)
                    return false;
                attempt = ++snapshot.RetryAttempts;
                if (attempt >= MaxRetryAttempts)
                {
                    pending = null;
                    exhausted = true;
                }
                return true;
            }
        }

        internal bool TryConsumeDiscarded(
            DateTimeOffset now,
            TimeSpan timeout,
            out bool noAppliedAfterDiscard)
        {
            lock (gate)
            {
                noAppliedAfterDiscard = false;
                var wasDiscarded = discarded;
                if (discarded) discarded = false;
                if (discardedAtUtc is not null && !discardedTimeoutReported &&
                    now - discardedAtUtc.Value >= timeout)
                {
                    discardedTimeoutReported = true;
                    noAppliedAfterDiscard = true;
                }
                return wasDiscarded;
            }
        }

        internal bool HasPendingForSelfTest => TryGetPending(out _);
    internal bool IsAcceptingForSelfTest
    {
        get { lock (gate) return accepting; }
    }
}

    /**
     * Side-effect-free R1 profile queue oracle.  It exercises only detached
     * objects/flags; no HC assembly, reflection callback or hardware path is
     * loaded.  Keep this next to the queue so a future lifecycle edit cannot
     * silently remove the retry/generation proof from the Host self-test.
     */
    internal static IReadOnlyList<string> RunExternalProfileQueueSelfTest()
    {
        var checks = new List<string>();

        var retryQueue = new ExternalProfilePendingQueue();
        var retryGeneration = retryQueue.BeginSession();
        if (!retryQueue.ActivateSession(retryGeneration))
            throw new InvalidOperationException("R1 profile queue failed to activate its session");
        if (!retryQueue.TryAcceptApplied(
                retryGeneration,
                new object(),
                "Serializer",
                out var retrySnapshot,
                out _)
            || retrySnapshot is null)
            throw new InvalidOperationException("R1 Applied snapshot was not accepted");

        for (var attempt = 1; attempt < ExternalProfilePendingQueue.MaxRetryAttempts; attempt++)
        {
            if (!retryQueue.RecordFailure(retrySnapshot, out var observedAttempt, out var exhausted) ||
                observedAttempt != attempt || exhausted || !retryQueue.HasPendingForSelfTest)
                throw new InvalidOperationException("R1 Applied failure was consumed before retry budget exhausted");
        }
        if (!retryQueue.RecordFailure(retrySnapshot, out var finalAttempt, out var finalExhausted) ||
            finalAttempt != ExternalProfilePendingQueue.MaxRetryAttempts || !finalExhausted ||
            retryQueue.HasPendingForSelfTest)
            throw new InvalidOperationException("R1 Applied retry budget did not terminate explicitly at its limit");
        checks.Add("r1-external-applied-bounded-retry");

        var sessionQueue = new ExternalProfilePendingQueue();
        var firstGeneration = sessionQueue.BeginSession();
        if (!sessionQueue.ActivateSession(firstGeneration) ||
            !sessionQueue.TryAcceptApplied(firstGeneration, new object(), "Background", out _, out _))
            throw new InvalidOperationException("R1 first profile session was not established");
        sessionQueue.InvalidateSession();
        if (sessionQueue.HasPendingForSelfTest ||
            sessionQueue.TryAcceptApplied(firstGeneration, new object(), "Background", out _, out _))
            throw new InvalidOperationException("R1 stale Applied crossed the Close/session invalidation boundary");

        var secondGeneration = sessionQueue.BeginSession();
        if (!sessionQueue.ActivateSession(secondGeneration) ||
            sessionQueue.TryAcceptDiscarded(firstGeneration, DateTimeOffset.UtcNow, out _))
            throw new InvalidOperationException("R1 stale Discarded callback crossed the Resume generation boundary");
        if (!sessionQueue.TryAcceptApplied(secondGeneration, new object(), "ProfilesPage", out _, out _))
            throw new InvalidOperationException("R1 current-session Applied was rejected after Resume");
        sessionQueue.InvalidateSession();
        if (sessionQueue.HasPendingForSelfTest)
            throw new InvalidOperationException("R1 Close did not discard the current detached profile snapshot");
        checks.Add("r1-external-profile-session-generation");

        var discardQueue = new ExternalProfilePendingQueue();
        var discardGeneration = discardQueue.BeginSession();
        if (!discardQueue.ActivateSession(discardGeneration) ||
            !discardQueue.TryAcceptApplied(discardGeneration, new object(), "Background", out _, out _) ||
            !discardQueue.TryAcceptDiscarded(discardGeneration, DateTimeOffset.UtcNow, out _) ||
            discardQueue.HasPendingForSelfTest)
            throw new InvalidOperationException("R1 Discarded did not clear only the current pending snapshot");
        checks.Add("r1-external-discarded-boundary");

        return checks;
    }

    public RealHcBackend(HostOptions options)
    {
        this.options = options;
        // HC-SLIM-01 R3 §6.2②：会话内固定 provider，非法值 fail-closed（不静默回退第二 writer）。
        // 缺省（null/空）保持发布默认 "hc"，用户路径与既有行为逐字一致。
        var requested = options.FanProvider?.Trim();
        useBackendFanWriter = requested switch
        {
            null or "" or "hc" => false,
            "backend" => true,
            _ => throw new ArgumentException($"Unsupported --fan-provider: {options.FanProvider}"),
        };
    }
    public bool IsLoaded => assembly is not null && device is not null;
    public bool IsOpen { get; private set; }
    public bool OpenAttempted => openAttempted;
    public bool HcOpenInvocationStarted => hcOpenInvocationStarted;
    public string? SessionRouteMarker => sessionRouteMarker;
    /**
     * §4（FAN-925B）：当前 HC 兼容入口操作 id 的只读观测。用于在**进入等待重开时**拍
     * 基线，使"最近一次 Completed"不能被当成本次重开（旧成功必须被拒绝）。
     * 读不到返回 null（不构成成功证据）。
     */
    public string? LastCompatEntryOperationIdObserved =>
        device is null ? null : GetMember(device, "LastCompatEntryOperationId") as string;
    public bool OemRestoreVerified => oemRestoreVerified;
    /** §3.1 单一权威：本周期释放动作证据（机器消费入口）。 */
    public string OemReleaseActionKind => oemReleaseActionKind;
    public string OemReleaseActionEvidence => oemReleaseActionEvidence;
    public string OemRestoreEvidence => oemRestoreEvidence;
    public string OemOwnershipStatus => oemOwnershipStatus;
    public bool HcVirtualCloseReturned { get; private set; }
    /**
     * 裁决 H1（2026-09-19）：本 Host 是否**仍欠一次 HC 虚拟 Close 边界**的唯一判据。
     * 由 Open() 失败路径的原表达式抽出（见 OpenCore catch），使 SystemPending 的
     * close owner 与 Open 清理路径不可能各自漂移出第二份判定。
     */
    public bool HcCloseIsOwed => IsOpen || (openAttempted && hcOpenInvocationStarted);
    /**
     * 裁决 H1：会话是否仍持有 Open 成功后捕获的 HC 设备引用（与 SessionRouteMarker
     * 同置同清，此处按 C3 要求独立暴露）。
     */
    public bool HasSessionDeviceReference => sessionDeviceReference is not null;
    /**
     * 裁决 H1：HC 自身 IsOpen 标记的**只读**观测。读不到（未加载设备/反射失败）
     * 返回 null，且**永不作为阻塞判据**——判据 C2 已证明"HC Open 调用从未开始"，
     * 无所有权交叉时"未知"不影响判定。仅供诊断字段使用。
     */
    public bool? HcDeviceIsOpenObserved
    {
        get
        {
            if (device is null) return null;
            try { return GetMember(device, "IsOpen") as bool?; }
            catch { return null; }
        }
    }
    public bool HcDeviceManagerStopCompleted { get; private set; }
    // FanHost never calls DeviceManager.Stop(). HC owns that operation in its
    // full application lifecycle; this Host only observes the post-Close
    // graph after CurrentDevice.Close() returns.
    public bool HcDeviceManagerStopInvoked => false;
    /**
     * 裁决 H1/H2（2026-09-19）：`HcManagerCleanupEvidence` 的**唯一派生**（纯函数）。
     * 未进入会话（从未观测 manager 图、Close 未返回）必须如实报
     * `manager-graph-not-observed`——这正是真机 01:16 样本的取值，也是 H1 短路**不得**
     * 改动的字段。抽成纯函数使"真实后端下的期望取值"可在 Safe 构建中确定验证。
     */
    internal static string ManagerCleanupEvidence(bool stopCompleted, bool managerFactoryObserved) =>
        stopCompleted
            ? "post-close-no-active-manager-observed"
            : managerFactoryObserved
                ? "post-close-manager-cleanup-unconfirmed"
                : "manager-graph-not-observed";
    public string HcManagerCleanupEvidence =>
        ManagerCleanupEvidence(HcDeviceManagerStopCompleted, managerFactoryObserved);
