    private Type? ResolveAsusObservationsType() =>
        useBackendFanWriter
            ? typeof(YeManFanBackend.Asus.AsusAcpiObservations)
            : FindType("HandheldCompanion.Devices.ASUS.AsusAcpiObservations");
