        .OrderBy(pair => pair.Key, StringComparer.Ordinal)
        .Select(pair => new
        {
            deviceClass = pair.Key,
            routeKind = pair.Value.Kind.ToString(),
            routeDescription = pair.Value.Description,
            writeReadyByDefault = pair.Value.WriteReadyByDefault,
