        .ToArray();
    internal static IReadOnlyDictionary<string, FanRoute> FanRoutesForSelfTest => FanRoutes;
    /** FAN-934 §4.A/§6：暴露同一 vendor-namespace 解析（生产 `Route` 属性用它）。 */
    internal static FanRoute? ResolveRouteForSelfTest(string? factoryType) => ResolveRoute(factoryType);
    /** FAN-934 §4.C：暴露命令通道解析供自测断言。 */
    internal static IReadOnlyList<string> ResolveFanCommandChannelsForSelfTest(FanRestoreStrategy? strategy) =>
        ResolveFanCommandChannels(strategy);

    /**
     * §4.C（FAN-934，2026-09-29 裁决）：**命令通道按实际 provider 定义**，不再对全部厂商硬填
     * `CPU/GPU/Mid`（那会为 GPD/MSI 捏造第三风扇）。名称是**命令目标**，不是物理台数，也不代表
     * 独立 RPM 回读或硬件成功：
     * - ASUS/ROG：ACPI 曲线的 CPU/GPU/Mid 命令点；
     * - MSI：已知的 CPU/GPU 风扇表通道；
     * - GPD Win4/Win5：两路 duty 寄存器 ⇒ 两个逻辑通道 Fan1/Fan2；
     * - 其余路线（GenericEcControl / CEii / OneX / Loki / Lenovo 表 / None 等）：单命令语义无法
     *   逐通道确定 ⇒ 显式 `aggregate`（fail-honest，不制造通道）。
     */
    internal static IReadOnlyList<string> ResolveFanCommandChannels(FanRestoreStrategy? strategy) => strategy switch
    {
        FanRestoreStrategy.AsusAcpiCurves => ["CPU", "GPU", "Mid"],
        FanRestoreStrategy.MsiHcDefaultRelease => ["CPU", "GPU"],
        FanRestoreStrategy.GpdWin4HcRelease or FanRestoreStrategy.GpdWin5HcAutoRelease => ["Fan1", "Fan2"],
        _ => ["aggregate"],
    };
    internal bool TemperatureWritesBlockedForSelfTest => AreTemperatureWritesBlocked();
    internal static bool IsAclWriteUnsafeForSelfTest(FileSystemRights rights) => HasUnsafeWriteRights(rights);

    private static FanRoute? ResolveRoute(string? factoryType)
    {
        if (string.IsNullOrWhiteSpace(factoryType)) return null;
        if (FanRoutes.TryGetValue(factoryType, out var exact)) return exact;
        // The matrix records class names while HC namespaces differ by vendor
        // (for example MSI.ClawA1M and Lenovo.LegionGoSZ1). Class names are
        // unique in the mapped set, so resolve the vendor namespace safely.
        var className = factoryType[(factoryType.LastIndexOf('.') + 1)..];
        return FanRoutes.FirstOrDefault(pair => pair.Key.EndsWith($".{className}", StringComparison.Ordinal)).Value;
    }

    public RealHandshakeResult LoadAndHandshake() => OnStaBounded(LoadAndHandshakeCore);

    private RealHandshakeResult LoadAndHandshakeCore()
    {
        if (!IsLoaded) LoadAssemblyAndFactory();
        var factoryType = FactoryType;
        var route = Route;
        // This is metadata only.  It records the exact HC-proven source that
        // could be used after Open(), but performs no WMI/HID/EC read during
        // handshake and never treats a raw EC register as a revision.
        (EcEvidence, ControllerFirmwareEvidence) = DescribeVersionEvidence(factoryType);
        var supported = route is not null;
        var reason = route is null
            ? "HC factory 类型不在 YeMan 风扇设备矩阵内"
            : (CanWrite
                ? $"HC fan route {route.Kind} 通过，真实写入已获显式授权"
                : $"HC fan route {route.Kind} 已识别；当前仅握手/未授权写入");
        if (HcCoreWarning is not null) reason += $"；{HcCoreWarning}";
        return new RealHandshakeResult(supported, factoryType, route?.Kind.ToString(), DeviceIdentity, EcEvidence, ControllerFirmwareEvidence, reason, true, supported && IsAuthorized());
    }

    /**
     * FAN-936 §1（2026-10-01 裁决）：MSI 专项**只读**状态采样入口。
     * 前提是**绝不先调用会改变硬件状态的 HC `Open()`**；一次带出风扇表 1/2、`Get_Data(152)`、
     * `Get_AP(1)`、`Get_AP(0)`、机型、固件、Host 实例与 boot identity，供现场 A/B 冷启动对拍。
     * 采样本身零写入；找不到 HC 的只读采样方法时如实记 `unsupported`，绝不回落成任何写入路径。
     * 返回 `(Snapshot, ExitCode)`：只有真正完成一次只读采样（装配成功且 `sampled`）才返回 0；
     * 装配失败/`unsupported`/`null-result`/采样抛错一律返回非零，采样失败不得以 exit0 冒充成功。
     */
    public (object Snapshot, int ExitCode) CaptureMsiReadOnlySnapshot() =>
        OnStaBounded(CaptureMsiReadOnlySnapshotCore, "msi-readonly-sample");

    private (object Snapshot, int ExitCode) CaptureMsiReadOnlySnapshotCore()
    {
        // 只补"装配程序集/构造工厂"这一步（与生产 `LoadAndHandshakeCore` 相同），**不**调用 Open()：
        // HC 的 Open() 会写软件控制位，取证卡必须发生在任何写入之前。
        var loadOutcome = "already-loaded";
        string? loadError = null;
        if (!IsLoaded)
        {
            try
            {
                LoadAssemblyAndFactory();
                loadOutcome = "loaded";
            }
            catch (Exception ex)
            {
                loadOutcome = "failed";
                // 展开完整异常链（含 TargetInvocationException/TypeInitializationException 的 inner），
                // 否则只留一句 "Exception has been thrown by the target of an invocation." 无法诊断。
                loadError = string.Join(" -> ", Unwrap(ex).Select(e => $"{e.GetType().Name}: {e.Message}"));
            }
        }

        var sampleOutcome = "unsupported";
        string? sampleError = null;
        object? msiState = null;
        bool? msiStateMatchesBootIdentity = null;
        if (device is not null)
        {
            var sampler = device.GetType()
                .GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(m => m.Name == "ReadMsiFanStateReadOnly" && m.GetParameters().Length == 0);
            if (sampler is not null)
            {
                try
                {
                    var result = sampler.Invoke(device, null);
                    if (result is null)
                    {
                        sampleOutcome = "null-result";
                    }
                    else
                    {
                        msiState = ReflectPublicState(result);
                        msiStateMatchesBootIdentity = string.Equals(
                            GetMember(result, "BootIdentity") as string, machineBootIdentity, StringComparison.Ordinal);
                        // FAN-936 R2 section 3: a cold-start evidence card is only a
                        // real sample when *every* core read was effective. When the
                        // device could not be read (CoreReadsEffective=false) the entry
                        // must report "incomplete" and exit non-zero - never "sampled"
                        // with a green exit, which would fake a successful cold-start
                        // observation. The failed JSON snapshot is preserved verbatim.
                        var coreReadsEffective = GetMember(result, "CoreReadsEffective") as bool?;
                        if (coreReadsEffective == true)
                        {
                            sampleOutcome = "sampled";
                        }
                        else
                        {
                            sampleOutcome = "incomplete";
                            sampleError = GetMember(result, "FailureStage") as string;
                        }
                    }
                }
                catch (Exception ex)
                {
                    var inner = (ex as TargetInvocationException)?.InnerException;
                    sampleOutcome = "failed";
                    sampleError = $"{inner?.GetType().Name ?? ex.GetType().Name}: {inner?.Message ?? ex.Message}";
                }
            }
        }

        var snapshot = new
        {
            readerVersion = "FAN-936-FanHost/1",
            readOnlyNoHardwareWrite = true,
            capturedAtUtc = DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ"),
            hostInstanceId = backendHostInstanceId,
            bootIdentity = machineBootIdentity,
            factoryType = FactoryType,
            route = Route?.Kind.ToString(),
            restoreStrategy = Route?.RestoreStrategy.ToString(),
            deviceIdentity = DeviceIdentity,
            hcOpen = IsOpen,
            openAttempted,
            hcCoreInitialized,
            hcCoreWarning = HcCoreWarning,
            loadOutcome,
            loadError,
            sampleOutcome,
            sampleError,
            msiStateMatchesBootIdentity,
            msiState,
            lastRelease = ReflectPublicState(device is null ? null : GetMember(device, "LastMsiFanRelease")),
        };
        // 只有真正装配成功且完成一次只读采样才算成功；其余（failed/unsupported/null-result/异常）非零。
        var sampled = (loadOutcome == "loaded" || loadOutcome == "already-loaded") && sampleOutcome == "sampled";
        return (snapshot, sampled ? 0 : 1);
    }

    /**
     * FAN-936 R2 section 2：MSI **首次 Open 之前**的有界、只读原始块快照。
     *
     * 现有顺序 `OpenHcDevice() → CaptureOemBaseline()` 只取 profile/Shift 上下文，拿不到原始块的
     * "Open 前图像"——而 HC 的 `Open()` 会写软件控制位，之后读到的已是本进程视图。故在首次 `Open()`
     * 之前补一次只读采样（复用设备 `ReadMsiFanStateReadOnly`，绝不 Open、绝不写），记录
     * 设备/Host/session 标识与读失败（**原样记录**，失败不得补零）。它只是诊断与将来"精确恢复"的
     * 前提，**不是**其它机型启用前的新重门；只有 MSI 路线、且只对该设备**第一次** Open 捕获（重开时的
     * 读数已被本会话改写，不得覆盖原始图像）。
     */
    private void CapturePreOpenMsiOriginalBlockSnapshot()
    {
        if (Route?.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease) return;
        if (device is null) { msiPreOpenOriginalDetail = "no-device"; return; }
        if (msiPreOpenOriginalCaptured && ReferenceEquals(msiPreOpenOriginalDeviceReference, device)) return;
        var sampler = device.GetType()
            .GetMethods(BindingFlags.Public | BindingFlags.Instance)
            .FirstOrDefault(m => m.Name == "ReadMsiFanStateReadOnly" && m.GetParameters().Length == 0);
        msiPreOpenOriginalDeviceReference = device;
        if (sampler is null)
        {
            msiPreOpenOriginalRawSnapshot = null;
            msiPreOpenOriginalReadEffective = false;
            msiPreOpenOriginalDetail = "unsupported:no-readonly-sampler";
            msiPreOpenOriginalCaptured = true;
            EmitPreOpenMsiOriginalBlockEvidence();
            return;
        }
        try
        {
            var result = sampler.Invoke(device, null);
            if (result is null)
            {
                msiPreOpenOriginalRawSnapshot = null;
                msiPreOpenOriginalReadEffective = false;
                msiPreOpenOriginalDetail = "null-result";
            }
            else
            {
                msiPreOpenOriginalRawSnapshot = ReflectPublicState(result);
                msiPreOpenOriginalReadEffective = GetMember(result, "CoreReadsEffective") as bool? == true;
                msiPreOpenOriginalDetail = msiPreOpenOriginalReadEffective
                    ? "captured"
                    : $"incomplete:{GetMember(result, "FailureStage") as string}";
            }
        }
        catch (Exception ex)
        {
            var inner = (ex as TargetInvocationException)?.InnerException;
            msiPreOpenOriginalRawSnapshot = null;
            msiPreOpenOriginalReadEffective = false;
            msiPreOpenOriginalDetail =
                $"failed:{inner?.GetType().Name ?? ex.GetType().Name}: {inner?.Message ?? ex.Message}";
        }
        msiPreOpenOriginalCaptured = true;
        EmitPreOpenMsiOriginalBlockEvidence();
    }

    /**
     * FAN-936 R2 section 2：把 Open 前原始块快照（设备/Host/session 标识 + 读失败）落到诊断事件，
     * 一次性、只读、不改变任何判定。门关闭时也可由故障账本读取（与其它取证事件同款）。
     */
    private void EmitPreOpenMsiOriginalBlockEvidence()
    {
        try
        {
            Diagnostic?.Invoke("host.msi-preopen-original-blocks", new
            {
                phase = "open.pre-baseline-readonly",
                source = "FanHost.CapturePreOpenMsiOriginalBlockSnapshot",
                deviceType = FactoryType,
                hostInstanceId = backendHostInstanceId,
                bootIdentity = machineBootIdentity,
                controlCycleId = ControlCycleId,
                readEffective = msiPreOpenOriginalReadEffective,
                detail = msiPreOpenOriginalDetail,
                snapshot = msiPreOpenOriginalRawSnapshot,
            });
        }
        catch
        {
            // 取证不得影响 Open 生命周期；事件写失败不改任何判定。
        }
    }

    /** 仅自测：读 Open 前原始块快照的捕获状态（生产路径不调用）。 */
    internal object PreOpenMsiOriginalBlockEvidenceForSelfTest => new
    {
        captured = msiPreOpenOriginalCaptured,
        deviceBound = msiPreOpenOriginalDeviceReference is not null &&
            ReferenceEquals(msiPreOpenOriginalDeviceReference, device),
        readEffective = msiPreOpenOriginalReadEffective,
        detail = msiPreOpenOriginalDetail,
        snapshot = msiPreOpenOriginalRawSnapshot,
    };

    /** 仅自测：走一次 Open 前原始块只读捕获（生产路径由 `OpenCore` 调用）。 */
    internal void CapturePreOpenMsiOriginalBlockSnapshotForSelfTest() => CapturePreOpenMsiOriginalBlockSnapshot();

    internal static (HardwareVersionEvidence? Ec, HardwareVersionEvidence? ControllerFirmware) DescribeVersionEvidenceForSelfTest(string? factoryType)
        => DescribeVersionEvidence(factoryType);

    private static (HardwareVersionEvidence? Ec, HardwareVersionEvidence? ControllerFirmware) DescribeVersionEvidence(string? factoryType)
    {
        var className = factoryType is null ? string.Empty : factoryType[(factoryType.LastIndexOf('.') + 1)..];
        if (className.StartsWith("OneXPlayerX1", StringComparison.Ordinal))
        {
            return (
                new HardwareVersionEvidence(
                    "not-attempted",
                    "ec-revision",
                    "HC",
                    "OneXPlayerX1.CheckIsBatteryProtectionSupported -> Win32_BIOS.EmbeddedControllerMajorVersion/EmbeddedControllerMinorVersion",
                    null,
                    null,
                    null,
                    false,
                    true,
                    "HC 明确提供该 WMI 字段；握手阶段不调用它，需设备路线明确授权后再读取"),
                null);
        }

        if (className.Equals("GPDWin5", StringComparison.Ordinal))
        {
            return (
                new HardwareVersionEvidence(
                    "unsupported",
                    "ec-revision",
                    "HC",
                    null,
                    null,
                    null,
                    null,
                    false,
                    true,
                    "HC GPDWin5 源码只证明 HID 控制器固件读取，不提供 EC revision 读取"),
                new HardwareVersionEvidence(
                    "not-attempted",
                    "controller-firmware",
                    "HC",
                    "GPDWin5.Open -> ReadControllerFirmwareVersion(HID report 0x41)",
                    null,
                    null,
                    null,
                    false,
                    true,
                    "HC 在 Open() 中读取控制器固件；握手阶段不执行 HID 读取"));
        }

        return (
            new HardwareVersionEvidence(
                "unsupported",
                "ec-revision",
                null,
                null,
                null,
                null,
                null,
                false,
                true,
                "HC 当前路线未提供通用 EC revision 读取契约；设备专用 EC 地址仅用于风扇/电源操作"),
            null);
    }

    public void Open() => OnStaBounded(OpenCore);

    private void OpenCore()
    {
        lock (hardwareGate)
        {
            // Use the actual HC virtual Open() implementation.  Some devices
            // establish fan prerequisites in their override, so a hand-built
            // OpenLib/ACPI subset is not an equivalent lifecycle.
            EnsureRealWriteAuthorization();
            openAttempted = true;
            hcOpenInvocationStarted = false;
            if (!IsOpen)
            {
                // A successful Open starts a new HC device session. Invalidate
                // any detached Applied/Discarded snapshot before HC can emit a
                // late callback from the previous session.
                externalProfileQueue.BeginSession();
            }
            // A fresh HC Open() starts a new device session. Never carry the
            // prior session's OEM proof into a new Open/Close transaction;
            // CaptureOemBaseline() will establish fresh route context after
            // Open succeeds.
            oemRestoreVerified = false;
            oemRestoreEvidence = "none";
            oemReleaseActionKind = "not-attempted";
            oemReleaseActionEvidence = "none";
            oemOwnershipStatus = "unknown-no-hc-contract";
            hcOemReleaseCallbackCompleted = false;
            asusOemReadbackConfirmed = false;
            HcVirtualCloseReturned = false;
            ResetManagerLifecycle();
            oemBaselineCaptured = false;
            try
            {
                // Fan-only ownership deliberately does not start the full HC
                // DeviceManager. The real virtual device Open/OpenEvents pair
                // remains the only HC device lifecycle entered by this Host;
                // an already-active external DeviceManager is rejected by the
                // isolation gate before OpenEvents.
                SetHcPhase("open.ready-wait");
                WaitForHcDeviceReadyBeforeOpen();
                // FAN-936 R2 section 2: observe the MSI original raw blocks before
                // the first Open() writes the software control latch. Bounded,
                // read-only, MSI-only; never gates other routes.
                SetHcPhase("open.pre-baseline-readonly");
                CapturePreOpenMsiOriginalBlockSnapshot();
                SetHcPhase("open.hc-device");
                OpenHcDevice();
                SetHcPhase("open.capture-baseline");
                CaptureOemBaseline();
                SetHcPhase(null);
                sessionDeviceReference = device;
                sessionRouteMarker = BuildSessionRouteMarker();
                closed = false;
            }
            catch
            {
                // E-2（2026-09-24）：Open 失败不得把 Open 期间的相位泄漏给后续操作。
                SetHcPhase(null);
                // Never manufacture a Close() call for a failed HC Open().
                // Some HC device overrides can emit their OEM release command
                // without an IsOpen guard, so only a successfully opened HC
                // session may follow HC's virtual Close() path.
                // A failed HC Open() is not an active fan session. HC's
                // MainWindow simply stops before OpenEvents when Open() is
                // false. Only a device that is still open after the
                // exception may enter the normal virtual Close/release path.
                var closeCompleted = false;
                if (HcCloseIsOwed)
                {
                    try
                    {
                        CloseHcDevice();
                        closeCompleted = true;
                    }
                    catch (Exception ex) { HcCoreWarning = $"HC Open cleanup failed: {ex.Message}"; }
                }
                if (closeCompleted)
                {
                    IsOpen = false;
                    openAttempted = false;
                    hcOpenInvocationStarted = false;
                    sessionDeviceReference = null;
                    sessionRouteMarker = null;
                }
                else if (!hcOpenInvocationStarted)
                {
                    // No route override was entered (for example, the
                    // readiness wait failed before Open()). No HC resource
                    // ownership was crossed, so this is the only path that
                    // may clear the attempt marker.
                    ResetManagerLifecycle();
                    hcDeviceManagerLifecycle = ManagerFactoryNotStarted;
                    openAttempted = false;
                }
                IsOpen = false;
                oemBaselineCaptured = false;
                throw;
            }
        }
    }

    private void ResetManagerLifecycle()
    {
        hcManagerFactoryLifecycle = ManagerFactoryUnknown;
        managerFactoryObserved = false;
        hcDeviceManagerLifecycle = ManagerFactoryUnknown;
        HcDeviceManagerStopCompleted = false;
        managerStatusSnapshot.Clear();
    }

    /**
     * Observe the ManagerFactory graph after HC's real OpenEvents call. This
     * deliberately reads status only; it never invokes a manager Start/Stop
     * method. A missing graph, unreadable status, or faulted manager is kept
     * as Faulted so Close cannot manufacture a no-cleanup result.
     */
    private void ObserveManagerFactoryLifecycle()
    {
        var observed = new Dictionary<string, string>(StringComparer.Ordinal);
        try
        {
            // FAN-934 R2 §3-B：唯一自测 HC 边界（默认关闭）。开启时按边界声明的可读性
            // 给出 Started/Started（可读）或复现不可读故障（抛异常 ⇒ 既有 catch 归 Faulted），
            // 让 Close 清理判定的「确认 / 未确认」两条路径都能被状态化驱动。
            if (hcBoundaryForSelfTest is { } selfTestManagerBoundary)
            {
                if (!selfTestManagerBoundary.ManagerObservationAvailable)
                    throw new MissingMemberException("HandheldCompanion.Managers.ManagerFactory (selftest-isolated)");
                managerFactoryObserved = true;
                hcManagerFactoryLifecycle = ManagerFactoryStarted;
                hcDeviceManagerLifecycle = ManagerFactoryStarted;
                HcDeviceManagerStopCompleted = false;
                observed["DeviceManager"] = "Started";
                managerStatusSnapshot.Clear();
                foreach (var pair in observed)
                    managerStatusSnapshot[pair.Key] = pair.Value;
                managerStatusSnapshot["managerFactory.observation"] = "selftest-isolated";
                Diagnostic?.Invoke("hc.manager-factory.observed", new
                {
                    lifecycle = hcManagerFactoryLifecycle,
                    deviceManagerLifecycle = hcDeviceManagerLifecycle,
                    statuses = observed,
                });
                return;
            }
            var factory = FindType("HandheldCompanion.Managers.ManagerFactory")
                ?? throw new MissingMemberException("HandheldCompanion.Managers.ManagerFactory");
            managerFactoryObserved = true;
            var managers = GetStaticMember(factory, "Managers") as System.Collections.IEnumerable
                ?? throw new MissingMemberException(factory.FullName, "Managers");
            var hasManagers = false;
            var hasActiveManager = false;
            var hasFaultedManager = false;
            string? deviceManagerStatus = null;
            foreach (var manager in managers)
            {
                if (manager is null) continue;
                hasManagers = true;
                var managerName = manager.GetType().Name;
                var statusValue = GetMember(manager, "Status")
                    ?? throw new MissingMemberException(manager.GetType().FullName, "Status");
                var status = Convert.ToString(statusValue) ?? throw new InvalidOperationException(
                    $"HC manager {managerName} returned a null Status");
                var snapshotKey = managerName;
                var duplicate = 1;
                while (observed.ContainsKey(snapshotKey))
                    snapshotKey = $"{managerName}#{duplicate++}";
                observed[snapshotKey] = status;
                if (managerName.Contains("DeviceManager", StringComparison.OrdinalIgnoreCase))
                    deviceManagerStatus = status;
                hasActiveManager |= IsActiveManagerStatus(status);
                hasFaultedManager |= IsFaultedManagerStatus(status);
            }
            if (!hasManagers || deviceManagerStatus is null)
                throw new InvalidOperationException("HC ManagerFactory graph did not expose DeviceManager status");

            hcManagerFactoryLifecycle = hasFaultedManager
                ? ManagerFactoryFaulted
                : hasActiveManager ? ManagerFactoryActive : ManagerFactoryStarted;
            hcDeviceManagerLifecycle = IsFaultedManagerStatus(deviceManagerStatus)
                ? ManagerFactoryFaulted
                : IsActiveManagerStatus(deviceManagerStatus) ? ManagerFactoryActive : ManagerFactoryStarted;
            HcDeviceManagerStopCompleted = false;
            managerStatusSnapshot.Clear();
            foreach (var pair in observed)
                managerStatusSnapshot[pair.Key] = pair.Value;
            managerStatusSnapshot["managerFactory.observation"] = "OpenEvents-post-observation";
            Diagnostic?.Invoke("hc.manager-factory.observed", new
            {
                lifecycle = hcManagerFactoryLifecycle,
                deviceManagerLifecycle = hcDeviceManagerLifecycle,
                statuses = observed,
            });
            if (hcManagerFactoryLifecycle == ManagerFactoryFaulted)
                throw new InvalidOperationException("HC_MANAGER_FACTORY_FAULTED: ManagerFactory status reported a fault");
        }
        catch (Exception ex)
        {
            hcManagerFactoryLifecycle = ManagerFactoryFaulted;
            hcDeviceManagerLifecycle = ManagerFactoryFaulted;
            HcDeviceManagerStopCompleted = false;
            managerStatusSnapshot.Clear();
            foreach (var pair in observed)
                managerStatusSnapshot[pair.Key] = pair.Value;
            managerStatusSnapshot["managerFactory.observation"] = "faulted";
            managerStatusSnapshot["managerFactory.error"] = DescribeException(ex);
            HcCoreWarning = $"HC ManagerFactory 状态观测失败: {ex.Message}";
            Diagnostic?.Invoke("hc.manager-factory.observation-failure", new { error = DescribeException(ex) });
            throw new InvalidOperationException("HC_MANAGER_FACTORY_LIFECYCLE_UNKNOWN: 无法确认 HC ManagerFactory 清理边界", ex);
        }
    }

    private static bool IsActiveManagerStatus(string status) =>
        status.Equals("Initializing", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Initialized", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Starting", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Started", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Running", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Active", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Busy", StringComparison.OrdinalIgnoreCase);

    private static bool IsFaultedManagerStatus(string status) =>
        status.Contains("Fault", StringComparison.OrdinalIgnoreCase) ||
        status.Contains("Fail", StringComparison.OrdinalIgnoreCase) ||
        status.Contains("Error", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Halting", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Halted", StringComparison.OrdinalIgnoreCase) ||
        status.Equals("Stopping", StringComparison.OrdinalIgnoreCase);

    /**
     * 920-v1.4 §16.2：把「短 STA 调用」与「异步等待」分离。
     *
     * 逻辑操作归属由 **engine 的 lock(gate)** 全程持有（FanHostEngine.OpenEvents 包裹本次调用），
     * 不靠 `activeStaWorkItem` 是否为空来代表操作结束；两个短 STA 阶段各自只在需要时持
     * `hardwareGate`。等待发生在不会占住 STA 派发器的调用方线程上，因此被等待的
     * `Device_Inserted` 续体可以恢复执行（这是本修复的目的）。
     */
    /**
     * 920-v1.4 §16.2（§17.1-2 已更正措辞）：把「短 STA 调用」与「异步等待」分离。
     *
     * **更正**：早期叙述"等待期间不持有任何 Monitor"**不成立** —— `hardwareGate` 已分段释放，
     * 但 `FanHostEngine.OpenEvents` 的 `lock(gate)` **仍包住整个三阶段调用**。该事实本身不等于
     * 死锁，但必须另行验证状态查询/睡眠通知/Close/恢复预算/回调重入的进展（见 §17.1-2）。
     * 等待发生在不会占住 STA 派发器的调用方线程上，因此被等待的 `Device_Inserted` 续体可以恢复执行。
     */
    public void OpenEvents()
    {
        Interlocked.Increment(ref hcDeviceOpenInFlight);
        try
        {
            var need = OnStaBounded(OpenEventsBeginCore, "open-events-begin");
            if (need == HcDeviceOpenNeed.WaitForDeviceInserted)
            {
                // §17.4-A：走**生产协调骨架**（自测走同一实现）。
                var adapter = new ReflectiveHcDeviceOpenAdapter(this);
                var operation = new HcDeviceOpenOperation("open-events", externalProfileQueue.CurrentGeneration);
                LastDeviceOpenOperation = operation;
                var phase = CoordinateHcDeviceOpen(adapter, HcDeviceOpenTimeoutMs, operation, Diagnostic);
                if (phase == HcDeviceOpenPhase.TimedOut)
                    throw new InvalidOperationException(
                        "HC_ROG_DEVICE_INSERT_TIMEOUT: HC Device_Inserted(true) 未在 10 秒内打开 HID，拒绝启用；" +
                        "注意：超时仅表示调用方等待结束，**不等于** HC 续体已取消或已结束");
                if (phase == HcDeviceOpenPhase.LifecycleRejected)
                    // §18.2-A：候选 HC 给出了真实完成终态（部分副作用/异常/会话失效）⇒ 必须失败，不得当成打开成功。
                    throw new InvalidOperationException(
                        $"HC_DEVICE_OPEN_REJECTED: {operation.Describe()}");
            }
            OnStaBounded(OpenEventsFinalizeCore, "open-events-finalize");
        }
        finally
        {
            Interlocked.Decrement(ref hcDeviceOpenInFlight);
        }
    }

    /** §17.4-A：最近一次设备打开操作的记录（只诊断/只断言，**不承担授权**）。 */
    internal HcDeviceOpenOperation? LastDeviceOpenOperation { get; private set; }

    /**
     * §16.2 / §17.1-1：这是一个**诊断计数器**，不是已实现的隔离/授权协议。
     *
     * >0 只表示"本进程此刻在 `OpenEvents` 的调用里"；它**不代表** HC 的 `async void`
     * `Device_Inserted` 已完成（`finally` 在调用方超时后即减零，而旧续体仍可能执行），
     * 也**不撤销**旧续体的后续写入资格。任何授权/隔离判定**不得**依赖本字段。
     */
    private int hcDeviceOpenInFlight;
    internal bool HcDeviceOpenInFlight => Volatile.Read(ref hcDeviceOpenInFlight) > 0;

    /**
     * §16.2/§16.5-2：可达的**遗弃设备打开**检测（只诊断，不改变行为，也不授权）。
     * 条件：没有在途调用、没有会话在册，而设备却是打开的 —— 最可能来自被放弃的
     * `Device_Inserted` 续体（本判据不能排除其它路径）。此处只记录诊断事件，
     * 不反射 HC 私有方法、不强设 IsOpen、不据此改变任何行为。
     */
    internal bool DetectAbandonedDeviceOpen(string source)
    {
        if (HcDeviceOpenInFlight || hcOpenEventsInvoked) return false;
        if (!HcDeviceIsOpen(device)) return false;
        Diagnostic?.Invoke("hc-abandoned-device-open.detected", new { source });
        return true;
    }

    /** 自测专用：把上面的判据暴露给探针，避免另写一份同形判定。 */
    internal bool DetectAbandonedDeviceOpenForSelfTest(object targetDevice, bool openEventsInvoked, bool inFlight)
    {
        if (inFlight || openEventsInvoked) return false;
        return HcDeviceIsOpen(targetDevice);
    }

    private enum HcDeviceOpenNeed { None, WaitForDeviceInserted }

    private HcDeviceOpenNeed OpenEventsBeginCore()
    {
        lock (hardwareGate)
        {
            // HC's ROG Open() can return successfully while the virtual device's
            // IsOpen marker is still false. That marker is established by the
            // OpenEvents/Device_Inserted(true) lifecycle boundary below, so the
            // full post-open control gate would reject the very call that must
            // make the HC device ready.
            EnsureRealWriteAuthorization();
            if (!IsOpen) throw new FanApiException(409, "HOST_NOT_OPEN", "HC 尚未 Open");
            try
            {
                EnsureHcSessionReadyForOpenEvents();
            }
            catch (InvalidOperationException ex) when (ex.Message.StartsWith("HC_SESSION_ROUTE_LOST:", StringComparison.Ordinal))
            {
                throw new FanApiException(409, "HC_SESSION_ROUTE_LOST", "HC 风扇设备/路线标记已丢失，已拒绝写入");
            }
            if (hcOpenEventsInvoked)
                return HcDeviceOpenNeed.None;
            if (!oemBaselineCaptured)
                throw new InvalidOperationException("FAN_ROUTE_RESTORE_UNAVAILABLE: Open 未完成 OEM 基线读取");
            // Execute the exact virtual device method. The Host must not pre-read
            // ManagerFactory fields as an invented admission test: doing so runs
            // HC's whole static application graph before this native lifecycle
            // boundary. Device-specific OpenEvents behavior remains owned by HC.
            Invoke(device!, "OpenEvents");
            return BeginHcDeviceOpenForRestore();
        }
    }

    private void OpenEventsFinalizeCore()
    {
        lock (hardwareGate)
        {
            if (hcOpenEventsInvoked) return;
            ObserveManagerFactoryLifecycle();
            SubscribeExternalProfileEvents(externalProfileQueue.CurrentGeneration);
            hcOpenEventsInvoked = true;
            // P-3（2026-09-23 立案）：新 HC 会话开始——同一会话内的 loop stop/reopen 记账归零。
            hcLoopStopSessionId++;
            hcLoopStopSessionStartedTick = Environment.TickCount64;
            hcLoopStopSessionAttempts = 0;
            hcLoopStopSessionStops = 0;
            hcLoopStopLastStopTick = 0;
            // F1' (2026-09-17): the fan path only needs HC's device + power-profile
            // managers. HC's controller-side tight loops (device HID read loop, SDL
            // hotplug pump) have no fan function and spin once HidHide takes the
            // built-in controller away; stop their flags as soon as the open
            // boundary is complete (the runtime diagnostics timer re-asserts this,
            // because a later device event can start a fresh read loop).
            StopHcControllerCpuLoops("open-events");
        }
    }

    private void SubscribeExternalProfileEvents(long sessionGeneration)
    {
        if (subscribedPowerProfileManager is not null) return;
        var factory = FindType("HandheldCompanion.Managers.ManagerFactory")
            ?? throw new MissingMemberException("HandheldCompanion.Managers.ManagerFactory");
        var manager = GetStaticMember(factory, "powerProfileManager")
            ?? throw new InvalidOperationException("HC_MANAGER_FACTORY_PROFILE_UNAVAILABLE: PowerProfileManager 未构造");
        var appliedAttached = false;
        var discardedAttached = false;
        try
        {
            var applied = manager.GetType().GetEvent("Applied", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            var discarded = manager.GetType().GetEvent("Discarded", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            if (applied?.EventHandlerType is null || discarded?.EventHandlerType is null)
                throw new MissingMemberException(manager.GetType().FullName, "Applied/Discarded");
            externalProfileAppliedHandler = BuildProfileEventDelegate(
                applied.EventHandlerType,
                nameof(OnExternalProfileAppliedForSession),
                sessionGeneration);
            externalProfileDiscardedHandler = BuildProfileEventDelegate(
                discarded.EventHandlerType,
                nameof(OnExternalProfileDiscardedForSession),
                sessionGeneration);
            // Activate before AddEventHandler: HC may publish its current
            // Applied snapshot synchronously while a subscription is added.
            if (!externalProfileQueue.ActivateSession(sessionGeneration))
                throw new InvalidOperationException("HC_PROFILE_EVENTS_SESSION_INVALID: OpenEvents 会话已失效");
            applied.AddEventHandler(manager, externalProfileAppliedHandler);
            appliedAttached = true;
            discarded.AddEventHandler(manager, externalProfileDiscardedHandler);
            discardedAttached = true;
            subscribedPowerProfileManager = manager;
            Diagnostic?.Invoke("hc.external-profile-events-subscribed", new { manager = manager.GetType().FullName });
        }
        catch (Exception ex)
        {
            // AddEventHandler is not transactional. If Applied succeeds but
            // Discarded fails, remove the first handler before dropping the
            // generation; otherwise a later Open/Resume would retain a hidden
            // stale delegate (generation rejection alone does not release the
            // HC event subscription).
            try
            {
                var applied = manager.GetType().GetEvent("Applied", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                var discarded = manager.GetType().GetEvent("Discarded", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                if (appliedAttached && applied is not null && externalProfileAppliedHandler is not null)
                    applied.RemoveEventHandler(manager, externalProfileAppliedHandler);
                if (discardedAttached && discarded is not null && externalProfileDiscardedHandler is not null)
                    discarded.RemoveEventHandler(manager, externalProfileDiscardedHandler);
            }
            catch (Exception cleanupError)
            {
                Diagnostic?.Invoke("hc.external-profile-events-subscribe-cleanup-failure", new { error = DescribeException(cleanupError) });
            }
            externalProfileQueue.InvalidateSession();
            subscribedPowerProfileManager = null;
            externalProfileAppliedHandler = null;
            externalProfileDiscardedHandler = null;
            Diagnostic?.Invoke("hc.external-profile-events-subscribe-failure", new { error = DescribeException(ex) });
            throw new InvalidOperationException("HC_PROFILE_EVENTS_SUBSCRIBE_FAILED: 无法确认 PowerProfileManager 事件订阅", ex);
        }
    }

    private Delegate BuildProfileEventDelegate(Type handlerType, string methodName, long sessionGeneration)
    {
        var invoke = handlerType.GetMethod("Invoke")
            ?? throw new MissingMethodException(handlerType.FullName, "Invoke");
        var parameters = invoke.GetParameters()
            .Select(parameter => Expression.Parameter(parameter.ParameterType, parameter.Name))
            .ToArray();
        var target = typeof(RealHcBackend).GetMethod(methodName, BindingFlags.Instance | BindingFlags.NonPublic)
            ?? throw new MissingMethodException(typeof(RealHcBackend).FullName, methodName);
        var arguments = parameters.Select(parameter => Expression.Convert(parameter, typeof(object))).ToArray();
        var callArguments = new Expression[] { Expression.Constant(sessionGeneration) }
            .Concat(arguments)
            .ToArray();
        var body = Expression.Call(Expression.Constant(this), target, callArguments);
        return Expression.Lambda(handlerType, body, parameters).Compile();
    }

    private void OnExternalProfileAppliedForSession(long sessionGeneration, object? profile, object? source)
    {
        var sourceName = Convert.ToString(source) ?? "Background";
        if (!externalProfileQueue.TryAcceptApplied(
                sessionGeneration,
                profile,
                sourceName,
                out var snapshot,
                out var reason))
        {
            Diagnostic?.Invoke("hc.external-profile-applied-ignored", new
            {
                source = sourceName,
                sessionGeneration,
                reason,
            });
            return;
        }
        lastExternalProfileSource = sourceName;
        Diagnostic?.Invoke("hc.external-profile-applied", new { source = sourceName });
        // HC raises Applied synchronously while holding its profile lock.
        // Do not re-enter HC or acquire hardwareGate from this callback;
        // request the serialized observer only after the snapshot is complete.
        Diagnostic?.Invoke("hc.external-profile-snapshot-queued", new
        {
            source = sourceName,
            sessionGeneration,
            eventSequence = snapshot?.Sequence,
            retryLimit = ExternalProfilePendingQueue.MaxRetryAttempts,
        });
        RequestPowerProfileWatchdogTick();
    }

    private void OnExternalProfileDiscardedForSession(long sessionGeneration, object? profile, object? swapped)
    {
        var swappedName = Convert.ToString(swapped);
        if (!externalProfileQueue.TryAcceptDiscarded(
                sessionGeneration,
                DateTimeOffset.UtcNow,
                out var reason))
        {
            Diagnostic?.Invoke("hc.external-profile-discarded-ignored", new
            {
                swapped = swappedName,
                sessionGeneration,
                reason,
            });
            return;
        }
        lastExternalProfileSource = "Discarded";
        Diagnostic?.Invoke("hc.external-profile-discarded", new { swapped = swappedName });
        // HC's own Discarded handler intentionally does not apply a
        // replacement profile: the following Applied event owns that
        // transition. Wake the serialized observer only to record the
        // boundary; it must not write a fallback profile in this window.
        RequestPowerProfileWatchdogTick();
    }

    private void RequestPowerProfileWatchdogTick(int delayMs = 0)
    {
        if (powerProfileWatchdog is null) return;
        try
        {
            // FAN-929：一次性武装（不再把 1 s 周期加回去）。事件驱动：外部 profile
            // Applied/Discarded 到达时只跑这一趟；稳态不再有任何 tick。
            // FAN-931 P1.5：需要"有界延迟复核"时按需再多武装**一次**（delayMs > 0）——
            // 这两类边沿各自有有限次数上限，绝不是常驻轮询。
            powerProfileWatchdog.Change(Math.Max(0, delayMs), Timeout.Infinite);
        }
        catch (ObjectDisposedException)
        {
            // Close/stop can race an event callback; the close gate remains
            // authoritative and no callback is allowed to touch hardware.
        }
    }

    /**
     * FAN-931 P1.5：为"有界延迟复核"补上有消费者的最后一次武装。
     * 只在确有边沿时排一拍；无 pending、无 discard 截止点 ⇒ 0 tick。
     */
    private void ArmBoundedProfileWatchdogFollowUp()
    {
        // 截止点复核只在"本拍刚消费到丢弃边界"时排一次（见 TickCore 的重置与赋值）；
        // 否则这条边沿的消费者可能永远排不出去，或者反过来变成无限 2 s 轮询。
        if (profileWatchdogDiscardBoundaryConsumed)
        {
            var now = DateTimeOffset.UtcNow;
            var deadlineRemaining = externalProfileQueue.DiscardedAppliedDeadlineRemainingMs(
                now, TimeSpan.FromMilliseconds(ExternalProfileDiscardedAppliedTimeoutMs));
            if (deadlineRemaining >= 0)
            {
                RequestPowerProfileWatchdogTick(deadlineRemaining + ProfileWatchdogArmMarginMs);
                return;
            }
        }
        // 无 discard 截止点时才考虑重试拍（两者不叠加，仍是一次性）。
        if (externalProfileQueue.HasRetryPending())
            RequestPowerProfileWatchdogTick(ExternalProfileRetryDelayMs);
    }

    private void UnsubscribeExternalProfileEvents()
    {
        // Invalidate before removing handlers. HC may already have queued a
        // callback on its profile lock; the generation check must reject it
        // even while CurrentDevice.Close() is still unwinding.
        externalProfileQueue.InvalidateSession();
        var manager = subscribedPowerProfileManager;
        if (manager is null)
        {
            externalProfileAppliedHandler = null;
            externalProfileDiscardedHandler = null;
            return;
        }
        try
        {
            var applied = manager.GetType().GetEvent("Applied", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            var discarded = manager.GetType().GetEvent("Discarded", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            if (applied is not null && externalProfileAppliedHandler is not null)
                applied.RemoveEventHandler(manager, externalProfileAppliedHandler);
            if (discarded is not null && externalProfileDiscardedHandler is not null)
                discarded.RemoveEventHandler(manager, externalProfileDiscardedHandler);
        }
        catch (Exception ex)
        {
            Diagnostic?.Invoke("hc.external-profile-events-unsubscribe-failure", new { error = DescribeException(ex) });
        }
        subscribedPowerProfileManager = null;
        externalProfileAppliedHandler = null;
        externalProfileDiscardedHandler = null;
    }

    /**
     * 920-v1.4 §16.1/§16.4：设备是否已打开 —— 生产的**唯一**判据实现。
     *
     * 必须用实际类型的重写，而不是基类：`ROGAlly.cs` L40
     *   `public override bool IsOpen => hidDevices.ContainsKey(INPUT_HID_ID)
     *        && hidDevices[INPUT_HID_ID].IsOpen && base.IsOpen;`
     * 而基类 `ASUS.cs` L7 是 `DeviceOpen && AsusACPI.IsOpen`。
     * 因此 **`Open()` 成功、ACPI 打开，并不等于输入 HID 已打开**，也不等于 ROG 的
     * `IsOpen` 为真 —— 这正是本 helper 需要派发 `Device_Inserted(true)` 的原因。
     * `GetMember` 从 `target.GetType()` 向基类逐层按 `DeclaredOnly` 查询，故天然取到重写。
     */
    internal static bool HcDeviceIsOpen(object? device) =>
        device is not null && GetMember(device, "IsOpen") is bool isOpen && isOpen;

    /**
     * 920-v1.4 §16.2：设备打开的**有界等待**（生产唯一实现）。
     *
     * 关键约束：**必须在不会占住 STA 派发器的线程上调用**。`Device_Inserted` 的续体
     * 恢复在被捕获的 `DispatcherSynchronizationContext` 上，若调用方占住该派发器，
     * 等待的就是被自己挡住的工作（自阻塞）。自测以保真替身调用**同一实现**，不另写同形循环。
     */
    internal static bool WaitForHcDeviceOpenBounded(
        object? device,
        int timeoutMs,
        string source,
        Action<string, object>? diagnose = null)
    {
        var deadline = Environment.TickCount64 + timeoutMs;
        var polls = 0;
        while (Environment.TickCount64 < deadline)
        {
            if (HcDeviceIsOpen(device))
            {
                diagnose?.Invoke("hc-device-open-confirmed", new { source, polls });
                return true;
            }
            polls++;
            Thread.Sleep(100);
        }
        var confirmed = HcDeviceIsOpen(device);
        diagnose?.Invoke("hc-device-open-wait-finished", new { source, polls, confirmed, timedOut = !confirmed });
        return confirmed;
    }

    private const int HcDeviceOpenTimeoutMs = 10_000;

    /**
     * 920-v1.5 §17.4-A：**窄设备适配接口**。
     * 生产协调骨架只依赖本接口；生产实现经反射调 HC 设备，自测实现注入可控硬件行为。
     * ⇒ 自测执行的是**生产协调骨架本身**，不是同形副本。
     */
    internal interface IHcDeviceOpenAdapter
    {
        bool IsDeviceOpen();
        /** 派发 HC 的设备插入（`async void`）：返回**不代表**其续体已完成。 */
        void DispatchDeviceInserted();
        /**
         * 920-v1.6 §18.2-A：候选 HC 若提供版本化生命周期接口，用**真实操作完成**替代
         * “观测到 IsOpen”。返回 false = 该运行时**不支持**新能力（不得悄悄回到 async void 并声称满足新合同）。
         * `outcome` 取值：Completed / AlreadyOpen / PartiallyApplied / Faulted / AbortedBySession / CancelledBeforeSideEffect。
         */
        bool TryWaitLifecycleCompletion(int timeoutMs, out string outcome, out string detail);
    }

    /** §17.4-A：操作阶段 —— 区分派发、真实完成、取消请求、已停止/隔离。 */
    internal enum HcDeviceOpenPhase
    {
        NotApplicable,
        AlreadyOpen,
        Dispatched,
        Completed,
        TimedOut,
        CancellationRequested,
        /**
         * §18.2-A：候选 HC 给出了**真实完成**，但终态是拒绝/部分/异常
         * （PartiallyApplied / Faulted / AbortedBySession）。调用方必须当作失败处理。
         */
        LifecycleRejected,
    }

    /**
     * §17.4-A：操作记录。**不做授权**，只做可断言的事实记录 —— 单纯计数器不得承担授权。
     * 明确标注：`Completed` 表示**观测到设备已打开**（本批唯一可用的真实完成判据）；
     * HC 的 `async void` 不向调用者返回完成，Host 也不能凭本记录宣称其续体已结束。
     */
    internal sealed class HcDeviceOpenOperation
    {
        public HcDeviceOpenOperation(string operationId, long sessionGeneration)
        {
            OperationId = operationId;
            SessionGeneration = sessionGeneration;
            StartedMonoMs = Environment.TickCount64;
        }

        public string OperationId { get; }
        public long SessionGeneration { get; }
        public long StartedMonoMs { get; }
        public HcDeviceOpenPhase Phase { get; private set; } = HcDeviceOpenPhase.NotApplicable;
        public long? DispatchedMonoMs { get; private set; }
        public long? CompletedMonoMs { get; private set; }
        public int Polls { get; private set; }
        public bool CancellationRequested { get; private set; }
        /** 观测到设备在**本操作已返回之后**才变开 —— 迟到副作用的直接证据。 */
        public long? ObservedOpenAfterReturnMonoMs { get; set; }
        /** §18.2-A：候选 HC 生命周期接口给出的真实完成终态（未提供该能力时为空）。 */
        public string? LifecycleOutcome { get; private set; }
        public string? LifecycleDetail { get; private set; }
        public long? LifecycleElapsedMs { get; private set; }
        public bool LifecycleApiUsed { get; private set; }

        public void MarkLifecycleCompletion(string outcome, string detail, long elapsedMs)
        {
            LifecycleApiUsed = true;
            LifecycleOutcome = outcome;
            LifecycleDetail = detail;
            LifecycleElapsedMs = elapsedMs;
            if (outcome is "Completed" or "AlreadyOpen")
                MarkCompleted();
        }

        public void MarkNotApplicable() => Phase = HcDeviceOpenPhase.NotApplicable;
        public void MarkAlreadyOpen() { Phase = HcDeviceOpenPhase.AlreadyOpen; CompletedMonoMs = Environment.TickCount64; }
        public void MarkDispatched() { Phase = HcDeviceOpenPhase.Dispatched; DispatchedMonoMs = Environment.TickCount64; }
        public void MarkCompleted() { Phase = HcDeviceOpenPhase.Completed; CompletedMonoMs = Environment.TickCount64; }
        public void MarkTimedOut() => Phase = HcDeviceOpenPhase.TimedOut;
        public void MarkCancellationRequested() { CancellationRequested = true; Phase = HcDeviceOpenPhase.CancellationRequested; }
        public void IncrementPolls() => Polls++;

        public string Describe() =>
            $"op={OperationId} gen={SessionGeneration} phase={Phase} polls={Polls} " +
            $"dispatchedMs={DispatchedMonoMs?.ToString() ?? "-"} completedMs={CompletedMonoMs?.ToString() ?? "-"} " +
            $"cancelRequested={CancellationRequested} openAfterReturn={ObservedOpenAfterReturnMonoMs?.ToString() ?? "-"} " +
            $"lifecycleApi={LifecycleApiUsed} lifecycleOutcome={LifecycleOutcome ?? "-"} " +
            $"lifecycleElapsedMs={LifecycleElapsedMs?.ToString() ?? "-"} lifecycleDetail={LifecycleDetail ?? "-"}";
    }

    /**
     * §17.4-A：**生产协调骨架**（唯一实现）。生产与自测都走这里。
     *
     * 约束（§17.2/§17.3）：等待**必须**在不占住 STA 派发器的线程上；不跨 await 持锁；
     * 不新增超时包装来宣称取消；`TimedOut` 只表示**调用方等待结束**，**不等于**硬件工作已取消
     * 或 HC 续体已结束。
     */
    internal static HcDeviceOpenPhase CoordinateHcDeviceOpen(
        IHcDeviceOpenAdapter adapter,
        int timeoutMs,
        HcDeviceOpenOperation operation,
        Action<string, object>? diagnose = null)
    {
        if (adapter.IsDeviceOpen())
        {
            operation.MarkAlreadyOpen();
            diagnose?.Invoke("hc-device-open-confirmed", new { source = "already-open", operation = operation.OperationId });
            return HcDeviceOpenPhase.AlreadyOpen;
        }

        operation.MarkDispatched();
        adapter.DispatchDeviceInserted();
        diagnose?.Invoke("hc-device-inserted.dispatched", new { operation = operation.OperationId });

        // §18.2-A：优先消费候选 HC 的**真实完成**（版本化接口）；旧 runtime 报告不支持。
        var lifecycleStarted = Environment.TickCount64;
        if (adapter.TryWaitLifecycleCompletion(timeoutMs, out var lifecycleOutcome, out var lifecycleDetail))
        {
            var elapsed = Environment.TickCount64 - lifecycleStarted;
            operation.MarkLifecycleCompletion(lifecycleOutcome, lifecycleDetail, elapsed);
            diagnose?.Invoke("hc-device-open-lifecycle-completion", new
            {
                operation = operation.OperationId,
                outcome = lifecycleOutcome,
                detail = lifecycleDetail,
                elapsedMs = elapsed,
            });
            return lifecycleOutcome switch
            {
                "Completed" => HcDeviceOpenPhase.Completed,
                "AlreadyOpen" => HcDeviceOpenPhase.AlreadyOpen,
                "CancelledBeforeSideEffect" => HcDeviceOpenPhase.CancellationRequested,
                _ => HcDeviceOpenPhase.LifecycleRejected,
            };
        }
        diagnose?.Invoke("hc-device-open-lifecycle-unsupported", new { operation = operation.OperationId });

        var deadline = Environment.TickCount64 + timeoutMs;
        while (Environment.TickCount64 < deadline)
        {
            if (operation.CancellationRequested) return HcDeviceOpenPhase.CancellationRequested;
            if (adapter.IsDeviceOpen())
            {
                operation.MarkCompleted();
                diagnose?.Invoke("hc-device-open-confirmed", new { source = "Device_Inserted(true)", operation = operation.OperationId, polls = operation.Polls });
                return HcDeviceOpenPhase.Completed;
            }
            operation.IncrementPolls();
            Thread.Sleep(100);
        }

        operation.MarkTimedOut();
        diagnose?.Invoke("hc-device-open-unconfirmed", new { operation = operation.OperationId, polls = operation.Polls });
        return HcDeviceOpenPhase.TimedOut;
    }

    /** 生产适配器：经反射调 HC 设备（派发仍走短 STA 跳，保持既有调用次序）。 */
    private sealed class ReflectiveHcDeviceOpenAdapter(RealHcBackend backend) : IHcDeviceOpenAdapter
    {
        public bool IsDeviceOpen() => HcDeviceIsOpen(backend.device);

        public void DispatchDeviceInserted() =>
            backend.OnStaBounded(() => { InvokeHcDeviceInserted(backend.device!); return true; }, "device-inserted-dispatch");

        public bool TryWaitLifecycleCompletion(int timeoutMs, out string outcome, out string detail) =>
            backend.TryWaitCandidateLifecycleCompletion(backend.device, timeoutMs, out outcome, out detail);
    }

    /** 自测适配器：把替身接到**生产协调骨架**上（派发仍走真实 STA 跳，与生产同路径）。 */
    private sealed class ProbeHcDeviceOpenAdapter(RealHcBackend backend, AsyncBoundaryProbeDevice device) : IHcDeviceOpenAdapter
    {
        public bool IsDeviceOpen() => HcDeviceIsOpen(device);

        public void DispatchDeviceInserted() =>
            backend.OnStaBounded(() => { InvokeHcDeviceInserted(device); return true; }, "probe-device-inserted-dispatch");

        /** 替身没有版本化生命周期接口：如实报告“不支持”，由既有有界判据兜底。 */
        public bool TryWaitLifecycleCompletion(int timeoutMs, out string outcome, out string detail)
        {
            outcome = "unsupported";
            detail = "probe-device-has-no-lifecycle-api";
            return false;
        }
    }

    /**
     * 920-v1.4 §16.2：Phase 1 的**非阻塞**部分 —— 只决定是否必须派发
     * `Device_Inserted(true)`，并把派发挂到本 STA 队列上；**不等待**。
     * 等待已移到 `OpenEvents()` 的调用方线程（见 `WaitForHcDeviceOpenBounded`）。
     */
    private HcDeviceOpenNeed BeginHcDeviceOpenForRestore()
    {
        // ROG's HC SetFanControl(false) is guarded by ROGAlly.IsOpen. That
        // property becomes true only after HC's DeviceManager arrival path
        // dispatches the virtual Device_Inserted(true) callback, which opens
        // the input HID. A fan-only Host deliberately does not own HC's full
        // DeviceManager graph, so reproduce that exact virtual device callback
        // after OpenEvents rather than inventing a replacement HID/ACPI path.
        if (Route?.RestoreStrategy != FanRestoreStrategy.AsusAcpiCurves || device is null)
            return HcDeviceOpenNeed.None;

        if (HcDeviceIsOpen(device))
        {
            Diagnostic?.Invoke("hc-device-open-confirmed", new { route = Route.Kind.ToString(), source = "already-open" });
            return HcDeviceOpenNeed.None;
        }

        Diagnostic?.Invoke("hc-device-inserted.begin", new { factoryType = FactoryType, reScan = true });
        // Device_Inserted 是 async void：这里只负责派出，完成判定交给调用方线程的等待。
        InvokeHcDeviceInserted(device);
        Diagnostic?.Invoke("hc-device-inserted.dispatched", new { factoryType = FactoryType, reScan = true });
        return HcDeviceOpenNeed.WaitForDeviceInserted;
    }

    private static void InvokeHcDeviceInserted(object target)
    {
        var method = target.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
            .Where(candidate => candidate.Name == "Device_Inserted")
            .Where(candidate => candidate.GetParameters() is [{ ParameterType: var type }] && type == typeof(bool))
            .OrderByDescending(candidate => candidate.DeclaringType == target.GetType())
            .FirstOrDefault()
            ?? throw new MissingMethodException(target.GetType().FullName, "Device_Inserted(bool)");

        // `true` is the exact argument used by IDevice.QueryDevices() after
        // DeviceManager reports an existing HID device.
        method.Invoke(target, [true]);
    }

    private class HcDeviceInsertedProbe
    {
        public bool Called { get; protected set; }
        public bool? ReScan { get; protected set; }

        protected virtual void Device_Inserted(bool reScan)
        {
            Called = true;
            ReScan = reScan;
        }
    }

    private sealed class HcDeviceInsertedOverrideProbe : HcDeviceInsertedProbe
    {
        protected override void Device_Inserted(bool reScan)
        {
            base.Device_Inserted(reScan);
        }
    }

    internal static IReadOnlyList<string> RunHcVirtualDeviceInsertionSelfTest()
    {
        var probe = new HcDeviceInsertedOverrideProbe();
        InvokeHcDeviceInserted(probe);
        if (!probe.Called || probe.ReScan != true)
            throw new InvalidOperationException("HC Device_Inserted(true) dispatch did not preserve the upstream HID attach contract");
        return ["hc-rog-device-inserted-true-dispatch"];
    }

    private void OpenHcDevice()
    {
        if (device is null)
            throw new InvalidOperationException("HC device unavailable");
        // Dispatches to the exact HC virtual override. Do not replace this
        // with a hand-built OpenLib/ACPI sequence: several device families
        // use Open() to establish their own fan and controller prerequisites.
        hcOpenInvocationStarted = true;
        if (Invoke(device, "Open") is not bool opened || !opened)
            throw new InvalidOperationException("HC device Open returned false");
        IsOpen = true;
    }

    /**
     * 会话门控能力面（920 §31 C2）：候选 HC 的版本化设备生命周期接口
     * （`IHcDeviceLifecycleApi`，`LifecycleApiVersion>=1`）即"公开 `IsReady()` 受
     * 会话准入约束"的判据（`ROGAlly.cs:280-290`）。旧 runtime 无此能力面
     * ⇒ **不适用**新顺序，保持原前置轮询（不擅自删除厂商等待）。
     */
    private bool HasSessionGatedPublicIsReady() =>
        device is not null && GetMember(device, "LifecycleApiVersion") is int apiVersion && apiVersion >= 1;

    private void WaitForHcDeviceReadyBeforeOpen()
    {
        // This is the same readiness probe and 10-second budget used by HC's
        // MainWindow. HC logs the timeout but still lets its virtual Open()
        // decide, so the Host does exactly that instead of inventing a new
        // pre-open rejection rule.
        var budgetMs = 10_000;
        // 920 §31 C2（2026-09-25 裁决卡 §6-C）：**关闭后重开**的前置条件顺序冲突。
        // HC 契约（树 B = 线上二进制源码面，锚点见 R5B 回函 §1.1/§1.3）：
        //   `RogAllyDeviceLifecycle.cs:525` `sessionValid = true`（构造初值）；
        //   `:1765-1776` `BeginCloseLocked` ⇒ `sessionValid = false` 且推进会话代次；
        //   `ROGAlly.cs:292-300` → `:804-813` 只有正式 `Open()` **成功之后**才
        //   `PublishNewSession()` 恢复会话有效。
        // 公开 `IsReady()` = `SessionMatchesLocked && probe.Ready`
        // （`:820-857` 物理探测照常执行，但 `:1145` 会话判据不成立就丢弃绑定）——
        // **失效会话下恒 false**，结构上无法表达"物理已就绪"。
        // ⇒ 本 Host 自己完成过一次 Close（`closed`）之后，前置轮询**必然跑满预算**，
        // 且不提供任何物理信息。此时按 §1.4(b) 改由**正式 `Open()`**（HC 唯一会话
        // 发布者）的返回值表达物理缺失/失败，而不是继续等一个被会话门控的读数。
        // 冷启动（从未 Close ⇒ `sessionValid` 仍为构造初值）语义**完全不变**。
        if (closed && HasSessionGatedPublicIsReady())
        {
            RecordReadyWaitEvidence(0, 0, 0, ready: true, skipped: "reopen-session-gated-by-hc-contract");
            return;
        }
        var startedTick = Environment.TickCount64;
        var deadline = startedTick + budgetMs;
        var polls = 0;
        var ready = false;
        while (Environment.TickCount64 < deadline)
        {
            if (Invoke(device!, "IsReady") is bool isReady && isReady)
            {
                ready = true;
                break;
            }
            polls++;
            Thread.Sleep(250);
        }
        // E-1（FAN-204 §31 R4，2026-09-24）：就绪等待**归入高频日志**（operator 口径：不算事件）
        // —— 读数随本采样带出（照 `hcLoopStopEvidence` 的做法），**不新增日志行**。
        // 真机背景：唤醒期该等待跑满 10 s 预算而旧日志无任何痕迹（`HcCoreWarning` 只并入
        // handshake reason），构成"唤醒黑盒"。HC 侧对应事实：唤醒期 `sessionValid=false` ⇒
        // `ProbeReadyForPublicIsReady` 每次探测被拒、绑定不发布（`RogAllyReadyBindingRejected`
        // / `RogAllyProbeBindingDiscarded`，见 HC Serilog 通道）。
        if (!ready)
            HcCoreWarning = "HC IsReady timed out; continuing with HC Open() as upstream does";
        RecordReadyWaitEvidence(polls, budgetMs, Environment.TickCount64 - startedTick, ready);
    }

    /**
     * E-1（FAN-204 §31 R4，2026-09-24）：最近一次就绪等待的**只读读数**。
     * 按 operator 口径归入**高频日志**——随既有 `host.runtime-sample`（30 s 常规 / 1 s 故障态自适应）
     * 带出，**不新增事件行**、不受事件清单/合同约束。字段写入无 I/O ⇒ 日志门关闭时零成本。
     * 真机背景（2026-09-24）：唤醒期该等待跑满 10 s 预算而旧日志**无任何痕迹**，构成"唤醒黑盒"。
     */
    private long hcReadyWaitLastTick;
    private int hcReadyWaitLastPolls = -1;
    private int hcReadyWaitLastBudgetMs;
    private int hcReadyWaitLastElapsedMs = -1;
    private bool hcReadyWaitLastReady = true;
    private string hcReadyWaitLastSkipped = "none";

    internal object HcReadyWaitEvidenceForSelfTest => new
    {
        polls = hcReadyWaitLastPolls,
        budgetMs = hcReadyWaitLastBudgetMs,
        elapsedMs = hcReadyWaitLastElapsedMs,
        ready = hcReadyWaitLastReady,
        timedOut = hcReadyWaitLastPolls >= 0 && !hcReadyWaitLastReady,
        lastTick = hcReadyWaitLastTick,
        hcCoreWarning = HcCoreWarning,
        // 920 §31 C2：本次前置轮询被跳过时的**原因**（`none` = 正常轮询）。
        // 与 polls/budgetMs/elapsedMs 一起读，避免把"没轮询"误读成"设备已就绪"。
        skipped = hcReadyWaitLastSkipped,
    };

    /** E-1：记录一次就绪等待（**唯一实现**，生产与自测共用；只写字段，不写日志）。 */
    internal void RecordReadyWaitEvidence(int polls, int budgetMs, long elapsedMs, bool ready, string skipped = "none")
    {
        hcReadyWaitLastPolls = polls;
        hcReadyWaitLastBudgetMs = budgetMs;
        hcReadyWaitLastElapsedMs = (int)Math.Clamp(elapsedMs, 0, int.MaxValue);
        hcReadyWaitLastReady = ready;
        hcReadyWaitLastSkipped = skipped;
        hcReadyWaitLastTick = Environment.TickCount64;
    }

    /**
     * G-1（2026-09-27 消费侧取证，T 批 §4 性质更正）：消费 HC **已有**的结构化逐轮入口 ——
     * `PeekReceipts()`（`RogAllyDeviceLifecycle.cs:965`）、`TryGetReceipt(opId)`（`:960`）、
     * `DescribeCleanupLedger()`（`:727`）、`DescribeCleanupCycle()`（`:705`）、
     * `IsInputBindingPresent()`（`:859`）。
     *
     * 真机背景：宿主此前只取"**最近一次**操作"（`LastCompatEntryOperationId`）⇒ 唤醒期"逐轮
     * 拒绝/丢弃"在宿主 JSON 通道里是**黑盒**（§8-316 行；T 批更正为**宿主消费缺口**）。
     *
     * 契约（与 E-1 同款，硬约束）：**只读、只增字段、不新增 I/O、不改任何判定**。
     * 入口缺失（旧 runtime）/ 反射异常 ⇒ 如实记 `absent` / `fault`，**不得**影响打开、
     * 停止、交还、睡眠任何路径。**只在既有事件里带出**，不做周期性采样（避免日志开销）。
     */
    internal object HcReceiptsEvidence => DescribeHcReceiptsEvidence(device);

    /** 逐轮收据只带最近 N 轮（HC 的 `PeekReceipts()` 返回全量；本字段只做可见性）。 */
    internal const int RecentHcReceiptLimit = 3;

    internal static object DescribeHcReceiptsEvidence(object? target)
    {
        if (target is null) return new { api = "no-device" };
        try
        {
            var type = target.GetType();
            var peek = FindNoArgMethod(type, "PeekReceipts");
            var hasLedger = FindNoArgMethod(type, "DescribeCleanupLedger") is not null;
            var hasCycle = FindNoArgMethod(type, "DescribeCleanupCycle") is not null;
            var hasBinding = FindNoArgMethod(type, "IsInputBindingPresent") is not null;
            var receipts = new List<string>();
            var receiptCount = 0;
            if (peek?.Invoke(target, null) is System.Collections.IEnumerable enumerated)
            {
                var all = enumerated.Cast<object?>().Where(item => item is not null).ToList();
                receiptCount = all.Count;
                foreach (var receipt in all.Skip(Math.Max(0, all.Count - RecentHcReceiptLimit)))
                    receipts.Add(DescribeHcLifecycleReceipt(receipt!));
            }
            return new
            {
                api = peek is not null || hasLedger || hasCycle || hasBinding ? "present" : "absent",
                bindingPresent = hasBinding ? TryInvokeNoArg(type, target, "IsInputBindingPresent") : null,
                receiptCount,
                recentLimit = RecentHcReceiptLimit,
                // 逐轮（最近 N 条，**含**非终态与拒绝原因），不是"最近一次"。
                receipts,
                cleanupLedger = hasLedger ? TryInvokeNoArg(type, target, "DescribeCleanupLedger") : null,
                cleanupCycle = hasCycle ? TryInvokeNoArg(type, target, "DescribeCleanupCycle") : null,
            };
        }
        catch (Exception ex)
        {
            // 取证失败不得影响任何控制路径：如实记 fault。
            return new { api = "fault", error = DescribeException(ex) };
        }
    }

    /** 单条 HC 操作收据：优先用 HC 自己的 `Describe()`（`RogAllyDeviceLifecycle.cs:303`），否则退化为关键字段。 */
    private static string DescribeHcLifecycleReceipt(object receipt)
    {
        try
        {
            if (TryInvokeNoArg(receipt.GetType(), receipt, "Describe") is string described &&
                !string.IsNullOrWhiteSpace(described))
                return described;
        }
        catch (Exception)
        {
            // 单条描述失败不影响整批；下面退化为字段拼接。
        }
        return $"op={GetMember(receipt, "OperationId") ?? "?"} gen={GetMember(receipt, "SessionGeneration") ?? "?"} " +
               $"outcome={GetMember(receipt, "Outcome") ?? "?"} phase={GetMember(receipt, "Phase") ?? "?"}";
    }

    private static System.Reflection.MethodInfo? FindNoArgMethod(Type type, string name) =>
        type.GetMethods(BindingFlags.Public | BindingFlags.Instance)
            .FirstOrDefault(m => string.Equals(m.Name, name, StringComparison.Ordinal) && m.GetParameters().Length == 0);

    private static object? TryInvokeNoArg(Type type, object target, string name) =>
        FindNoArgMethod(type, name)?.Invoke(target, null);

    private void EnsureCpuTemperatureLoop()
    {
        if (cpuTemperatureMonitor is not null) return;
        // FanHost consumes the existing YeMan HWiNFO snapshot. It must not
        // open a second hardware-sensor backend: HWiNFO already owns the
        // sensor read and publishes the HWiNFO shared-memory channel for the
        // rest of YeMan.
        cpuTemperatureMonitor = new HWiNFOTemperatureMonitor();
        // HC publishes an event only when a matching CPU temperature changes.
        // The second callback is deliberately not a dispatch event: it marks
        // a valid, non-zero HC-equivalent sample so a steady CPU temperature
        // cannot be mistaken for a dead monitor.
        try
        {
            cpuTemperatureMonitor.Start(OnHcCpuTemperatureChanged, OnHcCpuTemperatureSampled);
            Diagnostic?.Invoke("temperature.monitor-started", cpuTemperatureMonitor.DiagnosticsSnapshot());
        }
        catch (Exception ex)
        {
            Diagnostic?.Invoke("temperature.monitor-start-failed", new
            {
                error = DescribeException(ex),
                requestedIntervalMs = 1000,
                source = "HW.HWiNFO.shared-memory",
                route = Route?.Kind.ToString(),
            });
            cpuTemperatureMonitor.Dispose();
            cpuTemperatureMonitor = null;
            throw;
        }
        lastTemperatureTick = Environment.TickCount64;
        temperatureStaleSignaled = false;
        temperatureWatchdog?.Dispose();
        temperatureWatchdog = new Timer(_ => TemperatureWatchdogTick(), null, 2000, 2000);
    }

    private void TemperatureWatchdogTick()
    {
        var stale = false;
        lock (hardwareGate)
        {
            if (activeFanProfile is not null && IsOpen && !temperatureStaleSignaled &&
                Environment.TickCount64 - lastTemperatureTick > TemperatureStaleTimeoutMs)
            {
                temperatureStaleSignaled = true;
                DetachCpuTemperatureLoop();
                stale = true;
            }
        }
        if (stale)
            _ = Task.Run(() => TemperatureMonitorStale?.Invoke());
    }

    private void OnHcCpuTemperatureChanged(float? value)
    {
        lock (hardwareGate)
        {
            if (value is not null) MarkTemperatureHealthySample();
            if (AreTemperatureWritesBlocked() || activeFanProfile is null || !IsOpen || value is null) return;
            if (!IsHcSessionReadyForControl(out var sessionReason))
            {
                // A missing HC device/HID marker is a control-session fault,
                // not a harmless skipped sample. Stop the temperature source
                // before another callback can issue a write and hand the
                // single recovery owner back to FanHostEngine.
                DetachCpuTemperatureLoop();
                var error = new InvalidOperationException($"HC_SESSION_ROUTE_LOST: {sessionReason}");
                _ = Task.Run(() => FanDispatchFailure?.Invoke(error));
                return;
            }
            var temp = value.Value;
            // HC raises its temperature event only when the sensor changes.
            // The direct reader samples every second for watchdog health, but
            // preserves HC's dispatch behavior and avoids duplicate EC writes.
            if (lastDispatchedTemperature == temp) return;
            lastDispatchedTemperature = temp;

            // Exact body of HC PowerProfileManager's temperature-change
            // handler. HWiNFO supplies the sample; HC still owns the curve
            // calculation and the device callback that requests fan duty.
            try
            {
                Invoke(activeFanProfile, "SetTemperature", temp);
                var duty = Convert.ToDouble(Invoke(activeFanProfile, "GetFanSpeed"));
                Invoke("SetFanDuty", duty);
                lastTemperatureC = temp;
                lastDutyPercent = duty;
            }
            catch (Exception ex)
            {
                // Never let a timer callback escape into HC's sensor thread.
                // Detach first, then ask the engine to enter its existing
                // restore/fault-lock path asynchronously to avoid lock inversion.
                DetachCpuTemperatureLoop();
                _ = Task.Run(() => FanDispatchFailure?.Invoke(ex));
            }
        }
    }

    private void OnHcCpuTemperatureSampled()
    {
        lock (hardwareGate) MarkTemperatureHealthySample();
    }

    private void MarkTemperatureHealthySample()
    {
        lastTemperatureTick = Environment.TickCount64;
        temperatureStaleSignaled = false;
    }

    private bool AreTemperatureWritesBlocked() =>
        operationTimedOut ||
        // 第十轮返修（P1-B）：版本化睡眠写门——放行当且仅当"解除时记录的
        // 期望版本"与当前 gate 版本相等（睡眠宣布/关闭/超时都会递增 gate，
        // 无论交错顺序，旧解除都无法在新睡眠之后放行）。
        Volatile.Read(ref writeAllowEpoch) != Volatile.Read(ref suspendGateEpoch) ||
        Volatile.Read(ref closeWriteBlocked) != 0;

    private void DetachCpuTemperatureLoop()
    {
        temperatureWatchdog?.Dispose();
        temperatureWatchdog = null;
        var monitor = cpuTemperatureMonitor;
        cpuTemperatureMonitor = null;
        activeFanProfile = null;
        lastDispatchedTemperature = null;
        if (monitor is not null)
        {
            monitor.Dispose();
            Diagnostic?.Invoke("temperature.monitor-stopped", monitor.DiagnosticsSnapshot());
        }
    }

    private void StopCpuTemperatureMonitor()
    {
        DetachCpuTemperatureLoop();
        powerProfileWatchdog?.Dispose();
        powerProfileWatchdog = null;
    }

    private void CaptureOemBaseline()
    {
        oemRestoreVerified = false;
        oemRestoreEvidence = "none";
        oemReleaseActionKind = "not-attempted";
        oemReleaseActionEvidence = "none";
        oemOwnershipStatus = "unknown-no-hc-contract";
        oemBaselineCaptured = false;
        baselineStrategy = Route?.RestoreStrategy ?? FanRestoreStrategy.None;
        baselineRestoreRoute = FactoryType;
        baselineSmartFanMode = null;
        hcProfileTemplate = null;
        baselineMsiShiftValue = null;
        hcOemReleaseCallbackCompleted = false;
        asusOemReadbackConfirmed = false;

        switch (baselineStrategy)
        {
            case FanRestoreStrategy.MsiHcDefaultRelease:
                TryCaptureMsiProfileContext();
                break;
            case FanRestoreStrategy.LenovoHcDefaultTable:
            case FanRestoreStrategy.LegionGo2EcRpmOverride:
                TryCaptureSmartFanModeContext();
                break;
        }
        CaptureHcProfileTemplate();
        CaptureBaselineBinding();
        oemBaselineCaptured = true;
    }

    /**
     * FAN-936 §5：把"有效基线"显式绑定到**当前设备 / 当前 Host 实例 / 当前控制周期 / 当前 boot identity**。
     * 只在 `CaptureOemBaseline()` 末尾调用一次，四项同时落定。
     */
    private void CaptureBaselineBinding()
    {
        baselineDeviceType = FactoryType;
        baselineDeviceReference = device;
        baselineHostInstanceId = backendHostInstanceId;
        baselineBootIdentity = machineBootIdentity;
        baselineControlCycleId = ControlCycleId;
    }

    /**
     * FAN-936 §5：基线绑定核对（判定 + 原因）。任一项不符 ⇒ 旧基线**不得**被消费，
     * 由调用方 fail-closed 拒绝，而不是拿旧快照去覆盖 MSI 前端/其它 OEM writer 的新设置。
     */
    internal bool BaselineBindingStillValid(out string reason)
    {
        if (!oemBaselineCaptured) { reason = "baseline-not-captured"; return false; }
        if (!string.Equals(baselineDeviceType, FactoryType, StringComparison.Ordinal))
        { reason = "device-type-changed"; return false; }
        if (!ReferenceEquals(baselineDeviceReference, device))
        { reason = "device-instance-changed"; return false; }
        if (!string.Equals(baselineHostInstanceId, backendHostInstanceId, StringComparison.Ordinal))
        { reason = "host-instance-changed"; return false; }
        if (!string.Equals(baselineBootIdentity, machineBootIdentity, StringComparison.Ordinal))
        { reason = "boot-identity-changed"; return false; }
        if (baselineControlCycleId != ControlCycleId)
        { reason = "control-cycle-changed"; return false; }
        reason = "bound";
        return true;
    }

    /**
     * FAN-936 §5：写入/交还前的**唯一**绑定门。绑定失效时按路线语义 fail-closed：
     * 抛 `FAN_BASELINE_BINDING_LOST`，不得静默沿用旧快照。
     */
    internal void EnsureBaselineBindingForControl()
    {
        // FAN-936 R2 section 5: the baseline-binding rejection is an MSI-only
        // admission condition. ROG/GPD/Lenovo/generic routes keep their existing
        // behaviour and must not inherit FAN_BASELINE_BINDING_LOST just because
        // the MSI route introduced this gate. Non-MSI routes therefore return
        // without the check.
        if (Route?.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease) return;
        if (BaselineBindingStillValid(out var reason)) return;
        throw new FanApiException(409, "FAN_BASELINE_BINDING_LOST",
            $"基线绑定失效（{reason}）：拒绝用旧周期/旧实例/旧开机的快照覆盖当前 OEM 设置");
    }

    /**
     * FAN-936 §3/§5：HC 侧 `ReleaseMsiFanControl` 结构化结论在 Host 侧的投影（只读快照）。
     * 只有**绑定本次开机**的结构化结论才是本周期释放证书；旧周期/旧实例快照一律不可用。
     */
    private sealed record MsiStructuredRelease(
        string? Status,
        string? FullSpeed152Status,
        string? SoftwareControl212Status,
        string? HostInstanceId,
        string? BootIdentity,
        string? Summary,
        string Reason);

    /**
     * FAN-936 §3/§5 + R4：读 MSI 结构化释放结论。
     * 返回 null ⇒ **没有可用的本次操作证书**（缺失 / 未绑定本次开机 / 未回显本次操作令牌 / 无设备），
     * 调用方必须 fail-closed（Unknown），绝不回落成 compat 成功。`HostInstanceId` 只记录不直接比较
     * （HC 侧与 Host 侧的身份算法不同）；Host 实例/控制周期/操作序号的绑定改为由**操作令牌**
     * 往返校验（`BeginMsiReleaseOperation` 写入、HC 结论回显）。
     */
    private MsiStructuredRelease? ReadMsiStructuredRelease(out string detail)
    {
        if (device is null) { detail = "msi-release:no-device"; return null; }
        var release = GetMember(device, "LastMsiFanRelease");
        if (release is null) { detail = "msi-release:absent"; return null; }
        var bootIdentity = GetMember(release, "BootIdentity") as string;
        if (!string.Equals(bootIdentity, machineBootIdentity, StringComparison.Ordinal))
        {
            detail = $"msi-release:stale-boot-identity(hc={bootIdentity ?? "<null>"} host={machineBootIdentity})";
            return null;
        }
        // FAN-936 R4：释放证书还必须绑定**本次操作**——HC 结论要回显本 Host 刚写入的操作令牌
        // （含 Host 实例 + 控制周期 + 操作序号）。只对 boot identity、预置旧收据、迟到收据、
        // 错设备/错周期收据一律拒（fail-closed），不得冒充本次恢复结果。
        var operationToken = GetMember(release, "OperationToken") as string;
        if (!string.Equals(operationToken, pendingMsiReleaseOperationToken, StringComparison.Ordinal))
        {
            detail = $"msi-release:operation-token-mismatch(hc={operationToken ?? "<null>"} host={pendingMsiReleaseOperationToken ?? "<null>"})";
            return null;
        }
        detail = "msi-release:bound-to-current-operation";
        var fullSpeed = GetMember(release, "FullSpeed152");
        var software = GetMember(release, "SoftwareControl212");
        return new MsiStructuredRelease(
            GetMember(release, "Status") as string,
            fullSpeed is null ? null : GetMember(fullSpeed, "Status") as string,
            software is null ? null : GetMember(software, "Status") as string,
            GetMember(release, "HostInstanceId") as string,
            bootIdentity,
            GetMember(release, "Summary") as string,
            "bound-to-current-operation");
    }

    /**
     * FAN-936 R1：读设备的“释放例程进入次数”单调计数器（真实 HC 与自测 mock 同名成员）。
     * 返回 null ⇒ 无设备或该成员不可读；调用方在设备存在时必须 fail-closed 视为“已跨入交还边界”。
     */
    private int? ReadMsiReleaseInvocationCount()
    {
        if (device is null) return null;
        var raw = GetMember(device, "ReleaseMsiFanControlInvocationCount");
        return raw is int count ? count : (int?)null;
    }

    /**
     * FAN-936 R1：判断 MSI Close 是否真的跨入**交还边界**——比较跨越边界前后的释放例程进入次数。
     * 设备存在但计数不可读时 fail-closed 视为已跨入（绝不把“读不到”当成“没交还”）。
     */
    private bool MsiCloseHandbackEntered()
    {
        var after = ReadMsiReleaseInvocationCount();
        if (after is null) return device is not null;
        return msiCloseReleaseInvocationCountBefore is null
            || after.Value > msiCloseReleaseInvocationCountBefore.Value;
    }

    /**
     * FAN-936 R4：派发 MSI 交还前换发**本次操作令牌**（Host 实例 + 控制周期 + 单调序号），
     * 并写入 HC 设备的 `MsiReleaseOperationToken`。HC 的 `ReleaseMsiFanControl` 会把该串回显到
     * `MsiFanReleaseResult.OperationToken`；`ReadMsiStructuredRelease` 再严格比较。
     * 只对 `MsiHcDefaultRelease` 路线生效——其它路线（ASUS/GPD/Lenovo/通用）不引入该拒绝条件。
     */
    private void BeginMsiReleaseOperation()
    {
        if (Route?.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease) return;
        var token = $"{backendHostInstanceId}:{ControlCycleId}:{++msiReleaseOperationSeq}";
        pendingMsiReleaseOperationToken = token;
        if (device is not null) SetMember(device, "MsiReleaseOperationToken", token);
    }

    /** 仅自测：走一次 `BeginMsiReleaseOperation`（生产路径由 `RestoreOemCore` 调用）。 */
    internal void BeginMsiReleaseOperationForSelfTest() => BeginMsiReleaseOperation();

    /**
     * FAN-936 R1：MSI 软件控制成功态必须由 HC 的真实结论支撑，而不是"回调返回"。
     * 只有本次 `SetFanTable` 两块都 `ok`（`LastMsiFanTableWrite.Success`）且随后的
     * `SetFanControl(true)` 为 `ok`/`skipped-already-target`（`LastMsiFanControlWrite.Status`），
     * 才承认软件控制已建立。读取失败 / 未写满 / 未 latch ⇒ fail-closed 抛 409，
     * 绝不给下游"已建立控制"的成功态。只对 `MsiHcDefaultRelease` 路线生效。
     */
    private void EnsureMsiSoftwareControlEstablished(string phase)
    {
        if (Route?.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease) return;
        var tableWrite = device is null ? null : GetMember(device, "LastMsiFanTableWrite");
        var controlWrite = device is null ? null : GetMember(device, "LastMsiFanControlWrite");
        var tableStatus = tableWrite is null ? null : GetMember(tableWrite, "Status") as string;
        var controlStatus = controlWrite is null ? null : GetMember(controlWrite, "Status") as string;
        var controlOk = controlStatus is "ok" or "skipped-already-target";
        if (!string.Equals(tableStatus, "ok", StringComparison.Ordinal) || !controlOk)
        {
            throw new FanApiException(409, "FAN_CURVE_WRITE_FAILED",
                $"{phase}: MSI 软件控制未建立（fanTable={tableStatus ?? "<absent>"} softwareControl={controlStatus ?? "<absent>"}）");
        }
        Diagnostic?.Invoke("enable.msi-structured-control", new
        {
            phase,
            fanTableStatus = tableStatus,
            softwareControlStatus = controlStatus,
            scope = "hc-msi-structured-control-established-not-physical-rpm",
        });
    }

    /** 仅自测：走一次 `EnsureMsiSoftwareControlEstablished`（生产路径由 `ApplyCurveCore` 调用）。 */
    internal void EnsureMsiSoftwareControlEstablishedForSelfTest(string phase) =>
        EnsureMsiSoftwareControlEstablished(phase);

    private void TryCaptureSmartFanModeContext()
    {
        // Lenovo's callback performs this same query itself. It returns -1 on
        // WMI failure and continues with its normal HC fallback/write path, so
        // this Host lookup may improve profile selection but cannot gate it.
        try
        {
            var value = Invoke("GetSmartFanMode");
            if (value is null) return;
            var mode = Convert.ToInt32(value);
            if (mode < 0) return;
            baselineSmartFanMode = mode;
        }
        catch { }
    }

    private void TryCaptureMsiProfileContext()
    {
        // The current shift mode only selects the closest HC profile Guid.
        // HC itself falls through to its default branch when it cannot obtain
        // a valid value, so this cannot become a Host write-admission gate.
        try
        {
            var value = Invoke("GetShiftValue");
            if (value is null) return;
            var shift = Convert.ToInt32(value);
            if (shift >= 0) baselineMsiShiftValue = shift;
        }
        catch { }
    }

    private void CaptureHcProfileTemplate()
    {
        if (device is null)
            throw new InvalidOperationException("HC device unavailable for profile context");
        if (GetMember(device, "DevicePowerProfiles") is not System.Collections.IEnumerable profiles)
            throw new InvalidOperationException("HC device power-profile context unavailable");

        var candidates = profiles.Cast<object>().ToArray();
        if (candidates.Length == 0)
            throw new InvalidOperationException("HC device does not expose a power-profile context");

        object? selected = null;
        // Lenovo's HC callback uses OEMPowerMode before it applies the fan
        // table/RPM override.  Keep the firmware's current mode intact.
        if (baselineSmartFanMode is not null)
        {
            selected = candidates.FirstOrDefault(candidate =>
                GetMember(candidate, "OEMPowerMode") is not null &&
                Convert.ToInt32(GetMember(candidate, "OEMPowerMode")) == baselineSmartFanMode.Value);
        }

        // MSI's HC callback selects the vendor shift mode from the profile
        // Guid.  Its default ProfileManager mapping is Balanced on battery
        // and Performance on AC; a matching live shift value has priority.
        selected ??= SelectMsiProfileByCurrentShift(candidates);
        selected ??= SelectHcDefaultProfileForPowerLine(candidates);
        selected ??= candidates.FirstOrDefault(candidate => Convert.ToBoolean(GetMember(candidate, "DeviceDefault") ?? false));
        selected ??= candidates[0];

        hcProfileTemplate = CloneHcPowerProfilePreservingFanState(selected);
        profilePowerLineOnline = IsPowerLineOnline();
        profileSelectionSource = baselineSmartFanMode is not null
            ? "HC.OEMPowerMode"
            : baselineMsiShiftValue is not null
                ? "HC.MSI.shift-profile"
                : "HC.PowerLineStatus.default-profile";
        profileTemplateFingerprint = DescribeProfileFingerprint(hcProfileTemplate);
    }

    private static string DescribeProfileFingerprint(object profile)
    {
        var guid = Convert.ToString(GetMember(profile, "Guid")) ?? "none";
        var mode = Convert.ToString(GetMember(profile, "OEMPowerMode")) ?? "none";
        var deviceDefault = Convert.ToString(GetMember(profile, "DeviceDefault")) ?? "none";
        return $"guid={guid};oemPowerMode={mode};deviceDefault={deviceDefault}";
    }

    private bool TryAdoptExternalHcProfile(
        out ExternalProfilePendingQueue.Snapshot? adoptedSnapshot,
        out object? adoptedTemplate,
        out bool discardBoundaryConsumed)
    {
        adoptedSnapshot = null;
        adoptedTemplate = null;
        discardBoundaryConsumed = false;
        try
        {
            var discarded = externalProfileQueue.TryConsumeDiscarded(
                DateTimeOffset.UtcNow,
                TimeSpan.FromMilliseconds(ExternalProfileDiscardedAppliedTimeoutMs),
                out var noAppliedAfterDiscard);
            discardBoundaryConsumed = discarded;

            if (discarded)
            {
                // Match HC PowerProfileManager.ProfileManager_Discarded:
                // clear the ownership observation and leave the current fan
                // settings alone until the subsequent Applied event. A
                // discard is not a license to synthesize a device-default
                // profile during the handoff window.
                profileSelectionSource = "HC.ProfileManager.Discarded→waiting-for-Applied";
                Diagnostic?.Invoke("hc.external-profile-discarded-observed", new
                {
                    action = "wait-for-applied",
                    source = "HC.ProfileManager.Discarded",
                });
            }
            if (noAppliedAfterDiscard)
            {
                // A missing next Applied is not a reason to synthesize a
                // replacement profile. Record the bounded condition so the
                // operator can distinguish an external owner disappearing
                // from a successful profile handoff.
                Diagnostic?.Invoke("hc.external-profile-discarded-no-applied", new
                {
                    action = "retain-last-safe-template",
                    timeoutMs = 2000,
                });
            }
            if (externalProfileQueue.TryGetPending(out var pending) && pending is not null)
            {
                try
                {
                    // Clone only. The HC callback/physical dispatch remains in
                    // PowerProfileWatchdogTick, outside the HC profile lock.
                    adoptedTemplate = CloneHcPowerProfilePreservingFanState(pending.Profile);
                    if (!externalProfileQueue.IsCurrent(pending))
                    {
                        adoptedTemplate = null;
                        return false;
                    }
                    adoptedSnapshot = pending;
                }
                catch (Exception ex)
                {
                    RecordExternalProfileFailure(pending, ex, "clone");
                    return false;
                }
                return true;
            }
            // Do not call HC PowerProfileManager.GetCurrent() here. This
            // method runs under hardwareGate and HC calls this event while
            // holding its own profileLock; re-entering the manager here is a
            // lock-order inversion. Applied is the authoritative HC event;
            // the serialized tick consumes only the detached snapshot.
            return false;
        }
        catch (Exception ex)
        {
            Diagnostic?.Invoke("hc.external-profile-context-read-failure", new { error = DescribeException(ex) });
            return false;
        }
    }

    private void RecordExternalProfileFailure(
        ExternalProfilePendingQueue.Snapshot snapshot,
        Exception error,
        string phase)
    {
        if (!externalProfileQueue.RecordFailure(snapshot, out var attempt, out var exhausted))
        {
            Diagnostic?.Invoke("hc.external-profile-retry-stale", new
            {
                phase,
                snapshot.Generation,
                snapshot.Sequence,
                error = DescribeException(error),
            });
            return;
        }
        Diagnostic?.Invoke(
            exhausted ? "hc.external-profile-retry-exhausted" : "hc.external-profile-retry-scheduled",
            new
            {
                phase,
                attempt,
                maxAttempts = ExternalProfilePendingQueue.MaxRetryAttempts,
                snapshot.Generation,
                snapshot.Sequence,
                error = DescribeException(error),
            });
    }

    private void EnsurePowerProfileWatchdog()
    {
        powerProfileWatchdog?.Dispose();
        powerProfileWatchdogStartedAtUtc = DateTimeOffset.UtcNow;
        // FAN-929（2026-09-27 用户裁决）：改为**事件驱动**的一次性计时器。
        // 原 1 Hz 常驻轮询是运行期唯一恒定的风扇门 CPU 成本（真机 tickCount 与秒数精确 1:1）。
        // 现在只在 enable / 外部 profile 事件到达时武装一次；AC/DC 变化由
        // ApplyCurveCore 的**写时电源档对齐**覆盖，route 丢失由写时校验覆盖。
        powerProfileWatchdog = new Timer(_ => PowerProfileWatchdogTick(), null, Timeout.Infinite, Timeout.Infinite);
        powerProfileWatchdog.Change(0, Timeout.Infinite);
        Diagnostic?.Invoke("profile.watchdog-started", new
        {
            intervalMs = 0,
            mode = "event-driven",
            route = Route?.Kind.ToString(),
            source = "yeman-profile-watchdog",
        });
    }

    private static string NormalizeUpdateSourceName(string? source)
    {
        // Keep the HC enum boundary closed: an unknown/future source is safer
        // as Background than as a guessed UI-originated update. The value is
        // parsed against the pinned HC enum only at the callback boundary.
        return source switch
        {
            "ProfilesPage" or "QuickProfilesPage" or "QuickProfilesCreation" or
            "Creation" or "Serializer" or "LibraryUpdate" or
            "QuickProfilesEnable" or "LayoutPage" => source,
            _ => "Background",
        };
    }

    private void PowerProfileWatchdogTick()
    {
        var started = Stopwatch.GetTimestamp();
        var acted = false;
        try
        {
            acted = PowerProfileWatchdogTickCore();
        }
        finally
        {
            var durationTicks = Stopwatch.GetTimestamp() - started;
            Interlocked.Increment(ref powerProfileWatchdogTickCount);
            Interlocked.Exchange(ref powerProfileWatchdogLastDurationTicks, durationTicks);
            var previousMax = Volatile.Read(ref powerProfileWatchdogMaxDurationTicks);
            while (durationTicks > previousMax &&
                   Interlocked.CompareExchange(ref powerProfileWatchdogMaxDurationTicks, durationTicks, previousMax) != previousMax)
                previousMax = Volatile.Read(ref powerProfileWatchdogMaxDurationTicks);
            // FAN-929：撤销"每 5 个 tick 无条件写一条"的周期诊断（那是运行期恒定的写盘成本）。
            // 现在只在本次 tick **真的做了动作**（电源档变化 / 外部 profile 采纳 / route 丢失）时留证。
            if (acted)
                Diagnostic?.Invoke("profile.watchdog-sample", PowerProfileWatchdogDiagnostics);
            // FAN-931 P1.5：确认"有界延迟复核"确实有消费者——只在确有边沿时再排一拍。
            ArmBoundedProfileWatchdogFollowUp();
        }
    }

    private bool PowerProfileWatchdogTickCore()
    {
        // FAN-931 P1.5：每拍重置——只有本拍真的消费到丢弃边界才排截止点复核。
        profileWatchdogDiscardBoundaryConsumed = false;
        lock (hardwareGate)
        {
            if (activeCurveDuties is null || !IsOpen || AreTemperatureWritesBlocked()) return false;
            // YeMan observes the HC route marker before replaying an AC/DC or
            // external-profile update.  HC owns the actual device callback;
            // this check only prevents a stale fan-only session from issuing a
            // second write after Armoury/OEM has removed the route.  The
            // existing FanDispatchFailure owner then performs the single
            // Close/unbind recovery and the bridge may rebuild a fresh HC
            // session.  Do not synthesize an ACPI/HID command here.
            if (!IsHcSessionReadyForControl(out var routeReason))
            {
                var routeLoss = new InvalidOperationException($"HC_SESSION_ROUTE_LOST: {routeReason}");
                Diagnostic?.Invoke("hc.power-profile-route-lost", new
                {
                    reason = routeReason,
                    source = "yeman-profile-watchdog",
                });
                _ = Task.Run(() => FanDispatchFailure?.Invoke(routeLoss));
                return true;
            }
            var online = IsPowerLineOnline();
            var externalProfileChanged = TryAdoptExternalHcProfile(
                out var externalSnapshot,
                out var externalTemplate,
                out var discardBoundaryConsumed);
            // FAN-931 P1.5：只有在**本拍真的看到了丢弃边界**时才为"等 Applied 截止点"再排一拍，
            // 否则（无活动曲线/被阻断而根本走不到这里）就永远不会重复武装。
            profileWatchdogDiscardBoundaryConsumed = discardBoundaryConsumed;
            // A newer Applied or a Discarded event may have superseded the
            // detached snapshot while it was being cloned. Never dispatch the
            // superseded template; leave the newer event for the next tick.
            if (externalSnapshot is not null && !externalProfileQueue.IsCurrent(externalSnapshot))
            {
                externalSnapshot = null;
                externalTemplate = null;
                externalProfileChanged = false;
            }
            if (profilePowerLineOnline is null)
            {
                profilePowerLineOnline = online;
                if (!externalProfileChanged) return false;
            }
            if (profilePowerLineOnline.Value == online && !externalProfileChanged) return false;
            var previous = profilePowerLineOnline.Value;
            try
            {
                // Equivalent fan boundary of HC's
                // SystemManager.PowerLineStatusChanged ->
                // PowerProfileManager.ProfileManager_Applied path. Do not
                // start HC's TDP/GPU/profile managers in this isolated Host.
                if (profilePowerLineOnline.Value != online)
                    CaptureHcProfileTemplate();
                var profile = BuildPowerProfile(
                    activeCurveDuties,
                    software: true,
                    templateOverride: externalTemplate);
                var source = externalProfileChanged
                    ? NormalizeUpdateSourceName(externalSnapshot?.Source)
                    : "Background";
                ApplyPowerProfile(profile, source);
                hcProfileTemplate = profile;
                activeFanProfile = GetMember(profile, "FanProfile");
                profilePowerLineOnline = online;
                if (externalSnapshot is not null)
                {
                    if (externalProfileQueue.Complete(externalSnapshot))
                    {
                        profileSelectionSource = "HC.ProfileManager.Applied";
                        profileTemplateFingerprint = DescribeProfileFingerprint(profile);
                    }
                }
                Diagnostic?.Invoke("hc.power-line-profile-applied", new
                {
                    previousOnline = previous,
                    online,
                    source,
                    profileSelectionSource,
                    profileTemplateFingerprint,
                });
            }
            catch (Exception ex)
            {
                if (externalSnapshot is not null)
                    RecordExternalProfileFailure(externalSnapshot, ex, "apply");
                Diagnostic?.Invoke("hc.power-line-profile-failure", new
                {
                    previousOnline = previous,
                    online,
                    error = DescribeException(ex),
                });
                _ = Task.Run(() => FanDispatchFailure?.Invoke(ex));
            }
            return true;
        }
    }

    private object? SelectMsiProfileByCurrentShift(IReadOnlyList<object> candidates)
    {
        if (baselineMsiShiftValue is null) return null;
        // HC stores the shift type in the low six bits.  These are the same
        // values returned by ClawA1M.GetShiftModeValue().
        var shiftType = baselineMsiShiftValue.Value & 0x3F;
        var idDeviceType = FindType("HandheldCompanion.Devices.IDevice");
        if (idDeviceType is null) return null;
        var expectedGuid = shiftType switch
        {
            2 => GetStaticMember(idDeviceType, "BetterBatteryGuid"),
            1 => GetStaticMember(idDeviceType, "BetterPerformanceGuid"),
            4 => GetStaticMember(idDeviceType, "BestPerformanceGuid"),
            _ => null,
        };
        return expectedGuid is null
            ? null
            : candidates.FirstOrDefault(candidate => Equals(GetMember(candidate, "Guid"), expectedGuid));
    }

    private object? SelectHcDefaultProfileForPowerLine(IReadOnlyList<object> candidates)
    {
        // This is HC ProfileManager's built-in default mapping: Better
        // Performance when offline, Best Performance when online.  We only
        // use it when firmware state did not provide a stricter context.
        var online = IsPowerLineOnline();
        var idDeviceType = FindType("HandheldCompanion.Devices.IDevice");
        if (idDeviceType is null) return null;
        var expectedGuid = GetStaticMember(idDeviceType, online ? "BestPerformanceGuid" : "BetterPerformanceGuid");
        return expectedGuid is null
            ? null
            : candidates.FirstOrDefault(candidate => Equals(GetMember(candidate, "Guid"), expectedGuid));
    }

    private static bool IsPowerLineOnline()
    {
        var systemInformation = Type.GetType("System.Windows.Forms.SystemInformation, System.Windows.Forms");
        var powerStatus = systemInformation?.GetProperty("PowerStatus", BindingFlags.Public | BindingFlags.Static)?.GetValue(null);
        var status = powerStatus is null
            ? null
            : powerStatus.GetType().GetProperty("PowerLineStatus", BindingFlags.Public | BindingFlags.Instance)?.GetValue(powerStatus);
        // Keep the HC default AC mapping when the platform does not expose a
        // power-line value.  This is the same fallback HC uses for a normal
        // active desktop profile, and it does not perform a hardware write.
        return !string.Equals(Convert.ToString(status), "Offline", StringComparison.OrdinalIgnoreCase);
    }

    private object CloneHcPowerProfile(object source)
    {
        var factory = FindType("HandheldCompanion.Managers.ManagerFactory")
            ?? throw new MissingMemberException("HC ManagerFactory not found");
        var manager = GetStaticMember(factory, "powerProfileManager")
            ?? throw new MissingMemberException("HC PowerProfileManager not found");
        return Invoke(manager, "CloneProfile", source)
            ?? throw new InvalidOperationException("HC PowerProfile clone failed");
    }

    private object CloneHcPowerProfilePreservingFanState(object source)
    {
        var clone = CloneHcPowerProfile(source);
        var sourceFan = GetMember(source, "FanProfile");
        var cloneFan = GetMember(clone, "FanProfile");
        if (sourceFan is not null && cloneFan is not null)
            CopyFanRuntimeState(sourceFan, cloneFan);
        return clone;
    }

    private static void CopyFanRuntimeState(object sourceFan, object targetFan)
    {
        // Newtonsoft's HC CloneProfile serializes public fields/properties;
        // FanProfile's smoothing buffer, aggressivity and Tjmax latch are
        // private runtime state and would otherwise silently reset on every
        // curve/power-line update. Copy only those HC-owned fields, never
        // inventing a parallel fan algorithm.
        foreach (var name in new[] { "aggressivity", "tjLatch", "tjLastHitUtc", "belowCount" })
        {
            var sourceField = sourceFan.GetType().GetField(name, BindingFlags.Instance | BindingFlags.NonPublic);
            var targetField = targetFan.GetType().GetField(name, BindingFlags.Instance | BindingFlags.NonPublic);
            if (sourceField is not null && targetField is not null)
                targetField.SetValue(targetFan, sourceField.GetValue(sourceFan));
        }

        var sourceAverageField = sourceFan.GetType().GetField("avgTemp", BindingFlags.Instance | BindingFlags.NonPublic);
        var targetAverageField = targetFan.GetType().GetField("avgTemp", BindingFlags.Instance | BindingFlags.NonPublic);
        var sourceAverage = sourceAverageField?.GetValue(sourceFan) as System.Collections.IEnumerable;
        var targetAverage = targetAverageField?.GetValue(targetFan);
        if (sourceAverage is null || targetAverage is null) return;
        var add = targetAverage.GetType().GetMethod("Add", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        if (add is null) return;
        foreach (var sample in sourceAverage) add.Invoke(targetAverage, new[] { sample });
    }

    private bool ConfirmOemRestore()
    {
        if (!string.Equals(baselineRestoreRoute, FactoryType, StringComparison.Ordinal)) return false;
        // FAN-934 R2 §3-A.1：释放证书只认**本次操作的合格证据**。回调返回只是必要条件；
        // 若本次释放动作分类为 Unknown/Failed（未登记路由、无操作作用域、前提不满足、
        // 收据缺失、明确失败），一律不得置 verified，也不得给 ownership 记成功——
        // 否则"没有合格证据"会被下游 Close/状态导出读成已完成释放（fail-open）。
        oemRestoreVerified = hcOemReleaseCallbackCompleted
            && FanHostEngine.IsOemReleaseSafe(hardwareWritesObserved: true, oemReleaseActionKind);
        // §19-C / FAN-936 §3.2.2/§3.2.5：本次交还**观测到的写入结论**按 ASUS 收据语汇如实映射。
        // 已观察到的不确定（io 异常、收据缺失、混合失败）一律记 unknown，绝不写成功；该观测结论
        // 与"本次释放是否合格（oemRestoreVerified）"分开——未知仍是未知，但不等于"写入未发生"。
        var asusObservedReleaseWrite = Route?.RestoreStrategy == FanRestoreStrategy.AsusAcpiCurves
            ? asusReleaseWriteOutcome switch
            {
                "transported" => "hc-hardware-callback-returned-write-transmitted",
                "partial" => "hc-hardware-callback-returned-write-partial-asus-channel",
                "no-receipts" => "hc-hardware-callback-returned-write-unknown-no-receipts",
                "io-exception-unknown" => "hc-hardware-callback-returned-write-unknown-io-exception",
                "mixed-failed-unknown" => "hc-hardware-callback-returned-write-unknown-mixed",
                _ => "hc-hardware-callback-returned-readback-unconfirmed",
            }
            : null;
        if (oemRestoreVerified)
        {
            if (Route?.RestoreStrategy == FanRestoreStrategy.AsusAcpiCurves && asusOemReadbackConfirmed)
            {
                oemRestoreEvidence = "hc-default-table-readback";
                oemOwnershipStatus = "hc-default-table-readback-confirmed";
            }
            else
            {
                // This is deliberately the same success boundary as HC:
                // SetFanControl(false) returned through the real device
                // callback. GetFanCurve is diagnostic only and is not a
                // cross-firmware ownership ACK.
                oemRestoreEvidence = asusObservedReleaseWrite
                    ?? (Route?.RestoreStrategy == FanRestoreStrategy.MsiHcDefaultRelease
                        // FAN-936 §3：MSI 的合格证据是 HC 侧**结构化释放回读结论**（152→212 逐 bit），
                        // 不是"回调返回"；仍不是物理 RPM 确认，故 ownership 保持 physical-unknown。
                        ? "hc-msi-structured-release-returned"
                        : Route?.Evidence == FanEvidenceMode.CompatCallbackNoScope
                            // FAN-934 §4.A：非 ASUS 已审阅 HC 路线——证据是**软件回调合同**，
                            // 明确标注不属于物理确认，不用 ASUS 收据语汇冒充。
                            ? "hc-compat-route-callback-returned"
                            : "hc-hardware-callback-returned");
                oemOwnershipStatus = oemRestoreEvidence == "hc-hardware-callback-returned-write-transmitted"
                    ? "hc-callback-only-physical-unknown"
                    : Route?.RestoreStrategy == FanRestoreStrategy.AsusAcpiCurves
                        ? "hc-callback-write-outcome-unknown"
                        : "hc-callback-only-physical-unknown";
            }
        }
        else
        {
            // FAN-936 §3.2.2/§3.2.5：释放未被认定为合格（fail-closed），但**本次观测到的事实**
            // 仍须分栏如实记录——已观察到的 io 异常/收据缺失记 unknown，不得写成 verified，
            // 也不得与"写入未发生"合并。仅 ASUS 路线使用收据语汇，避免在未登记路由上复现
            // F1 的 compat 证书语汇。
            if (asusObservedReleaseWrite is not null) oemRestoreEvidence = asusObservedReleaseWrite;
            oemOwnershipStatus = "unknown-no-hc-contract";
        }
        return oemRestoreVerified;
    }


    public bool ApplyCurve(IReadOnlyList<FanNode> nodes) => OnStaBounded(() => ApplyCurveCore(nodes));

    private bool ApplyCurveCore(IReadOnlyList<FanNode> nodes)
    {
        lock (hardwareGate)
        {
        EnsureRealWriteSession();
        if (!oemBaselineCaptured)
            throw new FanApiException(409, "FAN_ROUTE_RESTORE_UNAVAILABLE", "尚未完成 HC 路线上下文初始化，拒绝写入");
        try
        {
            EnsureHcSessionReadyForControl();
        }
        catch (InvalidOperationException ex) when (ex.Message.StartsWith("HC_SESSION_ROUTE_LOST:", StringComparison.Ordinal))
        {
            throw new FanApiException(409, "HC_SESSION_ROUTE_LOST", "HC 风扇设备/路线标记已丢失，已拒绝写入");
        }
        // FAN-936 §5：写入前核对基线绑定，拒绝旧周期/旧实例/旧开机的快照。
        EnsureBaselineBindingForControl();
        ValidateCurve(nodes);
        oemRestoreVerified = false;
        oemRestoreEvidence = "none";
        oemReleaseActionKind = "not-attempted";
        oemReleaseActionEvidence = "none";
        oemOwnershipStatus = "unknown-no-hc-contract";
        asusReleaseWriteOutcome = "none";
        hcOemReleaseCallbackCompleted = false;
        asusOemReadbackConfirmed = false;
        var route = Route ?? throw new FanApiException(409, "FAN_UNSUPPORTED", "HC fan route 不在 YeMan 设备矩阵内");
        var duties = Enumerable.Range(0, 11).Select(temp => Interpolate(nodes, temp * 10)).ToArray();
        // FAN-929（2026-09-27 用户裁决）：把"AC/DC 电源档"对齐从 1 Hz 轮询移到**写时**。
        // 原 1 Hz watchdog 在电源线变化后重新捕获 HC 模板再套用曲线；现在只在本次写入发现
        // 电源线状态与记录不同（或记录未知）时，用**当前**状态重新捕获模板，再构建 profile。
        // 语义等价（仍是"按当前电源档的 OEM 模板建曲线"），触发者由 bridge 的 AC/DC 事件重放。
        if (profilePowerLineOnline is null || profilePowerLineOnline.Value != IsPowerLineOnline())
        {
            CaptureHcProfileTemplate();
            profilePowerLineOnline = IsPowerLineOnline();
        }
        var profile = BuildPowerProfile(duties, software: true);
        if (route.Kind is FanRouteKind.GenericDuty or FanRouteKind.GenericRpmTarget)
        {
            activeFanProfile = GetMember(profile, "FanProfile")
                ?? throw new InvalidOperationException("HC FanProfile unavailable");
            lastTemperatureC = null;
            lastDutyPercent = null;
        }
        else
        {
            DetachCpuTemperatureLoop();
        }

        // Dispatch through the same HC profile entry point that the original
        // PowerProfileManager uses. The Host only supplies the FanProfile;
        // Every fan-control write crosses the HC device callback.  Do not
        // reproduce vendor WMI/EC/ACPI sequences in this Host: HC owns the
        // software/hardware ordering, curve conversion and any device-level
        // prerequisite writes for every mapped route.
        // §19-C：写入收据按**本次操作作用域**消费——可确认的必要控制写失败不得报告控制成功；
        // 缺失/IoException 记 unknown（不写成成功，也不写成“写入一定未发生”）。
        var writeScope = BeginAsusWriteScope("enable-curve");
        try
        {
            ApplyPowerProfile(profile);
        }
        catch (Exception)
        {
            // 回调未返回：按路线模式结算（ASUS 消费本操作作用域；非 ASUS 记回调未返回）。
            _ = SettleOperationEvidence(writeScope, "enable-curve", callbackReturned: false);
            throw;
        }
        var writeVerdict = SettleOperationEvidence(writeScope, "enable-curve", callbackReturned: true);
        // Q1/Q2（2026-09-23 补充裁决）：本次控制写入的收据口径对外可见——partial 不再
        // 是"完全成功"，与竟态无关（同一映射也用于 restore 边界）。
        lastControlWriteEvidence = WriteEvidenceName(writeVerdict);
        if (writeVerdict.ExplicitFailure)
            throw new FanApiException(409, "FAN_CURVE_WRITE_FAILED",
                $"HC 风扇曲线必要写入失败，未建立控制: {writeVerdict.Detail}");
        // FAN-936 R1：回调返回只是必要条件。MSI 软件控制成功态必须由 HC 侧结构化结论支撑：
        // 风扇表读取/写入失败、或软件控制未 latch 时，不得对外报告"已建立控制"（fail-closed）。
        EnsureMsiSoftwareControlEstablished("enable-curve");
        // FAN-934 §4.A：诊断按**路线声明的证据模式**分流——非 ASUS 路线不得打印
        // "ASUS 收据缺失"这类误导诊断；支持性、控制提交、物理确认分列。
        if ((writeScope?.Mode ?? CurrentRouteEvidenceMode()) == FanEvidenceMode.AsusScopeReceipts)
        {
            // 2026-09-23：部分通道失败（至少一个通道已送达，如 RC73XA 的 Mid 通道固件不接受）
            // 不再致命——按 HC 能力库语义继续建立控制，但逐扇点名、不得报成功。
            if (writeVerdict.Partial)
            {
                Diagnostic?.Invoke("enable.asus-write-receipts-partial", new
                {
                    kind = writeVerdict.Kind,
                    detail = writeVerdict.Detail,
                    controlState = "partial-channel-evidence-not-success",
                });
            }
            if (writeVerdict.Unknown && !writeVerdict.Unsupported)
            {
                Diagnostic?.Invoke("enable.asus-write-receipts-unknown", new
                {
                    kind = writeVerdict.Kind,
                    detail = writeVerdict.Detail,
                    controlState = "unknown-not-verified",
                });
            }
        }
        else
        {
            Diagnostic?.Invoke(writeVerdict.ExplicitFailure
                ? "enable.compat-route-callback-failed"
                : writeVerdict.Unknown
                    ? "enable.compat-route-precondition-unsatisfied"
                    : "enable.compat-route-callback-contract", new
            {
                kind = writeVerdict.Kind,
                detail = writeVerdict.Detail,
                controlState = WriteEvidenceName(writeVerdict),
                scope = "software-callback-contract-not-physical-ack",
            });
        }
        hcProfileTemplate = profile;
        // HC's device-specific setup must succeed before this Host accepts a
        // temperature callback that could dispatch the first fan duty write.
        if (route.Kind is FanRouteKind.GenericDuty or FanRouteKind.GenericRpmTarget)
            EnsureCpuTemperatureLoop();
        activeCurveDuties = duties;
        EnsurePowerProfileWatchdog();
        return true;
        }
    }

    /**
     * HC does not define a cross-device hardware readback/ownership contract
     * for active fan curves. Lease renewal therefore proves the Host session
     * is still valid; it never turns a transient vendor EC/WMI/ACPI read into
     * a false ownership conflict.
     */
    public void VerifyActiveCurveSession()
    {
        // FAN-931 P0：心跳驱动的 STA 校验调用次数（P2A 的判定依据之一）。
        Interlocked.Increment(ref FanPerfCounters.StaVerifyRequests);
        OnStaBounded(VerifyActiveCurveSessionCore);
    }

    private void VerifyActiveCurveSessionCore()
    {
        lock (hardwareGate)
        {
            if (activeCurveDuties is null) return;
            EnsureHcSessionReadyForControl();
        }
    }

    public void RestoreOem() => OnStaBounded(RestoreOemCore);

    private void RestoreOemCore()
    {
        lock (hardwareGate)
        {
        if (operationTimedOut) throw new FanApiException(504, "HC_OPERATION_TIMEOUT", "HC 线程仍未返回，拒绝并发恢复调用");
        EnsureRestoreSession();
        if (!oemBaselineCaptured)
            throw new InvalidOperationException("FAN_ROUTE_RESTORE_UNAVAILABLE: HC 路线上下文未完成初始化");
        // FAN-936 §5：交还前先判会话就绪（设备/路线/前提标记），再判基线绑定——两者各自的
        // 失败原因都要如实暴露，不得让"基线绑定"埋掉"会话/设备已丢失"这一更早的事实。
        EnsureHcSessionReadyForControl();
        // FAN-936 §5：交还前同样核对基线绑定——不得用旧周期快照覆盖 MSI 前端/其它 OEM writer。
        EnsureBaselineBindingForControl();
        oemRestoreVerified = false;
        StopCpuTemperatureMonitor();
        Diagnostic?.Invoke("restore.hc-device-state", new
        {
            route = Route?.Kind.ToString(),
            backendIsOpen = IsOpen,
            hcDeviceIsOpen = device is null ? null : GetMember(device, "IsOpen"),
        });
        // Hardware mode is the sole OEM-release route.  It executes the
        // actual HC override for ASUS, MSI, Lenovo, GPD and all generic EC
        // devices; the Host never writes a replacement vendor command.
        // §19-C：本次交还写入的收据**只取本操作作用域**；明确失败不得报成功，
        // IoException 记为“是否发起未知”（不得描述成“写入一定未发生”），缺失记 unknown。
        var releaseScope = BeginAsusWriteScope("oem-restore");
        // FAN-936 R4：派发交还前先换发本次操作令牌，绑定当前 Host 实例 + 控制周期 + 操作序号；
        // HC 的释放结论必须回显同一串，否则本次恢复不得被认成成功（旧/迟到/错设备收据全拒）。
        BeginMsiReleaseOperation();
        // §3.3（FAN-925B）：主路径与回退路径的证据**独立绑定**，不机械覆盖。
        var primaryReleaseAction = OemReleaseAction.Unknown;
        var primaryReleaseEvidence = "not-attempted";
        try
        {
            // FAN-936 R2 section 2: MSI hands the fan channel back through HC's
            // dedicated fan release routine instead of the full
            // PowerProfileManager_Applied power-configuration callback. That
            // callback writes one Shift value (Set_Data(210), 0xC3->0xC4) through
            // SetShiftMode whenever MSI declares Shift support, which silently
            // rewrites the user's scenario during an OEM hand-back. HC's normal
            // power-configuration behaviour is preserved for genuine profile
            // applications; only this Host-driven release takes the narrow path.
            if (Route?.RestoreStrategy == FanRestoreStrategy.MsiHcDefaultRelease)
                DispatchMsiReleaseViaNarrowInterface();
            else
                ApplyPowerProfile(BuildPowerProfile(Array.Empty<double>(), software: false));
        }
        catch (Exception)
        {
            // 回调未返回：按路线模式结算（非 ASUS 记回调未返回的失败，供诊断/失败锁判据）。
            _ = SettleOperationEvidence(releaseScope, "oem-restore", callbackReturned: false);
            throw;
        }
        var releaseWrite = SettleOperationEvidence(releaseScope, "oem-restore", callbackReturned: true);
        asusReleaseWriteOutcome = releaseWrite.Kind;
        // §3.2（FAN-925B）：只消费**当次、对应路由**的 scope 收据来判释放动作。
        // 不消费回调返回位（`MarkHcOemReleaseCallbackCompleted` 只在走到末尾时置真），
        // 也不消费任何 HC 清理位 —— 那就是本批要挡掉的 "cleanup 冒充 release"（F02）。
        primaryReleaseAction = FanHostEngine.ClassifyReleaseAction(releaseWrite.Kind);
        primaryReleaseEvidence =
            $"hc-profile verdict={releaseWrite.Kind} receipts={releaseWrite.ReceiptCount} " +
            $"explicitFailure={releaseWrite.ExplicitFailure} unknown={releaseWrite.Unknown} " +
            $"noneTransported={releaseWrite.NoneTransported} detail={releaseWrite.Detail}";
        oemReleaseActionKind = FanHostEngine.ReleaseActionKindName(primaryReleaseAction);
        oemReleaseActionEvidence = primaryReleaseEvidence;
        // Q1/Q2（2026-09-23 补充裁决）：release 边界的收据口径与 enable 同一映射。
        lastControlWriteEvidence = WriteEvidenceName(releaseWrite);
        if (releaseWrite.ExplicitFailure)
        {
            // 2026-09-23 后 ExplicitFailure ⇔ 零通道送达（Partial 另立一类，不再致命）。
            var notHappened = releaseWrite.NoneTransported
                ? "HC OEM restore write did not happen"
                : "HC OEM restore write partially failed";
            throw new FanApiException(409, "OEM_RESTORE_FAILED", $"{notHappened}: {releaseWrite.Detail}");
        }
        // FAN-934 §4.A：诊断按路线声明的证据模式分流（非 ASUS 不再打印"ASUS 收据"诊断）。
        if ((releaseScope?.Mode ?? CurrentRouteEvidenceMode()) == FanEvidenceMode.AsusScopeReceipts)
        {
            if (releaseWrite.Partial)
            {
                // 部分通道失败：交还边界仍按能力库口径（HC 回调返回）继续走 Close；
                // 逐扇失败留在证据里，不写成"写入成功"。
                Diagnostic?.Invoke("restore.asus-write-receipts-partial", new
                {
                    kind = releaseWrite.Kind,
                    detail = releaseWrite.Detail,
                    writeOutcome = "partial-channel-evidence-not-success",
                });
            }
            if (releaseWrite.Unknown && !releaseWrite.Unsupported)
            {
                // 观测故障/缺失：不得当作 verified，也不得反过来写成“写入未发生”。
                Diagnostic?.Invoke("restore.asus-write-receipts-unknown", new
                {
                    kind = releaseWrite.Kind,
                    detail = releaseWrite.Detail,
                    physicalWrite = "unknown-not-proven-nor-refuted",
                });
            }
            else if (releaseWrite.Transported)
            {
                Diagnostic?.Invoke("restore.asus-write-receipts-transported", new { detail = releaseWrite.Detail });
            }
        }
        else
        {
            // 非 ASUS HC 路线：证据是**软件回调合同**，不是 ASUS 收据或物理确认。
            Diagnostic?.Invoke(releaseWrite.ExplicitFailure
                ? "restore.compat-route-callback-failed"
                : releaseWrite.Unknown
                    ? "restore.compat-route-precondition-unsatisfied"
                    : "restore.compat-route-callback-contract", new
            {
                kind = releaseWrite.Kind,
                detail = releaseWrite.Detail,
                writeOutcome = WriteEvidenceName(releaseWrite),
                scope = "software-callback-contract-not-physical-ack",
            });
        }
        // FAN-936 §3/§5（2026-10-01 裁决）：MSI 交还的**唯一**合格证书来自 HC 侧结构化释放结论
        // （`ReleaseMsiFanControl` 的 152→212 逐 bit「读整块 → 只改 bit7 → 写后回读」）。上面按
        // 兼容路线结算出的 `compat-route-without-scope` 只是"回调返回"，**不能**当 MSI 的释放证明；
        // 这里按 HC 的**本次开机**结构化结论重结算：ok ⇒ Proven，failed ⇒ Failed，
        // 缺失/陈旧/未知 ⇒ Unknown（fail-closed，绝不回落成 compat 成功）。
        if (Route?.RestoreStrategy == FanRestoreStrategy.MsiHcDefaultRelease)
        {
            var structured = ReadMsiStructuredRelease(out var structuredDetail);
            var structuredAction = FanHostEngine.ClassifyMsiReleaseStatus(structured?.Status);
            primaryReleaseAction = structuredAction;
            primaryReleaseEvidence =
                $"msi-structured[{structuredDetail}] status={structured?.Status ?? "<absent>"} " +
                $"fullSpeed152={structured?.FullSpeed152Status ?? "<absent>"} " +
                $"softwareControl212={structured?.SoftwareControl212Status ?? "<absent>"} " +
                $"hostInstanceId={structured?.HostInstanceId ?? "<absent>"} " +
                $"bootIdentity={structured?.BootIdentity ?? "<absent>"} " +
                $"summary={structured?.Summary ?? "<absent>"}";
            oemReleaseActionKind = structuredAction == OemReleaseAction.Proven
                ? "proven-by-msi-structured-release"
                : FanHostEngine.ReleaseActionKindName(structuredAction);
            oemReleaseActionEvidence = primaryReleaseEvidence;
            Diagnostic?.Invoke("restore.msi-structured-release", new
            {
                detail = structuredDetail,
                status = structured?.Status ?? "<absent>",
                fullSpeed152Status = structured?.FullSpeed152Status ?? "<absent>",
                softwareControl212Status = structured?.SoftwareControl212Status ?? "<absent>",
                hostInstanceId = structured?.HostInstanceId ?? "<absent>",
                bootIdentity = structured?.BootIdentity ?? "<absent>",
                classified = FanHostEngine.ReleaseActionKindName(structuredAction),
                scope = "software-bit-readback-contract-not-physical-rpm",
            });
        }
        // ★ 方案 D（2026-09-24 T0 根因）：HC 的 `SetFanControl(false)` 被 `if (!IsOpen) return;` 守卫，
        // 而 `IsOpen` 含 **HID 0x5A 绑定**。切换虚拟手柄会对 `vid_0b05&pid_1b4c` 复合设备做
        // unhide + PnP 端口循环（`hidhide.sweep-all-devices`）⇒ HID 真被拔掉 ⇒ `IsOpen` 回不到 true
        // ⇒ **上面的原生还原写入被静默吞掉**，OEM 交还失败（真机 18:57–19:05 零次 Close 即此）。
        // 此处补一条**只依赖 ACPI 句柄**（`\\.\ATKACPI`，不被 PnP 端口循环拔掉）的还原：
        // 同一个 HC `AsusACPI.SetFanCurve`，**不新增 EC 直写、不复制 HC 常量**；设备在场时不介入。
        var hcDeviceOpenForRestore = device is not null && GetMember(device, "IsOpen") is true;
        var acpiDirectRestoreOk = TryRestoreAsusCurvesViaAcpi(
            Route?.RestoreStrategy, hcDeviceOpenForRestore, out var acpiDirectRestoreKind, out var acpiDirectRestoreDetail);
        // §3.3（FAN-925B）：回退路径的证据**独立绑定**并参与合并，但不机械覆盖主路径结论。
        var fallbackReleaseAction = FanHostEngine.ParseReleaseAction(acpiDirectRestoreKind);
        var mergedReleaseAction = FanHostEngine.MergeReleaseActions(primaryReleaseAction, fallbackReleaseAction);
        if (mergedReleaseAction != primaryReleaseAction)
        {
            // 只有"主路径不是证明、回退给出了证明"时才让回退成为对外结论；证据里两条都留。
            oemReleaseActionKind = mergedReleaseAction == OemReleaseAction.Proven &&
                fallbackReleaseAction == OemReleaseAction.Proven &&
                primaryReleaseAction != OemReleaseAction.Proven
                ? "proven-by-host-hc-acpi-fallback"
                : FanHostEngine.ReleaseActionKindName(mergedReleaseAction);
        }
        oemReleaseActionEvidence =
            $"primary[{primaryReleaseEvidence}] fallback[{acpiDirectRestoreKind}] " +
            $"merged={FanHostEngine.ReleaseActionKindName(mergedReleaseAction)}";
        Diagnostic?.Invoke("restore.acpi-direct", new
        {
            route = Route?.Kind.ToString(),
            hcDeviceOpen = hcDeviceOpenForRestore,
            acpiDirectRestoreOk,
            acpiDirectRestoreKind,
            primaryReleaseAction = FanHostEngine.ReleaseActionKindName(primaryReleaseAction),
            mergedReleaseAction = FanHostEngine.ReleaseActionKindName(mergedReleaseAction),
            detail = acpiDirectRestoreDetail,
            nativeWriteOutcome = releaseWrite.Kind,
        });
        // §3.1/§3.3：主路径的显式失败必须保留（回退不得把它擦掉）。
        if (primaryReleaseAction == OemReleaseAction.Failed && mergedReleaseAction != OemReleaseAction.Proven)
            Diagnostic?.Invoke("restore.release-action-failed-preserved", new
            {
                primary = FanHostEngine.ReleaseActionKindName(primaryReleaseAction),
                fallback = acpiDirectRestoreKind,
                merged = FanHostEngine.ReleaseActionKindName(mergedReleaseAction),
            });
        // HC does not gate this callback on GetFanCurve readback. Xbox ROG
        // firmware can expose a table that differs byte-for-byte from HC's
        // compiled defaults even after SetFanControl(false) has returned.
        // Observe one readback for diagnostics, but never add a vendor-specific
        // fallback write or turn that optional observation into a restore
        // failure; doing so caused the real Host to retry forever and never
        // reach HC's subsequent Close() boundary.
        asusOemReadbackConfirmed = false;
        if (Route?.RestoreStrategy == FanRestoreStrategy.AsusAcpiCurves)
        {
            if (options.AsusReadbackEnabled)
            {
                asusOemReadbackConfirmed = ConfirmAsusOemReadback(out var restoreDetail);
                Diagnostic?.Invoke(asusOemReadbackConfirmed
                    ? "restore.asus-default-readback-confirmed"
                    : "restore.asus-default-readback-unconfirmed", new { detail = restoreDetail });
            }
            else
            {
                // §18.2-C：该可选观察的同步链没有内建时限，实测可在未决 I/O 上无限期等待；
                // 默认不再从自动 restore/close 必经路径发起。保留方法与显式入口（--asus-readback），
                // 并如实记录 not-attempted/unknown，不把未知写成确认。
                asusOemReadbackConfirmed = false;
                Diagnostic?.Invoke("restore.asus-default-readback-not-attempted", new
                {
                    reason = "optional-observation-not-attempted-by-default",
                    readback = "not-attempted/unknown",
                    enableWith = "--asus-readback",
                });
            }
        }
        MarkHcOemReleaseCallbackCompleted();
        if (!ConfirmOemRestore())
            throw new InvalidOperationException("HC OEM restore did not satisfy the route release contract");
        activeCurveDuties = null;
        }
    }

    private bool IsRouteStillReady()
    {
        var route = Route;
        return route is not null && route.HcCallbackReady && route.RestoreStrategy == baselineStrategy
            && string.Equals(baselineRestoreRoute, FactoryType, StringComparison.Ordinal);
    }

    private string BuildSessionRouteMarker() =>
        $"{FactoryType}|{Route?.Kind}|{baselineStrategy}";

    private bool IsHcSessionReadyForControl(out string reason, bool requireHcReportedOpen = true)
    {
        if (!IsOpen)
        {
            reason = "backend-is-open-false";
            return false;
        }
        if (device is null || sessionDeviceReference is null ||
            !ReferenceEquals(device, sessionDeviceReference))
        {
            reason = "device-reference-marker-lost";
            return false;
        }
        if (!oemBaselineCaptured || !IsRouteStillReady())
        {
            reason = "route-baseline-marker-lost";
            return false;
        }
        var currentMarker = BuildSessionRouteMarker();
        if (!string.Equals(sessionRouteMarker, currentMarker, StringComparison.Ordinal))
        {
            reason = "session-route-marker-lost";
            return false;
        }
        // HC routes do not all expose the same public marker. When a route
        // does expose IsOpen, however, a false value is authoritative HID /
        // device loss even if YeMan's backend bool is still true.
        if (requireHcReportedOpen && GetMember(device, "IsOpen") is bool hcIsOpen && !hcIsOpen)
        {
            reason = "hc-device-is-open-false";
            return false;
        }
        reason = "ready";
        return true;
    }

    private void EnsureHcSessionReadyForControl()
    {
        if (!IsHcSessionReadyForControl(out var reason))
            throw new InvalidOperationException($"HC_SESSION_ROUTE_LOST: {reason}");
    }

    private void EnsureHcSessionReadyForOpenEvents()
    {
        if (!IsHcSessionReadyForControl(out var reason, requireHcReportedOpen: false))
            throw new InvalidOperationException($"HC_SESSION_ROUTE_LOST: {reason}");
    }

    /**
     * B4 重开收据（HC 回函 H4，**推翻**本线此前的 `OpenCalled ∧ OpenEventsCalled`）
     * + §4（FAN-925B）**绑定核对**。
     * 真正的收据 = `LastCompatEntryOperationId` + `TryWaitDeviceOpenReceipt(opId, budget, out receipt)`，
     * 判定 = `Outcome == Completed` ∧ 四位副作用齐全 ∧ `UncertainSideEffects`/`LateSideEffects` 为空，
     * 且**必须是本次重开的操作**：hostInstance 相同、恢复周期未变、会话代际比绑定时更新、
     * 操作 id 不等于重开前拍的基线（否则"最近一次 Completed"会被当成本次恢复）。
     * 收据 API 缺失 / 超时 / 非终态 / 任一条绑定不符 ⇒ **不宣称已重开**。
     */
    internal bool TryObserveReopenReceipt(
        FanHostEngine.ReopenBinding? binding,
        string currentHostInstanceId,
        string? currentCycleId,
        long currentSessionGeneration,
        int budgetMs,
        out string detail)
    {
        detail = "reopen:receipt-api-absent";
        try
        {
            if (binding is null) { detail = "reopen:no-binding"; return false; }
            if (device is null) { detail = "reopen:no-device"; return false; }
            var operationId = GetMember(device, "LastCompatEntryOperationId") as string;
            // §4：绑定核对在"读收据"之前 —— 拒绝旧成功/旧 Host/跨实例/未换代/缺字段。
            var rejection = FanHostEngine.ReopenBindingRejection(
                binding.HostInstanceId, currentHostInstanceId,
                binding.CycleId, currentCycleId,
                binding.SessionGeneration, currentSessionGeneration,
                binding.BaselineOperationId, operationId);
            if (rejection is not null)
            {
                detail = $"{rejection} op={operationId ?? "<none>"} binding[{binding.Describe()}] " +
                    $"current[host={currentHostInstanceId} cycle={currentCycleId ?? "<none>"} gen={currentSessionGeneration}]";
                return false;
            }
            var method = device.GetType()
                .GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(m => m.Name == "TryWaitDeviceOpenReceipt" && m.GetParameters().Length == 3);
            if (method is null) return false;
            var args = new object?[] { operationId, budgetMs, null };
            if (method.Invoke(device, args) is not true || args[2] is null)
            {
                detail = $"reopen:no-receipt op={operationId} {binding.Describe()}";
                return false;
            }
            var receipt = args[2]!;
            var outcome = GetMember(receipt, "Outcome")?.ToString();
            var deviceBound = GetMember(receipt, "DeviceBoundByThisOperation") is true;
            var hidOpened = GetMember(receipt, "HidOpenedByThisOperation") is true;
            var readLoop = GetMember(receipt, "ReadLoopStartedByThisOperation") is true;
            var remap = GetMember(receipt, "RemapAppliedByThisOperation") is true;
            var uncertain = GetMember(receipt, "UncertainSideEffects")?.ToString();
            var late = GetMember(receipt, "LateSideEffects")?.ToString();
            detail = $"reopen:receipt op={operationId} outcome={outcome ?? "unknown"} bound={deviceBound} " +
                $"hid={hidOpened} readLoop={readLoop} remap={remap} " +
                $"uncertain={uncertain ?? "unknown"} late={late ?? "unknown"} {binding.Describe()}";
            return FanHostEngine.ReopenReceiptAccepted(outcome, deviceBound, hidOpened, readLoop, remap, uncertain, late);
        }
        catch (Exception ex)
        {
            detail = "reopen:probe-fault " + DescribeException(ex);
            return false;
        }
    }

    internal static bool SessionRouteMarkerMatchesForSelfTest(
        string? expected,
        string? observed,
        bool backendIsOpen,
        bool? hcDeviceIsOpen,
        bool baselineReady) =>
        backendIsOpen && baselineReady &&
        string.Equals(expected, observed, StringComparison.Ordinal) &&
        hcDeviceIsOpen != false;

    internal static bool SessionRouteMarkerReadyForOpenEventsForSelfTest(
        string? expected,
        string? observed,
        bool backendIsOpen,
        bool? hcDeviceIsOpen,
        bool baselineReady) =>
        backendIsOpen && baselineReady &&
        string.Equals(expected, observed, StringComparison.Ordinal);

    private void MarkHcOemReleaseCallbackCompleted()
    {
        // The immediately preceding HC Hardware callback plus any required
        // route-specific verification is the complete release action for the
        // selected device. ASUS default-table readback has already completed
        // before this marker is set.
        hcOemReleaseCallbackCompleted = true;
    }

    private bool ConfirmAsusOemReadback(out string detail)
    {
        detail = "";
        var expectedCpu = GetStaticMember(device?.GetType(), "defaultCPUFan") as byte[];
        var expectedGpu = GetStaticMember(device?.GetType(), "defaultGPUFan") as byte[];
        if (expectedCpu is null || expectedGpu is null || expectedCpu.Length != 16 || expectedGpu.Length != 16)
        {
            detail = "HC ROG 默认曲线不可读";
            return false;
        }

        // One bounded observation only. The HC callback above remains the
        // authoritative release action; this readback is evidence enrichment,
        // not a second write path and not a reason to block Close().
        return TryReadAsusDefaults(expectedCpu, expectedGpu, out detail);
    }

    private bool TryReadAsusDefaults(byte[] expectedCpu, byte[] expectedGpu, out string detail)
    {
        detail = "";
        try
        {
            // §17.3 仅自测（阻塞注入）：本机无 HC，故注入时跳过 HC 类型解析；其余路径与生产逐行相同
            // （同一 TryReadAsusDefaults 体、同一三次读取顺序、同一比较与上报）。
            var acpi = AsusCurveReadProbeForSelfTest is null
                ? FindType("HandheldCompanion.Devices.ASUS.AsusACPI")
                    ?? throw new MissingMemberException("HC AsusACPI not found")
                : null!;
            var fanType = AsusCurveReadProbeForSelfTest is null
                ? FindType("AsusFan")
                    ?? throw new MissingMemberException("HC AsusFan not found")
                : null!;
            var cpu = ReadAsusCurve(acpi, fanType, "CPU");
            var gpu = ReadAsusCurve(acpi, fanType, "GPU");
            var mid = ReadAsusCurve(acpi, fanType, "Mid");
            var cpuOk = cpu.SequenceEqual(expectedCpu);
            var gpuOk = gpu.SequenceEqual(expectedGpu);
            var midOk = mid.SequenceEqual(expectedCpu);
            if (cpuOk && gpuOk && midOk) return true;
            detail = $"CPU={cpuOk};GPU={gpuOk};Mid={midOk}";
            return false;
        }
        catch (Exception ex)
        {
            detail = DescribeException(ex);
            return false;
        }
    }

    private byte[] ReadAsusCurve(Type acpi, Type fanType, string fanName)
    {
        // §17.3：这条链（HC GetFanCurve → DeviceSet/DeviceGetBuffer → DeviceIoControl）是**同步**调用，
        // 没有内建时限。仅自测注入底层读取结果/阻塞，用于"阻塞注入测试"；生产默认 null ⇒ 行为不变。
        if (AsusCurveReadProbeForSelfTest is { } probeRead)
        {
            var attempt = Interlocked.Increment(ref asusCurveReadAttempts) - 1;
            var (ok, data, error) = probeRead(attempt, fanName);
            if (!ok) throw new IOException(error ?? "selftest-asus-curve-read-failed");
            return data ?? throw new InvalidOperationException($"selftest probe returned no data for {fanName}");
        }

        var fan = Enum.Parse(fanType, fanName);
        return InvokeStaticMember(acpi, "GetFanCurve", fan, 0) as byte[]
            ?? throw new InvalidOperationException($"HC AsusACPI.GetFanCurve({fanName}) returned no data");
    }

    /**
     * 方案 D（2026-09-24，T0 根因修复）：**还原改走直接 `AsusACPI.SetFanCurve`**。
     *
     * 根因（见 Docs\Tasks\Fan\FAN-920\T0-FANHOST-LIFETIME-COUPLED-TO-PARENT-20260924.md）：
     * HC 的 `SetFanControl(false)`（`ROGAlly.cs:370-372`）被 `if (!IsOpen) return;` 守卫，
     * 而 `IsOpen` 含 **HID 0x5A 绑定**。切换虚拟手柄会对 `vid_0b05&pid_1b4c` 复合设备做
     * unhide + PnP 端口循环（`hidhide.sweep-all-devices`，`native\main.cpp:15654-15675`），
     * HID 被**真正拔掉** ⇒ `IsOpen` 回不到 true ⇒ 还原写入被**静默吞掉** ⇒ OEM 交还失败。
     * 但 `AsusACPI.SetFanCurve`（`AsusACPI.cs:420-450`）**自身无任何 IsOpen 守卫**，其句柄是
     * `\\.\ATKACPI`（ACPI 设备节点，**不被 PnP 端口循环拔掉**）⇒ 该写入在 HID 缺席时依然可行。
     *
     * 纪律（不越权、不复制常量）：
     *   ① 只在本路线 HC 原生路径**无法写入**时启用（`hcDeviceOpen == false`）；设备在场时仍走 HC 原生 F4；
     *   ② 默认曲线**反射读** `ROGAlly.defaultCPUFan/defaultGPUFan`，不把 HC 常量抄进本宿主（避免版本漂移）；
     *   ③ 只调 HC 自己的公开 API（与 HC 原生 F4 同一个 `AsusACPI.SetFanCurve`），**不自造 ACPI 命令、不新增 EC 直写**；
     *   ④ `AsusACPI` 句柄不可用时**如实报 not-attempted**，不得报成功。
     */
    private bool TryRestoreAsusCurvesViaAcpi(
        FanRestoreStrategy? strategy, bool hcDeviceOpen, out string actionKind, out string detail)
    {
        actionKind = "not-attempted";
        detail = "";
        if (strategy != FanRestoreStrategy.AsusAcpiCurves)
        {
            detail = "not-applicable:route-is-not-asus-acpi-curves";
            actionKind = "not-applicable-route";
            return false;
        }
        if (UsesBackendFanWriter)
        {
            // HC-SLIM-01 R3 §6.2② 单一 writer：backend provider 下 ASUS 曲线还原已由
            // ApplyAsusCurveViaBackend/RestoreDefaultCurves 承担；本路径不得再产生第二次写入。
            detail = "skipped:backend-provider-is-single-writer";
            actionKind = "not-applicable-single-writer-backend-provider";
            return false;
        }
        if (hcDeviceOpen)
        {
            // D4：设备在场 ⇒ 保留 HC 原生 F4 为主路径，本路径不介入（不产生第二次写入）。
            detail = "skipped:hc-native-path-available";
            actionKind = "skipped-hc-native-path-available";
            return false;
        }
        if (AsusDirectRestoreProbeForSelfTest is { } probe)
        {
            var (attempted, ok, probeDetail) = probe();
            detail = probeDetail;
            actionKind = ok
                ? "proven-by-host-hc-acpi-fallback"
                : FanHostEngine.ReleaseActionKindName(OemReleaseAction.Unknown);
            return attempted && ok;
        }
        // §3.3（FAN-925B）：回退路径必须给出**结构化收据**，否则"有回退尝试"会被当成
        // 与主路径等价的成功证据。这里复用 HC 同一套 scope/收据能力，独立标
        // `host-hc-acpi-fallback`；**不再**把 `SetFanCurve` 的非负返回码当成
        // "TransportedComplete"——HC 的 `Status` 语义才是收据，正负号不是传输证明。
        var fallbackScope = BeginAsusWriteScope("host-hc-acpi-fallback");
        try
        {
            var acpi = FindType("HandheldCompanion.Devices.ASUS.AsusACPI")
                ?? throw new MissingMemberException("HC AsusACPI not found");
            var fanType = FindType("AsusFan")
                ?? throw new MissingMemberException("HC AsusFan not found");
            if (GetStaticBool(acpi, "IsOpen") != true)
            {
                // 句柄真的不可用 ⇒ 不得假装写成功。
                detail = "not-attempted:asus-acpi-handle-not-open";
                actionKind = FanHostEngine.ReleaseActionKindName(OemReleaseAction.Unknown);
                _ = CompleteAsusWriteScope(fallbackScope, "host-hc-acpi-fallback");
                return false;
            }
            var deviceType = device?.GetType()
                ?? throw new InvalidOperationException("FAN_ROUTE_DEVICE_UNAVAILABLE");
            var cpu = GetStaticFieldBytes(deviceType, "defaultCPUFan")
                ?? throw new MissingMemberException(deviceType.FullName, "defaultCPUFan");
            var gpu = GetStaticFieldBytes(deviceType, "defaultGPUFan")
                ?? throw new MissingMemberException(deviceType.FullName, "defaultGPUFan");
            foreach (var (fanName, curve) in new[] { ("CPU", cpu), ("GPU", gpu), ("Mid", cpu) })
            {
                var fan = Enum.Parse(fanType, fanName);
                _ = InvokeStaticMember(acpi, "SetFanCurve", fan, curve);
            }
            var fallbackWrite = CompleteAsusWriteScope(fallbackScope, "host-hc-acpi-fallback");
            var fallbackAction = FanHostEngine.ClassifyReleaseAction(fallbackWrite.Kind);
            // §3.3：唯一判定入口 —— 由当次 scope 收据决定，不由返回码正负决定。
            var fallbackProven = FanHostEngine.AcpiFallbackProven(fallbackWrite.Kind);
            actionKind = fallbackProven
                ? "proven-by-host-hc-acpi-fallback"
                : FanHostEngine.ReleaseActionKindName(fallbackAction);
            detail =
                $"acpi-direct scope=host-hc-acpi-fallback verdict={fallbackWrite.Kind} " +
                $"receipts={fallbackWrite.ReceiptCount} detail={fallbackWrite.Detail}";
            return fallbackProven;
        }
        catch (Exception ex)
        {
            _ = CompleteAsusWriteScope(fallbackScope, "host-hc-acpi-fallback");
            actionKind = FanHostEngine.ReleaseActionKindName(OemReleaseAction.Unknown);
            detail = "faulted:" + DescribeException(ex);
            return false;
        }
    }

    /** 反射读**静态**字段（用于 `ROGAlly.defaultCPUFan/defaultGPUFan`，`private static byte[]`）。 */
    private static byte[]? GetStaticFieldBytes(Type? type, string name)
    {
        if (type is null) return null;
        for (var t = type; t is not null; t = t.BaseType)
        {
            var field = t.GetField(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.DeclaredOnly);
            if (field?.GetValue(null) is byte[] bytes) return bytes;
        }
        return null;
    }

    /** 反射读**静态** bool（用于 `AsusACPI.IsOpen` —— ACPI 句柄，独立于 HID）。 */
    private static bool? GetStaticBool(Type? type, string name)
    {
        if (type is null) return null;
        var property = type.GetProperty(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static);
        if (property is not null && property.GetValue(null) is bool fromProperty) return fromProperty;
        var field = type.GetField(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static);
        return field?.GetValue(null) as bool?;
    }

    /** 仅自测：替换"直接 ACPI 还原"整段（可注入缺句柄/失败/成功）。生产为 null ⇒ 行为不变。 */
    internal static Func<(bool Attempted, bool Ok, string Detail)>? AsusDirectRestoreProbeForSelfTest { get; set; }

    /**
     * 方案 D 自测（2026-09-24）：判定与诚实性契约。**断言失败即抛异常（承重）**。
     *   ① 非 AsusAcpiCurves 路线 ⇒ not-applicable（不越权到其它路线）；
     *   ② `hcDeviceOpen == true` ⇒ **跳过**（D4：设备在场时 HC 原生 F4 为主，不产生第二次写入）；
     *   ③ `hcDeviceOpen == false` + 写入成功 ⇒ 走直接 ACPI 路径（这正是被 `IsOpen` 吞掉的那条路）；
     *   ④ 句柄不可用/写入失败 ⇒ 返回 false 且 detail 如实（**不得报成功**）。
     */
    internal static IReadOnlyList<string> RunAsusDirectRestoreSelfTest()
    {
        var checks = new List<string>();
        void Assert(bool ok, string message)
        {
            if (!ok) throw new InvalidOperationException("asus-direct-restore-selftest FAILED: " + message);
        }

        var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        try
        {
            // ① 非 AsusAcpiCurves 路线：不介入
            Assert(!backend.TryRestoreAsusCurvesViaAcpiForSelfTest(FanRestoreStrategy.GpdWin4HcRelease, true, out var naKind, out var naDetail) &&
                   naDetail.StartsWith("not-applicable", StringComparison.Ordinal) &&
                   naKind == "not-applicable-route",
                $"non-asus route must be not-applicable, got '{naDetail}' kind='{naKind}'");
            checks.Add("asus-direct-restore-selftest: non-asus route is not-applicable OK");

            // ② 设备在场：跳过（D4）
            Assert(!backend.TryRestoreAsusCurvesViaAcpiForSelfTest(FanRestoreStrategy.AsusAcpiCurves, true, out var skippedKind, out var skippedDetail) &&
                   skippedDetail == "skipped:hc-native-path-available" &&
                   skippedKind == "skipped-hc-native-path-available",
                $"device-open must skip direct path, got '{skippedDetail}' kind='{skippedKind}'");
            checks.Add("asus-direct-restore-selftest: device-open skips direct path (HC native F4 stays primary) OK");

            // ③ HID 缺席 + 写入成功 ⇒ 直接 ACPI 路径生效（正是被 IsOpen 静默吞掉的那条路）
            AsusDirectRestoreProbeForSelfTest = () => (true, true, "acpi-direct:CPU=TransportedComplete,GPU=TransportedComplete,Mid=TransportedComplete");
            Assert(backend.TryRestoreAsusCurvesViaAcpiForSelfTest(FanRestoreStrategy.AsusAcpiCurves, false, out var okKind, out var okDetail) &&
                   okDetail.Contains("TransportedComplete", StringComparison.Ordinal) &&
                   okKind == "proven-by-host-hc-acpi-fallback",
                $"hid-absent must attempt direct acpi restore, got '{okDetail}'");
            checks.Add("asus-direct-restore-selftest: HID-absent attempts direct AsusACPI restore OK");

            // ④ 句柄不可用 ⇒ 如实 not-attempted，不得报成功
            AsusDirectRestoreProbeForSelfTest = () => (false, false, "not-attempted:asus-acpi-handle-not-open");
            Assert(!backend.TryRestoreAsusCurvesViaAcpiForSelfTest(FanRestoreStrategy.AsusAcpiCurves, false, out var notAttemptedKind, out var notAttempted) &&
                   notAttempted.StartsWith("not-attempted", StringComparison.Ordinal) &&
                   notAttemptedKind == "unknown-release-action",
                $"closed acpi handle must be not-attempted, got '{notAttempted}' kind='{notAttemptedKind}'");
            checks.Add("asus-direct-restore-selftest: closed ACPI handle reports not-attempted (never success) OK");

            // ⑤ §3.3（FAN-925B）：回退尝试"有发起但无收据"不得被报成证明。
            //    注入 attempted=true / ok=false ⇒ 动作分类必须是 unknown，不得是 proven。
            AsusDirectRestoreProbeForSelfTest = () => (true, false, "acpi-direct scope=host-hc-acpi-fallback verdict=no-receipts receipts=0");
            Assert(!backend.TryRestoreAsusCurvesViaAcpiForSelfTest(FanRestoreStrategy.AsusAcpiCurves, false, out var unresolvedKind, out var unresolvedDetail) &&
                   unresolvedKind == "unknown-release-action" &&
                   !unresolvedKind.Contains("proven", StringComparison.Ordinal),
                $"fallback attempt without receipts must stay unknown, got '{unresolvedKind}'");
            checks.Add($"asus-direct-restore-selftest: fallback-without-receipts stays unknown kind='{unresolvedKind}' OK");
        }
        finally
        {
            AsusDirectRestoreProbeForSelfTest = null;
        }
        return checks;
    }

    internal bool TryRestoreAsusCurvesViaAcpiForSelfTest(
        FanRestoreStrategy strategy, bool hcDeviceOpen, out string actionKind, out string detail) =>
        TryRestoreAsusCurvesViaAcpi(strategy, hcDeviceOpen, out actionKind, out detail);

    /** 仅自测：把 restore 路径上的同步曲线读取替换为可控委托（可阻塞/可失败/可成功）。生产不设置。 */
    internal static Func<int, string, (bool Ok, byte[]? Data, string? Error)>? AsusCurveReadProbeForSelfTest { get; set; }
    private int asusCurveReadAttempts;

    /** 自测专用包装：直接验证生产函数 `TryReadAsusDefaults`（同一实现，不另写同形副本）。 */
    internal bool TryReadAsusDefaultsForSelfTest(byte[] expectedCpu, byte[] expectedGpu, out string detail) =>
        TryReadAsusDefaults(expectedCpu, expectedGpu, out detail);

    /**
     * §17.3：restore 诊断曲线读取的**阻塞注入**测试。
     *
     * 事实：`ConfirmAsusOemReadback` → `TryReadAsusDefaults` → `ReadAsusCurve` → HC `GetFanCurve`
     * → `DeviceIoControl` 全程同步，这条链**没有内建时限**。断言：
     *   ① 底层读未返回时，本层**不会**自行超时返回（实测超过 1.2 s 仍在内）；
     *   ② 阻塞期间不得重复读取（不许"边等边重试"）；
     *   ③ 失败（含阻塞结束后的失败）必须如实返回"未确认"，不得声称恢复成功；
     *   ④ 读取顺序与次数如实记录：首个失败会中止整轮观测（实测 attempts=1，即本层不重试整轮）；
     *      全部成功时每台风扇**恰好一次**（CPU/GPU/Mid=3），部分不匹配时同样恰好 3 次并给出逐台风扇结论。
     * 局限（如实声明）：真实 `DeviceIoControl` 的永久阻塞无法在本机产生（无 HC、无设备）；
     * 注入点就位于**同一调用位置**，注入的是"底层读不返回"这一条件本身。
     */
    internal static IReadOnlyList<string> RunAsusCurveReadBlockingInjectionSelfTest()
    {
        var checks = new List<string>();
        var expectedCpu = Enumerable.Range(0, 16).Select(index => (byte)(10 + index)).ToArray();
        var expectedGpu = Enumerable.Range(0, 16).Select(index => (byte)(60 + index)).ToArray();
        using var released = new ManualResetEventSlim(false);
        using var entered = new ManualResetEventSlim(false);
        var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        try
        {
            // ---- 阶段 A：阻塞注入（底层读不返回）----
            AsusCurveReadProbeForSelfTest = (attempt, _) =>
            {
                if (attempt == 0)
                {
                    entered.Set();
                    released.Wait(8000);            // 阻塞注入：模拟底层读未返回
                }
                return (false, null, "selftest-simulated-blocking-read");
            };

            var blockedOutcome = true;
            string? blockedDetail = null;
            var returnedAtMs = -1.0;
            var started = Stopwatch.GetTimestamp();
            var worker = new Thread(() =>
            {
                blockedOutcome = backend.TryReadAsusDefaultsForSelfTest(expectedCpu, expectedGpu, out var reported);
                blockedDetail = reported;
                returnedAtMs = (Stopwatch.GetTimestamp() - started) * 1000d / Stopwatch.Frequency;
            })
            { IsBackground = true };
            worker.Start();

            if (!entered.Wait(3000))
                throw new InvalidOperationException("asus-curve-read-blocking-injection: 注入的底层读从未被调用");
            Thread.Sleep(1200);
            if (returnedAtMs >= 0)
                throw new InvalidOperationException(
                    $"asus-curve-read-blocking-injection: 底层读未返回时本层却已返回（存在内建时限？）returnedAtMs={returnedAtMs:F0}");
            var attemptsWhileBlocked = Volatile.Read(ref backend.asusCurveReadAttempts);
            if (attemptsWhileBlocked != 1)
                throw new InvalidOperationException(
                    $"asus-curve-read-blocking-injection: 阻塞期间不得重复读取，实测 {attemptsWhileBlocked}");

            released.Set();
            if (!worker.Join(6000))
                throw new InvalidOperationException("asus-curve-read-blocking-injection: 释放后调用方未返回（疑似挂住）");
            if (blockedOutcome || string.IsNullOrWhiteSpace(blockedDetail))
                throw new InvalidOperationException(
                    $"asus-curve-read-blocking-injection: 未确认时不得声称成功 outcome={blockedOutcome} detail='{blockedDetail}'");
            var attemptsAfterBlock = Volatile.Read(ref backend.asusCurveReadAttempts);
            if (attemptsAfterBlock != 1)
                throw new InvalidOperationException(
                    $"asus-curve-read-blocking-injection: 首个失败应中止整轮观测（本层不重试整轮），attempts={attemptsAfterBlock}");
            checks.Add(
                $"asus-curve-read-blocking-injection[blocked] blockedNotReturnedWithinMs=1200 attemptsWhileBlocked={attemptsWhileBlocked} " +
                $"returnedAtMs={returnedAtMs:F0} attemptsAfterBlock={attemptsAfterBlock} outcome={blockedOutcome} detail='{blockedDetail}' " +
                $"verdict=NO-INTERNAL-TIMEOUT-AND-NO-FALSE-SUCCESS");

            // ---- 阶段 B：全部匹配 ⇒ 必须确认成功，且每台风扇恰好一次 ----
            Interlocked.Exchange(ref backend.asusCurveReadAttempts, 0);
            AsusCurveReadProbeForSelfTest = (attempt, _) => attempt switch
            {
                0 => (true, expectedCpu.ToArray(), null),
                1 => (true, expectedGpu.ToArray(), null),
                _ => (true, expectedCpu.ToArray(), null),
            };
            var successOutcome = backend.TryReadAsusDefaultsForSelfTest(expectedCpu, expectedGpu, out var successDetail);
            var successAttempts = Volatile.Read(ref backend.asusCurveReadAttempts);
            if (!successOutcome || successAttempts != 3)
                throw new InvalidOperationException(
                    $"asus-curve-read-blocking-injection: 全部匹配时应确认成功且恰好 3 次读取 outcome={successOutcome} attempts={successAttempts} detail='{successDetail}'");
            checks.Add(
                $"asus-curve-read-blocking-injection[matched] outcome={successOutcome} attempts={successAttempts} " +
                $"detail='{successDetail}' verdict=CONFIRMED-ONCE-PER-FAN");

            // ---- 阶段 C：部分不匹配 ⇒ 不得确认，并给出逐台风扇结论 ----
            Interlocked.Exchange(ref backend.asusCurveReadAttempts, 0);
            AsusCurveReadProbeForSelfTest = (attempt, _) => attempt switch
            {
                0 => (true, expectedCpu.ToArray(), null),
                1 => (true, new byte[16], null),                 // GPU 不匹配
                _ => (true, expectedCpu.ToArray(), null),
            };
            var mismatchOutcome = backend.TryReadAsusDefaultsForSelfTest(expectedCpu, expectedGpu, out var mismatchDetail);
            var mismatchAttempts = Volatile.Read(ref backend.asusCurveReadAttempts);
            if (mismatchOutcome || mismatchAttempts != 3 ||
                !mismatchDetail.Contains("CPU=True", StringComparison.Ordinal) ||
                !mismatchDetail.Contains("GPU=False", StringComparison.Ordinal))
                throw new InvalidOperationException(
                    $"asus-curve-read-blocking-injection: 部分不匹配必须如实报告 outcome={mismatchOutcome} " +
                    $"attempts={mismatchAttempts} detail='{mismatchDetail}'");
            checks.Add(
                $"asus-curve-read-blocking-injection[partial-mismatch] outcome={mismatchOutcome} attempts={mismatchAttempts} " +
                $"detail='{mismatchDetail}' verdict=NOT-CONFIRMED-WITH-PER-FAN-EVIDENCE");
        }
        finally
        {
            released.Set();
            AsusCurveReadProbeForSelfTest = null;
            backend.Dispose();
        }
        return checks;
    }

    private static string DescribeException(Exception ex) =>
        $"{ex.GetType().Name}: {ex.Message}";

    private object BuildPowerProfile(double[] duties, bool software, object? templateOverride = null)
    {
        // FAN-934 R2 §3-B：唯一自测 HC 边界（默认关闭）。生产路径 hcBoundaryForSelfTest
        // 恒为 null，走下方真实 HC FanMode/FanProfile 构造。
        if (hcBoundaryForSelfTest is { } selfTestProfileBoundary && templateOverride is null)
            return selfTestProfileBoundary.BuildProfile(duties, software);
        var fanModeType = FindType("HandheldCompanion.Misc.FanMode")
            ?? throw new MissingMemberException("HC FanMode not found");
        var template = templateOverride ?? hcProfileTemplate;
        if (template is null)
            throw new InvalidOperationException("HC power-profile context was not captured before fan control");
        // Clone HC's own device profile rather than constructing a new one.
        // Device callbacks may use Guid/OEMPowerMode alongside FanProfile.
        var profile = CloneHcPowerProfilePreservingFanState(template);
        var fan = GetMember(profile, "FanProfile");
        if (fan is null) throw new InvalidOperationException("HC FanProfile construction failed");
        // Keep the profile's original HC FanProfile object and its public
        // smoothing/Tjmax settings. Only replace the 11-point curve through
        // HC's own validation method; do not synthesize a parallel profile.
        if (duties.Length == 11)
            Invoke(fan, "SetFanSpeed", duties);
        SetMember(fan, "fanMode", Enum.Parse(fanModeType, software ? "Software" : "Hardware"));
        SetMember(profile, "FanProfile", fan);
        return profile;
    }

    private object BuildFanDispatchEvidence(object profile, string sourceName)
    {
        var fan = GetMember(profile, "FanProfile");
        var requested = fan is null
            ? Array.Empty<double>()
            : GetMember(fan, "fanSpeeds") as double[] ?? Array.Empty<double>();
        var isSoftware = string.Equals(
            Convert.ToString(fan is null ? null : GetMember(fan, "fanMode")),
            "Software",
            StringComparison.OrdinalIgnoreCase);
        var asusNormalization = Route?.RestoreStrategy == FanRestoreStrategy.AsusAcpiCurves;
        var normalized = asusNormalization
            ? requested.Select(value => Math.Clamp(value, 0d, 99d)).ToArray()
            : Array.Empty<double>();
        var phase = isSoftware ? "F3-controlled" : "F4-oem-handoff";
        // §4.C：命令通道按实际 provider 路线定义（ROG=CPU/GPU/Mid 命令点；MSI=CPU/GPU 表通道；
        // GPD=两路 duty 逻辑通道 Fan1/Fan2；其余=aggregate）。不硬填 CPU/GPU/Mid 以免捏造第三风扇。
        var fanIds = ResolveFanCommandChannels(Route?.RestoreStrategy).ToArray();
        var perFan = fanIds.Select(fanId => new
        {
            fanId,
            requestedCurve = requested,
            normalizedCurve = asusNormalization ? normalized : null,
            transportResult = "not-observed",
            callbackResult = "not-observed",
            readback = "not-observed",
            readbackMatch = "not-observed",
            physicalObservation = "not-observed",
            physicalWindow = "not-observed",
            owner = "not-observed",
        }).ToArray();
        return new
        {
            phase,
            source = FanDispatchSource,
            operation = FanDispatchOperation(isSoftware),
            provider = FanDispatchProviderName,
            sourceName,
            factoryType = FactoryType ?? "not-observed",
            fanIds,
            requestedCurve = requested,
            normalizedCurve = asusNormalization ? normalized : null,
            normalizationRule = asusNormalization
                ? "AsusACPI.SetFanCurve clamps curve bytes to 0..99"
                : "HC route-specific; not-observed",
            transportResult = "not-observed",
            callbackResult = "not-observed",
            readback = "not-observed",
            readbackMatch = "not-observed",
            physicalObservation = "not-observed",
            physicalWindow = "not-observed",
            owner = "not-observed",
            perFan,
        };
    }

    private void ApplyPowerProfile(object profile, string sourceName = "Background")
    {
        // FAN-934 R2 §3-B：唯一自测 HC 边界（默认关闭）。开启时 HC 的 UpdateSource
        // 枚举解析与 PowerProfileManager_Applied 回调都改由边界承载（无 HC 程序集、
        // 无真实 EC/WMI），但诊断形状与回调计数语义保持不变。
        var selfTestCallbackBoundary = hcBoundaryForSelfTest;
        var normalized = NormalizeUpdateSourceName(sourceName);
        object? source = null;
        // HC-SLIM-01 R3 §4.2：backend provider 不使用 HC 的 UpdateSource 枚举（写入由叶组件直接
        // 承担），因此在无 HC 程序集的离线自测中不得解析该类型；仅在真正要走 HC 回调时解析。
        if (selfTestCallbackBoundary is null && !UsesBackendFanWriter)
        {
            var updateType = FindType("HandheldCompanion.UpdateSource")
                ?? throw new MissingMemberException("HC UpdateSource not found");
            try
            {
                source = Enum.Parse(updateType, normalized, ignoreCase: false);
            }
            catch
            {
                source = Enum.Parse(updateType, "Background", ignoreCase: false);
                normalized = "Background";
            }
        }
        lastUpdateSource = normalized;
        var evidence = BuildFanDispatchEvidence(profile, normalized);
        var callbackFan = GetMember(profile, "FanProfile");
        var callbackPhase = string.Equals(
            Convert.ToString(callbackFan is null ? null : GetMember(callbackFan, "fanMode")),
            "Software",
            StringComparison.OrdinalIgnoreCase)
            ? "F3-controlled"
            : "F4-oem-handoff";
        Diagnostic?.Invoke("hc.fan-dispatch.begin", evidence);
        try
        {
            // This remains the single fan-write boundary. The Host does not
            // synthesize vendor writes or reinterpret a callback as hardware
            // transport/readback evidence.
            if (selfTestCallbackBoundary is not null)
                selfTestCallbackBoundary.Apply(profile, normalized);
            else if (UsesBackendFanWriter)
                ApplyAsusCurveViaBackend(profile);
            else
                Invoke("PowerProfileManager_Applied", profile, source);
            Diagnostic?.Invoke("hc.fan-dispatch.callback-returned", new
            {
                phase = callbackPhase,
                source = FanDispatchSource,
                operation = FanDispatchOperation(callbackPhase == "F3-controlled"),
                provider = FanDispatchProviderName,
                sourceName = normalized,
                factoryType = FactoryType ?? "not-observed",
                callbackResult = "returned",
                transportResult = "not-observed",
                readback = "not-observed",
                readbackMatch = "not-observed",
                physicalObservation = "not-observed",
                physicalWindow = "not-observed",
                owner = "not-observed",
            });
        }
        catch (Exception ex)
        {
            Diagnostic?.Invoke("hc.fan-dispatch.callback-failure", new
            {
                phase = callbackPhase,
                source = FanDispatchSource,
                operation = FanDispatchOperation(callbackPhase == "F3-controlled"),
                provider = FanDispatchProviderName,
                sourceName = normalized,
                factoryType = FactoryType ?? "not-observed",
                callbackResult = "threw",
                transportResult = "not-observed",
                readback = "not-observed",
                readbackMatch = "not-observed",
                physicalObservation = "not-observed",
                physicalWindow = "not-observed",
                owner = "not-observed",
                error = DescribeException(ex),
            });
            throw;
        }
    }

    /**
     * HC-SLIM-01 R3 §4.2：backend provider 下的 ASUS 曲线写入。
     *
     * 复用 Host 已构造的 profile（因此输入曲线/Software-Hardware 判定与 HC 回调逐字一致），
     * 但由叶组件直接执行 CPU/GPU/Mid 三写：Software 走 `ToAsusCurve` + `ApplySoftwareCurve`，
     * 否则交还默认表（镜像 `SetFanControl(false)`）。逐扇收据经 backend `AsusAcpiObservations`
     * 发布，使既有的 Begin/Settle 证据结算链（`CompleteAsusWriteScope` 反射 duck-typing）原样复用。
     */
    private void ApplyAsusCurveViaBackend(object profile)
    {
        EnsureBackendAsusAcpiOpen();
        var fan = GetMember(profile, "FanProfile")
            ?? throw new InvalidOperationException("HC FanProfile construction failed");
        var isSoftware = string.Equals(
            Convert.ToString(GetMember(fan, "fanMode")),
            "Software",
            StringComparison.OrdinalIgnoreCase);
        if (isSoftware)
        {
            var requested = GetMember(fan, "fanSpeeds") as double[] ?? Array.Empty<double>();
            YeManFanBackend.Asus.AsusFanCurveWriter.ApplySoftwareCurve(
                YeManFanBackend.Asus.AsusFanCurveWriter.ToAsusCurve(requested));
        }
        else
        {
            _ = YeManFanBackend.Asus.AsusFanCurveWriter.RestoreDefaultCurves();
        }
    }

    /**
     * HC-SLIM-01 R4 §4 H1：backend provider 自有的 ACPI 句柄归位于 Host 生命周期边界。
     *
     * 睡眠、显式关闭/取消和进程退出都在既有串行边界（CloseCore/Dispose）内调用本方法，
     * 不能只等 Dispose。归还后 host 标记 `backendAsusAcpiOpened` 复位；若 Close 抛异常，
     * 保留 host 标记与 leaf 的真实句柄状态（fail-closed：不伪造已归还），下一次
     * `EnsureBackendAsusAcpiOpen()` 会按真实句柄状态重试。
     */
    private void ReleaseBackendAsusAcpiOwnedHandle(string cause)
    {
        if (!backendAsusAcpiOpened && !YeManFanBackend.Asus.AsusACPI.IsOpen) return;
        var wasOpen = YeManFanBackend.Asus.AsusACPI.IsOpen;
        try
        {
            YeManFanBackend.Asus.AsusACPI.Close();
            backendAsusAcpiOpened = false;
            Diagnostic?.Invoke("fan.backend-acpi.release", new
            {
                cause,
                wasOpen,
                released = !YeManFanBackend.Asus.AsusACPI.IsOpen,
            });
        }
        catch (Exception ex)
        {
            Diagnostic?.Invoke("fan.backend-acpi.release-fault", new
            {
                cause,
                wasOpen,
                error = DescribeException(ex),
            });
        }
    }

    /**
     * HC-SLIM-01 R3 §6.2②：backend provider 的首次硬件动作前，冻结并记录 provider/组件版本，
     * 并打开 ACPI 句柄（唯一 OS 边界；HID 无关）。句柄打不开 ⇒ fail-closed，**不允许**静默
     * 降级到 HC 第二 writer（uncertain 写入后不得自动试第二个 writer）。
     *
     * HC-SLIM-01 R4 §4 H1：`backendAsusAcpiOpened` 只表示"本会话打开过"，不等于 leaf 自有
     * 句柄当前仍然有效。睡眠/关闭/驱动句柄失效后必须按 leaf 的真实句柄状态
     * （`AsusACPI.IsOpen`）决定是否重开，不能被旧标记吞掉。`AsusACPI.Open()` 在句柄仍有效时
     * 会短路返回，因此重开不会产生第二个 writer/句柄。
     */
    private void EnsureBackendAsusAcpiOpen()
    {
        var handleWasOpen = YeManFanBackend.Asus.AsusACPI.IsOpen;
        if (backendAsusAcpiOpened && handleWasOpen) return;
        YeManFanBackend.Asus.AsusACPI.DiagnosticSink ??= message =>
            Diagnostic?.Invoke("backend.asus-acpi", new { message });
        if (!YeManFanBackend.Asus.AsusACPI.Open())
            throw new InvalidOperationException(
                @"FAN_BACKEND_ASUS_ACPI_OPEN_FAILED: \\.\ATKACPI handle unavailable");
        var reopened = backendAsusAcpiOpened && !handleWasOpen;
        backendAsusAcpiOpened = true;
        Diagnostic?.Invoke("fan.provider.frozen", new
        {
            provider = "backend",
            component = YeManFanBackend.Asus.AsusFanCurveWriter.ComponentVersion,
            singleWriter = true,
            hcAssemblyLoaded = assembly is not null,
            reopened,
        });
    }

    /**
     * FAN-936 R2 section 2: the MSI-only OEM hand-back seam. It runs inside the
     * same STA/serial boundary as the profile path (RestoreOemCore holds
     * hardwareGate) and calls HC's existing dedicated release routine
     * `ReleaseMsiFanControl` directly, so the Host never triggers the full
     * PowerProfileManager_Applied callback (and its Shift write) for a release.
     * The operation token was already issued by BeginMsiReleaseOperation, so the
     * resulting LastMsiFanRelease is bound to this operation.
     */
    private void DispatchMsiReleaseViaNarrowInterface()
    {
        if (device is null)
            throw new InvalidOperationException("FAN_ROUTE_RESTORE_UNAVAILABLE: MSI device unavailable");
        var result = Invoke(device, "ReleaseMsiFanControl", "oem-restore");
        Diagnostic?.Invoke("restore.msi-narrow-release-dispatch", new
        {
            route = Route?.Kind.ToString(),
            source = "hc.device-narrow-interface",
            operation = "HC.ReleaseMsiFanControl",
            cause = "oem-restore",
            fullPowerProfileCallbackInvoked = false,
            status = result is null ? "<null>" : GetMember(result, "Status") as string,
            scope = "hc-msi-fan-release-without-power-profile-shift-side-effect",
        });
    }

    /** 仅自测：走一次 MSI 窄接口释放分派（生产路径由 `RestoreOemCore` 调用）。 */
    internal void DispatchMsiReleaseViaNarrowInterfaceForSelfTest() => DispatchMsiReleaseViaNarrowInterface();

    /**
     * FAN-936 R2 section 1: settle Close against the release result it produced.
     * Close issues its own operation token (`BeginMsiReleaseOperation` above) and
     * HC's Close-time hand-back must echo it. Three outcomes, fail-closed:
     *   - HC returns a release result for *this* operation with `ok`
     *     ⇒ the close-scoped release is proven; record it (separate from cleanup).
     *   - HC returns a result for this operation with `failed`/`unknown`
     *     ⇒ clear any earlier success so a stale `verified` cannot survive a
     *       newer failing release.
     *   - no bound result (Close performed no hand-back, or a stale/old receipt)
     *     ⇒ `not-attempted`; leave prior state untouched (a normal exit must not
     *       be downgraded). Only MSI routes participate; this never throws.
     */
    private void SettleMsiCloseRelease()
    {
        if (Route?.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease) return;
        try
        {
            var structured = ReadMsiStructuredRelease(out var detail);
            if (structured is null)
            {
                // FAN-936 R1: a null read is ambiguous — it covers both "Close never
                // crossed the hand-back boundary" (a normal exit that must not be
                // downgraded) and "Close really called the hand-back but returned no
                // usable/current receipt" (missing, stale, foreign-token, or
                // unclassifiable ⇒ must not keep an earlier success). The Host
                // records whether the boundary was actually entered by comparing the
                // device's monotonic release-routine invocation count across the
                // boundary (captured in `CloseHcDevice`): a real hand-back — even one
                // that throws — increments it, while a suppressed hand-back leaves it
                // untouched. Fail-closed: if a device exists but its counter cannot
                // be read, assume the boundary was entered rather than invent a
                // normal exit.
                if (!MsiCloseHandbackEntered())
                {
                    hcCloseReleaseSettlement = "not-attempted";
                    hcCloseReleaseDetail = detail;
                    Diagnostic?.Invoke("hc-close.msi-release-settlement", new
                    {
                        settlement = hcCloseReleaseSettlement,
                        detail,
                        scope = "close-release-not-attempted-preserves-prior-state",
                    });
                    return;
                }
                // Entered the hand-back boundary but produced no proof for *this*
                // operation: fail-closed, and clear any earlier success so a stale
                // proven can never survive this newer, unproven hand-back.
                hcCloseReleaseSettlement = "unknown";
                hcCloseReleaseDetail = $"attempted-without-current-receipt:{detail}";
                oemRestoreVerified = false;
                oemReleaseActionKind = FanHostEngine.ReleaseActionKindName(OemReleaseAction.Unknown);
                oemReleaseActionEvidence =
                    $"hc-close-msi-handback-attempted-without-current-receipt[{detail}]";
                oemOwnershipStatus = "unknown-no-hc-contract";
                Diagnostic?.Invoke("hc-close.msi-release-settlement", new
                {
                    settlement = hcCloseReleaseSettlement,
                    detail,
                    scope = "close-release-attempted-without-current-receipt-clears-prior-proven",
                });
                return;
            }
            var action = FanHostEngine.ClassifyMsiReleaseStatus(structured.Status);
            hcCloseReleaseDetail = detail;
            if (action == OemReleaseAction.Proven)
            {
                hcCloseReleaseSettlement = "proven";
                oemRestoreVerified = true;
                oemReleaseActionKind = "proven-by-msi-structured-release";
                oemReleaseActionEvidence =
                    $"hc-close-msi-structured-release[{detail}] status={structured.Status ?? "<absent>"} " +
                    $"fullSpeed152={structured.FullSpeed152Status ?? "<absent>"} " +
                    $"softwareControl212={structured.SoftwareControl212Status ?? "<absent>"}";
                oemOwnershipStatus = "hc-close-msi-structured-release-physical-unknown";
            }
            else
            {
                hcCloseReleaseSettlement = action == OemReleaseAction.Failed ? "failed" : "unknown";
                // A newer, non-proven close release invalidates any earlier success.
                oemRestoreVerified = false;
                oemReleaseActionKind = FanHostEngine.ReleaseActionKindName(action);
                oemReleaseActionEvidence =
                    $"hc-close-msi-structured-release[{detail}] status={structured.Status ?? "<absent>"} " +
                    $"classified={hcCloseReleaseSettlement}";
                oemOwnershipStatus = "unknown-no-hc-contract";
            }
            Diagnostic?.Invoke("hc-close.msi-release-settlement", new
            {
                settlement = hcCloseReleaseSettlement,
                status = structured.Status ?? "<absent>",
                detail,
                scope = "close-release-settled-separately-from-manager-cleanup",
            });
        }
        catch (Exception ex)
        {
            // Settlement must never abort the Close boundary; record honestly.
            hcCloseReleaseSettlement = "unknown";
            hcCloseReleaseDetail = $"settlement-exception:{DescribeException(ex)}";
            // FAN-936 R1: an unreadable/malformed receipt after an *entered*
            // hand-back must not leave an earlier proven in place — otherwise a
            // stale success survives a newer, unprovable release. Mirror the
            // null-read path exactly: only downgrade when the boundary was really
            // entered, and fail-closed when the count cannot be read.
            if (MsiCloseHandbackEntered())
            {
                oemRestoreVerified = false;
                oemReleaseActionKind = FanHostEngine.ReleaseActionKindName(OemReleaseAction.Unknown);
                oemReleaseActionEvidence =
                    $"hc-close-msi-handback-attempted-receipt-unreadable[{DescribeException(ex)}]";
                oemOwnershipStatus = "unknown-no-hc-contract";
            }
            Diagnostic?.Invoke("hc-close.msi-release-settlement", new
            {
                settlement = "unknown",
                error = DescribeException(ex),
                scope = "close-release-settlement-exception",
            });
        }
    }

    /**
     * FAN-936 R3：MSI Close 在交还边界抛异常、且本次没有产出有效绑定 `ok` 收据时，
     * 清除旧的“交还已证”证据并如实记未证。交还边界已经进入 ⇒ 绝不能因旧成功收据把
     * `IsOemReleaseSafe` 重新判成功。仅 MSI 路线生效；非 MSI 路线保持原行为（early return）。
     */
    private void MarkMsiCloseReleaseUnknownAfterException(Exception ex)
    {
        if (Route?.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease) return;
        var reason = $"close-boundary-exception:{DescribeException(ex)}";
        hcCloseReleaseSettlement = "unknown";
        hcCloseReleaseDetail = reason;
        oemRestoreVerified = false;
        oemReleaseActionKind = FanHostEngine.ReleaseActionKindName(OemReleaseAction.Unknown);
        oemReleaseActionEvidence = $"hc-close-msi-handback-boundary-exception[{reason}]";
        oemOwnershipStatus = "unknown-no-hc-contract";
        Diagnostic?.Invoke("hc-close.msi-release-settlement", new
        {
            settlement = "unknown",
            error = DescribeException(ex),
            scope = "close-release-boundary-exception-clears-prior-proven",
        });
    }

    /** 仅自测：走一次 Close 释放结算（生产路径由 `CloseHcDevice` 调用）。 */
    internal void SettleMsiCloseReleaseForSelfTest() => SettleMsiCloseRelease();

    /** 仅自测：Close 释放结算三态读数（与清理记账分列）。 */
    internal (string Settlement, string Detail) HcCloseReleaseSettlementForSelfTest =>
        (hcCloseReleaseSettlement, hcCloseReleaseDetail);

    public void Close(bool stopDeviceManager = true) => OnStaBounded(() => CloseCore(stopDeviceManager), "close");

    /** Non-blocking power-boundary guard; the queued restore still owns all
     * HC calls, but no temperature callback may issue a new hardware write. */
    public void BlockWritesForSuspend()
    {
        Volatile.Write(ref suspendWriteBlocked, 1);
        // 第十轮返修（P1-B）：递增版本（Interlocked，回调非阻塞）——
        // 任何在此之后到达的"解除保护"都会因版本不等而被拒。
        Interlocked.Increment(ref suspendGateEpoch);
    }

    /**
     * Closing is stronger than suspend. It remains closed even if Windows
     * emits a late Resume while Close/recovery still owns the hardware path.
     */
    public void BlockWritesForClose()
    {
        Volatile.Write(ref closeWriteBlocked, 1);
        Volatile.Write(ref suspendWriteBlocked, 1);
        Interlocked.Increment(ref suspendGateEpoch);
    }

    /** Only the resume path may lift the sleep write gate, never Close. */
    public void AllowWritesAfterResume()
    {
        if (Volatile.Read(ref closeWriteBlocked) == 0)
        {
            Volatile.Write(ref suspendWriteBlocked, 0);
            // 第十轮返修（P1-B）：允许基准 = 当前 gate 版本（两版本相等才放行）。
            Volatile.Write(ref writeAllowEpoch, Volatile.Read(ref suspendGateEpoch));
        }
    }

    /**
     * 第十轮返修（P1-B）：版本化解除。仅当"自我捕获的 gate 版本"仍是当前版本
     * （期间无新睡眠/关闭/超时递增）时才解除；放行由"两版本相等"判定——
     * 任意交错下（先解除后睡眠、先睡眠后解除）均无窗口，无需锁，
     * 回调与写路径均保持非阻塞。
     */
    public bool TryAllowWritesAfterResume(long expectedGateEpoch)
    {
        if (Volatile.Read(ref closeWriteBlocked) != 0) return false;
        if (Volatile.Read(ref suspendGateEpoch) != expectedGateEpoch) return false;
        Volatile.Write(ref suspendWriteBlocked, 0);
        Volatile.Write(ref writeAllowEpoch, expectedGateEpoch);
        return true;
    }

    internal long SuspendGateEpochForResume => Volatile.Read(ref suspendGateEpoch);

    private void CloseCore(bool stopDeviceManager)
    {
        // ManagerFactory cleanup is not assumed to be absent. The virtual
        // device Close boundary remains serialized here; its observed
        // ManagerFactory state is validated after Close before this method
        // can report a completed lifecycle.
        lock (hardwareGate)
        {
        // This is the earliest fan-only lifecycle boundary. Invalidate the
        // session before HC Close begins so a queued Applied/temperature/HID
        // callback cannot become a second recovery owner while Close is
        // unwinding.
        externalProfileQueue.InvalidateSession();
        // CloseCore is also used by the suspend/release path. The engine has
        // already selected the correct admission boundary: suspend remains
        // resumable, while an application/parent close explicitly called
        // BlockWritesForClose() before it entered this method.
        Volatile.Write(ref suspendWriteBlocked, 1);
        Interlocked.Increment(ref suspendGateEpoch);
        if (device is null)
        {
            HcDeviceManagerStopCompleted = false;
            hcDeviceManagerLifecycle = ManagerFactoryUnknown;
            throw new InvalidOperationException("HC_CLOSE_PENDING: HC ManagerFactory 状态未知，拒绝伪造 Close 完成");
        }
        // HC invokes CurrentDevice.Close() on the SystemPending boundary and
        // invokes it again from Window_Closed.  Duplicate power notifications
        // must remain idempotent, but a real process-close boundary must not
        // use the sleep-time `closed` marker to skip the second virtual close;
        // device overrides may perform their final HID/ACPI cleanup there.
        if (closed && !stopDeviceManager)
        {
            // A duplicate SystemPending boundary is already closed; the
            // process-close owner will perform the final virtual Close call.
            return;
        }
        try
        {
            SetHcPhase("close.temperature-monitor-stop");
            StopCpuTemperatureMonitor();
            activeCurveDuties = null;
            // Call the real HC virtual close path after the verified Hardware
            // profile restore when the caller is performing a profile handoff.
            // For sleep/process close this is the HC ownership boundary itself:
            // ROGAlly.Close() performs AsusACPI.Close, controller restoration,
            // HID disposal and base.Close in HC's original order.
            CloseHcDevice();
            // A returned virtual Close is a completed HC lifecycle boundary;
            // it is not a generic Hardware-profile callback or a physical
            // OEM ownership acknowledgement. Preserve any earlier explicit
            // Hardware callback evidence, but never manufacture it here.
            // FAN-936 R2 section 1: on the MSI route the close-scoped release
            // settlement (`SettleMsiCloseRelease`) already wrote the precise
            // evidence, so this generic fallback must not overwrite it.
            if (!oemRestoreVerified
                && Route?.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease)
            {
                oemRestoreEvidence = "hc-device-close-returned-no-hardware-callback";
                oemOwnershipStatus = "hc-close-returned-physical-unknown";
            }
            IsOpen = false;
            openAttempted = false;
            hcOpenInvocationStarted = false;
            sessionDeviceReference = null;
            sessionRouteMarker = null;
            closed = true;
        }
        finally
        {
            // HC-SLIM-01 R4 §4 H1：无论 Close 是否在 CloseHcDevice 处抛出，都在同一串行
            // 边界内归还 backend provider 自有 ACPI 句柄（睡眠/显式关闭/进程退出共用此边界）。
            // MUTATION-B: ReleaseBackendAsusAcpiOwnedHandle("close") intentionally removed.
            SetHcPhase(null);
        }
        }
    }

    /**
     * §19-A/B：候选 Close 清理结算的有界等待预算。语义与既有 close 重试窗口一致：
     * 期限内未结算 ⇒ 报 HC_CLOSE_PENDING（不宣称关闭清理完成），由重试窗口继续处理。
     */
    internal const int CloseCleanupSettlementWaitMs = 1_500;

    private void CloseHcDevice()
    {
        SetHcPhase("close.virtual-device-close");
        HcVirtualCloseReturned = false;
        // FAN-936 R2 section 1: bind Close to its own release operation. HC's
        // current device Close performs its own fan hand-back; issuing a fresh
        // operation token here means Close's release result is compared against
        // *this* operation, so a successful earlier hand-back can no longer mask
        // a failed/unknown Close-time release. Non-MSI routes are untouched.
        hcCloseReleaseSettlement = "not-attempted";
        hcCloseReleaseDetail = "none";
        BeginMsiReleaseOperation();
        // FAN-936 R1: capture the pre-boundary release-routine invocation count so
        // a later null/throw read can tell "never entered the boundary" (a normal
        // exit) from "entered but unproven".
        msiCloseReleaseInvocationCountBefore = ReadMsiReleaseInvocationCount();
        Diagnostic?.Invoke("hc-close.virtual-device.begin", new { factoryType = FactoryType });
        ExecuteCloseBoundary(
            closeDevice: () =>
            {
                try
                {
                    Invoke(device!, "Close");
                }
                catch (Exception closeEx)
                {
                    // FAN-936 R3: the Close boundary threw. If this operation still
                    // produced a valid bound `ok` receipt, keep it (a later
                    // handle/manager cleanup failure must not erase a real
                    // success); otherwise clear any earlier proven evidence — a
                    // throwing hand-back must never leave a stale release success.
                    SettleMsiCloseRelease();
                    if (hcCloseReleaseSettlement != "proven")
                        MarkMsiCloseReleaseUnknownAfterException(closeEx);
                    throw;
                }
                HcVirtualCloseReturned = true;
                // FAN-936 R2 section 1: consume Close's own latest release result
                // immediately after the boundary returns, before the (independent)
                // manager-cleanup confirmation. Never throws.
                SettleMsiCloseRelease();
                // §19-A/B：消费候选 Close 的**结构化清理收据**。清理责任未结算（例如句柄释放
                // 被延迟给在途读取、设备调用仍在库内）时不得报告关闭清理完成；保持
                // HC_CLOSE_PENDING 交给既有有界重试窗口，而不是先报“已清理”。
                if (!ConfirmCandidateCloseCleanup(CloseCleanupSettlementWaitMs, out var cleanupDetail))
                    throw new InvalidOperationException(
                        $"HC_CLOSE_PENDING: candidate close cleanup not settled: {cleanupDetail}");
                Diagnostic?.Invoke("hc-close.virtual-device.return", new { factoryType = FactoryType });
            },
            unbindEvents: () =>
            {
                // HC Window_Closed unbinds application/device events only
                // after CurrentDevice.Close() returns. Keep that ordering;
                // manager cleanup is validated after the event boundary.
                UnsubscribeExternalProfileEvents();
                hcOpenEventsInvoked = false;
            },
            confirmManagerCleanup: ConfirmManagerCleanupAfterClose);
    }

    /**
     * 裁决 H2（2026-09-19）：Close 返回后是否需要补做**一次**只读 ManagerFactory 观测。
     * 已观测过 ⇒ 按既有语义重观测一次（保留原行为）；从未观测过但虚拟 Close 已返回
     * （C 族：Open 已开始但 OpenEvents 未完成，post-OpenEvents 观测从未发生）⇒ 允许
     * 补做一次，而不是直接判失败。
     */
    internal static bool ShouldObserveManagerAfterClose(bool managerFactoryObserved, bool hcVirtualCloseReturned) =>
        managerFactoryObserved || hcVirtualCloseReturned;

    /** 裁决 H2：Close 返回后的清理结论——只有两种可能。 */
    internal enum ManagerCleanupOutcome
    {
        Confirmed,
        PendingCloseCleanup,
    }

    /**
     * 裁决 H2：**一次**只读观测的结果分类（纯函数）。它是"观测成功"的可证形式，
     * 使"观测失败/不可读 ⇒ 不得确认清理"成为单一判定而不是散落的 if。
     * Unknown 归入 Faulted（fail-closed）：观测后仍 Unknown 不构成"无 Active manager"。
     */
    internal enum ManagerObservationOutcome
    {
        NotAttempted,
        ObservedClean,
        ObservedActive,
        ObservedFaulted,
        Unreadable,
    }

    internal static ManagerObservationOutcome DescribeManagerObservation(
        string managerFactoryLifecycle,
        string deviceManagerLifecycle)
    {
        if (managerFactoryLifecycle == ManagerFactoryFaulted || deviceManagerLifecycle == ManagerFactoryFaulted)
            return ManagerObservationOutcome.ObservedFaulted;
        if (managerFactoryLifecycle == ManagerFactoryActive || deviceManagerLifecycle == ManagerFactoryActive)
            return ManagerObservationOutcome.ObservedActive;
        if (managerFactoryLifecycle == ManagerFactoryStarted && deviceManagerLifecycle == ManagerFactoryStarted)
            return ManagerObservationOutcome.ObservedClean;
        // Unknown / 未读到的任何组合都不得当作"已清理"。
        return ManagerObservationOutcome.ObservedFaulted;
    }

    /**
     * 裁决 H2：Close 返回后的清理**判定**（纯函数、单一出处）——覆盖整条链：
     *   ① 不需要观测（既未观测过、虚拟 Close 也未返回）⇒ PendingCloseCleanup；
     *   ② 需要观测但结果不可读（Unreadable）⇒ PendingCloseCleanup（**不得**用
     *      HcVirtualCloseReturned 单独代替确认）；
     *   ③ 观测到 ObservedClean ⇒ Confirmed；
     *   ④ 观测到 Active/Faulted ⇒ PendingCloseCleanup。
     */
    internal static ManagerCleanupOutcome DecideManagerCleanupAfterClose(
        bool managerFactoryObserved,
        bool hcVirtualCloseReturned,
        ManagerObservationOutcome observation) =>
        !ShouldObserveManagerAfterClose(managerFactoryObserved, hcVirtualCloseReturned)
            ? ManagerCleanupOutcome.PendingCloseCleanup
            : observation == ManagerObservationOutcome.ObservedClean
                ? ManagerCleanupOutcome.Confirmed
                : ManagerCleanupOutcome.PendingCloseCleanup;

    private void ConfirmManagerCleanupAfterClose()
    {
        // Do not reuse the snapshot captured immediately after OpenEvents.
        // HC's Window_Closed checks the post-Close manager boundary; a stale
        // pre-Close status can either keep a valid fan-only close resident or
        // falsely report cleanup while a manager is still active.  The
        // observation is read-only and never starts/stops a HC manager.
        // 裁决 H2：C 族（Open 已开始、OpenEvents 未完成）下 managerFactoryObserved
        // 必为 false ⇒ 补做一次只读观测；观测不可读时**不得**据虚拟 Close 返回值
        // 确认清理，一律落到下面的 HC_CLOSE_PENDING 未确认分支。
        var observation = ManagerObservationOutcome.NotAttempted;
        if (ShouldObserveManagerAfterClose(managerFactoryObserved, HcVirtualCloseReturned))
        {
            try
            {
                ObserveManagerFactoryLifecycle();
                observation = DescribeManagerObservation(hcManagerFactoryLifecycle, hcDeviceManagerLifecycle);
            }
            catch (Exception ex)
            {
                observation = ManagerObservationOutcome.Unreadable;
                Diagnostic?.Invoke("hc-close.manager-observation-unreadable", new
                {
                    error = DescribeException(ex),
                    hcVirtualCloseReturned = HcVirtualCloseReturned,
                });
            }
        }

        if (DecideManagerCleanupAfterClose(
                managerFactoryObserved,
                HcVirtualCloseReturned,
                observation) == ManagerCleanupOutcome.Confirmed)
        {
            HcDeviceManagerStopCompleted = true;
            Diagnostic?.Invoke("hc-close.manager-cleanup-confirmed", new
            {
                managerFactoryLifecycle = hcManagerFactoryLifecycle,
                deviceManagerLifecycle = hcDeviceManagerLifecycle,
                outcome = "no-active-manager-observed",
                deviceManagerStopInvoked = false,
                evidence = "post-close-no-active-manager-observed",
            });
            return;
        }

        HcDeviceManagerStopCompleted = false;
        Diagnostic?.Invoke("hc-close.manager-cleanup-unconfirmed", new
        {
            managerFactoryLifecycle = hcManagerFactoryLifecycle,
            deviceManagerLifecycle = hcDeviceManagerLifecycle,
            managerFactoryObserved,
            observation = observation.ToString(),
        });
        throw new InvalidOperationException(
            $"HC_CLOSE_PENDING: ManagerFactory cleanup 未确认 (factory={hcManagerFactoryLifecycle}, device={hcDeviceManagerLifecycle})");
    }

    /**
     * The only production close-order seam.  It is deliberately shared by
     * CloseHcDevice and the side-effect-free self-test so the test cannot pass
     * while a separate mock hides the real CurrentDevice.Close -> event
     * unbind boundary. The final callback must retain cleanup evidence.
     */
    private static void ExecuteCloseBoundary(
        Action closeDevice,
        Action unbindEvents,
        Action confirmManagerCleanup)
    {
        var closeReturned = false;
        try
        {
            closeDevice();
            closeReturned = true;
        }
        finally
        {
            // A failed virtual Close has not crossed HC's successful
            // Window_Closed boundary. Do not claim the success order or
            // unbind events on that failure path. Cleanup is still checked
            // and an unconfirmed result remains fail-closed.
            if (closeReturned)
                unbindEvents();
            confirmManagerCleanup();
        }
    }

    internal static IReadOnlyList<string> RunCloseOrderSelfTest()
    {
        var checks = new List<string>();

        var normal = new List<string>();
        ExecuteCloseBoundary(
            () => normal.Add("CurrentDevice.Close"),
            () => normal.Add("FanEvents.Unbind"),
            () => normal.Add("ManagerFactory.CleanupConfirmed"));
        var expectedNormal = new[] { "CurrentDevice.Close", "FanEvents.Unbind", "ManagerFactory.CleanupConfirmed" };
        if (!normal.SequenceEqual(expectedNormal))
            throw new InvalidOperationException($"R4.1 production close order mismatch: {string.Join(" -> ", normal)}");
        checks.Add("r4.1-production-normal-close-order");

        var sleep = new List<string>();
        ExecuteCloseBoundary(
            () => sleep.Add("CurrentDevice.Close"),
            () => sleep.Add("FanEvents.Unbind"),
            () => sleep.Add("ManagerFactory.CleanupConfirmed"));
        var expectedSleep = new[] { "CurrentDevice.Close", "FanEvents.Unbind", "ManagerFactory.CleanupConfirmed" };
        if (!sleep.SequenceEqual(expectedSleep))
            throw new InvalidOperationException($"R4.1 sleep close order mismatch: {string.Join(" -> ", sleep)}");
        checks.Add("r4.1-sleep-close-manager-cleanup-boundary");

        var failed = new List<string>();
        try
        {
            ExecuteCloseBoundary(
                () =>
                {
                    failed.Add("CurrentDevice.Close");
                    throw new InvalidOperationException("synthetic-close-failure");
                },
                () => failed.Add("FanEvents.Unbind"),
                () => failed.Add("ManagerFactory.CleanupConfirmed"));
        }
        catch (InvalidOperationException ex) when (ex.Message == "synthetic-close-failure")
        {
            // Expected: the exception remains visible to the recovery owner.
        }
        var expectedFailed = new[] { "CurrentDevice.Close", "ManagerFactory.CleanupConfirmed" };
        if (!failed.SequenceEqual(expectedFailed))
            throw new InvalidOperationException($"R4.1 close-failure ordering mismatch: {string.Join(" -> ", failed)}");
        checks.Add("r4.1-close-failure-does-not-claim-success-order");

        var retry = new List<string>();
        var failFirstClose = true;
        void CloseWithOneFailure()
        {
            ExecuteCloseBoundary(
                () =>
                {
                    retry.Add("CurrentDevice.Close");
                    if (failFirstClose)
                    {
                        failFirstClose = false;
                        throw new InvalidOperationException("synthetic-close-retry");
                    }
                },
                () => retry.Add("FanEvents.Unbind"),
                () => retry.Add("ManagerFactory.CleanupConfirmed"));
        }
        try { CloseWithOneFailure(); }
        catch (InvalidOperationException ex) when (ex.Message == "synthetic-close-retry") { }
        CloseWithOneFailure();
        var expectedRetry = new[]
        {
            "CurrentDevice.Close", "ManagerFactory.CleanupConfirmed",
            "CurrentDevice.Close", "FanEvents.Unbind", "ManagerFactory.CleanupConfirmed",
        };
        if (!retry.SequenceEqual(expectedRetry))
            throw new InvalidOperationException($"R4.2 close retry ordering mismatch: {string.Join(" -> ", retry)}");
        checks.Add("r4.2-close-throw-followup-retry");

        var duplicate = new List<string>();
        var closeOwnerCompleted = false;
        void CloseOnce()
        {
            if (closeOwnerCompleted) return;
            ExecuteCloseBoundary(
                () => duplicate.Add("CurrentDevice.Close"),
                () => duplicate.Add("FanEvents.Unbind"),
                () => duplicate.Add("ManagerFactory.CleanupConfirmed"));
            closeOwnerCompleted = true;
        }
        CloseOnce();
        CloseOnce();
        if (duplicate.Count(value => value == "ManagerFactory.CleanupConfirmed") != 1)
            throw new InvalidOperationException("R4.1 duplicate close created a second manager cleanup outcome");
        checks.Add("r4.1-duplicate-close-single-manager-cleanup");

        var initializingOracle = new FanLifecycleSequenceMock { ManagersInitializing = true };
        if (initializingOracle.WindowClosed(TimeSpan.FromMilliseconds(40)) ||
            !initializingOracle.Events.Contains("Window_Closed.HostBoundaryTimedOut.ManagerStillInitializing"))
            throw new InvalidOperationException("R4.1 full-app Initializing oracle unexpectedly changed HC reference semantics");
        checks.Add("r4.1-initializing-oracle-only");

        return checks;
    }

    /**
     * Safe/no-HC subscription oracle for the Host-only PowerProfile event
     * bridge. HC proves that MainWindow subscriptions survive SystemPending
     * and that IDevice.Close owns device-level unsubscription, but it does
     * not define ownership for this resident Host's extra Applied/Discarded
     * handlers. This oracle therefore records the observable count and late
     * callback gate without claiming HC parity or physical evidence.
     */
    internal static IReadOnlyList<string> RunSleepSubscriptionOracleSelfTest()
    {
        var checks = new List<string>();
        var subscriptions = 0;
        var noManagerCleanupOutcomes = 0;
        var lateCallbacksObserved = 0;
        var closeGate = false;

        void Subscribe()
        {
            if (!closeGate && subscriptions == 0) subscriptions = 1;
        }

        void LateExternalProfileCallback()
        {
            if (!closeGate && subscriptions != 0) lateCallbacksObserved++;
        }

        void SleepClose()
        {
            closeGate = true;
            ExecuteCloseBoundary(
                () => { },
                () => subscriptions = 0,
                () => noManagerCleanupOutcomes++);
        }

        Subscribe();
        Subscribe();
        if (subscriptions != 1)
            throw new InvalidOperationException("R4.2 duplicate OpenEvents created duplicate subscription");
        checks.Add("r4.2-subscription-count-idempotent");

        SleepClose();
        LateExternalProfileCallback();
        if (subscriptions != 0 || noManagerCleanupOutcomes != 1 || lateCallbacksObserved != 0)
            throw new InvalidOperationException("R4.2 sleep close subscription/manager-cleanup oracle mismatch");
        checks.Add("r4.2-sleep-close-unbind-manager-cleanup-and-late-callback-gate");

        closeGate = false;
        Subscribe();
        Subscribe();
        if (subscriptions != 1)
            throw new InvalidOperationException("R4.2 resume OpenEvents did not re-admit exactly one subscription");
        checks.Add("r4.2-resume-resubscribe-once");

        closeGate = true;
        var processClose = new List<string>();
        ExecuteCloseBoundary(
            () => processClose.Add("CurrentDevice.Close"),
            () => { subscriptions = 0; processClose.Add("FanEvents.Unbind"); },
            () => { noManagerCleanupOutcomes++; processClose.Add("ManagerFactory.CleanupConfirmed"); });
        LateExternalProfileCallback();
        var expectedProcessClose = new[] { "CurrentDevice.Close", "FanEvents.Unbind", "ManagerFactory.CleanupConfirmed" };
        if (!processClose.SequenceEqual(expectedProcessClose) || noManagerCleanupOutcomes != 2 || lateCallbacksObserved != 0)
            throw new InvalidOperationException("R4.2 process close subscription/late callback oracle mismatch");
        checks.Add("r4.2-process-close-single-manager-cleanup-late-callback-gate");

        return checks;
    }

    private void SetHcPhase(string? phase)
    {
        Volatile.Write(ref currentHcPhase, phase);
        Diagnostic?.Invoke("hc-operation.phase", new { phase });
    }

    private static IReadOnlyDictionary<string, FanRoute> BuildFanRoutes()
    {
        var routes = new Dictionary<string, FanRoute>(StringComparer.Ordinal);
        void Add(FanRouteKind kind, string description, FanRestoreStrategy strategy, FanEvidenceMode evidence,
            FanRoutePrecondition precondition, params string[] classes)
        {
            foreach (var name in classes)
                routes[$"HandheldCompanion.Devices.{name}"] = new FanRoute(
                    kind, description, true, true, strategy, evidence, precondition);
        }

        // OpenLib 句柄族（`UseOpenLib=true`）：GPD*/AYANEO*/AOKZOE*/SuiPlay0X1/OneXPlayer*/GamingZone。
        Add(FanRouteKind.GenericDuty, "原版 SetFanDuty / percent-to-raw-register", FanRestoreStrategy.GenericEcControl,
            FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen,
            "AOKZOEA1", "AOKZOEA1Pro", "AOKZOEA1X", "AOKZOEA2",
            "AYANEO2", "AYANEO2S", "AYANEOAIR", "AYANEOAIR1S", "AYANEOAIRLite",
            "AYANEOFlip1SDS", "AYANEOFlip1SKB", "AYANEOFlipDS", "AYANEOFlipKB", "AYANEOKUN",
            "GPDWin4", "GPDWin4_2023", "GPDWin4_2023_7640U", "GPDWin4_2024", "GPDWin4_2024_8640U", "GPDWin4_2024_HX370",
            "GPDWinMax2Intel", "GPDWinMax2_2022_6800U", "GPDWinMax2_2023_7640U",
            "GPDWinMax2_2023_7840U", "GPDWinMax2_2024_8640U", "GPDWinMax2_2024_8840U", "GPDWinMax2_2024_HX370",
            "GamingZone",
            "OneXPlayer2", "OneXPlayer2Pro", "OneXPlayerApex", "OneXPlayerG1AMD", "OneXPlayerG1Intel",
            "OneXPlayerMiniAMD", "OneXPlayerMiniIntel", "OneXPlayerMiniPro", "OneXPlayerOneXFly", "OneXPlayerOneXFlyF1Pro",
            "OneXPlayerX1AMD", "OneXPlayerX1Intel", "OneXPlayerX1Mini", "OneXPlayerX1Pro", "SuiPlay0X1");

        // These subclasses bypass ECDetails.AddressFanControl and use their
        // inherited ACPI_FanMode_Address (0=automatic, 1=manual) via HC's
        // EcWriteByte/EcReadByte path. Keep that contract separate from the
        // generic Super-I/O register routes.
        foreach (var name in new[]
        {
            "AOKZOEA1", "AOKZOEA1Pro", "AOKZOEA1X", "AOKZOEA2",
            "OneXPlayerMiniAMD", "OneXPlayerMiniIntel", "OneXPlayerMiniPro",
            "OneXPlayerOneXFly", "OneXPlayerOneXFlyF1Pro",
        })
            routes[$"HandheldCompanion.Devices.{name}"] = new FanRoute(FanRouteKind.GenericDuty,
                "原版 OneX/AOKZOE ACPI fan mode/duty", true, true, FanRestoreStrategy.OneXAcpiFanMode,
                FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen);

        foreach (var name in new[] { "AYANEOAIRPlusAMD", "AYANEOAIRPlusAMDMendocino", "AYANEOAIRPlusIntel", "AYANEOAIRPro", "AYANEOSlide" })
            if (routes.ContainsKey($"HandheldCompanion.Devices.{name}"))
                routes[$"HandheldCompanion.Devices.{name}"] = routes[$"HandheldCompanion.Devices.{name}"] with
                { RestoreStrategy = FanRestoreStrategy.GenericEcControl };
        routes["HandheldCompanion.Devices.GPDWin4"] = new FanRoute(FanRouteKind.GenericDuty,
            "原版 GPD Win4 HC SetFanControl(false) release", true, true, FanRestoreStrategy.GpdWin4HcRelease,
            FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen);
        // CEii devices use 0xC8 mode and 0x04 duty, with a 0xA5 enable value;
        // a generic EC control read/write would restore the wrong register.
        foreach (var name in new[] { "AYANEOAIRPlusAMD", "AYANEOAIRPlusAMDMendocino", "AYANEOAIRPlusIntel", "AYANEOSlide" })
            routes[$"HandheldCompanion.Devices.{name}"] = new FanRoute(FanRouteKind.GenericDuty,
                "原版 AYANEO CEii fan mode/duty", true, true, FanRestoreStrategy.AyanEOCEiiModeRegister,
                FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen);
        routes["HandheldCompanion.Devices.AYANEOAIRPro"] = new FanRoute(FanRouteKind.GenericDuty,
            "原版 AYANEO CEc fan mode/duty", true, true, FanRestoreStrategy.GenericEcControl,
            FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen);
        foreach (var name in new[] { "GPDWinMini", "GPDWinMini_7640U", "GPDWinMini_8840U", "GPDWinMini_HX370" })
            routes[$"HandheldCompanion.Devices.{name}"] = new FanRoute(FanRouteKind.GenericDuty,
                "原版 SetFanDuty / GPD 0x047A duty-register", true, true, FanRestoreStrategy.None,
                FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen);
        routes["HandheldCompanion.Devices.GPDWin5"] = new FanRoute(FanRouteKind.GenericDuty,
            "原版 SetFanDuty / GPD Win5 dual duty-register auto release", true, true, FanRestoreStrategy.GpdWin5HcAutoRelease,
            FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen);

        Add(FanRouteKind.GenericRpmTarget, "原版 SetFanDuty / EC RPM override release", FanRestoreStrategy.LegionGo2EcRpmOverride,
            FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen,
            "LegionGoTablet2");
        // SteamDeck：`IsOpen => inpOut is not null` 且 `IsSupported => SupportedDevice!=null && Firmware!=0`。
        Add(FanRouteKind.GenericRpmTarget, "原版 SetFanDuty / percent-to-rpm-target", FanRestoreStrategy.None,
            FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.DeviceOpenAndSupported,
            "SteamDeck");

        foreach (var name in new[] { "LokiMax6600U", "LokiMax6800U", "LokiMiniPro", "LokiZero" })
            routes[$"HandheldCompanion.Devices.{name}"] = new FanRoute(FanRouteKind.GenericDuty,
                "原版 Ayn Loki EC fan mode/duty", true, true, FanRestoreStrategy.AynLokiMode,
                FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.OpenLibHandleOpen);

        // MSI Claw（`IsOpen => DeviceOpen && ClawOpen`，WMI writer 静默失败）与 Lenovo LegionGo
        // SZ1/SZ2/Tablet（同一受保护 WMI 风扇表）⇒ 前提为设备句柄打开即可（另由会话/路线签核守）。
        Add(FanRouteKind.ProfileCurve, "原版 PowerProfileManager_Applied / HC hardware-default table release", FanRestoreStrategy.MsiHcDefaultRelease,
            FanEvidenceMode.CompatCallbackNoScope, FanRoutePrecondition.DeviceOpen,
            "ClawA1M", "ClawA2VM", "ClawBZ2EM", "ClawCG3EM", "LegionGoSZ1", "LegionGoSZ2", "LegionGoTablet");
        // Lenovo's profile route uses the same protected WMI fan table
        // implementation as LegionGo; replace the strategy for those entries
        // after the MSI-family add above.
        foreach (var name in new[] { "LegionGoSZ1", "LegionGoSZ2", "LegionGoTablet" })
            routes[$"HandheldCompanion.Devices.{name}"] = routes[$"HandheldCompanion.Devices.{name}"] with
            {
                RestoreStrategy = FanRestoreStrategy.LenovoHcDefaultTable,
                WriteReadyByDefault = true,
                HcCallbackReady = true,
            };
        // §4.A：ASUS 是全库中**唯一**期望 ASUS 操作作用域收据的路线；保留其既有有效检查。
        Add(FanRouteKind.ProfileCurve, "原版 PowerProfileManager_Applied / curve-percent-points", FanRestoreStrategy.AsusAcpiCurves,
            FanEvidenceMode.AsusScopeReceipts,
            // ASUS 走操作作用域收据（AsusScopeReceipts），不使用 compat 回调前提 ⇒ Undeclared（前提不适用）。
            FanRoutePrecondition.Undeclared,
            "ROGAlly", "ROGAllyX", "XboxROGAlly", "XboxROGAllyX");
        return routes;
    }

    private void LoadAssemblyAndFactory()
    {
        ValidateFormalSessionCapabilityAcl();
        // FAN-927 §2.2（2026-09-27 用户批准）：HC 首次加载**不再**遍历并哈希全部依赖文件，
        // 也**不再**重复哈希 HC 主 DLL——完整文件校验归部署边界（安装/更新/回滚/修复）。
        // 这里只做一次轻量"部署代"核对；记录缺失或不匹配才回落到一次完整校验并补齐记录。
        ValidateDeploymentGenerationForHcLoad();
        var hcPath = options.HcAssemblyPath ?? Path.Combine(options.HcRuntimeRoot ?? AppContext.BaseDirectory, "HandheldCompanion.dll");
        if (!File.Exists(hcPath)) throw new FileNotFoundException("HandheldCompanion.dll not found", hcPath);
        assemblyDirectory = Path.GetDirectoryName(Path.GetFullPath(hcPath));
        hcRuntimeDirectory = Path.GetFullPath(options.HcRuntimeRoot ?? assemblyDirectory!);
        ValidateGamepadMotion();
        AssemblyLoadContext.Default.Resolving += ResolveDependency;
        assembly = AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.GetFullPath(hcPath));
        ConfigureHcRuntime();
        // Match HC App.InitializeDevice/StartNonUIInit ordering. These are
        // initialization/read operations; the device cannot receive an EC or
        // ACPI write until the separately authorized Open() session below.
        InvokeStatic("HandheldCompanion.MotherboardInfo", "Collect");
        deviceType = assembly.GetType("HandheldCompanion.Devices.IDevice", throwOnError: true);
        if (string.IsNullOrWhiteSpace(options.HcDeviceType))
        {
            device = deviceType!.GetMethod("GetCurrent", BindingFlags.Public | BindingFlags.Static)?.Invoke(null, null)
                ?? throw new InvalidOperationException("HC IDevice.GetCurrent returned null");
        }
        else
        {
            // §18 诊断/无硬件联调：开发机不是 ROG 掌机，GetCurrent 不会返回 ROGAlly。
            // 按类型名构造候选设备实例，其余初始化步骤与生产一致。
            var requestedType = assembly.GetType(options.HcDeviceType, throwOnError: true)
                ?? throw new InvalidOperationException($"HC device type not found: {options.HcDeviceType}");
            device = Activator.CreateInstance(requestedType)
                ?? throw new InvalidOperationException($"HC device type could not be constructed: {options.HcDeviceType}");
        }
        try
        {
            Invoke(device, "PullSensors");
        }
        catch (Exception ex) when (Unwrap(ex).Any(item => item is PlatformNotSupportedException))
        {
            // HC treats IMU/serial sensor bootstrap as part of the desktop
            // application. A Fan Host on an unsupported desktop runtime can
            // still perform a truthful read-only device Gate; never turn this
            // environment limitation into a hardware-write permission.
            HcCoreWarning = "HC PullSensors skipped: current runtime does not support System.IO.Ports";
        }
        Invoke(device, "Initialize", false, false);
        hcCoreInitialized = true;
        DeviceIdentity = ReadIdentity(device);
    }

    /**
     * FAN-927 §2.2（2026-09-27 用户批准）：运行快路径。只做两件小事：① 对两个**小清单**
     * 取摘要；② 匹配一份小"部署记录"。任一不匹配（记录缺失、包代描述变更、便携包/旧安装
     * 首次启用）才回落到**一次**完整校验（ValidateSplitPayloadManifest），成功后补齐记录。
     *
     * 明确接受的信任调整：记录证明该包代在部署时完整，不保证每个 DLL 此刻仍与发布字节相同；
     * 绕过更新流程只改 DLL 并保持清单不变的离线替换不再由每次加载的全量哈希发现。
     */
    private const int DeploymentValidationRulesVersion = 1;

    private static string DeploymentRecordPath()
    {
        var isolated = Environment.GetEnvironmentVariable(HostDiagnosticLog.SelfTestLogRootEnvVar);
        var directory = string.IsNullOrWhiteSpace(isolated)
            ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "YeManCC", "fan-host")
            : isolated;
        Directory.CreateDirectory(directory);
        return Path.Combine(directory, "YeManFanHost.deployment.json");
    }

    private sealed class DeploymentRecord
    {
        public int SchemaVersion { get; init; }
        public int ValidationRulesVersion { get; init; }
        public string PayloadRoot { get; init; } = string.Empty;
        public string RuntimeRoot { get; init; } = string.Empty;
        public string PayloadManifestSha256 { get; init; } = string.Empty;
        public string RuntimeManifestSha256 { get; init; } = string.Empty;
        public string RuntimeId { get; init; } = string.Empty;
        public string Result { get; init; } = string.Empty;
    }

    private static DeploymentRecord? ReadDeploymentRecord(string path)
    {
        try
        {
            if (!File.Exists(path)) return null;
            using var document = JsonDocument.Parse(File.ReadAllText(path, Encoding.UTF8));
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object) return null;
            static string Text(JsonElement element, string name) =>
                element.TryGetProperty(name, out var value) && value.ValueKind == JsonValueKind.String
                    ? value.GetString() ?? string.Empty
                    : string.Empty;
            static int Number(JsonElement element, string name) =>
                element.TryGetProperty(name, out var value) && value.ValueKind == JsonValueKind.Number
                    ? value.GetInt32()
                    : -1;
            return new DeploymentRecord
            {
                SchemaVersion = Number(root, "schemaVersion"),
                ValidationRulesVersion = Number(root, "validationRulesVersion"),
                PayloadRoot = Text(root, "payloadRoot"),
                RuntimeRoot = Text(root, "runtimeRoot"),
                PayloadManifestSha256 = Text(root, "payloadManifestSha256"),
                RuntimeManifestSha256 = Text(root, "runtimeManifestSha256"),
                RuntimeId = Text(root, "runtimeId"),
                Result = Text(root, "result"),
            };
        }
        catch
        {
            return null;
        }
    }

    private static string ReadPayloadRuntimeId(string manifestPath)
    {
        using var document = JsonDocument.Parse(File.ReadAllText(manifestPath, Encoding.UTF8));
        var runtimeId = document.RootElement.TryGetProperty("runtimeId", out var value) && value.ValueKind == JsonValueKind.String
            ? value.GetString()
            : null;
        if (string.IsNullOrWhiteSpace(runtimeId)) throw new InvalidOperationException("Fan Host payload manifest 缺少 runtimeId");
        return runtimeId!;
    }

    private void WriteDeploymentRecord(string path, string payloadRoot, string runtimeRoot,
        string payloadManifestSha256, string runtimeManifestSha256, string runtimeId)
    {
        try
        {
            var record = new Dictionary<string, object?>
            {
                ["schemaVersion"] = 1,
                ["validationRulesVersion"] = DeploymentValidationRulesVersion,
                ["payloadRoot"] = payloadRoot.ToLowerInvariant(),
                ["runtimeRoot"] = runtimeRoot.ToLowerInvariant(),
                ["payloadManifestSha256"] = payloadManifestSha256.ToLowerInvariant(),
                ["runtimeManifestSha256"] = runtimeManifestSha256.ToLowerInvariant(),
                ["runtimeId"] = runtimeId,
                ["result"] = "ok",
                ["deployedAtUtc"] = DateTimeOffset.UtcNow.ToString("o"),
            };
            var staged = path + "." + Guid.NewGuid().ToString("N") + ".new";
            File.WriteAllText(staged, JsonSerializer.Serialize(record, JsonDefaults.Options));
            File.Move(staged, path, overwrite: true);
            Diagnostic?.Invoke("deployment.record-written", new { runtimeId });
        }
        catch (Exception ex)
        {
            Diagnostic?.Invoke("deployment.record-write-failed", new { error = DescribeException(ex) });
        }
    }

    private void ValidateDeploymentGenerationForHcLoad()
    {
        var hostRoot = Path.GetFullPath(AppContext.BaseDirectory).TrimEnd(Path.DirectorySeparatorChar);
        var runtimeRoot = Path.GetFullPath(hcRuntimeDirectory ?? options.HcRuntimeRoot ?? hostRoot).TrimEnd(Path.DirectorySeparatorChar);
        var payloadManifestPath = Path.Combine(hostRoot, "YeManFanHost.payload.json");
        var runtimeManifestPath = Path.Combine(runtimeRoot, "HandheldCompanion.runtime.json");
        if (!File.Exists(payloadManifestPath) || !File.Exists(runtimeManifestPath))
            throw new InvalidOperationException("Fan Host 部署不完整：缺少 payload/runtime manifest");
        var payloadManifestSha256 = Sha256(payloadManifestPath);
        var runtimeManifestSha256 = Sha256(runtimeManifestPath);
        var runtimeId = ReadPayloadRuntimeId(payloadManifestPath);
        var recordPath = DeploymentRecordPath();
        var record = ReadDeploymentRecord(recordPath);
        if (record is not null &&
            record.SchemaVersion == 1 &&
            record.ValidationRulesVersion == DeploymentValidationRulesVersion &&
            record.Result == "ok" &&
            string.Equals(record.PayloadRoot, hostRoot, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(record.RuntimeRoot, runtimeRoot, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(record.PayloadManifestSha256, payloadManifestSha256, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(record.RuntimeManifestSha256, runtimeManifestSha256, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(record.RuntimeId, runtimeId, StringComparison.Ordinal))
        {
            Diagnostic?.Invoke("deployment.record-hit", new { runtimeId });
            return;
        }
        Diagnostic?.Invoke("deployment.record-miss", new { recordPresent = record is not null, runtimeId });
        // 便携包/旧安装首次明确开启、包代描述变更、记录损坏：一次完整校验，成功后补齐记录。
        ValidateSplitPayloadManifest();
        WriteDeploymentRecord(recordPath, hostRoot, runtimeRoot, payloadManifestSha256, runtimeManifestSha256, runtimeId);
    }

    /**
     * The loopback token authorizes every local API request, so it belongs in
     * a private AppData sidecar rather than in the immutable executable tree.
     * Direct diagnostic packages use an explicitly supplied token elsewhere;
     * only the formal YeManCC sidecar path has this strict on-disk contract.
     */
    private void ValidateFormalSessionCapabilityAcl()
    {
        if (string.IsNullOrWhiteSpace(options.SessionTokenPath)) return;
        var expectedDirectory = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "YeManCC", "fan-host");
        var actualPath = Path.GetFullPath(options.SessionTokenPath);
        var actualDirectory = Path.GetDirectoryName(actualPath);
        if (actualDirectory is null ||
            !actualDirectory.Equals(Path.GetFullPath(expectedDirectory), StringComparison.OrdinalIgnoreCase))
            return;
        if (!File.Exists(actualPath) ||
            !IsPrivateCapabilityAcl(new DirectoryInfo(actualDirectory).GetAccessControl()) ||
            !IsPrivateCapabilityAcl(new FileInfo(actualPath).GetAccessControl()))
            throw new InvalidOperationException("Fan Host 会话令牌 ACL 不允许私有能力使用");
    }

    private void ValidatePayloadManifest()
    {
        // HC's frozen dependency closure still carries this legacy assembly,
        // but FanHost no longer loads it or uses it for temperature polling.
        // Do not make startup depend on being able to hash that optional file;
        // retain the manifest entry so the immutable payload remains explicit.
        const string legacyLhmAssembly = "LibreHardwareMonitorLib.dll";
        var manifestPath = Path.Combine(AppContext.BaseDirectory, "YeManFanHost.payload.json");
        if (!File.Exists(manifestPath))
            throw new InvalidOperationException("Fan Host payload manifest is missing");
        // 方案 A（2026-09-12）：manifest ACL 不可变强制已移除（禁加回）；
        // 保留 manifest 解析/防逃逸/哈希校验。
        using var document = JsonDocument.Parse(File.ReadAllText(manifestPath, Encoding.UTF8));
        var root = document.RootElement;
        if (!root.TryGetProperty("schemaVersion", out var schema) || schema.GetInt32() != 1 ||
            !root.TryGetProperty("files", out var files) || files.ValueKind != JsonValueKind.Array)
            throw new InvalidOperationException("Fan Host payload manifest is invalid");
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var entry in files.EnumerateArray())
        {
            if (!entry.TryGetProperty("path", out var relativeElement) || relativeElement.ValueKind != JsonValueKind.String ||
                !entry.TryGetProperty("sha256", out var expectedElement) || expectedElement.ValueKind != JsonValueKind.String)
                throw new InvalidOperationException("Fan Host payload manifest has an invalid entry");
            var relative = relativeElement.GetString()!;
            var expected = expectedElement.GetString()!;
            if (string.IsNullOrWhiteSpace(relative) || Path.IsPathRooted(relative) ||
                relative.Contains("..", StringComparison.Ordinal) || relative.Contains('/') || relative.Contains('\\') || expected.Length != 64 ||
                !expected.All(Uri.IsHexDigit))
                throw new InvalidOperationException("Fan Host payload manifest has an unsafe entry");
            if (!seen.Add(relative))
                throw new InvalidOperationException($"Fan Host payload manifest duplicates: {relative}");
            var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, relative));
            var basePath = Path.GetFullPath(AppContext.BaseDirectory).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
            if (!path.StartsWith(basePath, StringComparison.OrdinalIgnoreCase) || !File.Exists(path))
                throw new InvalidOperationException($"Fan Host payload entry is missing: {relative}");
            if (!relative.Equals(legacyLhmAssembly, StringComparison.OrdinalIgnoreCase) &&
                !Sha256(path).Equals(expected, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException($"Fan Host payload hash mismatch: {relative}");
        }
        foreach (var required in new[]
        {
            "YeManFanHost.exe", "YeManFanHost.dll", "YeManFanHost.deps.json",
            "YeManFanHost.runtimeconfig.json", "HandheldCompanion.deps.json", "HandheldCompanion.dll", "GamepadMotion.dll",
            // OneXPlayerOxpHidMonitor is part of HC's device factory and
            // directly binds the managed HIDAPI wrapper and native DLL.
            "hidapi.net.dll", "hidapi.dll",
            // IDevice.GetCurrent has a single all-device factory. These are
            // the non-UI input/HID bootstrap closure required before it can
            // select any HC device class, including the ROG Xbox route.
            "WindowsInput.dll", "GregsStack.InputSimulatorStandard.dll", "Gma.System.MouseKeyHook.dll",
            "HidLibrary.dll", "Nefarius.Utilities.DeviceManagement.dll", "Nefarius.Utilities.Bluetooth.dll",
            "Nefarius.Vicius.Abstractions.dll", "PInvoke.Kernel32.dll", "PInvoke.Windows.Core.dll",
            "SharpDX.dll", "SharpDX.Direct3D9.dll", "SharpDX.DirectInput.dll", "SharpDX.XInput.dll",
            // These files are the pinned Windows runtime-target implementations
            // of HC platform APIs. Generic compile-time variants fail during
            // MotherboardInfo initialization before a factory can be selected.
            "System.Management.dll", "System.IO.Ports.dll", "System.ServiceProcess.ServiceController.dll",
        })
        {
            if (!seen.Contains(required))
                throw new InvalidOperationException($"Fan Host payload manifest omits required file: {required}");
        }
        var allowed = new HashSet<string>(seen, StringComparer.OrdinalIgnoreCase)
        {
            "YeManFanHost.payload.json",
        };
        foreach (var file in Directory.EnumerateFiles(AppContext.BaseDirectory, "*", SearchOption.AllDirectories))
        {
            var relative = Path.GetRelativePath(AppContext.BaseDirectory, file);
            if (!allowed.Contains(relative))
                throw new InvalidOperationException($"Fan Host payload has an unexpected file: {relative}");
        }
        foreach (var directory in Directory.EnumerateDirectories(AppContext.BaseDirectory, "*", SearchOption.AllDirectories))
        {
            var relative = Path.GetRelativePath(AppContext.BaseDirectory, directory);
            throw new InvalidOperationException($"Fan Host payload has an unexpected directory: {relative}");
        }
    }

    private void ValidateSplitPayloadManifest()
    {
        var hostRoot = Path.GetFullPath(AppContext.BaseDirectory).TrimEnd(Path.DirectorySeparatorChar);
        var runtimeRoot = Path.GetFullPath(hcRuntimeDirectory ?? options.HcRuntimeRoot ?? hostRoot).TrimEnd(Path.DirectorySeparatorChar);
        if (!Directory.Exists(runtimeRoot)) throw new InvalidOperationException($"HC runtime directory is missing: {runtimeRoot}");
        // R-fan-Safe（2026-09-11，与 install-fan-host-payload.ps1 runtime 段同构）：
        // 旧实现 value.Contains('/') || value.Contains('\\') 会把任何含子路径的
        // 条目整体拒绝——HC runtime.json 合法包含 XInputPlus/Loader/...、
        // Resources/... 等子路径（911-23 已实证），凡含 '/' 必被 Safe 拒绝，
        // ValidateSplitPayloadManifest 一启动就抛"manifest entry is unsafe"，
        // 风扇 Host 必挂（conflict-locked 盲区即由该路径判定触发）。
        // 改为：只归一化分隔符（/ → \）+ IsPathRooted + 逐段 .. 判据；
        // 允许子目录分隔符，与 ps1 R3 语义完全一致。长度/hex/去重/哈希/ACL 不动。
        static bool Safe(string value)
        {
            if (string.IsNullOrWhiteSpace(value) || Path.IsPathRooted(value)) return false;
            var normalized = value.Replace(Path.AltDirectorySeparatorChar, Path.DirectorySeparatorChar);
            foreach (var segment in normalized.Split(Path.DirectorySeparatorChar))
            {
                // 逐段判据：仅 '..' 段逃逸为不安全；空段（a//b）允许（ps1 同构
                // 只查 (^|[\\/])\.\.([\\/]|$)，不拒空段）。
                if (segment == "..") return false;
            }
            return true;
        }
        HashSet<string> Read(string root, string manifestPath, int schema, string label)
        {
            if (!File.Exists(manifestPath)) throw new InvalidOperationException($"{label} manifest is missing: {manifestPath}");
            using var document = JsonDocument.Parse(File.ReadAllText(manifestPath, Encoding.UTF8));
            var element = document.RootElement;
            if (!element.TryGetProperty("schemaVersion", out var version) || version.GetInt32() != schema || !element.TryGetProperty("files", out var files) || files.ValueKind != JsonValueKind.Array) throw new InvalidOperationException($"{label} manifest is invalid");
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var entry in files.EnumerateArray())
            {
                var relative = entry.GetProperty("path").GetString() ?? string.Empty;
                var expected = entry.GetProperty("sha256").GetString() ?? string.Empty;
                if (!Safe(relative) || expected.Length != 64 || !expected.All(Uri.IsHexDigit) || !seen.Add(relative)) throw new InvalidOperationException($"{label} manifest entry is unsafe or duplicated: {relative}");
                var path = Path.Combine(root, relative);
                if (!File.Exists(path) || !Sha256(path).Equals(expected, StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException($"{label} payload hash/missing mismatch: {relative}");
            }
            return seen;
        }
        var host = Read(hostRoot, Path.Combine(hostRoot, "YeManFanHost.payload.json"), 2, "Fan Host");
        var runtime = Read(runtimeRoot, Path.Combine(runtimeRoot, "HandheldCompanion.runtime.json"), 1, "HC runtime");
        foreach (var required in new[] { "YeManFanHost.exe", "YeManFanHost.dll", "YeManFanHost.deps.json", "YeManFanHost.runtimeconfig.json" }) if (!host.Contains(required)) throw new InvalidOperationException($"Fan Host manifest omits required file: {required}");
        foreach (var required in new[] { "HandheldCompanion.dll", "HandheldCompanion.deps.json", "LibreHardwareMonitorLib.dll", "Microsoft.Windows.SDK.NET.dll", "WinRT.Runtime.dll", "GamepadMotion.dll", "hidapi.dll", "hidapi.net.dll" }) if (!runtime.Contains(required)) throw new InvalidOperationException($"HC runtime manifest omits required file: {required}");
        foreach (var file in Directory.EnumerateFiles(hostRoot, "*", SearchOption.TopDirectoryOnly)) if (!file.EndsWith("YeManFanHost.payload.json", StringComparison.OrdinalIgnoreCase) && !host.Contains(Path.GetFileName(file))) throw new InvalidOperationException($"Fan Host has an unexpected file: {Path.GetFileName(file)}");
        foreach (var file in Directory.EnumerateFiles(runtimeRoot, "*", SearchOption.TopDirectoryOnly)) if (!file.EndsWith("HandheldCompanion.runtime.json", StringComparison.OrdinalIgnoreCase) && !runtime.Contains(Path.GetFileName(file))) throw new InvalidOperationException($"HC runtime has an unexpected file: {Path.GetFileName(file)}");
    }

    // 方案 A（2026-09-12 用户裁决）：IsImmutablePayloadAcl / IsImmutableAcl 已删除
    // （payload ACL 不可变强制随脚本同步移除，禁加回）。阀门=防逃逸+存在+哈希；
    // 会话令牌侧仍保留 IsPrivateCapabilityAcl（私有能力 ACL，非 payload 强制）。

    private static bool IsPrivateCapabilityAcl(FileSystemSecurity security)
    {
        var currentUser = WindowsIdentity.GetCurrent().User
            ?? throw new InvalidOperationException("无法解析当前 Fan Host 用户 SID");
        var allowedPrincipals = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid, null).Value,
            new SecurityIdentifier(WellKnownSidType.LocalSystemSid, null).Value,
            currentUser.Value,
        };
        // As above, do not put composite Read/Modify/FullControl values in an
        // OR mask. Only atomic rights preserve an exact ACL interpretation.
        const FileSystemRights readRights = FileSystemRights.ReadData | FileSystemRights.ListDirectory |
            FileSystemRights.ReadAttributes | FileSystemRights.ReadExtendedAttributes |
            FileSystemRights.ReadPermissions | FileSystemRights.ExecuteFile;
        foreach (FileSystemAccessRule rule in security.GetAccessRules(includeExplicit: true, includeInherited: true, typeof(SecurityIdentifier)))
        {
            if (rule.AccessControlType != AccessControlType.Allow || rule.IdentityReference is not SecurityIdentifier sid ||
                !((rule.FileSystemRights & readRights) != 0 || HasUnsafeWriteRights(rule.FileSystemRights))) continue;
            if (!allowedPrincipals.Contains(sid.Value)) return false;
        }
        return true;
    }

    private static bool HasUnsafeWriteRights(FileSystemRights rights)
    {
        // Do not use Modify or FullControl here. Both are composites and
        // therefore overlap with read-only rights in an AND expression.
        const FileSystemRights atomicWriteRights = FileSystemRights.WriteData | FileSystemRights.AppendData |
            FileSystemRights.WriteAttributes | FileSystemRights.WriteExtendedAttributes | FileSystemRights.Delete |
            FileSystemRights.DeleteSubdirectoriesAndFiles | FileSystemRights.ChangePermissions |
            FileSystemRights.TakeOwnership;
        return (rights & atomicWriteRights) != 0;
    }

    private Assembly? ResolveDependency(AssemblyLoadContext _, AssemblyName name)
    {
        if (assemblyDirectory is null || string.IsNullOrWhiteSpace(name.Name)) return null;
        var path = Path.Combine(hcRuntimeDirectory ?? assemblyDirectory, name.Name + ".dll");
        return File.Exists(path) ? AssemblyLoadContext.Default.LoadFromAssemblyPath(path) : null;
    }

    private void ConfigureHcRuntime()
    {
        if (assembly is null) return;
        Directory.SetCurrentDirectory(AppContext.BaseDirectory);
        var root = Path.Combine(Path.GetTempPath(), "YeManFanHost-HC");
        var logs = Path.Combine(root, "logs");
        Directory.CreateDirectory(logs);
        Environment.SetEnvironmentVariable("LOG_PATH", logs);
        var appType = assembly.GetType("HandheldCompanion.App");
        SetStaticMember(appType, "SettingsPath", root);
        SetStaticMember(appType, "LogsPath", logs);
        SetStaticMember(appType, "InstallPath", hcRuntimeDirectory ?? AppContext.BaseDirectory);
        SetStaticMember(appType, "GameControllerDbPath", Path.Combine(hcRuntimeDirectory ?? AppContext.BaseDirectory, "gamecontrollerdb.txt"));
        var shared = AssemblyLoadContext.Default.Assemblies.FirstOrDefault(item => item.GetName().Name == "Shared")
            ?? (hcRuntimeDirectory is not null && File.Exists(Path.Combine(hcRuntimeDirectory, "Shared.dll"))
                ? AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(hcRuntimeDirectory, "Shared.dll"))
                : null);
        var logType = shared?.GetType("HandheldCompanion.Shared.LogManager");
        var init = logType?.GetMethod("Initialize", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static, [typeof(string)]);
        if (init is null) throw new MissingMethodException("HandheldCompanion.Shared.LogManager.Initialize not found");
        init?.Invoke(null, ["YeManFanHost"]);
        // ManagerFactory is not started by the Host. Its lifecycle begins as
        // Unknown and is observed only after the real OpenEvents boundary.
        ResetManagerLifecycle();
    }

    private void ValidateGamepadMotion()
    {
        var path = Path.Combine(hcRuntimeDirectory ?? assemblyDirectory!, "GamepadMotion.dll");
        if (!File.Exists(path)) throw new FileNotFoundException("GamepadMotion.dll not found", path);
        if (!NativeLibrary.TryLoad(path, out var handle)) throw new InvalidOperationException("GamepadMotion.dll could not load");
        NativeLibrary.Free(handle);
    }

    private bool IsAuthorized()
    {
        if (!options.AllowHardwareWrites || !HasValidWriteConfirmation()) return false;
        if (string.IsNullOrWhiteSpace(options.AuthorizationPath) || !File.Exists(options.AuthorizationPath)) return false;
        var text = File.ReadAllText(options.AuthorizationPath);
        var generic = text.Contains("hardwareWriteAuthorizationGranted: true", StringComparison.OrdinalIgnoreCase)
            || text.Contains("hardwareWritesAuthorized: true", StringComparison.OrdinalIgnoreCase);
        var allMapped = text.Contains("allMappedFanRoutesAuthorized: true", StringComparison.OrdinalIgnoreCase) && generic;
        var gpd = text.Contains("batch12Authorized: true", StringComparison.OrdinalIgnoreCase) && generic;
        var rog = text.Contains("batch13HardwareWriteAuthorizationGranted: true", StringComparison.OrdinalIgnoreCase);
        // Authorization is never enough by itself: the selected HC factory
        // route must remain one of the audited mapped routes.
        if (Route is null || !Route.HcCallbackReady) return false;
        if (allMapped) return true;
        if (FactoryType == "HandheldCompanion.Devices.GPDWin5") return gpd;
        if (FactoryType is "HandheldCompanion.Devices.XboxROGAlly" or "HandheldCompanion.Devices.XboxROGAllyX") return rog;
        return false;
    }

    private void EnsureRealWriteAuthorization()
    {
        // The route is only known after the pinned HC assembly has selected a
        // device.  Do not test CanWrite before that load: an authorized first
        // Open() after process start must be able to complete the same
        // handshake/load gate as an explicit /api/handshake call.
        if (!options.AllowHardwareWrites || !HasValidWriteConfirmation()
            || string.IsNullOrWhiteSpace(options.AuthorizationPath) || !File.Exists(options.AuthorizationPath))
            throw new FanApiException(403, "REAL_WRITE_AUTH_REQUIRED", "真实风扇写入需要独立授权文件与确认口令");
        if (!IsLoaded) LoadAssemblyAndFactory();
        if (!CanWrite) throw new FanApiException(403, "REAL_WRITE_AUTH_REQUIRED", "真实风扇写入需要独立授权文件与确认口令");
        if (!hcCoreInitialized) throw new FanApiException(409, "HC_NOT_INITIALIZED", "HC 核心初始化尚未完成");
        if (FactoryType is null || Route is null) throw new FanApiException(409, "FAN_UNSUPPORTED", "风扇不支持");
        var capabilities = GetMember(device!, "Capabilities");
        if (capabilities is not null)
        {
            var fanFlag = Enum.Parse(capabilities.GetType(), "FanControl");
            var hasFanControl = capabilities.GetType().GetMethod("HasFlag")?.Invoke(capabilities, [fanFlag]) as bool?;
            if (hasFanControl == false)
                throw new FanApiException(409, "FAN_UNSUPPORTED", "HC 当前设备未声明 FanControl 能力");
        }
    }

    /**
     * A real-write launch must prove possession of this Host instance's random
     * loopback session token. Do not accept a repository-wide confirmation
     * string: it could be replayed by an unrelated local process long after a
     * UI session was closed.
     */
    private bool HasValidWriteConfirmation()
    {
        var confirmation = options.Confirmation;
        var session = options.SessionToken;
        return !string.IsNullOrWhiteSpace(confirmation) && !string.IsNullOrWhiteSpace(session)
            && CryptographicOperations.FixedTimeEquals(
                Encoding.UTF8.GetBytes(confirmation), Encoding.UTF8.GetBytes(session));
    }

    private void EnsureRealWriteSession()
    {
        EnsureRealWriteAuthorization();
        if (!IsOpen) throw new FanApiException(409, "HOST_NOT_OPEN", "HC 尚未 Open");
        try
        {
            EnsureHcSessionReadyForControl();
        }
        catch (InvalidOperationException ex) when (ex.Message.StartsWith("HC_SESSION_ROUTE_LOST:", StringComparison.Ordinal))
        {
            throw new FanApiException(409, "HC_SESSION_ROUTE_LOST", "HC 风扇设备/路线标记已丢失，已拒绝写入");
        }
    }

    private void EnsureRestoreSession()
    {
        // Recovery is a capability of the already-open HC session. It must not
        // depend on a new authorization file/confirmation token: those inputs
        // are intentionally allowed to disappear after a write has begun.
        if (!openAttempted && !IsOpen)
            throw new FanApiException(409, "HOST_NOT_OPEN", "HC 尚未进入可恢复会话");
        if (device is null || !hcCoreInitialized || Route is null)
            throw new FanApiException(409, "HOST_RECOVERY_UNAVAILABLE", "HC 恢复会话不可用");
    }

    private Type? FindType(string fullName) => assembly?.GetType(fullName) ?? assembly?.GetTypes().FirstOrDefault(t => t.Name == fullName[(fullName.LastIndexOf('.') + 1)..]);
    private object? Invoke(string name, params object?[] args) => Invoke(device ?? throw new InvalidOperationException("HC device unavailable"), name, args);
    private static object? Invoke(object target, string name, params object?[] args)
    {
        var method = target.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
            .FirstOrDefault(m => m.Name == name && m.GetParameters().Length == args.Length)
            ?? throw new MissingMethodException(target.GetType().FullName, name);
        return method.Invoke(target, args);
    }

    private void TryInvokeOptional(string name, params object?[] args)
    {
        var method = device?.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
            .FirstOrDefault(m => m.Name == name && m.GetParameters().Length == args.Length);
        method?.Invoke(device, args);
    }

    private static object? GetStaticMember(Type? type, string name)
    {
        for (var current = type; current is not null; current = current.BaseType)
        {
            var flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.DeclaredOnly;
            var property = current.GetProperty(name, flags);
            if (property is not null) return property.GetValue(null);
            var field = current.GetField(name, flags);
            if (field is not null) return field.GetValue(null);
        }
        return null;
    }

    private object? InvokeStatic(string fullTypeName, string name, params object?[] args)
    {
        var targetType = FindType(fullTypeName) ?? throw new MissingMemberException(fullTypeName);
        var method = targetType.GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)
            .FirstOrDefault(m => m.Name == name && m.GetParameters().Length == args.Length)
            ?? throw new MissingMethodException(fullTypeName, name);
        return method.Invoke(null, args);
    }

    private static object? InvokeStaticMember(Type targetType, string name, params object?[] args)
    {
        var method = targetType.GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)
            .FirstOrDefault(m => m.Name == name && m.GetParameters().Length == args.Length)
            ?? throw new MissingMethodException(targetType.FullName, name);
        return method.Invoke(null, args);
    }

    private static void SetStaticMember(Type? type, string name, object? value)
    {
        if (type is null) return;
        var property = type.GetProperty(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static);
        if (property?.CanWrite == true) { property.SetValue(null, value); return; }
        type.GetField(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static)?.SetValue(null, value);
    }

    private static void SetMember(object target, string name, object value)
    {
        var type = target.GetType();
        var property = type.GetProperty(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
        if (property?.CanWrite == true) { property.SetValue(target, value); return; }
        type.GetField(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)?.SetValue(target, value);
    }

    private static object? GetMember(object target, string name)
    {
        for (var type = target.GetType(); type is not null; type = type.BaseType)
        {
            var flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.DeclaredOnly;
            var property = type.GetProperty(name, flags);
            if (property is not null) return property.GetValue(target);
            var field = type.GetField(name, flags);
            if (field is not null) return field.GetValue(target);
        }
        return null;
    }

    /**
     * FAN-936 §9：把任意 HC 结果对象投影成"属性名 → 归一化值"的字典，供现场取证卡与
     * `--msi-readonly-sample` 直接序列化。只读 public 实例属性；单个属性读取失败不炸整张卡
     * （记成 `error:<类型>`），也不制造任何写入。null 入参 → null（区别于空对象）。
     */
    private static Dictionary<string, object?>? ReflectPublicState(object? source)
    {
        if (source is null) return null;
        var map = new Dictionary<string, object?>(StringComparer.Ordinal);
        foreach (var property in source.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance))
        {
            if (property.GetIndexParameters().Length != 0) continue;
            object? value;
            try { value = property.GetValue(source); }
            catch (Exception ex) { value = "error:" + ex.GetType().Name; }
            map[property.Name] = NormalizeReflectedValue(value);
        }
        return map;
    }

    /** 归一化：字节数组转 HEX，枚举转名，其余原值（复杂对象退化为 ToString）。 */
    private static object? NormalizeReflectedValue(object? value) => value switch
    {
        null => null,
        byte[] bytes => Convert.ToHexString(bytes),
        Enum enumeration => enumeration.ToString(),
        _ when value!.GetType().IsPrimitive || value is string || value is decimal => value,
        _ => value.ToString(),
    };

    private static bool SetInstanceBoolField(object target, string[] names, bool value)
    {
        for (var type = target.GetType(); type is not null; type = type.BaseType)
        {
            foreach (var name in names)
            {
                var field = type.GetField(
                    name,
                    BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.DeclaredOnly);
                if (field is not null && field.FieldType == typeof(bool))
                {
                    field.SetValue(target, value);
                    return true;
                }
            }
        }
        return false;
    }

    private int hcControllerCpuLoopStopActions;
    /**
     * P-3（FAN-204 s31 补充裁决 2026-09-23，立案取证；**不改冻结 HC 源码**）：
     * HC controller loop 的 stop 尝试 / 实际结果 / reopen→stop 节拍记账（只诊断）。
     * `attempts` 含"没有循环在跑"的空转尝试；`session*` 在同一 HC 会话（OpenEvents
     * 边界起算）内归零重计；`lastStopTick` 用于算 reopen→stop 周期（两次真的停到之间，
     * 就是 HC 侧把 loop 重开了一次的间隔）。
     */
    private int hcLoopStopAttempts;
    private int hcLoopStopIdleAttempts;
    private long hcLoopStopSessionId;
    private long hcLoopStopSessionStartedTick;
    private long hcLoopStopSessionAttempts;
    private long hcLoopStopSessionStops;
    private long hcLoopStopLastStopTick;

    /**
     * P-3 收口（2026-09-24 裁决 B）：**按 resume generation 的 loop 记账 + 预算判据**。
     *
     * 真机 01:10 包已证"能发现并停止重开的 loop"（`reopenToStopMs=4265`、`cpuMsPerSec=12.8`），
     * 但没有"每个恢复代次的次数/延迟/CPU 上限"的可裁决读数。本账本把每次 stop 尝试按
     * `powerGeneration` 归集，超预算时发**独立事件**（不伪造成功、不静默）。
     *
     * 目标阈值（裁决 B.2；不是"已消除重开"——HC 侧重开不受宿主控制，见下方注释）：
     *   - 单代次 stop actions 上限：`HcLoopStopActionsPerGenerationBudget`；
     *   - reopen→stop 延迟上限：`HcLoopReopenToStopMsBudget`（超了说明"重开后很久才停"）；
     *   - 单代次 CPU 上限：`HcLoopCpuMsPerSecCeiling`（单核 ms/s；真机重建期峰值 27.1）。
     * 不可安全禁止重开：loop 由 HC 自己的设备/管理器代码重开，宿主只能在**发现后**停它；
     * 冻结 HC 源码不得改动 ⇒ 本批保留为**受控重开**（有次数/延迟/CPU 预算 + 超限留痕），
     * **不得写成"已消除"**。
     */
    internal const int HcLoopStopActionsPerGenerationBudget = 24;
    /**
     * reopen→stop 延迟预算。**取值依据 = 真机实测包络**（2026-09-24 01:10 包，按代次归集）：
     * gen 4 = 4 265 ms、gen 0 = 25 438 ms、gen 3 = 30 015 ms ⇒ 观测上限 ≈30 s。预算必须
     * **高于观测包络**才有意义（否则把正常节拍判成病态）；取 60 s = 观测上限 ×2 余量。
     * 超 60 s 意味着"loop 重开后超过 1 分钟才被停掉"，属需要调查的病态，不是本批已消除项。
     */
    internal const int HcLoopReopenToStopMsBudget = 60_000;
    /**
     * 单代次 CPU 上限（单核 ms/s）。真机实测同包：runtime-sample 峰值 40.1 ms/s
     * （≈0.25% 全机，16 逻辑处理器口径），空闲 0.8–5 ms/s ⇒ 取 200 ms/s（≈1.25% 全机）
     * 作病态阈值，留 5× 余量。
     */
    internal const double HcLoopCpuMsPerSecCeiling = 200.0;

    private sealed class HcLoopGenerationLedger
    {
        internal long Generation = -1;
        internal int StopCalls;        // 本代内"真的停到"的调用次数（= 观测到的 reopen 次数）
        internal int StopActions;      // 本代内累计 stop actions
        internal int Attempts;         // 本代内全部尝试（含空转）
        internal int IdleAttempts;
        internal long FirstStopTick;
        internal long LastStopTick;
        internal int LastReopenToStopMs = -1;
        internal int MaxReopenToStopMs = -1;
        internal double LastCpuMsPerSec = -1;
        internal double MaxCpuMsPerSec = -1;
        internal bool ActionsExceeded;
        internal bool ReopenLatencyExceeded;
        internal bool CpuExceeded;
        // ---- P-3 目标 A（FAN-204 §31 R4 阶段 2，2026-09-24）：settle→stop→verify 三段证据 ----
        // 与主账本同代次归集；三段分开计数，绝不把"请求已接受"当成"已停止"。
        internal int StopRequests;            // ② stop：停止请求被接受的次数
        internal int StopVerified;            // ③ verify：复核到"真的结束"的次数
        internal int SettleDeferred;          // ① settle：因打开管线在途而推迟停止的次数
        internal int VerifyPending;           // 复核仍显示未结束的次数（受控残留留痕）
        internal int StopAlreadyPending;      // FAN-931 P1.1：已有未决停止请求时**只观察、不重复提交**的次数
        internal long PendingStopRequestTick; // 未被复核的停止请求时刻（0=无未决）
        internal int LastStopToVerifyMs = -1; // 最近一次 stop→verify 间隔
        internal string LastSettleDetail = "none";
        internal string LastVerifyDetail = "none";

        /**
         * P-3 收口：**唯一的归集实现**（真机路径与自测共用，杜绝"两套算术"漂移）。
         * 返回本次**新**触发预算超限的维度名（每个维度每代只报一次；空列表=未超限）。
         */
        internal List<string> Observe(bool stoppedAnything, int stopActionCount, long attemptTick, long sinceLastStopMs, double? cpuMsPerSec, bool idleAttempt)
        {
            var exceeded = new List<string>();
            Attempts++;
            if (idleAttempt)
            {
                // 空转尝试（此刻没有 loop 在跑）：只记账，不推进 reopen→stop 周期。
                IdleAttempts++;
                return exceeded;
            }
            if (cpuMsPerSec is double cpu)
            {
                LastCpuMsPerSec = cpu;
                if (cpu > MaxCpuMsPerSec) MaxCpuMsPerSec = cpu;
            }
            if (stoppedAnything)
            {
                StopCalls++;
                StopActions += stopActionCount;
                if (FirstStopTick == 0) FirstStopTick = attemptTick;
                LastStopTick = attemptTick;
                if (sinceLastStopMs >= 0)
                {
                    LastReopenToStopMs = (int)sinceLastStopMs;
                    if (sinceLastStopMs > MaxReopenToStopMs) MaxReopenToStopMs = (int)sinceLastStopMs;
                }
            }
            if (StopActions > HcLoopStopActionsPerGenerationBudget && !ActionsExceeded)
            {
                ActionsExceeded = true;
                exceeded.Add("stop-actions-per-generation");
            }
            if (MaxReopenToStopMs > HcLoopReopenToStopMsBudget && !ReopenLatencyExceeded)
            {
                ReopenLatencyExceeded = true;
                exceeded.Add("reopen-to-stop-ms");
            }
            if (MaxCpuMsPerSec > HcLoopCpuMsPerSecCeiling && !CpuExceeded)
            {
                CpuExceeded = true;
                exceeded.Add("cpu-ms-per-sec");
            }
            return exceeded;
        }
    }

    private HcLoopGenerationLedger hcLoopLedger = new();
    /** 已结束代次的账本（有界：只留最近 8 代，避免长驻进程无界增长）。 */
    private readonly List<HcLoopGenerationLedger> hcLoopLedgerHistory = new();
    internal const int HcLoopLedgerHistoryKeep = 8;

    /** gate 无关（只在 stop 路径的单线程调用序列里用）；返回本代账本，必要时换页。 */
    private HcLoopGenerationLedger LedgerFor(long generation)
    {
        var gen = generation >= 0 ? generation : -1;
        if (hcLoopLedger.Generation != gen)
        {
            if (hcLoopLedger.Generation != -1) hcLoopLedgerHistory.Add(hcLoopLedger);
            while (hcLoopLedgerHistory.Count > HcLoopLedgerHistoryKeep) hcLoopLedgerHistory.RemoveAt(0);
            hcLoopLedger = new HcLoopGenerationLedger { Generation = gen };
        }
        return hcLoopLedger;
    }

    /** P-3（自测/取证）：本代 + 历史代的只读读数。 */
    internal object HcLoopGenerationLedgersForSelfTest
    {
        get
        {
            object Snapshot(HcLoopGenerationLedger l) => new
            {
                generation = l.Generation,
                stopCalls = l.StopCalls,
                stopActions = l.StopActions,
                attempts = l.Attempts,
                idleAttempts = l.IdleAttempts,
                firstStopTick = l.FirstStopTick,
                lastStopTick = l.LastStopTick,
                lastReopenToStopMs = l.LastReopenToStopMs,
                maxReopenToStopMs = l.MaxReopenToStopMs,
                lastCpuMsPerSec = l.LastCpuMsPerSec,
                maxCpuMsPerSec = l.MaxCpuMsPerSec,
                actionsExceeded = l.ActionsExceeded,
                reopenLatencyExceeded = l.ReopenLatencyExceeded,
                cpuExceeded = l.CpuExceeded,
                // P-3 目标 A（阶段 2）：三段证据（stopRequested / stopVerified / settleDeferred / verifyPending）。
                stopRequests = l.StopRequests,
                stopVerified = l.StopVerified,
                settleDeferred = l.SettleDeferred,
                verifyPending = l.VerifyPending,
                // FAN-931 P1.1：已有未决停止请求时只观察、不重复提交的次数（旧实现重复提交并计入 stopRequests）。
                stopAlreadyPending = l.StopAlreadyPending,
                lastStopToVerifyMs = l.LastStopToVerifyMs,
                lastSettleDetail = l.LastSettleDetail,
                lastVerifyDetail = l.LastVerifyDetail,
            };
            return new
            {
                current = Snapshot(hcLoopLedger),
                history = hcLoopLedgerHistory.Select(Snapshot).ToArray(),
                budget = new
                {
                    stopActionsPerGeneration = HcLoopStopActionsPerGenerationBudget,
                    reopenToStopMs = HcLoopReopenToStopMsBudget,
                    cpuMsPerSecCeiling = HcLoopCpuMsPerSecCeiling,
                },
            };
        }
    }

    /// <summary>
    /// F1' (2026-09-17, CPU-targeted): stop HC's tight CPU loops inside this headless host.
    /// HC's per-device HID read loop (`while (IsReading) await ReadReportAsync()`) and the
    /// SDL hotplug pump (`while (pumpThreadRunning) SDL.WaitEvent()`) are tight loops that
    /// spin once HidHide + the virtual pad take the built-in controller away (measured on
    /// the test machine: 5 loops ~= 2 cores, 98.7% of the runaway). Only the controlling
    /// flags are flipped here - never ControllerManager.Stop(), which would Suspend() and
    /// possibly unhide controllers and fight HidHide. Idempotent and diagnostic-logged;
    /// callers re-assert it from the existing runtime diagnostics timer, so a loop created
    /// by a later device event is stopped within one sample instead of burning until exit.
    /// </summary>
    public bool StopHcControllerCpuLoops(string source, long powerGeneration = -1, string? hostState = null, double? cpuMsPerSec = null)
    {
        var stopped = new List<string>();
        var failures = new List<string>();
        // P-3：本函数是"宿主侧发现的 HC loop 重开"的唯一入口 ⇒ 每一次调用=一次 stop 尝试；
        // 只有真的停到（stopped.Count>0）才算 reopen→stop 周期的结束点。
        var attemptTick = Environment.TickCount64;
        var attempt = Interlocked.Increment(ref hcLoopStopAttempts);
        Interlocked.Increment(ref FanPerfCounters.LoopStopAttempts);
        var sessionAttempt = ++hcLoopStopSessionAttempts;
        var sessionAgeMs = hcLoopStopSessionStartedTick > 0 ? attemptTick - hcLoopStopSessionStartedTick : -1;
        var sinceLastStopMs = hcLoopStopLastStopTick > 0 ? attemptTick - hcLoopStopLastStopTick : -1;
        var verifiedThisTick = false;
        // FAN-931 P1.1：本 tick 是否只在复核一个**已存在的**未决停止请求（既非空转，也非新停止）。
        var observedExistingPending = false;
        try
        {
            if (device is not null)
            {
                // §18.2-A：候选 HC 提供版本化接口时，用明确的停止入口（不再反射写私有布尔字段）。
                var readLoopState = GetMember(device, "ReadLoopState");
                if (GetMember(device, "LifecycleApiVersion") is int lifecycleApiVersion && lifecycleApiVersion >= 1)
                {
                    // ---- P-3 目标 A（FAN-204 §31 R4 阶段 2，2026-09-24）：settle 后再停 + 复核 ----
                    // 判据来源（树 B == 线上 DLL）：读循环只能由打开操作启动/取代，自身不重启；每步打开
                    // 都经 AdmitDeviceCallOrWait 串行准入 ⇒ 在管线在途期间停循环是宿主侧自造的竞态
                    // （真机 reopenToStopMs=4265 的自洽解释）。判定实现在 EvaluateLoopStop（真机与自测
                    // **共用同一实现**）；全部探针 0ms 非阻塞：本函数在 hardwareGate 持有期（open-events）
                    // 与 5s 采样上被调用，任何阻塞都会拖慢既有边界。
                    verifiedThisTick = EvaluateLoopStop(
                        new LifecycleLoopStopProbe(device),
                        LedgerFor(powerGeneration),
                        source,
                        attemptTick,
                        readLoopState?.ToString() ?? "unknown",
                        loopPresent: readLoopState?.ToString() != "NotStarted",
                        stopped,
                        failures,
                        out observedExistingPending);
                }
                else
                {
                    var reading = GetMember(device, "IsReading") ?? GetMember(device, "isReading");
                    if (reading is bool isReading && isReading)
                    {
                        if (SetInstanceBoolField(device, new[] { "IsReading", "isReading" }, false))
                            stopped.Add("device-read-loop");
                        else
                            failures.Add("device-read-loop:boolean-field-not-writable");
                    }
                }
            }

            var controllerManager = FindType("HandheldCompanion.Managers.ControllerManager");
            if (controllerManager is not null)
            {
                if (GetStaticMember(controllerManager, "pumpThreadRunning") is bool pumpRunning && pumpRunning)
                {
                    SetStaticMember(controllerManager, "pumpThreadRunning", false);
                    stopped.Add("sdl-hotplug-pump");
                }

                var modeField = controllerManager.GetField(
                    "slotManagementMode",
                    BindingFlags.Static | BindingFlags.NonPublic);
                if (modeField is not null && modeField.FieldType.IsEnum)
                {
                    var manual = Enum.Parse(modeField.FieldType, "Manual");
                    if (!Equals(modeField.GetValue(null), manual))
                    {
                        modeField.SetValue(null, manual);
                        stopped.Add("slot-management-manual");
                    }
                }
            }
        }
        catch (Exception ex)
        {
            failures.Add(DescribeException(ex));
        }

        if (stopped.Count == 0 && failures.Count == 0 && !verifiedThisTick && !observedExistingPending)
        {
            // P-3：空转尝试（此刻没有 loop 在跑）只记账不写行——事件式日志，零周期开销；
            //      "本轮只做了复核"不算空转（已在上方 verify 段登记）；FAN-931 P1.1：只复核
            //      一个既有未决请求同样不算空转（它本身就在推进收敛观察）。
            Interlocked.Increment(ref hcLoopStopIdleAttempts);
            _ = LedgerFor(powerGeneration).Observe(false, 0, attemptTick, -1, null, idleAttempt: true);
            return false;
        }

        var ledger = LedgerFor(powerGeneration);
        if (stopped.Count > 0)
        {
            Interlocked.Add(ref hcControllerCpuLoopStopActions, stopped.Count);
            hcLoopStopSessionStops += stopped.Count;
            hcLoopStopLastStopTick = attemptTick;
            hcLoopStopLastStopAckSource = source;
        }
        else
        {
            // 只失败（没停到）：不推进 reopen→stop 周期（那条周期没闭合）。
            Interlocked.Add(ref hcControllerCpuLoopStopActions, 0);
        }
        // P-3 收口：按代次归集（**唯一实现** = ledger.Observe，真机与自测共用）。
        var budgetExceeded = ledger.Observe(stopped.Count > 0, stopped.Count, attemptTick, sinceLastStopMs, cpuMsPerSec, idleAttempt: false);
        // P-3 预算判定：超限**只发独立事件**（留痕，不改变任何控制语义、不伪造成功）；
        // 每个阈值每代只报一次（由 Observe 保证），避免高频。
        foreach (var dimension in budgetExceeded)
        {
            var observed = dimension switch
            {
                "stop-actions-per-generation" => (object)ledger.StopActions,
                "reopen-to-stop-ms" => ledger.MaxReopenToStopMs,
                _ => ledger.MaxCpuMsPerSec,
            };
            var budget = dimension switch
            {
                "stop-actions-per-generation" => (object)HcLoopStopActionsPerGenerationBudget,
                "reopen-to-stop-ms" => HcLoopReopenToStopMsBudget,
                _ => HcLoopCpuMsPerSecCeiling,
            };
            Diagnostic?.Invoke("hc.controller-loop-budget-exceeded", new
            {
                generation = ledger.Generation,
                dimension,
                observed,
                budget,
                note = "HC 侧重开不受宿主控制；本批为受控重开（有预算+留痕），不得写成已消除",
            });
        }

        if (stopped.Count > 0 || failures.Count > 0 || verifiedThisTick)
        {
            Diagnostic?.Invoke("hc.controller-cpu-loops-stopped", new
            {
                source,
                stopped,
                failures,
                totalStopActions = hcControllerCpuLoopStopActions,
                // P-3 取证字段（同一会话内）：尝试/空转、reopen→stop 周期、会话年龄、电源代次与
                // 当时的宿主状态、以及本次采样 CPU——用于判定"是谁把 loop 开回来的节拍"。
                attempt,
                idleAttempts = Volatile.Read(ref hcLoopStopIdleAttempts),
                sessionId = hcLoopStopSessionId,
                sessionAgeMs,
                sessionAttempt = sessionAttempt,
                sessionStops = hcLoopStopSessionStops,
                reopenToStopMs = sinceLastStopMs,
                stopAckSource = hcLoopStopLastStopAckSource,
                powerGeneration,
                hostState = hostState ?? "unknown",
                cpuMsPerSec,
                hcPhase = CurrentHcPhase,
                route = Route?.Kind.ToString(),
                // G-1（2026-09-27 消费侧取证）：停止/失败这一拍把 HC **已有**的逐轮收据、
                // 输入绑定在场性与清理台账一并带出（只读、不改判定）。
                hcReceipts = HcReceiptsEvidence,
                // P-3 收口（裁决 B.1）：**按代次**的次数/首次/最后/最大 reopen→stop/CPU 与预算标记。
                generation = ledger.Generation,
                genStopCalls = ledger.StopCalls,
                genStopActions = ledger.StopActions,
                genAttempts = ledger.Attempts,
                genIdleAttempts = ledger.IdleAttempts,
                genFirstStopTick = ledger.FirstStopTick,
                genLastStopTick = ledger.LastStopTick,
                genLastReopenToStopMs = ledger.LastReopenToStopMs,
                genMaxReopenToStopMs = ledger.MaxReopenToStopMs,
                genMaxCpuMsPerSec = ledger.MaxCpuMsPerSec,
                genBudgetExceeded = ledger.ActionsExceeded || ledger.ReopenLatencyExceeded || ledger.CpuExceeded,
                // P-3 目标 A（阶段 2）：settle→stop→verify 三段证据与复核细节（同一代次）。
                genStopRequests = ledger.StopRequests,
                genStopVerified = ledger.StopVerified,
                genSettleDeferred = ledger.SettleDeferred,
                genVerifyPending = ledger.VerifyPending,
                genLastStopToVerifyMs = ledger.LastStopToVerifyMs,
                lastSettleDetail = ledger.LastSettleDetail,
                lastVerifyDetail = ledger.LastVerifyDetail,
                verifiedThisTick,
            });
        }
        return stopped.Count > 0;
    }

    /**
     * P-3 收口自测（2026-09-24 裁决 B.2）：**确定性模型**——只用 ledger.Observe（真机同一实现），
     * 不碰 HC、不碰设备、不睡眠。验证：① 归集算术（次数/首次/最后/最大 reopen→stop/CPU）；
     * ② 三个预算阈值的**边界**（恰好等于预算=不超；超一点=超）；③ 每维度每代只报一次；
     * ④ 换代次会开新账本且历史有界。
     */
    internal static IReadOnlyList<string> RunHcLoopBudgetSelfTest()
    {
        var checks = new List<string>();
        // ① 归集算术：3 次停止（actions 1/1/2）+ 2 次空转 + CPU 峰值 12.8
        var l = new HcLoopGenerationLedger { Generation = 7 };
        var e1 = l.Observe(true, 1, 1000, -1, 5.0, false);
        var e2 = l.Observe(true, 1, 5000, 4000, 12.8, false);
        var e3 = l.Observe(false, 0, 6000, -1, null, true);
        var e4 = l.Observe(true, 2, 9000, 4000, 3.0, false);
        checks.Add((l.StopCalls == 3 && l.StopActions == 4 && l.Attempts == 4 && l.IdleAttempts == 1 &&
                    l.FirstStopTick == 1000 && l.LastStopTick == 9000 && l.LastReopenToStopMs == 4000 &&
                    l.MaxReopenToStopMs == 4000 && l.MaxCpuMsPerSec == 12.8 && l.LastCpuMsPerSec == 3.0)
            ? "hc-loop-budget-self-test: ledger arithmetic OK"
            : $"hc-loop-budget-self-test: ledger arithmetic WRONG (stopCalls={l.StopCalls} stopActions={l.StopActions} attempts={l.Attempts} idle={l.IdleAttempts} first={l.FirstStopTick} last={l.LastStopTick} lastReopen={l.LastReopenToStopMs} maxReopen={l.MaxReopenToStopMs} maxCpu={l.MaxCpuMsPerSec})");
        checks.Add((e1.Count == 0 && e2.Count == 0 && e3.Count == 0 && e4.Count == 0)
            ? "hc-loop-budget-self-test: within-budget sequence raises no exceeded event"
            : $"hc-loop-budget-self-test: within-budget sequence wrongly raised {string.Join(',', e1.Concat(e2).Concat(e3).Concat(e4))}");

        // ② 边界：stop actions 恰好等于预算 ⇒ 不超；再 +1 ⇒ 超（且只报一次）
        var b = new HcLoopGenerationLedger { Generation = 8 };
        var bx = b.Observe(true, HcLoopStopActionsPerGenerationBudget, 100, -1, null, false);
        checks.Add((bx.Count == 0 && !b.ActionsExceeded) ? "hc-loop-budget-self-test: stop-actions == budget is not exceeded" : "hc-loop-budget-self-test: stop-actions == budget wrongly exceeded");
        var by = b.Observe(true, 1, 200, 100, null, false);
        var bz = b.Observe(true, 1, 300, 100, null, false);
        checks.Add((by.Count == 1 && by[0] == "stop-actions-per-generation" && bz.Count == 0)
            ? "hc-loop-budget-self-test: stop-actions over budget raised exactly once"
            : $"hc-loop-budget-self-test: stop-actions over budget raised {by.Count} then {bz.Count}");

        // ③ 边界：reopen→stop 恰好等于预算 ⇒ 不超；超 ⇒ 超
        var c = new HcLoopGenerationLedger { Generation = 9 };
        var cx = c.Observe(true, 1, 100, HcLoopReopenToStopMsBudget, null, false);
        var cy = c.Observe(true, 1, 200, HcLoopReopenToStopMsBudget + 1, null, false);
        checks.Add((cx.Count == 0 && cy.Count == 1 && cy[0] == "reopen-to-stop-ms")
            ? "hc-loop-budget-self-test: reopen-to-stop boundary (== budget ok, > budget exceeded) OK"
            : $"hc-loop-budget-self-test: reopen-to-stop boundary WRONG ({string.Join(',', cx.Concat(cy))})");

        // ④ 边界：CPU 恰好等于上限 ⇒ 不超；超 ⇒ 超
        var d = new HcLoopGenerationLedger { Generation = 10 };
        var dx = d.Observe(true, 1, 100, -1, HcLoopCpuMsPerSecCeiling, false);
        var dy = d.Observe(true, 1, 200, -1, HcLoopCpuMsPerSecCeiling + 0.5, false);
        checks.Add((dx.Count == 0 && dy.Count == 1 && dy[0] == "cpu-ms-per-sec")
            ? "hc-loop-budget-self-test: cpu ceiling boundary (== ceiling ok, > ceiling exceeded) OK"
            : $"hc-loop-budget-self-test: cpu ceiling boundary WRONG ({string.Join(',', dx.Concat(dy))})");

        return checks;
    }

    /**
     * 仅沙箱负例（FAN-204 §31 R4 阶段 2；**默认 false，用户路径永不设置**）：
     * 让 settle 探针恒报"已 settle"，构造"在管线在途期间也发停止请求"的变异构型；
     * 与 `--mock-loopstop-skip-settle` 对应，须使 RunHcLoopTargetASelfTest **抛异常**（N1 证据）。
     */
    internal static bool MockLoopStopSkipSettleForTest { get; set; }
    /** 仅沙箱负例：让复核探针恒报"已结束"，构造"把未结束的循环报成 verified"的变异构型。 */
    internal static bool MockLoopStopClaimVerifiedForTest { get; set; }

    /**
     * P-3 目标 A（FAN-204 §31 R4 阶段 2，2026-09-24）：读循环停止的三段判定探针接口。
     * 生产实现 = LifecycleLoopStopProbe（反射到候选 HC 公开契约，树 B == 线上 DLL）；
     * 自测实现 = ScriptedLoopStopProbe（脚本化行为）——两者走**同一** EvaluateLoopStop。
     */
    internal interface ILoopStopProbe
    {
        /** ① 打开管线是否已 settle（false = 在途，本轮不得发停止请求）。 */
        bool TryObserveSettled(out string detail);
        /** ② 请求停止读取循环（HC 语义：只登记停止请求，不等待、不宣称已停止）。 */
        bool TryRequestStop(string source);
        /** ③ 非阻塞复核"是否真的已结束"（false = 仍有未决读取）。 */
        bool TryVerifyEnded(out string detail);
    }

    /**
     * P-3 目标 A 的**唯一判定实现**（真机路径与自测共用，杜绝"两套编排"漂移）：
     * ① 先复核历史未决停止请求（非阻塞）→ ② 无循环 ⇒ 仅复核即返回；
     * ③ 管线在途 ⇒ 只登记 defer、**不发停止请求** → ④ settle 后请求停止（登记 pending）
     * → ⑤ 立即一次非阻塞复核（成功即结算 stop→verify）。
     * 返回"本轮是否完成了一次复核"（只影响记账与事件门，不改变对外返回语义）。
     */
    private static bool EvaluateLoopStop(
        ILoopStopProbe probe,
        HcLoopGenerationLedger ledger,
        string source,
        long attemptTick,
        string loopState,
        bool loopPresent,
        List<string> stopped,
        List<string> failures,
        out bool observedExistingPending)
    {
        var verifiedThisTick = false;
        observedExistingPending = false;
        // 仅沙箱负例（默认 false）：复核恒报"已结束"，用于构造 N1 变异构型。
        bool Verify(out string detail)
        {
            if (MockLoopStopClaimVerifiedForTest)
            {
                detail = "verify:mock-claim-verified";
                return true;
            }
            return probe.TryVerifyEnded(out detail);
        }
        if (ledger.PendingStopRequestTick != 0)
        {
            if (Verify(out var verifyDetail))
            {
                ledger.StopVerified++;
                ledger.LastStopToVerifyMs = (int)(attemptTick - ledger.PendingStopRequestTick);
                ledger.PendingStopRequestTick = 0;
                ledger.LastVerifyDetail = verifyDetail;
                verifiedThisTick = true;
            }
            else
            {
                // FAN-931 P1.1：同一会话、同一代次已有**未被复核的**停止请求时，只观察/复核其
                // 收敛，**不再重复提交**（旧实现会再次 RequestReadLoopStop 并把被接受的重复请求
                // 计进 StopRequests/totalStopActions，使请求计数被误读成"重开次数"）。
                // 该 tick 不是空转（确实做了一次复核），也不推进 reopen→stop 周期。
                ledger.VerifyPending++;
                ledger.StopAlreadyPending++;
                Interlocked.Increment(ref FanPerfCounters.LoopStopAlreadyPending);
                ledger.LastVerifyDetail = verifyDetail;
                observedExistingPending = true;
                return false;
            }
        }
        // 本轮已复核到"循环结束"（调用方读到的 Running 已是过时状态）或本来就没有循环 ⇒ 不再发停止请求。
        if (verifiedThisTick || !loopPresent) return verifiedThisTick;
        // 仅沙箱负例（默认 false）：settle 恒判为"已 settle"，用于构造 N1 变异构型。
        bool settled;
        string settleDetail;
        if (MockLoopStopSkipSettleForTest)
        {
            settled = true;
            settleDetail = "settle:mock-skip-inflight";
        }
        else
        {
            settled = probe.TryObserveSettled(out settleDetail);
        }
        if (!settled)
        {
            ledger.SettleDeferred++;
            ledger.LastSettleDetail = settleDetail;
            failures.Add($"device-read-loop:deferred-not-settled {settleDetail} state={loopState}");
            return verifiedThisTick;
        }
        ledger.LastSettleDetail = settleDetail;
        if (!probe.TryRequestStop(source))
        {
            failures.Add($"device-read-loop:lifecycle-api-rejected state={loopState}");
            return verifiedThisTick;
        }
        ledger.StopRequests++;
        Interlocked.Increment(ref FanPerfCounters.LoopStopRequests);
        ledger.PendingStopRequestTick = attemptTick;
        stopped.Add($"device-read-loop:lifecycle-api state={loopState} settle={settleDetail}");
        if (Verify(out var immediateDetail))
        {
            ledger.StopVerified++;
            ledger.LastStopToVerifyMs = 0;
            ledger.PendingStopRequestTick = 0;
            ledger.LastVerifyDetail = immediateDetail;
            verifiedThisTick = true;
        }
        else
        {
            ledger.LastVerifyDetail = immediateDetail;
        }
        return verifiedThisTick;
    }

    /** ILoopStopProbe 的生产实现：反射到候选 HC 设备（树 B == 线上 DLL 的公开契约）。 */
    private sealed class LifecycleLoopStopProbe : ILoopStopProbe
    {
        private readonly object device;
        internal LifecycleLoopStopProbe(object device) => this.device = device;
        public bool TryObserveSettled(out string detail) => TryObserveOpenPipelineSettled(device, out detail);
        public bool TryRequestStop(string source) =>
            device.GetType()
                .GetMethod("RequestReadLoopStop", BindingFlags.Public | BindingFlags.Instance)
                ?.Invoke(device, new object?[] { source }) is true;
        public bool TryVerifyEnded(out string detail) => TryInvokeWaitReadLoopEnded(device, out detail);
    }

    /**
     * settle 探针（**0ms 非阻塞**）：`LastCompatEntryOperationId` 给出的最近一次兼容入口操作若
     * **未终态**（`TryWaitDeviceOpenReceipt` 0ms 有界等待拿不到结果）⇒ 打开管线仍在途 ⇒ false。
     * 无操作 id / 收据已终态 / 探针不可用或异常 ⇒ true（退回既有"直接停"行为；原因如实记入 detail）。
     */
    internal static bool TryObserveOpenPipelineSettled(object device, out string detail)
    {
        detail = "settle:no-compat-entry-operation";
        try
        {
            if (GetMember(device, "LastCompatEntryOperationId") is not string operationId || operationId.Length == 0)
                return true;
            var method = device.GetType()
                .GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(m => m.Name == "TryWaitDeviceOpenReceipt" && m.GetParameters().Length == 3);
            if (method is null)
            {
                detail = "settle:receipt-api-absent";
                return true;
            }
            var args = new object?[] { operationId, 0, null };
            var terminal = method.Invoke(device, args) is true;
            detail = terminal ? $"settle:receipt-terminal op={operationId}" : $"settle:pipeline-in-flight op={operationId}";
            return terminal;
        }
        catch (Exception ex)
        {
            detail = "settle:probe-fault " + DescribeException(ex);
            return true;
        }
    }

    /**
     * 复核探针（**0ms 非阻塞**）：反射调用候选 HC 的 `TryWaitReadLoopEnded(0, out detail)`；
     * 返回 true 仅代表"此刻已无未完成读取循环"（HC 侧原文：取消请求不等于已停止）。
     * 方法不可用或异常 ⇒ false（**不宣称复核通过**），detail 如实记录。
     */
    internal static bool TryInvokeWaitReadLoopEnded(object device, out string detail)
    {
        detail = "verify:api-absent";
        try
        {
            var method = device.GetType()
                .GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(m => m.Name == "TryWaitReadLoopEnded" && m.GetParameters().Length == 2);
            if (method is null) return false;
            var args = new object?[] { 0, null };
            var ended = method.Invoke(device, args) is true;
            detail = ended ? "verify:read-loop-ended" : "verify:" + (args[1] as string ?? "pending");
            return ended;
        }
        catch (Exception ex)
        {
            detail = "verify:probe-fault " + DescribeException(ex);
            return false;
        }
    }

    /**
     * P-3 目标 A 自测（2026-09-24 阶段 2）：正例三段 + 两条负例，全部走**同一** EvaluateLoopStop。
     * **断言承重**：任一断言失败即抛异常（进程非零退出）；沙箱变异构型
     * （`--mock-loopstop-skip-settle` / `--mock-loopstop-claim-verified`）必须使本自测失败（N1 证据）。
     * 正例：in-flight ⇒ defer（不发请求）→ settle 后 ⇒ 一个停止请求 + pending → 复核 true ⇒ 结算延迟。
     * 负例①：in-flight 期间**不得**发出 RequestReadLoopStop（把 defer 当 stop 的实现会在此失败）。
     * 负例②：永不结束的循环**不得**被报成 verified（把 pending 写成 verified 的实现会在此失败）。
     */
    internal static IReadOnlyList<string> RunHcLoopTargetASelfTest()
    {
        var checks = new List<string>();
        // 失败即抛异常（与 P-4C 同口径：断言必须**承重**；checks 字符串只记录通过态）。
        void Assert(bool ok, string message)
        {
            if (!ok) throw new InvalidOperationException("p3-targetA-selftest FAILED: " + message);
        }

        // ---- 正例三段（同一账本连续推进）----
        var ledger = new HcLoopGenerationLedger { Generation = 41 };
        var stopped = new List<string>();
        var failures = new List<string>();
        var probe = new ScriptedLoopStopProbe { Settled = false, StopAccepts = true, VerifyEnds = false };
        var v1 = EvaluateLoopStop(probe, ledger, "selftest", 1000, "Running", true, stopped, failures, out _);
        Assert(!v1 && ledger.SettleDeferred == 1 && ledger.StopRequests == 0 && stopped.Count == 0 &&
               failures.Count == 1 && ledger.PendingStopRequestTick == 0 && probe.StopCalls == 0,
            $"in-flight pipeline must defer without a stop request (settleDeferred={ledger.SettleDeferred} stopRequests={ledger.StopRequests} stopped={stopped.Count} failures={failures.Count} stopCalls={probe.StopCalls})");
        checks.Add("p3-targetA-selftest: in-flight pipeline defers stop and issues no request OK");
        probe.Settled = true;
        var v2 = EvaluateLoopStop(probe, ledger, "selftest", 2000, "Running", true, stopped, failures, out _);
        Assert(!v2 && ledger.StopRequests == 1 && ledger.PendingStopRequestTick == 2000 && ledger.StopVerified == 0 &&
               stopped.Count == 1 && probe.StopCalls == 1,
            $"settled pipeline must issue exactly one stop request and keep verification pending (stopRequests={ledger.StopRequests} pendingTick={ledger.PendingStopRequestTick} verified={ledger.StopVerified} stopped={stopped.Count} stopCalls={probe.StopCalls})");
        checks.Add("p3-targetA-selftest: settled pipeline issues one stop request, verification stays pending OK");
        probe.VerifyEnds = true;
        var v3 = EvaluateLoopStop(probe, ledger, "selftest", 2500, "Running", true, stopped, failures, out _);
        Assert(v3 && ledger.StopVerified == 1 && ledger.PendingStopRequestTick == 0 && ledger.LastStopToVerifyMs == 500 &&
               ledger.StopRequests == 1 && stopped.Count == 1,
            $"verification must close the pending cycle without a duplicate stop request (verified={ledger.StopVerified} pendingTick={ledger.PendingStopRequestTick} lastStopToVerifyMs={ledger.LastStopToVerifyMs} stopRequests={ledger.StopRequests})");
        checks.Add("p3-targetA-selftest: read-loop-ended verification closes the cycle with stop→verify latency OK");

        // ---- 负例①：把 in-flight 当可停（实现若在在途期发停止请求，本断言必须失败）----
        var ledgerNeg1 = new HcLoopGenerationLedger { Generation = 42 };
        var probeNeg1 = new ScriptedLoopStopProbe { Settled = false, StopAccepts = true, VerifyEnds = true };
        var stoppedNeg1 = new List<string>();
        var failuresNeg1 = new List<string>();
        _ = EvaluateLoopStop(probeNeg1, ledgerNeg1, "selftest", 100, "Running", true, stoppedNeg1, failuresNeg1, out _);
        Assert(probeNeg1.StopCalls == 0 && ledgerNeg1.StopRequests == 0 && stoppedNeg1.Count == 0,
            $"negative control: stop was issued during in-flight pipeline (stopCalls={probeNeg1.StopCalls} stopRequests={ledgerNeg1.StopRequests})");
        checks.Add("p3-targetA-selftest-negative: in-flight pipeline must not issue RequestReadLoopStop OK");

        // ---- 负例②（FAN-931 P1.1 改写）：已有**未被复核的**停止请求 ⇒ 不得重复提交。
        //      旧实现会把被接受的重复请求再计一次 StopRequests（现场日志因此把请求数误读成"重开次数"）；
        //      把 pending 当"可再停"的实现会在 stopCalls/stopRequests 上失败，本断言即去重门。
        var ledgerNeg2 = new HcLoopGenerationLedger { Generation = 43, PendingStopRequestTick = 500 };
        var probeNeg2 = new ScriptedLoopStopProbe { Settled = true, StopAccepts = true, VerifyEnds = false };
        var stoppedNeg2 = new List<string>();
        var failuresNeg2 = new List<string>();
        var v4 = EvaluateLoopStop(probeNeg2, ledgerNeg2, "selftest", 900, "Running", true, stoppedNeg2, failuresNeg2, out var pendingObservedNeg2);
        Assert(!v4 && pendingObservedNeg2 && probeNeg2.StopCalls == 0 && ledgerNeg2.StopRequests == 0 &&
               ledgerNeg2.StopAlreadyPending == 1 && ledgerNeg2.StopVerified == 0 && ledgerNeg2.VerifyPending == 1 &&
               ledgerNeg2.PendingStopRequestTick == 500 && stoppedNeg2.Count == 0 && failuresNeg2.Count == 0,
            $"negative control: an already-pending stop request was re-submitted or mis-accounted (stopCalls={probeNeg2.StopCalls} stopRequests={ledgerNeg2.StopRequests} alreadyPending={ledgerNeg2.StopAlreadyPending} verifyPending={ledgerNeg2.VerifyPending} pendingTick={ledgerNeg2.PendingStopRequestTick})");
        checks.Add("p3-targetA-selftest-negative: an already-pending stop request must be observed, never re-submitted OK");

        // ---- 正例②：未决请求最终被复核到"已结束" ⇒ 仍正确收敛（去重不得丢掉结算）----
        probeNeg2.VerifyEnds = true;
        var v5 = EvaluateLoopStop(probeNeg2, ledgerNeg2, "selftest", 1300, "Running", true, stoppedNeg2, failuresNeg2, out var pendingObservedLate);
        Assert(v5 && !pendingObservedLate && ledgerNeg2.StopVerified == 1 && ledgerNeg2.PendingStopRequestTick == 0 &&
               ledgerNeg2.LastStopToVerifyMs == 800 && probeNeg2.StopCalls == 0 && stoppedNeg2.Count == 0,
            $"late verification must still settle the deduped pending cycle (verified={ledgerNeg2.StopVerified} pendingTick={ledgerNeg2.PendingStopRequestTick} lastStopToVerifyMs={ledgerNeg2.LastStopToVerifyMs} stopCalls={probeNeg2.StopCalls})");
        checks.Add("p3-targetA-selftest: late read-loop-ended verification still settles the deduped pending OK");

        // ---- 正例③：新代次（新账本）仍应及时受控——去重不得演变成"漏停"----
        var ledgerNext = new HcLoopGenerationLedger { Generation = 44 };
        var probeNext = new ScriptedLoopStopProbe { Settled = true, StopAccepts = true, VerifyEnds = false };
        var stoppedNext = new List<string>();
        var failuresNext = new List<string>();
        var v6 = EvaluateLoopStop(probeNext, ledgerNext, "selftest", 2000, "Running", true, stoppedNext, failuresNext, out var pendingObservedNext);
        Assert(!v6 && !pendingObservedNext && probeNext.StopCalls == 1 && ledgerNext.StopRequests == 1 &&
               ledgerNext.StopAlreadyPending == 0 && ledgerNext.PendingStopRequestTick == 2000 && stoppedNext.Count == 1,
            $"a new generation must still issue exactly one stop request (stopCalls={probeNext.StopCalls} stopRequests={ledgerNext.StopRequests} alreadyPending={ledgerNext.StopAlreadyPending} pendingTick={ledgerNext.PendingStopRequestTick} stopped={stoppedNext.Count})");
        checks.Add("p3-targetA-selftest: a new generation still issues exactly one stop request OK");

        return checks;
    }

    /** 自测用脚本化探针（与生产探针同接口；不碰 HC、不碰设备）。 */
    private sealed class ScriptedLoopStopProbe : ILoopStopProbe
    {
        internal bool Settled = true;
        internal bool StopAccepts = true;
        internal bool VerifyEnds = false;
        internal int StopCalls;
        public bool TryObserveSettled(out string detail)
        {
            detail = Settled ? "settle:receipt-terminal op=scripted" : "settle:pipeline-in-flight op=scripted";
            return Settled;
        }
        public bool TryRequestStop(string source)
        {
            StopCalls++;
            return StopAccepts;
        }
        public bool TryVerifyEnded(out string detail)
        {
            detail = VerifyEnds ? "verify:read-loop-ended" : "verify:read-loop-pending-after-0ms [scripted]";
            return VerifyEnds;
        }
    }

    /**
     * R4 黑盒修复自测（2026-09-24）：E-1（就绪等待读数，**归入高频日志、不算事件**）+ E-3（收据 win32 摘要）。
     * **断言失败即抛异常（承重）**。覆盖：
     *   ① 超时形态：读数正确（polls/budgetMs/elapsedMs/ready=false/timedOut=true）+ `hcCoreWarning` 可见；
     *   ② **不算事件**：记录读数**不得**产生任何日志事件行（既不新增事件、也不受事件清单约束）；
     *   ③ 健康形态：立即就绪（polls=0、ready=true）⇒ timedOut=false；
     *   ④ E-3 形状：失败态带 `/win32=N`，成功态（win32=null）**不带**；`{fan}:{status}` 前缀原样保留。
     *   ⑤/⑥/⑦ **G-1 消费侧取证（2026-09-27）**：候选入口在场时按**轮**带出（最近 N 条 + 绑定在场 +
     *           清理台账/周期）；旧 runtime 无入口 ⇒ `absent`；探针异常 ⇒ `fault`（**不逃逸**）；
     *           构建快照**不得**产生任何日志事件行（字段由既有事件携带）。
     */
    internal static IReadOnlyList<string> RunBlackBoxObservabilitySelfTest()
    {
        var checks = new List<string>();
        void Assert(bool ok, string message)
        {
            if (!ok) throw new InvalidOperationException("blackbox-observability-selftest FAILED: " + message);
        }

        // ---- ①/②/③ 就绪等待读数（手动接线，验证"记录读数 → 不写事件"）----
        var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        var log = new HostDiagnosticLog();
        backend.Diagnostic = (eventName, details) => log.Write(eventName, details);
        HostDiagnosticLog.SelfTestCaptureEnabled = true;
        try
        {
            HostDiagnosticLog.ResetSelfTestCapture();
            // 超时形态（模拟真机：40 次探测、跑满 10 s 预算）
            backend.SetHcCoreWarningForSelfTest("HC IsReady timed out; continuing with HC Open() as upstream does");
            backend.RecordReadyWaitEvidence(polls: 40, budgetMs: 10_000, elapsedMs: 10_263, ready: false);
            var evidence = JsonSerializer.SerializeToElement(
                backend.HcReadyWaitEvidenceForSelfTest, JsonDefaults.Options);
            Assert(evidence.GetProperty("polls").GetInt32() == 40 &&
                   evidence.GetProperty("budgetMs").GetInt32() == 10_000 &&
                   evidence.GetProperty("elapsedMs").GetInt32() == 10_263 &&
                   evidence.GetProperty("ready").GetBoolean() == false &&
                   evidence.GetProperty("timedOut").GetBoolean() == true,
                $"ready-wait evidence wrong: {evidence.GetRawText()}");
            Assert(evidence.GetProperty("hcCoreWarning").GetString()?.Contains("IsReady timed out") == true,
                "ready-wait evidence must expose hcCoreWarning (P-06)");
            checks.Add("blackbox-selftest: ready-wait timeout evidence carries polls/budgetMs/timedOut/hcCoreWarning OK");

            // ② **不算事件**：读数记录不得产生任何日志事件行（本批 operator 口径）
            var captured = HostDiagnosticLog.SelfTestCaptured;
            Assert(captured.Count == 0,
                $"recording ready-wait evidence must NOT emit a log event (got {captured.Count}: " +
                string.Join(",", captured.Select(e => e.Event)) + ")");
            checks.Add("blackbox-selftest: ready-wait evidence is NOT emitted as a log event OK");

            // ③ 健康形态
            backend.RecordReadyWaitEvidence(polls: 0, budgetMs: 10_000, elapsedMs: 3, ready: true);
            var healthy = JsonSerializer.SerializeToElement(
                backend.HcReadyWaitEvidenceForSelfTest, JsonDefaults.Options);
            Assert(healthy.GetProperty("polls").GetInt32() == 0 &&
                   healthy.GetProperty("ready").GetBoolean() == true &&
                   healthy.GetProperty("timedOut").GetBoolean() == false,
                $"healthy ready-wait evidence wrong: {healthy.GetRawText()}");
            checks.Add("blackbox-selftest: immediate-ready evidence reports timedOut=false OK");
        }
        finally
        {
            HostDiagnosticLog.SelfTestCaptureEnabled = false;
        }

        // ---- ③/④ E-3 收据摘要形状与向后兼容 ----
        var failed = RealHcBackend.FormatFanReceiptObserved("Mid", "InitiatedFailed", 5);
        var complete = RealHcBackend.FormatFanReceiptObserved("CPU", "TransportedComplete", null);
        Assert(failed == "Mid:InitiatedFailed/win32=5",
            $"failed receipt must carry win32 (got '{failed}')");
        Assert(complete == "CPU:TransportedComplete",
            $"successful receipt must NOT carry win32 (got '{complete}')");
        Assert(failed.Contains("Mid:InitiatedFailed", StringComparison.Ordinal) &&
               complete.Contains("CPU:TransportedComplete", StringComparison.Ordinal),
            "receipt prefix must stay byte-identical for Section19 substring assertions");
        checks.Add("blackbox-selftest: receipt summary carries win32 on failure and preserves prefix OK");

        // ---- ⑤/⑥/⑦ G-1 消费侧取证（2026-09-27）：在场形状 / 旧 runtime 缺失 / 探针异常 / 零事件契约 ----
        var g1Probe = new G1ReceiptsProbe();
        for (var i = 0; i < 5; i++) g1Probe.Receipts.Add(new G1LifecycleReceiptProbe { OperationId = $"op{i}" });
        var g1 = JsonSerializer.SerializeToElement(
            RealHcBackend.DescribeHcReceiptsEvidence(g1Probe), JsonDefaults.Options);
        Assert(g1.GetProperty("api").GetString() == "present" &&
               g1.GetProperty("bindingPresent").GetBoolean() &&
               g1.GetProperty("receiptCount").GetInt32() == 5 &&
               g1.GetProperty("recentLimit").GetInt32() == RealHcBackend.RecentHcReceiptLimit &&
               g1.GetProperty("receipts").GetArrayLength() == RealHcBackend.RecentHcReceiptLimit &&
               g1.GetProperty("receipts")[0].GetString()!.Contains("op2", StringComparison.Ordinal) &&
               g1.GetProperty("receipts")[2].GetString()!.Contains("op4", StringComparison.Ordinal) &&
               g1.GetProperty("cleanupLedger").GetString() == "no-cycle" &&
               g1.GetProperty("cleanupCycle").GetString()!.Contains("completed=True", StringComparison.Ordinal),
            $"G-1 present shape wrong: {g1.GetRawText()}");
        checks.Add("g1-consumption-selftest: per-round receipts (last N) + binding + cleanup ledger/cycle surface OK");

        var g1Legacy = JsonSerializer.SerializeToElement(
            RealHcBackend.DescribeHcReceiptsEvidence(new G1LegacyProbe()), JsonDefaults.Options);
        Assert(g1Legacy.GetProperty("api").GetString() == "absent" &&
               g1Legacy.GetProperty("receipts").GetArrayLength() == 0,
            $"G-1 legacy runtime (no entries) must report api=absent without throwing: {g1Legacy.GetRawText()}");
        checks.Add("g1-consumption-selftest: legacy runtime without the entries reports api=absent OK");

        var g1Faulty = new G1ReceiptsProbe { ThrowOnPeek = true };
        g1Faulty.Receipts.Add(new G1LifecycleReceiptProbe { OperationId = "op-fault" });
        var g1Fault = JsonSerializer.SerializeToElement(
            RealHcBackend.DescribeHcReceiptsEvidence(g1Faulty), JsonDefaults.Options);
        Assert(g1Fault.GetProperty("api").GetString() == "fault" &&
               g1Fault.GetProperty("error").GetString()!.Length > 0,
            $"G-1 probe fault must be recorded as advisory instead of escaping: {g1Fault.GetRawText()}");
        Assert(JsonSerializer.SerializeToElement(
                   RealHcBackend.DescribeHcReceiptsEvidence(null), JsonDefaults.Options)
               .GetProperty("api").GetString() == "no-device",
            "G-1 no-device shape wrong");
        checks.Add("g1-consumption-selftest: probe fault/absent device is advisory (never escapes into control paths) OK");

        HostDiagnosticLog.SelfTestCaptureEnabled = true;
        try
        {
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = RealHcBackend.DescribeHcReceiptsEvidence(g1Probe);
            var capturedG1 = HostDiagnosticLog.SelfTestCaptured;
            Assert(capturedG1.Count == 0,
                $"G-1 snapshot must NOT emit a log event (got {capturedG1.Count}: " +
                string.Join(",", capturedG1.Select(e => e.Event)) + ")");
            checks.Add("g1-consumption-selftest: snapshot emits no log event (fields are carried by existing events) OK");
        }
        finally
        {
            HostDiagnosticLog.SelfTestCaptureEnabled = false;
        }

        return checks;
    }

    /** G-1 自测替身：模拟候选 HC 已有多轮的逐轮收据（每条自带 `Describe()`）。 */
    private sealed class G1LifecycleReceiptProbe
    {
        public string OperationId { get; init; } = "op";
        public string Describe() =>
            $"op={OperationId} gen=41 outcome=RejectedCleanupPending effects=None phase=open-hid-cleanup-pending";
    }

    /** G-1 自测替身：模拟候选 HC 的 5 个结构化取证入口（可切换"探针抛异常"）。 */
    private sealed class G1ReceiptsProbe
    {
        internal List<object> Receipts { get; } = new();
        internal bool ThrowOnPeek { get; init; }
        public IReadOnlyList<object> PeekReceipts() =>
            ThrowOnPeek ? throw new InvalidOperationException("scripted peek failure") : Receipts;
        public bool IsInputBindingPresent() => true;
        public string DescribeCleanupLedger() => "no-cycle";
        public string DescribeCleanupCycle() =>
            "owner=- deferred=False completed=True cycle=[<none>] lastReport=[<none>]";
    }

    /** G-1 自测替身：旧 runtime（**无**任何结构化取证入口）。 */
    private sealed class G1LegacyProbe
    {
        public bool IsOpen => true;
    }

    /** P-3：最近一次"真的停到"的调用来源（诊断）。 */
    private string hcLoopStopLastStopAckSource = "none";

    /** P-3（自测/取证）：当前记账快照（不再触发任何 HC 调用）。 */
    internal object HcLoopStopEvidenceForSelfTest => new
    {
        attempts = Volatile.Read(ref hcLoopStopAttempts),
        idleAttempts = Volatile.Read(ref hcLoopStopIdleAttempts),
        actions = hcControllerCpuLoopStopActions,
        sessionId = hcLoopStopSessionId,
        sessionAttempts = hcLoopStopSessionAttempts,
        sessionStops = hcLoopStopSessionStops,
        lastStopTick = hcLoopStopLastStopTick,
    };

    private static Dictionary<string, string> ReadIdentity(object target)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var name in new[] { "ManufacturerName", "SystemModel", "ProductName", "SystemName", "Version" })
        {
            var value = target.GetType().GetField(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)?.GetValue(target)
                ?? target.GetType().GetProperty(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)?.GetValue(target);
            if (value is not null && !string.IsNullOrWhiteSpace(value.ToString())) result[name] = value.ToString()!;
        }
        return result;
    }

    internal static double[] ExpandCurveForSelfTest(IReadOnlyList<FanNode> nodes)
    {
        ValidateCurve(nodes);
        return Enumerable.Range(0, 11).Select(temp => Interpolate(nodes, temp * 10)).ToArray();
    }

    internal static void ValidateCurveForSelfTest(IReadOnlyList<FanNode> nodes) => ValidateCurve(nodes);

    private static void ValidateCurve(IReadOnlyList<FanNode> nodes)
    {
        if (nodes.Count != 4) throw new FanApiException(400, "INVALID_CURVE", "曲线必须包含 4 个节点");
        if (nodes[0].TempC != 0) throw new FanApiException(400, "INVALID_CURVE", "节点 1 温度必须固定为 0°C");
        for (var i = 0; i < nodes.Count; i++)
        {
            if (double.IsNaN(nodes[i].TempC) || double.IsInfinity(nodes[i].TempC) || nodes[i].TempC is < 0 or > 100)
                throw new FanApiException(400, "INVALID_CURVE", "温度必须在 0-100°C");
            if (double.IsNaN(nodes[i].DutyPercent) || double.IsInfinity(nodes[i].DutyPercent) || nodes[i].DutyPercent is < 0 or > 100)
                throw new FanApiException(400, "INVALID_CURVE", "转速必须在 0-100%");
            if (i > 0 && nodes[i].TempC < nodes[i - 1].TempC) throw new FanApiException(400, "INVALID_CURVE", "温度节点必须递增");
            if (i > 0 && nodes[i].DutyPercent < nodes[i - 1].DutyPercent) throw new FanApiException(400, "INVALID_CURVE", "转速节点必须递增");
        }
        if (nodes[3].DutyPercent < 50) throw new FanApiException(400, "INVALID_CURVE", "节点 4 最低 50%");
    }

    private static double Interpolate(IReadOnlyList<FanNode> nodes, double temperature)
    {
        if (temperature <= nodes[0].TempC) return nodes[0].DutyPercent;
        for (var i = 1; i < nodes.Count; i++)
        {
            if (temperature <= nodes[i].TempC)
            {
                var span = nodes[i].TempC - nodes[i - 1].TempC;
                if (span <= 0) return nodes[i].DutyPercent;
                var ratio = (temperature - nodes[i - 1].TempC) / span;
                return nodes[i - 1].DutyPercent + (nodes[i].DutyPercent - nodes[i - 1].DutyPercent) * ratio;
            }
        }
        return nodes[^1].DutyPercent;
    }

    private static string Sha256(string path) => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant();

    private sealed class StaWorkItem<T>
    {
        private readonly Func<T> action;

        public StaWorkItem(Func<T> action, string operationName)
        {
            this.action = action;
            OperationName = operationName;
        }

        public string OperationName { get; }
        public ManualResetEventSlim Completed { get; } = new(false);
        public Exception? Failure { get; private set; }
        public T? Result { get; private set; }

        public void Execute()
        {
            try { Result = action(); }
            catch (Exception ex) { Failure = ex; }
            finally { Completed.Set(); }
        }
    }

    private Dispatcher EnsureStaDispatcher()
    {
        var shouldStart = false;
        lock (staGate)
        {
            if (staDispatcherStopping)
                throw new ObjectDisposedException(nameof(RealHcBackend), "HC STA dispatcher 已关闭");
            if (staDispatcher is not null) return staDispatcher;
            if (staThread is null || !staThread.IsAlive)
            {
                staDispatcherReady.Reset();
                staThread = new Thread(StaDispatcherLoop)
                {
                    // A foreground thread is deliberate. If a vendor Close()
                    // is still executing, Windows must not tear down this
                    // process underneath the HC ACPI/HID lifecycle.
                    IsBackground = false,
                    Name = "YeManFanHost.HC.STA",
                };
                staThread.SetApartmentState(ApartmentState.STA);
                shouldStart = true;
            }
        }

        if (shouldStart)
            staThread!.Start();

        if (!staDispatcherReady.Wait(TimeSpan.FromSeconds(5)))
            throw new TimeoutException("HC STA Dispatcher 未在 5 秒内启动");

        lock (staGate)
        {
            if (staDispatcherStopping || staDispatcher is null)
                throw new ObjectDisposedException(nameof(RealHcBackend), "HC STA dispatcher 已关闭");
            return staDispatcher;
        }
    }

    private void StaDispatcherLoop()
    {
        var dispatcher = Dispatcher.CurrentDispatcher;
        lock (staGate)
        {
            if (!staDispatcherStopping)
                staDispatcher = dispatcher;
            staDispatcherReady.Set();
        }
        Dispatcher.Run();
    }

    private void ExecuteStaWorkItem<T>(StaWorkItem<T> workItem)
    {
        Diagnostic?.Invoke("hc-operation.begin", new { operation = workItem.OperationName, phase = CurrentHcPhase });
        workItem.Execute();

        var timedOutCallReturned = false;
        lock (staGate)
        {
            if (ReferenceEquals(activeStaWorkItem, workItem))
            {
                activeStaWorkItem = null;
                // A timed-out HC call remains unsafe until this exact
                // lifecycle STA has naturally returned. Only then may the
                // engine make one serialized recovery attempt.
                timedOutCallReturned = operationTimedOut;
                operationTimedOut = false;
            }
        }
        Diagnostic?.Invoke("hc-operation.return", new
        {
            operation = workItem.OperationName,
            phase = CurrentHcPhase,
            timedOut = timedOutCallReturned,
            error = workItem.Failure is null ? null : DescribeException(workItem.Failure),
        });
        if (timedOutCallReturned)
            _ = Task.Run(() => TimedOutOperationReturned?.Invoke(workItem.Failure is null));
    }

    private T OnStaBounded<T>(Func<T> action, string operationName = "hc-operation")
    {
        Thread? lifecycleThread;
        lock (staGate) lifecycleThread = staThread;
        if (lifecycleThread is not null && Thread.CurrentThread == lifecycleThread) return action();

        var workItem = new StaWorkItem<T>(action, operationName);
        var dispatcher = EnsureStaDispatcher();
        lock (staGate)
        {
            if (operationTimedOut || activeStaWorkItem is not null)
                throw new FanApiException(504, "HC_OPERATION_TIMEOUT", "上一次 HC 操作仍未返回，已拒绝并发调用");
            activeStaWorkItem = workItem;
            try
            {
                _ = dispatcher.BeginInvoke(
                    DispatcherPriority.Send,
                    new Action(() => ExecuteStaWorkItem(workItem)));
            }
            catch (Exception ex) when (ex is InvalidOperationException or TaskCanceledException)
            {
                activeStaWorkItem = null;
                throw new ObjectDisposedException(nameof(RealHcBackend), "HC STA dispatcher 已关闭");
            }
        }

        if (!workItem.Completed.Wait(TimeSpan.FromSeconds(15)))
        {
            var timedOut = false;
            lock (staGate)
            {
                if (!workItem.Completed.IsSet && ReferenceEquals(activeStaWorkItem, workItem))
                {
                    operationTimedOut = true;
                    timedOut = true;
                }
            }
            if (timedOut)
            {
                // Immediately stop temperature-driven writes. The pending HC
                // call is allowed to unwind naturally; no second Host call may
                // overlap it until this dispatcher reports completion.
                Volatile.Write(ref suspendWriteBlocked, 1);
                Interlocked.Increment(ref suspendGateEpoch);
                Diagnostic?.Invoke("hc-operation.timeout", new { operation = operationName, phase = CurrentHcPhase, timeoutSeconds = 15 });
                throw new FanApiException(504, "HC_OPERATION_TIMEOUT", "HC 操作超过 15 秒未返回，已进入故障锁定");
            }
            workItem.Completed.Wait();
        }

        if (workItem.Failure is not null) throw workItem.Failure;
        return workItem.Result!;
    }

    private T OnSta<T>(Func<T> action) => OnStaBounded(action);

    private void OnStaBounded(Action action, string operationName = "hc-operation") =>
        OnStaBounded(() => { action(); return true; }, operationName);

    private static IEnumerable<Exception> Unwrap(Exception ex)
    {
        for (Exception? current = ex; current is not null; current = current.InnerException)
            yield return current;
    }

    private void OnSta(Action action) => OnStaBounded(action);

    internal static IReadOnlyList<string> RunStaDispatcherSelfTest()
    {
        var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        try
        {
            var firstThread = backend.OnStaBounded(() => Environment.CurrentManagedThreadId, "selftest-sta-first");
            var secondThread = backend.OnStaBounded(() => Environment.CurrentManagedThreadId, "selftest-sta-second");
            var apartment = backend.OnStaBounded(() => Thread.CurrentThread.GetApartmentState(), "selftest-sta-apartment");
            var hasDispatcher = backend.OnStaBounded(() => Dispatcher.CurrentDispatcher.CheckAccess(), "selftest-sta-message-pump");
            if (firstThread != secondThread || apartment != ApartmentState.STA || !hasDispatcher)
                throw new InvalidOperationException("HC STA dispatcher did not preserve a single message-pumped STA lifecycle thread");
            // FAN-931 P2A 判定依据：**实测**生产过程里 OnStaBounded 的一次往返成本（不是假设微秒）。
            // 只在自测里跑（有界 20 次，先预热 3 次），生产零成本；数值随行报告，供
            // "心跳去掉 STA 校验是否值得"的裁决直接引用。
            for (var warm = 0; warm < 3; warm++) backend.OnStaBounded(() => 0, "selftest-sta-warmup");
            const int roundTrips = 20;
            var started = Stopwatch.GetTimestamp();
            for (var i = 0; i < roundTrips; i++) backend.OnStaBounded(() => i, "selftest-sta-cost");
            var meanUs = Stopwatch.GetElapsedTime(started).TotalMicroseconds / roundTrips;
            return new[]
            {
                "hc-single-message-pumped-sta-lifecycle-dispatcher",
                $"fan931-p2a-sta-roundtrip-cost meanUs={meanUs.ToString("F1", System.Globalization.CultureInfo.InvariantCulture)} samples={roundTrips}",
            };
        }
        finally
        {
            backend.Dispose();
        }
    }

    /**
     * 920-v1.3 §15.1：HC-G9 异步调用边界的确定性判别（无硬件）。
     *
     * 链接的是**真实**逻辑，不是镜像模型：
     *   - 真实 RealHcBackend.OnStaBounded + 真实 STA Dispatcher（含真实
     *     DispatcherSynchronizationContext）；
     *   - 真实 InvokeHcDeviceInserted 反射派发（与生产同一条代码路径）；
     *   - 与 EnsureHcDeviceOpenForRestore 同形的“有界轮询 IsOpen 后抛出”；
     *   - 真实 StopHcControllerCpuLoops 所用的 SetInstanceBoolField 停止机制。
     *
     * 只有**设备**是可控替身：替身不加载 HC、不访问 HID，但
     * async void Device_Inserted / WaitUntilReady 的形态（含 ConfigureAwait(false)
     * 位置与“无 try/catch”）与 ROGAlly.cs / IDevice.cs 逐行同形。
     * 替身的 IsOpen 与生产一样在 **await 之后**才可能置真，因此“等待方占住
     * 派发线程 ⇒ 阻塞自己正在等待的工作”这一命题可被直接检出或推翻。
     */
    internal static IReadOnlyList<string> RunHcAsyncBoundaryProbeSelfTest()
    {
        var checks = new List<string>();
        var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        try
        {
            // §16.1：先静态+替身证明三项条件前提（"Open 成功 ≠ ROG 设备 IsOpen"）
            checks.AddRange(RunHcDeviceOpenConditionSelfTest());

            // 历史形态（§16.2 之前）：派发后由**同一个 STA 工作项**轮询 —— 基准/反例
            foreach (var c in new[]
            {
                new AsyncBoundaryCase("legacy-immediate-ready", 0, 800, false, false, false),
                new AsyncBoundaryCase("legacy-ready-during-poll", 250, 3000, false, false, false),
                new AsyncBoundaryCase("legacy-ready-after-timeout", 1500, 800, false, false, false),
                new AsyncBoundaryCase("legacy-never-ready", int.MaxValue, 700, false, false, false),
            })
                checks.AddRange(RunAsyncBoundaryScenario(backend, c));

            // 修复形态（§16.2）：STA 只派发，等待走**真实共享** WaitForHcDeviceOpenBounded
            foreach (var c in new[]
            {
                new AsyncBoundaryCase("fixed-immediate-ready", 0, 800, false, false, true),
                new AsyncBoundaryCase("fixed-ready-during-poll", 250, 3000, false, false, true),
                new AsyncBoundaryCase("fixed-ready-after-timeout", 1500, 800, false, false, true),
                new AsyncBoundaryCase("fixed-never-ready", int.MaxValue, 700, false, false, true),
                new AsyncBoundaryCase("fixed-close-after-timeout", 900, 500, true, false, true),
                new AsyncBoundaryCase("fixed-new-session-after-timeout", 900, 500, false, true, true),
                new AsyncBoundaryCase("fixed-isready-also-opens-hid", 250, 3000, false, false, true, true),
            })
                checks.AddRange(RunAsyncBoundaryScenario(backend, c));

            // §16.5-2：旧操作是否干扰下一轮（会话代次判据）
            checks.AddRange(RunAsyncBoundaryInterferenceScenario(backend, "orphan-then-new-session", 600, 400, false));
            checks.AddRange(RunAsyncBoundaryInterferenceScenario(backend, "new-session-then-orphan", 1500, 400, true));
            // §17.4-A：异常用例（生产骨架，调用方必须得到失败而不是成功）
            checks.AddRange(RunAsyncBoundaryExceptionScenario(backend));
            return checks;
        }
        finally
        {
            backend.Dispose();
        }
    }

    /**
     * §16.1：三项条件的**前提验证**（静态 + 替身）。
     * 这是对上一轮"Open 成功 ⇒ helper 必早退"误读的正式更正。
     */
    internal static IReadOnlyList<string> RunHcDeviceOpenConditionSelfTest()
    {
        var checks = new List<string>();
        var device = new AsyncBoundaryProbeDevice { ReadyAfterMs = int.MaxValue };
        device.SimulateHcOpen();   // HC Open() 成功：DeviceOpen + ACPI

        if (!device.BaseIsOpen)
            throw new InvalidOperationException("hc-device-open-condition: HC Open() success must set the base IsOpen terms");
        if (device.IsOpen)
            throw new InvalidOperationException("hc-device-open-condition: HC Open() success must NOT make ROGAlly.IsOpen true (input HID still closed)");
        if (HcDeviceIsOpen(device))
            throw new InvalidOperationException("hc-device-open-condition: production predicate must agree that the device is not open yet");

        checks.Add($"hc-device-open-condition[open-succeeded-but-hid-closed] {device.ConditionTrace} productionIsOpen={HcDeviceIsOpen(device)} - the helper's dispatch branch IS reachable");

        // §17.1-6：此前用"永不就绪"的替身，实际从未绑定 HID ⇒ 断言空洞。
        // 改为**确实绑定且未打开**的对照：ReadyAfterMs=0 使 IsReady() 真的执行绑定，
        // 但 IsReadyAlsoOpensHid=false ⇒ 只绑定、不打开。
        var boundOnly = new AsyncBoundaryProbeDevice { ReadyAfterMs = 0, IsReadyAlsoOpensHid = false };
        boundOnly.SimulateHcOpen();
        if (!boundOnly.IsReady())
            throw new InvalidOperationException("hc-device-open-condition: the bound-only control must report ready");
        if (!boundOnly.HidBound)
            throw new InvalidOperationException("hc-device-open-condition: the bound-only control must ACTUALLY bind the input HID (previous version never bound it)");
        if (boundOnly.HidOpen)
            throw new InvalidOperationException("hc-device-open-condition: the bound-only control must NOT open the HID");
        if (boundOnly.IsOpen || HcDeviceIsOpen(boundOnly))
            throw new InvalidOperationException("hc-device-open-condition: bound but unopened HID must not satisfy IsOpen");
        checks.Add($"hc-device-open-condition[bound-but-not-opened] {boundOnly.ConditionTrace} productionIsOpen={HcDeviceIsOpen(boundOnly)} - binding alone is not enough");

        var readyOpens = new AsyncBoundaryProbeDevice { ReadyAfterMs = 0, IsReadyAlsoOpensHid = true };
        readyOpens.SimulateHcOpen();
        readyOpens.IsReady();
        checks.Add($"hc-device-open-condition[isready-also-opens-variant] {readyOpens.ConditionTrace} productionIsOpen={HcDeviceIsOpen(readyOpens)} - recorded as the unresolved device-dependent variant");
        // §17.1-4：本夹具**从未派发**（没有 Device_Inserted 续体、没有循环），
        // 因此没有"真实完成的任务"可等，只置退出标志；真实排空断言在已派发场景里做。
        device.RequestReadyLoopExit();
        readyOpens.RequestReadyLoopExit();
        return checks;
    }

    /** §17.4-C：strict 模式下把"旧工作改变状态"升级为失败断言；默认模式输出 EXPECTATION-UNMET。 */
    internal static bool HcAsyncBoundaryStrict { get; set; }

    private sealed record AsyncBoundaryCase(
        string Label,
        int ReadyAfterMs,
        int CallerDeadlineMs,
        bool CloseAfterTimeout,
        bool NewSessionAfterTimeout,
        bool FixedShape,
        bool IsReadyAlsoOpensHid = false);

    private static IReadOnlyList<string> RunAsyncBoundaryScenario(RealHcBackend backend, AsyncBoundaryCase c)
    {
        var label = c.Label;
        var checks = new List<string>();
        var device = new AsyncBoundaryProbeDevice
        {
            ReadyAfterMs = c.ReadyAfterMs,
            IsReadyAlsoOpensHid = c.IsReadyAlsoOpensHid,
        };
        // 前提：HC Open() 已成功（DeviceOpen + ACPI 打开），但输入 HID 尚未打开。
        device.SimulateHcOpen();

        var staThreadId = 0;
        var staContext = "<none>";
        string? callerFailure = null;
        var pollSawOpen = false;
        var pollEndedAtMs = 0.0;

        var staActionMs = Stopwatch.GetTimestamp();
        try
        {
            if (c.FixedShape)
            {
                // §16.2 修复形态：STA 上只派发，**不等待**。
                var need = backend.OnStaBounded(() =>
                {
                    staThreadId = Environment.CurrentManagedThreadId;
                    staContext = SynchronizationContext.Current?.GetType().FullName ?? "<none>";
                    if (HcDeviceIsOpen(device)) { pollSawOpen = true; return false; }
                    InvokeHcDeviceInserted(device);
                    return true;
                }, $"selftest-async-boundary-begin-{label}");
                if (need)
                {
                    // 等待走**真实共享生产实现**，且位于不会占住 STA 派发器的本线程。
                    pollSawOpen = WaitForHcDeviceOpenBounded(device, c.CallerDeadlineMs, $"probe-{label}");
                    pollEndedAtMs = device.ElapsedMs();
                    if (!pollSawOpen)
                        callerFailure = "HC_ROG_DEVICE_INSERT_TIMEOUT: async-boundary-probe";
                }
            }
            else
            {
                // 历史形态（复现 §16.2 之前的代码）：派发与轮询在**同一个 STA 工作项**内。
                backend.OnStaBounded(() =>
                {
                    staThreadId = Environment.CurrentManagedThreadId;
                    staContext = SynchronizationContext.Current?.GetType().FullName ?? "<none>";
                    InvokeHcDeviceInserted(device);
                    device.MarkDispatchReturned();
                    var deadline = Environment.TickCount64 + c.CallerDeadlineMs;
                    while (Environment.TickCount64 < deadline)
                    {
                        if (HcDeviceIsOpen(device)) { pollSawOpen = true; return true; }
                        Thread.Sleep(100);
                    }
                    pollEndedAtMs = device.ElapsedMs();
                    throw new InvalidOperationException("HC_ROG_DEVICE_INSERT_TIMEOUT: async-boundary-probe");
                }, $"selftest-async-boundary-{label}");
            }
        }
        catch (Exception ex)
        {
            callerFailure = Unwrap(ex).First().Message;
        }
        var callerReturnedAtMs = (Stopwatch.GetTimestamp() - staActionMs) * 1000d / Stopwatch.Frequency;

        if (staContext != "System.Windows.Threading.DispatcherSynchronizationContext")
            throw new InvalidOperationException(
                $"async-boundary premise failed: HC STA thread had no DispatcherSynchronizationContext, got {staContext}");

        // 历史形态的判别：等待方占住派发线程 ⇒ 轮询期内看不到就绪（自阻塞反例）
        if (label == "legacy-ready-during-poll")
        {
            if (pollSawOpen)
                throw new InvalidOperationException("async-boundary: legacy shape unexpectedly saw IsOpen during the poll; the self-block premise is falsified");
            if (!device.WaitedForContinuation(4000))
                throw new InvalidOperationException("async-boundary: legacy shape produced no continuation at all");
            if (device.ContinuationAtMs < pollEndedAtMs)
                throw new InvalidOperationException($"async-boundary: legacy continuation ran at {device.ContinuationAtMs:F0}ms inside the poll window ending at {pollEndedAtMs:F0}ms");
        }

        // 修复形态的鉴别力：就绪发生在等待窗口内的场景必须**成功**，否则修复无效
        if (label == "fixed-ready-during-poll" || label == "fixed-isready-also-opens-hid" || label == "fixed-immediate-ready")
        {
            if (callerFailure is not null)
                throw new InvalidOperationException($"async-boundary: fixed shape must not time out here (failure={callerFailure})");
            if (!pollSawOpen)
                throw new InvalidOperationException("async-boundary: fixed shape did not observe IsOpen");
        }

        // 永久不就绪：两种形态都必须有界失败，且不得留下迟到副作用
        if (label.EndsWith("never-ready", StringComparison.Ordinal) && callerFailure is null)
            throw new InvalidOperationException("async-boundary: never-ready case did not time out as expected");

        var order = "<none>";
        if (c.CloseAfterTimeout || c.NewSessionAfterTimeout)
        {
            try
            {
                backend.OnStaBounded(() =>
                {
                    order = device.ContinuationAtMs >= 0 ? "continuation-first" : "followup-first";
                    if (c.CloseAfterTimeout) device.SimulateClose();
                    if (c.NewSessionAfterTimeout) device.SimulateNewSessionRemapOn(3);
                    return true;
                }, $"selftest-async-boundary-followup-{label}");
            }
            catch (Exception ex)
            {
                order = "followup-failed:" + Unwrap(ex).First().Message;
            }
        }

        device.WaitedForContinuation(2500);

        var flagBeforeStop = device.ReadLoopFlag;
        var stopWorked = device.TryStopReadLoop();
        var flagAfterStop = device.ReadLoopFlag;

        // §16.4/§17.1-4：测试侧排空 —— 请求退出后**等待真实完成的任务**（续体/就绪循环/读取循环），
        // 不再用"睡固定秒数"或"停止标志为 false"充当任务结束的证据。
        var drain = device.DrainAndAwaitCompletion();
        if (drain.Dispatched && !drain.AllStartedTasksCompleted)
            throw new InvalidOperationException(
                $"async-boundary[{label}]: 排空失败，任务未真正结束 continuation={drain.Continuation} " +
                $"readyLoop={drain.ReadyLoop} readLoop={drain.ReadLoop} detail={drain.Detail}");

        checks.Add(
            $"hc-async-boundary[{label}] shape={(c.FixedShape ? "fixed" : "legacy")} staCtx={staContext} staThread={staThreadId} " +
            $"cont={device.ContinuationThreadId}/{device.ContinuationThreadContext} contAtMs={device.ContinuationAtMs:F0} " +
            $"callerReturnedAtMs={callerReturnedAtMs:F0} readyCalls={device.IsReadyCalls} pollSawOpen={pollSawOpen} " +
            $"callerFailure={callerFailure ?? "<none>"} remapOn={device.RemapOnCount} remapOff={device.RemapOffCount} " +
            $"readLoopStarts={device.ReadLoopStarts} order={order} flagBeforeStop={flagBeforeStop} stopWorked={stopWorked} " +
            $"flagAfterStop={flagAfterStop} drain={drain.ReadyLoop}/{drain.Continuation}/{drain.ReadLoop} " +
            $"drainedTasksCompleted={drain.AllStartedTasksCompleted} continuationFault={drain.ContinuationFaultType ?? "<none>"} " +
            $"{device.ConditionTrace}");
        return checks;
    }

    /**
     * §15.1 完成出口的判别：**旧操作会不会干扰后续控制**。
     *
     * 会话代次模型：`SimulateRecoveryClose` 结束旧会话并把代次推进；旧续体带着
     * 它派发时捕获的代次调用 `ConfigureController(true)`。若该调用发生时设备代次
     * 已经推进，它就是一次**属于已死会话的写入**（I-10），并会把 remap 置开。
     * 判据是**最后一个 remap-on 属于谁**：收敛到新会话 ⇒ 无持久干扰；
     * 落在旧代次 ⇒ 旧操作确实改写了新会话的状态。
     */
    private static IReadOnlyList<string> RunAsyncBoundaryInterferenceScenario(
        RealHcBackend backend,
        string label,
        int readyAfterMs,
        int callerDeadlineMs,
        bool newSessionFirst)
    {
        var checks = new List<string>();
        var device = new AsyncBoundaryProbeDevice { ReadyAfterMs = readyAfterMs };
        // 前提：HC Open() 已成功，但输入 HID 未打开（三条件同形）。
        device.SimulateHcOpen();
        string? callerFailure = null;
        try
        {
            // §17.1-3：改用**生产协调骨架**，不再在单个 STA 工作项里轮询旧形态。
            var adapter = new ProbeHcDeviceOpenAdapter(backend, device);
            var operation = new HcDeviceOpenOperation($"interference-{label}", 1);
            var phase = CoordinateHcDeviceOpen(adapter, callerDeadlineMs, operation);
            if (phase == HcDeviceOpenPhase.TimedOut)
                callerFailure = "HC_ROG_DEVICE_INSERT_TIMEOUT: async-boundary-interference";
        }
        catch (Exception ex)
        {
            callerFailure = Unwrap(ex).First().Message;
        }
        // 操作已返回：此后任何打开都是迟到副作用，由 §17.4-C 断言捕获。
        device.OperationReturnedAtMs = (long)device.ElapsedMs();

        // 恢复流程的 Close：结束旧会话（清设备、remap 还原、代次推进）
        backend.OnStaBounded(() => { device.SimulateRecoveryClose(); return true; }, $"selftest-async-boundary-close-{label}");
        if (newSessionFirst)
            backend.OnStaBounded(() => { device.SimulateNewSessionRemapOn(3); return true; }, $"selftest-async-boundary-new-{label}");

        device.WaitedForContinuation(4000);

        if (!newSessionFirst)
            backend.OnStaBounded(() => { device.SimulateNewSessionRemapOn(3); return true; }, $"selftest-async-boundary-new-{label}");
        Thread.Sleep(300);

        var stale = device.StaleRemapOnCount;
        var lastGeneration = device.LastRemapOnGeneration;
        var converges = lastGeneration == 3;
        // §17.4-C：**真正的验收断言** —— 旧工作不得改变关闭后/新会话的状态。
        // 非 strict 模式不放过：输出以 EXPECTATION-UNMET 开头，明确表示"尚未满足"，
        // 不得被读成绿色通过。
        var violations = new List<string>();
        if (newSessionFirst && !converges)
            violations.Add("stale-generation-remap-became-last-writer-of-a-live-session");
        if (device.ObservedOpenAfterOperationReturn)
            violations.Add("device-became-open-after-the-operation-returned");
        if (device.UnownedReadLoopStarted)
            violations.Add("read-loop-started-without-a-session-owning-it");
        var verdict = violations.Count == 0
            ? "OLD-WORK-DID-NOT-CHANGE-STATE"
            : "EXPECTATION-UNMET[" + string.Join("+", violations) + "]";
        if (violations.Count > 0 && HcAsyncBoundaryStrict)
            throw new InvalidOperationException(
                "async-boundary strict: old work changed post-Close/new-session state: " + string.Join("+", violations));

        // §17.1-4：本场景同样以**真实完成的任务**收尾（读取循环停止 + 续体/就绪循环结束）。
        device.TryStopReadLoop();
        var drain = device.DrainAndAwaitCompletion();
        if (!drain.AllStartedTasksCompleted)
            throw new InvalidOperationException(
                $"async-boundary[{label}]: 排空失败，任务未真正结束 continuation={drain.Continuation} " +
                $"readyLoop={drain.ReadyLoop} readLoop={drain.ReadLoop} detail={drain.Detail}");

        // §17.4-A：**当前有效控制意图恢复** —— 旧工作结算后，下一轮合法入口必须可达、且经生产协调
        // 骨架真实完成（§3 闭合定义）。这一条独立于上面的"未被改写"断言：不受干扰 ≠ 入口还能用。
        var nextRound = new AsyncBoundaryProbeDevice { ReadyAfterMs = 0 };
        nextRound.SimulateHcOpen();
        var nextPhase = HcDeviceOpenPhase.NotApplicable;
        string? nextFailure = null;
        try
        {
            nextPhase = CoordinateHcDeviceOpen(
                new ProbeHcDeviceOpenAdapter(backend, nextRound), 3000,
                new HcDeviceOpenOperation($"next-round-after-{label}", 4));
        }
        catch (Exception ex)
        {
            nextFailure = Unwrap(ex).First().Message;
        }
        nextRound.TryStopReadLoop();
        var nextDrain = nextRound.DrainAndAwaitCompletion();
        // 下一轮的写入必须归属**它自己的会话**（无陈旧代次归属）——这才是"有效控制意图"。
        var nextRoundRemapOwnedByItsOwnSession =
            nextRound.RemapOnCount == 1 && nextRound.StaleRemapOnCount == 0 &&
            nextRound.LastRemapOnGeneration == nextRound.DispatchGeneration;
        if (nextPhase != HcDeviceOpenPhase.Completed || nextFailure is not null ||
            !HcDeviceIsOpen(nextRound) || !nextDrain.AllStartedTasksCompleted ||
            !nextRoundRemapOwnedByItsOwnSession)
            throw new InvalidOperationException(
                $"async-boundary[{label}]: 旧工作结算后下一轮合法入口未完成 phase={nextPhase} " +
                $"failure={nextFailure ?? "<none>"} isOpen={HcDeviceIsOpen(nextRound)} " +
                $"remapOwned={nextRoundRemapOwnedByItsOwnSession} (lastRemapGen={nextRound.LastRemapOnGeneration} " +
                $"dispatchGen={nextRound.DispatchGeneration} stale={nextRound.StaleRemapOnCount}) " +
                $"drain={nextDrain.Continuation}/{nextDrain.ReadyLoop}/{nextDrain.ReadLoop}");

        checks.Add(
            $"hc-async-boundary[{label}] callerFailure={callerFailure ?? "<none>"} " +
            $"orphanDispatchGeneration={device.DispatchGeneration} " +
            $"remapOn={device.RemapOnCount} remapOff={device.RemapOffCount} readLoopStarts={device.ReadLoopStarts} " +
            $"staleRemapOnCount={stale} lastRemapOnGeneration={lastGeneration} " +
            $"drain={drain.ReadyLoop}/{drain.Continuation}/{drain.ReadLoop} drainedTasksCompleted={drain.AllStartedTasksCompleted} " +
            $"continuationFault={drain.ContinuationFaultType ?? "<none>"} " +
            $"nextRoundPhase={nextPhase} nextRoundRemapOwnedByItsOwnSession={nextRoundRemapOwnedByItsOwnSession} " +
            $"finalStateOwnedByCurrentSession={converges} strict={HcAsyncBoundaryStrict} verdict={verdict}");
        return checks;
    }

    /**
     * §17.1-2：**引擎 gate 持有期的进展验证**。
     *
     * 生产事实：`FanHostEngine.OpenEvents()` 的 `lock(gate)` 包住整个三阶段
     * （真实设备打开等待上限 10 秒）。本场景用**同一个 gate**、**同一个生产入口**
     * 复现该持有期（仅自测延时缝，生产默认 0），逐项测量五类入口的进展：
     *   ① 状态查询（Snapshot）
     *   ② 睡眠通知（OS 面向回调面 + 串行 worker）
     *   ③ Close（生产关闭入口）
     *   ④ 父进程退出交接（设计上 lock-free）
     *   ⑤ 重复广播/回调重入（去重，不伪造新转换）
     * 断言只约束"必须有界完成"与"回调面不得被持有期阻塞"；观测到的阻塞时长按事实记录。
     * 恢复重试计时器与 gate 的交互在本机**不可达运行时测量**（safe 构建无法同时具备
     * FaultLocked + 已排定的重试），按源码事实判定并登记为未运行时测量项。
     */
    internal static IReadOnlyList<string> RunEngineGateProgressSelfTest()
    {
        const int gateHoldMs = 1_200;
        const int callbackBoundMs = 250;
        var checks = new List<string>();
        var diagnostics = new HostDiagnosticLog();
        var port = 8801;

        static double Ms(long startedTicks) => (Stopwatch.GetTimestamp() - startedTicks) * 1000d / Stopwatch.Frequency;

        static FanHostEngine NewProbe(HostDiagnosticLog log, int probePort)
        {
            var options = HostOptions.Parse(new[] { "--port", probePort.ToString() });
            var engine = new FanHostEngine(options, log);
            _ = engine.Open();
            _ = engine.OpenEvents();
            return engine;
        }

        static bool WaitForStateBounded(FanHostEngine engine, string expected, int timeoutMs)
        {
            var deadline = Environment.TickCount64 + timeoutMs;
            while (Environment.TickCount64 < deadline)
            {
                if (engine.Snapshot().State == expected) return true;
                Thread.Sleep(25);
            }
            return false;
        }

        // ---- ① 状态查询 ----
        {
            var engine = NewProbe(diagnostics, port++);
            engine.SetGateHoldForSelfTest(gateHoldMs);
            var hold = Task.Run(() => { _ = engine.OpenEvents(); });
            Thread.Sleep(150);
            var queryStarted = Stopwatch.GetTimestamp();
            var snapshot = engine.Snapshot();
            var queryMs = Ms(queryStarted);
            if (!hold.Wait(gateHoldMs + 5000))
                throw new InvalidOperationException("engine-gate-progress: 持有者未在有界时间内返回（疑似死锁）");
            if (queryMs > gateHoldMs + 2000)
                throw new InvalidOperationException($"engine-gate-progress: 状态查询未在有界时间内完成 queryMs={queryMs:F0}");
            if (snapshot.State != "Ready")
                throw new InvalidOperationException($"engine-gate-progress: 持有期内状态查询返回值损坏 state={snapshot.State}");
            checks.Add($"engine-gate-progress[state-query] holdMs={gateHoldMs} queryBlockedMs={queryMs:F0} bounded=true state={snapshot.State}");
        }

        // ---- ② 睡眠通知（OS 面向回调面 + 串行 worker）----
        {
            var options = HostOptions.Parse(new[] { "--port", port++.ToString() });
            var engine = new FanHostEngine(options, diagnostics);
            using var server = new LocalFanHostServer(engine, options, diagnostics);
            _ = server.StartPowerWorkerForSelfTest();
            _ = engine.Open();
            _ = engine.OpenEvents();
            engine.SetGateHoldForSelfTest(gateHoldMs);
            var hold = Task.Run(() => { _ = engine.OpenEvents(); });
            Thread.Sleep(150);
            var callbackStarted = Stopwatch.GetTimestamp();
            server.InvokePowerModeChangedForSelfTest(PowerModes.Suspend);
            var callbackMs = Ms(callbackStarted);
            if (callbackMs > callbackBoundMs)
                throw new InvalidOperationException($"engine-gate-progress: OS 面向的电源回调被 gate 持有期阻塞 callbackMs={callbackMs:F0}");
            var workerProgressed = WaitForStateBounded(engine, "Suspended", gateHoldMs + 5000);
            var holdReturned = hold.Wait(gateHoldMs + 5000);
            if (!holdReturned || !workerProgressed)
                throw new InvalidOperationException(
                    $"engine-gate-progress: 串行 worker 未在有界时间内推进 holdReturned={holdReturned} workerProgressed={workerProgressed}");
            checks.Add($"engine-gate-progress[sleep-notification] holdMs={gateHoldMs} osCallbackMs={callbackMs:F0} workerReachedSuspended={workerProgressed} bounded=true");
        }

        // ---- ③ Close ----
        {
            var options = HostOptions.Parse(new[] { "--port", port++.ToString() });
            var engine = new FanHostEngine(options, diagnostics);
            using var server = new LocalFanHostServer(engine, options, diagnostics);
            _ = engine.Open();
            _ = engine.OpenEvents();
            engine.SetGateHoldForSelfTest(gateHoldMs);
            var hold = Task.Run(() => { _ = engine.OpenEvents(); });
            Thread.Sleep(150);
            var closeStarted = Stopwatch.GetTimestamp();
            var closeTask = Task.Run(() =>
            {
                try { _ = server.CloseForSelfTest(); return "closed"; }
                catch (Exception ex) { return "error:" + Unwrap(ex).First().GetType().Name; }
            });
            if (!closeTask.Wait(gateHoldMs + 5000))
                throw new InvalidOperationException("engine-gate-progress: Close 未在有界时间内完成（疑似死锁）");
            var closeMs = Ms(closeStarted);
            hold.Wait(gateHoldMs + 5000);
            if (closeTask.Result != "closed")
                throw new InvalidOperationException($"engine-gate-progress: Close 结果异常 {closeTask.Result}");
            checks.Add($"engine-gate-progress[close] holdMs={gateHoldMs} closeBlockedMs={closeMs:F0} bounded=true outcome=closed");
        }

        // ---- ④ 父进程退出交接（设计上 lock-free）----
        {
            var engine = NewProbe(diagnostics, port++);
            engine.SetGateHoldForSelfTest(gateHoldMs);
            var hold = Task.Run(() => { _ = engine.OpenEvents(); });
            Thread.Sleep(150);
            var handoffStarted = Stopwatch.GetTimestamp();
            _ = engine.BeginParentExitHandoff();
            var handoffMs = Ms(handoffStarted);
            hold.Wait(gateHoldMs + 5000);
            if (handoffMs > callbackBoundMs)
                throw new InvalidOperationException($"engine-gate-progress: 父进程退出交接被 gate 持有期阻塞 handoffMs={handoffMs:F0}");
            checks.Add($"engine-gate-progress[parent-exit-handoff] holdMs={gateHoldMs} handoffMs={handoffMs:F0} lockFree=true");
        }

        // ---- ⑤ 重复广播 / 回调重入 ----
        {
            var options = HostOptions.Parse(new[] { "--port", port++.ToString() });
            var engine = new FanHostEngine(options, diagnostics);
            using var server = new LocalFanHostServer(engine, options, diagnostics);
            _ = server.StartPowerWorkerForSelfTest();
            _ = engine.Open();
            _ = engine.OpenEvents();
            engine.SetGateHoldForSelfTest(gateHoldMs);
            var hold = Task.Run(() => { _ = engine.OpenEvents(); });
            Thread.Sleep(150);
            var firstStarted = Stopwatch.GetTimestamp();
            var first = server.PublishPowerForSelfTest(PowerIngressTarget.Suspended);
            var firstMs = Ms(firstStarted);
            var secondStarted = Stopwatch.GetTimestamp();
            var second = server.PublishPowerForSelfTest(PowerIngressTarget.Suspended);
            var secondMs = Ms(secondStarted);
            hold.Wait(gateHoldMs + 5000);
            if (firstMs > callbackBoundMs || secondMs > callbackBoundMs)
                throw new InvalidOperationException($"engine-gate-progress: 回调重入被 gate 持有期阻塞 first={firstMs:F0} second={secondMs:F0}");
            if (first != PowerPublishResult.Queued || second != PowerPublishResult.Suppressed)
                throw new InvalidOperationException($"engine-gate-progress: 重复广播未被去重 first={first} second={second}");
            checks.Add($"engine-gate-progress[duplicate-callback] holdMs={gateHoldMs} firstMs={firstMs:F0} secondMs={secondMs:F0} first={first} second={second}");
        }

        // ---- ⑥ 恢复重试计时器（到点被持有期挡住 → 释放后有界执行；预算按真实时间消耗、不重置、不重复计数）----
        {
            var options = HostOptions.Parse(new[] { "--port", port++.ToString() });
            var engine = new FanHostEngine(options, diagnostics);
            _ = engine.Open();
            _ = engine.OpenEvents();

            static List<JsonElement> RetryScheduled() =>
                HostDiagnosticLog.SelfTestCaptured
                    .Where(entry => entry.Event == "recovery.retry-scheduled")
                    .Select(entry => JsonDocument.Parse(entry.Details).RootElement.Clone())
                    .ToList();

            HostDiagnosticLog.ResetSelfTestCapture();
            HostDiagnosticLog.SelfTestCaptureEnabled = true;
            try
            {
                // 夹具：FaultLocked + 已排定的第 1 次恢复重试（Close 的 OEM 恢复未确认分支）。
                engine.InjectUncertainStateForSelfTest();
                var faultCode = "<none>";
                try { _ = engine.Close(); }
                catch (FanApiException ex) { faultCode = ex.Code; }
                var faultState = engine.Snapshot().State;
                if (faultCode == "<none>" || (faultState != "FaultLocked" && faultState != "AwaitingCloseCleanup"))
                    throw new InvalidOperationException(
                        $"engine-gate-progress: 夹具未进入 FaultLocked（恢复重试无法排定） code={faultCode} state={faultState}");
                if (RetryScheduled().Count != 1)
                    throw new InvalidOperationException("engine-gate-progress: Close 失败后应恰好排定 1 次恢复重试");

                // 持有期覆盖"第 1 次重试到点时刻"（间隔 2000ms）：到点回调应被 gate 挡住。
                var holdStarted = Stopwatch.GetTimestamp();
                var hold = Task.Run(() => engine.HoldGateForSelfTest(3000));
                Thread.Sleep(2500);
                var scheduledDuringHold = RetryScheduled().Count;
                if (scheduledDuringHold != 1)
                    throw new InvalidOperationException(
                        $"engine-gate-progress: 持有期内重试排定数异常 scheduled={scheduledDuringHold}（到点回调不得在持锁期间执行/重复排定）");
                if (!hold.Wait(6000))
                    throw new InvalidOperationException("engine-gate-progress: 持有者未返回（疑似死锁）");

                // 释放后有界推进：到点那次真正执行（失败后再排下一次）。
                var progressed = false;
                var deadline = Environment.TickCount64 + 6000;
                while (Environment.TickCount64 < deadline)
                {
                    if (RetryScheduled().Count >= 2) { progressed = true; break; }
                    Thread.Sleep(50);
                }
                var events = RetryScheduled();
                var last = events[^1];
                var lastAttempt = last.GetProperty("attempt").GetInt32();
                var lastElapsedMs = last.GetProperty("elapsedMs").GetDouble();
                var attempts = events.Select(e => e.GetProperty("attempt").GetInt32()).ToList();
                var terminalSeen = HostDiagnosticLog.SelfTestCaptured.Any(e => e.Event == "recovery.retry-terminal");
                if (!progressed)
                    throw new InvalidOperationException(
                        $"engine-gate-progress: 释放后恢复重试未推进 scheduled={events.Count} state={engine.Snapshot().State}");
                if (attempts.Distinct().Count() != attempts.Count)
                    throw new InvalidOperationException($"engine-gate-progress: 重试 attempt 重复计数 attempts=[{string.Join(",", attempts)}]");
                if (lastElapsedMs < 2500)
                    throw new InvalidOperationException(
                        $"engine-gate-progress: 重试预算未按真实时间消耗（持有期被抹掉） lastElapsedMs={lastElapsedMs:F0} attempts=[{string.Join(",", attempts)}]");
                if (terminalSeen)
                    throw new InvalidOperationException("engine-gate-progress: 持有期内不应进入 retry 终态");
                checks.Add(
                    $"engine-gate-progress[recovery-retry] holdMs=3000 scheduledDuringHold={scheduledDuringHold} " +
                    $"attemptsAfterRelease=[{string.Join(",", attempts)}] lastAttempt={lastAttempt} lastElapsedMs={lastElapsedMs:F0} " +
                    $"terminalSeen={terminalSeen} state={engine.Snapshot().State} " +
                    $"(到点重试被持有期推迟，释放后执行；预算按真实时间消耗、不重置、不重复计数)");
            }
            finally
            {
                HostDiagnosticLog.SelfTestCaptureEnabled = false;
                HostDiagnosticLog.ResetSelfTestCapture();
            }
        }

        return checks;
    }

    /**
     * §17.4-A"异常"用例：判据读取抛异常时，**生产协调骨架**必须把失败交给调用方，
     * 不得变成成功、也不得被当成普通超时；且异常不得伴随副作用。
     * 该不变量是生产骨架自身的性质（不是冻结 HC 的已知缺陷）⇒ 违规在**默认模式也失败**。
     */
    private static IReadOnlyList<string> RunAsyncBoundaryExceptionScenario(RealHcBackend backend)
    {
        var checks = new List<string>();
        var device = new AsyncBoundaryProbeDevice { ReadyAfterMs = 0, ThrowOnIsOpen = true };
        device.SimulateHcOpen();   // HC Open() 成功，但判据读取本身抛异常
        var adapter = new ProbeHcDeviceOpenAdapter(backend, device);
        var operation = new HcDeviceOpenOperation("exception-on-predicate", 1);
        string? callerFailure = null;
        var phase = HcDeviceOpenPhase.NotApplicable;
        try
        {
            phase = CoordinateHcDeviceOpen(adapter, 500, operation);
        }
        catch (Exception ex)
        {
            callerFailure = string.Join(" | ", Unwrap(ex).Select(e => e.GetType().Name + ": " + e.Message));
        }

        var violations = new List<string>();
        if (callerFailure is null) violations.Add("exception-was-not-reported-to-the-caller");
        else if (!callerFailure.Contains("selftest-probe-isopen-throw", StringComparison.Ordinal))
            violations.Add("caller-failure-lost-the-original-reason");
        if (phase is HcDeviceOpenPhase.Completed or HcDeviceOpenPhase.AlreadyOpen)
            violations.Add("exception-was-reported-as-success");
        if (device.WasDispatched) violations.Add("dispatch-happened-despite-predicate-failure");
        if (operation.Phase != HcDeviceOpenPhase.NotApplicable)
            violations.Add("operation-record-claimed-a-phase-despite-immediate-exception");
        if (device.HidOpen || device.ReadLoopStarts > 0 || device.RemapOnCount > 0)
            violations.Add("side-effect-happened-despite-exception");
        device.RequestReadyLoopExit();
        if (violations.Count > 0)
            throw new InvalidOperationException(
                "async-boundary exception case: " + string.Join("+", violations) + " | callerFailure=" + (callerFailure ?? "<none>"));

        checks.Add(
            $"hc-async-boundary[exception-on-predicate] callerFailure={callerFailure} phase={phase} " +
            $"operationPhase={operation.Phase} dispatched={device.WasDispatched} hidOpen={device.HidOpen} " +
            $"readLoopStarts={device.ReadLoopStarts} remapOn={device.RemapOnCount} verdict=FAILURE-REACHED-THE-CALLER");
        return checks;
    }

    #if YEMAN_ASYNC_BOUNDARY_TEST
    /**
     * 独立子进程专用：让 async void 内的异常真的逃逸，观察它是否终止进程。
     * 主自测进程不得执行本方法。
     * §17.1-5：本方法**只存在于测试专用构建**（YEMAN_ASYNC_BOUNDARY_TEST），
     * 正式构建里连方法带入口都不存在 ⇒ 生产启动不可能被改道到故意崩溃路径。
     */
    internal static IReadOnlyList<string> RunHcAsyncBoundaryChildThrowProbe()
    {
        var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        var device = new AsyncBoundaryProbeDevice { ReadyAfterMs = 0, ThrowOnRemap = true };
        var checks = new List<string> { "hc-async-boundary-child:probe-started" };
        try
        {
            backend.OnStaBounded(() =>
            {
                InvokeHcDeviceInserted(device);
                return true;
            }, "selftest-async-boundary-child-throw");
            checks.Add("hc-async-boundary-child:dispatch-returned");
        }
        catch (Exception ex)
        {
            checks.Add("hc-async-boundary-child:caller-caught:" + Unwrap(ex).First().GetType().Name);
        }
        Thread.Sleep(1500);
        checks.Add("hc-async-boundary-child:process-survived-async-void-throw");
        return checks;
    }
#endif

    /**
     * §17.1-4：排空结果 —— 记录**真实完成事实**，不用"停止标志为 false"冒充任务结束。
     * `AllStartedTasksCompleted` 只在"已派发且所有已启动任务都真正结束"时为真。
     */
    internal sealed record HcProbeDrainResult(
        bool Dispatched,
        string ReadyLoop,
        string Continuation,
        string ReadLoop,
        bool AllStartedTasksCompleted,
        string? ContinuationFaultType,
        string Detail);

    private sealed class AsyncBoundaryProbeDevice
    {
        private readonly object gate = new();
        // 锚点取构造时刻：真实 HC 的 IsReady() 不依赖 Device_Inserted 是否已派发。
        // 派发时会被重设为派发时刻，以保留“就绪窗口自派发起算”的语义。
        private long startedAtTicks = Stopwatch.GetTimestamp();
        private int isReadyCalls;
        private int remapOn;
        private int remapOff;
        private int readLoopStarts;
        private int staleRemapOn;
        private int activeGeneration = 1;
        private volatile bool readLoopRunning;
        private volatile bool drained;
        private bool IsReading;
        // §17.1-4：**真实完成记录**（不是布尔标志）。三项任务各自以 Task 结束为证：
        //   continuationCompletion = Device_Inserted 续体整体（含异常逃逸前的 finally）
        //   readyLoopCompletion    = WaitUntilReady 就绪循环
        //   readLoopTask           = 持续读取循环（生命周期与操作分开管理）
        private readonly TaskCompletionSource continuationCompletion =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource readyLoopCompletion =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private Task? readyLoopTask;
        private Task? readLoopTask;
        // 与 ROGAlly.cs L40 的三项条件同形（基类两项 + 派生类两项）：
        //   ROGAlly.IsOpen = hidDevices.ContainsKey(INPUT_HID_ID)
        //                 && hidDevices[INPUT_HID_ID].IsOpen && base.IsOpen
        //   base (ASUS.cs L7) = DeviceOpen && AsusACPI.IsOpen
        private bool DeviceOpen;      // 基类项1：HC Open() 成功
        private bool AsusAcpiOpen;    // 基类项2：ACPI 句柄打开
        private bool hidBound;        // 派生类项1：hidDevices.ContainsKey(INPUT_HID_ID)
        private bool hidOpen;         // 派生类项2：hidDevices[INPUT_HID_ID].IsOpen

        public int ReadyAfterMs { get; set; }
        public bool ThrowOnRemap { get; set; }
        /**
         * §17.4-A"异常"用例：让**判据读取本身**抛异常，用于在生产协调骨架内断言
         * "调用方得到失败而不是成功"。`IsOpen` 是生产唯一判据 `HcDeviceIsOpen` 读取的属性，
         * 因此异常会沿 `IHcDeviceOpenAdapter.IsDeviceOpen()` 冒泡到调用者。
         */
        public bool ThrowOnIsOpen { get; set; }
        /** §16.1 变量：IsReady() 是否顺带把 HID 打开（真实取值待实机；两种都测）。 */
        public bool IsReadyAlsoOpensHid { get; set; }
        /** 模拟拟定 HC 最小差异：Device_Inserted 的 await 不捕获调用方上下文。 */
        public bool ContinuationOffDispatcher { get; set; }
        public string PrefixThreadContext { get; private set; } = "<unset>";
        public int PrefixThreadId { get; private set; }
        public string ContinuationThreadContext { get; private set; } = "<unset>";
        public int ContinuationThreadId { get; private set; }
        public double ContinuationAtMs { get; private set; } = -1;
        public double DispatchReturnedAtMs { get; private set; } = -1;
        public int RemapOnCount => Volatile.Read(ref remapOn);
        public int RemapOffCount => Volatile.Read(ref remapOff);
        public int ReadLoopStarts => Volatile.Read(ref readLoopStarts);
        public int StaleRemapOnCount => Volatile.Read(ref staleRemapOn);
        public int DispatchGeneration { get; private set; } = -1;
        public int LastRemapOnGeneration { get; private set; } = -1;
        public int IsReadyCalls => Volatile.Read(ref isReadyCalls);
        public bool ReadLoopRunning => readLoopRunning;
        /** 与 ROGAlly.cs L40 同形的三项条件；真实生产用 HcDeviceIsOpen 读同一属性。 */
        public bool IsOpen
        {
            get
            {
                if (ThrowOnIsOpen)
                    throw new InvalidOperationException("selftest-probe-isopen-throw");
                lock (gate) return hidBound && hidOpen && DeviceOpen && AsusAcpiOpen;
            }
        }
        public bool ReadLoopFlag { get { lock (gate) return IsReading; } }
        /** 基类 IsOpen（DeviceOpen && AsusACPI.IsOpen）—— 用于证明"Open 成功 ≠ 设备 IsOpen"。 */
        public bool BaseIsOpen { get { lock (gate) return DeviceOpen && AsusAcpiOpen; } }
        /** §17.1-6：单项可观测，使"确实绑定但未打开"这类断言不再空洞。 */
        public bool HidBound { get { lock (gate) return hidBound; } }
        public bool HidOpen { get { lock (gate) return hidOpen; } }
        /** §17.4-C 断言用：操作返回后才发生的打开，以及没有会话归属的读取循环。 */
        public long OperationReturnedAtMs { get; set; } = -1;
        public bool ObservedOpenAfterOperationReturn { get; private set; }
        public bool SessionOwnsDevice { get; set; }
        public bool UnownedReadLoopStarted { get; private set; }
        /** 单项可观测，便于把早退/挂起分支的成因分开报告。 */
        public string ConditionTrace { get { lock (gate) return $"deviceOpen={DeviceOpen} acpi={AsusAcpiOpen} hidBound={hidBound} hidOpen={hidOpen}"; } }

        /** HC Open() 成功：只置基类两项，**不**绑定/打开输入 HID（这正是 helper 存在的理由）。 */
        public void SimulateHcOpen()
        {
            lock (gate) { DeviceOpen = true; AsusAcpiOpen = true; }
        }

        /** 会话结束：与 ROGAlly.Close() 同形 —— ACPI 关闭、remap 还原、hidDevices 清空。 */
        public void SimulateClose()
        {
            lock (gate) { DeviceOpen = false; AsusAcpiOpen = false; hidBound = false; hidOpen = false; activeGeneration++; }
            Interlocked.Increment(ref remapOff);
        }

        /** §16.4/§17.1-4：测试侧退出标志（**只请求退出，不代表任务已结束**）。 */
        public void RequestReadyLoopExit() => drained = true;

        /**
         * §17.1-4：排空 = 请求退出 + **等待真实完成的任务**。
         * 不再用"睡几秒"或"停止标志为 false"冒充结束；三项任务的实际 Task 状态逐项报告。
         */
        public HcProbeDrainResult DrainAndAwaitCompletion(int timeoutMs = 5000)
        {
            RequestReadyLoopExit();
            var readyLoop = Volatile.Read(ref readyLoopTask);
            var readLoop = Volatile.Read(ref readLoopTask);
            var tasks = new List<Task>();
            if (readyLoop is not null) tasks.Add(readyLoop);
            if (readLoop is not null) tasks.Add(readLoop);
            tasks.Add(continuationCompletion.Task);
            var all = Task.WhenAll(tasks);
            bool allCompleted;
            try
            {
                allCompleted = all.Wait(timeoutMs);
            }
            catch (AggregateException)
            {
                // 任务以异常结束：等于已经结束（异常归属由 ContinuationFault 单独记录），
                // 但不得把它当成"平静排空"。
                allCompleted = true;
            }
            var readyLoopState = readyLoop is null ? "not-started" : readyLoop.IsCompleted ? "completed" : "running";
            var continuation = continuationCompletion.Task.IsCompleted ? "completed" : "running";
            var readLoopState = readLoop is null ? "not-started" : readLoop.IsCompleted ? "completed" : "running";
            var startedCompleted = WasDispatched &&
                continuation == "completed" &&
                readyLoopState != "running" &&
                readLoopState != "running";
            return new HcProbeDrainResult(
                WasDispatched,
                readyLoopState,
                continuation,
                readLoopState,
                startedCompleted,
                ContinuationFault?.GetType().Name,
                $"waitedMs<={timeoutMs} allCompleted={allCompleted} readyLoopAlive={IsReadyLoopAlive()} readLoopRunning={readLoopRunning} IsReading={ReadLoopFlag}");
        }

        /** §17.1-4：续体异常归属（异常仍按 async void 逃逸；此处只登记事实）。 */
        public Exception? ContinuationFault { get; private set; }

        private bool IsReadyLoopAlive() => Volatile.Read(ref readyLoopAlive) != 0;
        private int readyLoopAlive;

        public double ElapsedMs() =>
            startedAtTicks == 0 ? -1 : (Stopwatch.GetTimestamp() - startedAtTicks) * 1000d / Stopwatch.Frequency;

        /** 是否已派发过（用于报告"续体从未执行"这类事实）。 */
        public bool WasDispatched { get; private set; }

        public void MarkDispatchReturned() => DispatchReturnedAtMs = ElapsedMs();

        public void RecordRemapOff() => Interlocked.Increment(ref remapOff);

        /** 恢复流程的 Close：结束旧会话（清设备、remap 还原、代次推进）。 */
        public void SimulateRecoveryClose() => SimulateClose();

        /** 建立一个新会话：设备就绪、代次推进，并由新会话自己应用 remap。 */
        public void SimulateNewSessionRemapOn(int generation)
        {
            lock (gate) { DeviceOpen = true; AsusAcpiOpen = true; hidBound = true; hidOpen = true; activeGeneration = generation; }
            SessionOwnsDevice = true;
            ConfigureController(true, generation);
        }

        public bool WaitedForContinuation(int timeoutMs)
        {
            var deadline = Environment.TickCount64 + timeoutMs;
            while (Environment.TickCount64 < deadline && ContinuationAtMs < 0) Thread.Sleep(25);
            return ContinuationAtMs >= 0;
        }

        // 与 ROGAlly.IsReady()（L344-363）同形：轮询期间会**绑定** hidDevices[INPUT_HID_ID]，
// 但**不打开**该 HID —— 打开是 Device_Inserted 续体里 device.OpenDevice() 的职责。
        public bool IsReady()
        {
            Interlocked.Increment(ref isReadyCalls);
            var ready = ElapsedMs() >= ReadyAfterMs;
            if (ready) { lock (gate) { hidBound = true; if (IsReadyAlsoOpensHid) hidOpen = true; } }
            return ready;
        }

        // 与 IDevice.WaitUntilReady()（L952-956）逐行同形，含 ConfigureAwait(false)；
        // 额外只加测试侧排空退出（drained），不改生产语义。
        // §17.1-4：结束（正常或退出）时置**真实完成**记录，供排空断言使用。
        private async Task WaitUntilReady()
        {
            Interlocked.Increment(ref readyLoopAlive);
            try
            {
                while (!IsReady())
                {
                    if (drained) return;
                    await Task.Delay(250).ConfigureAwait(false);
                }
            }
            finally
            {
                Interlocked.Decrement(ref readyLoopAlive);
                readyLoopCompletion.TrySetResult();
            }
        }

        // 与 ROGAlly.Device_Inserted（L275-292）同形：async void、无 try/catch
        // §17.1-4 追加（不改变形态）：异常只登记归属后**仍然逃逸**；续体结束时置真实完成记录。
        private async void Device_Inserted(bool reScan)
        {
            PrefixThreadId = Environment.CurrentManagedThreadId;
            PrefixThreadContext = SynchronizationContext.Current?.GetType().FullName ?? "<none>";
            lock (gate) { startedAtTicks = Stopwatch.GetTimestamp(); DispatchGeneration = activeGeneration; }
            WasDispatched = true;
            try
            {
                if (reScan)
                {
                    var ready = WaitUntilReady();
                    Volatile.Write(ref readyLoopTask, ready);
                    if (ContinuationOffDispatcher) await ready.ConfigureAwait(false);
                    else await ready;
                }
                ContinuationThreadId = Environment.CurrentManagedThreadId;
                ContinuationThreadContext = SynchronizationContext.Current?.GetType().FullName ?? "<none>";
                ContinuationAtMs = ElapsedMs();
                bool bound;
                lock (gate) bound = hidBound;
                // 与 ROGAlly 的 hidDevices.TryGetValue 失配等价：整段跳过
                if (!bound) return;
                // 操作身份：把派发时捕获的代次作为**局部值**传给写入，避免被后续会话覆盖
                var operationGeneration = DispatchGeneration;
                // 与 ROGAlly L283 device.OpenDevice() 等价：这才是把 hidOpen 置真的地方
                lock (gate) { hidOpen = true; IsReading = true; }
                // §17.4-C：操作已返回之后才发生的打开 = 迟到副作用的直接证据
                if (OperationReturnedAtMs >= 0 && ElapsedMs() > OperationReturnedAtMs)
                    ObservedOpenAfterOperationReturn = true;
                Volatile.Write(ref readLoopTask, ReadLoopAsync());
                ConfigureController(true, operationGeneration);
            }
            catch (Exception ex)
            {
                // async void 的异常归属：只登记，不改逃逸行为（子进程崩溃探针依赖该形态）。
                ContinuationFault = ex;
                throw;
            }
            finally
            {
                continuationCompletion.TrySetResult();
            }
        }

        // 与 ROGAlly.ReadLoopAsync（L294-305）同形：ConfigureAwait(false) 后续体在线程池
        private async Task ReadLoopAsync()
        {
            Interlocked.Increment(ref readLoopStarts);
            if (!SessionOwnsDevice) UnownedReadLoopStarted = true;
            readLoopRunning = true;
            try
            {
                while (true)
                {
                    lock (gate) { if (!IsReading) break; }
                    await Task.Delay(20).ConfigureAwait(false);
                }
            }
            catch { }
            finally { readLoopRunning = false; }
        }

        private void ConfigureController(bool remap, int operationGeneration)
        {
            if (ThrowOnRemap) throw new InvalidOperationException("selftest-async-boundary-remap-throw");
            int currentGeneration;
            lock (gate) currentGeneration = activeGeneration;
            if (remap)
            {
                Interlocked.Increment(ref remapOn);
                LastRemapOnGeneration = operationGeneration;
                // 归属已死会话的写入：这就是“旧操作干扰后续控制”的判据（I-10）
                if (operationGeneration != currentGeneration) Interlocked.Increment(ref staleRemapOn);
            }
            else
            {
                Interlocked.Increment(ref remapOff);
            }
        }

        // 真实 StopHcControllerCpuLoops（L4590-4620）所用的同一停止机制
        public bool TryStopReadLoop() => SetInstanceBoolField(this, new[] { "IsReading", "isReading" }, false);
    }

    public void Dispose()
    {
        // Engine Close owns the real CurrentDevice.Close boundary. Dispose is
        // only reached after a confirmed Host shutdown, so never synthesize a
        // second virtual device Close here.
        lock (hardwareGate) StopCpuTemperatureMonitor();
        // HC-SLIM-01 R4 §4 H1：backend provider 自持 ACPI 句柄，走同一归还助手（仅在真正
        // 打开或 leaf 句柄仍有效时归还），与 CloseCore 的关闭边界共用一份归属逻辑。
        ReleaseBackendAsusAcpiOwnedHandle("dispose");
        Dispatcher? dispatcher;
        Thread? dispatcherThread;
        lock (staGate)
        {
            if (staDispatcherStopping) return;
            staDispatcherStopping = true;
            dispatcher = staDispatcher;
            dispatcherThread = staThread;
        }
        if (dispatcher is not null && Thread.CurrentThread != dispatcherThread)
        {
            try { dispatcher.BeginInvokeShutdown(DispatcherPriority.Send); }
            catch (InvalidOperationException) { }
        }
        if (dispatcherThread is null || Thread.CurrentThread == dispatcherThread) return;
        if (!dispatcherThread.Join(TimeSpan.FromSeconds(2)))
            Diagnostic?.Invoke("hc-sta-dispatcher.dispose-pending", new { });
    }
}

/**
 * Read-only HWiNFO temperature source for the Fan Host.
 *
 * The existing YeMan monitor already opens HWiNFO shared memory. FanHost is
 * another read-only consumer of that same mapping; it never opens a second
 * hardware-sensor backend. HC FanProfile and the HC device callback remain
 * the only fan-control path.
 */
internal sealed class HWiNFOTemperatureMonitor : IDisposable
{
    private const int PollIntervalMs = 1000;
    private const uint HWiNFOSignature = 0x53695748;
    private const int ReadingLabelOffset = 12;
    private const int ReadingValueOffset = 284;
    private const int MinimumReadingSize = 316;
    private static readonly string[] SharedMemoryNames =
    [
        "Global\\HWiNFO_SENS_SM2",
        "HWiNFO_SENS_SM2",
        "Global\\HWiNFO_SENS_SM",
        "HWiNFO_SENS_SM",
    ];
    private readonly record struct HWiNFOSnapshot(float TemperatureC);

    private readonly object gate = new();
    private Timer? timer;
    private Action<float?>? sampleReceived;
    private Action? healthySampleReceived;
    private float? lastPublishedTemperature;
    private int polling;
    private bool disposed;
    private long pollCount;
    private long healthyPollCount;
    private long pollErrorCount;
    private long skippedOverlapCount;
    private long lastPollDurationTicks;
    private long maxPollDurationTicks;
    private string? lastPollError;
    private DateTimeOffset? startedAtUtc;
    private long lastReadAtUnixMs;
    private string? lastMappingName;

    public HWiNFOTemperatureMonitor() { }

    public void Start(Action<float?> callback, Action healthySampleCallback)
    {
        lock (gate)
        {
            if (disposed) throw new ObjectDisposedException(nameof(HWiNFOTemperatureMonitor));
            if (timer is not null) return;
            sampleReceived = callback;
            healthySampleReceived = healthySampleCallback;
            startedAtUtc = DateTimeOffset.UtcNow;
            timer = new Timer(Poll, null, 0, PollIntervalMs);
        }
    }

    private void Poll(object? _)
    {
        var started = Stopwatch.GetTimestamp();
        if (Interlocked.Exchange(ref polling, 1) != 0)
        {
            Interlocked.Increment(ref skippedOverlapCount);
            return;
        }
        try
        {
            Action<float?>? callback;
            Action? healthyCallback;
            lock (gate)
            {
                if (disposed) return;
                callback = sampleReceived;
                healthyCallback = healthySampleReceived;
            }
            if (callback is null || healthyCallback is null) return;
            var snapshot = ReadSnapshot();
            Interlocked.Increment(ref pollCount);
            if (snapshot is null) return;

            Interlocked.Increment(ref healthyPollCount);
            Volatile.Write(ref lastReadAtUnixMs, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            // A valid but unchanged temperature is still a healthy sample;
            // the watchdog must not confuse a steady CPU with a dead source.
            healthyCallback();

            if (lastPublishedTemperature == snapshot.Value.TemperatureC) return;
            lastPublishedTemperature = snapshot.Value.TemperatureC;
            callback(snapshot.Value.TemperatureC);
        }
        catch (Exception ex)
        {
            // The Host watchdog observes the missing sample and enters its
            // existing restore/fault-lock path. Never let a monitor exception
            // escape a Timer callback.
            Interlocked.Increment(ref pollErrorCount);
            Interlocked.Exchange(ref lastPollError, ex.GetType().Name);
        }
        finally
        {
            var durationTicks = Stopwatch.GetTimestamp() - started;
            Interlocked.Exchange(ref lastPollDurationTicks, durationTicks);
            var previousMax = Volatile.Read(ref maxPollDurationTicks);
            while (durationTicks > previousMax &&
                   Interlocked.CompareExchange(ref maxPollDurationTicks, durationTicks, previousMax) != previousMax)
                previousMax = Volatile.Read(ref maxPollDurationTicks);
            Volatile.Write(ref polling, 0);
        }
    }

    public object DiagnosticsSnapshot()
    {
        bool active;
        DateTimeOffset? started;
        lock (gate)
        {
            active = !disposed && timer is not null;
            started = startedAtUtc;
        }
        return new
        {
            active,
            source = "HWiNFO.shared-memory",
            sharedMemoryNames = SharedMemoryNames,
            lastMappingName,
            intervalMs = PollIntervalMs,
            startedAtUtc = started,
            pollCount = Volatile.Read(ref pollCount),
            healthyPollCount = Volatile.Read(ref healthyPollCount),
            pollErrorCount = Volatile.Read(ref pollErrorCount),
            skippedOverlapCount = Volatile.Read(ref skippedOverlapCount),
            lastPollDurationMs = ToMilliseconds(Volatile.Read(ref lastPollDurationTicks)),
            maxPollDurationMs = ToMilliseconds(Volatile.Read(ref maxPollDurationTicks)),
            lastReadAtUnixMs = Volatile.Read(ref lastReadAtUnixMs),
            lastPollError,
        };
    }

    private static double ToMilliseconds(long ticks) =>
        ticks <= 0 ? 0 : ticks * 1000d / Stopwatch.Frequency;

    private HWiNFOSnapshot? ReadSnapshot()
    {
        foreach (var name in SharedMemoryNames)
        {
            try
            {
                using var map = MemoryMappedFile.OpenExisting(name, MemoryMappedFileRights.Read);
                using var view = map.CreateViewAccessor(0, 0, MemoryMappedFileAccess.Read);
                var snapshot = ReadSnapshot(view);
                if (snapshot is not null)
                {
                    Volatile.Write(ref lastMappingName, name);
                    return snapshot;
                }
            }
            catch (FileNotFoundException) { }
            catch (WaitHandleCannotBeOpenedException) { }
            catch (UnauthorizedAccessException ex) { Volatile.Write(ref lastPollError, ex.GetType().Name); }
            catch (IOException ex) { Volatile.Write(ref lastPollError, ex.GetType().Name); }
        }
        return null;
    }

    private static HWiNFOSnapshot? ReadSnapshot(MemoryMappedViewAccessor view)
    {
        if (view.Capacity < 44 || view.ReadUInt32(0) != HWiNFOSignature) return null;
        var offset = view.ReadUInt32(32);
        var size = view.ReadUInt32(36);
        var count = view.ReadUInt32(40);
        if (size < MinimumReadingSize || count == 0 || count > 100000) return null;
        var end = (long)offset + ((long)size * count);
        if (offset < 44 || end > view.Capacity) return null;

        var readings = new List<(string Label, double Value)>();
        for (var index = 0; index < count; index++)
        {
            var baseOffset = (long)offset + ((long)size * index);
            var label = ReadAnsi(view, baseOffset + ReadingLabelOffset, 128);
            var value = view.ReadDouble(baseOffset + ReadingValueOffset);
            if (double.IsFinite(value)) readings.Add((label, value));
        }

        var temperature = SelectTemperature(readings);
        if (temperature is null) return null;
        return new HWiNFOSnapshot((float)temperature.Value);
    }

    private static string ReadAnsi(MemoryMappedViewAccessor view, long position, int length)
    {
        var bytes = new byte[length];
        view.ReadArray(position, bytes, 0, bytes.Length);
        var end = Array.IndexOf(bytes, (byte)0);
        return Encoding.ASCII.GetString(bytes, 0, end >= 0 ? end : bytes.Length).Trim();
    }

    private static double? SelectTemperature(IEnumerable<(string Label, double Value)> readings)
    {
        double? tctlOrTdie = null;
        double? cpuPackage = null;
        foreach (var reading in readings)
        {
            if (reading.Label.Length == 0 ||
                reading.Label.Contains("Power", StringComparison.OrdinalIgnoreCase) ||
                reading.Label.Contains("Voltage", StringComparison.OrdinalIgnoreCase) ||
                reading.Label.Contains("RPM", StringComparison.OrdinalIgnoreCase) ||
                reading.Label.Contains("Current", StringComparison.OrdinalIgnoreCase))
                continue;
            if (!double.IsFinite(reading.Value) || reading.Value <= 0 || reading.Value > 100) continue;

            var isTctlOrTdie = reading.Label.Contains("CPU", StringComparison.OrdinalIgnoreCase) &&
                               (reading.Label.Contains("Tctl", StringComparison.OrdinalIgnoreCase) ||
                                reading.Label.Contains("Tdie", StringComparison.OrdinalIgnoreCase));
            var isCpuPackage = reading.Label.Equals("CPU Package", StringComparison.OrdinalIgnoreCase);
            if (isTctlOrTdie)
                tctlOrTdie = tctlOrTdie is null ? reading.Value : Math.Max(tctlOrTdie.Value, reading.Value);
            else if (isCpuPackage)
                cpuPackage = cpuPackage is null ? reading.Value : Math.Max(cpuPackage.Value, reading.Value);
        }
        return tctlOrTdie ?? cpuPackage;
    }

    internal static float? SelectTemperatureForSelfTest(IEnumerable<(string Label, double Value)> readings) =>
        SelectTemperature(readings) is { } value ? (float)value : null;

    internal static bool IsValidSharedSampleForSelfTest(double temperature, bool mappingAvailable) =>
        mappingAvailable && double.IsFinite(temperature) && temperature > 0 && temperature <= 100;

    public void Dispose()
    {
        lock (gate)
        {
            if (disposed) return;
            disposed = true;
            timer?.Dispose();
            timer = null;
            sampleReceived = null;
            healthySampleReceived = null;
        }
    }
}

internal sealed class FanHostEngine : IDisposable
{
    // MOCK 伪装握手（2026-09-15 用户需求，原创测试设施；**2026-09-23 架构修正**）：
    // 仅当显式 CLI 开关 `--mock-handshake` 存在时才伪装 HC 风扇设备就绪（支持
    // FanControl、fanRoute 可写），完整生命周期（handshake→open→acquire→
    // enable→release）跑通但不写真实 EC（realBackend 保持 null = safe 模式，
    // 零硬件写入）。
    // operator 裁决（2026-09-23）：**测试模式只允许 AI 代码调用，用户路径永远不可到达**。
    // App 的 fanHost.ts 只传 --real-backend/--allow-hardware-writes/--authorization/--confirm，
    // 从不传本开关 ⇒ 用户端口无法进入 mock；exe 同目录下遗留的
    // `mock-handshake.flag` **不再**开启 mock（只在诊断里记一条 ignored 事件，
    // 防止"一个多余文件改变产品行为"再次发生）。
    private bool MockFanHandshakeFlag => options.MockHandshake;
    private static bool MockHandshakeFlagFilePresent =>
        File.Exists(Path.Combine(AppContext.BaseDirectory, "mock-handshake.flag"));

    private readonly object gate = new();
    private readonly HostOptions options;
    private readonly HostDiagnosticLog diagnostics;
    private readonly HostState state;
    private readonly RealHcBackend? realBackend;
    /**
     * FAN-204 Q1-b（2026-09-23 裁决 DC61E311…）：**读路径的已发布不可变快照**。
     * 背景（真机 20:26 取证）：`Open()`/`OpenEvents()` 在 `lock (gate)` 内调用 HC，而
     * `Snapshot()` 需要同一把锁 ⇒ HC 设备打开就绪等待的 10.22 s 里，`/api/state`、`/health`、
     * 快速接受响应与诊断行全部被排队（实测 10.30 s / 6.96 s 后 500）。
     * 语义（裁决逐条）：
     *   ① 快照**整体替换**（Interlocked 换引用；对象本身是 gate 内的新鲜深拷贝，发布后不再改）；
     *   ② 读路径**不等待 gate、不调用 HC**：`Monitor.TryEnter(gate, 0)` 成功 ⇒ 现取新鲜快照并
     *      顺带发布；失败 ⇒ 返回最近一次已发布快照；
     *   ③ 长 HC 操作开始前，在 gate 内先发布一份**阶段快照**（Resuming/Open），绝不伪造 Ready；
     *   ④ 负例专用：`--mock-no-published-snapshot`（仅 mock）让读路径退回阻塞读，用于证明
     *      AC15c 的判定不空转。
     */
    private HostState? lastPublishedSnapshot;
    private bool publishedSnapshotDisabledForMock;
    private Timer? runtimeDiagnosticsTimer;
    private readonly object runtimeDiagnosticsGate = new();
    // 2026-09-23 CPU/日志降负（operator 指令：把风扇进程 CPU 占用大幅降低）：
    // 高频采样自适应——常规态 30s 一条轻量心跳；故障/挂起/未知态 1s（有界）；
    // 线程归因只在 CPU 超阈值时才做（常态不再枚举 ProcessThread）。
    private const int RuntimeSampleNormalIntervalMs = 30000;
    private const int RuntimeSampleBusyIntervalMs = 1000;
    private const double CpuThreadAttributionThresholdPercent = 1.0;
    private const double CpuWarningThresholdPercent = 3.0;
    private int runtimeSampleInFlight;
    /**
     * FAN-931 P1.2：30 s 采样里 loop 维护（StopHcControllerCpuLoops / DetectAbandonedDeviceOpen）
     * 实际被执行的次数。取数与维护已解耦，本计数用于**承重断言**"减少取数后维护仍被调用"。
     */
    private long runtimeLoopMaintenanceRuns;
    /** FAN-931 P1.2：自测/取证读数（不触发任何 HC 调用）。 */
    internal long RuntimeLoopMaintenanceRunsForSelfTest => Interlocked.Read(ref runtimeLoopMaintenanceRuns);
    private TimeSpan? lastProcessCpuTime;
    private long lastProcessSampleTimestamp;
    // Per-thread CPU accounting (read-only, diagnostic-only): lets a log archive
    // identify a runaway thread without a debugger on the test machine.
    private readonly Dictionary<int, double> lastThreadCpuMs = new();
    private HashSet<int> lastThreadIds = new();

    private readonly struct ThreadCpuRow
    {
        public ThreadCpuRow(int tid, double deltaMs, double totalMs, string startedAt, string state, bool isNew)
        {
            Tid = tid;
            DeltaMs = deltaMs;
            TotalMs = totalMs;
            StartedAt = startedAt;
            State = state;
            IsNew = isNew;
        }

        public int Tid { get; }
        public double DeltaMs { get; }
        public double TotalMs { get; }
        public string StartedAt { get; }
        public string State { get; }
        public bool IsNew { get; }
    }
    private bool disposed;
    private long generation;
    private Timer? leaseTimer;
    // R1（FAN-926R 唤醒租约裁决 §3.2.1）：**恢复 worker 自己**铸造的临时租约身份。
    // 只保存自己的 leaseId + generation，供"成功提交后窄撤销自己那一个占位租约"用；
    // 该身份只在本进程内比对，绝不出现在日志/证据/快照里（§3.2.9 不记 lease token）。
    private string? automaticResumePlaceholderLeaseId;
    private long automaticResumePlaceholderLeaseGeneration;
    private Timer? recoveryTimer;
    // Once F4 has entered strict HC SystemPending, every bounded retry must
    // remain Close-first as well. It must never fall back to the non-F4
    // Hardware-profile handoff path merely because the first Close timed out.
    private bool recoveryRetryUsesSystemPendingClose;
    // A failed HC Close/restore remains owned by this resident Host, but the
    // automatic observer/retry window is deliberately finite.  The frozen
    // Phase2 contract is one retry every 2 seconds, at most 30 attempts (60
    // seconds); after that the Host stays FaultLocked until an explicit close
    // or retry request arrives.  No timer is allowed to reschedule itself
    // forever after the cap.
    private int recoveryRetryAttempt;
    private long recoveryRetryWindowStartedMonoMs;
    private bool recoveryRetryWindowTerminal;
    private const int RecoveryRetryMaxAttempt = 30;
    private const int RecoveryRetryIntervalMs = 2_000;
    private const long RecoveryRetryWindowMs = 60_000;
    /**
     * §4.1（FAN-926 P2 场景三）：**仅自测**把 60 s 故障周期窗口缩短，使**生产**的
     * "预算耗尽 ⇒ 诚实终态 ⇒ 只有 caller-visible 显式重试能开新窗口"这条路径能被确定性覆盖。
     * 此前该语义只对手写 `Model` 断言（不是生产引擎）。生产恒 60 000。
     */
    internal static long? RecoveryRetryWindowMsForSelfTest { get; set; }
    private static long EffectiveRecoveryRetryWindowMs => RecoveryRetryWindowMsForSelfTest ?? RecoveryRetryWindowMs;
    // 2026-09-25 FAN-925 T0-X（合同 §2.1）：异常情况下 20 s 是**升级处置点**，不是清理
    // 成功证据，也不是无条件退出许可。本故障周期的预算按"一次故障周期"计账，并且
    // **跨进程更换继承**——换一个 Host 不能把 60 s / 30 次重新计时。周期记录落在用户
    // 状态目录，使被外部强终止后的替代 Host 仍能读到剩余预算与已用尝试数，并据此
    // 执行"每故障周期至多一次自动更换"的边界（超限 ⇒ 失败终态 + 用户显式重试入口）。
    private RecoveryCycleRecord? recoveryCycle;
    private bool recoveryCycleInherited;
    // 显式用户重试（caller-visible /api/close）是唯一允许"开启新周期"的自动性豁免；
    // 自动重试 / 定时器 / 替代 Host 一律不得凭此绕过周期预算。
    private bool recoveryCycleExplicitRetryRequested;
    // B4（FAN-925 / HC 回函 A1–A3）：route-lost 后宿主自身出清不了 ⇒ 转"有界等待 bridge 重开"。
    private bool recoveryReopenRequired;
    private int recoveryReopenCount;

    // ── §3（FAN-926 P1 / CP-07）：parent-exit 交接的**真实受理顺序**──────────────
    // 缺陷：旧实现把 `recoveryCycle?.CycleId` 直接当"已接受恢复周期"回报。干净的首次
    // 交接时周期还不存在 ⇒ 产品真的返回 200 + recoveryAccepted=true 却**没有**
    // acceptedRecoveryCycleId，native 判 unbound（这个拒绝是对的，是产品侧缺口）。
    // 受理必须在**返回 ACK 之前**建立，且只取短临界区 acceptanceGate —— 引擎 gate 在
    // HC/ACPI 调用期间被长持有（真机 10.22 s），受理**绝不**靠抢那把锁赢（H4）。
    private sealed record ParentExitAcceptance(
        string HostInstanceId,
        string CycleId,
        string BindingKind,
        string Scope,
        int ParentPid,
        DateTimeOffset AcceptedAtUtc);

    private const string ParentExitAcceptanceScope =
        "accepted-by-this-host-instance-for-this-recovery-cycle";

    /** 只保护"受理记录 + 周期从无到有"这一段。锁序固定 gate → acceptanceGate。 */
    private readonly object acceptanceGate = new();
    private ParentExitAcceptance? parentExitAcceptance;

    /**
     * §4.2（FAN-926 P2）：父进程**映像**路径，只用来分辨"同一应用的另一个进程实例"
     * （= 同一个未结算故障 episode 的换实例接管）与"无关的新会话"。读不到就是 null，
     * 不改变任何既有判定，也**不**单独充当实例身份证据。
     */
    private readonly string? parentEpisodeImagePath;

    /**
     * B4：同一故障周期内**第二次** route-lost 必须收敛（重开环上限）。
     * 纯函数：便于确定性自测，避免动到共享引擎状态。
     */
    internal static bool ReopenLoopCapReached(int reopenCount) => reopenCount > 1;

    /** 故障周期记录（跨进程持久化：剩余预算 / 已用尝试 / 自动更换次数 / 终态）。 */
    private sealed record RecoveryCycleRecord(
        string CycleId,
        int ParentPid,
        DateTime StartedAtUtc,
        int Attempts,
        int Replacements,
        bool Terminal,
        bool Completed,
        string? LastReason,
        DateTime LastUpdatedAtUtc,
        // §4.2（FAN-926 P2）：父进程**映像**身份。仅凭 PID 数值无法分辨"同一故障 episode
        // 的另一个父进程实例"与该周期无关的新会话 ⇒ 换实例会被误判成新 episode 而刷新 60 s。
        string? ParentExecutablePath = null);
    private IReadOnlyList<FanNode>? activeCurve;
    // The curve is retained across the HC SystemPending Close boundary so a
    // resident Host can rebuild the session even if the WebView never sends
    // its resume callback.
    private IReadOnlyList<FanNode>? suspendedCurve;
    private Task? resumeTask;
    // 第一批：resume 接续归属。旧恢复任务未结束时收到的新 resume 请求不静默丢弃，
    // 登记为接续；由旧任务收尾时按归属再接跑（新睡眠会清此标记=被取代）。
    private int resumeContinuationRequested;
    // 第十轮返修：接续登记时的取消版本——接跑前必须核对；
    // 否则旧请求会在"新睡眠已宣布"时启动并清掉新睡眠的保护。
    private long resumeContinuationEpoch;
    // 第二十二轮返修（P1#1）：接续**登记身份**与结算留存（全部在 gate 内维护）。
    // 目的：deferred 请求在登记时就获得稳定身份（ContinuationId + 睡眠周期
    // (Value, Stamp)），等待者只按身份/周期解析——禁止用"当前 token 是否还在"或
    // "最新 attempt 比观察值大"推定归属（后者会把新周期的结果借给旧等待者，R22 复现）。
    private long resumeContinuationCounter;          // 登记身份铸号（单调）
    private long resumeContinuationId;               // 当前挂起登记的 id（0=无）
    private long resumeContinuationValue;            // 当前挂起登记的睡眠周期值
    private long resumeContinuationStamp;            // 当前挂起登记的授权归属（-1=未知）
    private long resumeSettledContinuationId;        // 最近一次"被新睡眠结算为 superseded"的登记
    private long resumeSettledContinuationValue;
    private long resumeSettledContinuationStamp;
    private long resumeConsumedContinuationId;       // 最近一次被消费（接续物化）的登记
    private long resumeConsumedContinuationValue;
    private long resumeConsumedContinuationStamp;
    private long resumeConsumedAttemptId;            // 该消费启动的 attempt（0=未启动）
    // 第一批返修：执行中恢复任务的操作身份。worker 完成时必须核对归属，
    // 非当前归属（已被新睡眠取代 / 手工注入的空身份）不得提交 Ready/completed。
    private sealed record ResumeOperationIdentity(
        long Generation, int AttemptId,
        // 第十一轮返修（R5）：请求接受时建立的不可变取消版本（贯穿 worker 与提交核对）——
        // worker 不得在启动时重读版本（否则会把期间新睡眠的版本当成旧恢复的授权）。
        long AcceptedPowerEpoch, long AcceptedPendingEpoch, long AcceptedGateEpoch);
    private object? activeResumeOperation;
    private int resumeAttemptCounter;
    // 第二十一轮返修（P1）：单槽"结算终态"留存——最近一次结算（completed/failed/
    // superseded）所属 attempt 及其结果（全部在 gate 内写入）。等待者按 attempt
    // 关联时，若自己的 attempt 已不是最新 attempt（期间已有新恢复启动），只能从本
    // 槽读取本操作的终态；未命中 ⇒ 有界回退为 superseded（fail-closed），绝不借用
    // 新操作的 completed。仅记账（不改动判定），供等待者隔离使用。
    private long resumeTerminalAttempt;
    private string? resumeTerminalStatus;
    private string? resumeTerminalOutcome;
    // 第一批返修（R1/R3）：版本化取消协议。任何"睡眠宣布/取代/新转换"都递增 epoch
    // （MarkSystemSuspendPending 用 Interlocked，保持 Windows 回调非阻塞）；
    // worker 提交前必须核对 epoch 未变——覆盖"睡眠已宣布、SuspendUnlocked 尚未执行"的窗口。
    private long powerEpoch;
    // 第十一/十九轮返修（R5/R19）：睡眠保护记录（不可变：token 值 + 发布归属一体，
    // 读取即一致快照）。恢复侧只能"值匹配"地精确消费（值唯一 ⇒ 等价于引用 CAS）；
    // 新睡眠宣布后旧恢复的任何消费尝试都会失败（无无条件清 pending 的窗口）。
    private SuspendProtectionToken? suspendProtection;
    // 裁决 H3（2026-09-19）：本次睡眠边界所属的**不可变保护记录实例**（引用同一性，
    // 不是裸 Value）。仅用于"睡眠失败/进入 retry 终态"时的**条件式**令牌释放：
    // 释放前必须证明当前记录仍是这一条实例，且本 Host 不欠任何 HC Close 义务。
    private SuspendProtectionToken? suspendBoundaryOwnedRecord;
    // 第一批返修（R3）：worker 归属标志由本协议在 gate 内维护，
    // 不依赖 Task.IsCompleted（CLR 的完成标记不在同一笔同步操作里）。
    private int resumeWorkerActive;
    // Q1-c（2026-09-24 裁决）：heartbeat 的**取锁前**快速判定要在 gate 之外读它 ⇒ 必须
    // volatile（否则可能读到陈旧的 false，把"重建中"误判成可控制）。写点全部在 gate 内。
    private volatile bool automaticResumeInProgress;
    private bool? automaticResumeResult;
    // The HC SystemReady path rebuilds Open -> OpenEvents -> lease -> curve
    // asynchronously after ManagerFactory/LibreHardware resume.  Keep the
    // public admission gate closed for the whole rebuild so an external
    // enable/preset/heartbeat cannot interleave with that half-open session.
    // The worker itself is allowed through by thread identity; this avoids a
    // second public lifecycle owner without weakening the gate for callers.
    private int automaticResumeWorkerThreadId;
    // HC parity: a suspend boundary closes synchronously even while the
    // background SystemReady rebuild is in flight (HC's Open task has no sleep
    // gate). The backend serializes every HC call on hardwareGate; an in-flight
    // F5 is either completed before the Close or abandoned benignly by the
    // resume worker (CompleteAutomaticResume catch). No deferral is needed.
    private bool stopped;
    // HC MainWindow.SystemReady waits an extra 3s when the device slept for at
    // least 30 minutes (arbitrary) before resuming managers/device. Record the
    // suspend-entry UTC here so the resume worker can mirror that delay.
    private DateTime sleepEntryUtc;
    // Written by the Windows power callback without taking the engine lock.
    // It closes the admission gate before the queued restore gets a turn.
    private int systemSuspendPending;
    // Closing is also an asynchronous safety boundary. Once a parent/UI close
    // request is accepted, temperature dispatch must not obtain one more EC
    // turn while the engine lock is waiting for an in-flight HC operation.
    private int closeWriteBlocked;
    // Parent exit must never be coupled to completion of an ACPI restore. This
    // gate is set before acquiring the engine lock, then one resident Host
    // worker owns recovery after YeManCC has gone away.
    private int parentExitHandoffQueued;
    // This is set before /api/close takes the engine lock.  A native parent
    // exit can otherwise arrive in the small interval before state.CloseCalled
    // is visible and enqueue a second HC Close owner.
    private int closeBoundaryClaimed;
    // A returned close failure may be retried later, but concurrent callers
    // must observe the existing owner instead of re-entering RestoreHardware.
    private int closeBoundaryInFlight;
    private int closeOwnerSelfTestDelayMs;
    private int closeEntryCount;

    /** 920-v1.6 §18：自测组需要读取隔离候选相关选项（只读，不改变引擎行为）。 */
    internal HostOptions Options => options;

    /** §19-D 自测：本引擎自身的有界恢复重试记账（归属精确到实例，不受其它实例日志干扰）。 */
    internal int RecoveryRetryAttemptsForSelfTest => recoveryRetryAttempt;

    internal bool RecoveryRetryTimerActiveForSelfTest => recoveryTimer is not null;
    /** §4.1（FAN-926 P2 场景三）：生产引擎的终态/尝试数只读视图（行为覆盖用）。 */
    internal bool RecoveryRetryTerminalForSelfTest => recoveryRetryWindowTerminal;
    internal int RecoveryRetryAttemptForSelfTest => recoveryRetryAttempt;

    public FanHostEngine(HostOptions options, HostDiagnosticLog? diagnostics = null)
    {
        if (options.MockZeroHardwareEvidence && (!options.MockHandshake || options.RealBackend || options.AllowHardwareWrites))
            throw new ArgumentException("MOCK_ZERO_HARDWARE_REQUIRES_MOCK_ONLY");
        this.options = options;
        this.diagnostics = diagnostics ?? new HostDiagnosticLog();
        parentEpisodeImagePath = CaptureParentEpisodeImagePath(options);
        state = new HostState
        {
            // No assembly is loaded and no native API is touched in this build.
            HardwareCapable = false,
            HardwareWriteAuthorizationGranted = false,
            HardwareWritesEnabled = false,
            HardwareWritesObserved = false,
            HostMode = "safe-no-hardware",
            OemRestoreEvidence = options.RealBackend ? "none" : "not-applicable-safe-build",
            OemOwnershipStatus = options.RealBackend ? "unknown-no-hc-contract" : "not-applicable",
            ApiSessionProtected = !string.IsNullOrWhiteSpace(options.SessionToken),
            RecoveryReadbackRequired = options.RealBackend,
            ListenerState = "Starting",
        };
        realBackend = options.RealBackend && !options.MockHandshake ? new RealHcBackend(options) : null;
        // FAN-204 Q1-b：负例开关（仅 mock）——让读路径退回阻塞读，供 AC15c 负例证明判定非空转。
        if (options.MockHandshake && options.MockNoPublishedSnapshot) publishedSnapshotDisabledForMock = true;
        // FAN-204 Q1-b：启动即发布一份读快照（读者在首次持锁窗口内也有可判定答复）。
        PublishSnapshotLocked();
        if (realBackend is not null)
        {
            realBackend.FanDispatchFailure = OnBackendFanDispatchFailure;
            realBackend.TemperatureMonitorStale = OnBackendTemperatureMonitorStale;
            realBackend.TimedOutOperationReturned = OnTimedOutHcOperationReturned;
            realBackend.Diagnostic = (eventName, details) => this.diagnostics.Write(eventName, details);
        }
        this.diagnostics.SetContextProvider(BuildDiagnosticContext);
        this.diagnostics.Write("route.catalog", new
        {
            routeCount = RealHcBackend.KnownFanRouteCount,
            routes = RealHcBackend.RouteCatalogForDiagnostics,
        });
        this.diagnostics.Write("engine.created", new { options.RealBackend, options.AllowHardwareWrites });
        // 2026-09-23：mock 只经显式测试开关；遗留旗标文件不再改变行为（只记录）。
        if (options.MockHandshake)
        {
            this.diagnostics.Write("mock-handshake-requested", new { note = "test-only switch (--mock-handshake); realBackend forced null; zero hardware writes" });
        }
        else if (MockHandshakeFlagFilePresent)
        {
            this.diagnostics.Write("mock-handshake-flag-ignored", new { note = "stray mock-handshake.flag present but --mock-handshake was not passed; mock NOT enabled (2026-09-23 architecture fix: test mode is AI-only)" });
        }
        if (options.RealBackend)
        {
            // Low-frequency process telemetry is diagnostic-only. It lets a
            // real-machine run distinguish HC/route work from a runaway Host
            // loop without changing any fan or recovery timer cadence.
            runtimeDiagnosticsTimer = new Timer(_ => WriteRuntimeDiagnostics(), null, RuntimeSampleNormalIntervalMs, Timeout.Infinite);
        }
    }

    /** FAN-931 P1.2：internal 仅为自测直接驱动一次采样（生产仍只由 30 s 定时器调用）。 */
    internal void WriteRuntimeDiagnostics()
    {
        // 2026-09-23（operator：把风扇进程 CPU 占用大幅降低）：重入保护 + 自复位节拍。
        if (Interlocked.Exchange(ref runtimeSampleInFlight, 1) == 1) return;
        var nextDelayMs = RuntimeSampleNormalIntervalMs;
        try
        {
            using var process = Process.GetCurrentProcess();
            var nowTimestamp = Stopwatch.GetTimestamp();
            var nowCpu = process.TotalProcessorTime;
            double? cpuPercent = null;
            double? intervalMs = null;
            lock (runtimeDiagnosticsGate)
            {
                if (lastProcessCpuTime is not null && lastProcessSampleTimestamp != 0)
                {
                    var elapsedTicks = nowTimestamp - lastProcessSampleTimestamp;
                    intervalMs = elapsedTicks * 1000d / Stopwatch.Frequency;
                    if (intervalMs > 0)
                    {
                        var cpuMs = (nowCpu - lastProcessCpuTime.Value).TotalMilliseconds;
                        cpuPercent = Math.Clamp(cpuMs / intervalMs.Value / Math.Max(1, Environment.ProcessorCount) * 100d, 0d, 100d);
                    }
                }
                lastProcessCpuTime = nowCpu;
                lastProcessSampleTimestamp = nowTimestamp;
            }
            // 绝对口径（ms/s）：与任务管理器/软件里"单核百分比"口径可直接对账。
            var cpuMsPerSec = cpuPercent is null || intervalMs is null || intervalMs <= 0
                ? (double?)null
                : Math.Round(cpuPercent.Value / 100d * Math.Max(1, Environment.ProcessorCount) * 1000d, 1);
            // 线程归因（只读）只在"确实有话要说"时做：常态不再枚举 ProcessThread，
            // 省掉每个采样周期的 StartTime/ThreadState 系统调用——本次 CPU 降负主项之一。
            var faultish = state.UnknownState || state.State is "FaultLocked" or "Suspended" or "Unknown";
            nextDelayMs = faultish ? RuntimeSampleBusyIntervalMs : RuntimeSampleNormalIntervalMs;
            // FAN-931 P1.2：只为**会落盘**的记录取数。日志门关闭且本次 CPU 未达归因阈值时，
            // 不再每 30 s 去取线程数（Toolhelp 快照）/工作集/私有内存/GC 与各证据对象——
            // 旧实现即使门关也照取，而那条记录本身注定不会被写。loop 维护（下方
            // StopHcControllerCpuLoops / DetectAbandonedDeviceOpen）与采样取数**解耦**，
            // 两个分支都照常执行（不得 early-return 掉维护责任）。
            var recordSample = diagnostics.IsRuntimeGateEnabled() ||
                cpuPercent is >= CpuThreadAttributionThresholdPercent;
            Interlocked.Increment(ref FanPerfCounters.RuntimeStatusReads);
            if (recordSample) Interlocked.Increment(ref FanPerfCounters.RuntimeSamplesRecorded);
            else Interlocked.Increment(ref FanPerfCounters.RuntimeSamplesSkipped);
            object[] hotThreads = [];
            object[] threadsAdded = [];
            var threadsRemovedCount = 0;
            if (recordSample)
            {
                var attributeThreads = cpuPercent is >= CpuThreadAttributionThresholdPercent;
                if (attributeThreads)
                {
                    (hotThreads, threadsAdded, threadsRemovedCount) = CollectThreadCpuAttribution(process);
                }
                diagnostics.Write("host.runtime-sample", new
                {
                    processId = process.Id,
                    processorCount = Environment.ProcessorCount,
                    cpuPercent,
                    cpuMsPerSec,
                    sampleCadenceMs = nextDelayMs,
                    threadsAttributed = attributeThreads,
                    intervalMs,
                    processCpuTimeMs = nowCpu.TotalMilliseconds,
                    workingSetBytes = process.WorkingSet64,
                    privateMemoryBytes = process.PrivateMemorySize64,
                    threadCount = process.Threads.Count,
                    gcHeapBytes = GC.GetTotalMemory(false),
                    temperatureMonitor = realBackend?.TemperatureMonitorDiagnostics,
                    profileWatchdog = realBackend?.PowerProfileWatchdogDiagnostics,
                    hotThreads,
                    threadsAdded,
                    threadsRemovedCount,
                    // P-3（2026-09-23 立案）：loop stop/reopen 记账随采样一起可见（事件式，
                    // 不新增写行）；真实 reopen→stop 周期见 hc.controller-cpu-loops-stopped。
                    hcLoopStopEvidence = realBackend?.HcLoopStopEvidenceForSelfTest,
                    // E-1（2026-09-24）：就绪等待读数随本高频采样带出（不算事件、不新增日志行）。
                    hcReadyWaitEvidence = realBackend?.HcReadyWaitEvidenceForSelfTest,
                });
                // 一眼可见的 CPU 检测（operator 要求：高频日志区加入风扇进程 CPU 占用检测）：
                // 超阈值即写一条 process 级告警，附最强线程归因（tid/startedAt/本区间 CPU），
                // 无需再翻样本逐条比对。阈值只在进程总占用 ≥3% 时触发。
                if (cpuPercent is >= CpuWarningThresholdPercent)
                {
                    diagnostics.Write("host.cpu-warning", new
                    {
                        cpuPercent,
                        cpuMsPerSec,
                        processorCount = Environment.ProcessorCount,
                        intervalMs,
                        sampleCadenceMs = nextDelayMs,
                        threadCount = process.Threads.Count,
                        state = state.State,
                        hotThreads,
                    });
                }
                // Dedicated, greppable evidence when this process is hot: search the
                // archive for `host.cpu-hot-threads` to see which threads burned CPU in
                // which interval, and match `startedAt` against the triggering action.
                if (cpuPercent is >= 4d)
                {
                    diagnostics.Write("host.cpu-hot-threads", new
                    {
                        cpuPercent,
                        intervalMs,
                        processorCount = Environment.ProcessorCount,
                        threadCount = process.Threads.Count,
                        hotThreads,
                        threadsAdded,
                        threadsRemovedCount,
                    });
                }
            }

            // F1' re-assert: HC can start a fresh device read loop when a device
            // event arrives after the open boundary (the test-machine capture
            // showed exactly that at the virtual-gamepad click). Re-checking on
            // this existing 5s timer is bounded, allocation-free and only writes
            // when a loop flag is actually found set.
            realBackend?.StopHcControllerCpuLoops("runtime-sample", state.PowerOperationGeneration, state.State, cpuMsPerSec);
            // 920-v1.4 §16.2：同一处再做**遗弃设备打开**的可达性判定（只诊断）。
            // 若命中，说明被放弃的 Device_Inserted 续体确实在新的会话边界之后仍然生效，
            // 这正是"旧操作是否干扰后续控制"的证据入口。
            realBackend?.DetectAbandonedDeviceOpen("runtime-sample");
            Interlocked.Increment(ref runtimeLoopMaintenanceRuns);
        }
        catch (Exception ex)
        {
            diagnostics.Write("host.runtime-sample-failure", new { error = ExceptionText(ex) });
        }
        finally
        {
            // 自复位节拍：本方法（含异常路径）是唯一重排入口（Timer 为一次性）。
            Interlocked.Exchange(ref runtimeSampleInFlight, 0);
            try { runtimeDiagnosticsTimer?.Change(nextDelayMs, Timeout.Infinite); } catch { }
        }
    }

    /**
     * 线程级 CPU 归因（只读）。**只在 CPU 超阈值时调用**：枚举本进程每个 OS 线程，
     * 给出本区间消耗最多的前 8 个（含线程起始时间，便于回指触发它的动作）。
     * 常态不再进入这里——`StartTime`/`ThreadState` 是系统调用，几千次/小时纯属开销。
     */
    private (object[] HotThreads, object[] ThreadsAdded, int ThreadsRemovedCount)
        CollectThreadCpuAttribution(Process process)
    {
        var currentIds = new HashSet<int>();
        var rows = new List<ThreadCpuRow>();
        foreach (ProcessThread thread in process.Threads)
        {
            int tid;
            double cpuMs;
            try
            {
                tid = thread.Id;
                cpuMs = thread.TotalProcessorTime.TotalMilliseconds;
            }
            catch
            {
                continue;
            }
            currentIds.Add(tid);
            var known = lastThreadCpuMs.TryGetValue(tid, out var previousCpuMs);
            var deltaMs = known ? Math.Max(0d, cpuMs - previousCpuMs) : 0d;
            lastThreadCpuMs[tid] = cpuMs;
            var startedAt = "unknown";
            try { startedAt = thread.StartTime.ToString("HH:mm:ss.fff"); } catch { }
            var stateText = "unknown";
            try { stateText = thread.ThreadState.ToString(); } catch { }
            rows.Add(new ThreadCpuRow(tid, Math.Round(deltaMs, 1), Math.Round(cpuMs, 1), startedAt, stateText, !known));
        }
        var hotThreads = rows
            .OrderByDescending(row => row.DeltaMs)
            .Take(8)
            .Select(row => (object)new
            {
                tid = row.Tid,
                cpuDeltaMs = row.DeltaMs,
                cpuTotalMs = row.TotalMs,
                startedAt = row.StartedAt,
                state = row.State,
            })
            .ToArray();
        var threadsAdded = rows
            .Where(row => row.IsNew)
            .Take(12)
            .Select(row => (object)new { tid = row.Tid, startedAt = row.StartedAt, state = row.State })
            .ToArray();
        var threadsRemovedCount = lastThreadIds.Count(id => !currentIds.Contains(id));
        lastThreadIds = currentIds;
        if (lastThreadCpuMs.Count > 256)
        {
            var live = lastThreadCpuMs.Where(kv => currentIds.Contains(kv.Key)).ToList();
            lastThreadCpuMs.Clear();
            foreach (var kv in live) lastThreadCpuMs[kv.Key] = kv.Value;
        }
        return (hotThreads, threadsAdded, threadsRemovedCount);
    }

    private object BuildDiagnosticContext()
    {
        // FAN-931 P0：只统计"确实构造了完整上下文"的次数（轻量事件已在上游跳过）。
        Interlocked.Increment(ref FanPerfCounters.DiagnosticContextBuilds);
        var route = realBackend?.Route;
        return new
        {
            state.State,
            state.PowerState,
            state.HostMode,
            state.ProtocolVersion,
            hardwareCapable = state.HardwareCapable,
            hardwareWriteAuthorizationGranted = state.HardwareWriteAuthorizationGranted,
            hardwareWritesEnabled = !options.MockZeroHardwareEvidence && state.HardwareWritesEnabled,
            hardwareWritesObserved = !options.MockZeroHardwareEvidence && state.HardwareWritesObserved,
            mockZeroHardwareEvidence = options.MockZeroHardwareEvidence,
            mockControlEnabled = options.MockZeroHardwareEvidence && state.HardwareWritesEnabled && state.Lease is not null && activeCurve is not null,
            mockWritesObserved = options.MockZeroHardwareEvidence && state.HardwareWritesObserved,
            mockControlSequence = state.MockControlSequence,
            oemRestoreConfirmed = state.OemRestoreConfirmed,
            hcRestoreCallbackReturned = state.HcRestoreCallbackReturned,
            oemRestoreEvidence = state.OemRestoreEvidence,
            oemOwnershipStatus = state.OemOwnershipStatus,
            oemPhysicalOwnershipConfirmed = state.OemPhysicalOwnershipConfirmed,
            hcCloseCleanupPending = state.HcCloseCleanupPending,
            hcVirtualCloseReturned = state.HcVirtualCloseReturned,
            hcDeviceManagerStopCompleted = state.HcDeviceManagerStopCompleted,
            hcDeviceManagerStopInvoked = state.HcDeviceManagerStopInvoked,
            hcManagerCleanupEvidence = state.HcManagerCleanupEvidence,
            hcDeviceManagerLifecycle = state.HcDeviceManagerLifecycle,
            hcManagerFactoryLifecycle = realBackend?.HcManagerFactoryLifecycle ?? state.HcManagerFactoryLifecycle,
            unknownState = state.UnknownState,
            factoryType = state.FactoryType,
            fanRoute = state.FanRoute,
            fanRouteCount = RealHcBackend.KnownFanRouteCount,
            fanRouteWriteReady = state.FanRouteWriteReady,
            routeKind = route?.Kind.ToString(),
            routeDescription = route?.Description,
            restoreStrategy = route?.RestoreStrategy.ToString(),
            routeHcCallbackReady = route?.HcCallbackReady,
            routeWriteReadyByDefault = route?.WriteReadyByDefault,
            deviceIdentity = state.DeviceIdentity,
            ecEvidence = state.EcEvidence,
            controllerFirmwareEvidence = state.ControllerFirmwareEvidence,
            openCalled = state.OpenCalled,
            openEventsCalled = state.OpenEventsCalled,
            hcManagerFactoryStarted = realBackend?.HcManagerFactoryStarted ?? state.HcManagerFactoryStarted,
            hcManagerFactoryIsolated = realBackend?.HcManagerFactoryIsolated ?? state.HcManagerFactoryIsolated,
            hcManagerStatuses = realBackend?.ManagerStatusSnapshot() ?? state.HcManagerStatuses,
            hcOpenEventsInvoked = realBackend?.HcOpenEventsInvoked ?? false,
            hcOperationPhase = realBackend?.CurrentHcPhase ?? state.HcOperationPhase,
            profilePowerLineOnline = realBackend?.ProfilePowerLineOnline,
            profileSelectionSource = realBackend?.ProfileSelectionSource,
            profileTemplateFingerprint = realBackend?.ProfileTemplateFingerprint,
            lastUpdateSource = realBackend?.LastUpdateSource ?? state.LastUpdateSource,
            externalProfileEventsSubscribed = realBackend?.ExternalProfileEventsSubscribed,
            lastExternalProfileSource = realBackend?.LastExternalProfileSource,
            hcEventMode = state.HcEventMode,
            leaseActive = state.Lease is not null,
            leaseGeneration = state.LeaseGeneration,
            lastTemperatureC = state.LastTemperatureC,
            currentDutyPercent = state.CurrentDutyPercent,
            temperatureSource = realBackend?.TemperatureMonitorActive == true ? "HW.HWiNFO.shared-memory" : "none",
            temperatureSourceContract = options.RealBackend
                ? "HW.HWiNFO.shared-memory(route-gated; GenericDuty/GenericRpmTarget only)"
                : "none",
            temperatureMonitor = realBackend?.TemperatureMonitorDiagnostics,
            profileWatchdog = realBackend?.PowerProfileWatchdogDiagnostics,
            activeCurve = state.ActiveCurve?.Select(node => new { node.TempC, node.DutyPercent }).ToArray(),
            lastError = state.LastError,
            recoveryReadbackRequired = state.RecoveryReadbackRequired,
            // FAN-925 T0-X：故障周期账目（剩余预算 / 已用尝试 / 自动更换次数 / 终态）
            // 必须与"状态变化原因"一起导出，不能被旧 Ready 掩盖。
            recoveryCycle = recoveryCycle is null ? null : new
            {
                cycleId = recoveryCycle.CycleId,
                inherited = recoveryCycleInherited,
                parentPid = recoveryCycle.ParentPid,
                attempts = recoveryCycle.Attempts,
                maxAttempts = RecoveryRetryMaxAttempt,
                replacements = recoveryCycle.Replacements,
                remainingMs = RemainingRecoveryCycleMs(recoveryCycle),
                terminal = recoveryCycle.Terminal,
                completed = recoveryCycle.Completed,
                startedAtUtc = recoveryCycle.StartedAtUtc,
                lastReason = recoveryCycle.LastReason,
            },
            // FAN-925 / HC 回函 D1–D3：不可宣称项一律显式字段（导出可直接断言）。
            recoveryClaimEvidence = RecoveryClaimEvidence(),
        };
    }

    private void OnTimedOutHcOperationReturned(bool operationSucceeded)
    {
        lock (gate)
        {
            if (stopped) return;
            var backend = realBackend;
            if (backend is null) return;
            // The STA call can return after the 15-second bound either
            // normally or with an exception. Only the former is a completed
            // HC lifecycle boundary. In particular, a Close() exception
            // after the Hardware callback must not be reported as a safe
            // stopped state merely because OEM fan ownership was proven.
            // Fan-only ownership treats a returned CurrentDevice.Close() as
            // the local process-exit boundary. ManagerFactory shutdown is
            // owned by HC's full application, not this Host.
            var completedHcClose = backend.HcVirtualCloseReturned && backend.HcManagerCleanupConfirmed;
            if (operationSucceeded &&
                (completedHcClose || backend.OemRestoreVerified) &&
                !state.HardwareWritesEnabled)
            {
                state.OemRestoreEvidence = backend.OemRestoreEvidence;
                state.OemOwnershipStatus = backend.OemOwnershipStatus;
                state.OemPhysicalOwnershipConfirmed = string.Equals(
                    backend.OemOwnershipStatus,
                    "hc-default-table-readback-confirmed",
                    StringComparison.Ordinal);
                // HC's Hardware callback return is the release boundary.
                // ASUS curve readback is optional diagnostic evidence only.
                state.OemRestoreConfirmed = backend.OemRestoreVerified;
                state.HcRestoreCallbackReturned = backend.OemRestoreVerified;
                state.HcVirtualCloseReturned = backend.HcVirtualCloseReturned;
                state.HcDeviceManagerStopCompleted = backend.HcDeviceManagerStopCompleted;
                state.HcDeviceManagerStopInvoked = backend.HcDeviceManagerStopInvoked;
                state.HcManagerCleanupEvidence = backend.HcManagerCleanupEvidence;
                state.HcDeviceManagerLifecycle = backend.HcDeviceManagerLifecycle;
                state.HcManagerFactoryLifecycle = backend.HcManagerFactoryLifecycle;
                state.HcCloseCleanupPending = false;
                state.UnknownState = !IsOemReleaseSafe(
                    state.HardwareWritesObserved,
                    state.OemReleaseActionKind);
                state.RecoveryReadbackRequired = state.UnknownState;
                if (!backend.IsOpen)
                {
                    state.OpenCalled = false;
                    state.OpenEventsCalled = false;
                    if (state.PowerState is "Suspending" or "Suspended")
                    {
                        // HC's SystemPending path closes the device while
                        // keeping DeviceManager alive (SuspendWithOS=false).
                        // Once the bounded Close returns, complete the sleep
                        // boundary so resume can recreate Open/OpenEvents.
                        state.PowerState = "Suspended";
                        state.State = "Suspended";
                    }
                    else if (state.CloseCalled)
                    {
                        if (state.UnknownState)
                        {
                            state.State = "FaultLocked";
                            state.PowerState = "Unknown";
                            ScheduleRecoveryRetry();
                        }
                        else
                        {
                            ClearLease();
                            state.State = "Stopped";
                            stopped = true;
                        }
                    }
                    else if (state.State == "FaultLocked" || state.State == "AwaitingCloseCleanup")
                        state.State = state.UnknownState ? "FaultLocked" : "AwaitingControl";
                }
                else if (state.State == "FaultLocked" || state.State == "AwaitingCloseCleanup")
                    state.State = state.UnknownState
                        ? "FaultLocked"
                        : (state.CloseCalled ? "AwaitingCloseCleanup" : "AwaitingControl");
                state.LastError = state.UnknownState
                    ? "HC 调用已返回，但物理 OEM 所有权未确认"
                    : null;
                diagnostics.Write("hc.timeout-returned-after-completed-boundary", new
                {
                    operationSucceeded,
                    backendIsOpen = backend.IsOpen,
                    completedHcClose,
                    hardwareCallbackReturned = backend.OemRestoreVerified,
                    state = state.State,
                });
                if (state.CloseCalled && state.PowerState != "Suspended" && !stopped)
                    ScheduleRecoveryRetry();
                return;
            }
            if (!operationSucceeded && state.OemRestoreConfirmed && !state.HardwareWritesEnabled)
            {
                // The fan handoff is proven, but HC resource disposal failed.
                // Keep the admission flags and resident endpoint so the next
                // retry invokes the real virtual Close() again; never clear
                // them and never turn this into a successful shutdown.
                state.HcCloseCleanupPending = true;
                state.UnknownState = false;
                state.LastError = "HC_CLOSE_CLEANUP_FAILED: HC Close 调用已返回异常，OEM 已确认但资源清理仍待重试";
                state.State = state.CloseCalled ? "AwaitingCloseCleanup" : "FaultLocked";
                diagnostics.Write("hc.timeout-returned-close-failure-after-oem-restore", new { state = state.State });
                ScheduleRecoveryRetry();
                return;
            }
            // A timeout never authorizes a new write. If the timed-out HC
            // operation had reached an open or observed-write session, retry
            // the existing OEM recovery only after its STA thread returned.
            // HardwareWritesObserved is an audit bit retained after a
            // successful OEM handoff. It must never turn a later, unrelated
            // timeout into a live hardware-session fault. Only current HC
            // admission, active software writes, pending HC cleanup, or an
            // already-unknown state can require recovery here.
            if (!HasLiveHardwareSession()) return;
            state.UnknownState = true;
            state.State = "FaultLocked";
            state.LastError = operationSucceeded
                ? "HC_OPERATION_TIMEOUT: HC 调用已返回，但 OEM 恢复证据不足"
                : "HC_OPERATION_TIMEOUT: HC 调用已返回异常，等待 OEM 恢复确认";
            diagnostics.Write("hc.timeout-returned", new { operationSucceeded, state = state.State });
            ScheduleRecoveryRetry();
        }
    }

    private void OnBackendFanDispatchFailure(Exception error)
    {
        lock (gate)
        {
            if (stopped) return;
            // The temperature/HID callback has already stopped the source and
            // blocked the next write.  Route loss must now use the same single
            // recovery owner as heartbeat: one HC Close/unbind, then the
            // bridge may observe AwaitingControl and rebuild on a stable route.
            // Do not leave this to the generic retry path, which would first
            // attempt an OEM callback against a device whose HID marker is
            // already gone.
            if (IsHcRouteLoss(error))
            {
                RecoverAfterHardwareFailure(error);
                return;
            }
            state.UnknownState = true;
            state.State = "FaultLocked";
            state.LastError = $"HC temperature dispatch failed: {ExceptionText(error)}";
            diagnostics.Write("hc.temperature-dispatch-failure", new { state = state.State, error = state.LastError });
            ScheduleRecoveryRetry();
        }
    }

    /**
     * The HW temperature reader is a YeMan isolation layer, not an HC route
     * acknowledgement.  A missing sample must stop software fan scheduling and
     * return the device to HC Hardware mode, but a successful return remains a
     * normal resumable state rather than a fabricated route conflict/lock.
     */
    private void OnBackendTemperatureMonitorStale()
    {
        lock (gate)
        {
            if (stopped || !state.HardwareWritesEnabled) return;
            diagnostics.Write("temperature.monitor-stale", new { state = state.State });
            if (RestoreHardware(close: false))
            {
                state.State = "Ready";
                state.UnknownState = false;
                state.LastError = "HC_TEMPERATURE_STALE: 温度采样暂停，已安全交还 OEM；可重新启用风扇控制";
                diagnostics.Write("temperature.monitor-stale-oem-restored", new { state = state.State });
                return;
            }

            state.UnknownState = true;
            state.State = "FaultLocked";
            state.LastError = "HC_TEMPERATURE_STALE: 温度采样暂停且 OEM 恢复未确认";
            diagnostics.Write("temperature.monitor-stale-oem-restore-failed", new { state = state.State });
            ScheduleRecoveryRetry();
        }
    }

    internal void MarkOperationTimeoutForSelfTest()
    {
        lock (gate)
        {
            state.UnknownState = true;
            state.State = "FaultLocked";
            state.LastError = "HC_OPERATION_TIMEOUT";
        }
    }

    internal void MarkTransportFault(Exception error)
    {
        lock (gate)
        {
            // HardwareWritesObserved is deliberately historical for audit
            // evidence. HC's current ownership boundary is represented by the
            // live Open/write/cleanup state, never by a previous curve write.
            state.UnknownState = HasLiveHardwareSession();
            state.State = state.UnknownState ? "FaultLocked" : "AwaitingControl";
            state.LastError = $"HOST_TRANSPORT_FAULT: {ExceptionText(error)}";
            if (state.UnknownState) ScheduleRecoveryRetry();
        }
    }

    internal void MarkListenerReady()
    {
        lock (gate)
        {
            if (state.ListenerState != "ListenerFaultLocked")
                state.ListenerState = "Listening";
        }
    }

    internal void MarkListenerFaultLocked(Exception error)
    {
        lock (gate)
        {
            state.ListenerState = "ListenerFaultLocked";
            state.LastError = $"LISTENER_FAULT_LOCKED: {ExceptionText(error)}";
            if (!stopped)
                state.State = "ListenerFaultLocked";
            diagnostics.Write("listener.fault-locked", new
            {
                state = state.State,
                error = state.LastError,
                hardwareWritesEnabled = state.HardwareWritesEnabled,
                hardwareWritesObserved = state.HardwareWritesObserved,
            });
        }
    }

    internal bool ParentExitHandoffQueuedForSelfTest => Volatile.Read(ref parentExitHandoffQueued) != 0;
    internal int CloseEntryCountForSelfTest => Volatile.Read(ref closeEntryCount);

    private bool HasLiveHardwareSession()
    {
        return state.UnknownState || state.OpenCalled || state.HardwareWritesEnabled ||
            state.HcCloseCleanupPending || (realBackend?.IsOpen ?? false) ||
            (realBackend?.OpenAttempted ?? false);
    }

    internal static bool HasLiveHardwareSessionForSelfTest(
        bool unknownState,
        bool openCalled,
        bool writesEnabled,
        bool closeCleanupPending,
        bool backendOpen,
        bool openAttempted,
        bool writesObserved)
    {
        // The final parameter is intentionally ignored: it is the historical
        // audit bit whose presence must not imply current HC ownership.
        return unknownState || openCalled || writesEnabled || closeCleanupPending || backendOpen || openAttempted;
    }

    public HostState Snapshot()
    {
        lock (gate)
        {
            var snapshot = JsonSerializer.Deserialize<HostState>(JsonSerializer.Serialize(state, JsonDefaults.Options), JsonDefaults.Options)!;
            ApplyDerivedSnapshotFields(snapshot);
            return snapshot;
        }
    }

    /**
     * FAN-204 Q1-b（2026-09-23 裁决）：**读路径快照**——不等待 gate、不调用 HC。
     * - `Monitor.TryEnter(gate, 0)` 成功：现取新鲜快照（同一个 gate 内的深拷贝，并顺带发布，
     *   让后续等锁的读者拿到的是"最后已知真值"）；
     * - 拿不到锁（HC 长操作持锁，例如真机 10.22 s 的设备打开就绪等待）：返回最近一次已发布
     *   快照（整体替换 ⇒ 读者不会看到逐字段半更新；阶段可能是 Resuming 或上次安全态，
     *   **绝不伪造 Ready**）；
     * - 仅 `--mock-no-published-snapshot`（mock）时退回阻塞读，供 AC15c 负例证明判定非空转。
     */
    public HostState SnapshotForRead() => SnapshotForReadBounded(0);

    /**
     * FAN-204 Q1-b（2026-09-23 裁决）：**有界**读快照——给"必须看到同一代次收据才能判定"的
     * 读点用（如 /api/resume 的去重/未知分支：收据可能正在队列 worker 的动作里落位，纯非阻塞
     * 读会读到尚未含收据的旧发布快照而误报 expired）。最多等 timeoutMs 拿 gate（有界，绝不
     * 跟随 HC 长持有期——真机 10.22 s 的门内等待下，到期即返回已发布快照）。
     */
    internal HostState SnapshotForReadBounded(int timeoutMs)
    {
        if (publishedSnapshotDisabledForMock) return Snapshot();
        if (Monitor.TryEnter(gate, timeoutMs))
        {
            try { return PublishSnapshotLocked(); }
            finally { Monitor.Exit(gate); }
        }
        var published = Volatile.Read(ref lastPublishedSnapshot);
        return published ?? Snapshot();
    }

    /** gate 内调用：取新鲜深拷贝、**整体替换**发布、返回同一对象（发布后不再修改）。 */
    private HostState PublishSnapshotLocked(string? stateOverride = null)
    {
        var snapshot = JsonSerializer.Deserialize<HostState>(JsonSerializer.Serialize(state, JsonDefaults.Options), JsonDefaults.Options)!;
        // 先落阶段覆盖、再派生（否则 resumePhase/controlAccepting 会与覆盖后的 state 漂移）。
        if (stateOverride is not null) snapshot.State = stateOverride;
        ApplyDerivedSnapshotFields(snapshot);
        Interlocked.Exchange(ref lastPublishedSnapshot, snapshot);
        return snapshot;
    }

    /** 仅 mock（`--mock-no-published-snapshot`）：让读路径退回阻塞读，作为负例开关。 */
    internal void DisablePublishedSnapshotForMock() => publishedSnapshotDisabledForMock = true;

    /**
     * Q1/Q2（2026-09-23 补充裁决）：派生字段（恢复阶段/建议轮询间隔/控制可发送性/最近写入
     * 收据）的**唯一实现**。两个快照入口——公开 `Snapshot()`（API/调用方）与 gate 内
     * `SnapshotUnlocked()`（内部判定）——必须一致，否则 API 看到的阶段与内部判定会漂移。
     */
    private void ApplyDerivedSnapshotFields(HostState snapshot)
    {
        snapshot.ResumePhase = DeriveResumePhase(snapshot);
        snapshot.ResumePhaseGeneration = snapshot.PowerOperationGeneration;
        snapshot.ResumeRetryAfterMs = HostState.ResumePollRetryAfterMs;
        snapshot.ControlAccepting = IsControlAccepting(snapshot);
        snapshot.LastControlWriteEvidence = realBackend?.LastControlWriteEvidence ?? "none";
        if (options.MockZeroHardwareEvidence)
        {
            // Engine retains logical mock flags for existing lifecycle/restore
            // semantics. Only the exported physical evidence is separated.
            if (!options.MockHandshake || realBackend is not null) throw new InvalidOperationException("MOCK_BACKEND_INVARIANT");
            snapshot.MockZeroHardwareEvidence = true;
            snapshot.MockControlEnabled = state.HardwareWritesEnabled && state.Lease is not null && activeCurve is not null;
            snapshot.MockWritesObserved = state.HardwareWritesObserved;
            snapshot.MockControlSequence = state.MockControlSequence;
            snapshot.MockCloseCompleted = stopped && state.State == "Stopped" && state.CloseCalled && !state.OpenCalled && !state.OpenEventsCalled && state.Lease is null;
            // No OEM/EC physical ownership was observed in a null-backend mock.
            snapshot.OemPhysicalOwnershipConfirmed = false;
            snapshot.HardwareWritesEnabled = false;
            snapshot.HardwareWritesObserved = false;
        }
    }

    // Test-only in-process fault injection used by --self-test. It never has
    // an HTTP route and lets the safe build prove that an uncertain hardware
    // state cannot be turned into a successful stopped result.
    internal void InjectUncertainStateForSelfTest()
    {
        lock (gate)
        {
            state.OpenCalled = true;
            state.HardwareWritesObserved = true;
            state.OemRestoreConfirmed = false;
            state.HcRestoreCallbackReturned = false;
        }
    }

    internal void ResolveUncertainStateForSelfTest()
    {
        lock (gate)
        {
            // The safe fault injector models a returned HC Close boundary.
            // Clear the virtual session markers as the real Close path does;
            // otherwise the parent-recovery oracle could never prove that
            // CurrentDevice.Close had completed and would intentionally keep
            // the listener resident forever.
            state.OpenCalled = false;
            state.OpenEventsCalled = false;
            state.HardwareWritesObserved = false;
            state.UnknownState = false;
            state.LastError = null;
        }
    }

    /** 920-v1.6 §18：把生产 backend 暴露给自测组（只读引用，不改变引擎行为）。 */
    internal RealHcBackend? RealBackendForSelfTest => realBackend;

    /**
     * 920-v1.6 §18：给一个有效期内的 lease（不写硬件），使**生产** Enable/Restore 入口
     * 可被无硬件联调驱动（与既有 *ForSelfTest 的 lease 夹具同构）。
     */
    internal void GrantSelfTestLeaseForSelfTest(string leaseId)
    {
        lock (gate)
        {
            state.Lease = new FanLease(leaseId, ++generation, MonoMs() + 60000, "selftest");
        }
    }

    /**
     * R1（FAN-926R 裁决 §3.2.5/§3.2.6）自测：把当前租约置为**已到期**并触发它**自己**的
     * 到期回调——等价于真实 15 s TTL 到期。用于证明"普通客户端租约真正到期仍执行原有
     * 安全策略（交还默认模式 + 落 AwaitingControl）"，以及迟到/异身份回调不得处置新租约。
     */
    internal void ExpireCurrentLeaseForSelfTest()
    {
        string leaseId;
        long leaseGeneration;
        lock (gate)
        {
            if (state.Lease is null) return;
            leaseId = state.Lease.LeaseId;
            leaseGeneration = state.Lease.Generation;
            state.Lease = state.Lease with { ExpiresAtMonoMs = MonoMs() - 1 };
        }
        ExpireLease(leaseId, leaseGeneration);
    }

    /** R1 自测：以**不匹配**的身份触发到期回调（模拟被 Dispose 前排队的迟到回调）。 */
    internal void ExpireLeaseWithStaleIdentityForSelfTest() =>
        ExpireLease("stale-lease-identity-selftest", 0);

    internal bool VerifyLeaseExclusivityForSelfTest()
    {
        lock (gate)
        {
            state.Lease = new FanLease("selftest-owner", ++generation, MonoMs() + 15000, "selftest");
            try { _ = AcquireControl(); return false; }
            catch (FanApiException ex) when (ex.Code == "LEASE_HELD") { return true; }
            finally { ClearLease(); }
        }
    }

    internal bool VerifyPresetLeasePropagationForSelfTest()
    {
        lock (gate)
        {
            state.Lease = new FanLease("preset-selftest", ++generation, MonoMs() + 15000, "selftest");
            using var body = JsonDocument.Parse(JsonSerializer.Serialize(new
            {
                name = "balanced",
                leaseId = "preset-selftest",
            }, JsonDefaults.Options));
            try
            {
                _ = Preset(body.RootElement);
                return false;
            }
            catch (FanApiException ex) when (ex.Code == "FAN_UNSUPPORTED")
            {
                // The safe engine must reach its hardware-disabled gate only
                // after the preset lease has been accepted. Before the fix it
                // stopped earlier with LEASE_REQUIRED; FAN_UNSUPPORTED is the
                // expected next gate for a safe/no-hardware engine.
                return true;
            }
            finally { ClearLease(); }
        }
    }

    internal bool VerifyExpiredLeaseDoesNotBlockSafetyRestoreForSelfTest()
    {
        lock (gate)
        {
            state.Lease = new FanLease("expired-selftest", ++generation, MonoMs() - 1, "selftest");
            state.OpenCalled = false;
            state.HardwareWritesObserved = false;
            try
            {
                using var body = JsonDocument.Parse("{\"leaseId\":\"expired-selftest\"}");
                var restored = Restore(body.RootElement);
                // The safe/no-hardware engine must not fabricate physical OEM
                // confirmation. Its contract is that expired ownership cannot
                // block a safe cleanup and no write/unknown state remains.
                return restored is HostState snapshot && !snapshot.HardwareWritesEnabled &&
                    !snapshot.UnknownState && state.Lease is not null;
            }
            catch { return false; }
            finally { ClearLease(); }
        }
    }

    internal bool VerifyExpiredLeaseReleaseAfterRestoreForSelfTest()
    {
        lock (gate)
        {
            state.Lease = new FanLease("expired-release-selftest", ++generation, MonoMs() - 1, "selftest");
            state.OpenCalled = false;
            state.HardwareWritesObserved = false;
            try
            {
                using var body = JsonDocument.Parse("{\"leaseId\":\"expired-release-selftest\"}");
                var released = Release(body.RootElement);
                return released is HostState snapshot && !snapshot.HardwareWritesEnabled &&
                    !snapshot.UnknownState && state.Lease is null &&
                    state.State == "AwaitingControl";
            }
            catch { return false; }
            finally { ClearLease(); }
        }
    }

    public object Handshake()
    {
        lock (gate)
        {
            if (MockFanHandshakeFlag)
            {
                // MOCK 伪装握手（2026-09-15 用户需求，原创测试设施，HC 无对应）：
                // 伪装 HC 风扇设备就绪（XboxROGAlly 类 + EC 可写 fanRoute），
                // realBackend 保持 null（safe 模式）→ 后续 Open/OpenEvents/
                // RestoreHardware 走无后端路径，零 EC 写入。
                state.HardwareCapable = true;
                state.HardwareWriteAuthorizationGranted = true;
                // The AI-only handshake is read-only on an existing mock
                // control session. Legacy mock semantics remain unchanged.
                if (!options.MockZeroHardwareEvidence || state.HostMode != "mock-handshake")
                {
                    state.HardwareWritesEnabled = false;
                    state.HardwareWritesObserved = false;
                }
                state.FactoryType = "HandheldCompanion.Devices.XboxROGAlly";
                state.FanRoute = "EC";
                state.FanRouteWriteReady = true;
                state.DeviceIdentity = new Dictionary<string, string>
                {
                    ["manufacturer"] = "mock", ["model"] = "mock-fan",
                    ["product"] = "mock", ["bios"] = "mock",
                };
                state.EcEvidence = null;
                state.ControllerFirmwareEvidence = null;
                state.HostMode = "mock-handshake";
                state.LastError = null;
                if (options.MockZeroHardwareEvidence) PublishSnapshotLocked();
                return new
                {
                    ok = true,
                    supported = true,
                    protocolVersion = 2,
                    hostMode = state.HostMode,
                    mockZeroHardwareEvidence = options.MockZeroHardwareEvidence,
                    hardwareCapable = true,
                    hardwareWritesEnabled = false,
                    hardwareWritesObserved = false,
                    deviceClass = "HandheldCompanion.Devices.XboxROGAlly",
                    fanRoute = "EC",
                    fanRouteCount = RealHcBackend.KnownFanRouteCount,
                    fanRouteWriteReady = true,
                    recoveryReadbackRequired = false,
                    deviceIdentity = state.DeviceIdentity,
                    reason = "MOCK：伪装风扇设备就绪（完整生命周期测试，零硬件写入）",
                };
            }
            if (realBackend is not null)
            {
                // Handshake is a read-only capability probe.  It may be
                // repeated when the listener is rebuilt, when the UI returns
                // to the Fan page, or after resume.  Never let that probe
                // erase evidence belonging to an already-open HC session:
                // clearing these bits here makes native /api/close and
                // /api/parent-exit believe the firmware is idle while the
                // HC/ACPI/HID session is still alive.
                var liveSessionBeforeHandshake = HasLiveHardwareSession();
                try
                {
                    var handshake = realBackend.LoadAndHandshake();
                    state.HardwareCapable = handshake.HardwareCapable;
                    state.HardwareWriteAuthorizationGranted = handshake.HardwareWriteAuthorizationGranted;
                    if (!liveSessionBeforeHandshake)
                    {
                        state.HardwareWritesEnabled = false;
                        state.HardwareWritesObserved = false;
                    }
                    state.OemRestoreEvidence = realBackend.OemRestoreEvidence;
                    state.FactoryType = handshake.FactoryType;
                    state.FanRoute = handshake.FanRoute;
                    state.FanRouteWriteReady = handshake.HardwareWriteAuthorizationGranted;
                    state.DeviceIdentity = handshake.DeviceIdentity;
                    state.EcEvidence = handshake.EcEvidence;
                    state.ControllerFirmwareEvidence = handshake.ControllerFirmwareEvidence;
                    state.HcManagerFactoryStarted = realBackend.HcManagerFactoryStarted;
                    state.HcManagerFactoryIsolated = realBackend.HcManagerFactoryIsolated;
                    state.HcManagerFactoryLifecycle = realBackend.HcManagerFactoryLifecycle;
                    state.HcEventMode = "hc-native-lifecycle";
                    state.HostMode = handshake.Supported && realBackend.CanWrite ? "real-hc-authorized" : "real-hc-read-only";
                    // A successful metadata probe must not erase a pending
                    // close/restore diagnostic from an active or faulted
                    // session.  Only a genuinely idle handshake clears the
                    // previous error.
                    if (!liveSessionBeforeHandshake) state.LastError = null;
                    return new
                    {
                        ok = true,
                        supported = handshake.Supported,
                        protocolVersion = 2,
                        hostMode = state.HostMode,
                        hardwareCapable = true,
                        // Return the current session evidence, not a fresh
                        // handshake default.  A repeated probe during an
                        // active curve must remain truthful to native exit
                        // safety and the UI telemetry.
                        hardwareWritesEnabled = state.HardwareWritesEnabled,
                        hardwareWritesObserved = state.HardwareWritesObserved,
                        deviceClass = handshake.FactoryType,
                        fanRoute = handshake.FanRoute,
                        fanRouteCount = RealHcBackend.KnownFanRouteCount,
                        fanRouteWriteReady = handshake.HardwareWriteAuthorizationGranted,
                        hcManagerFactoryStarted = realBackend.HcManagerFactoryStarted,
                        hcManagerFactoryIsolated = realBackend.HcManagerFactoryIsolated,
                        hcManagerFactoryLifecycle = realBackend.HcManagerFactoryLifecycle,
                        hcManagerStatuses = realBackend.ManagerStatusSnapshot(),
                        hcOpenEventsInvoked = realBackend.HcOpenEventsInvoked,
                        hcEventMode = "hc-native-lifecycle",
                        recoveryReadbackRequired = true,
                        deviceIdentity = handshake.DeviceIdentity,
                        ecEvidence = handshake.EcEvidence,
                        controllerFirmwareEvidence = handshake.ControllerFirmwareEvidence,
                        reason = handshake.Reason,
                    };
                }
                catch (Exception ex)
                {
                    // A first handshake can fail before HC Open() has ever
                    // touched the device (desktop System.Management limits,
                    // missing optional dependency, or an unsupported host).
                    // That is an unavailable/read-only environment, not an
                    // uncertain hardware session and must not be over-locked.
                    var hardwareSessionActive = liveSessionBeforeHandshake || HasLiveHardwareSession();
                    state.HardwareCapable = false;
                    state.HardwareWriteAuthorizationGranted = false;
                    if (!hardwareSessionActive)
                    {
                        state.HardwareWritesEnabled = false;
                        state.HardwareWritesObserved = false;
                    }
                    state.HostMode = hardwareSessionActive ? "real-hc-fault-locked" : "real-hc-unavailable";
                    if (!hardwareSessionActive)
                    {
                        state.FanRoute = null;
                        state.FanRouteWriteReady = false;
                        state.EcEvidence = null;
                        state.ControllerFirmwareEvidence = null;
                    }
                    state.LastError = ExceptionText(ex);
                    if (hardwareSessionActive)
                    {
                        // A failed re-probe cannot cancel an HC operation or
                        // turn an active session into a safe idle state. Keep
                        // the listener resident and send it through the same
                        // serialized recovery path as a failed lease/close.
                        state.UnknownState = true;
                        state.State = "FaultLocked";
                        ScheduleRecoveryRetry();
                    }
                    return new
                    {
                        ok = !hardwareSessionActive,
                        supported = false,
                        protocolVersion = 2,
                        hostMode = state.HostMode,
                        hardwareCapable = false,
                        hardwareWritesEnabled = state.HardwareWritesEnabled,
                        hardwareWritesObserved = state.HardwareWritesObserved,
                        fanRoute = (string?)null,
                        fanRouteCount = RealHcBackend.KnownFanRouteCount,
                        ecEvidence = state.EcEvidence,
                        controllerFirmwareEvidence = state.ControllerFirmwareEvidence,
                        recoveryReadbackRequired = true,
                        reason = state.LastError,
                    };
                }
            }
            return new
            {
                ok = true,
                supported = false,
                protocolVersion = 2,
                hostMode = state.HostMode,
                hardwareCapable = state.HardwareCapable,
                hardwareWritesEnabled = state.HardwareWritesEnabled,
                hardwareWritesObserved = state.HardwareWritesObserved,
                deviceClass = state.FactoryType,
                deviceIdentity = state.DeviceIdentity,
                fanRoute = state.FanRoute,
                fanRouteCount = RealHcBackend.KnownFanRouteCount,
                ecEvidence = state.EcEvidence,
                controllerFirmwareEvidence = state.ControllerFirmwareEvidence,
                reason = "当前 Host 为安全桌面构建：未加载 HC，风扇不支持",
            };
        }
    }

    public object Open()
    {
        lock (gate)
        {
            EnsureNotStopped();
            EnsureControlAvailable();
            if (state.HardwareWritesEnabled || state.Lease is not null)
                throw new FanApiException(409, "HC_SESSION_ACTIVE", "当前 HC 风扇会话仍在控制中，禁止重复 Open");
            // FAN-204 Q1-b（2026-09-23 真机 20:26 取证）：**仅沙箱**——真机的 HC 设备打开
            // 就绪等待（实测 10.22 s）发生在**唤醒自动重建**里的这把 `gate` 之内，期间所有读
            // 请求（/api/state、/health、接受响应的快照、诊断行）都被排队。这里如实复现同一
            // 持有期（仅在 `automaticResumeInProgress` 时生效，与真机同形：普通 /api/open 不受影响），
            // 供 api_contract AC15c 判定"过渡期是否仍可判定"。生产（无 --mock-handshake）恒 0。
            // 裁决要求：长 HC 操作开始前在 gate 内发布**阶段快照**——恢复中显式发布 "Resuming"，
            // 非恢复路径不覆盖（发布当前真值），读者据此在持锁期间得到可判定答复且**不伪造 Ready/Open**。
            PublishSnapshotLocked(automaticResumeInProgress ? "Resuming" : null);
            var mockHcOpenHoldMs = (options.MockHandshake && automaticResumeInProgress) ? options.MockHcOpenHoldMs : 0;
            if (mockHcOpenHoldMs > 0) Thread.Sleep(mockHcOpenHoldMs);
            if (realBackend is not null)
            {
                EnsureRealSupported();
                // FAN-936 §5：进入新的 HC 会话即开启**新的控制周期**。基线（以及 profile 模板）
                // 只绑定本周期；上一周期/上一实例/上一次开机的快照不得再被消费。
                realBackend.ControlCycleId++;
                // Mark the session before invoking HC. If HC throws after
                // touching EC/ACPI, close/recovery must remain fail-closed
                // instead of treating the partially-open call as harmless.
                state.OpenCalled = true;
                state.OpenEventsCalled = false;
                // Open begins a new HC device session. A prior Hardware
                // profile acknowledgement belongs to the previous session
                // and must not let a failed/partial Open skip OEM restore.
                state.OemRestoreConfirmed = false;
                state.HcRestoreCallbackReturned = false;
                state.OemRestoreEvidence = "none";
                state.OemOwnershipStatus = "unknown-no-hc-contract";
                state.OemPhysicalOwnershipConfirmed = false;
                state.HcVirtualCloseReturned = false;
                state.HcDeviceManagerStopCompleted = false;
                state.HcDeviceManagerLifecycle = "Unknown";
                state.HcManagerFactoryLifecycle = "Unknown";
                state.HcCloseCleanupPending = false;
                try
                {
                    realBackend.Open();
                }
                catch (Exception ex)
                {
                    // HC's normal startup treats a failed Open() as a
                    // non-session and does not manufacture a Close/release
                    // callback. The backend clears OpenAttempted when its
                    // virtual Open() never established IsOpen. Only a
                    // session that survived Open() may enter recovery.
                    if (realBackend.IsOpen || realBackend.OpenAttempted)
                        RecoverAfterHardwareFailure(ex);
                    else
                    {
                        state.OpenCalled = false;
                        state.OpenEventsCalled = false;
                        state.State = "AwaitingControl";
                        state.LastError = ExceptionText(ex);
                    }
                    throw;
                }
            }
            state.OpenCalled = true;
            state.State = automaticResumeInProgress ? "Resuming" : "Open";
            return SnapshotUnlocked();
        }
    }

    public object OpenEvents()
    {
        // FAN-204 §31 R4（阶段 2）：用户控制端点过渡期统一快速拒绝（无锁、无 HC、无 lease 变更）。
        RejectUserControlDuringTransitionLockFree("open-events");
        lock (gate)
        {
            EnsureNotStopped();
            EnsureControlAvailable();
            // §17.1-2（仅自测）：在**同一个 gate 内**、**生产调用点**复现"三阶段设备打开
            // 有界等待"的持有期。生产构建不会设置该值（默认 0），行为不变。
            var gateHoldSelfTestMs = Volatile.Read(ref this.gateHoldSelfTestMs);
            if (gateHoldSelfTestMs > 0)
            {
                // FAN-204 Q1-b：持锁期间读路径必须仍可判定 ⇒ 先发布阶段快照再持锁等待
                // （恢复中报"Resuming"；非恢复不覆盖——发布当前真值，绝不预宣告"Open/Ready"）。
                PublishSnapshotLocked(automaticResumeInProgress ? "Resuming" : null);
                Thread.Sleep(gateHoldSelfTestMs);
            }
            if (realBackend is not null)
            {
                try
                {
                    EnsureRealSupported();
                    realBackend.OpenEvents();
                }
                catch (Exception ex)
                {
                    RecoverAfterHardwareFailure(ex);
                    throw;
                }
            }
            state.OpenEventsCalled = true;
            state.State = automaticResumeInProgress ? "Resuming" : "Ready";
            return SnapshotUnlocked();
        }
    }

    public FanLease AcquireControl()
    {
        // FAN-204 §31 R4（阶段 2）：用户控制端点过渡期统一快速拒绝；恢复 worker 线程在判据内豁免。
        RejectUserControlDuringTransitionLockFree("acquire-control");
        lock (gate)
        {
            EnsureNotStopped();
            EnsureControlAvailable();
            if (realBackend is not null && (!state.OpenCalled || !state.OpenEventsCalled))
                throw new FanApiException(409, "HOST_EVENTS_NOT_OPEN", "HC OpenEvents 尚未完成，禁止申请风扇 lease");
            if (state.Lease is not null)
            {
                if (state.Lease.ExpiresAtMonoMs > MonoMs())
                    throw new FanApiException(409, "LEASE_HELD", "Fan lease 已被当前 owner 持有");
                // An expired lease is an ownership/profile boundary, not a
                // process or sleep boundary. HC hands fan ownership back by
                // applying its Hardware profile and keeps the device session
                // open for the resident app to acquire again.
                if (!RestoreHardware(close: false))
                {
                    state.State = "FaultLocked";
                    ScheduleRecoveryRetry();
                    throw new FanApiException(409, "OEM_RESTORE_FAILED", "旧 lease 已过期但 OEM restore 未确认");
                }
                ClearLease();
                state.State = "AwaitingControl";
            }
            try
            {
                // MOCK（2026-09-15）：伪装设备就绪，跳过 realBackend 能力门，
                // 直接授予 lease（safe 模式，零硬件写入）。
                if (MockFanHandshakeFlag) { /* mock: 能力门放行 */ }
                else if (realBackend is not null) EnsureRealSupported();
                else RejectUnsupported();
            }
            catch (Exception ex)
            {
                // Acquire is normally read-only, but it follows Open/OpenEvents
                // in the same HC session. If the route disappears between the
                // two calls, do not leave that partially-open session resident.
                if (state.OpenCalled) RecoverAfterHardwareFailure(ex);
                throw;
            }
            var now = MonoMs();
            var prefix = realBackend is null ? "safe" : "real";
            var lease = new FanLease($"{prefix}-{Guid.NewGuid():N}", ++generation, now + 15000, "YeManCC");
            state.Lease = lease;
            state.LeaseGeneration = lease.Generation;
            state.State = automaticResumeInProgress ? "Resuming" : "Ready";
            leaseTimer?.Dispose();
            // R1（§3.2.5）：到期回调必须能自证"我仍是创建它的**那一个**租约"。
            // 只 Dispose 定时器不算竞态证据——已经被 Dispose 前入队的回调用旧身份运行，
            // 由 ExpireLease 的身份核对拒绝，绝不撤销新客户端租约或改动新恢复周期。
            var timerLeaseId = lease.LeaseId;
            var timerLeaseGeneration = lease.Generation;
            leaseTimer = new Timer(_ => ExpireLease(timerLeaseId, timerLeaseGeneration), null, 15000, Timeout.Infinite);
            return lease;
        }
    }

    /**
     * FAN-204 Q1-c / HB-RESUME-BLOCKED（2026-09-24 裁决）：**heartbeat 取锁前快速判定**。
     *
     * 真机证据（01:09:51）：`POST /api/heartbeat` 在 HC `Open()` 持 gate ≈10.2 s 期间排队
     * `10009.35 ms` 后才返回 409 —— 足以表现为"唤醒后风扇暂时不可控"。裁决要求：不得靠延长
     * HTTP 超时掩盖，必须在 FanHost 内做**快速、结构化**的拒绝。
     *
     * 本判定只读两类**免门**事实：① 免门 volatile（`closeWriteBlocked`、`suspendProtection`、
     * `automaticResumeInProgress`、`automaticResumeWorkerThreadId`）；② 整体替换发布的不可变
     * `lastPublishedSnapshot`。因此：
     *   - **不等待 gate**（真机形态下不会被 HC 长操作挡住）；
     *   - **不调用 HC**（不碰 realBackend）；
     *   - **不延长旧 lease**（不改 `state.Lease`、不重排 leaseTimer）；
     *   - **不写曲线**、**不创建第二 owner**。
     *
     * 错误优先级与 `EnsureControlAvailable()` **逐条一致**（否则快速路径会把 FAULT_LOCKED /
     * POWER_SUSPENDING 误报成 POWER_RESUMING，掩盖真实原因）。判定不成立时返回 null，
     * 由原路径进 gate 走完整 lease 身份校验 + `VerifyActiveCurveSession()`。
     */
    private FanApiException? TryFastRejectHeartbeatLockFree()
    {
        if (Volatile.Read(ref closeWriteBlocked) != 0)
            return new FanApiException(409, "HOST_CLOSING", "Fan Host 正在关闭，禁止新的风扇接管");
        var published = Volatile.Read(ref lastPublishedSnapshot);
        // 快照缺失（构造后立刻来请求）⇒ 不猜：交给原路径进 gate 走权威判定。
        if (published is null) return null;
        if (published.UnknownState || published.State == "FaultLocked")
            return new FanApiException(409, "FAULT_LOCKED", "Fan Host 处于故障锁定，必须先确认 OEM restore");
        if (SuspendProtectionPending)
            return new FanApiException(409, "POWER_SUSPENDING", "系统正在进入睡眠，禁止新的风扇接管");
        if (published.HcCloseCleanupPending)
            return new FanApiException(409, "HC_CLOSE_PENDING", "HC 资源清理仍在完成，暂时禁止重新接管风扇");
        if (published.State == "Suspending" || published.PowerState == "Suspending")
            return new FanApiException(409, "POWER_SUSPENDING", "系统正在进入睡眠，禁止新的风扇接管");
        if (published.State == "Suspended" || published.PowerState == "Suspended")
            return new FanApiException(409, "POWER_SUSPENDED", "系统处于睡眠状态，禁止重新接管风扇");
        // 本批的唯一目标分支：Resuming（或电源操作 pending/executing）⇒ 立即结构化拒绝。
        // 恢复 worker 自己（同线程）不受此限，与 EnsureControlAvailable 的既有豁免一致。
        var resuming = published.State == "Resuming"
            || published.PowerState == "Resuming"
            || published.PowerOperationStatus is "pending" or "executing";
        if (!resuming) return null;
        if (Volatile.Read(ref automaticResumeWorkerThreadId) == Environment.CurrentManagedThreadId) return null;
        return new FanApiException(409, "POWER_RESUMING", "系统刚从睡眠恢复，HC 风扇会话正在重建");
    }

    /**
     * FAN-204 §31 R4（阶段 2，2026-09-24）：**用户控制端点统一快速拒绝**。
     *
     * 与 Heartbeat 共用**同一判据**（TryFastRejectHeartbeatLockFree：免门 volatile + 已发布快照，
     * 按 EnsureControlAvailable 的优先级逐条判定），本方法只补端点名与结构化附加字段并写一条
     * 事件级诊断。**不取任何 gate、不调 HC、不改 lease、不写曲线、不建第二 owner**。
     *
     * 豁免：恢复 worker 自身线程（判据内部已含 automaticResumeWorkerThreadId 判断）——worker 在
     * Resuming 期间会按序调用 Open/OpenEvents/AcquireControl/Enable 重建会话，该路径必须放行
     * （与 EnsureControlAvailable 的既有豁免一致）。
     *
     * 生命周期 owner 路径（suspend/resume/close/parent-exit）**不经过本方法**：继续由各自唯一
     * owner 串行处理，安全边界不变。**安全清理端点（disable/restore/release-control）也不接入**：
     * 源码合同明示其必须在租约失效/客户端崩溃后仍可达（见各方法注释），不得为"统一"而阻断 OEM 交还。
     */
    internal void RejectUserControlDuringTransitionLockFree(string operation)
    {
        // 负例开关（仅 mock，需 --mock-handshake）：`--mock-user-control-legacy-gate` 退回修复前的
        // "直接进 gate"行为，使 AC16 的快速判定断言失败 —— 证明统一判定不空转。
        if (options.MockUserControlLegacyGate) return;
        var reject = TryFastRejectHeartbeatLockFree();
        if (reject is null) return;
        var published = Volatile.Read(ref lastPublishedSnapshot);
        reject.Details = new
        {
            source = "published-snapshot",
            operation,
            gateWaited = false,
            hcCalled = false,
            generation = published?.PowerOperationGeneration ?? -1,
            resumePhase = published?.ResumePhase ?? "unknown",
            retryAfterMs = published?.ResumeRetryAfterMs ?? HostState.ResumePollRetryAfterMs,
            controlAccepting = false,
            leaseRenewed = false,
            leaseExtensionMs = 0,
        };
        diagnostics.Write("api.user-control-fast-reject", new
        {
            code = reject.Code,
            operation,
            gateWaited = false,
            hcCalled = false,
            generation = published?.PowerOperationGeneration ?? -1,
            resumePhase = published?.ResumePhase ?? "unknown",
            state = published?.State,
        });
        throw reject;
    }

    public FanLease Heartbeat(string leaseId)
    {
        // ── Q1-c：取锁前快速判定（不等 gate / 不调 HC / 不续租 / 不写曲线 / 不建第二 owner）──
        // 负例开关（仅 mock）：`--mock-heartbeat-legacy-gate` 退回修复前的"直接进 gate"行为，
        // 使 AC15d 的快速判定断言失败 —— 证明该判定不空转。
        var startedTick = Environment.TickCount64;
        if (!options.MockHeartbeatLegacyGate)
        {
            var fastReject = TryFastRejectHeartbeatLockFree();
            if (fastReject is not null)
            {
                // 负例开关（仅 mock）：`--mock-heartbeat-renew-lease` 让快速拒绝路径**如实上报**
                // "错误延长了旧 lease"（details.leaseRenewed=true / leaseExtensionMs=15000），
                // 使 AC15d 的"leaseRenewed=false / leaseExtensionMs=0"断言失败。
                //
                // 口径（必须如实写清，勿误读）：本开关是**可观测契约变异**，不改引擎状态。
                // 真做状态级误延长（把陈旧令牌重新铸成有效 lease）会与恢复 worker 自己的
                // AcquireControl 冲突并把宿主卡死——那是**另一种**（更危险的）缺陷形态，
                // 不属于本夹具的断言范围；本夹具只对"快速拒绝路径是否如实上报未续租"负责。
                var leaseRenewed = false;
                var leaseExtensionMs = 0;
                if (options.MockHeartbeatRenewLease)
                {
                    leaseExtensionMs = 15000;
                    leaseRenewed = true;
                    diagnostics.Write("api.heartbeat-fast-reject-defect-injected", new
                    {
                        injection = "mock-heartbeat-renew-lease",
                        reportedLeaseRenewed = leaseRenewed,
                        leaseExtensionMs,
                        engineStateMutated = false,
                        note = "sandbox-only contract mutation: AC15d's notRenewed assertion must fail",
                    });
                }
                var waitedForGateMs = Environment.TickCount64 - startedTick;
                var published = Volatile.Read(ref lastPublishedSnapshot);
                fastReject.Details = new
                {
                    source = "published-snapshot",
                    waitedForGateMs,
                    gateWaited = false,
                    hcCalled = false,
                    generation = published?.PowerOperationGeneration ?? -1,
                    resumePhase = published?.ResumePhase ?? "unknown",
                    retryAfterMs = published?.ResumeRetryAfterMs ?? HostState.ResumePollRetryAfterMs,
                    controlAccepting = false,
                    leaseRenewed,
                    leaseExtensionMs,
                };
                // 事件级诊断（低频：仅在"重建期收到控制请求"时写一条），供真机取证。
                diagnostics.Write("api.heartbeat-fast-reject", new
                {
                    code = fastReject.Code,
                    waitedForGateMs,
                    hcCalled = false,
                    leaseRenewed,
                    leaseExtensionMs,
                    generation = published?.PowerOperationGeneration ?? -1,
                    resumePhase = published?.ResumePhase ?? "unknown",
                    state = published?.State,
                });
                throw fastReject;
            }
        }
        lock (gate)
        {
            EnsureControlAvailable();
            EnsureLease(leaseId);
            try
            {
                // HC has no device-independent ownership readback contract.
                // Heartbeat therefore validates only the live Host/HC session;
                // it never claims that an OEM tool took over from a transient
                // EC, WMI or ACPI read result.
                realBackend?.VerifyActiveCurveSession();
            }
            catch (Exception ex)
            {
                RecoverAfterHardwareFailure(ex);
                throw new FanApiException(409, "HC_SESSION_UNAVAILABLE", "HC 风扇会话失效，已停止 YeMan 控制并尝试恢复 OEM");
            }
            var lease = state.Lease! with { ExpiresAtMonoMs = MonoMs() + 15000 };
            state.Lease = lease;
            leaseTimer?.Change(15000, Timeout.Infinite);
            return lease;
        }
    }

    public object Enable(JsonElement body)
    {
        // FAN-204 §31 R4（阶段 2）：用户控制端点过渡期统一快速拒绝；恢复 worker 的自建首写豁免。
        RejectUserControlDuringTransitionLockFree("enable");
        lock (gate)
        {
            diagnostics.Write("api.enable.begin", new { state = state.State, hasLease = state.Lease is not null });
            EnsureControlAvailable();
            EnsureLeaseFromBody(body);
            if (realBackend is null && !MockFanHandshakeFlag)
            {
                RejectUnsupported();
                throw new FanApiException(409, "HARDWARE_DISABLED", "当前构建未授权真实风扇写入");
            }
            IReadOnlyList<FanNode> nodes;
            try
            {
                // MOCK（2026-09-15）：伪装设备就绪，跳过 realBackend 能力门。
                if (MockFanHandshakeFlag) { /* mock: 能力门放行 */ }
                else EnsureRealSupported();
                nodes = ParseNodes(body);
            }
            catch (FanApiException ex) when (ex.Code == "INVALID_CURVE")
            {
                // A malformed request must not tear down an otherwise valid
                // active curve; reject only this request.
                throw;
            }
            catch (Exception ex)
            {
                state.HardwareWritesObserved = true;
                RecoverAfterHardwareFailure(ex);
                throw;
            }
            // A real curve write is the only transition into active software
            // control. Opening HC prepares the device but does not itself
            // prove that a fan command was issued.  Clear a previous OEM
            // acknowledgement before the HC callback so a disable -> enable
            // sequence can never skip its next hardware restore.
            state.HardwareWritesObserved = true;
            state.HardwareWritesEnabled = true;
            state.OemRestoreConfirmed = false;
            state.HcRestoreCallbackReturned = false;
            state.OemRestoreEvidence = "none";
            state.OemOwnershipStatus = "unknown-no-hc-contract";
            state.OemPhysicalOwnershipConfirmed = false;
            if (MockFanHandshakeFlag)
            {
                // MOCK（2026-09-15）：伪装写曲线——不调 HC，模拟温度/占空比。
                state.LastTemperatureC = 55.0;
                state.CurrentDutyPercent = 40;
            }
            else
            {
                try { realBackend!.ApplyCurve(nodes); }
                catch (Exception ex)
                {
                    diagnostics.Write("api.enable.hc-write-failure", new { error = ExceptionText(ex) });
                    RecoverAfterHardwareFailure(ex);
                    throw;
                }
            }
            activeCurve = nodes;
            state.ActiveCurve = nodes;
            if (options.MockZeroHardwareEvidence) state.MockControlSequence++;
            state.LastTemperatureC = MockFanHandshakeFlag ? 55.0 : realBackend!.LastTemperatureC;
            state.CurrentDutyPercent = MockFanHandshakeFlag ? 40 : realBackend!.LastDutyPercent;
            state.HardwareWritesEnabled = true;
            state.OemRestoreConfirmed = false;
            state.HcRestoreCallbackReturned = false;
            state.State = automaticResumeInProgress ? "Resuming" : "Ready";
            diagnostics.Write("api.enable.success", new { state = state.State, state.CurrentDutyPercent, state.LastTemperatureC });
            return SnapshotUnlocked();
        }
    }

    public object Preset(JsonElement body)
    {
        var name = body.TryGetProperty("name", out var value) && value.ValueKind == JsonValueKind.String ? value.GetString() : null;
        var leaseId = body.TryGetProperty("leaseId", out var leaseValue) && leaseValue.ValueKind == JsonValueKind.String
            ? leaseValue.GetString()
            : null;
        // The UI stores an independently editable curve for each preset. If
        // the caller supplies that curve, apply exactly those nodes instead
        // of silently replacing it with the Host's fixed fallback preset.
        // External callers may omit nodes and still use the named defaults.
        var nodes = body.TryGetProperty("nodes", out var nodeValue) && nodeValue.ValueKind == JsonValueKind.Array
            ? ParseNodes(body)
            : PresetNodes(name);
        // Preserve the caller's lease when translating the named preset into
        // the same one-shot curve request used by manual edits. Dropping it
        // here made every real preset fail at Enable's lease gate and then
        // needlessly enter the UI recovery path.
        using var document = JsonDocument.Parse(JsonSerializer.Serialize(new { nodes, leaseId }, JsonDefaults.Options));
        return Enable(document.RootElement);
    }

    internal static string BuildPresetPayloadForSelfTest(string name, string leaseId)
    {
        var nodes = PresetNodes(name);
        return JsonSerializer.Serialize(new { nodes, leaseId }, JsonDefaults.Options);
    }

    private static FanNode[] PresetNodes(string? name) => name?.ToLowerInvariant() switch
    {
        "soft" => new[] { new FanNode(0, 0), new FanNode(40, 0), new FanNode(70, 20), new FanNode(100, 80) },
        "balanced" => new[] { new FanNode(0, 0), new FanNode(40, 20), new FanNode(70, 45), new FanNode(100, 90) },
        "aggressive" => new[] { new FanNode(0, 0), new FanNode(40, 30), new FanNode(70, 75), new FanNode(100, 100) },
        _ => throw new FanApiException(400, "INVALID_PRESET", "未知风扇预设"),
    };

    public object Disable(JsonElement body)
    {
        lock (gate)
        {
            // OEM restoration is safety cleanup, never an ownership mutation.
            // It must stay reachable after a lease timer fired or a client
            // crashed; a stale lease must never block the release of hardware.
            LogIgnoredLeaseForSafetyCleanup(body, "disable");
            if (!RestoreHardware(close: false))
            {
                state.State = "FaultLocked";
                ScheduleRecoveryRetry();
                throw new FanApiException(409, "OEM_RESTORE_FAILED", "OEM 风扇控制恢复未确认，Host 保持运行等待重试");
            }
            state.State = "Ready";
            suspendedCurve = null;
            return SnapshotUnlocked();
        }
    }

    public object Restore(JsonElement body)
    {
        lock (gate)
        {
            // See Disable: a stale lease can authorize neither a write nor a
            // new owner, but it cannot be allowed to prevent OEM recovery.
            LogIgnoredLeaseForSafetyCleanup(body, "restore");
            if (!RestoreHardware(close: false))
            {
                state.State = "FaultLocked";
                ScheduleRecoveryRetry();
                throw new FanApiException(409, "OEM_RESTORE_FAILED", "OEM 风扇控制恢复未确认，Host 保持运行等待重试");
            }
            state.State = "Ready";
            suspendedCurve = null;
            return SnapshotUnlocked();
        }
    }

    public object Release(JsonElement body)
    {
        lock (gate)
        {
            // Release is the final ownership cleanup step. A lease gates new
            // writes, but an expired lease must not block relinquishing a
            // session that has already restored OEM. Require the token to
            // match the current owner when one exists, while accepting its
            // expiry as a cleanup condition rather than returning
            // LEASE_INVALID before RestoreHardware can run.
            if (state.Lease is not null)
            {
                if (!body.TryGetProperty("leaseId", out var value) || value.ValueKind != JsonValueKind.String ||
                    !string.Equals(value.GetString(), state.Lease.LeaseId, StringComparison.Ordinal))
                    throw new FanApiException(409, "LEASE_INVALID", "Fan lease 已失效");
            }
            // HC's normal profile handoff changes FanMode back to Hardware but
            // keeps the device session open. IDevice.Close() belongs to the
            // process/sleep boundary, not lease release; calling it here can
            // repeat vendor resource disposal and block a later enable.
            if (!RestoreHardware(close: false))
            {
                state.State = "FaultLocked";
                ScheduleRecoveryRetry();
                throw new FanApiException(409, "OEM_RESTORE_FAILED", "OEM 风扇控制恢复未确认，lease 保留，Host 保持运行等待重试");
            }
            ClearLease();
            suspendedCurve = null;
            state.State = state.UnknownState ? "FaultLocked" : "AwaitingControl";
            return SnapshotUnlocked();
        }
    }

    public object Suspend(JsonElement body)
    {
        MarkSystemSuspendPending();
        lock (gate)
        {
            LogIgnoredLeaseForSafetyCleanup(body, "suspend");
            return SuspendUnlocked();
        }
    }

    /** Invoked by the serialized native SystemPending ingress before HC Close. */
    public void MarkSystemSuspendPending()
    {
        // 第十六轮返修：引擎级/直调发布保持"无条件"语义（外部回调与自测注入
        // 不携带边沿归属）——只有携带边沿归属的准入回调（AnnounceSuspendPending）
        // 才做"边沿仍当前"的守护。
        PublishSuspendProtection();
        realBackend?.BlockWritesForSuspend();
    }

    /**
     * 第十六轮返修（admission/commit 协议）：宿主机接入的"当前已宣布边沿"查询
     * （由 LocalFanHostServer 构造时接线）。未接线（纯引擎/离线自测）时按
     * "无条件发布"处理，保持既有语义。
     */
    internal Func<bool>? SuspendEdgeCurrentProbe;

    // 第十七/十八轮返修（admission/commit）：保护提交序号——每次"成功提交保护
    // 发布"递增。它不是取消版本（不参与取代/超时/放行判定），只用于接受边界
    // 归属：接受记录在 claim 瞬间携带该边界；上下文发布以 CAS 取得提交权，
    // 期间任何更新的提交都会使其 CAS 失败 ⇒ 终态 no-op，绝不覆盖他人 token。
    private long suspendProtectionCommitSequence;

    /** claim 时铸造接受记录用的边界读取（由 QueuePowerTransition 注入 provider）。 */
    internal long SuspendProtectionCommitBoundary => Volatile.Read(ref suspendProtectionCommitSequence);

    // 接受上下文（线程作用域；Enter 返回进入前上下文供 finally 恢复，支持嵌套）。
    [ThreadStatic] private static FanHostEngine? t_suspendAdmissionContextOwner;
    [ThreadStatic] private static PowerEdgeAcceptance? t_suspendAdmissionContextAcceptance;

    /**
     * 第十八轮返修：接受上下文携带的是**不可变接受记录**（claim 瞬间铸造的
     * acceptanceId + 完整边沿身份 + 保护提交边界）——不再在 Enter 时现读共享
     * 序号，因此"claim 成功 → 线程被抢占 → 回调才执行"的窗口里，回调仍按 A 的
     * 接受边界判定（而不是当前值）。
     */
    internal (FanHostEngine? Owner, PowerEdgeAcceptance? Acceptance) EnterSuspendAdmissionContext(PowerEdgeAcceptance acceptance)
    {
        var previous = (Owner: t_suspendAdmissionContextOwner, Acceptance: t_suspendAdmissionContextAcceptance);
        t_suspendAdmissionContextOwner = this;
        t_suspendAdmissionContextAcceptance = acceptance;
        return previous;
    }

    internal void ExitSuspendAdmissionContext((FanHostEngine? Owner, PowerEdgeAcceptance? Acceptance) previous)
    {
        t_suspendAdmissionContextOwner = previous.Owner;
        t_suspendAdmissionContextAcceptance = previous.Acceptance;
    }

    /**
     * 第十五轮返修（统一准入协议）：睡眠保护"只在准入成功后"发布——生产 API 与
     * 自测入口把它作为共享准入操作（QueuePowerTransition）的"已接纳"回调；
     * 去重/过期/关闭/被拒（非 Queued）永不调用 ⇒ 不推进版本、不写待办、零副作用。
     *
     * 第十六轮返修：发布必须仍归属"当前已宣布的睡眠边沿"（目标探针）——边沿已被
     * 更新唤醒取代时以"无保护"终止（迟到发布不得留下无人认领的待办）。
     *
     * 第十七/十八轮返修：归属以"不可变接受边界"判定——在已接纳回调上下文
     * （接受上下文）中调用时，以 CAS 原子取得提交权（期望值 = 接受记录的
     * ProtectionBoundaryStamp）；取得失败 ⇒ 期间已有更新的保护提交（含直调
     * 发布），本次迟到发布 no-op——检查与提交之间不再有窗口，即使当前目标
     * 仍是 Suspended（新睡眠 C），A 的迟到回调也不能覆盖 C 的 token。
     * 保持 Windows 回调语义：无锁、无分配、非阻塞。
     */
    internal void AnnounceSuspendPending()
    {
        var probe = SuspendEdgeCurrentProbe;
        if (probe is not null && !probe()) return;
        SuspendProtectionToken? published;
        if (ReferenceEquals(t_suspendAdmissionContextOwner, this) &&
            t_suspendAdmissionContextAcceptance is { } acceptance)
        {
            // 第十九/二十二轮返修（归属以 claim 代次线性化 + 授权推进）：当前保护必须
            // "可证明可更新"——不存在、或由严格更早代次的接受提交。"不更早"的接受使本次
            // 提交终态 no-op（迟到旧回调不得覆盖新睡眠 token；A→B→C 链上 A 的迟到回调
            // 在此被拒）。
            // 第二十二轮（P1#2）修正：**owner=0（直调发布）不再阻断合法接受**——改为
            // "合并授权"：保留 Value、把 OwnerGeneration 推进到本次接受，使此前发出的
            // (值, 旧归属) 消费授权立即失效（否则新睡眠沿用旧 token，旧队列 resume 仍能
            // 解除新睡眠保护——R22 复现）。合法性仍由后续提交序号 CAS 守卫（迟到的、
            // 边界已推进的接受在此失败 ⇒ no-op）。
            var current = Volatile.Read(ref suspendProtection);
            if (current is not null && current.OwnerGeneration >= acceptance.Generation)
                return;
            // 辅助新鲜度守卫（第二十一轮返修：如实定性——这是**分层守卫中的一层**，
            // 不是"claim + 边界 + 入队"的单一线性化事务）：接受边界 CAS 的读数在
            // claim 之前取得，是**保守下界**；失败 ⇒ 期间已有更新的提交。本层与
            // ① 目标探针、② OwnerGeneration 代次归属共同保证归属正确。
            if (Interlocked.CompareExchange(
                    ref suspendProtectionCommitSequence,
                    acceptance.ProtectionBoundaryStamp + 1,
                    acceptance.ProtectionBoundaryStamp) != acceptance.ProtectionBoundaryStamp)
                return;
            // 第二十二轮（P1#2）：无保护 ⇒ 铸新 token；已有**直调（owner=0）**保护 ⇒
            // 合并授权（保留 Value、推进 OwnerGeneration；DirectOwner 语义不变）；
            // 已有更早的**接受**保护 ⇒ 按既有语义铸新 token（每个接受周期一个新值）。
            // 第二十三轮（P1）：本分支返回**本次确实拥有的不可变记录实例**（合并未取得
            // 归属时返回 null）——尾部清理据此做记录级 CAS，不再用 Value 认领他人记录。
            published = current is not null && current.OwnerGeneration == 0
                ? MergeSuspendProtectionOwner(acceptance.Generation)
                : WriteSuspendProtection(acceptance.Generation);
        }
        else
        {
            // 直调路径（Mark / 外部回调 / 离线自测）：无条件发布语义保持（归属 0）。
            published = PublishSuspendProtection();
        }
        // 竞态兜底（第二十三轮 P1 修正）：检查与发布之间若出现更新的边沿，立即以
        // "无对象"收敛——**只清除本次发布者自己拥有的那条不可变记录实例**。此前按
        // Value 匹配会在"新睡眠合并授权（保留 Value、推进 Stamp）"后误清他人的新授权
        // （R23 复现：{1,0}→{1,4} 被旧回调清空）。未被我们拥有者一律不动。
        if (probe is not null && !probe() && published is not null)
            ClearSuspendProtectionIfCurrent(published);
    }

    /** 原始发布（无归属守护，直调路径）：序号无条件递增 + 写保护（归属 = 直调 0）。 */
    private SuspendProtectionToken PublishSuspendProtection()
    {
        // 第十七轮返修：先记录"提交开始"（序号先行——缩小迟到回调与本次提交
        // 之间的竞态窗口；任何晚到的边沿回调都会看到边界已变而 no-op）。
        Interlocked.Increment(ref suspendProtectionCommitSequence);
        return WriteSuspendProtection(ownerGeneration: 0);
    }

    /**
     * 写保护本体：镜像 + 取消版本 + 保护记录（值 + 归属一体）。
     * 第二十三轮（P1）：返回**本发布者拥有的不可变记录实例**（而不是裸 Value）——
     * 后续清理/回滚必须以该实例为归属判据；裸 Value 在授权合并后不再唯一指向
     * 本发布者的记录。
     */
    private SuspendProtectionToken WriteSuspendProtection(long ownerGeneration)
    {
        // No engine lock, allocation, diagnostics I/O, or timer disposal is
        // permitted in the Windows callback. This volatile guard is checked
        // before every new control operation and in the HC temperature path.
        Volatile.Write(ref systemSuspendPending, 1);
        // 第一批返修（R1）：把"睡眠已宣布"纳入版本化取消协议——Interlocked 递增，
        // 保持回调非阻塞；进行中的恢复 worker 提交前核对 epoch 即会被拒。
        var announcedEpoch = Interlocked.Increment(ref powerEpoch);
        // 第十一/十九轮返修：登记保护记录（值 + 归属一体写入；恢复侧按值精确消费）。
        var record = new SuspendProtectionToken(announcedEpoch, ownerGeneration);
        Volatile.Write(ref suspendProtection, record);
        return record;
    }

    /**
     * 第二十三轮（修订）：**睡眠周期身份 / 发布归属比较的唯一实现**——保护授权就是
     * (Value = 周期编号, Stamp = 归属代次)。发布、合并、消费、等待解析一律复用本函数；
     * 禁止各处自写"只比值"的比较。清理路径另用**记录实例同一性**（更强的判据，
     * 见 `ClearSuspendProtectionIfCurrent`）。
     */
    internal static bool SameSuspendCycle(long valueA, long stampA, long valueB, long stampB) =>
        valueA == valueB && stampA == stampB;

    /** 保护记录存在性判定（与 IsSystemSuspendPendingForSelfTest 同源）。 */
    private bool SuspendProtectionPending => Volatile.Read(ref suspendProtection) is not null;

    /**
     * 第十九/二十三轮返修：**记录级**精确清除——只清除"本次发布者拥有的那条不可变
     * 记录实例"（引用同一性）。按裸 Value 匹配在授权合并后不再安全：新睡眠合并会
     * 保留 Value、推进 Stamp，旧发布者用 Value 认领会把**他人的新授权**清掉
     * （R23 P1 复现）。不是自己那条记录 ⇒ 一律不动。
     */
    private bool ClearSuspendProtectionIfCurrent(SuspendProtectionToken owned)
    {
        var current = Volatile.Read(ref suspendProtection);
        if (current is null || !ReferenceEquals(current, owned)) return false;
        return ReferenceEquals(Interlocked.CompareExchange(ref suspendProtection, null, current), current);
    }

    /**
     * 第二十二/二十三轮返修（P1#2）授权合并：把 owner=0（直调）保护的**消费授权归属**
     * 推进到本次接受——保留 Value（保护对象/周期编号不变 ⇒ DirectOwner 语义不变、
     * 不会被重铸），只让此前发出的 (值, 旧归属) 授权失效。单次原子引用交换（CAS 循环）。
     * 返回：**合并后由本次发布的记录实例**；未取得归属（保护已被消费、或已被同级/
     * 更新的 owner 持有）时返回 null——**不得把他人记录的 Value 当作自己的归属凭证**
     * （R23 P1 要求：看到更高 owner 后返回其 Value 会错误授予旧调用清理权）。
     */
    private SuspendProtectionToken? MergeSuspendProtectionOwner(long ownerGeneration)
    {
        while (true)
        {
            var current = Volatile.Read(ref suspendProtection);
            if (current is null) return null;
            if (current.OwnerGeneration >= ownerGeneration) return null;
            var merged = new SuspendProtectionToken(current.Value, ownerGeneration);
            if (ReferenceEquals(Interlocked.CompareExchange(ref suspendProtection, merged, current), current))
                return merged;
        }
    }

    /**
     * 第十九/二十二/二十三轮返修：恢复侧"消费"保护——**(值, 授权归属) 双匹配**的精确清除
     * （比较统一走 `SameSuspendCycle`）。只比值会让"新睡眠沿用旧 token（授权已推进）"的
     * 旧授权继续生效（R22 P1#2）；expectedStamp < 0 = 未指定（legacy/自测路径，按值消费，
     * 保持既有语义）。expectedValue==0 且当前无保护时按"空者自空"成功（CAS(0→0) 语义）。
     */
    internal bool TryConsumeSuspendProtection(long expectedValue, long expectedStamp = -1)
    {
        if (expectedValue == 0 && Volatile.Read(ref suspendProtection) is null) return true;
        while (true)
        {
            var current = Volatile.Read(ref suspendProtection);
            if (current is null || current.Value != expectedValue) return false;
            if (expectedStamp >= 0 && !SameSuspendCycle(current.Value, current.OwnerGeneration, expectedValue, expectedStamp))
                return false;
            if (ReferenceEquals(Interlocked.CompareExchange(ref suspendProtection, null, current), current)) return true;
        }
    }

    /**
     * 第十五轮返修：写门在"准入写入之前"落位（由 QueuePowerTransition 的准入
     * writer 调用）——写门变更严格先于该转换对消费者可见，后到的恢复读取
     * gate 版本时必然看到它。拒绝路径**不回退**写门（fail-closed：被拒边沿保留
     * 为 deferred，写门保持阻断，由下一次获准入的恢复按版本放行）。
     */
    internal void BlockWritesForSuspendNow() => realBackend?.BlockWritesForSuspend();

    internal bool IsCloseWriteBlockedForPower => Volatile.Read(ref closeWriteBlocked) != 0;
    internal bool IsSystemSuspendPendingForSelfTest => SuspendProtectionPending;

    /**
     * 裁决 H3（N15，2026-09-19）：睡眠保护令牌的**条件式**释放判据（纯函数，可测）。
     * 只有两个条件同时成立才允许释放：
     * ① recordStillCurrent：当前保护记录仍是本次睡眠发布的那**一条实例**（引用同一性）；
     * ② !hcCloseIsOwed：本 Host 不欠任何 HC Close 义务（未交叉所有权 ⇒ 无需清理）。
     * 禁止无条件清除；成功 suspend 路径不调用本判据（令牌必须留给唤醒侧消费）。
     */
    internal static bool MayReleaseUnresolvableSuspendProtection(bool recordStillCurrent, bool hcCloseIsOwed) =>
        recordStillCurrent && !hcCloseIsOwed;

    /**
     * 裁决 H3（N15）：把"已不可能被正常消费"的睡眠保护令牌释放掉——用于睡眠失败与
     * recovery retry 进入终态（FaultLocked）两条路径。守卫（记录级身份 + 无 Close
     * 义务）必须全部通过；释放用记录实例 CAS（ClearSuspendProtectionIfCurrent），
     * 绝不按 token value 认领他人记录。
     */
    private void TryReleaseUnresolvableSuspendProtection()
    {
        var owned = suspendBoundaryOwnedRecord;
        if (owned is null) return;
        var stillCurrent = ReferenceEquals(Volatile.Read(ref suspendProtection), owned);
        if (!MayReleaseUnresolvableSuspendProtection(stillCurrent, IsHcCloseOwedForSuspendRelease())) return;
        if (!ClearSuspendProtectionIfCurrent(owned)) return;
        suspendBoundaryOwnedRecord = null;
        diagnostics.Write("power.suspend-protection-released-unresolvable", new
        {
            reason = "suspend-failed-no-close-obligation",
            state = state.State,
            powerState = state.PowerState,
            value = owned.Value,
            ownerGeneration = owned.OwnerGeneration,
            closeOwed = false,
        });
    }

    /**
     * T9（2026-09-19）：由于 Safe 构建无真实 HC 后端，`IsHcCloseOwed()` 恒 false，
     * 无法在 Safe 端到端验证"有 Close 义务 ⇒ 拒绝释放令牌"的拒绝**方向**。为此提供
     * 一个自测专用力度：默认与生产完全一致（委托给 IsHcCloseOwed），自测可注入
     * `HcCloseOwedForSuspendReleaseOverride` 模拟"本 Host 仍欠一次 HC Close"。
     * 生产代码路径（未注入时）与 <b>零改动前完全等同</b>——见 `IsHcCloseOwed()`。
     */
    private bool? hcCloseOwedForSuspendReleaseOverride;
    internal void SetHcCloseOwedForSuspendReleaseForSelfTest(bool value) =>
        hcCloseOwedForSuspendReleaseOverride = value;
    private bool IsHcCloseOwedForSuspendRelease() =>
        hcCloseOwedForSuspendReleaseOverride ?? HcCloseIsOwed();

    /**
     * 裁决 H5（2026-09-19）：FaultLocked 的**免门**白名单故障记录（每次进入终态一条，
     * 低频）。日志门是逐次读 flag，门开启前的故障整段无证据（N17）；本事件由
     * HostDiagnosticLog 无条件落 fan-host-fault.log，不受日志门影响。
     */
    private void WriteFaultLockedDiagnostic(string reason)
    {
        diagnostics.Write("power.fault-locked", new
        {
            reason,
            state = state.State,
            powerState = state.PowerState,
            openCalled = state.OpenCalled,
            openEventsCalled = state.OpenEventsCalled,
            hardwareWritesObserved = state.HardwareWritesObserved,
            hcCloseCleanupPending = state.HcCloseCleanupPending,
            closeOwed = realBackend?.HcCloseIsOwed == true,
        });
    }

    // 第十三/十九轮返修：入口接受点的睡眠保护快照——必须随队列/接续/worker 传递；
    // 排队中的旧恢复不得在"实际执行"时读取并消费后来宣布的新睡眠保护。
    internal long SuspendPendingEpochSnapshot => Volatile.Read(ref suspendProtection)?.Value ?? 0;
    /**
     * 第二十二轮返修（P1#2）：**授权快照**（值 + 归属代次）——必须**一次读取**同一
     * 不可变记录（分别读 Value/OwnerGeneration 会撕裂），并随队列/接续一路传递；
     * 消费时双匹配。(0, 0) = 接受时无保护。
     */
    internal SuspendProtectionAuthorization SuspendProtectionAuthorizationSnapshot
    {
        get
        {
            var current = Volatile.Read(ref suspendProtection);
            return current is null ? new SuspendProtectionAuthorization(0, 0)
                : new SuspendProtectionAuthorization(current.Value, current.OwnerGeneration);
        }
    }
    internal bool CloseOwnerInFlightForSelfTest => Volatile.Read(ref closeBoundaryInFlight) != 0;
    internal void SetCloseOwnerDelayForSelfTest(int milliseconds) =>
        Volatile.Write(ref closeOwnerSelfTestDelayMs, Math.Max(0, milliseconds));

    // §17.1-2（仅自测）：gate 持有期复现缝。语义与既有 closeOwnerSelfTestDelayMs 一致：
    // 只在自测里被设置，生产默认 0 ⇒ 零行为变化。
    private int gateHoldSelfTestMs;
    internal void SetGateHoldForSelfTest(int milliseconds) =>
        Volatile.Write(ref gateHoldSelfTestMs, Math.Max(0, milliseconds));

    /**
     * §17.1-2（仅自测）：**直接**持有引擎 gate 指定时长，用于测量持有期对恢复重试计时器等
     * 后台消费者的影响（生产入口 `OpenEvents` 的持有期已在同场景其它分项中测量）。生产不调用。
     */
    internal void HoldGateForSelfTest(int milliseconds)
    {
        if (milliseconds <= 0) return;
        lock (gate)
        {
            Volatile.Write(ref gateHeldSelfTest, 1);
            try { Thread.Sleep(milliseconds); }
            finally { Volatile.Write(ref gateHeldSelfTest, 0); }
        }
    }

    /** 夹具可判定性：让自测能确定"gate 确实被持有"，避免有界取锁用例空转。 */
    private int gateHeldSelfTest;
    internal bool GateHeldForSelfTest => Volatile.Read(ref gateHeldSelfTest) != 0;

    /** Invoked by the serialized native SystemPending ingress. */
    public object SuspendForSystemPower()
    {
        lock (gate) return SuspendUnlocked();
    }

    private object SuspendUnlocked()
    {
        if (stopped) return SnapshotUnlocked();
        // 第一批：新睡眠取代进行中的恢复——操作记录标 superseded，
        // 并清 resume 接续登记（旧任务不得解除新睡眠保护）。
        if (state.PowerOperationStatus == "pending" || state.PowerOperationStatus == "executing")
            state.PowerOperationStatus = "superseded";
        // 第一批返修（P1#3）：归属失效——旧 worker 完成时核对不过，不得覆盖睡眠保护。
        activeResumeOperation = null;
        // 第一批返修（R1）：取代同样推进版本（与 MarkSystemSuspendPending 同一协议）。
        Interlocked.Increment(ref powerEpoch);
        // 第二十二轮返修（P1#1）：清接续登记的同时**显式结算**该登记为 superseded
        // （身份 + 周期一起留存）——等待者据此得到显式终态，而不是靠"token 是否还在"
        // 猜历史归属（新睡眠一旦推进授权，旧登记不可能再被消费）。
        SettlePendingContinuationAsSupersededUnlocked();
        Interlocked.Exchange(ref resumeContinuationRequested, 0);
        // HC SystemPending closes synchronously even when the previous
        // SystemReady background Open task is still in flight; HC does not
        // defer Close to that task (MainWindow has no isPowerSuspended gate
        // on the background Open). The backend serializes every HC call on
        // hardwareGate, so an in-flight Open/OpenEvents/Enable either
        // completes before this Close or is abandoned by the resume worker
        // (see CompleteAutomaticResume catch: PowerState Suspending/Suspended
        // is a benign skip, next SystemReady re-runs the F5). Full parity.
        // HC's SystemManager handler ignores duplicate status notifications
        // (`status == prevStatus`). YeMan receives the same suspend boundary
        // from two legitimate observers: the Host's SystemEvents callback and
        // the native safety worker. Once the first serialized transition has
        // reached Suspended, a second request must be a read-only no-op; it
        // must not invoke the HC virtual Close() a second time.
        if (state.State == "Suspending" || state.PowerState == "Suspending" ||
            state.State == "Suspended" || state.PowerState == "Suspended" ||
            state.State == "AwaitingCloseCleanup" || state.HcCloseCleanupPending)
        {
            diagnostics.Write("power.suspend-ignored-duplicate", new
            {
                state = state.State,
                powerState = state.PowerState,
                state.OpenCalled,
                state.OpenEventsCalled,
                state.HardwareWritesObserved,
            });
            if (state.State == "AwaitingCloseCleanup" || state.HcCloseCleanupPending)
                ScheduleRecoveryRetry();
            return SnapshotUnlocked();
        }
        // A fault/unknown session is not a duplicate completed transition.
        // HC SystemPending still reaches CurrentDevice.Close() after a prior
        // device error; do not let the de-duplication guard skip that one
        // Close-first recovery attempt before sleep. If an earlier Close is
        // still pending, the branch above remains read-only and its retry timer
        // owns the same strict F4 gate.
        if (state.State == "FaultLocked" || state.UnknownState)
            diagnostics.Write("power.suspend-recovery-from-fault", new
            {
                state = state.State,
                powerState = state.PowerState,
                state.OpenCalled,
                state.OpenEventsCalled,
                state.HardwareWritesObserved,
            });
        state.PowerState = "Suspending";
        state.State = "Suspending";
        // 裁决 H3：登记本次睡眠边界所属的不可变保护记录**实例**（引用同一性）——
        // 后续失败/终态路径只允许用这一条实例做记录级 CAS 释放，绝不按 Value 认领。
        suspendBoundaryOwnedRecord = Volatile.Read(ref suspendProtection);
        suspendedCurve = activeCurve is null
            ? null
            : activeCurve.Select(node => new FanNode(node.TempC, node.DutyPercent)).ToArray();
        StopCurveTimer();
        // Strict HC SystemPending: freeze/write-gate first, then let the
        // device's own CurrentDevice.Close() own all ACPI/HID teardown. Do not
        // pre-apply Hardware/default curves while the session is still open.
        if (!CloseForSystemPending())
        {
            if (state.HcCloseCleanupPending)
            {
                // Strict F4 has no pre-Close Hardware callback to prove. A
                // pending virtual Close cleanup is still retried by the same
                // Close-first owner; do not require OEM callback evidence.
                state.PowerState = "Suspending";
                state.State = "AwaitingCloseCleanup";
                diagnostics.Write("power.awaiting-close-cleanup", new
                {
                    reason = "system-pending-close-not-confirmed",
                    state = state.State,
                    powerState = state.PowerState,
                    hcCloseCleanupPending = true,
                    closeOwed = realBackend?.HcCloseIsOwed == true,
                });
            }
            else
            {
                state.PowerState = "Unknown";
                state.State = "FaultLocked";
                WriteFaultLockedDiagnostic("system-pending-close-failed");
            }
            // 裁决 H3：只有"当前记录仍是本次睡眠那一条实例"且"无 Close 义务"时才
            // 允许释放睡眠保护（此处有 Close 义务 ⇒ 守卫必然拒绝，保持保守）。
            TryReleaseUnresolvableSuspendProtection();
            ScheduleRecoveryRetry();
            return SnapshotUnlocked();
        }
        ClearLease();
        state.PowerState = "Suspended";
        state.State = "Suspended";
        // HC MainWindow.SystemPending samples pendingTime when the suspend
        // boundary is entered; the SystemReady handler later compares it to
        // resumeTime to decide the extra 3s wait. Record the same instant.
        sleepEntryUtc = DateTime.UtcNow;
        return SnapshotUnlocked();
    }

    /**
     * 第二十一轮返修（P1）：结算记账（必须在 gate 内调用）——把本 attempt 的终态写入
     * 单槽留存，供"自己的 attempt 已不是最新"的等待者读取本操作终态。仅记账，
     * 不参与任何判定；attemptId<=0（无身份/注入夹具的合成 worker）不记账。
     */
    private void RecordResumeTerminalLocked(long attemptId, string status, string? outcome)
    {
        if (attemptId <= 0) return;
        resumeTerminalAttempt = attemptId;
        resumeTerminalStatus = status;
        resumeTerminalOutcome = outcome;
    }

    /**
     * 第二十二轮返修（P1#1）：把"当前挂起的接续登记"结算为 superseded（身份 + 睡眠
     * 周期一起留存，必须在 gate 内调用）。用于新睡眠取代挂起登记的时刻——等待者据此
     * 得到显式终态，而不是靠"当前 token 是否还在"推断历史归属。
     */
    private void SettlePendingContinuationAsSupersededUnlocked()
    {
        if (Volatile.Read(ref resumeContinuationRequested) == 0) return;
        var pendingId = resumeContinuationId;
        if (pendingId <= 0) return;
        resumeSettledContinuationId = pendingId;
        resumeSettledContinuationValue = resumeContinuationValue;
        resumeSettledContinuationStamp = resumeContinuationStamp;
    }

    /**
     * 第二十二/二十三轮（P1#1）：登记接续（铸稳定身份 + 记录睡眠周期身份）。
     * **同周期复用**（第二十三轮 P2 修正）：若槽位仍挂着**同一周期**（`SameSuspendCycle`：
     * 相同 Value + 相同归属）的登记，则复用该登记身份——同周期合并等待的多个请求因此
     * 共享同一份完成结果，不会被"最后一次登记覆盖单槽"淘汰成 EXPIRED（R23 复现：
     * A 先登记并已在等待、B 后登记 ⇒ 此前只有 B 能拿到结果）。不同周期一律铸新身份
     * （旧登记由新睡眠显式结算为 superseded）。
     */
    private long RegisterContinuationUnlocked(long cycleValue, long cycleStamp)
    {
        if (Volatile.Read(ref resumeContinuationRequested) != 0 && resumeContinuationId > 0 &&
            SameSuspendCycle(resumeContinuationValue, resumeContinuationStamp, cycleValue, cycleStamp))
        {
            return resumeContinuationId;
        }
        var id = ++resumeContinuationCounter;
        resumeContinuationId = id;
        resumeContinuationValue = cycleValue;
        resumeContinuationStamp = cycleStamp;
        Interlocked.Exchange(ref resumeContinuationRequested, 1);
        Volatile.Write(ref resumeContinuationEpoch, cycleValue);
        return id;
    }

    /**
     * 第二十一/二十二轮返修（P1）：返回本次调用的接受裁决（ResumeAdmission.Kind）——
     * 与既有语义完全一致，仅新增"本次调用产生了什么"的观测输出（调用方为恢复
     * API 等待者做 operation/attempt 关联）。参数与副作用不变。
     * `expectedPendingStamp`：接受点的消费授权归属（-1 = 未指定，按现场快照）。
     */
    private ResumeAdmission StartAutomaticResumeUnlocked(long expectedPendingEpoch = -1, long expectedPendingStamp = -1, long continuationId = 0)
    {
        // 第一批返修（R3）：归属判定用本协议维护的 resumeWorkerActive，
        // 不得用 Task.IsCompleted（任务体最后一段与 CLR 完成标记之间存在调度窗口，
        // 在该窗口内登记接续会没有 worker 消费）。
        if (resumeWorkerActive != 0)
        {
            // 登记接续（第二十二轮 P1#1）：铸稳定身份 + 记录睡眠周期身份
            // （值 + 授权归属）——等待者按身份/周期解析，不用"最新 attempt"或
            // "token 是否还在"推定归属。
            var snapshot = SuspendProtectionAuthorizationSnapshot;
            var cycleValue = expectedPendingEpoch >= 0 ? expectedPendingEpoch : snapshot.Value;
            var cycleStamp = expectedPendingStamp >= 0 ? expectedPendingStamp : snapshot.Stamp;
            var registeredId = RegisterContinuationUnlocked(cycleValue, cycleStamp);
            state.PowerOperationStatus = "pending";
            // 第二十四轮（任务书 D）：日志必须能按同一身份重放请求——登记身份 + 完整授权
            // （值 + 归属）落盘，供 A→B→C→A 链的日志串联核对。
            diagnostics.Write("power.resume-continuation-deferred", new
            {
                state = state.State,
                continuationId = registeredId,
                authorization = new { value = cycleValue, stamp = cycleStamp },
            });
            return new ResumeAdmission(SnapshotUnlocked(), 0, state.PowerOperationAttempt, "deferred", registeredId);
        }
        // 第十一轮返修（R5）：原子消费"睡眠待办"——仅当待办仍是我们认识的版本才
        // 释放（清 systemSuspendPending）。新睡眠宣布会改写该版本 ⇒ CAS 失败 ⇒
        // 本次恢复被取代（不清保护、不启动），杜绝"检查之后新睡眠被旧恢复覆盖"。
        var acceptedSnapshot = SuspendProtectionAuthorizationSnapshot;
        var acceptedPendingEpoch = expectedPendingEpoch >= 0 ? expectedPendingEpoch : acceptedSnapshot.Value;
        // 第二十二轮返修（P1#2）：消费授权必须同时匹配**值 + 归属代次**——新睡眠
        // 推进授权后，旧 resume 的旧快照（值相同、归属过时）不再放行。
        var acceptedPendingStamp = expectedPendingStamp >= 0 ? expectedPendingStamp : acceptedSnapshot.Stamp;
        // 第十二轮返修（P1-B）：gate 与合作版本都在 CAS 之前捕获——与待办版本
        // 同属一次接受；若期间有新睡眠，待办版本已被改写 ⇒ CAS 失败 ⇒ 整体丢弃。
        var acceptedGateEpoch = realBackend?.SuspendGateEpochForResume ?? 0;
        var acceptedPowerEpoch = Volatile.Read(ref powerEpoch);
        if (!TryConsumeSuspendProtection(acceptedPendingEpoch, acceptedPendingStamp))
        {
            state.PowerOperationStatus = "superseded";
            diagnostics.Write("power.resume-continuation-discarded", new
            {
                state = state.State,
                attempt = state.PowerOperationAttempt,
                authorization = new { value = acceptedPendingEpoch, stamp = acceptedPendingStamp },
            });
            // 第二十一轮返修（P1）：本调用没有产生 attempt——等待者据 "superseded"
            // 立即以显式终态返回，不得转而等待（并借用）后续新恢复的 completed。
            return new ResumeAdmission(SnapshotUnlocked(), 0, state.PowerOperationAttempt, "superseded", continuationId);
        }
        // 第十二轮返修（P1-A）：CAS 消费就是"解除保护"本身——不再对布尔镜像
        // 做任何独立清零（此前"CAS 成功后无条件清 systemSuspendPending"允许
        // 新睡眠在两条语句之间被旧恢复清掉保护）。
        var curve = suspendedCurve is null
            ? null
            : suspendedCurve.Select(node => new FanNode(node.TempC, node.DutyPercent)).ToArray();
        // Q1（FAN-204 s31 补充裁决 C）：**仅沙箱**的慢重建注入的第二半——mock 下"带曲线入睡"
        // 会 fail-closed（D2 形态），沙箱因此永远走不到"有曲线要重建"的路径。显式注入开关
        // 同时声明"把这次空恢复当作要重建"，让 10 s 重建窗口在 mock 里被真实走一遍。
        // 生产（无 --mock-handshake ⇒ MockResumeRebuildDelayMs 恒 0）不可达。
        if (curve is null && options.MockHandshake && options.MockResumeRebuildDelayMs > 0)
        {
            curve = new[] { new FanNode(0, 30), new FanNode(55, 45), new FanNode(75, 70), new FanNode(90, 100) };
            diagnostics.Write("power.resume-mock-slow-rebuild", new
            {
                injection = "synthetic-curve",
                delayMs = options.MockResumeRebuildDelayMs,
                note = "sandbox-only: accept must stay fast while this rebuild window runs in the background",
            });
        }
        state.PowerState = "On";
        state.State = "Resuming";
        // 第十二轮（P1-B 修订）：不可变身份的三个版本全部在 CAS 之前捕获——
        // CAS 成功即保证"捕获之后、消费之前无新睡眠"；CAS 失败则不创建身份。
        var operation = new ResumeOperationIdentity(
            state.PowerOperationGeneration,
            ++resumeAttemptCounter,
            acceptedPowerEpoch,
            acceptedPendingEpoch,
            acceptedGateEpoch);
        activeResumeOperation = operation;
        // 第二十二轮（P1#1）：若本次 attempt 由"接续消费"启动，留存该消费的登记身份
        // 与周期——对应等待者据此精确解析到本 attempt 的终态。
        if (continuationId > 0)
        {
            resumeConsumedContinuationId = continuationId;
            resumeConsumedContinuationValue = acceptedPendingEpoch;
            resumeConsumedContinuationStamp = acceptedPendingStamp;
            resumeConsumedAttemptId = operation.AttemptId;
        }
        state.PowerOperationStatus = "executing";
        state.PowerOperationOutcome = null;
        state.PowerOperationAttempt = operation.AttemptId;
        // A new HC SystemReady transaction ends the prior F4 retry mode. Any
        // later non-power recovery is governed by its own explicit contract.
        recoveryRetryUsesSystemPendingClose = false;
        automaticResumeInProgress = true;
        state.OpenCalled = false;
        state.OpenEventsCalled = false;
        automaticResumeResult = null;
        if (curve is null)
        {
            automaticResumeInProgress = false;
            automaticResumeResult = true;
            state.State = "AwaitingControl";
            state.PowerOperationStatus = "completed";
            state.PowerOperationOutcome = "await-user";
            // 第二十一轮返修（P1）：同步完成也结算本 attempt 终态（等待者关联）。
            RecordResumeTerminalLocked(operation.AttemptId, "completed", "await-user");
            // 第二十四轮（任务书 D）：同步完成路径同样落盘 attempt + 授权身份（日志可重放）。
            diagnostics.Write("power.resume-sync-completed", new
            {
                state = state.State,
                attempt = operation.AttemptId,
                authorization = new { value = acceptedPendingEpoch, stamp = acceptedPendingStamp },
            });
            // 第一批返修（R3 兼容）：同步完成的空恢复没有 worker 在跑——
            // 立即注销本次身份，避免后续延迟任务把它误认成自己的归属。
            if (ReferenceEquals(activeResumeOperation, operation)) activeResumeOperation = null;
            return new ResumeAdmission(SnapshotUnlocked(), operation.AttemptId, operation.AttemptId, "attempt", continuationId);
        }
        diagnostics.Write("power.resume-auto-rebuild.begin", new
        {
            nodeCount = curve.Length,
            attempt = operation.AttemptId,
            authorization = new { value = acceptedPendingEpoch, stamp = acceptedPendingStamp },
            // G-1（2026-09-27 消费侧取证）：唤醒恢复入口带出 HC **已有**的逐轮收据/绑定/清理台账，
            // 把"唤醒边沿黑盒"变成可判因（只读、只增字段、不改判定）。
            hcReceipts = realBackend?.HcReceiptsEvidence,
        });
        resumeWorkerActive = 1;
        resumeTask = Task.Run(() => CompleteAutomaticResume(curve));
        return new ResumeAdmission(SnapshotUnlocked(), operation.AttemptId, operation.AttemptId, "attempt", continuationId);
    }

    private void CompleteAutomaticResume(IReadOnlyList<FanNode> curve)
    {
        var workerThreadId = Environment.CurrentManagedThreadId;
        Volatile.Write(ref automaticResumeWorkerThreadId, workerThreadId);
        // 第一批返修：捕获本任务的操作身份；提交前必须核对仍是当前归属。
        var operation = activeResumeOperation;
        // 第十一轮返修（R5）：使用"请求接受点"捕获的不可变版本——
        // 不得在 worker 启动时重读（否则会把期间新睡眠的版本当成旧恢复的授权）。
        var epochAtStart = operation is ResumeOperationIdentity accepted ? accepted.AcceptedPowerEpoch : 0;
        var gateEpochAtStart = operation is ResumeOperationIdentity acceptedGate ? acceptedGate.AcceptedGateEpoch : 0;
        // 第二十一轮返修（P1）：本 worker 的 attempt 结算记账 id（无身份/注入夹具=0，不记账）。
        var attemptId = operation is ResumeOperationIdentity identity ? identity.AttemptId : 0;
        try
        {
            // Q1（FAN-204 s31 补充裁决 C）：**仅沙箱**的慢重建注入——真机 HC 重建实测
            // ≈10.2 s，而 mock 重建几乎瞬时，AC15 无法覆盖"宿主忙"过渡窗。本延迟只在
            // `--mock-handshake` + 显式 `--mock-resume-rebuild-delay-ms` 同时存在时非零
            // （用户路径永不触达；生产路径 options.MockResumeRebuildDelayMs 恒为 0）。
            if (options.MockHandshake && options.MockResumeRebuildDelayMs > 0)
            {
                diagnostics.Write("power.resume-mock-slow-rebuild-window", new
                {
                    delayMs = options.MockResumeRebuildDelayMs,
                    state = state.State,
                    note = "sandbox-only injection; the accepted response stayed fast while this window runs",
                });
                Thread.Sleep(options.MockResumeRebuildDelayMs);
            }
            // HC MainWindow.SystemReady waits an extra 3 seconds when the
            // device slept for at least 30 minutes before resuming managers or
            // opening the device. Mirror that delay here (background worker,
            // never on the engine gate) so the first HC call is not issued
            // immediately after a long sleep, exactly as upstream does.
            // sleepEntryUtc is only set by a completed suspend boundary; a
            // default value means this F5 did not follow sleep, so skip it.
            if (sleepEntryUtc != default(DateTime) &&
                (DateTime.UtcNow - sleepEntryUtc).TotalMinutes >= 30)
            {
                diagnostics.Write("power.resume-long-sleep-grace", new { delayMs = 3000 });
                Thread.Sleep(3000);
            }
            // Call the same public engine boundaries used by the UI, but do
            // it from the resident Host so WebView loss cannot skip HC
            // Open/OpenEvents/lease/curve reconstruction.
            _ = Open();
            KeepAutomaticResumeState();
            _ = OpenEvents();
            KeepAutomaticResumeState();
            var lease = AcquireControl();
            // R1（FAN-926R 唤醒租约裁决 §3.2.1）：本 worker 留存**自己**铸造的临时租约身份，
            // 与既有 operation/epoch/attempt 身份一并用于成功提交处的窄撤销。
            automaticResumePlaceholderLeaseId = lease.LeaseId;
            automaticResumePlaceholderLeaseGeneration = lease.Generation;
            diagnostics.Write("power.resume-placeholder-lease-created", new
            {
                attempt = attemptId,
                leaseGeneration = lease.Generation,
                controlResponsibility = "host-resume-intent",
                leaseTokenRecorded = false,
            });
            KeepAutomaticResumeState();
            using var document = JsonDocument.Parse(JsonSerializer.Serialize(new
            {
                nodes = curve,
                leaseId = lease.LeaseId,
            }, JsonDefaults.Options));
            _ = Enable(document.RootElement);
            // HC G5 keeps the fan write gate closed until Open, OpenEvents,
            // owner acquisition and the first profile write have completed.
            // Opening it at the start of recovery allowed a temperature tick
            // to cross the half-open session boundary.
            // 第一批返修（R1）：写保护解除纳入版本化协议——先做归属+版本快照，
            // 仅在快照通过时解除；解除后立刻在锁内复查（epoch/pending），
            // 若期间"睡眠已宣布/被取代"，补偿性重建写保护并放弃提交。
            bool ownedBeforeReopen;
            lock (gate)
            {
                ownedBeforeReopen = !stopped
                    && operation is not null
                    && ReferenceEquals(activeResumeOperation, operation)
                    && Volatile.Read(ref powerEpoch) == epochAtStart
                    && !SuspendProtectionPending;
            }
            if (!ownedBeforeReopen)
            {
                lock (gate)
                {
                    // 第一批返修（P2）：退出路径必须结算本操作的执行账目
                    // （仅当没有更新的 worker 接管时才清 inProgress）。
                    if (activeResumeOperation is null || ReferenceEquals(activeResumeOperation, operation)) automaticResumeInProgress = false;
                    state.PowerOperationStatus = "superseded";
                    // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                    RecordResumeTerminalLocked(attemptId, "superseded", null);
                }
                diagnostics.Write("power.resume-commit-superseded", new { state = state.State, attempt = attemptId });
                return;
            }
            // 第十轮返修（P1-B）：版本化解除——仅当自我捕获的 gate 版本仍有效才解除写保护；
// 否则本次恢复已被新睡眠/关闭取代（不解除、不提交）。
            if (realBackend is not null && !realBackend.TryAllowWritesAfterResume(gateEpochAtStart))
            {
                lock (gate)
                {
                    if (activeResumeOperation is null || ReferenceEquals(activeResumeOperation, operation)) automaticResumeInProgress = false;
                    state.PowerOperationStatus = "superseded";
                    // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                    RecordResumeTerminalLocked(attemptId, "superseded", null);
                }
                diagnostics.Write("power.resume-commit-superseded", new { state = state.State, attempt = attemptId });
                return;
            }
            KeepAutomaticResumeState();
            var committedResume = false;
            lock (gate)
            {
                if (!stopped
                    && operation is not null
                    && ReferenceEquals(activeResumeOperation, operation)
                    && Volatile.Read(ref powerEpoch) == epochAtStart
                    && !SuspendProtectionPending)
                {
                    automaticResumeInProgress = false;
                    automaticResumeResult = true;
                    suspendedCurve = null;
                    state.PowerState = "On";
                    state.State = "Ready";
                    state.LastError = null;
                    state.PowerOperationStatus = "completed";
                    state.PowerOperationOutcome = "restored";
                    // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                    RecordResumeTerminalLocked(attemptId, "completed", "restored");
                    // R1（裁决 §3.2.2/§3.2.3）：走到本分支即等价满足全部前件——
                    // operation 仍为当前归属、`powerEpoch == epochAtStart`（未被新睡眠取代）、
                    // 未 stopped、无待处理睡眠保护，且本次 Enable 已成功返回（失败会走 catch）。
                    // 因此在此**窄撤销本 worker 自己的占位租约**，并保持已恢复的
                    // activeCurve / 硬件写授权 / Host 控制责任：不 RestoreHardware、
                    // 不转 AwaitingControl、不伪造客户端租约、不清后来客户端取得的租约。
                    RevokeAutomaticResumePlaceholderLeaseLocked(attemptId);
                    // 第一批返修：本 worker 退出——注销自身身份（避免延迟任务误认归属）。
                    if (ReferenceEquals(activeResumeOperation, operation)) activeResumeOperation = null;
                    committedResume = true;
                }
                else
                {
                    // 第十轮返修（P1-B）：版本化门已保证"新睡眠后旧解除不会放行"（无需补回）；
                    // 此处仅结算本操作并放弃提交。
                    if (activeResumeOperation is null || ReferenceEquals(activeResumeOperation, operation)) automaticResumeInProgress = false;
                    state.PowerOperationStatus = "superseded";
                    // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                    RecordResumeTerminalLocked(attemptId, "superseded", null);
                }
            }
            // R1（裁决 §3.2.7）：成功事件只属**真正的提交分支**——superseded 分支
            // 过去也会跑到这里输出 success（与本 worker 的真实终态不符）。
            if (committedResume)
                diagnostics.Write("power.resume-auto-rebuild.success", new
                {
                    state = state.State,
                    attempt = attemptId,
                    // G-1（2026-09-27 消费侧取证）：恢复提交这一拍带出 HC 逐轮收据（只读、不改判定）。
                    hcReceipts = realBackend?.HcReceiptsEvidence,
                });
        }
        catch (Exception ex)
        {
            lock (gate)
            {
                // HC parity: a suspend boundary may close the device while
                // this background rebuild is in flight (HC's SystemReady Open
                // task has no sleep gate and Close is synchronous). The
                // interruption is a benign skip — never FaultLocked, never a
                // recovery retry; the next SystemReady re-runs the F5.
                if (stopped || state.CloseCalled ||
                    state.PowerState == "Suspended" || state.PowerState == "Suspending")
                {
                    automaticResumeInProgress = false;
                    // 第一批：被新睡眠/关闭取代——完成记录不得声称恢复。
                    state.PowerOperationStatus = "superseded";
                    // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                    RecordResumeTerminalLocked(attemptId, "superseded", null);
                    return;
                }
                // 第一批返修（P1#3）：失败结论同样必须属于当前归属。
                // 第十二轮返修（P2）：被睡眠保护正常拒绝（待办仍生效）⇒ 这是
                // 正常取消（superseded），不是恢复故障——供 native 区分取消/故障/重试。
                if (SuspendProtectionPending)
                {
                    automaticResumeInProgress = false;
                    if (ReferenceEquals(activeResumeOperation, operation)) activeResumeOperation = null;
                    state.PowerOperationStatus = "superseded";
                    // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                    RecordResumeTerminalLocked(attemptId, "superseded", null);
                    return;
                }
                if (operation is null || !ReferenceEquals(activeResumeOperation, operation))
                {
                    // 第一批返修（P2）：退出路径结算本操作的执行账目（无新接管时）。
                    if (activeResumeOperation is null || ReferenceEquals(activeResumeOperation, operation)) automaticResumeInProgress = false;
                    state.PowerOperationStatus = "superseded";
                    // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                    RecordResumeTerminalLocked(attemptId, "superseded", null);
                    return;
                }
                automaticResumeInProgress = false;
                automaticResumeResult = false;
                state.PowerOperationStatus = "failed";
                // 第二十一轮返修（P1）：结算本 attempt 终态（等待者隔离）。
                RecordResumeTerminalLocked(attemptId, "failed", null);
                // 第一批返修：本 worker 退出——注销自身身份（避免延迟任务误认归属）。
                if (ReferenceEquals(activeResumeOperation, operation)) activeResumeOperation = null;
                state.UnknownState = HasLiveHardwareSession();
                state.State = state.UnknownState ? "FaultLocked" : "AwaitingControl";
                state.PowerState = state.UnknownState ? "Unknown" : "On";
                state.LastError = $"HC_RESUME_REBUILD_FAILED: {ExceptionText(ex)}";
                diagnostics.Write("power.resume-auto-rebuild.failure", new
                {
                    state = state.State,
                    attempt = attemptId,
                    error = state.LastError,
                });
                if (state.UnknownState) ScheduleRecoveryRetry();
            }
        }
        finally
        {
            // R1（裁决 §3.2.7）：非提交（失败/superseded/被睡眠取代）路径**只结算本 attempt**，
            // 不撤销任何租约与预算；这里只注销本 worker 的占位身份记录（若提交分支已撤销
            // 过，此调用为空操作）。放在接续消费之前，避免覆盖接续 worker 自己登记的租约身份。
            ForgetAutomaticResumePlaceholderLease(attemptId, "worker-exit-without-commit");
            // Clear the internal bypass after the final state transition. A
            // later API request must observe Ready/AwaitingControl and never
            // inherit the resume worker's admission privilege.
            if (Volatile.Read(ref automaticResumeWorkerThreadId) == workerThreadId)
                Volatile.Write(ref automaticResumeWorkerThreadId, 0);
            // 第一批返修（P1#1）：接续的"读+决定+启动"与登记/清除共用同一把锁
            // （登记在 gate 内、取代在 SuspendUnlocked 的 gate 内）。
            // 判据只认登记标记：取代以"清点"为唯一判据——不得以 PowerState 判定
            // （登记时状态恰为 Suspended，用状态判定会把刚登记的新恢复丢掉）。
            lock (gate)
            {
                // 第一批返修（R3）：先在同一协议内发布"旧 worker 已释放归属"，
                // 再消费接续。此后到达的新 resume 看到 resumeWorkerActive==0
                // 会直接启动新任务，而不是登记一个没有消费者的标记——
                // 不再依赖 CLR 的 Task.IsCompleted（它不在本同步操作里）。
                resumeWorkerActive = 0;
                var pendingEpoch = Volatile.Read(ref resumeContinuationEpoch);
                // 第二十二轮（P1#1）：连同登记的稳定身份与授权归属一起消费。
                var pendingId = resumeContinuationId;
                var pendingStamp = resumeContinuationStamp;
                Volatile.Write(ref resumeContinuationEpoch, 0);
                resumeContinuationId = 0;
                resumeContinuationValue = 0;
                resumeContinuationStamp = -1;
                if (Interlocked.Exchange(ref resumeContinuationRequested, 0) != 0)
                {
                    if (stopped)
                    {
                        state.PowerOperationStatus = "superseded";
                        // 消费但未启动 attempt：留存该登记的显式终态（superseded）。
                        resumeConsumedContinuationId = pendingId;
                        resumeConsumedContinuationValue = pendingEpoch;
                        resumeConsumedContinuationStamp = pendingStamp;
                        resumeConsumedAttemptId = 0;
                    }
                    else
                    {
                        // StartAutomaticResumeUnlocked 内部会重新置 resumeWorkerActive=1。
                        diagnostics.Write("power.resume-continuation-resumed", new { state = state.State, continuationId = pendingId });
                        // 第十/二十二轮返修：携带登记时的取消版本 + 授权归属 + 登记身份；
                        // 若期间有新睡眠已宣布（授权已推进），新版校验会丢弃本次接续
                        // （不再清掉新睡眠的保护），等待者也会得到显式终态。
                        StartAutomaticResumeUnlocked(pendingEpoch, pendingStamp, pendingId);
                    }
                }
            }
        }
    }

    /**
     * R1（FAN-926R 唤醒租约裁决 §3.2.2–§3.2.4）：**窄撤销**恢复 worker 自己铸造的临时租约。
     *
     * 为什么不能直接用 `ClearLease()`：后者还会 `StopRecoveryRetry()`，把**其他**恢复周期的
     * 尝试次数、窗口起点、定时器与终态一起清零（§3.2.4 明令不得顺手重置）。本方法只做两件事：
     * ① 清掉"这一个"租约身份；② 只处置该租约自己的到期定时责任。
     *
     * 前件已在调用点（`CompleteAutomaticResume` 的提交分支）等价满足：operation 仍为当前归属、
     * `powerEpoch` 未被新睡眠推进、未 stopped、无待处理睡眠保护、本次 Enable 已成功返回（§3.2.2）。
     * 本方法仍自证"租约仍是我那一个"（§3.2.5）：若期间客户端已 acquire 到新租约，则只记证据不动它。
     *
     * 撤销后**不**调用 `RestoreHardware`、**不**转 `AwaitingControl`、**不**伪造客户端租约；
     * `activeCurve`、已授权的硬件写状态与 Host 控制责任全部保持（§3.2.3）。客户端仍须凭认证、
     * 当前实例/代际和自己的租约才能写入（§3.1：不授予旧客户端写权）。
     */
    private void RevokeAutomaticResumePlaceholderLeaseLocked(long attemptId)
    {
        var lease = state.Lease;
        var mine = automaticResumePlaceholderLeaseId is not null
            && lease is not null
            && string.Equals(lease.LeaseId, automaticResumePlaceholderLeaseId, StringComparison.Ordinal)
            && lease.Generation == automaticResumePlaceholderLeaseGeneration;
        if (!mine)
        {
            diagnostics.Write("power.resume-placeholder-lease-kept", new
            {
                attempt = attemptId,
                reason = lease is null ? "no-lease-present" : "lease-not-owned-by-resume-worker",
                controlResponsibility = "host-resume-intent",
                nextAdjustmentStillRequired = true,
            });
            automaticResumePlaceholderLeaseId = null;
            automaticResumePlaceholderLeaseGeneration = 0;
            return;
        }
        state.Lease = null;
        state.LeaseGeneration = null;
        leaseTimer?.Dispose();
        leaseTimer = null;
        diagnostics.Write("power.resume-placeholder-lease-revoked", new
        {
            attempt = attemptId,
            leaseGeneration = lease!.Generation,
            reason = "resume-commit-complete",
            controlResponsibility = "host-resume-intent",
            clientWritesAuthorized = false,
            nextAdjustmentStillRequired = true,
            state = state.State,
        });
        automaticResumePlaceholderLeaseId = null;
        automaticResumePlaceholderLeaseGeneration = 0;
    }

    /** R1（§3.2.7）：非提交路径只注销本 worker 的占位身份记录，不触碰任何租约/预算。 */
    private void ForgetAutomaticResumePlaceholderLease(long attemptId, string reason)
    {
        if (automaticResumePlaceholderLeaseId is null) return;
        automaticResumePlaceholderLeaseId = null;
        automaticResumePlaceholderLeaseGeneration = 0;
        diagnostics.Write("power.resume-placeholder-lease-kept", new
        {
            attempt = attemptId,
            reason,
            controlResponsibility = "host-resume-intent",
            nextAdjustmentStillRequired = true,
        });
    }

    /**
     * The HC SystemReady boundary is not complete when /api/resume merely
     * queued Open/OpenEvents.  Native wake admission uses this result so the
     * parent cannot publish Ready while the fan route is still rebuilding.
     */
    public Task<object> WaitForAutomaticResumeAsync(int timeoutMs = 15000) =>
        WaitForAutomaticResumeCoreAsync(timeoutMs, ResumeWaitBinding.Legacy);

    /**
     * 第二十一轮返修（P1，等待者隔离）：等待者关联版本——只报告"本操作"的终态。
     * - Pinned(attemptId)：本请求自己创建/执行的 attempt——按 attempt 关联判定
     *   （活体状态或单槽终态留存），绝不借用后续新操作的 completed；
     * - Chained(observedAttempt, acceptedEpoch)：deferred 请求（本次执行并入既有
     *   worker 的接续）——同一睡眠周期守卫 + 接续 attempt 终态；
     * - Legacy：既有全局语义（引擎级调用方/夹具不变）。
     */
    internal Task<object> WaitForAutomaticResumeAsync(int timeoutMs, ResumeWaitBinding binding) =>
        WaitForAutomaticResumeCoreAsync(timeoutMs, binding);

    private async Task<object> WaitForAutomaticResumeCoreAsync(int timeoutMs, ResumeWaitBinding binding)
    {
        var started = Stopwatch.GetTimestamp();
        while (true)
        {
            lock (gate)
            {
                if (binding.Chain)
                {
                    if (TryResolveChainedResumeUnlocked(binding, out var chained))
                        return chained!;
                }
                else if (binding.AttemptId >= 0)
                {
                    if (TryResolveResumeAttemptUnlocked(binding.AttemptId, out var pinned))
                        return pinned!;
                }
                else
                {
                    if (!automaticResumeInProgress)
                    {
                        if (automaticResumeResult == false || state.State == "FaultLocked" || state.UnknownState)
                            throw new FanApiException(409, "HC_RESUME_REBUILD_FAILED", "HC 风扇恢复未完成");
                        // 第十五轮返修：终态判定先于"无待办即可返回"——被取代的操作必须
                        // 以显式终态返回（superseded），"没有待办"不是"操作成功"的证据。
                        if (state.PowerOperationStatus == "superseded" &&
                            Volatile.Read(ref resumeContinuationRequested) == 0)
                            throw ResumeSupersededError();
                        // 第一批返修（P1#1）：仍有待接续的恢复（pending）或仍处于睡眠保护时，
                        // 不得报告"恢复已完成"——继续等待（有界于 timeoutMs）。
                        if (Volatile.Read(ref resumeContinuationRequested) == 0 &&
                            state.PowerState != "Suspended" &&
                            !SuspendProtectionPending)
                            return SnapshotUnlocked();
                    }
                }
            }
            if (Stopwatch.GetElapsedTime(started).TotalMilliseconds >= timeoutMs)
                throw new FanApiException(504, "HC_RESUME_REBUILD_TIMEOUT", "HC 风扇恢复超过等待窗口");
            await Task.Delay(100).ConfigureAwait(false);
        }
    }

    internal static FanApiException ResumeSupersededError() =>
        new(409, "HC_RESUME_SUPERSEDED", "HC 风扇恢复已被新睡眠取代，未完成");

    /** 第二十二轮返修（P1）：结果不可证（留存未命中/历史完成但当前已属他人）⇒ 显式过期，禁止猜。 */
    internal static FanApiException ResumeResultExpiredError() =>
        new(409, "HC_RESUME_RESULT_EXPIRED", "HC 风扇恢复操作的结果已过期或不可证明（无匹配留存）");

    /**
     * 第二十二轮返修（P1#1）：Chained（deferred）等待者解析——**只认登记身份/睡眠周期
     * 身份**，禁止用"当前 token 是否还在"或"最新 attempt 比我观察的大"推定归属。
     * 解析顺序（必须在 gate 内调用）：
     * ① 槽位仍挂着我的登记（ContinuationId 精确匹配；未带身份时按周期 (值,归属) 匹配）
     *    —— 仅当出现"外来保护"（不同周期）时才判定被新睡眠取代，否则继续等待；
     * ② 槽位挂着别人的登记 —— 同周期 ⇒ 同周期合并（继续等其终态）；不同周期 ⇒ superseded；
     * ③ 无挂起登记 —— 查两个留存槽：被结算（superseded）/ 被消费（启动 attempt）；
     * ④ 两个留存槽都不匹配 ⇒ 显式 expired（fail-closed，不猜 superseded）。
     */
    private bool TryResolveChainedResumeUnlocked(ResumeWaitBinding binding, out object? resolved)
    {
        resolved = null;
        // 周期身份比较统一走 SameSuspendCycle（发布/合并/消费/清理/等待解析同一套判据）；
        // 未携带归属（<0 = 审核夹具的 2 参形式）时退化为"同周期值"匹配。
        bool CycleMatches(long value, long stamp) => binding.AcceptedStamp < 0
            ? value == binding.AcceptedEpoch
            : SameSuspendCycle(value, stamp, binding.AcceptedEpoch, binding.AcceptedStamp);
        bool IdentityMatches(long id, long value, long stamp) => binding.ContinuationId > 0
            ? id == binding.ContinuationId
            : id > 0 && CycleMatches(value, stamp);

        if (Volatile.Read(ref resumeContinuationRequested) != 0)
        {
            if (IdentityMatches(resumeContinuationId, resumeContinuationValue, resumeContinuationStamp))
            {
                // ① 我的登记仍挂起：只有当保护已被推进到"别的周期"时才判定取代。
                var protection = Volatile.Read(ref suspendProtection);
                if (protection is not null && !CycleMatches(protection.Value, protection.OwnerGeneration))
                    throw ResumeSupersededError();
                return false;
            }
            // ② 挂起的是别人的登记：同周期 ⇒ 合并等待；不同周期 ⇒ 我的周期已被取代。
            if (CycleMatches(resumeContinuationValue, resumeContinuationStamp)) return false;
            throw ResumeSupersededError();
        }
        // ③ 被结算为 superseded（新睡眠取代了挂起登记）。
        if (IdentityMatches(resumeSettledContinuationId, resumeSettledContinuationValue, resumeSettledContinuationStamp))
            throw ResumeSupersededError();
        // ④ 被消费：按该消费启动的 attempt 解析（0 = 消费未启动 ⇒ superseded）。
        if (IdentityMatches(resumeConsumedContinuationId, resumeConsumedContinuationValue, resumeConsumedContinuationStamp))
        {
            if (resumeConsumedAttemptId <= 0) throw ResumeSupersededError();
            if (TryResolveResumeAttemptUnlocked(resumeConsumedAttemptId, out var chained))
            {
                resolved = chained;
                return true;
            }
            return false;
        }
        // ⑤ 无任何匹配留存：无法证明本请求的终态 ⇒ 显式过期（绝不借用新周期结果）。
        throw ResumeResultExpiredError();
    }

    /**
     * 第二十一轮返修（P1）：按 attempt 关联判定终态（必须在 gate 内调用）。
     * 返回 true ⇒ resolved 给出"本操作"的终态快照；false ⇒ 尚无本操作的终态
     * （等待者继续保持有界等待）。终态为"被取代/失败"时直接抛出对应错误。
     * 关键不变式：绝不读取"其它 attempt"的活体 completed 充当本操作结果。
     */
    private bool TryResolveResumeAttemptUnlocked(long attemptId, out object? resolved)
    {
        resolved = null;
        var currentAttempt = state.PowerOperationAttempt;
        if (currentAttempt == attemptId)
        {
            // 本 attempt 仍是最新 attempt：活体状态就是本操作的结算状态。
            if (state.PowerOperationStatus == "superseded") throw ResumeSupersededError();
            if (state.PowerOperationStatus == "failed" || automaticResumeResult == false ||
                state.State == "FaultLocked" || state.UnknownState)
                throw new FanApiException(409, "HC_RESUME_REBUILD_FAILED", "HC 风扇恢复未完成");
            if (!automaticResumeInProgress &&
                state.PowerOperationStatus == "completed" &&
                Volatile.Read(ref resumeContinuationRequested) == 0 &&
                state.PowerState != "Suspended" &&
                !SuspendProtectionPending)
            {
                resolved = SnapshotUnlocked();
                return true;
            }
            // 执行中 / 仍待接续（pending）/ 仍有睡眠保护：继续保持有界等待。
            return false;
        }
        if (currentAttempt > attemptId)
        {
            // 更新的 attempt 已存在 ⇒ 只能从单槽留存读取本 attempt 的终态。
            if (resumeTerminalAttempt == attemptId)
            {
                switch (resumeTerminalStatus)
                {
                    case "completed":
                        // 第二十二轮返修（审核第 4 点）：留存只证明"本操作当时完成"，
                        // 不能拿**当前**状态充当"本操作终态快照"（当前状态可能已属
                        // 更新的周期）⇒ 显式过期，不冒充本操作结果。
                        throw ResumeResultExpiredError();
                    case "failed":
                        throw new FanApiException(409, "HC_RESUME_REBUILD_FAILED", "HC 风扇恢复未完成");
                    default:
                        throw ResumeSupersededError();
                }
            }
            // 留存未命中：本 attempt 的终态不可证（可能是完成记录被覆盖）⇒ 显式过期；
            // 不得猜测 superseded，更不得借用新 attempt 的 completed。
            throw ResumeResultExpiredError();
        }
        // currentAttempt < attemptId：计数器单调，理论不可达——保持有界等待。
        return false;
    }

    private void KeepAutomaticResumeState()
    {
        lock (gate)
        {
            if (!stopped && !state.CloseCalled && state.PowerState == "On")
                state.State = "Resuming";
        }
    }

    public object Resume()
    {
        lock (gate)
        {
            EnsureNotStopped();
            if (state.UnknownState || state.State == "FaultLocked")
                throw new FanApiException(409, "FAULT_LOCKED", "Fan Host 处于故障锁定，必须先确认 OEM restore");
            // Resume is only valid after this Host has completed the suspend
            // boundary. Windows can deliver a duplicate/spurious resume
            // notification; treating it as a fresh session while Ready would
            // clear OpenCalled without releasing the still-active HC route.
            // That is a false safety state, so an out-of-boundary resume is a
            // strict no-op rather than a lifecycle transition.
            if (state.PowerState != "Suspended" || state.State != "Suspended")
            {
                diagnostics.Write("api.resume-ignored-not-suspended", new { state = state.State, state.PowerState, state.OpenCalled, state.HardwareWritesObserved });
                // 裁决 H4（2026-09-19）：no-op 仍是 HTTP 200 且引擎返回值保持原样
                // （HostState 快照，字段兼容）；"本次未发生真恢复"由 HTTP 层按
                // ResumeAdmission.Kind == "noop" 显式标注 resumeNoop/reason（N18）。
                return SnapshotUnlocked();
            }
            // 第十三/十九/二十二轮返修：在"接受点"绑定本次恢复所属的睡眠保护**授权**
            // （值 + 归属代次，一次读取同一不可变记录）——旧授权不得解除新睡眠保护。
            var authorization = SuspendProtectionAuthorizationSnapshot;
            StartAutomaticResumeUnlocked(authorization.Value, authorization.Stamp);
            return SnapshotUnlocked();
        }
    }

    /** Invoked directly by the Host's Windows power notification watcher. */
    public object ResumeForSystemPower(long powerGeneration = 0, long acceptedPendingEpoch = -1, long acceptedPendingStamp = -1) =>
        ResumeForSystemPowerWithAdmission(powerGeneration, acceptedPendingEpoch, acceptedPendingStamp).Snapshot!;

    /**
     * 第二十一/二十二轮返修（P1）：恢复入口的"接受裁决"版——与 ResumeForSystemPower
     * 完全相同的准入/绑定逻辑与副作用，额外返回本次调用产生了什么（ResumeAdmission），
     * 供 API 等待者做 operation/attempt 关联（只报告本操作终态）。
     */
    internal ResumeAdmission ResumeForSystemPowerWithAdmission(long powerGeneration = 0, long acceptedPendingEpoch = -1, long acceptedPendingStamp = -1)
    {
        lock (gate)
        {
            if (stopped) return new ResumeAdmission(SnapshotUnlocked(), 0, 0, "noop", 0);
            if (state.UnknownState || state.State == "FaultLocked") return new ResumeAdmission(SnapshotUnlocked(), 0, 0, "noop", 0);
            // See Resume(): never let a duplicate Windows notification erase
            // the engine's active-session evidence while software fan control
            // is still live.
            if (state.PowerState != "Suspended" || state.State != "Suspended")
            {
                diagnostics.Write("power.resume-ignored-not-suspended", new { state = state.State, state.PowerState, state.OpenCalled, state.HardwareWritesObserved });
                return new ResumeAdmission(SnapshotUnlocked(), 0, 0, "noop", 0);
            }
            // 第一批返修（P1#2）：仅在准入通过、本次恢复将真正执行之后才绑定转换身份。
            // no-op 路径不得把上一代的 completed 结果标注到新代次。
            if (powerGeneration > 0) state.PowerOperationGeneration = powerGeneration;
            // 第十三/十四/二十二轮返修：使用"入口接受点"绑定的待办授权（值 + 归属）；
            // -1（未传）才退回现场读；显式的 0 表示"接受时无待办"（CAS 0==0 语义）。
            return StartAutomaticResumeUnlocked(acceptedPendingEpoch, acceptedPendingStamp);
        }
    }

    public object Close()
    {
        Interlocked.Increment(ref closeEntryCount);
        BlockWritesForClose();
        // Claim the same CurrentDevice.Close boundary before taking `gate`.
        // HC has one Window_Closed close owner; this only closes the native
        // HTTP race window and does not alter the device's virtual sequence.
        Interlocked.Exchange(ref closeBoundaryClaimed, 1);
        if (Interlocked.CompareExchange(ref closeBoundaryInFlight, 1, 0) != 0)
            throw new FanApiException(409, "HC_CLOSE_PENDING", "HC Close 正在完成，已拒绝重复关闭请求");
        try
        {
            var selfTestDelayMs = Volatile.Read(ref closeOwnerSelfTestDelayMs);
            if (selfTestDelayMs > 0) Thread.Sleep(selfTestDelayMs);
            lock (gate)
            {
                diagnostics.Write("api.close.begin", new { state = state.State, hasLease = state.Lease is not null, state.OpenCalled, state.HardwareWritesObserved });
                if (stopped) return SnapshotUnlocked();
                // The native parent-exit endpoint has already assigned this
                // CurrentDevice.Close boundary to its resident recovery worker.
                // ProcessExit, /api/shutdown and a late UI close must observe that
                // worker rather than become a second serialized Close owner.
                if (Volatile.Read(ref parentExitHandoffQueued) != 0)
                {
                    diagnostics.Write("api.close.parent-exit-observed", new { state = state.State });
                    throw new FanApiException(409, "PARENT_EXIT_HANDOFF", "Parent exit 风扇恢复正在执行，已拒绝重复关闭请求");
                }
                // HC has one Window_Closed -> CurrentDevice.Close() boundary. A
                // returned transport timeout cannot cancel the underlying ACPI or
                // HID call, so all later close requests are observers until that
                // original virtual Close returns. Re-entering it was the direct
                // cause of the real-device close storm.
                if (state.CloseCalled && (state.HcCloseCleanupPending || realBackend?.OperationTimedOut == true))
                {
                    diagnostics.Write("api.close.pending-observed", new { state = state.State, state.HcCloseCleanupPending });
                    throw new FanApiException(409, "HC_CLOSE_PENDING", "HC Close 正在完成，已拒绝重复关闭请求");
                }
                // A caller-visible close is an explicit retry request after a
                // prior bounded window reached terminal FaultLocked.  It may
                // start one fresh 60-second window, while automatic timer
                // callbacks never reset their own cap.
                // FAN-925：它同时是**唯一**允许开启新故障周期的自动性豁免——
                // 自动重试 / 替代 Host 一律只能继承剩余预算。
                recoveryCycleExplicitRetryRequested = true;
                BeginExplicitRecoveryRetryWindow();
                state.CloseCalled = true;
                if (!RestoreHardware(close: true))
                {
                    state.State = state.HcCloseCleanupPending ? "AwaitingCloseCleanup" : "FaultLocked";
                    ScheduleRecoveryRetry();
                    throw new FanApiException(409,
                        state.HcCloseCleanupPending ? "HC_CLOSE_PENDING" : "OEM_RESTORE_FAILED",
                        state.HcCloseCleanupPending
                            ? $"HC Close 资源清理尚未返回，Host 保持运行等待完成；未报告关闭成功（{state.LastError}）"
                            : "OEM 风扇控制恢复未确认，Host 不退出，等待恢复重试");
                }
                ClearLease();
                suspendedCurve = null;
                state.State = "Stopped";
                stopped = true;
                diagnostics.Write("api.close.success", new { state = state.State, state.OemRestoreConfirmed });
                CompleteRecoveryCycleLocked("api-close-success");
                return SnapshotUnlocked();
            }
        }
        finally
        {
            Volatile.Write(ref closeBoundaryInFlight, 0);
        }
    }

    /**
     * Lock-free acknowledgement for the native application exit path.  It
     * closes write admission immediately, then hands OEM recovery to this
     * resident process.  The caller must not wait for the ACPI operation: an
     * unavailable firmware path must never prevent YeManCC itself from
     * exiting, while this Host remains alive to retry recovery.
     */
    public object BeginParentExitHandoff()
    {
        BlockWritesForClose();
        // §3（FAN-926 P1 / CP-07）：返回 recoveryAccepted=true **之前**必须先建立可核对的受理身份
        // （处理该请求的 Host 实例 + **真实**恢复周期 + scope）。旧实现直接读 recoveryCycle?.CycleId，
        // 干净的首次交接时周期还不存在 ⇒ 真的返回了 200 + recoveryAccepted 却**没有**
        // acceptedRecoveryCycleId，native 判 unbound 是对的。
        var acceptance = EnsureParentExitAcceptance();
        if (acceptance is null)
        {
            // 责任无法绑定（周期被拒/已终态/持久化不可用）⇒ **不报假接受**：native 保持
            // fail-closed，既不新开窗口，也不制造第二 owner。
            diagnostics.Write("parent-exit-handoff.unbound", new
            {
                acceptingHostInstanceId = diagnostics.HostInstanceId,
                reason = "recovery-responsibility-unbound",
                state = state.State,
                hostWillRemainResident = !stopped,
            });
            return new
            {
                ok = true,
                recoveryAccepted = false,
                queuedNow = false,
                hostWillRemainResident = !stopped,
                acceptingHostInstanceId = diagnostics.HostInstanceId,
                acceptedRecoveryCycleId = recoveryCycle?.CycleId ?? string.Empty,
                acceptedAtUtc = DateTimeOffset.UtcNow,
                acceptanceScope = "not-accepted:recovery-responsibility-unbound",
                recoveryPhase = RecoveryPhaseText(),
            };
        }
        // A normal /api/close may already own the HC Close boundary. Do not
        // enqueue a second recovery worker while that serialized call is
        // still inside AsusACPI/HID cleanup; the worker would only observe
        // the timeout later, but its extra lifecycle owner created the
        // repeated shutdown/recovery storm seen on the ROG log.
        var cycle = Volatile.Read(ref recoveryCycle);
        var closeOwnerBusy = Volatile.Read(ref closeBoundaryClaimed) != 0 ||
            state.CloseCalled || state.HcCloseCleanupPending || realBackend?.OperationTimedOut == true;
        // §3.1：已完成/已终态按**真实阶段**返回幂等结果——既不新开 60 s 窗口，也不伪造
        // "仍驻留执行中"。
        var settled = stopped || cycle?.Completed == true || cycle?.Terminal == true;
        var queuedNow = false;
        if (closeOwnerBusy || settled)
        {
            diagnostics.Write(
                settled ? "parent-exit-handoff.already-settled" : "parent-exit-handoff.existing-close-observed",
                new
                {
                    acceptingHostInstanceId = acceptance.HostInstanceId,
                    acceptedRecoveryCycleId = acceptance.CycleId,
                    state = state.State,
                    closeBoundaryClaimed = Volatile.Read(ref closeBoundaryClaimed) != 0,
                    state.CloseCalled,
                    state.HcCloseCleanupPending,
                    operationTimedOut = realBackend?.OperationTimedOut == true,
                    settled,
                    recoveryPhase = RecoveryPhaseText(),
                });
        }
        else
        {
            queuedNow = Interlocked.Exchange(ref parentExitHandoffQueued, 1) == 0;
            diagnostics.Write(
                queuedNow ? "parent-exit-handoff.accepted" : "parent-exit-handoff.duplicate-observed",
                new
                {
                    acceptingHostInstanceId = acceptance.HostInstanceId,
                    acceptedRecoveryCycleId = acceptance.CycleId,
                    acceptanceScope = acceptance.Scope,
                    acceptanceBinding = acceptance.BindingKind,
                    acceptance.AcceptedAtUtc,
                    queuedNow,
                });
            if (queuedNow) _ = Task.Run(CompleteParentExitHandoff);
        }
        return new
        {
            ok = true,
            recoveryAccepted = true,
            queuedNow,
            hostWillRemainResident = !stopped,
            acceptingHostInstanceId = acceptance.HostInstanceId,
            acceptedRecoveryCycleId = acceptance.CycleId,
            acceptedAtUtc = acceptance.AcceptedAtUtc,
            acceptanceScope = acceptance.Scope,
            acceptanceBinding = acceptance.BindingKind,
            recoveryPhase = RecoveryPhaseText(),
        };
    }

    /**
     * §3（FAN-926 P1）：建立/复用本次交接的**受理身份**（Host 实例 + 真实恢复周期 + scope）。
     * - 幂等：同一进程内重复/并发交接返回**同一条**责任（一个 owner / 一个 worker / 一个终态）；
     * - 不取 gate：HC/ACPI 长持有期内也立即完成（H4），受理绝不靠抢锁赢；
     * - 返回 null ⇒ 责任无法绑定 ⇒ 调用方**不得**报"已接受"。
     */
    private ParentExitAcceptance? EnsureParentExitAcceptance()
    {
        lock (acceptanceGate)
        {
            if (parentExitAcceptance is not null) return parentExitAcceptance;
            bool cycleOk;
            acceptanceFastPathActive = true;
            try { cycleOk = EnsureRecoveryCycleLocked("parent-exit-handoff"); }
            finally { acceptanceFastPathActive = false; }
            if (!cycleOk) return null;
            var cycle = recoveryCycle;
            if (cycle is null || string.IsNullOrEmpty(cycle.CycleId)) return null;
            var acceptance = new ParentExitAcceptance(
                diagnostics.HostInstanceId,
                cycle.CycleId,
                recoveryCycleInherited ? "inherited-recovery-cycle" : "established-recovery-cycle",
                ParentExitAcceptanceScope,
                options.ParentPid ?? 0,
                DateTimeOffset.UtcNow);
            parentExitAcceptance = acceptance;
            diagnostics.Write("parent-exit-handoff.bound", new
            {
                acceptance.HostInstanceId,
                acceptance.CycleId,
                acceptance.BindingKind,
                acceptance.Scope,
                acceptance.ParentPid,
                acceptance.AcceptedAtUtc,
                rule = "recoveryAccepted=true may only come from this realised acceptance",
            });
            return acceptance;
        }
    }

    /** §3.1：受理的**真实阶段**——绝不把"已接受"或"已排队"说成"恢复已完成"。 */
    private string RecoveryPhaseText()
    {
        if (stopped) return "host-stopped";
        var cycle = Volatile.Read(ref recoveryCycle);
        if (cycle is null) return "accepted-no-cycle";
        if (cycle.Completed) return "recovery-completed";
        if (cycle.Terminal) return "recovery-terminal";
        return Volatile.Read(ref parentExitHandoffQueued) != 0
            ? "recovery-executing"
            : "recovery-accepted-not-started";
    }

    /** §5.1：本引擎当前恢复周期 ID（只读；无周期时为 null）。 */
    internal string? RecoveryCycleIdForReport => recoveryCycle?.CycleId;
    /** §3（FAN-926 P1）：受理身份只读视图（自测核对 ACK ↔ worker ↔ 终态同一条责任）。 */
    internal string? ParentExitAcceptanceCycleForSelfTest => Volatile.Read(ref parentExitAcceptance)?.CycleId;
    internal string? ParentExitAcceptanceHostForSelfTest => Volatile.Read(ref parentExitAcceptance)?.HostInstanceId;
    internal string? ParentExitAcceptanceBindingForSelfTest => Volatile.Read(ref parentExitAcceptance)?.BindingKind;
    internal string RecoveryPhaseForSelfTest => RecoveryPhaseText();
    internal DateTimeOffset? ParentExitAcceptanceAtForSelfTest =>
        Volatile.Read(ref parentExitAcceptance)?.AcceptedAtUtc;

    /**
     * 仅自测（§3.1 负例）：让"本 episode 已终态 ⇒ 责任无法绑定"可复现。
     * 与生产同一条路径建立周期并置终态，不改任何产品行为。
     */
    internal void ForceTerminalRecoveryCycleForSelfTest(string reason)
    {
        lock (gate)
        {
            lock (acceptanceGate)
            {
                recoveryCycle = NewRecoveryCycleLocked(options.ParentPid ?? 0, "selftest-terminal:" + reason);
                recoveryCycleInherited = false;
                MarkRecoveryCycleTerminalLocked(reason);
            }
        }
    }

    /**
     * 仅自测（§3.1 H3）：让"已有 Close owner 占着 HC Close 边界、但尚未进终态"可复现，
     * 用于区分"观察同一条责任"与"又开第二个 worker"这两件事。不改产品行为。
     */
    internal void MarkCloseBoundaryClaimedForSelfTest() => Interlocked.Exchange(ref closeBoundaryClaimed, 1);

    private void CompleteParentExitHandoff()
    {
        lock (gate)
        {
            // §5.1（FAN-926 P1）：worker 行只需补**阶段**。"谁执行、结算归谁"已经由诊断上下文
            // （每行都带的 `hostInstanceId` + `context.recoveryCycle.cycleId`）导出，
            // 这里绝不重复第二份同一事实（否则两处会漂移）。
            if (stopped) return;
            BeginExplicitRecoveryRetryWindow();
            state.CloseCalled = true;
            diagnostics.Write("parent-exit-handoff.recovery-begin",
                new { state = state.State, recoveryPhase = RecoveryPhaseText() });
            if (RestoreHardware(close: true))
            {
                ClearLease();
                suspendedCurve = null;
                state.State = "Stopped";
                stopped = true;
                CompleteRecoveryCycleLocked("parent-exit-recovery-confirmed");
                diagnostics.Write("parent-exit-handoff.recovery-confirmed",
                    new { recoveryPhase = RecoveryPhaseText() });
                return;
            }
            state.State = state.HcCloseCleanupPending ? "AwaitingCloseCleanup" : "FaultLocked";
            ScheduleRecoveryRetry();
            diagnostics.Write("parent-exit-handoff.recovery-deferred",
                new { state = state.State, state.LastError, recoveryPhase = RecoveryPhaseText() });
        }
    }

    private void RejectUnsupported()
    {
        throw new FanApiException(409, "FAN_UNSUPPORTED", "风扇不支持");
    }

    private void EnsureNotStopped()
    {
        if (stopped) throw new FanApiException(409, "HOST_STOPPED", "Fan Host 已停止");
    }

    private void EnsureControlAvailable()
    {
        if (Volatile.Read(ref closeWriteBlocked) != 0)
            throw new FanApiException(409, "HOST_CLOSING", "Fan Host 正在关闭，禁止新的风扇接管");
        // 裁决 H3（N15，2026-09-19）：FaultLocked 判定必须**先于**睡眠保护令牌。
        // 令牌在失败路径上可能滞留且无超时；若先判令牌，应用内只能看到
        // POWER_SUSPENDING（看起来像"系统正在睡眠"），看不到真正原因 FAULT_LOCKED，
        // 也找不到释放路径。错误码必须是 FAULT_LOCKED。
        // D5（FAN-926R 裁决 §3）：FaultLocked 仍是默认拒绝，只有**唯一恢复 owner** 在
        // 自己的一次内部恢复动作期间持受限准入（见 TryGrantInternalRecoveryAdmission）。
        // 这不是全局放宽：公有 enable/用户写入、以及所有非 owner 调用者拿不到该准入，
        // 其余门（关闭中/睡眠保护/清理未结/挂起/恢复中）对 owner 也**照常生效**。
        if (!internalRecoveryAdmissionActive && (state.UnknownState || state.State == "FaultLocked"))
            throw new FanApiException(409, "FAULT_LOCKED", "Fan Host 处于故障锁定，必须先确认 OEM restore");
        if (SuspendProtectionPending)
            throw new FanApiException(409, "POWER_SUSPENDING", "系统正在进入睡眠，禁止新的风扇接管");
        if (state.HcCloseCleanupPending)
            throw new FanApiException(409, "HC_CLOSE_PENDING", "HC 资源清理仍在完成，暂时禁止重新接管风扇");
        if (state.State == "Suspending" || state.PowerState == "Suspending")
            throw new FanApiException(409, "POWER_SUSPENDING", "系统正在进入睡眠，禁止新的风扇接管");
        if (state.State == "Suspended" || state.PowerState == "Suspended")
            throw new FanApiException(409, "POWER_SUSPENDED", "系统处于睡眠状态，禁止重新接管风扇");
        var resumeWorker = Volatile.Read(ref automaticResumeWorkerThreadId) == Environment.CurrentManagedThreadId;
        if (!resumeWorker && (automaticResumeInProgress || state.State == "Resuming"))
            throw new FanApiException(409, "POWER_RESUMING", "系统刚从睡眠恢复，HC 风扇会话正在重建");
    }

    private void BlockWritesForClose()
    {
        // Like the sleep boundary, this is deliberately lock-free. An EC/ACPI
        // call already in progress cannot be cancelled by HC, but no later
        // temperature callback or API enable may begin after Close is asked.
        Volatile.Write(ref closeWriteBlocked, 1);
        realBackend?.BlockWritesForClose();
    }

    private void EnsureLeaseFromBody(JsonElement body, bool optional = false)
    {
        if (!body.TryGetProperty("leaseId", out var value) || value.ValueKind != JsonValueKind.String)
        {
            if (optional) return;
            throw new FanApiException(409, "LEASE_REQUIRED", "需要有效 Fan lease");
        }
        EnsureLease(value.GetString()!);
    }

    private void EnsureLease(string leaseId)
    {
        lock (gate)
        {
            if (state.Lease is null)
                throw new FanApiException(409, "LEASE_INVALID", "Fan lease 已失效");

            // A stale or foreign token must never clear the current owner's
            // lease. Only the owner of an expired lease may trigger the
            // emergency restore attempt, and the lease is retained if restore
            // is not confirmed so that /api/close can retry safely.
            if (state.Lease.LeaseId != leaseId)
                throw new FanApiException(409, "LEASE_INVALID", "Fan lease 已失效");

            if (state.Lease.ExpiresAtMonoMs <= MonoMs())
            {
                // Lease expiry follows HC's Hardware-profile handoff. Only a
                // sleep or process-exit boundary owns the virtual Close().
                if (RestoreHardware(close: false))
                {
                    ClearLease();
                    state.State = "AwaitingControl";
                }
                else { state.State = "FaultLocked"; ScheduleRecoveryRetry(); }
                throw new FanApiException(409, "LEASE_INVALID", "Fan lease 已失效");
            }
        }
    }

    private void LogIgnoredLeaseForSafetyCleanup(JsonElement body, string operation)
    {
        // Never log the token itself. It is unneeded to diagnose why cleanup
        // happened and must not be written to disk.
        var supplied = body.TryGetProperty("leaseId", out var value) && value.ValueKind == JsonValueKind.String;
        var matchesCurrent = supplied && state.Lease is not null && string.Equals(value.GetString(), state.Lease.LeaseId, StringComparison.Ordinal);
        var expired = state.Lease is not null && state.Lease.ExpiresAtMonoMs <= MonoMs();
        diagnostics.Write("api.safety-cleanup-lease-bypassed", new { operation, supplied, hasCurrentLease = state.Lease is not null, matchesCurrent, expired });
    }

    private void ExpireLease(string callbackLeaseId, long callbackLeaseGeneration)
    {
        lock (gate)
        {
            // R1（FAN-926R 唤醒租约裁决 §3.2.5）：**迟到/被取代**的到期回调只记账。
            // 回调只能处置"创建它的那个租约"；租约已被替换（新客户端 acquire、恢复 worker
            // 撤销占位租约后的再获取）或已不存在时，一律不得执行交还默认模式，
            // 也不得改动新恢复周期的任何预算。
            if (state.Lease is null ||
                !string.Equals(state.Lease.LeaseId, callbackLeaseId, StringComparison.Ordinal) ||
                state.Lease.Generation != callbackLeaseGeneration)
            {
                diagnostics.Write("lease.expiry-callback-stale", new
                {
                    callbackGeneration = callbackLeaseGeneration,
                    current = state.Lease is null ? "none" : "replaced",
                    state = state.State,
                });
                return;
            }
            if (state.Lease.ExpiresAtMonoMs <= MonoMs())
            {
                // The HC SystemReady rebuild owns Open/OpenEvents/lease/Enable
                // as one serialized transaction. An expiry callback must not
                // restore OEM halfway through that transaction, otherwise the
                // worker can finish as Ready with the lease already gone.
                if (automaticResumeInProgress || state.State == "Resuming" || state.PowerState == "Resuming")
                {
                    diagnostics.Write("lease.expiry-deferred-during-resume", new
                    {
                        state = state.State,
                        powerState = state.PowerState,
                        openCalled = state.OpenCalled,
                        openEventsCalled = state.OpenEventsCalled,
                    });
                    leaseTimer?.Change(1000, Timeout.Infinite);
                    return;
                }
                // The expired-token guard is the same resident lease boundary
                // as Disable/Release; do not dispose HC resources here.
                // R1（§3.2.9）：本次释放的**责任来源**必须可判读——只有"租约到期"这一条是
                // 客户端租约安全策略；L1 用它证明占位租约撤销后不再有该来源的 restore。
                if (RestoreHardware(close: false, cause: "lease-expiry"))
                {
                    ClearLease();
                    state.State = state.UnknownState ? "FaultLocked" : "AwaitingControl";
                }
                else { state.State = "FaultLocked"; ScheduleRecoveryRetry(); }
            }
        }
    }

    // Strict HC SystemPending is not a profile handoff. It freezes local
    // writes, preserves only the desired curve in memory, and delegates the
    // physical teardown to CurrentDevice.Close(). HC exposes no generic
    // post-Close OEM/EC acknowledgement, so that evidence is deliberately
    // recorded as not-observed instead of being manufactured from an earlier
    // Hardware callback.
    /**
     * 裁决 H1（2026-09-19）：SystemPending close owner 是否可以**完全跳过** HC 清理。
     * 这是判据 C1-C7 的引擎侧实现（唯一实现；诊断/自测/短路共用）。任何条件不满足即
     * 不可短路 —— 宁可变慢（真实 Close）也不得伪造"未进入即已清洁"，静默跳过真实
     * 的 HC 资源所有权。
     *
     * C1  未成功进入 Open/OpenEvents：!OpenEventsCalled && !hcOpenEventsInvoked
     * C2  HC Open 调用从未开始（未越过 route override 边界）：!HcCloseIsOwed
     *     （= !IsOpen && !(openAttempted && hcOpenInvocationStarted)）
     * C3  未交错 HC 资源所有权：!HardwareWritesObserved、无 route marker、无 device 引用、无 lease
     * C4  未观测到硬件写入（与 C3 同源，按裁决要求独立列出）：!HardwareWritesObserved
     * C5  Host IsOpen false，且 HC 侧读数未读到时不阻塞（Safe 默认即真）
     * C6  同 C2（Open 已开始 ⇒ 一律不得短路的禁区条款，由 HcCloseIsOwed 覆盖）
     * C7  未曾发起/挂起 Close：!CloseCalled && !HcCloseCleanupPending
     *
     * return：true=未进入 HC 会话，可短路（不调 Close、不置 CLOSE_PENDING、不启动
     * retry，直接完成 Suspended）；false=进入过会话，必须走真实 Close/cleanup 确认。
     */
    internal bool HcSessionNeverEntered()
    {
        if (state.CloseCalled || state.HcCloseCleanupPending) return false;        // C7
        if (HcCloseIsOwed()) return false;                                          // C2/C6
        if (state.OpenEventsCalled) return false;                                   // C1
        if (realBackend?.HcOpenEventsInvoked == true) return false;                 // C1 (backend)
        if (state.HardwareWritesObserved) return false;                             // C3/C4
        if (realBackend?.HasSessionDeviceReference == true) return false;           // C3
        if (state.Lease is not null) return false;                                  // C3 (lease path is ownership)
        // C3 route marker：route marker 与 device reference 同置同清；引用已验空，
        // marker 亦为空（保留判据以防未来两者解耦）。
        var marker = realBackend?.SessionRouteMarker;
        if (marker is not null) return false;                                       // C3
        // C5：Host 侧 IsOpen 恒 false（Safe 默认）；HC 侧读数仅在"读得到 true"时
        // 才打断判定（null 未知、false 均不阻塞，见 HcDeviceIsOpenObserved 契约）。
        if (realBackend?.IsOpen == true) return false;
        var hcIsOpen = realBackend?.HcDeviceIsOpenObserved;
        if (hcIsOpen == true) return false;
        return true;
    }

    /**
     * 裁决 H1/C2：本 Host 是否仍欠一次 HC 虚拟 Close 边界。Safe 构建（realBackend null）
     * 恒 false ⇒ 默认态可短路；Real 构建委托给 HC 侧同一表达式（见 RealHcBackend.HcCloseIsOwed）。
     */
    private bool HcCloseIsOwed() => realBackend?.HcCloseIsOwed == true;

    internal bool HcSessionNeverEnteredForSelfTest() => HcSessionNeverEntered();

    private bool CloseForSystemPending()
    {
        if (HcSessionNeverEntered())
        {
            // 裁决 H1（P1 A/B）：从未进入 Open/OpenEvents、无硬件写入、无 lease、
            // 无 Close 义务时，不存在任何待清理的 HC 资源。不调用 HC device.Close、
            // 不进入 HC_CLOSE_PENDING、不启动 recovery retry，直接完成 Suspended。
            // 禁止伪造 OEM restore / HC virtual close / Manager cleanup confirmed——
            // 据此只写诊断，不动任何证据字段。
            diagnostics.Write("power.suspend-no-session-complete", new
            {
                result = "not-entered-no-cleanup-required",
                sessionNeverEntered = true,
                closeOwed = false,
                hcDeviceIsOpen = realBackend?.HcDeviceIsOpenObserved is bool o ? (o ? "true" : "false") : "unknown",
                openCalled = state.OpenCalled,
                openEventsCalled = state.OpenEventsCalled,
                hcOpenEventsInvoked = realBackend?.HcOpenEventsInvoked ?? false,
                hardwareWritesObserved = state.HardwareWritesObserved,
                // A：从未调用 Open；B：Open 已尝试但未越过 HC 调用边界（前置检查失败）。
                reason = state.OpenCalled ? "pre-open-check-failed" : "no-hc-resource-ownership-crossed",
            });
            state.HcCloseCleanupPending = false;
            return true;
        }
        recoveryRetryUsesSystemPendingClose = true;
        // D1（FAN-926R 裁决 §3）：睡眠边界不再一律 Close-first。已有授权、有写历史且
        // 会话仍可操作时，在**同一生命周期 owner 内**、关闭 HC **之前**有界执行一次现成
        // 默认模式恢复（HC Hardware/RestoreOem），再进入 HC Close。会话已丢失/已不可操作
        // 时**不得**为取证新 Open 或反复写默认表，只记 not-attempted 并做可行清理。
        // 意图已由调用方冻结在 `suspendedCurve`（本行之后的 StopCurveTimer 只清 activeCurve）。
        var preCloseReleaseAttempted = state.HardwareWritesObserved
            && realBackend is not null
            && (realBackend.IsOpen || state.OpenCalled)
            && !state.HcCloseCleanupPending;
        if (!preCloseReleaseAttempted)
        {
            // 本周期**没有**发起释放动作：必须显式回落为 not-attempted，否则后端里
            // 上一次 enable 的 scope 收据会被当成"本周期已释放"（假成功）。
            state.OemReleaseActionKind = "not-attempted";
            state.OemReleaseActionEvidence = state.HardwareWritesObserved
                ? "suspend:no-usable-session-release-not-attempted"
                : "suspend:no-write-history-release-not-applicable";
        }
        diagnostics.Write("power.suspend-preclose-release-decision", new
        {
            hardwareWritesObserved = state.HardwareWritesObserved,
            backendIsOpen = realBackend?.IsOpen ?? false,
            openCalled = state.OpenCalled,
            hcCloseCleanupPending = state.HcCloseCleanupPending,
            route = realBackend?.Route?.Kind.ToString(),
            decision = preCloseReleaseAttempted
                ? "bounded-release-before-close"
                : "not-attempted-session-not-usable",
            // 三轴分列（裁决 §3-D3）：本事件只判"是否发起"，不代表命令送达或物理接管。
            releaseAction = "decided-by-this-event-only-if-attempted",
            hcLifecycle = "not-decided-here",
            physicalOwnership = "unknown-not-a-release-decision-input",
        });
        StopCurveTimer();
        diagnostics.Write("power.suspend-hc-close-first-begin", new
        {
            state = state.State,
            powerState = state.PowerState,
            state.HardwareWritesObserved,
            // 本事件名来自"一律 Close-first"的旧要求，已被本裁决定点取代；顺序真值见
            // `order` 与 `power.suspend-preclose-release-decision`。名字暂留供既有消费者。
            order = preCloseReleaseAttempted ? "release-then-close" : "close-only",
        });
        return CloseHcSessionForLifecycle(
            stopDeviceManager: false,
            skipOemRestore: !preCloseReleaseAttempted,
            // D1/D3：证据**不再清除**——三轴分列记账，清理完成不能顶替释放。
            clearOemEvidence: false);
    }

    private void MarkSystemPendingOemEvidenceNotObserved()
    {
        state.OemRestoreConfirmed = false;
        state.HcRestoreCallbackReturned = false;
        state.OemPhysicalOwnershipConfirmed = false;
        state.OemRestoreEvidence = "not-observed";
        state.OemOwnershipStatus = "hc-close-returned-physical-unknown";
    }

    // This common close owner also serves non-F4 recovery/exit paths. Those
    // explicit profile handoffs may still request an HC Hardware callback; the
    // SystemPending caller above passes skipOemRestore/clearOemEvidence so its
    // order remains exactly HC Close-first.
    private bool CloseHcSessionForLifecycle(
        bool stopDeviceManager,
        bool skipOemRestore = false,
        bool clearOemEvidence = false)
    {
        if (realBackend is null)
        {
            if (clearOemEvidence)
                MarkSystemPendingOemEvidenceNotObserved();
            return !state.HardwareWritesObserved;
        }
        try
        {
            diagnostics.Write("restore.close-hc-begin", new
            {
                stopDeviceManager,
                skipOemRestore,
                clearOemEvidence,
                state.OpenCalled,
                state.HardwareWritesEnabled,
                state.OemRestoreConfirmed,
            });

            if (clearOemEvidence)
                MarkSystemPendingOemEvidenceNotObserved();

            // Non-F4 recovery/exit may explicitly release a profile while the
            // device remains open. SystemPending never enters this branch: its
            // Close-first path above must not write OEM/default curves before
            // CurrentDevice.Close().
            if (!skipOemRestore && state.HardwareWritesObserved && !state.OemRestoreConfirmed)
            {
                diagnostics.Write("restore.close-hc-oem-restore-begin", new { source = "restore-before-hc-close" });
                realBackend.RestoreOem();
                state.OemRestoreEvidence = realBackend.OemRestoreEvidence;
                state.OemOwnershipStatus = realBackend.OemOwnershipStatus;
                state.OemPhysicalOwnershipConfirmed = string.Equals(
                    realBackend.OemOwnershipStatus,
                    "hc-default-table-readback-confirmed",
                    StringComparison.Ordinal);
                // HC treats the returned Hardware callback as the release
                // boundary. ASUS curve readback is optional evidence and is
                // never a prerequisite for Close().
                state.OemRestoreConfirmed = realBackend.OemRestoreVerified;
                state.HcRestoreCallbackReturned = realBackend.OemRestoreVerified;
                state.OemReleaseActionKind = realBackend.OemReleaseActionKind;
                state.OemReleaseActionEvidence = realBackend.OemReleaseActionEvidence;
                state.HardwareWritesEnabled = false;
                diagnostics.Write("restore.close-hc-oem-restore-returned", new
                {
                    state.OemRestoreConfirmed,
                    state.OemPhysicalOwnershipConfirmed,
                    state.OemRestoreEvidence,
                    state.OemOwnershipStatus,
                });
            }

            // CurrentDevice.Close is the HC lifecycle boundary. No outer
            // precondition may imply that an OEM/default-curve write happened
            // first: strict SystemPending reaches this call directly.
            realBackend.Close(stopDeviceManager);
            if (clearOemEvidence)
            {
                MarkSystemPendingOemEvidenceNotObserved();
            }
            else
            {
                state.OemRestoreEvidence = realBackend.OemRestoreEvidence;
                state.OemOwnershipStatus = realBackend.OemOwnershipStatus;
                state.OemPhysicalOwnershipConfirmed = string.Equals(
                    realBackend.OemOwnershipStatus,
                    "hc-default-table-readback-confirmed",
                    StringComparison.Ordinal);
                state.OemRestoreConfirmed = realBackend.OemRestoreVerified;
                state.HcRestoreCallbackReturned = realBackend.OemRestoreVerified;
                state.OemReleaseActionKind = realBackend.OemReleaseActionKind;
                state.OemReleaseActionEvidence = realBackend.OemReleaseActionEvidence;
            }
            state.HcVirtualCloseReturned = realBackend.HcVirtualCloseReturned;
            state.HcDeviceManagerStopCompleted = realBackend.HcDeviceManagerStopCompleted;
            state.HcDeviceManagerStopInvoked = realBackend.HcDeviceManagerStopInvoked;
            state.HcManagerCleanupEvidence = realBackend.HcManagerCleanupEvidence;
            state.HcDeviceManagerLifecycle = realBackend.HcDeviceManagerLifecycle;
            state.HcManagerFactoryLifecycle = realBackend.HcManagerFactoryLifecycle;
            var hcCloseComplete = state.HcVirtualCloseReturned && realBackend.HcManagerCleanupConfirmed;
            if (!hcCloseComplete)
                throw new InvalidOperationException("HC Close 返回但生命周期边界未完整完成");
            // HC's Window_Closed and SystemPending clear their device session
            // once the virtual Close boundary returns. Do not require a
            // separate Hardware-profile callback here: HC uses that callback
            // only for profile ownership handoff while the device stays open.
            state.OpenCalled = false;
            state.OpenEventsCalled = false;
            state.HardwareWritesEnabled = false;
            state.UnknownState = false;
            state.HcCloseCleanupPending = false;
            state.LastError = null;

            // §3.4（FAN-925B）：`skipOemRestore` 与 HC 清理完整**最多**表示"该阶段只结算
            // 设备关闭"。它**不是**"已释放"的出口：旧写法用它整条绕过 `IsOemReleaseSafe`，
            // 使 route-lost 之后以"无需读回、收尾安全"对外，而那一轮一次释放动作都没做。
            // 现在只豁免"本轮确实没有写入历史"的诚实对照；有写历史而无释放动作证据 ⇒
            // **保留未结算责任**（如实标未证 + 记重开需求），仍允许同一 owner 在稳定路由上重开。
            var noWriteHistoryThisCycle = !state.HardwareWritesObserved;
            // §3.4／D4：唯一判定入口；调用点**没有**传清理/关闭边界的位置（入参已删）。
            var releaseSafe = RouteLostCloseIsRelease(
                state.HardwareWritesObserved,
                state.OemReleaseActionKind);
            if (!releaseSafe)
            {
                state.UnknownState = true;
                state.RecoveryReadbackRequired = true;
                state.LastError = skipOemRestore
                    ? "route-lost：释放动作未证，未结算责任保留（不宣称交还完成）"
                    : "HC 释放动作未证（无当次收据/未知/失败）；保持故障锁定等待恢复";
                diagnostics.Write("restore.close-hc-release-unproven", new
                {
                    skipOemRestore,
                    hcCloseComplete,
                    // D3：释放未证时三轴同样分列——清理完成不改变"释放未证"这一结论。
                    releaseAction = state.OemReleaseActionKind,
                    evidenceLevel = "none",
                    hcLifecycle = hcCloseComplete ? "close-boundary-complete" : "close-boundary-incomplete",
                    physicalOwnership = "unknown",
                    ownershipClaim = false,
                    noWriteHistoryThisCycle,
                    state.OemReleaseActionKind,
                    state.OemReleaseActionEvidence,
                    state.OemRestoreConfirmed,
                    state.OemPhysicalOwnershipConfirmed,
                    outcome = skipOemRestore
                        ? "unsettled-responsibility-retained; close-boundary-settled-only"
                        : "fault-locked-release-unproven",
                });
                if (skipOemRestore)
                {
                    // 关闭边界已结算，但释放责任未结算 ⇒ 仍要进入"等待重开"，
                    // 由 bridge/native 在同一故障周期预算内驱动重开（唯一 owner）。
                    MarkReopenRequiredLocked("close-route-lost-release-unproven");
                    return false;
                }
                state.State = "FaultLocked";
                state.PowerState = "Unknown";
                return false;
            }

            // 释放动作已证（或本周期确无写入历史）：读回要求随之收敛。
            state.RecoveryReadbackRequired = false;
            diagnostics.Write("restore.close-hc-success", new
            {
                stopDeviceManager,
                skipOemRestore,
                state.OemRestoreEvidence,
                state.OemOwnershipStatus,
                // D3（FAN-926R 裁决 §3）：三轴分列 + 证据等级。传输层收据**不**等于物理接管。
                releaseAction = state.OemReleaseActionKind,
                evidenceLevel = FanHostEngine.ParseReleaseAction(state.OemReleaseActionKind) == OemReleaseAction.Proven
                    ? "transport"
                    : "compat-route-or-none",
                hcLifecycle = hcCloseComplete ? "close-boundary-complete" : "close-boundary-incomplete",
                physicalOwnership = state.OemPhysicalOwnershipConfirmed ? "readback-confirmed" : "unknown-not-claimed",
                ownershipClaim = false,
                hcCloseComplete,
                hardwareCallbackReturned = state.OemRestoreConfirmed,
                state.HcVirtualCloseReturned,
                state.HcDeviceManagerStopCompleted,
                state.HcDeviceManagerLifecycle,
            });
            return true;
        }
        catch (Exception ex)
        {
            var timedOut = realBackend.OperationTimedOut;
            state.HardwareWritesEnabled = false;
            state.HcCloseCleanupPending = true;
            // FAN-936 R3: a throwing MSI Close may have cleared the backend's
            // release evidence (unbound/throwing hand-back) or kept a genuine bound
            // `ok` receipt (only the later handle/manager cleanup failed). Sync the
            // backend's *current* release accounting before re-deciding safety, so
            // the engine can never hold a stale proven over a cleared backend.
            if (realBackend.Route?.RestoreStrategy == FanRestoreStrategy.MsiHcDefaultRelease)
            {
                state.OemRestoreEvidence = realBackend.OemRestoreEvidence;
                state.OemOwnershipStatus = realBackend.OemOwnershipStatus;
                state.OemPhysicalOwnershipConfirmed = string.Equals(
                    realBackend.OemOwnershipStatus,
                    "hc-default-table-readback-confirmed",
                    StringComparison.Ordinal);
                state.OemRestoreConfirmed = realBackend.OemRestoreVerified;
                state.HcRestoreCallbackReturned = realBackend.OemRestoreVerified;
                state.OemReleaseActionKind = realBackend.OemReleaseActionKind;
                state.OemReleaseActionEvidence = realBackend.OemReleaseActionEvidence;
            }
            state.UnknownState = !IsOemReleaseSafe(
                state.HardwareWritesObserved,
                state.OemReleaseActionKind);
            state.RecoveryReadbackRequired = state.UnknownState;
            state.LastError = timedOut
                ? $"HC Close 资源清理超时，等待原调用返回后重试: {ExceptionText(ex)}"
                : $"HC Close 资源清理失败，等待重试: {ExceptionText(ex)}";
            // B4：route-lost 不是"HC 卡住"，是本产品第五道门抛的（HC 回函 D2）⇒ 结算 Close 边界后
            // **重开归 bridge**，宿主不得再空转被门挡住的 restore（每轮都必然同点失败）。
            if (!timedOut && IsHcRouteLoss(ex)) MarkReopenRequiredLocked("close-route-lost");
            diagnostics.Write(timedOut
                ? "restore.close-hc-timeout"
                : "restore.close-hc-failure", new
            {
                stopDeviceManager,
                timedOut,
                error = state.LastError,
                hcVirtualCloseReturned = realBackend.HcVirtualCloseReturned,
                hcDeviceManagerStopCompleted = realBackend.HcDeviceManagerStopCompleted,
                hcDeviceManagerStopInvoked = realBackend.HcDeviceManagerStopInvoked,
                hcManagerCleanupEvidence = realBackend.HcManagerCleanupEvidence,
                hcDeviceManagerLifecycle = realBackend.HcDeviceManagerLifecycle,
            });
            return false;
        }
    }

    // Lease loss is an emergency cleanup path.  It must not merely discard
    // the lease in memory while leaving HC software control active.
    private bool RestoreHardware(bool close, bool stopDeviceManager = true, bool skipOemRestore = false, string cause = "unspecified")
    {
        if (MockFanHandshakeFlag)
        {
            // MOCK（2026-09-15）：伪装 OEM 恢复完成（不写 EC）——enable 模拟
            // 写入后 release 必须能 restore，否则真实判据（写后无 HC restore
            // 回调）会 FaultLocked。
            state.HardwareWritesEnabled = false;
            state.HcRestoreCallbackReturned = true;
            state.OemPhysicalOwnershipConfirmed = true;
            state.OemRestoreConfirmed = true;
            // §3.1（FAN-925B）：mock 路径显式声明"释放动作已证"，否则新判据会（正确地）
            // 把这条只靠回调位的假成功判成 unknown。这里如实标 mock，不冒充真实收据。
            state.OemReleaseActionKind = "proven-by-scope-receipts";
            state.OemReleaseActionEvidence = "mock-fan-handshake: no hardware write path; release action asserted by test facility";
            state.OpenCalled = false;
            state.OpenEventsCalled = false;
            state.State = close ? "AwaitingCloseCleanup" : "AwaitingControl";
            // R1（§3.2.9）：mock 分支不写真实 `restore.begin`（它本来就不做真实清理），
            // 但"这次释放是谁发起的"同样必须可判读——否则沙箱里无法区分
            // "租约到期触发的释放"与其它来源，L1/L2 的负例就成了空断言。
            diagnostics.Write("restore.mock-applied", new { close, cause, state = state.State });
            return true;
        }
        StopCurveTimer();
        state.SetFanControlRestoreAttempted = true;
        diagnostics.Write("restore.begin", new { close, cause, state = state.State, state.OpenCalled, state.HardwareWritesObserved, state.OemRestoreConfirmed });
        if (realBackend?.OperationTimedOut == true)
        {
            if (state.OemRestoreConfirmed && !state.HardwareWritesEnabled)
            {
                state.OpenCalled = false;
                state.OpenEventsCalled = false;
                state.HcCloseCleanupPending = true;
                state.UnknownState = false;
                state.State = close ? "AwaitingCloseCleanup" : "FaultLocked";
                state.LastError = "HC 默认风扇表已写回；等待 HC Close 资源清理返回，不能报告关闭成功";
                diagnostics.Write("restore.deferred-close-cleanup-after-oem-restore", new { close });
                return false;
            }
            // HC has no supported cancellation primitive for an EC/ACPI call.
            // Do not queue restore behind that call or force-close its thread;
            // keep the Host fault-locked and retry only after its completion
            // callback has observed a real return.
            state.HardwareWritesEnabled = false;
            state.OemRestoreConfirmed = false;
            state.HcRestoreCallbackReturned = false;
            state.HcCloseCleanupPending = false;
            state.UnknownState = true;
            state.LastError = "HC_OPERATION_TIMEOUT: 等待未返回的 HC 调用结束后再恢复 OEM";
            diagnostics.Write("restore.deferred-hc-timeout", new { close });
            return false;
        }
        var backendSessionActive = realBackend?.IsOpen == true || realBackend?.OpenAttempted == true;
        if (realBackend is null || (!state.OpenCalled && !backendSessionActive))
        {
            // A failed write may have already driven HC's virtual Close()
            // boundary (for example an OpenEvents/Enable exception unwinds
            // through RecoverAfterHardwareFailure).  A returned virtual Close
            // is the complete resource boundary for this fan-only Host.
            // Historical HardwareWritesObserved must not
            // turn that safe, closed session into a permanent OEM restore
            // failure on the next observer-only recovery request.
            var completedHcClose = state.HcVirtualCloseReturned &&
                state.HcDeviceManagerStopCompleted &&
                state.HcManagerFactoryLifecycle == "Started" &&
                state.HcDeviceManagerLifecycle == "Started" &&
                !state.OpenCalled && !state.OpenEventsCalled &&
                !state.HcCloseCleanupPending && !state.HardwareWritesEnabled;
            // Keep `OemRestoreConfirmed` reserved for HC's Hardware callback;
            // a virtual Close is a separate lifecycle acknowledgement. The
            // optional ASUS readback remains diagnostic evidence only.
            var releaseConfirmed = IsOemReleaseSafe(
                state.HardwareWritesObserved,
                state.OemReleaseActionKind);
            state.HardwareWritesEnabled = false;
            state.UnknownState = !IsOemReleaseSafe(
                state.HardwareWritesObserved,
                state.OemReleaseActionKind);
            state.HcCloseCleanupPending = false;
            if (state.UnknownState)
            {
                state.State = "FaultLocked";
                state.RecoveryReadbackRequired = true;
                state.LastError = "HC OEM restore callback/Close 未返回；恢复仍需重试";
            }
            // D4（FAN-926R 裁决 §3）：旧事件名 `restore.not-required` 把两件不同事实混在一句
            // "无需恢复"里（名字说 not-required、实际可能是故障锁定）⇒ 拆为两件：
            //   ① 确无写历史/无会话      ⇒ not-applicable（不是失败，也不宣称交还）
            //   ② 有写历史但无活会话      ⇒ release-unproven-no-live-session（未证，不宣称交还）
            var noWriteHistory = !state.HardwareWritesObserved;
            diagnostics.Write(noWriteHistory
                ? "restore.not-applicable-no-write-history"
                : "restore.release-unproven-no-live-session", new
            {
                close,
                releaseConfirmed,
                hardwareWritesObserved = state.HardwareWritesObserved,
                oemRestoreConfirmed = state.OemRestoreConfirmed,
                oemPhysicalOwnershipConfirmed = state.OemPhysicalOwnershipConfirmed,
                completedHcClose,
                state = state.State,
                // D3（裁决 §3）：三轴分列——清理完成不是释放证明，物理接管始终不在此事件内宣称。
                releaseAction = state.OemReleaseActionKind,
                hcLifecycle = completedHcClose ? "close-boundary-complete" : "close-boundary-incomplete",
                physicalOwnership = "unknown-not-claimed",
                // D3：只有当次传输层收据才给出 evidenceLevel=transport；它**不**等于物理接管。
                evidenceLevel = FanHostEngine.ParseReleaseAction(state.OemReleaseActionKind) == OemReleaseAction.Proven
                    ? "transport"
                    : "none",
                ownershipClaim = false,
            });
            return releaseConfirmed;
        }

        if (close)
        {
            // Match the HC virtual device boundary. Profile handoff is used
            // for lease/disable; sleep and process exit go straight into the
            // device's virtual Close so route-specific ACPI/HID cleanup stays
            // inside the frozen HC implementation.
            // A lost HID/device marker is already outside HC's route-specific
            // Hardware callback contract.  The only safe owner in that state
            // is the HC virtual Close -> event unbind boundary; attempting a
            // second OEM callback first can re-enter AsusACPI/ACPI after the
            // route has disappeared and strand the partial session.
            return CloseHcSessionForLifecycle(stopDeviceManager, skipOemRestore);
        }

        // A confirmed Hardware callback is idempotent for release. Lease
        // release itself keeps HC open; only a full close/sleep boundary owns
        // the later virtual Close() phase. A later Enable() clears this
        // acknowledgement before its next HC software callback, so this
        // idempotence cannot suppress a real handoff.
        var hardwareAlreadyReleased = HasConfirmedOemRelease(state.OemRestoreConfirmed, state.HardwareWritesEnabled);
        if (hardwareAlreadyReleased)
        {
            // close=true has already taken CloseHcSessionForLifecycle. A lease or
            // disable handoff keeps HC open, so never call virtual Close here.
            state.HardwareWritesEnabled = false;
            state.UnknownState = !IsOemReleaseSafe(
                state.HardwareWritesObserved,
                state.OemReleaseActionKind);
            state.HcCloseCleanupPending = false;
            state.RecoveryReadbackRequired = state.UnknownState;
            state.LastError = state.UnknownState
                ? "HC OEM restore callback 未返回，保持故障锁定"
                : null;
            diagnostics.Write("restore.already-confirmed", new
            {
                close,
                state.OemRestoreConfirmed,
                state.OemOwnershipStatus,
                state.OemPhysicalOwnershipConfirmed,
                state.HcVirtualCloseReturned,
                state.HcDeviceManagerStopCompleted,
                state.HcDeviceManagerLifecycle,
            });
            return true;
        }

        // HC invokes the Hardware profile callback once. A callback failure
        // is retried only by the serialized recovery timer (with backoff),
        // never by an inner sleep/retry loop that can stall the UI or drive
        // the Host CPU while the firmware rejects the request.
        const int attempt = 1;
        try
        {
            realBackend.RestoreOem();
            state.HardwareWritesObserved = true;
            state.OemRestoreEvidence = realBackend.OemRestoreEvidence;
            state.OemOwnershipStatus = realBackend.OemOwnershipStatus;
            state.OemPhysicalOwnershipConfirmed = string.Equals(
                realBackend.OemOwnershipStatus,
                "hc-default-table-readback-confirmed",
                StringComparison.Ordinal);
            state.OemRestoreConfirmed = realBackend.OemRestoreVerified;
            state.HcRestoreCallbackReturned = realBackend.OemRestoreVerified;
            state.OemReleaseActionKind = realBackend.OemReleaseActionKind;
            state.OemReleaseActionEvidence = realBackend.OemReleaseActionEvidence;
            if (!state.OemRestoreConfirmed)
                throw new InvalidOperationException("HC OEM restore callback did not return");
            // This flag describes active software control, not historical
            // writes. Keep the historical observed bit for audit, but make
            // the live hardware-write signal false immediately after OEM
            // restore succeeds.
            state.HardwareWritesEnabled = false;
            state.UnknownState = !IsOemReleaseSafe(
                state.HardwareWritesObserved,
                state.OemReleaseActionKind);
            state.HcCloseCleanupPending = false;
            state.RecoveryReadbackRequired = state.UnknownState;
            state.LastError = state.UnknownState
                ? "HC OEM restore callback 未返回；禁止继续风扇写入"
                : null;
            diagnostics.Write("restore.success", new
            {
                attempt,
                close,
                state.OemRestoreConfirmed,
                state.OemOwnershipStatus,
                state.OemPhysicalOwnershipConfirmed,
                state.HcVirtualCloseReturned,
                state.HcDeviceManagerStopCompleted,
                state.HcDeviceManagerLifecycle,
            });
            return !state.UnknownState;
        }
        catch (Exception ex)
        {
            state.OemRestoreConfirmed = false;
            state.UnknownState = true;
            // FAN-936 §3.2.2/§3.2.5：本次释放未被认定为合格（fail-closed），但 backend
            // 已按路线收据语汇如实记录的**本次观测结论**仍须分栏进入快照，避免因失败路径
            // 未同步而把已观测到的 unknown 退化成 stale "none"（=把 unknown 写成 success 的反面）。
            // 绝不同步为"已确认"：OemRestoreConfirmed / OemPhysicalOwnershipConfirmed 保持 false。
            if (realBackend is not null)
            {
                state.OemRestoreEvidence = realBackend.OemRestoreEvidence;
                state.OemOwnershipStatus = realBackend.OemOwnershipStatus;
                state.OemPhysicalOwnershipConfirmed = false;
                state.OemReleaseActionKind = realBackend.OemReleaseActionKind;
                state.OemReleaseActionEvidence = realBackend.OemReleaseActionEvidence;
            }
            state.LastError = $"restore attempt {attempt}/1: {ExceptionText(ex)}";
            diagnostics.Write("restore.failure", new { attempt, close, error = state.LastError });
        }
        return false;
    }

    /**
     * §3.2（FAN-925B）：收据 → 动作分类（§3.2 表）。注意三条边界：
     *   ① 兼容证书（`Compatible`）**只能**由已审阅路线的**本次操作**证据取得，也就是
     *      `compat-route-without-scope`（会话/实例/路线/前提成立且真实回调返回）。
     *      **不得**把任何"没有本次操作作用域合格证据"的 kind 降成兼容成功。
     *   ② `unsupported`（旧 runtime 不支持作用域，见 §19 legacy 诊断）**不再**是兼容证书 ⇒
     *      Unknown。FAN-934 R2 §3-A.1 实证：旧映射把默认分支的 `unsupported` 当兼容放行，
     *      等于把"没有合格证据"判成安全。
     *   ③ `partial` 保留既有"至少一通道送达即不因 Mid 致命"的范围内策略：算 Proven，
     *      但**不伪全成功**（逐通道差异留在证据里），也不重开 30 次追 Mid。
     */
    internal static OemReleaseAction ClassifyReleaseAction(string? verdictKind) => verdictKind switch
    {
        "transported" => OemReleaseAction.Proven,
        "partial" => OemReleaseAction.Proven,
        "no-receipts" => OemReleaseAction.Unknown,
        "io-exception-unknown" => OemReleaseAction.Unknown,
        "receipt-api-fault" => OemReleaseAction.Unknown,
        "explicit-failure" => OemReleaseAction.Failed,
        "mixed-failed-unknown" => OemReleaseAction.Failed,
        // FAN-936 §3/§4：MSI 结构化释放证明——由 HC 侧 `ReleaseMsiFanControl` 的
        // 152→212 逐 bit「读整块 → 只改 bit7 → 写后回读」结论产生，是**软件回调合同**
        // 级别的合格证明（不是物理 RPM 确认）。
        "proven-by-msi-structured-release" => OemReleaseAction.Proven,
        // FAN-934 §4.A：非 ASUS 已审阅路线的软件回调合同证据（会话/实例/路线/Open 前提成立
        // 且真实回调返回）——不是物理成功或传输收据，但可作释放判据的合格证书。
        "compat-route-without-scope" => OemReleaseAction.CompatRouteWithoutScope,
        // 回调未返回（真实调用未完成）⇒ 明确失败；前提不成立 ⇒ unknown（fail-closed）。
        "compat-route-callback-not-returned" => OemReleaseAction.Failed,
        "compat-route-precondition-unsatisfied" => OemReleaseAction.Unknown,
        // FAN-934 R2 §3-A.1：旧 runtime"不支持作用域"只是诊断身份，不是合格证据 ⇒ unknown。
        "unsupported" => OemReleaseAction.Unknown,
        // FAN-934 R2 §3-A.1：未登记/未声明证据适用性的默认分支 ⇒ 独立 unknown（fail-closed）；
        // 这不是"已审阅无 scope 兼容"，不得被任何下游读成可放行。
        "unregistered-route-no-scope" => OemReleaseAction.Unknown,
        _ => OemReleaseAction.Unknown,
    };

    /**
     * FAN-936 §3（2026-10-01 裁决）：MSI 结构化释放三态 → Host 释放动作分类。
     * 只有 HC 侧逐位回读证实"152/212 的 bit7 已是目标值"（`Status == "ok"`）才记 Proven；
     * 明确失败记 Failed；其余（unknown/缺项/null）一律 Unknown —— **不能**因为
     * "HC callback returned" 就记成功，也不得由 Unknown 回落成 compat 成功。
     */
    internal static OemReleaseAction ClassifyMsiReleaseStatus(string? status) => status switch
    {
        "ok" => OemReleaseAction.Proven,
        "failed" => OemReleaseAction.Failed,
        _ => OemReleaseAction.Unknown,
    };

    /**
     * §3.3（FAN-925B）：主路径（HC profile callback）与回退路径（Host→HC AsusACPI）的证据
     * **合并**，不机械覆盖：主路径 no-receipts 不能抹掉一次有效的回退尝试，回退失败也不能
     * 掩盖成主路径成功。两边都不是证明时，明确失败优先于未知。
     */
    internal static OemReleaseAction MergeReleaseActions(OemReleaseAction primary, OemReleaseAction fallback) =>
        primary == OemReleaseAction.Proven ? OemReleaseAction.Proven
        : fallback == OemReleaseAction.Proven ? OemReleaseAction.Proven
        : primary == OemReleaseAction.Failed ? OemReleaseAction.Failed
        : fallback == OemReleaseAction.Failed ? OemReleaseAction.Failed
        : primary == OemReleaseAction.CompatRouteWithoutScope ? OemReleaseAction.CompatRouteWithoutScope
        : fallback == OemReleaseAction.CompatRouteWithoutScope ? OemReleaseAction.CompatRouteWithoutScope
        : OemReleaseAction.Unknown;

    /** 收据 kind → 对外动作 kind 字符串（导出/日志用，机器可读）。 */
    internal static string ReleaseActionKindName(OemReleaseAction action) => action switch
    {
        OemReleaseAction.NotApplicable => "not-applicable-no-write-history",
        OemReleaseAction.Proven => "proven-by-scope-receipts",
        OemReleaseAction.Unknown => "unknown-release-action",
        OemReleaseAction.Failed => "failed-release-action",
        OemReleaseAction.CompatRouteWithoutScope => "compat-route-without-scope",
        _ => "not-attempted",
    };

    /** 导出串 → 动作分类（消费端统一入口）。 */
    internal static OemReleaseAction ParseReleaseAction(string? kind) => kind switch
    {
        "not-applicable-no-write-history" => OemReleaseAction.NotApplicable,
        "proven-by-scope-receipts" or "proven-by-host-hc-acpi-fallback" or "proven-by-msi-structured-release" => OemReleaseAction.Proven,
        "failed-release-action" => OemReleaseAction.Failed,
        "compat-route-without-scope" => OemReleaseAction.CompatRouteWithoutScope,
        "unknown-release-action" => OemReleaseAction.Unknown,
        _ => OemReleaseAction.Unknown,
    };

    /**
     * §3.1（FAN-925B）：**唯一**的"释放已安全"判据。
     * 输入只有两项：本周期是否有写入历史 + 释放动作证据。
     * `hcCloseComplete`（资源清理）与物理观察**都不是**入参 —— 清理不能顶替释放（F02）。
     * 诚实对照：无写入历史 ⇒ 不适用释放，成功（F01 的正例）。
     */
    internal static bool IsOemReleaseSafe(bool hardwareWritesObserved, string? releaseActionKind) =>
        !hardwareWritesObserved ||
        ParseReleaseAction(releaseActionKind) is OemReleaseAction.Proven or OemReleaseAction.CompatRouteWithoutScope;

    internal static bool IsOemReleaseSafe(bool hardwareWritesObserved, OemReleaseAction releaseAction) =>
        !hardwareWritesObserved ||
        releaseAction is OemReleaseAction.Proven or OemReleaseAction.CompatRouteWithoutScope;

    internal static bool IsOemReleaseSafeForSelfTest(bool hardwareWritesObserved, string releaseActionKind) =>
        IsOemReleaseSafe(hardwareWritesObserved, releaseActionKind);

    /**
     * §3.4（FAN-925B）／D4（FAN-926R 裁决 §3）：**route-lost 的关闭边界不是"已释放"出口**的
     * 唯一判定（纯函数）。入参**只有两项**：本周期写历史 + 释放动作证据。
     *
     * 裁决 §3-D4：旧实现的两个入参（`closeBoundarySettledOnly` / `hcCloseComplete`）**已被删除**
     * ——它们曾是"有意接受但不参与结论"的死参，留着就等于给调用点留了一个"关闭边界可以参与
     * 释放判定"的错觉。清参**不是**移除保护：保护改为由 f02 的**签名钉**（本函数入参必须恰好
     * 两项）直接守住，任何想重新引入"清理/关闭边界入参"的改动都会被自测挡下。
     */
    internal static bool RouteLostCloseIsRelease(
        bool hardwareWritesObserved,
        string? releaseActionKind) =>
        IsOemReleaseSafe(hardwareWritesObserved, releaseActionKind);

    /**
     * §3.3（FAN-925B）：HC→`AsusACPI` 回退路径是否**构成释放动作证明**（纯函数）。
     * 只有**当次 scope 收据**为 transported/partial 才算证明；"已发起""读不到收据"
     * "句柄不可用"一律不算（旧实现把 `SetFanCurve` 的非负返回码当 `TransportedComplete`）。
     */
    internal static bool AcpiFallbackProven(string? scopeVerdictKind) =>
        ClassifyReleaseAction(scopeVerdictKind) == OemReleaseAction.Proven;

    /** §3.1：三类证据分列，供报告/HTTP/native 判据消费同一份定义。 */
    internal static string ReleaseEvidenceClass(bool hardwareWritesObserved, string? releaseActionKind) =>
        !hardwareWritesObserved ? "not-applicable-no-write-history"
        : ParseReleaseAction(releaseActionKind) switch
        {
            OemReleaseAction.Proven => "release-action-proven",
            OemReleaseAction.CompatRouteWithoutScope => "release-action-compat-route",
            OemReleaseAction.Failed => "release-action-failed",
            _ => "release-action-unknown",
        };

    private static bool HasConfirmedOemRelease(bool oemRestoreConfirmed, bool softwareWriteActive) =>
        oemRestoreConfirmed && !softwareWriteActive;

    internal static bool HasConfirmedOemReleaseForSelfTest(bool oemRestoreConfirmed, bool softwareWriteActive) =>
        HasConfirmedOemRelease(oemRestoreConfirmed, softwareWriteActive);

    private void ClearLease()
    {
        state.Lease = null;
        state.LeaseGeneration = null;
        leaseTimer?.Dispose();
        leaseTimer = null;
        StopRecoveryRetry();
    }

    private void RecoverAfterHardwareFailure(Exception error)
    {
        state.UnknownState = true;
        var failureText = ExceptionText(error);
        var routeLost = IsHcRouteLoss(error);
        state.LastError = failureText;
        if (RestoreHardware(close: true, skipOemRestore: routeLost))
        {
            ClearLease();
            state.State = state.PowerState == "Suspended" ? "Suspended" : "AwaitingControl";
            // Keep a bounded diagnostic breadcrumb after a successful safety
            // recovery. The live-write flag is already false, so this cannot
            // be mistaken for active control and it makes the failure prompt
            // actionable on the next state readback.
            state.LastError = routeLost
                ? $"recovered: HC route marker lost; virtual Close/unbind completed: {failureText}"
                : $"recovered: {failureText}";
        }
        else
        {
            state.State = "FaultLocked";
            WriteFaultLockedDiagnostic("hardware-failure-restore-failed");
            ScheduleRecoveryRetry();
        }
    }

    private static bool IsHcRouteLoss(Exception error) =>
        Unwrap(error).Any(item =>
            item.Message.Contains("HC_SESSION_ROUTE_LOST", StringComparison.OrdinalIgnoreCase) ||
            item.Message.Contains("hc-device-is-open-false", StringComparison.OrdinalIgnoreCase) ||
            item.Message.Contains("route-marker-lost", StringComparison.OrdinalIgnoreCase));

    internal static bool IsHcRouteLossForSelfTest(string message) =>
        IsHcRouteLoss(new InvalidOperationException(message));

    private void ScheduleRecoveryRetry()
    {
        if (stopped || recoveryTimer is not null || recoveryRetryWindowTerminal) return;
        // The in-flight HC call is the only owner of this lifecycle. HC does
        // not expose cancellation, so a timer must wait for its real return
        // callback rather than repeatedly calling Close/ManagerFactory.
        if (realBackend?.OperationTimedOut == true)
        {
            diagnostics.Write("recovery.retry-deferred-hc-operation-pending", new { state = state.State });
            return;
        }
        var now = MonoMs();
        if (recoveryRetryWindowStartedMonoMs == 0)
        {
            // 2026-09-25 FAN-925 T0-X：先看能否**继承**上一代（被更换的）Host 的剩余预算。
            // 继承被拒（周期终态 / 已用满"至多一次自动更换"）⇒ 失败终态，不再自动重试。
            if (!EnsureRecoveryCycleLocked("schedule-recovery-retry"))
            {
                EnterRecoveryRetryTerminalState("recovery-cycle-refused");
                return;
            }
            if (recoveryRetryWindowStartedMonoMs == 0) recoveryRetryWindowStartedMonoMs = now;
        }
        var elapsed = Math.Max(0, now - recoveryRetryWindowStartedMonoMs);
        if (recoveryRetryAttempt >= RecoveryRetryMaxAttempt || elapsed >= EffectiveRecoveryRetryWindowMs)
        {
            EnterRecoveryRetryTerminalState(recoveryReopenRequired
                ? "reopen-not-completed-within-cycle-budget"
                : "recovery retry window exhausted");
            return;
        }
        var attempt = recoveryRetryAttempt++;
        // 尝试数跨进程持久化：替代 Host 继承的是**剩余**次数，不是新的 30 次。
        // 节流（operator 日志开销规则：降低基本开销）：只在每 5 次落盘一次；30 是 5 的倍数，
        // 因此次数上限在最后一步**恰好**被记录，跨进程继承不会漏掉上限。
        if (recoveryCycle is not null && recoveryCycle.Attempts != attempt + 1 &&
            (attempt + 1) % 5 == 0)
        {
            recoveryCycle = recoveryCycle with { Attempts = attempt + 1, LastUpdatedAtUtc = DateTime.UtcNow };
            PersistRecoveryCycleLocked();
        }
        const int delayMs = RecoveryRetryIntervalMs;
        diagnostics.Write("recovery.retry-scheduled", new
        {
            attempt = attempt + 1,
            maxAttempts = RecoveryRetryMaxAttempt,
            delayMs,
            elapsedMs = elapsed,
            windowMs = RecoveryRetryWindowMs,
        });
        recoveryTimer = new Timer(_ =>
        {
            lock (gate)
            {
                recoveryTimer?.Dispose();
                recoveryTimer = null;
                if (stopped || (state.State != "FaultLocked" && state.State != "AwaitingCloseCleanup")) return;
                if (recoveryRetryWindowStartedMonoMs == 0 ||
                    MonoMs() - recoveryRetryWindowStartedMonoMs >= EffectiveRecoveryRetryWindowMs)
                {
                    EnterRecoveryRetryTerminalState(recoveryReopenRequired
                        ? "reopen-not-completed-within-cycle-budget"
                        : "recovery retry window elapsed");
                    return;
                }
                var strictSystemPendingRetry = recoveryRetryUsesSystemPendingClose;
                // B4（FAN-925 / HC 回函 A1–A3）：route-lost 时宿主**自身出清不了**——
                // `Device_Inserted(true)` 绕过 PnP 重放 + VID/PID 过滤 + 状态门，须由调用方自证
                // "设备在场"，且 HC 侧没有任何"等 HID 稳定"步骤（等待是调用方责任）
                // ⇒ **重开归 bridge**。这里改成"有界等待重开收据"，不再空转被第五道门挡住的 restore。
                // 判据只用**收据**（A1/A5/H4）：`OpenEvents()` 返回 / `IsReady()` / `IsConnected` /
                // `OpenCalled` / `OpenEventsCalled` **都不算**——H4 已源码级证明后两者只代表"已发起"。
                // 等待是静默的（不逐轮记日志，遵守"事件=低频"）。
                var reopenReceiptDetail = "not-required";
                if (recoveryReopenRequired)
                {
                    // §4.5（FAN-925B）：明确**谁在页面不可用期间驱动 Fan 恢复**，并保证
                    // "永远等旧页面"不是自动恢复实现：有界等待 → 复用既有受控更换升级路径
                    // （至多一次/周期）；本宿主在此期间保持唯一写入权，不自起第二个 owner。
                    var waited = Math.Max(0, Environment.TickCount64 - reopenWaitStartedMonoMs);
                    var decision = ReopenOwnershipDecision(
                        reopenRequired: true,
                        waitedMs: waited,
                        budgetMs: EffectiveReopenBridgeWaitBudgetMs,
                        replacementAlreadyRequested: controlledReplacementRequested);
                    if (!string.Equals(decision, recoveryOwner, StringComparison.Ordinal))
                    {
                        recoveryOwner = decision;
                        var requestsReplacement = decision == "fan-host-requests-controlled-replacement";
                        if (requestsReplacement)
                        {
                            // §4.1（FAN-926 P2）：**先**做恰好一次"有正式 HC 生命周期收据证明
                            // 的同进程恢复"；只有拿不到完整收据时才允许请求一次受控更换。
                            if (uiFreeSelfOpenAttempts == 0)
                            {
                                uiFreeSelfOpenAttempts++;
                                if (TryUiFreeSameProcessRecoveryLocked())
                                {
                                    recoveryReopenRequired = false;
                                    recoveryOwner = "fan-host-same-process-recovered";
                                    CompleteRecoveryCycleLocked("ui-free-same-process-recovered");
                                    diagnostics.Write("recovery.ui-free-same-process-confirmed", new
                                    {
                                        reopenCount = recoveryReopenCount,
                                        cycleId = recoveryCycle?.CycleId,
                                        selfOpenAttempts = uiFreeSelfOpenAttempts,
                                        scope = "ui-free-same-process-stage-only",
                                    });
                                    reopenBinding = null;
                                    state.State = state.PowerState == "Suspended" ? "Suspended" : "AwaitingControl";
                                    return;
                                }
                            }
                            controlledReplacementRequested = true;
                            controlledReplacementRequests++;
                            uiFreeReplacementRequests++;
                            // §4.1（FAN-926 P2）：恰好一次受控更换。拉起成功**不等于**恢复成功——
                            // 恢复由后继实例的"旧实例已退出"自证 + 正式收据证明。
                            _ = TryRequestControlledHostReplacementLocked();
                        }
                        diagnostics.Write(requestsReplacement
                            ? "recovery.controlled-replacement-requested"
                            : "recovery.reopen-owner-changed", new
                        {
                            owner = decision,
                            selfOpenAttempts = uiFreeSelfOpenAttempts,
                            replacementRequests = uiFreeReplacementRequests,
                            waitedMs = waited,
                            bridgeWaitBudgetMs = EffectiveReopenBridgeWaitBudgetMs,
                            reopenCount = recoveryReopenCount,
                            cycleId = recoveryCycle?.CycleId,
                            binding = reopenBinding?.Describe(),
                            replacementCap = "at-most-one-auto-host-replacement-per-cycle",
                            note = requestsReplacement
                                ? "page/bridge did not hand over the reopen within the bounded window; escalate through the existing controlled-replacement path; this host keeps sole write authority until old-owner exit is proven"
                                : "no-ui-callback-required; host keeps the budgeted supervision",
                        });
                    }
                }
                var recovered = recoveryReopenRequired
                    ? (realBackend?.TryObserveReopenReceipt(
                        reopenBinding,
                        engineInstanceId,
                        recoveryCycle?.CycleId,
                        CurrentSessionGeneration,
                        AbnormalFinalizeGateWaitMs,
                        out reopenReceiptDetail) ?? false)
                    : (strictSystemPendingRetry ? CloseForSystemPending() : RestoreHardware(close: true));
                if (recovered)
                {
                    if (recoveryReopenRequired)
                    {
                        // bridge 已完成重开：收据 = Outcome==Completed ∧ 四位副作用齐全。
                        recoveryReopenRequired = false;
                        recoveryOwner = "reopen-confirmed-by-bridge";
                        CompleteRecoveryCycleLocked("reopen-confirmed-by-bridge");
                        diagnostics.Write("recovery.reopen-confirmed", new
                        {
                            cycleId = recoveryCycle?.CycleId,
                            reopenCount = recoveryReopenCount,
                            binding = reopenBinding?.Describe(),
                            receipt = reopenReceiptDetail,
                            // G-1（2026-09-27 消费侧取证）：确认重开这一拍把 HC 逐轮收据一并带出
                            // —— 重开窗内"哪几轮被拒/丢弃、绑定是否在场、清理台账是否仍欠"由此可判。
                            hcReceipts = realBackend?.HcReceiptsEvidence,
                            // §4.4：本事件**只签重开阶段**。原控制意图恢复与"下一次调整成功"
                            // 仍由 T0-U 判；不得因为取到 open 收据就把整条恢复算结束。
                            scope = "reopen-stage-only; intent-restore-and-next-adjustment-still-decide-T0",
                        });
                        reopenBinding = null;
                        state.State = state.PowerState == "Suspended" ? "Suspended" : "AwaitingControl";
                        return;
                    }
                    ClearLease();
                    CompleteRecoveryCycleLocked("retry-recovered");
                    if (strictSystemPendingRetry)
                    {
                        // The retry completed the same F4 boundary. Do not
                        // reopen or apply a profile until a new native F5.
                        state.PowerState = "Suspended";
                        state.State = "Suspended";
                    }
                    else if (state.CloseCalled)
                    {
                        state.State = state.PowerState == "Suspended" ? "Suspended" : "Stopped";
                        stopped = state.PowerState != "Suspended";
                    }
                    else
                        state.State = state.PowerState == "Suspended" ? "Suspended" : "AwaitingControl";
                }
                else ScheduleRecoveryRetry();
            }
        }, null, delayMs, Timeout.Infinite);
    }

    private void EnterRecoveryRetryTerminalState(string reason)
    {
        recoveryTimer?.Dispose();
        recoveryTimer = null;
        recoveryRetryWindowTerminal = true;
        // FAN-925：终态落盘，使替代 Host 不会把它当成"新周期"重新计时。
        MarkRecoveryCycleTerminalLocked(reason);
        state.State = "FaultLocked";
        state.UnknownState = true;
        state.RecoveryReadbackRequired = true;
        state.LastError = $"HC 自动恢复窗口已结束：{reason}；等待明确事件或人工重试";
        // 裁决 H3（N15）：进入 retry 终态（FaultLocked）＝本次睡眠保护已不可能被正常
        // 消费。仅当"当前记录仍是本次睡眠那一条实例"且"无 Close 义务"时释放（否则保留，
        // 由真正的 Close 边界负责）。不放行 retry-terminal 本身。
        TryReleaseUnresolvableSuspendProtection();
        WriteFaultLockedDiagnostic($"retry-terminal:{reason}");
        diagnostics.Write("recovery.retry-terminal", new
        {
            reason,
            attempts = recoveryRetryAttempt,
            windowMs = RecoveryRetryWindowMs,
            state = state.State,
        });
    }

    // A caller-visible close/retry is the explicit event permitted to start a
    // fresh bounded window after the prior automatic window reached terminal
    // FaultLocked.  Automatic timer callbacks never call this method.
    private void BeginExplicitRecoveryRetryWindow()
    {
        // FAN-934 R2：跨进程账本"已耗尽且未结算"被拒时，进入终态而窗口**从未开始**
        // （recoveryRetryWindowStartedMonoMs == 0）。旧实现要求 started != 0 才清除终态，导致
        // 用户显式 Close 无法开出新周期——Host 永久卡死在旧周期上。此处只以"当前无在飞定时器"
        // 为条件：显式边界始终允许开一次有界新周期（次数/更换上界仍由周期账本与
        // DecideRecoveryCycleAdoption 约束，不因本改动而放宽）。
        if (recoveryTimer is null)
        {
            recoveryRetryAttempt = 0;
            recoveryRetryWindowStartedMonoMs = 0;
            recoveryRetryWindowTerminal = false;
        }
    }

    private void StopRecoveryRetry()
    {
        recoveryTimer?.Dispose();
        recoveryTimer = null;
        recoveryRetryAttempt = 0;
        recoveryRetryWindowStartedMonoMs = 0;
        recoveryRetryWindowTerminal = false;
    }

    // ── FAN-925 T0-X：故障周期预算（跨进程继承 + 受控更换计数）────────────────────

    private static string RecoveryCycleStatePath()
    {
        // 自测/故障注入落在隔离根，绝不污染用户真实状态（与 HostDiagnosticLog 同源规则）。
        var isolated = Environment.GetEnvironmentVariable(HostDiagnosticLog.SelfTestLogRootEnvVar);
        var directory = string.IsNullOrWhiteSpace(isolated)
            ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "YeManCC", "fan-host")
            : isolated;
        Directory.CreateDirectory(directory);
        return Path.Combine(directory, "YeManFanHost.recovery-cycle.json");
    }

    private static long RemainingRecoveryCycleMs(RecoveryCycleRecord record)
    {
        if (record.Completed || record.Terminal) return 0;
        if (record.Attempts >= RecoveryRetryMaxAttempt) return 0;
        var elapsed = (long)(DateTime.UtcNow - record.StartedAtUtc).TotalMilliseconds;
        if (elapsed < 0) elapsed = 0;
        var remaining = EffectiveRecoveryRetryWindowMs - elapsed;
        return remaining > 0 ? remaining : 0;
    }

    /** 供确定性自测直接消费**真实**剩余预算函数（不是另写一份模型）。 */
    internal static long RemainingRecoveryCycleMsForSelfTest(
        DateTime startedAtUtc, int attempts, bool terminal, bool completed)
        => RemainingRecoveryCycleMs(new RecoveryCycleRecord(
            "selftest", 0, startedAtUtc, attempts, 0, terminal, completed, null, DateTime.UtcNow));

    /**
     * 仅自测：走**真实**落盘路径写一条周期记录，返回其路径。用于验证跨进程继承的
     * 磁盘格式与读回路径（自测已进隔离根 ⇒ 不污染用户真实状态）。
     */
    internal string PersistRecoveryCycleForSelfTest(int parentPid, DateTime startedAtUtc, int attempts)
    {
        lock (gate)
        {
            recoveryCycle = new RecoveryCycleRecord(
                "selftest-cycle", parentPid, startedAtUtc, attempts, 0, false, false, "selftest", DateTime.UtcNow);
            PersistRecoveryCycleLocked();
            return RecoveryCycleStatePath();
        }
    }

    /** 仅自测：走**真实**读回路径。 */
    internal (bool Found, string? CycleId, int Attempts, int Replacements, long RemainingMs) ReadRecoveryCycleForSelfTest()
    {
        var record = ReadPersistedRecoveryCycle();
        return record is null
            ? (false, null, 0, 0, 0)
            : (true, record.CycleId, record.Attempts, record.Replacements, RemainingRecoveryCycleMs(record));
    }

    /** 仅自测：清理隔离根里的周期记录（模拟"用户显式重试 ⇒ 新周期"）。 */
    internal void ClearRecoveryCycleForSelfTest()
    {
        lock (gate)
        {
            recoveryCycle = null;
            recoveryCycleInherited = false;
            try { File.Delete(RecoveryCycleStatePath()); } catch (Exception) { /* best-effort */ }
        }
    }

    private RecoveryCycleRecord? ReadPersistedRecoveryCycle()
    {
        try
        {
            var path = RecoveryCycleStatePath();
            if (!File.Exists(path)) return null;
            return JsonSerializer.Deserialize<RecoveryCycleRecord>(File.ReadAllText(path), JsonDefaults.Options);
        }
        catch (Exception ex)
        {
            diagnostics.Write("recovery.cycle-read-failed", new { error = ExceptionText(ex) });
            return null;
        }
    }

    private void PersistRecoveryCycleLocked()
    {
        if (recoveryCycle is null) return;
        // §3.1（FAN-926 P1）：受理的 ACK **之前绝不碰磁盘**——冷盘/AV 首次写入实测 ~460 ms，
        // 会冲破既有"交接不被 gate 持有期阻塞"的 250 ms 快速门。周期已在内存建立；替代 Host
        // 只可能在预算之后才被拉起，那时这次落盘早已完成（预算继承读的是磁盘，不读内存引用）。
        if (acceptanceFastPathActive)
        {
            _ = Task.Run(() =>
            {
                lock (gate) { lock (acceptanceGate) { PersistRecoveryCycleSynchronously(); } }
            });
            return;
        }
        PersistRecoveryCycleSynchronously();
    }

    /** 仅受理线程在建立周期的短短一段里为 true；用 ThreadStatic 保证只影响该线程。 */
    [ThreadStatic] private static bool acceptanceFastPathActive;

    private void PersistRecoveryCycleSynchronously()
    {
        if (recoveryCycle is null) return;
        // §3（FAN-926 P1）：受理路径只取 acceptanceGate（**不**取 gate），因此它会与 gate 内
        // 的周期写路径并发落盘；固定 ".new" 暂存名会让两次写入互相覆盖/占用。改为唯一暂存名
        // 后仍是"写完整文件再整体替换"，读侧永远看到完整 JSON。
        var path = RecoveryCycleStatePath();
        var staged = path + "." + Guid.NewGuid().ToString("N") + ".new";
        try
        {
            File.WriteAllText(staged, JsonSerializer.Serialize(recoveryCycle, JsonDefaults.Options));
            File.Move(staged, path, overwrite: true);
        }
        catch (Exception ex)
        {
            try { File.Delete(staged); } catch (Exception) { /* best-effort */ }
            diagnostics.Write("recovery.cycle-write-failed", new { error = ExceptionText(ex) });
        }
    }

    /** 周期接管判定（纯函数：便于确定性自测，不读盘、不改状态）。 */
    internal enum RecoveryCycleAdoption
    {
        StartNew,
        Inherit,
        RefuseReplacementCap,
        // §4.2（FAN-926 P2）：**同一未结算故障 episode** 的预算已耗尽（到时 / 次数到限 / 已终态）。
        // 这不是"从未发生过故障"——绝不允许静默刷新一个新的 60 s，只能由用户显式重试开新周期。
        RefuseExhaustedWithoutSettlement,
    }

    internal static RecoveryCycleAdoption DecideRecoveryCycleAdoption(
        bool explicitRetry, bool hasPersisted, bool sameParent, bool completed, long remainingMs, int replacements)
    {
        if (explicitRetry) return RecoveryCycleAdoption.StartNew;   // 唯一豁免：用户显式重试
        if (!hasPersisted) return RecoveryCycleAdoption.StartNew;   // 从未发生过故障
        if (completed) return RecoveryCycleAdoption.StartNew;       // 真正完成后的**新**故障
        if (!sameParent) return RecoveryCycleAdoption.StartNew;     // 已核父实例/映像不属于本 episode
        // 本 episode 尚未结算且属于同一父实例 ⇒ 到期与到限都只能拒绝：不得重新计时。
        if (remainingMs <= 0) return RecoveryCycleAdoption.RefuseExhaustedWithoutSettlement;
        return replacements >= 1
            ? RecoveryCycleAdoption.RefuseReplacementCap
            : RecoveryCycleAdoption.Inherit;
    }

    /**
     * §4.2：本持久化周期是否属于**同一个未结算故障 episode**（**纯函数**，便于确定性自测）。
     * 不能只比较 PID 数值——同一映像的另一个进程实例仍是同一 episode 的换实例接管；
     * 映像身份缺失时退回已核实的父 PID。
     */
    internal static bool SameEpisodeParentIdentity(
        int parentPid, int persistedParentPid, string? parentImage, string? persistedImage)
        => (parentPid != 0 && persistedParentPid == parentPid) ||
           (!string.IsNullOrWhiteSpace(persistedImage) && !string.IsNullOrWhiteSpace(parentImage) &&
            string.Equals(persistedImage, parentImage, StringComparison.OrdinalIgnoreCase));

    private bool ParentIdentityMatchesEpisode(RecoveryCycleRecord persisted) =>
        SameEpisodeParentIdentity(
            options.ParentPid ?? 0, persisted.ParentPid, parentEpisodeImagePath, persisted.ParentExecutablePath);

    /** §4.2：父进程映像路径（读不到 ⇒ null；绝不影响启动或任何既有判定）。 */
    private static string? CaptureParentEpisodeImagePath(HostOptions options)
    {
        try
        {
            if (options.ParentPid is int pid and > 0)
            {
                using var process = Process.GetProcessById(pid);
                return process.HasExited ? null : process.MainModule?.FileName;
            }
            var name = Path.GetFileNameWithoutExtension(options.ParentProcessName);
            if (string.IsNullOrWhiteSpace(name)) return null;
            var matches = Process.GetProcessesByName(name);
            try
            {
                var alive = matches
                    .Where(item => { try { return !item.HasExited; } catch { return false; } })
                    .ToArray();
                // 名字级父进程只有在唯一且身份可读时才有意义；歧义不是权限。
                return alive.Length == 1 ? alive[0].MainModule?.FileName : null;
            }
            finally
            {
                foreach (var item in matches) item.Dispose();
            }
        }
        catch { return null; }
    }

    private RecoveryCycleRecord NewRecoveryCycleLocked(int parentPid, string reason)
        => new(Guid.NewGuid().ToString("N"), parentPid, DateTime.UtcNow, 0, 0, false, false, reason, DateTime.UtcNow,
            parentEpisodeImagePath);

    /**
     * 建立或继承本故障周期。返回 false ⇒ **不得**开始自动恢复（失败终态）。
     * 只有 caller-explicit 重试允许开启新周期；自动路径遇到终态、或已用满
     * "每故障周期至多一次自动 Host 更换"必须停在这里，留给用户显式重试入口。
     */
    private bool EnsureRecoveryCycleLocked(string reason)
    {
        // §3（FAN-926 P1）：与受理路径互斥——受理可能在周期还没建立时并发登记**同一条**责任。
        // Monitor 可重入，因此受理在自己的 acceptanceGate 临界区内直接调用本方法也安全。
        // 锁序固定 gate → acceptanceGate（受理路径只取 acceptanceGate，绝不取 gate）。
        lock (acceptanceGate) return EnsureRecoveryCycleCoreLocked(reason);
    }

    private bool EnsureRecoveryCycleCoreLocked(string reason)
    {
        var parentPid = options.ParentPid ?? 0;
        if (recoveryCycle is not null)
        {
            if (!recoveryCycle.Terminal) return true;
            if (!recoveryCycleExplicitRetryRequested) return false;
            recoveryCycleExplicitRetryRequested = false;
            recoveryCycle = NewRecoveryCycleLocked(parentPid, "explicit-retry-after-terminal:" + reason);
            recoveryCycleInherited = false;
            diagnostics.Write("recovery.cycle-started", new
            {
                reason, trigger = "explicit-retry-after-terminal", cycleId = recoveryCycle.CycleId,
            });
            PersistRecoveryCycleLocked();
            return true;
        }
        var explicitRetry = recoveryCycleExplicitRetryRequested;
        recoveryCycleExplicitRetryRequested = false;
        var persisted = ReadPersistedRecoveryCycle();
        var remaining = persisted is null ? 0 : RemainingRecoveryCycleMs(persisted);
        var adoption = DecideRecoveryCycleAdoption(
            explicitRetry,
            persisted is not null,
            persisted is not null && ParentIdentityMatchesEpisode(persisted),
            persisted?.Completed == true,
            remaining,
            persisted?.Replacements ?? 0);
        switch (adoption)
        {
            case RecoveryCycleAdoption.RefuseExhaustedWithoutSettlement:
                // §4.2：同一未结算 episode 的预算已耗尽（到时/次数到限）⇒ 落**终态**，
                // 明确区别于"从未发生过故障"：不自动开新 60 s，只留用户显式重试入口。
                recoveryCycle = persisted! with
                {
                    Terminal = true,
                    LastReason = "exhausted-without-settlement:" + reason,
                    LastUpdatedAtUtc = DateTime.UtcNow,
                };
                recoveryCycleInherited = true;
                diagnostics.Write("recovery.cycle-exhausted-without-settlement", new
                {
                    reason, cycleId = recoveryCycle.CycleId, attempts = recoveryCycle.Attempts,
                    replacements = recoveryCycle.Replacements, remainingMs = remaining,
                });
                PersistRecoveryCycleLocked();
                return false;
            case RecoveryCycleAdoption.RefuseReplacementCap:
                // 每故障周期至多一次自动 Host 更换：本次启动属于同一周期的第二次自动接管 ⇒ 拒绝。
                recoveryCycle = persisted! with
                {
                    LastReason = "replacement-cap-reached:" + reason,
                    LastUpdatedAtUtc = DateTime.UtcNow,
                };
                recoveryCycleInherited = true;
                diagnostics.Write("recovery.cycle-replacement-cap-reached", new
                {
                    reason, cycleId = recoveryCycle.CycleId, replacements = recoveryCycle.Replacements,
                    attempts = recoveryCycle.Attempts, remainingMs = remaining,
                });
                PersistRecoveryCycleLocked();
                return false;
            case RecoveryCycleAdoption.Inherit:
                recoveryCycle = persisted! with
                {
                    Replacements = persisted!.Replacements + 1,
                    LastReason = "inherited:" + reason,
                    LastUpdatedAtUtc = DateTime.UtcNow,
                };
                recoveryCycleInherited = true;
                // 继承剩余预算与尝试数：绝不重新计 60 s，也不重新计 30 次。
                recoveryRetryWindowStartedMonoMs = MonoMs() - (EffectiveRecoveryRetryWindowMs - remaining);
                recoveryRetryAttempt = persisted!.Attempts;
                diagnostics.Write("recovery.cycle-inherited", new
                {
                    reason, cycleId = recoveryCycle.CycleId, replacements = recoveryCycle.Replacements,
                    attempts = recoveryRetryAttempt, remainingMs = remaining,
                });
                PersistRecoveryCycleLocked();
                return true;
            default:
                recoveryCycle = NewRecoveryCycleLocked(parentPid, reason);
                recoveryCycleInherited = false;
                diagnostics.Write("recovery.cycle-started", new
                {
                    reason, trigger = explicitRetry ? "explicit-retry" : "automatic", cycleId = recoveryCycle.CycleId,
                });
                PersistRecoveryCycleLocked();
                return true;
        }
    }

    private void CompleteRecoveryCycleLocked(string reason)
    {
        if (recoveryCycle is null) return;
        recoveryCycle = recoveryCycle with { Completed = true, LastReason = reason, LastUpdatedAtUtc = DateTime.UtcNow };
        diagnostics.Write("recovery.cycle-completed", new
        {
            reason, cycleId = recoveryCycle.CycleId, attempts = recoveryCycle.Attempts,
            replacements = recoveryCycle.Replacements,
        });
        PersistRecoveryCycleLocked();
    }

    private void MarkRecoveryCycleTerminalLocked(string reason)
    {
        if (recoveryCycle is null) return;
        recoveryCycle = recoveryCycle with { Terminal = true, LastReason = reason, LastUpdatedAtUtc = DateTime.UtcNow };
        PersistRecoveryCycleLocked();
    }

    /**
     * §4（FAN-925B）：**本次重开**的绑定票据。重开由 bridge 驱动，但"这次重开是不是
     * 当前恢复周期的重开"必须由宿主绑定并核对，否则"最近一次 Completed"会被当成本次恢复
     * （旧成功、旧 Host、同 ID 跨实例、迟到结果、缺字段都必须被拒绝）。
     */
    internal sealed record ReopenBinding(
        string HostInstanceId,
        string? CycleId,
        long SessionGeneration,
        string? BaselineOperationId,
        long CreatedMonoMs)
    {
        public string Describe() =>
            $"host={HostInstanceId} cycle={CycleId ?? "<none>"} gen={SessionGeneration} " +
            $"baselineOp={BaselineOperationId ?? "<none>"}";
    }

    private ReopenBinding? reopenBinding;
    internal string? ReopenBindingForSelfTest => reopenBinding?.Describe();

    /**
     * §4.5（FAN-925B）：bridge 重开的**有界等待预算**。它不是新的恢复预算：
     * 总账仍是本故障周期的 60 s / 30 次（`RecoveryRetryWindowMs` / `RecoveryRetryMaxAttempt`）。
     * 它只回答"页面/桥接多久没把重开交出来就升级"，避免把"永远等旧页面"当作自动恢复实现。
     */
    internal const long ReopenBridgeWaitBudgetMs = 15_000;
    /**
     * 仅自测覆写（生产恒为 null ⇒ 用上面的 15 s）。让 §4.5 的结合场景能在确定性时间里
     * 观察到"有界等待 → 一次性升级"，而不必在每次自测里真实等待 15 s。
     */
    internal static long? ReopenBridgeWaitBudgetMsForSelfTest { get; set; }
    private static long EffectiveReopenBridgeWaitBudgetMs =>
        ReopenBridgeWaitBudgetMsForSelfTest ?? ReopenBridgeWaitBudgetMs;
    private long reopenWaitStartedMonoMs;
    private bool controlledReplacementRequested;
    private int controlledReplacementRequests;
    // ── §4.1（FAN-926 P2）：UI 不可用时的**单所有者恢复链** ──────────────────────
    // 链：BudgetedBridgeWait → SameProcessAttempt(每周期 ≤1) → ReplacementRequested(每周期 ≤1)
    //     → Terminal / Recovered。全程继承**同一个**恢复周期与剩余预算。
    private int uiFreeSelfOpenAttempts;
    private int uiFreeReplacementRequests;
    internal int UiFreeSelfOpenAttemptsForSelfTest => uiFreeSelfOpenAttempts;
    internal int UiFreeReplacementRequestsForSelfTest => uiFreeReplacementRequests;
    /**
     * §4.1（FAN-926 P2）：受控更换时，本实例在拉起后继实例之后必须**有序退出**，后继实例才可能
     * 重建生命周期互斥（= 旧实例确已退出的证明）。由宿主进程接线；未接线（自测）时保持 null。
     */
    internal Action? RequestHostExit { get; set; }

    /**
     * §4.1（FAN-926 P2）：同进程恢复是否**完成**——唯一判据（纯函数，便于确定性自测）。
     * 关键负例：只留下"已请求更换"绝不算完成。"HTTP 200 / Open 调用返回 / 页面恢复"
     * **不**是入参：它们必须先汇成一个**正式 HC 生命周期收据**才有资格进入本判定。
     */
    internal static bool UiFreeRecoveryComplete(bool formalReceiptAccepted, bool replacementRequested) =>
        formalReceiptAccepted && !replacementRequested;
    /// <summary>§4.5 / F07 自测：受控更换请求次数（计数器，不依赖日志捕获）。</summary>
    internal int ControlledReplacementRequestsForSelfTest => controlledReplacementRequests;
    /// <summary>§4.5：页面不可用期间唯一承担 Fan 恢复责任的执行者（机器可读）。</summary>
    private string recoveryOwner = "none";
    /**
     * D5（FAN-926R 裁决 §3）：当前恢复 owner 的**受限内部恢复准入**深度。
     * 这不是"全局移除 FaultLocked 门"：只有唯一恢复 owner 在自己的一次内部恢复动作
     * （`Open` → `Device_Inserted(true)` → 正式收据）期间、且系统已恢复可操作、周期匹配、
     * 预算尚有余量、旧操作已收敛时才 +1。公有 enable/用户写入**永远拿不到**它。
     */
    private int internalRecoveryAdmissionDepth;
    private bool internalRecoveryAdmissionActive => internalRecoveryAdmissionDepth > 0;
    internal bool InternalRecoveryAdmissionActiveForSelfTest => internalRecoveryAdmissionActive;

    /**
     * D5：授予内部恢复准入。调用方必须持 `gate` 且是**唯一恢复 owner**。
     * 全部前件为真才放行；任一不满足即拒绝并如实记账（不伪造 generation / op id）。
     */
    private bool TryGrantInternalRecoveryAdmission(string source, out string refusal)
    {
        refusal = "granted";
        if (stopped) refusal = "host-stopped";
        else if (state.State == "Suspended" || state.PowerState == "Suspended") refusal = "system-not-operable-suspended";
        else if (state.HcCloseCleanupPending) refusal = "hc-close-cleanup-pending";
        else if (realBackend?.OperationTimedOut == true) refusal = "previous-hc-operation-not-settled";
        else if (recoveryCycle is null || RemainingRecoveryCycleMs(recoveryCycle) <= 0) refusal = "no-remaining-cycle-budget";
        else if (suspendedCurve is null || suspendedCurve.Count == 0) refusal = "no-valid-control-intent";
        if (refusal != "granted")
        {
            diagnostics.Write("recovery.internal-admission-refused", new
            {
                source,
                reason = refusal,
                cycleId = recoveryCycle?.CycleId,
                state = state.State,
                powerState = state.PowerState,
                scope = "public-enable-remains-refused-by-FaultLocked",
            });
            return false;
        }
        internalRecoveryAdmissionDepth++;
        diagnostics.Write("recovery.internal-admission-granted", new
        {
            source,
            depth = internalRecoveryAdmissionDepth,
            cycleId = recoveryCycle?.CycleId,
            remainingMs = RemainingRecoveryCycleMs(recoveryCycle!),
            scope = "single-owner-internal-reopen-only; public-enable-still-refused",
        });
        return true;
    }

    private void ReleaseInternalRecoveryAdmission()
    {
        if (internalRecoveryAdmissionDepth > 0) internalRecoveryAdmissionDepth--;
    }
    internal string RecoveryOwnerForSelfTest => recoveryOwner;
    internal bool ControlledReplacementRequestedForSelfTest => controlledReplacementRequested;

    /**
     * §4.5（FAN-925B）：**谁在页面不可用期间驱动 Fan 恢复**的唯一判定（纯函数）。
     * `route-lost` 时宿主是唯一写入权的持有者：先在有界预算内等待 bridge/页面交出重开收据；
     * 预算内没等到 ⇒ 复用既有"至多一次自动 Host 更换"升级路径，并把执行者如实记名；
     * 已经请求过 ⇒ 只做终态记账（不无限等、不重复换代、不自己起第二个 owner）。
     */
    internal static string ReopenOwnershipDecision(
        bool reopenRequired, long waitedMs, long budgetMs, bool replacementAlreadyRequested) =>
        !reopenRequired ? "none"
        : waitedMs < budgetMs ? "fan-host-budgeted-supervision;awaiting-bridge-reopen"
        : replacementAlreadyRequested ? "fan-host-terminal-accounting;replacement-already-requested"
        : "fan-host-requests-controlled-replacement";

    /**
     * §4.1（FAN-926 P2）：UI 不可用时的**同进程恢复尝试**（每故障周期恰好一次）。
     * 走**既有单一权威**，不新开释放路径：`RestoreHardware(close:false)`（§3 唯一释放判据）
     * → 生产入口 `Open()` + `OpenEvents()`（FAN-925 §A1 已证这两步足够、无第三动作、无新 HC 接口）。
     * 成功判据**只能是正式 HC 生命周期收据**（`ReopenReceiptAccepted`：本次操作 + 四位副作用 +
     * 无不确定/迟到副作用 + 已换代 + 周期未变）。调用返回 / HTTP 200 / 页面回来**都不算**。
     */
    private bool TryUiFreeSameProcessRecoveryLocked()
    {
        diagnostics.Write("recovery.ui-free-same-process-begin", new
        {
            reopenCount = recoveryReopenCount,
            cycleId = recoveryCycle?.CycleId,
            binding = reopenBinding?.Describe(),
        });
        // 同一口径：本路径由故障触发，`activeCurve` 多半已被 `StopCurveTimer()` 置空，
        // 保留曲线在 `suspendedCurve`。只读前者会把这个证据字段恒报成 0。
        var retainedCurveNodes = (suspendedCurve ?? activeCurve)?.Count ?? 0;
        // D5（FAN-926R 裁决 §3）：这条内部恢复动作**真正发起**一次重开（不再只等票据），
        // 但只在唯一恢复 owner 持有受限准入时执行；准入前件任一不满足即如实拒绝。
        if (!TryGrantInternalRecoveryAdmission("ui-free-same-process", out var admissionRefusal))
        {
            diagnostics.Write("recovery.ui-free-same-process-denied", new
            {
                refusal = admissionRefusal,
                cycleId = recoveryCycle?.CycleId,
                retainedCurveNodes,
            });
            return false;
        }
        var accepted = false;
        var detail = "receipt-api-absent-no-hc-backend";
        var intentReplayed = false;
        var intentDetail = "not-attempted";
        try
        {
            _ = RestoreHardware(close: false);
            _ = Open();
            _ = OpenEvents();
            // 规范收据：**必须**由 realBackend 观测到"本次操作"的正式生命周期收据。
            if (realBackend is not null)
            {
                accepted = realBackend.TryObserveReopenReceipt(
                    reopenBinding, engineInstanceId, recoveryCycle?.CycleId, CurrentSessionGeneration,
                    AbnormalFinalizeGateWaitMs, out detail);
            }
            // D5：拿到重开收据只代表**会话恢复**。成功结算还需当前意图重放（下一次调整
            // 是否有效由 T0-U 判），不得在曲线未恢复时报 recovered。
            if (accepted)
                intentReplayed = RestoreControlIntentAfterTakeover(out intentDetail);
        }
        catch (Exception ex)
        {
            diagnostics.Write("recovery.ui-free-same-process-fault",
                new { error = ExceptionText(ex), cycleId = recoveryCycle?.CycleId });
            return false;
        }
        finally
        {
            ReleaseInternalRecoveryAdmission();
        }
        diagnostics.Write("recovery.ui-free-same-process-receipt", new
        {
            accepted,
            cycleId = recoveryCycle?.CycleId,
            detail,
            retainedCurveNodes,
            sessionRestored = accepted,
            intentReplayed,
            intentDetail,
            nextAdjustmentStillRequired = true,
        });
        // D5：会话已恢复但意图未重放 ⇒ 不宣称恢复完成（调用方据 UiFreeRecoveryComplete
        // 只结算"重开阶段"，状态落 AwaitingControl 等下一次调整）。
        if (accepted && !intentReplayed)
            diagnostics.Write("recovery.reopen-without-intent-replay", new
            {
                cycleId = recoveryCycle?.CycleId,
                intentDetail,
                outcome = "session-restored-but-recovery-not-complete",
            });
        return UiFreeRecoveryComplete(accepted, replacementRequested: false);
    }

    /** §4.1：控制意图落盘路径（与周期记录同源根，自测落隔离根）。 */
    private static string ControlIntentPath()
    {
        var isolated = Environment.GetEnvironmentVariable(HostDiagnosticLog.SelfTestLogRootEnvVar);
        var directory = string.IsNullOrWhiteSpace(isolated)
            ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "YeManCC", "fan-host")
            : isolated;
        Directory.CreateDirectory(directory);
        return Path.Combine(directory, "YeManFanHost.control-intent.json");
    }

    /**
     * §4.1（FAN-926 P2）：把**当前控制意图**落盘，供受控更换后的后继实例恢复。
     * 只写"要恢复到什么"（曲线 + 周期归属），**不写**凭据、不写命令行原文。
     */
    private void PersistControlIntentForSuccessor()
    {
        try
        {
            // 睡眠/故障边界上 `StopCurveTimer()` 已把 `activeCurve` 置空；被保留的那份在
            // `suspendedCurve`（其注释原文即"跨 HC SystemPending Close 边界保留曲线，供常驻
            // Host 重建会话"）。只读 `activeCurve` ⇒ 本文件在"睡眠→故障→受控更换"路径上
            // **恒为空**（真机 `recovery.control-intent-persisted curveNodes=0`），后继实例
            // 只能记 `control-intent-unusable(empty-curve)`，与本节"供后继恢复"的目的相反。
            var intentCurve = suspendedCurve ?? activeCurve;
            var intent = new
            {
                cycleId = recoveryCycle?.CycleId,
                predecessorInstanceId = engineInstanceId,
                curve = intentCurve,
                curveNodes = intentCurve?.Count ?? 0,
                hardwareWritesObserved = state.HardwareWritesObserved,
                persistedAtUtc = DateTimeOffset.UtcNow,
            };
            var path = ControlIntentPath();
            var staged = path + "." + Guid.NewGuid().ToString("N") + ".new";
            File.WriteAllText(staged, JsonSerializer.Serialize(intent, JsonDefaults.Options));
            File.Move(staged, path, overwrite: true);
            diagnostics.Write("recovery.control-intent-persisted", new
            {
                cycleId = recoveryCycle?.CycleId,
                curveNodes = intent.curveNodes,
            });
        }
        catch (Exception ex)
        {
            diagnostics.Write("recovery.control-intent-write-failed", new { error = ExceptionText(ex) });
        }
    }

    /**
     * §4.1（FAN-926 P2）：**恰好一次**受控 Host 更换。
     * 严格串行且不并写：先落盘控制意图 → 拉起**同映像**的后继实例（`--successor-takeover
     * --predecessor-instance <本实例>`）→ 写正式收据。后继实例只有**重建生命周期互斥成功**
     * （= 本实例确已退出）后才会开始 HC 操作；周期与剩余预算由 `EnsureRecoveryCycleLocked`
     * 的 `Inherit` 分支继承，`Replacements>=1 ⇒ RefuseReplacementCap` 保证每周期至多一次。
     * 拉起失败一律如实记账，**不**当作恢复成功。
     */
    private bool TryRequestControlledHostReplacementLocked()
    {
        if (uiFreeReplacementRequests > 1)
        {
            diagnostics.Write("recovery.host-replacement-unavailable",
                new { reason = "replacement-cap-reached-in-this-episode", cycleId = recoveryCycle?.CycleId });
            return false;
        }
        // 每故障周期至多一次自动更换——**以周期账为准**，不能以本进程的计数器为准：
        // 后继实例会以全新计数器启动，只看本进程计数就会拉起第二个后继（同周期二次更换）。
        if (recoveryCycle is null || recoveryCycle.Replacements >= 1)
        {
            diagnostics.Write("recovery.host-replacement-unavailable", new
            {
                reason = recoveryCycle is null ? "no-cycle-bound" : "replacement-cap-reached-in-cycle",
                cycleId = recoveryCycle?.CycleId,
                replacements = recoveryCycle?.Replacements ?? 0,
                replacementCap = "at-most-one-auto-host-replacement-per-cycle",
            });
            return false;
        }
        var exe = Environment.ProcessPath;
        if (string.IsNullOrWhiteSpace(exe) || !File.Exists(exe))
        {
            diagnostics.Write("recovery.host-replacement-unavailable",
                new { reason = "process-path-unavailable", exe = exe ?? "absent" });
            return false;
        }
        // D6（FAN-926R 裁决 §3）：前置停止/后继等待/接管恢复**共用同一截止时间**。
        // 余量不足以让后继获得执行时间时诚实终止，**不**拉起注定没有执行时间的实例来凑"已替换"。
        var remainingForTakeover = recoveryCycle is null ? 0 : RemainingRecoveryCycleMs(recoveryCycle);
        const int MinTakeoverBudgetMs = 3000;
        if (remainingForTakeover < MinTakeoverBudgetMs)
        {
            diagnostics.Write("recovery.host-replacement-unavailable", new
            {
                reason = "insufficient-remaining-cycle-budget-for-takeover",
                cycleId = recoveryCycle?.CycleId,
                remainingMs = remainingForTakeover,
                minRequiredMs = MinTakeoverBudgetMs,
                outcome = "failure-terminal-not-success; no-successor-spawned",
            });
            return false;
        }
        // 分配给后继的等待份额：不超过本周期剩余预算，也不超过旧常量上限。
        var allocatedTakeoverBudgetMs = (int)Math.Min(remainingForTakeover, 15000);
        PersistControlIntentForSuccessor();
        var argv = Environment.GetCommandLineArgs();
        var entry = argv.Length > 0 ? argv[0] : string.Empty;
        // 宿主可能经 `dotnet <dll>` 启动：此时 ProcessPath 是 dotnet 宿主，入口程序集在 argv[0]。
        // 两种形态都必须能正确重启**同一个** Host 载荷。
        var viaMuxer = !string.IsNullOrWhiteSpace(entry) && File.Exists(entry) &&
            !string.Equals(Path.GetFileNameWithoutExtension(entry), Path.GetFileNameWithoutExtension(exe),
                StringComparison.OrdinalIgnoreCase);
        var launchArgs = new List<string>();
        if (viaMuxer) launchArgs.Add(entry);
        launchArgs.AddRange(argv.Skip(1)
            .Where(arg => !string.Equals(arg, "--successor-takeover", StringComparison.Ordinal) &&
                          !string.Equals(arg, "--predecessor-instance", StringComparison.Ordinal) &&
                          !string.Equals(arg, "--successor-budget-ms", StringComparison.Ordinal)));
        // D6：从继承的 argv 里剔除上一代的 `--successor-budget-ms` **值**（避免旧预算被当成新预算）。
        for (var i = launchArgs.Count - 1; i > 0; i--)
        {
            if (string.Equals(launchArgs[i - 1], "--successor-budget-ms", StringComparison.Ordinal))
                launchArgs.RemoveAt(i);
        }
        launchArgs.Add("--successor-takeover");
        launchArgs.Add("--predecessor-instance");
        launchArgs.Add(engineInstanceId);
        // D6：把靠同一剩余预算分配出的接管等待预算交给后继；后继不再自带固定 15 s。
        launchArgs.Add("--successor-budget-ms");
        launchArgs.Add(allocatedTakeoverBudgetMs.ToString());
        if (options.SelfTest)
        {
            // 自测必须保持**无副作用**：不真拉起进程。进程级场景由 Fan 自有进程门覆盖。
            diagnostics.Write("recovery.host-replacement-spawned", new
            {
                predecessorInstanceId = engineInstanceId,
                successorPid = 0,
                cycleId = recoveryCycle?.CycleId,
                reopenCount = recoveryReopenCount,
                replacementRequests = uiFreeReplacementRequests,
                spawnSuppressed = "self-test-hermetic",
                proofRequired = "successor may not touch HC before it recreates the lifetime mutex",
                replacementCap = "at-most-one-auto-host-replacement-per-cycle",
                scope = "spawn-is-a-request-only; recovery is proven by the successor takeover receipt",
            });
            return true;
        }
        try
        {
            var info = new ProcessStartInfo(exe) { UseShellExecute = false, CreateNoWindow = true };
            foreach (var arg in launchArgs) info.ArgumentList.Add(arg);
            var successor = Process.Start(info);
            diagnostics.Write("recovery.host-replacement-spawned", new
            {
                predecessorInstanceId = engineInstanceId,
                successorPid = successor?.Id ?? 0,
                cycleId = recoveryCycle?.CycleId,
                reopenCount = recoveryReopenCount,
                replacementRequests = uiFreeReplacementRequests,
                proofRequired = "successor may not touch HC before it recreates the lifetime mutex",
                replacementCap = "at-most-one-auto-host-replacement-per-cycle",
                scope = "spawn-is-a-request-only; recovery is proven by the successor takeover receipt",
            });
            SchedulePredecessorOrderlyExit(successor?.Id ?? 0);
            return successor is not null;
        }
        catch (Exception ex)
        {
            diagnostics.Write("recovery.host-replacement-fault", new { error = ExceptionText(ex) });
            return false;
        }
    }

    /**
     * §4.1（FAN-926 P2）：拉起后继实例后**有序**退出本实例（绝不是强杀，也不做第二次 HC 释放——
     * 本实例的 HC 会话已经不可用，再释放只会重新撞上死路由）。留一小段让后继实例先进入互斥等待，
     * 然后走宿主进程既有的有序退出路径；请求不到退出入口时如实记账，不假装已交权。
     */
    private void SchedulePredecessorOrderlyExit(int successorPid)
    {
        // 交权期间**不得**把周期结算成"已完成"（见 CompleteRecoveryCycle）：后继实例要继承
        // 的是**同一个未结算 episode** 的剩余预算，而不是被当成新故障重开 60 s。
        replacementHandoffInFlight = true;
        _ = Task.Run(async () =>
        {
            await Task.Delay(800).ConfigureAwait(false);
            diagnostics.Write("recovery.host-replacement-predecessor-exit", new
            {
                predecessorInstanceId = engineInstanceId,
                successorPid,
                cycleId = recoveryCycle?.CycleId,
                reason = "handing sole write authority to the successor; the successor proves this exit by recreating the lifetime mutex",
                secondReleaseAttempted = false,
            });
            var requestExit = RequestHostExit;
            if (requestExit is null)
            {
                diagnostics.Write("recovery.host-replacement-predecessor-exit-unavailable",
                    new { reason = "no-orderly-exit-entry-wired", successorPid });
                return;
            }
            requestExit();
        });
    }

    /** 本引擎实例的非秘密实例 ID（§5.1：实例身份与凭据版本分列；它不是认证凭据）。 */
    private readonly string engineInstanceId = Guid.NewGuid().ToString("N");
    internal string EngineInstanceIdForBinding => engineInstanceId;

    /** §4：本引擎观测到的 HC 会话代际（由 HC 外部 profile 订阅代次提供，每次正式 Open 递增）。 */
    private long CurrentSessionGeneration => realBackend?.ExternalProfileSessionGeneration ?? 0;

    /**
     * B4（HC 回函 A1–A3）+ §4（FAN-925B）：route-lost 的**重开归 bridge**。宿主在这里只做四件事：
     * ① 记账（进入"等待重开"）；② 停止空转被第五道门挡住的 restore；
     * ③ **绑定本次重开票据**（hostInstance + recoveryCycle + sessionGeneration + 重开前操作 id 基线）；
     * ④ 有界等待与绑定核对过的重开收据（H4：`OpenEvents()` 返回 / `IsReady()` / `IsConnected`
     * / `OpenCalled` / `OpenEventsCalled` **都不算**）。
     * 同一周期第二次 route-lost ⇒ 重开环上限，如实收敛为失败终态。
     */
    private void MarkReopenRequiredLocked(string source)
    {
        recoveryReopenCount++;
        recoveryReopenRequired = true;
        reopenWaitStartedMonoMs = Environment.TickCount64;
        controlledReplacementRequested = false;
        recoveryOwner = "fan-host-budgeted-supervision;awaiting-bridge-reopen";
        // §4.1（FAN-926 P2）：新一轮重开 episode ⇒ "恰好一次"的两个计数同时归零；
        // 但**恢复周期与剩余预算不归零**（那是同一个未结算 episode 的账）。
        uiFreeSelfOpenAttempts = 0;
        uiFreeReplacementRequests = 0;
        reopenBinding = new ReopenBinding(
            engineInstanceId,
            recoveryCycle?.CycleId,
            CurrentSessionGeneration,
            realBackend?.LastCompatEntryOperationIdObserved,
            Environment.TickCount64);
        if (recoveryCycle is not null)
        {
            recoveryCycle = recoveryCycle with
            {
                LastReason = $"reopen-required:{source}",
                LastUpdatedAtUtc = DateTime.UtcNow,
            };
            PersistRecoveryCycleLocked();
        }
        var capped = ReopenLoopCapReached(recoveryReopenCount);
        diagnostics.Write(capped ? "recovery.reopen-loop-capped" : "recovery.reopen-required", new
        {
            source,
            reopenCount = recoveryReopenCount,
            cycleId = recoveryCycle?.CycleId,
            binding = reopenBinding?.Describe(),
            sessionGenerationAtBinding = reopenBinding?.SessionGeneration,
            baselineOperationId = reopenBinding?.BaselineOperationId,
            reopenSequence = "Open() -> Device_Inserted(true) -> wait for open receipt",
            receiptsOnly = "OpenEvents() return / IsReady() / IsConnected() are NOT receipts",
            bindingRule = "receipt must belong to this host instance + this recovery cycle + a session generation newer than the binding, and must not be the pre-reopen baseline operation",
            outcome = capped ? "failure-terminal-not-success" : "awaiting-bridge-reopen",
            // G-1（2026-09-27 消费侧取证）：进入等待重开这一刻拍下 HC 逐轮收据基线
            // （只读、只增字段）—— 与后一拍 `recovery.reopen-confirmed` 对读即可看出"逐轮"差异。
            hcReceipts = realBackend?.HcReceiptsEvidence,
        });
        if (capped) EnterRecoveryRetryTerminalState("reopen-loop-capped");
    }

    /** 仅自测：走真实记账路径，验证"首次 route-lost ⇒ 进入等待重开"。 */
    internal void MarkReopenRequiredForSelfTest(string source)
    {
        lock (gate) MarkReopenRequiredLocked(source);
    }

    /**
     * 仅自测（§4.5 / F07）：按**生产入口的形状**进入 FaultLocked 并调度既有恢复重试 --
     * 这正是 route-lost 未被 bridge 交出重开时的落点。用于验证"页面持续不可用"时
     * 仍有唯一 Fan 恢复执行者在工作，且全程不需要任何 UI 回调。
     */
    internal void EnterFaultLockedAndScheduleRecoveryForSelfTest()
    {
        lock (gate)
        {
            state.UnknownState = true;
            state.State = "FaultLocked";
            state.RecoveryReadbackRequired = true;
            ScheduleRecoveryRetry();
        }
    }

    internal bool RecoveryReopenRequiredForSelfTest => recoveryReopenRequired;
    internal int RecoveryReopenCountForSelfTest => recoveryReopenCount;

    /** B4 重开收据的**判定**（HC 回函 H4 + §4 FAN-925B）。纯函数：便于确定性自测。 */
    internal static bool ReopenReceiptAccepted(
        string? outcome, bool deviceBound, bool hidOpened, bool readLoopStarted, bool remapApplied) =>
        string.Equals(outcome, "Completed", StringComparison.Ordinal) &&
        deviceBound && hidOpened && readLoopStarted && remapApplied;

    /** §4：副作用字符串是否为"无"。缺字段（null/空）视为**未知**，不得当"无"。 */
    internal static bool ReopenSideEffectAbsent(string? sideEffects) =>
        string.Equals(sideEffects, "None", StringComparison.OrdinalIgnoreCase);

    /**
     * §4（FAN-925B）：结构化收据判定 —— 在 H4 的四位副作用之外，必须
     * ① `Outcome == Completed`；② `UncertainSideEffects` 为空/"None"；③ `LateSideEffects` 为空/"None"。
     * HC 字段定义里"不确定"和"迟到"是**独立字段**（不是 Outcome 名称），所以旧自测只用
     * 字符串 `UncertainSideEffects` 当 Outcome 只能证明"非 Completed 会被拒"，不足以覆盖本项。
     */
    internal static bool ReopenReceiptAccepted(
        string? outcome, bool deviceBound, bool hidOpened, bool readLoopStarted, bool remapApplied,
        string? uncertainSideEffects, string? lateSideEffects) =>
        ReopenReceiptAccepted(outcome, deviceBound, hidOpened, readLoopStarted, remapApplied) &&
        (uncertainSideEffects is null || ReopenSideEffectAbsent(uncertainSideEffects)) &&
        (lateSideEffects is null || ReopenSideEffectAbsent(lateSideEffects));

    /**
     * §4：**绑定核对**（纯函数）。返回 null 表示通过，否则返回拒绝原因。
     * 拒绝旧的/错绑的/同一操作跨实例的收据 —— 这是"旧 Completed 冒充当前恢复"的唯一闸门。
     */
    internal static string? ReopenBindingRejection(
        string? bindingHostInstanceId, string? currentHostInstanceId,
        string? bindingCycleId, string? currentCycleId,
        long bindingSessionGeneration, long currentSessionGeneration,
        string? baselineOperationId, string? observedOperationId)
    {
        if (string.IsNullOrEmpty(bindingHostInstanceId) ||
            !string.Equals(bindingHostInstanceId, currentHostInstanceId, StringComparison.Ordinal))
            return "reopen:host-instance-mismatch";
        if (bindingCycleId is not null &&
            !string.Equals(bindingCycleId, currentCycleId, StringComparison.Ordinal))
            return "reopen:recovery-cycle-changed";
        if (string.IsNullOrEmpty(observedOperationId)) return "reopen:no-operation-id";
        if (baselineOperationId is not null &&
            string.Equals(baselineOperationId, observedOperationId, StringComparison.Ordinal))
            return "reopen:still-baseline-operation";
        if (currentSessionGeneration <= bindingSessionGeneration)
            return "reopen:session-generation-unchanged";
        return null;
    }

    /** 仅自测：把"等待重开"记账复原，避免污染同一引擎上后续的恢复重试用例。 */
    internal void ResetReopenStateForSelfTest()
    {
        lock (gate)
        {
            recoveryReopenRequired = false;
            recoveryReopenCount = 0;
            reopenBinding = null;
            reopenWaitStartedMonoMs = 0;
            controlledReplacementRequested = false;
            controlledReplacementRequests = 0;
            uiFreeSelfOpenAttempts = 0;
            uiFreeReplacementRequests = 0;
            recoveryOwner = "none";
        }
    }

    /**
     * 20 s 到点时的**升级处置**（合同 §2.1）。返回还可继续持有恢复责任的时间；
     * 返回 0 ⇒ 本故障周期预算已耗尽，调用方必须走失败终态，**绝不**写成成功。
     * 只在异常路径调用：正常退出的 20 s 验收目标不变（安全收尾已完成即退）。
     */
    internal long EscalateAbnormalFinalize(string reason)
    {
        // FAN-925：异常收尾**不得**被 gate 无限期挂住。设备语料实测：旧实现的收尾决定在
        // `lock (gate)` 上等了 **5.0 s**（gate 被一条不返回的 HC 调用持有），使"20 s 预算"
        // 根本不是驻留时间上界。这里改为**有界取锁**：取不到就保守按"责任仍未结算"处理，
        // 只做有界记录，不读不写 state。
        if (!Monitor.TryEnter(gate, AbnormalFinalizeGateWaitMs))
        {
            var remainingWhileBusy = recoveryCycle is null ? 0 : RemainingRecoveryCycleMs(recoveryCycle);
            diagnostics.Write("finalize.escalation-gate-busy", new
            {
                reason,
                waitMs = AbnormalFinalizeGateWaitMs,
                remainingMs = remainingWhileBusy,
                cycleId = recoveryCycle?.CycleId,
                outcome = remainingWhileBusy > 0
                    ? "escalated-recovery-duty-retained; state-unread-gate-busy"
                    : "budget-unprovable-gate-busy",
            });
            return remainingWhileBusy;
        }
        try
        {
            var restoreDutyUnresolved = state.HcCloseCleanupPending || state.UnknownState ||
                (state.HardwareWritesObserved && !state.OemRestoreConfirmed);
            if (!restoreDutyUnresolved)
            {
                diagnostics.Write("finalize.escalation-not-needed", new { reason, state = state.State });
                return 0;
            }
            if (!EnsureRecoveryCycleLocked("finalize-escalation"))
            {
                diagnostics.Write("finalize.escalation-refused", new
                {
                    reason, state = state.State, cycleId = recoveryCycle?.CycleId,
                    replacements = recoveryCycle?.Replacements, outcome = "failure-terminal-not-success",
                });
                return 0;
            }
            // 让引擎自身的定时重试继续做唯一写入者（若尚未在跑）；不在这里发起任何新 HC 调用。
            if (recoveryTimer is null && !recoveryRetryWindowTerminal && !stopped)
            {
                state.State = state.HcCloseCleanupPending ? "AwaitingCloseCleanup" : "FaultLocked";
                ScheduleRecoveryRetry();
            }
            var remaining = recoveryCycle is null ? 0 : RemainingRecoveryCycleMs(recoveryCycle);
            diagnostics.Write("finalize.escalated-to-recovery-budget", new
            {
                reason,
                remainingMs = remaining,
                budgetMs = RecoveryRetryWindowMs,
                cycleId = recoveryCycle?.CycleId,
                attempts = recoveryRetryAttempt,
                replacements = recoveryCycle?.Replacements,
                state = state.State,
                unknownState = state.UnknownState,
                hcCloseCleanupPending = state.HcCloseCleanupPending,
                oemRestoreConfirmed = state.OemRestoreConfirmed,
                hardwareWritesObserved = state.HardwareWritesObserved,
                claimEvidence = RecoveryClaimEvidence(),
                outcome = remaining > 0 ? "escalated-recovery-duty-retained" : "budget-exhausted",
            });
            return remaining;
        }
        finally { Monitor.Exit(gate); }
    }

    /** 异常收尾预算耗尽：失败终态（不是成功，也不是 T0 通过），保留用户重试入口。 */
    internal void MarkAbnormalFinalizeTerminal(string reason)
    {
        // 同上：失败终态记录也不能被 gate 挂住（进程即将退出，取不到锁就不写状态只留痕）。
        if (!Monitor.TryEnter(gate, AbnormalFinalizeGateWaitMs))
        {
            diagnostics.Write("finalize.abnormal-budget-exhausted", new
            {
                reason,
                gateAcquired = false,
                waitMs = AbnormalFinalizeGateWaitMs,
                cycleId = recoveryCycle?.CycleId,
                outcome = "failure-terminal-not-success; state-unread-gate-busy",
            });
            return;
        }
        try
        {
            StopRecoveryRetry();
            MarkRecoveryCycleTerminalLocked(reason);
            state.State = "FaultLocked";
            state.UnknownState = true;
            state.RecoveryReadbackRequired = true;
            state.LastError = $"异常收尾预算耗尽：{reason}；恢复未证实，已进入失败终态并保留用户重试入口";
            diagnostics.Write("finalize.abnormal-budget-exhausted", new
            {
                reason,
                gateAcquired = true,
                budgetMs = RecoveryRetryWindowMs,
                maxAttempts = RecoveryRetryMaxAttempt,
                state = state.State,
                unknownState = state.UnknownState,
                hcCloseCleanupPending = state.HcCloseCleanupPending,
                oemRestoreConfirmed = state.OemRestoreConfirmed,
                oemRestoreEvidence = state.OemRestoreEvidence,
                hardwareWritesEnabled = state.HardwareWritesEnabled,
                hardwareWritesObserved = state.HardwareWritesObserved,
                cycleId = recoveryCycle?.CycleId,
                attempts = recoveryCycle?.Attempts,
                replacements = recoveryCycle?.Replacements,
                lastError = state.LastError,
                claimEvidence = RecoveryClaimEvidence(),
                outcome = "failure-terminal-not-success",
            });
        }
        finally { Monitor.Exit(gate); }
    }

    // 2026-09-23 T0（operator：绝不允许"父进程已退出而宿主不退"的死循环）：
    // 交还/停止请求之后的"安全收尾"必须有界；预算耗尽即停止重试、如实记为未证实，然后退出发送侧。
    // 2026-09-25 FAN-925 修订：正常退出场景保持该 20 s 验收目标；**异常情况下 20 s 只是升级
    // 处置点**——安全收尾未完成时按 §2.1 升级到本故障周期的 60 s/30 次预算继续持有恢复责任，
    // 预算耗尽才是失败终态（MarkAbnormalFinalizeTerminal），不得伪写成功。
    internal const int ParentExitFinalizeBudgetMs = 20000;

    /**
     * 异常收尾取引擎 gate 的**有界**等待。设备语料实测旧实现在此无限等（观测到 +5.0 s，
     * 由一条不返回的 HC 调用持锁造成）⇒ 异常路径不得再用无限 `lock`。
     */
    internal const int AbnormalFinalizeGateWaitMs = 2000;

    /**
     * FAN-925 / HC 回函 D1+D2+D3：**"能宣称什么"必须由显式字段表达，不靠文案**。
     * - D1：`CurrentDevice.Close()` 返回 ≠ 物理释放、≠ 原曲线交还（`ROGAlly.cs:347-361`
     *   `CloseForSession`→`AsusACPI.Close()`→`base.Close()`，ACPI 句柄先关 ⇒ `IDevice.cs:428`
     *   唯一写回被 `SetFanControl` 的 `if (!IsOpen) return;` **结构必然短路**）。
     * - D2：`HC_SESSION_ROUTE_LOST: hc-device-is-open-false` 由**本产品第五道门**抛出
     *   （HC 全树 0 命中），进程内可恢复（重开 + 0x5A 绑定重发布）⇒ 需要 bridge 重新 Open，
     *   **不是**"HC 会话永久不可恢复"。
     * - D3：`HcDeviceManagerStopCompleted` 是本产品硬编码值（从不调用 `DeviceManager.Stop()`），
     *   不是 HC 观测 ⇒ 不得当作设备已释放；与 `HcCloseCleanupPending` 必须分开记账。
     */
    internal object RecoveryClaimEvidence() => new
    {
        oemPhysicalOwnershipMayBeClaimed = state.OemRestoreConfirmed && state.OemPhysicalOwnershipConfirmed,
        oemRestoreConfirmed = state.OemRestoreConfirmed,
        oemPhysicalOwnershipConfirmed = state.OemPhysicalOwnershipConfirmed,
        // §3.1（FAN-925B）：三类证据分列，机器消费一致 —— 释放动作 / HC 清理 / 可选物理观察。
        oemReleaseActionKind = state.OemReleaseActionKind,
        oemReleaseActionClass = FanHostEngine.ReleaseEvidenceClass(
            state.HardwareWritesObserved, state.OemReleaseActionKind),
        // 兼容字段语义声明：它是**软件动作合同**，不是物理所有权。
        oemRestoreConfirmedIsSoftwareActionContract = true,
        // §4.5：页面不可用期间唯一承担 Fan 恢复责任的执行者 + 是否已请求受控更换。
        recoveryOwner,
        controlledReplacementRequested,
        virtualCloseIsNotPhysicalRelease = true,
        managerStopFieldIsProductHardcoded = true,
        routeLostRequiresBridgeReopen = RouteLostRequiresBridgeReopen(),
        hcCloseCleanupPending = state.HcCloseCleanupPending,
        hcDeviceManagerStopCompleted = state.HcDeviceManagerStopCompleted,
    };

    /** D2：route-lost 只能靠"重开 + 绑定重发布"出清 ⇒ 是否处于该状态。 */
    internal bool RouteLostRequiresBridgeReopen() =>
        state.LastError is { } error && error.Contains("HC_SESSION_ROUTE_LOST", StringComparison.Ordinal);

    /** 供确定性自测：断言"不可宣称项"确实以显式字段表达。 */
    internal string RecoveryClaimEvidenceJsonForSelfTest() =>
        JsonSerializer.Serialize(RecoveryClaimEvidence(), JsonDefaults.Options);

    /**
     * 正常收尾确认后结算本故障周期（由 server 的正常退出/确认关闭路径调用）。
     * 只做账目收口：不发起任何 HC/ACPI 调用，也不改变设备状态。
     */
    internal void CompleteRecoveryCycle(string reason)
    {
        lock (gate)
        {
            // §4.1（FAN-926 P2）：**受控更换交接中不得把周期标记为已完成**。否则后继实例
            // 会把同一个未结算 episode 读成"已完成 ⇒ 这是新故障"，从而**不继承**周期与剩余
            // 预算（实测就是这样：后继另起了一个全新周期）。这里只落"未结算 + 已交接"。
            if (replacementHandoffInFlight)
            {
                if (recoveryCycle is not null)
                {
                    // 交接中的 episode **必须留在未结算态**：既不许在这里完成，也要撤掉任何
                    // 更早的"已完成"标记——否则后继实例会把它读成"已完成 ⇒ 新故障"而另起新周期。
                    var clearedPrematureCompletion = recoveryCycle.Completed;
                    recoveryCycle = recoveryCycle with
                    {
                        Completed = false,
                        LastReason = "controlled-replacement-handoff-unsettled:" + reason,
                        LastUpdatedAtUtc = DateTime.UtcNow,
                    };
                    PersistRecoveryCycleLocked();
                    diagnostics.Write("recovery.cycle-handoff-unsettled", new
                    {
                        reason,
                        cycleId = recoveryCycle.CycleId,
                        replacements = recoveryCycle.Replacements,
                        clearedPrematureCompletion,
                        note = "the successor must inherit this unsettled cycle and its remaining budget",
                    });
                }
                else
                {
                    diagnostics.Write("recovery.cycle-handoff-unsettled", new
                    {
                        reason,
                        cycleId = "absent",
                        note = "no cycle was bound at handoff time; nothing to inherit",
                    });
                }
                return;
            }
            CompleteRecoveryCycleLocked(reason);
        }
    }

    /** §4.1：受控更换交接进行中（本实例正把写权交给被拉起的后继实例）。 */
    private bool replacementHandoffInFlight;

    /** §4.1：控制意图记录（只含"要恢复到什么"，**不含**凭据、不含命令行原文）。 */
    private sealed record ControlIntent(
        string? CycleId,
        string? PredecessorInstanceId,
        IReadOnlyList<FanNode>? Curve,
        int CurveNodes,
        bool HardwareWritesObserved,
        DateTimeOffset PersistedAtUtc);

    /** §4.1：读回控制意图（缺失 / 损坏 ⇒ null，绝不猜）。 */
    private ControlIntent? ReadControlIntent()
    {
        try
        {
            var path = ControlIntentPath();
            if (!File.Exists(path)) return null;
            return JsonSerializer.Deserialize<ControlIntent>(File.ReadAllText(path), JsonDefaults.Options);
        }
        catch (Exception ex)
        {
            diagnostics.Write("recovery.control-intent-read-failed", new { error = ExceptionText(ex) });
            return null;
        }
    }

    /**
     * §4.1（FAN-926 P2）：后继实例接管后**读回并恢复原控制意图**。
     * 这是宿主自身的恢复动作（与 `RestoreHardware` 同类），**不是**客户端控制动作：因此它写
     * 自己的 `recovery.control-intent-restored` 事件并显式标注 authority，绝不冒充 `api.enable`。
     * 无意图文件 / 曲线为空 / 无写权限 / 写入失败 ⇒ 一律如实记账，**不**宣称已恢复。
     */
    internal bool RestoreControlIntentAfterTakeover(out string detail)
    {
        lock (gate)
        {
            var intent = ReadControlIntent();
            if (intent is null)
            {
                detail = "intent:absent";
                diagnostics.Write("recovery.control-intent-unusable", new { reason = "no-intent-file" });
                return false;
            }
            if (intent.Curve is null || intent.Curve.Count == 0)
            {
                detail = "intent:empty-curve";
                diagnostics.Write("recovery.control-intent-unusable",
                    new { reason = "empty-curve", intent.CycleId, intent.CurveNodes });
                return false;
            }
            if (realBackend is null && !MockFanHandshakeFlag)
            {
                detail = "intent:no-write-authority";
                diagnostics.Write("recovery.control-intent-unusable",
                    new { reason = "no-write-authority", intent.CycleId, intent.CurveNodes });
                return false;
            }
            try
            {
                if (MockFanHandshakeFlag)
                {
                    state.LastTemperatureC = 55.0;
                    state.CurrentDutyPercent = 40;
                }
                else
                {
                    realBackend!.ApplyCurve(intent.Curve);
                    state.LastTemperatureC = realBackend.LastTemperatureC;
                    state.CurrentDutyPercent = realBackend.LastDutyPercent;
                }
            }
            catch (Exception ex)
            {
                detail = "intent:write-failed";
                diagnostics.Write("recovery.control-intent-unusable",
                    new { reason = "write-failed", error = ExceptionText(ex), intent.CycleId });
                return false;
            }
            activeCurve = intent.Curve;
            state.ActiveCurve = intent.Curve;
            state.HardwareWritesObserved = true;
            state.HardwareWritesEnabled = true;
            state.State = "Ready";
            diagnostics.Write("recovery.control-intent-restored", new
            {
                intent.CycleId,
                curveNodes = intent.Curve.Count,
                intent.PredecessorInstanceId,
                authority = "host-takeover-recovery",
                isClientEnable = false,
                nextAdjustmentStillRequired = true,
            });
            detail = $"intent:restored nodes={intent.Curve.Count} cycle={intent.CycleId ?? "<none>"}";
            return true;
        }
    }

    /**
     * §4.1（FAN-926 P2）：后继实例的接管恢复序列——**先开新的 HC 会话**（这正是受控更换的目的），
     * 再读回并恢复原控制意图。任一步失败都如实记账，**不**宣称已恢复。
     */
    internal void RunTakeoverRecovery()
    {
        try
        {
            _ = Open();
            _ = OpenEvents();
        }
        catch (Exception ex)
        {
            diagnostics.Write("recovery.takeover-open-failed", new { error = ExceptionText(ex) });
            return;
        }
        _ = RestoreControlIntentAfterTakeover(out var detail);
        diagnostics.Write("recovery.takeover-recovery-finished", new { detail });
    }

    private void EnsureRealSupported()
    {
        if (realBackend is null) return;
        var handshake = realBackend.LoadAndHandshake();
        state.HardwareCapable = handshake.HardwareCapable;
        state.HardwareWriteAuthorizationGranted = handshake.HardwareWriteAuthorizationGranted;
        state.FactoryType = handshake.FactoryType;
        state.FanRoute = handshake.FanRoute;
        state.FanRouteWriteReady = handshake.HardwareWriteAuthorizationGranted;
        state.DeviceIdentity = handshake.DeviceIdentity;
        state.EcEvidence = handshake.EcEvidence;
        state.ControllerFirmwareEvidence = handshake.ControllerFirmwareEvidence;
        if (!handshake.Supported) throw new FanApiException(409, "FAN_UNSUPPORTED", handshake.Reason);
        if (!realBackend.CanWrite) throw new FanApiException(403, "REAL_WRITE_AUTH_REQUIRED", "真实风扇写入需要独立授权文件与确认口令");
    }

    private static IReadOnlyList<FanNode> ParseNodes(JsonElement body)
    {
        if (!body.TryGetProperty("nodes", out var value) || value.ValueKind != JsonValueKind.Array)
            throw new FanApiException(400, "INVALID_CURVE", "缺少 nodes 曲线");
        var nodes = value.EnumerateArray().Select(node =>
        {
            if (!node.TryGetProperty("tempC", out var temp) || !node.TryGetProperty("dutyPercent", out var duty))
                throw new FanApiException(400, "INVALID_CURVE", "节点缺少 tempC/dutyPercent");
            return new FanNode(temp.GetDouble(), duty.GetDouble());
        }).ToArray();
        ValidateCurve(nodes);
        return nodes;
    }

    private static void ValidateCurve(IReadOnlyList<FanNode> nodes)
    {
        if (nodes.Count != 4) throw new FanApiException(400, "INVALID_CURVE", "曲线必须包含 4 个节点");
        if (nodes[0].TempC != 0) throw new FanApiException(400, "INVALID_CURVE", "节点 1 温度必须固定为 0°C");
        for (var i = 0; i < nodes.Count; i++)
        {
            if (double.IsNaN(nodes[i].TempC) || double.IsInfinity(nodes[i].TempC) || nodes[i].TempC is < 0 or > 100)
                throw new FanApiException(400, "INVALID_CURVE", "温度必须在 0-100°C");
            if (double.IsNaN(nodes[i].DutyPercent) || double.IsInfinity(nodes[i].DutyPercent) || nodes[i].DutyPercent is < 0 or > 100)
                throw new FanApiException(400, "INVALID_CURVE", "转速必须在 0-100%");
            if (i > 0 && nodes[i].TempC < nodes[i - 1].TempC) throw new FanApiException(400, "INVALID_CURVE", "温度节点必须递增");
            if (i > 0 && nodes[i].DutyPercent < nodes[i - 1].DutyPercent) throw new FanApiException(400, "INVALID_CURVE", "转速节点必须递增");
        }
        if (nodes[3].DutyPercent < 50) throw new FanApiException(400, "INVALID_CURVE", "节点 4 最低 50%");
    }

    private static double InterpolateCurve(IReadOnlyList<FanNode> nodes, double temperature)
    {
        if (temperature <= nodes[0].TempC) return nodes[0].DutyPercent;
        for (var i = 1; i < nodes.Count; i++)
        {
            if (temperature <= nodes[i].TempC)
            {
                var span = nodes[i].TempC - nodes[i - 1].TempC;
                return span <= 0 ? nodes[i].DutyPercent : nodes[i - 1].DutyPercent + (nodes[i].DutyPercent - nodes[i - 1].DutyPercent) * ((temperature - nodes[i - 1].TempC) / span);
            }
        }
        return nodes[^1].DutyPercent;
    }

    private void StopCurveTimer()
    {
        activeCurve = null;
        state.ActiveCurve = null;
    }

    public void Dispose()
    {
        lock (gate)
        {
            if (disposed) return;
            // A Host with a live HC session must remain resident so its
            // recovery owner can finish. Disposing the STA dispatcher here
            // would recreate the exact early-process-exit hazard that the
            // Host lifecycle gates are designed to prevent.
            if (HasLiveHardwareSession())
            {
                diagnostics.Write("engine.dispose-deferred-live-hc-session", new
                {
                    state = state.State,
                    // 判据是 HasLiveHardwareSession()，它含 `UnknownState` 与后端
                    // IsOpen/OpenAttempted。只记下面三个位会让"三假仍 defer"读起来像矛盾
                    // （真机命中原因正是未知的 unknownState=true）⇒ 六个入参全记。
                    state.UnknownState,
                    state.OpenCalled,
                    state.HardwareWritesEnabled,
                    state.HcCloseCleanupPending,
                    backendIsOpen = realBackend?.IsOpen ?? false,
                    backendOpenAttempted = realBackend?.OpenAttempted ?? false,
                });
                return;
            }
            disposed = true;
            runtimeDiagnosticsTimer?.Dispose();
            runtimeDiagnosticsTimer = null;
            ClearLease();
            StopCurveTimer();
        }
        realBackend?.Dispose();
    }

    private HostState SnapshotUnlocked()
    {
        if (realBackend is not null)
        {
            state.LastTemperatureC = realBackend.LastTemperatureC;
            state.CurrentDutyPercent = realBackend.LastDutyPercent;
                state.HcManagerFactoryStarted = realBackend.HcManagerFactoryStarted;
                state.HcManagerFactoryIsolated = realBackend.HcManagerFactoryIsolated;
                state.HcManagerFactoryLifecycle = realBackend.HcManagerFactoryLifecycle;
            state.HcManagerStatuses = realBackend.ManagerStatusSnapshot()
                .ToDictionary(pair => pair.Key, pair => pair.Value, StringComparer.Ordinal);
            state.HcOperationPhase = realBackend.CurrentHcPhase;
            state.ProfilePowerLineOnline = realBackend.ProfilePowerLineOnline;
            state.ProfileSelectionSource = realBackend.ProfileSelectionSource;
            state.ProfileTemplateFingerprint = realBackend.ProfileTemplateFingerprint;
            state.ExternalProfileEventsSubscribed = realBackend.ExternalProfileEventsSubscribed;
            state.LastExternalProfileSource = realBackend.LastExternalProfileSource;
            state.OemOwnershipStatus = realBackend.OemOwnershipStatus;
            state.HcVirtualCloseReturned = realBackend.HcVirtualCloseReturned;
            state.HcDeviceManagerStopCompleted = realBackend.HcDeviceManagerStopCompleted;
            state.HcDeviceManagerStopInvoked = realBackend.HcDeviceManagerStopInvoked;
            state.HcManagerCleanupEvidence = realBackend.HcManagerCleanupEvidence;
            state.HcDeviceManagerLifecycle = realBackend.HcDeviceManagerLifecycle;
            state.HcManagerFactoryLifecycle = realBackend.HcManagerFactoryLifecycle;
            state.OemPhysicalOwnershipConfirmed = string.Equals(
                realBackend.OemOwnershipStatus,
                "hc-default-table-readback-confirmed",
                StringComparison.Ordinal);
        }
        var snapshot = JsonSerializer.Deserialize<HostState>(JsonSerializer.Serialize(state, JsonDefaults.Options), JsonDefaults.Options)!;
        // Q1（FAN-204 s31 补充裁决 2026-09-23）：恢复阶段真值 / 建议轮询间隔 / 控制可发送性 /
        // 最近写入收据——由 ApplyDerivedSnapshotFields 统一派生（与公开 Snapshot() 同一实现）。
        ApplyDerivedSnapshotFields(snapshot);
        // /api/state is already protected by the per-session token. Expose the
        // current lease so the native-owned wake transaction can be reconciled
        // by the UI after Host completes HC Open -> OpenEvents -> Acquire.
        // The token is never written to diagnostics or returned by /health.
        // FAN-204 Q1-b：这是所有写路径的**唯一收口** ⇒ 顺带整体替换发布读快照
        // （读者在 gate 被 HC 长操作占用时拿到的就是这份"最后已知真值"）。
        Interlocked.Exchange(ref lastPublishedSnapshot, snapshot);
        return snapshot;
    }

    /**
     * Q1（2026-09-23 补充裁决）：恢复阶段派生（**单一真值源**，不新增独立状态）。
     * - FaultLocked：未知态/故障锁定（含 listener 故障）——绝不写成"处理中"；
     * - Resuming：自动恢复正在执行（state=Resuming 或 PowerOperationStatus=executing/pending）；
     * - Suspended：仍在睡眠侧（state/powerState=Suspended）；
     * - Ready：重建完成且无待清理；
     * 其余（AwaitingControl/Stopped/Suspending/AwaitingCloseCleanup/…）按名透传（诚实）。
     */
    internal static string DeriveResumePhase(HostState snapshot)
    {
        if (snapshot.UnknownState || snapshot.State is "FaultLocked" or "ListenerFaultLocked") return "FaultLocked";
        if (snapshot.State == "Resuming" || snapshot.PowerOperationStatus is "executing" or "pending") return "Resuming";
        if (snapshot.State == "Suspended" || snapshot.PowerState == "Suspended") return "Suspended";
        if (snapshot.State == "Ready" && snapshot.HcCloseCleanupPending) return "AwaitingCloseCleanup";
        if (snapshot.State == "Ready") return "Ready";
        return snapshot.State;
    }

    /** 控制可发送性：未过渡（Resuming/Suspending）、未故障/未知、无待清理、未关闭。 */
    internal static bool IsControlAccepting(HostState snapshot) =>
        !snapshot.UnknownState && !snapshot.HcCloseCleanupPending && !snapshot.CloseCalled &&
        snapshot.State is "Ready" or "AwaitingControl";
    private static long MonoMs() => Environment.TickCount64;
    private static string ExceptionText(Exception ex) => string.Join(" -> ", Unwrap(ex).Select(e => e.GetType().Name + ": " + e.Message));
    private static IEnumerable<Exception> Unwrap(Exception ex)
    {
        for (Exception? current = ex; current is not null; current = current.InnerException) yield return current;
    }
}

/**
 * Deterministic, named listener retry contract. A bind failure may recover
 * only inside both limits; once either limit is crossed the Host publishes a
 * terminal ListenerFaultLocked state. This policy is independent of HC.
 */
internal sealed class ListenerRetryBudget
{
    public const int MaxAttempts = 6;
    public const long WindowMilliseconds = 3000;
    public const int DelayMilliseconds = 250;

    private long startedAtMilliseconds;
    private int attempts;

    public int Attempts => Volatile.Read(ref attempts);
    public long ElapsedMilliseconds(long nowMilliseconds) =>
        Volatile.Read(ref startedAtMilliseconds) == 0
            ? 0
            : Math.Max(0, nowMilliseconds - Volatile.Read(ref startedAtMilliseconds));

    public bool RecordFailure(long nowMilliseconds, out int attempt, out long elapsedMilliseconds)
    {
        if (Interlocked.CompareExchange(ref startedAtMilliseconds, nowMilliseconds, 0) == 0)
            elapsedMilliseconds = 0;
        else
            elapsedMilliseconds = ElapsedMilliseconds(nowMilliseconds);
        attempt = Interlocked.Increment(ref attempts);
        return attempt < MaxAttempts && elapsedMilliseconds < WindowMilliseconds;
    }

    public void Reset()
    {
        Volatile.Write(ref attempts, 0);
        Volatile.Write(ref startedAtMilliseconds, 0);
    }

    internal static IReadOnlyList<string> RunSelfTest()
    {
        var checks = new List<string>();
        var held = new ListenerRetryBudget();
        var now = 1000L;
        var allowed = 0;
        var locked = false;
        for (var i = 0; i < MaxAttempts; i++)
        {
            if (held.RecordFailure(now, out _, out _)) allowed++;
            else locked = true;
            now += DelayMilliseconds;
        }
        if (!locked || allowed != MaxAttempts - 1 || held.Attempts != MaxAttempts)
            throw new InvalidOperationException("listener retry budget did not reach terminal state");
        checks.Add("r7-listener-held-full-budget-terminal");

        held.Reset();
        if (!held.RecordFailure(2000, out _, out _) ||
            !held.RecordFailure(2000 + DelayMilliseconds, out _, out _))
            throw new InvalidOperationException("listener retry budget rejected an in-window retry");
        held.Reset();
        var firstWindowFailure = held.RecordFailure(3000, out _, out _);
        var expiredWindowFailure = held.RecordFailure(3000 + WindowMilliseconds + 1, out _, out _);
        if (!firstWindowFailure || expiredWindowFailure)
            throw new InvalidOperationException("listener retry window did not terminate after expiry");
        checks.Add("r7-listener-released-within-window-recoverable");
        return checks;
    }
}

internal sealed class LocalFanHostServer : IDisposable
{
    /** FAN-204 Q1-b：/api/resume 去重/未知分支的收据读预算（有界，远小于任何客户端预算）。 */
    private const int ResumeReceiptReadBudgetMs = 400;
    private readonly FanHostEngine engine;
    private readonly HostOptions options;
    private readonly HostDiagnosticLog diagnostics;
    private HttpListener listener;
    private readonly CancellationTokenSource stopCts = new();
    private readonly PowerTransitionIngress powerIngress = new();
    private readonly Channel<PowerTransition> powerTransitions = Channel.CreateUnbounded<PowerTransition>(
        new UnboundedChannelOptions { SingleReader = true, SingleWriter = false });
    private Task? watchdog;
    private Task? watchdogFaultObserver;
    private int stopRequested;
    private int stopObserverScheduled;
    private int acceptedPowerTransitions;
    private int executedPowerTransitions;
    private int skippedPowerTransitions;
    private long observedPowerGeneration = 1;
    private int nativePowerGenerationObserved;
    private int fallbackPowerTarget = (int)PowerIngressTarget.Ready;
    private readonly ListenerRetryBudget listenerRetryBudget = new();
    private int listenerFaultLocked;
    private int listenerCreateCount;
    private int watchdogStartCount;
    private int powerWorkerStartCount;
    private int watchdogFaultObserved;
    // 2026-09-30 FAN-934 R2-B5：父退出收尾（HandoffForParentExitAsync）进行中标记。
    // 该收尾会经 StopListenerAfterConfirmedEngineClose -> stopCts.Cancel() 同步内联推进
    // RunAsync 主循环续体，进而经 Main 返回触发本实例的 Dispose()。此时 Dispose 与收尾
    // 处在同一任务内（Task.CurrentId 对 async 续体不可靠），若仍在 FinalizeWatchdogBeforeDispose
    // 里 task.Wait 就是等待自己。以此标记如实判别"因自身在收尾路径上而延后"。
    private int watchdogHandoffActive;
    // PID alone is not a durable parent identity on Windows: after YeManCC
    // exits, the same PID can be assigned to an unrelated process. Capture
    // start/path evidence once and require it on every watchdog check.
    private readonly DateTime? parentStartTimeUtc;
    private readonly string? parentExecutablePath;

    private readonly record struct PowerTransition(
        string Name,
        PowerIngressTarget Target,
        PowerEventMetadata Metadata,
        Func<object> Action,
        TaskCompletionSource<object?>? Completion);

    public LocalFanHostServer(FanHostEngine engine, HostOptions options, HostDiagnosticLog? diagnostics = null)
    {
        this.engine = engine;
        this.options = options;
        this.diagnostics = diagnostics ?? new HostDiagnosticLog();
        // 第十六轮返修（admission/commit）：准入发布的"边沿归属"接线——睡眠保护
        // 只有在本 ingress 当前已宣布边沿仍是 Suspended 时才提交（更新的边沿意味着
        // 该睡眠已被后续唤醒覆盖，迟到发布必须收敛为"无保护"而非无主待办）。
        engine.SuspendEdgeCurrentProbe = () => powerIngress.AnnouncedEdge.Target == PowerIngressTarget.Suspended;
        if (options.ParentPid is int parentPid)
            (parentStartTimeUtc, parentExecutablePath) = CaptureParentIdentity(parentPid);
        else if (!string.IsNullOrWhiteSpace(options.ParentProcessName))
            (parentStartTimeUtc, parentExecutablePath) = CaptureNamedParentIdentity(options.ParentProcessName);
        listener = CreateListener();
    }

    private static (DateTime? StartTimeUtc, string? ExecutablePath) CaptureParentIdentity(int pid)
    {
        try
        {
            using var process = Process.GetProcessById(pid);
            if (process.HasExited) return (null, null);
            DateTime? start = null;
            string? path = null;
            try { start = process.StartTime.ToUniversalTime(); } catch { }
            try { path = process.MainModule?.FileName; } catch { }
            return (start, path);
        }
        catch { return (null, null); }
    }

    private static (DateTime? StartTimeUtc, string? ExecutablePath) CaptureNamedParentIdentity(string name)
    {
        var normalized = Path.GetFileNameWithoutExtension(name);
        var matches = Process.GetProcessesByName(normalized);
        try
        {
            var alive = matches.Where(process =>
            {
                try { return !process.HasExited; }
                catch { return false; }
            }).ToArray();
            // A name-only parent is usable only when exactly one process is
            // present and its identity can be captured. Ambiguity is a
            // recovery condition, never permission to keep an HC session.
            if (alive.Length != 1) return (null, null);
            var process = alive[0];
            DateTime? start = null;
            string? path = null;
            try { start = process.StartTime.ToUniversalTime(); } catch { }
            try { path = process.MainModule?.FileName; } catch { }
            return (start, path);
        }
        finally
        {
            foreach (var process in matches) process.Dispose();
        }
    }

    private HttpListener CreateListener()
    {
        var next = new HttpListener();
        next.Prefixes.Add($"http://127.0.0.1:{options.Port}/");
        Interlocked.Increment(ref listenerCreateCount);
        return next;
    }

    private void StartParentWatchdog()
    {
        Interlocked.Increment(ref watchdogStartCount);
        watchdog = WatchParentAsync(stopCts.Token);
        watchdogFaultObserver = ObserveWatchdogTask(watchdog);
    }

    private Task ObserveWatchdogTask(Task task)
    {
        return task.ContinueWith(
            completed =>
            {
                if (!completed.IsFaulted) return;
                Interlocked.Exchange(ref watchdogFaultObserved, 1);
                var error = completed.Exception?.GetBaseException();
                diagnostics.Write("parent-watchdog.unhandled-observed", new
                {
                    error = error is null ? "unknown" : ExceptionText(error),
                });
                _ = completed.Exception;
            },
            CancellationToken.None,
            TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);
    }

    private async Task<bool> RetryListenerAsync(Exception error)
    {
        var now = Environment.TickCount64;
        var canRetry = listenerRetryBudget.RecordFailure(now, out var attempt, out var elapsed);
        diagnostics.Write("listener.retry", new
        {
            attempt,
            maxAttempts = ListenerRetryBudget.MaxAttempts,
            elapsedMilliseconds = elapsed,
            retryWindowMilliseconds = ListenerRetryBudget.WindowMilliseconds,
            delayMilliseconds = ListenerRetryBudget.DelayMilliseconds,
            port = options.Port,
            error = ExceptionText(error),
            canRetry,
        });
        try { listener.Close(); } catch { }
        if (!canRetry) return false;
        listener = CreateListener();
        try
        {
            await Task.Delay(ListenerRetryBudget.DelayMilliseconds, stopCts.Token).ConfigureAwait(false);
            return !stopCts.IsCancellationRequested;
        }
        catch (OperationCanceledException)
        {
            return false;
        }
    }

    private async Task HandleListenerFaultLockedAsync(Exception error)
    {
        if (Interlocked.Exchange(ref listenerFaultLocked, 1) != 0) return;
        engine.MarkListenerFaultLocked(error);
        diagnostics.Write("listener.fault-locked", new
        {
            port = options.Port,
            attempts = listenerRetryBudget.Attempts,
            elapsedMilliseconds = listenerRetryBudget.ElapsedMilliseconds(Environment.TickCount64),
            maxAttempts = ListenerRetryBudget.MaxAttempts,
            retryWindowMilliseconds = ListenerRetryBudget.WindowMilliseconds,
        });

        // Stop accepting new HTTP work immediately, but keep the Host alive
        // until the existing single engine Close/recovery owner is safe.
        try { if (listener.IsListening) listener.Stop(); } catch { }
        powerIngress.BeginClose();
        try
        {
            engine.Close();
            powerIngress.CompleteClose();
            StopListenerAfterConfirmedEngineClose(StopListenerPath.ConfirmedRelease);
        }
        catch (Exception closeError)
        {
            diagnostics.Write("listener.fault-locked.close-deferred", new
            {
                error = ExceptionText(closeError),
                state = engine.Snapshot().State,
            });
            // The engine's existing recovery timer remains the sole retry
            // owner. Await its terminal state without re-entering Close.
            await ObserveRequestedStopAsync().ConfigureAwait(false);
        }
    }

    public async Task RunAsync()
    {
        // The parent YMCC process is the sole Windows power-lifecycle owner.
        // FanHost only executes authenticated, generation-tagged API commands;
        // subscribing here would create a second suspend/resume owner.
        StartParentWatchdog();
        Interlocked.Increment(ref powerWorkerStartCount);
        _ = ProcessPowerTransitionsAsync(stopCts.Token);
        while (!stopCts.IsCancellationRequested && Volatile.Read(ref listenerFaultLocked) == 0)
        {
            try
            {
                if (!listener.IsListening) listener.Start();
                if (listenerRetryBudget.Attempts != 0)
                {
                    diagnostics.Write("listener.recovered", new
                    {
                        port = options.Port,
                        attempts = listenerRetryBudget.Attempts,
                    });
                    listenerRetryBudget.Reset();
                }
                engine.MarkListenerReady();
                // Handshake is a read-only capability probe. Run it once as
                // soon as the resident listener is ready so a frontend that
                // misses its first request cannot leave the Fan route hidden
                // while HC has never been queried at all. This never calls
                // Open(), OpenEvents(), EC, ACPI or a fan write.
                if (options.RealBackend)
                {
                    try
                    {
                        var startupHandshake = engine.Handshake();
                        diagnostics.Write("startup.handshake", startupHandshake);
                    }
                    catch (Exception ex)
                    {
                        diagnostics.Write("startup.handshake-failure", new { error = ExceptionText(ex) });
                    }
                }
                diagnostics.Write("listener.ready", new { options.Port, options.RealBackend });
                while (!stopCts.IsCancellationRequested)
                {
                    HttpListenerContext context;
                    try { context = await listener.GetContextAsync().WaitAsync(stopCts.Token); }
                    catch (OperationCanceledException) { break; }
                    catch (HttpListenerException) when (stopCts.IsCancellationRequested) { break; }
                    // 2026-09-25 C1 复现中发现：确认停止时 `StopListenerAfterConfirmedEngineClose`
                    // 先 `stopCts.Cancel()` 再 `listener.Stop()`；本循环若正好在该窗口内重新
                    // 发起 `GetContextAsync()`，HttpListener 会以
                    // `InvalidOperationException("Please call the Start() method before calling this method.")`
                    // 同步抛出——它既不是 OCE 也不是 HttpListenerException，且外层
                    // `when (!stopCts.IsCancellationRequested)` 过滤器此时为假 ⇒ 会逃出
                    // `RunAsync()`，把一次**已确认的正常停止**变成进程级未处理异常
                    // （候选自测 3 次中出现 1 次；`RunR6R7SafetySelfTestAsync` 直接 await 该任务）。
                    // 语义与上一行一致：取消之后"监听器已不再监听"是**预期停止**，不是传输故障。
                    catch (InvalidOperationException) when (stopCts.IsCancellationRequested) { break; }
                    _ = Task.Run(() => HandleAsync(context), stopCts.Token);
                }
            }
            catch (OperationCanceledException) when (stopCts.IsCancellationRequested) { break; }
            catch (Exception ex) when (!stopCts.IsCancellationRequested)
            {
                engine.MarkTransportFault(ex);
                diagnostics.Write("listener.fault", new { error = ExceptionText(ex) });
                // Collision diagnostics are retained in the structured Host
                // log. Do not mirror the expected finite-retry faults to
                // stderr: safe regression runners consume stdout as JSON and
                // stderr must remain reserved for unhandled process errors.
                if (stopCts.IsCancellationRequested) break;
                if (!await RetryListenerAsync(ex).ConfigureAwait(false))
                {
                    await HandleListenerFaultLockedAsync(ex).ConfigureAwait(false);
                    break;
                }
            }
        }
    }

    public void Stop()
    {
        if (stopCts.IsCancellationRequested) return;
        // ProcessExit, Dispose and /api/shutdown can all arrive after one
        // another. They share one HC close ownership boundary; only the first
        // one may initiate it. Later calls only observe completion.
        if (Interlocked.Exchange(ref stopRequested, 1) != 0) return;
        powerIngress.BeginClose();
        try { engine.Close(); }
        catch (Exception ex)
        {
            if (Volatile.Read(ref listenerFaultLocked) == 0)
                powerIngress.ReopenAfterFailedClose();
            diagnostics.Write("host.stop-restore-unconfirmed", new { error = ExceptionText(ex) });
            // Do not tear down the listener after an unconfirmed OEM restore.
            // Keeping the endpoint alive is the recovery path: the caller can
            // retry /api/close after HC/EC becomes responsive again.
            Console.Error.WriteLine($"YeManFanHost remains resident: OEM restore not confirmed: {ex.Message}");
            if (Interlocked.Exchange(ref stopObserverScheduled, 1) == 0)
                _ = ObserveRequestedStopAsync();
            return;
        }
        powerIngress.CompleteClose();
        engine.CompleteRecoveryCycle("stop-confirmed");
        StopListenerAfterConfirmedEngineClose(StopListenerPath.ConfirmedRelease);
    }

    private async Task ObserveRequestedStopAsync()
    {
        // 2026-09-23 T0：显式停止请求（/api/close 未证实）同样有界——不许无限期驻留。
        // 2026-09-25 FAN-925 §2.1：异常情况下 20 s 只是升级处置点，见 ObserveFinalizeBoundedAsync。
        await ObserveFinalizeBoundedAsync("requested-stop", stopCts.Token).ConfigureAwait(false);
    }

    /**
     * 有界收尾观察（FAN-925 §2.1 / T0-X）。
     * 正常路径：安全收尾完成即停监听并退出（保留既有 20 s 验收目标，不强迫常驻）。
     * 异常路径：20 s 到点且恢复责任仍未结算 ⇒ 升级到本故障周期的 60 s/30 次预算，
     *           由引擎自身的定时重试继续持有唯一写入权；预算耗尽 ⇒ **失败终态**。
     * 任何分支都不伪写成功，也不无界驻留。
     */
    private async Task ObserveFinalizeBoundedAsync(string reason, CancellationToken cancellationToken)
    {
        var escalationDeadline = Environment.TickCount64 + FanHostEngine.ParentExitFinalizeBudgetMs;
        var escalated = false;
        while (!cancellationToken.IsCancellationRequested)
        {
            if (ParentRecoveryIsSafeToFinalize(engine.Snapshot()))
            {
                StopListenerAfterConfirmedEngineClose(StopListenerPath.BoundedFinalizeSafe);
                return;
            }
            var now = Environment.TickCount64;
            if (now >= escalationDeadline)
            {
                if (!escalated)
                {
                    escalated = true;
                    var remaining = engine.EscalateAbnormalFinalize(reason);
                    if (remaining > 0) escalationDeadline = now + remaining;
                }
                if (now >= escalationDeadline)
                {
                    // 预算耗尽：失败终态（不是清理成功，也不是 T0 通过）。
                    engine.MarkAbnormalFinalizeTerminal(reason);
                    StopListenerAfterConfirmedEngineClose(StopListenerPath.FailureTerminal);
                    return;
                }
            }
            try { await Task.Delay(500, cancellationToken).ConfigureAwait(false); }
            catch (OperationCanceledException) { return; }
        }
    }

    /**
     * §4.B（FAN-934）：停监听的实际触发路径。
     * 旧写法把所有路径都记成同一个 `host.stopped`，读日志的人会把它当成"进程已退出"，
     * 而实际上宿主实例可能仍在采样/仍持有引擎句柄。故本批按路径分列报告。
     */
    internal enum StopListenerPath
    {
        /** Stop()/fault-locked 路径：OEM 恢复已确认，正常安全关闭。 */
        ConfirmedRelease,
        /** 父退出有界收尾：恢复已可安全终结，属正常安全关闭。 */
        BoundedFinalizeSafe,
        /** 父退出有界收尾：恢复预算耗尽 ⇒ 失败终态（不是清理成功，也不是 T0 通过）。 */
        FailureTerminal,
    }

    /**
     * The parent watchdog may finalize the listener only after the engine has
     * already confirmed its HC Close/OEM boundary. This is deliberately
     * separate from Stop(): a failed Stop must not call engine.Close() again.
     *
     * §4.B（FAN-934）：本事件只描述"本宿主实例停止接受控制/采样"，
     * **不是**"进程已退出"的证明——引擎/驱动句柄的最终释放被延后到进程收尾，
     * 失败终态也不等于清理成功。真进程退出由外部 watchdog 以 pid＋启动时间观测证明。
     */
    private void StopListenerAfterConfirmedEngineClose(StopListenerPath path)
    {
        if (stopCts.IsCancellationRequested) return;
        var wasListening = listener.IsListening;
        // 2026-09-30 FAN-934 R2-B5：先把"本宿主实例停止接受控制/采样"的如实记录落盘，
        // 再取消 stopCts。Cancel() 会**同步内联**推进 RunAsync 主循环中
        // `GetContextAsync().WaitAsync(stopCts.Token)` 的续体，进而经 RunAsync 返回 ->
        // Main 返回 -> `using var host` 触发 Dispose() 在此线程上重入完成进程收尾。
        // 若记录放在 Cancel() 之后（旧写法），该重入收尾可能在本方法返回前就结束，
        // 造成 host.stopped 永不落盘（正是 R2-B5 父退出门的确定性失败原因）。
        powerTransitions.Writer.TryComplete();
        diagnostics.Write("host.stopped", new
        {
            path = path.ToString(),
            // 三种语义分列，互不冒充：
            listenerStopped = wasListening,                       // 本调用是否真的停掉了仍在监听的 listener
            engineDisposeDeferred = true,                         // 引擎/驱动释放不在本边界发生，延后到进程收尾
            failureTerminal = path == StopListenerPath.FailureTerminal, // 预算耗尽 ⇒ 失败终态
            // 进程是否真正退出必须由外部证据判定：
            processExitProven = false,
            processExitEvidence = "external-watchdog-pid+start-time",
        });
        // 记录已落盘，现在取消 token。必须先 Cancel 再 listener.Stop()：否则 Stop() 造成的
        // HttpListenerException 会落到 RunAsync 的故障分支并被当成监听器故障（二次 Close）。
        stopCts.Cancel();
        if (wasListening) listener.Stop();
    }

    /** §6 F02（FAN-925B）：暴露收尾安全判据（纯函数）供正反例自测。 */
    internal static bool ParentRecoveryIsSafeToFinalizeForSelfTest(HostState snapshot) =>
        ParentRecoveryIsSafeToFinalize(snapshot);

    private static bool ParentRecoveryIsSafeToFinalize(HostState snapshot)
    {
        var liveWrites = snapshot.HardwareWritesEnabled || snapshot.HardwareWrites;
        // §3.1/§3.4（FAN-925B）：释放动作证据与 HC 资源清理**分列**。
        // 这里的 `hcCloseComplete` 只描述"HC 关闭边界完整"，**不再**能顶替释放动作
        // （旧写法 `|| hcCloseComplete` 会在 route-lost/skipOemRestore 路径上把
        // "一次写入都没尝试"报成收尾安全 —— 就是本批要挡的假成功，F02）。
        var hcCloseComplete = snapshot.HcVirtualCloseReturned &&
            snapshot.HcDeviceManagerStopCompleted &&
            snapshot.HcManagerFactoryLifecycle == "Started" &&
            snapshot.HcDeviceManagerLifecycle == "Started";
        var releaseEvidence = FanHostEngine.IsOemReleaseSafe(
            snapshot.HardwareWritesObserved,
            snapshot.OemReleaseActionKind);
        var cleanupEvidence = hcCloseComplete || !snapshot.HcVirtualCloseReturned;
        return snapshot.State == "Stopped" &&
            !snapshot.UnknownState &&
            !snapshot.HcCloseCleanupPending &&
            !liveWrites &&
            !snapshot.OpenCalled &&
            !snapshot.OpenEventsCalled &&
            cleanupEvidence &&
            releaseEvidence;
    }

    private PowerEventMetadata NormalizePowerEvent(
        PowerIngressTarget target,
        long requestedGeneration,
        string? requestedSource)
    {
        var source = string.IsNullOrWhiteSpace(requestedSource) ? "yeman.power" : requestedSource.Trim();
        if (requestedGeneration > 0)
        {
            while (true)
            {
                var current = Volatile.Read(ref observedPowerGeneration);
                if (requestedGeneration <= current) break;
                if (Interlocked.CompareExchange(ref observedPowerGeneration, requestedGeneration, current) == current) break;
            }
            Volatile.Write(ref fallbackPowerTarget, (int)target);
            if (source.StartsWith("native", StringComparison.OrdinalIgnoreCase))
                Volatile.Write(ref nativePowerGenerationObserved, 1);
            return new PowerEventMetadata(requestedGeneration, source);
        }

        // SystemEvents.PowerModeChanged does not carry the native generation.
        // Before an authoritative native event is seen, give a standalone Host
        // observer a monotonic fallback identity. Once native metadata has been
        // observed, keep the current generation so a duplicate/reverse callback
        // can be suppressed as the same physical edge rather than inventing a
        // newer cycle for a late notification.
        if (Volatile.Read(ref nativePowerGenerationObserved) != 0)
            return new PowerEventMetadata(Math.Max(1, Volatile.Read(ref observedPowerGeneration)), source);

        while (true)
        {
            var previousTarget = Volatile.Read(ref fallbackPowerTarget);
            if (previousTarget == (int)target)
                return new PowerEventMetadata(Math.Max(1, Volatile.Read(ref observedPowerGeneration)), source);
            if (Interlocked.CompareExchange(ref fallbackPowerTarget, (int)target, previousTarget) == previousTarget)
            {
                var generation = Interlocked.Increment(ref observedPowerGeneration);
                return new PowerEventMetadata(Math.Max(1, generation), source);
            }
        }
    }

    private PowerEventMetadata MetadataFromPowerBody(
        PowerIngressTarget target,
        JsonElement body,
        string fallbackSource)
    {
        long generation = 0;
        if (body.ValueKind == JsonValueKind.Object &&
            body.TryGetProperty("generation", out var generationValue) &&
            generationValue.ValueKind == JsonValueKind.Number)
            generationValue.TryGetInt64(out generation);
        var source = fallbackSource;
        if (body.ValueKind == JsonValueKind.Object &&
            body.TryGetProperty("source", out var sourceValue) &&
            sourceValue.ValueKind == JsonValueKind.String &&
            !string.IsNullOrWhiteSpace(sourceValue.GetString()))
            source = sourceValue.GetString()!;
        return NormalizePowerEvent(target, generation, source);
    }

    private object SuspendOnPowerWorker()
    {
        // A close owner may have already blocked writes while a queued
        // suspend is waiting. Do not re-assert the suspend gate after a failed
        // close; the close owner/recovery retry is the sole authority then.
        if (engine.IsCloseWriteBlockedForPower) return engine.SnapshotForRead();
        return engine.SuspendForSystemPower();
    }

    private PowerPublishResult QueuePowerTransition(
        string name,
        PowerIngressTarget target,
        PowerEventMetadata metadata,
        Func<object> action,
        TaskCompletionSource<object?>? completion = null,
        Action? acceptedCallback = null)
    {
        // TryPublish is lock-free and Channel.TryWrite is non-blocking.  Do
        // not add diagnostics here: this method is called by the Windows
        // callback as well as by the API request path.
        // 第十五/十六轮返修（统一准入协议）：只有真正获准入（writer 被调用）的睡眠
        // 边沿才落位写门；写门变更严格先于该转换入队（对消费者可见），因此任何后到
        // 的恢复读取 gate 版本时必然看到它。拒绝（writer 返回 false）不回退写门——
        // 被拒边沿保留为 deferred，写门保持阻断（fail-closed，无版本回退）。
        var result = powerIngress.TryPublish(target, metadata, () =>
        {
            if (target == PowerIngressTarget.Suspended)
                engine.BlockWritesForSuspendNow();
            return powerTransitions.Writer.TryWrite(new PowerTransition(name, target, metadata, action, completion));
        },
        // 第十八轮返修：claim 成功瞬间铸造接受记录（不可变身份 + claim 时的保护
        // 提交边界）——边界在 TryPublish 内部取，杜绝"claim 后、Enter 前被抢占"
        // 导致的边界漂移。
        claimBoundaryProvider: () => engine.SuspendProtectionCommitBoundary,
        out var acceptance);
        if (result == PowerPublishResult.Queued)
        {
            Interlocked.Increment(ref acceptedPowerTransitions);
            // 第二十四轮（任务书 D）：接受侧身份落盘（claim/acceptance/边界）——与
            // power.transition-complete 的 generation/source 一起构成可重放的同一身份链。
            if (acceptance is { } admittedEdge)
                diagnostics.Write("power.transition-accepted", new
                {
                    name,
                    target = target.ToString(),
                    generation = metadata.Generation,
                    source = metadata.Source,
                    claimId = admittedEdge.AcceptanceId,
                    boundaryStamp = admittedEdge.ProtectionBoundaryStamp,
                });
            if (acceptedCallback is not null && acceptance is { } acceptedEdge)
            {
                // 第十五/十七/十八轮返修：睡眠保护只在准入成功后发布（调用方提供
                // 发布动作；生产 API 与自测入口共用同一实现）。Stale/Suppressed/
                // Closed/Rejected 永不调用 ⇒ 零副作用；接受上下文携带本次接受
                // 记录——迟到回调（期间已有更新的保护提交）只能 no-op。
                var previousContext = engine.EnterSuspendAdmissionContext(acceptedEdge);
                try { acceptedCallback(); }
                finally { engine.ExitSuspendAdmissionContext(previousContext); }
            }
        }
        return result;
    }

    // R2 safe integration hooks. They invoke the production callback and queue
    // path; they never load HC because the self-test HostOptions use the safe
    // backend. They are internal so no HTTP route or release API is added.
    internal void InvokePowerModeChangedForSelfTest(PowerModes mode)
    {
        // Test-only injection models the native parent command and therefore
        // always carries an explicit generation/source pair.
        var target = mode == PowerModes.Suspend
            ? PowerIngressTarget.Suspended
            : PowerIngressTarget.Ready;
        var metadata = NormalizePowerEvent(target, Math.Max(1, Volatile.Read(ref observedPowerGeneration) + 1), "selftest.native");
        // 第十三/十五轮返修：与生产入口共用同一准入操作（QueuePowerTransition）——
        // suspend 侧：保护由"准入成功"回调发布（AnnounceSuspendPending），写门随
        // 准入写入前落位；非 Queued 零副作用（无宣布、无回滚）。resume 侧：接受点
        // 快照待办版本并随队列传递。
        if (mode == PowerModes.Suspend)
        {
            QueuePowerTransition(
                "suspend",
                target,
                metadata,
                SuspendOnPowerWorker,
                acceptedCallback: engine.AnnounceSuspendPending);
            return;
        }
        // 第二十二轮（P1#2）：与生产 API 一致——接受点同时快照保护**值 + 授权归属**。
        var accepted = engine.SuspendProtectionAuthorizationSnapshot;
        QueuePowerTransition(
            "resume",
            target,
            metadata,
            () => engine.ResumeForSystemPower(metadata.Generation, accepted.Value, accepted.Stamp));
    }

    internal Task StartPowerWorkerForSelfTest() => ProcessPowerTransitionsAsync(stopCts.Token);
    /** T7：当前已观察到的 native 代次——自测据此给出严格更新的代次（避免误判 Stale）。 */
    internal long ObservedPowerGenerationForSelfTest => Volatile.Read(ref observedPowerGeneration);
    internal Task<object> SuspendForSelfTest() => SuspendForSelfTest(1);
    /**
     * T7（2026-09-19）：带显式代次的睡眠入口。生产用 1 即可；自测需要"已观察到 native
     * 代次之后再次睡眠"时，必须给出**严格更新**的代次，否则 ingress 会按设计判 Stale
     * （`metadata.Generation < previous.Generation`）。
     */
    internal Task<object> SuspendForSelfTest(long generation) =>
        SuspendFromApiAsync(JsonDocument.Parse(
            $"{{\"generation\":{Math.Max(1, generation)},\"source\":\"selftest.native\"}}").RootElement.Clone());
    internal Task<object> ResumeForSelfTest()
    {
        // The integration sequence may already have consumed several native
        // edges. Use the next announced generation so the test exercises the
        // same tagged boundary as production instead of manufacturing a
        // stale request that production must correctly reject.
        var generation = Math.Max(1, Volatile.Read(ref observedPowerGeneration) + 1);
        return ResumeFromApiAsync(JsonDocument.Parse(
            $"{{\"generation\":{generation},\"source\":\"selftest.native\"}}").RootElement.Clone());
    }
    internal object CloseForSelfTest() => CloseFromApi();
    internal void CompletePowerQueueForSelfTest() => powerTransitions.Writer.TryComplete();
    internal int AcceptedPowerTransitionsForSelfTest => Volatile.Read(ref acceptedPowerTransitions);
    internal int ExecutedPowerTransitionsForSelfTest => Volatile.Read(ref executedPowerTransitions);
    internal int SkippedPowerTransitionsForSelfTest => Volatile.Read(ref skippedPowerTransitions);
    internal PowerIngressTarget? DeferredPowerTargetForSelfTest => powerIngress.DeferredTarget;
    internal bool PowerIngressClosingForSelfTest => powerIngress.IsClosing;
    internal void SetCloseOwnerDelayForSelfTest(int milliseconds) => engine.SetCloseOwnerDelayForSelfTest(milliseconds);
    internal void ResolveUncertainStateForSelfTest() => engine.ResolveUncertainStateForSelfTest();
    internal string ListenerStateForSelfTest => engine.Snapshot().ListenerState;
    internal int ListenerRetryAttemptsForSelfTest => listenerRetryBudget.Attempts;
    internal int ListenerCreateCountForSelfTest => Volatile.Read(ref listenerCreateCount);
    internal int WatchdogStartCountForSelfTest => Volatile.Read(ref watchdogStartCount);
    internal int PowerWorkerStartCountForSelfTest => Volatile.Read(ref powerWorkerStartCount);
    internal bool WatchdogFaultObservedForSelfTest => Volatile.Read(ref watchdogFaultObserved) != 0;
    internal void InjectWatchdogTaskForSelfTest(Task task)
    {
        watchdog = task;
        watchdogFaultObserver = ObserveWatchdogTask(task);
    }
    internal PowerPublishResult PublishPowerForSelfTest(PowerIngressTarget target) =>
        QueuePowerTransition(
            $"selftest-{target}", target,
            NormalizePowerEvent(target, 0, "self-test"),
            () => engine.Snapshot());

    private async Task ProcessPowerTransitionsAsync(CancellationToken cancellationToken)
    {
        try
        {
            await foreach (var transition in powerTransitions.Reader.ReadAllAsync(cancellationToken))
            {
                if (cancellationToken.IsCancellationRequested) return;
                if (powerIngress.IsClosing)
                {
                    Interlocked.Increment(ref skippedPowerTransitions);
                    transition.Completion?.TrySetResult(engine.Snapshot());
                    diagnostics.Write("power.transition-skipped-close", new
                    {
                        transition.Name,
                        target = transition.Target.ToString(),
                        generation = transition.Metadata.Generation,
                        source = transition.Metadata.Source,
                    });
                    continue;
                }
                try
                {
                    Interlocked.Increment(ref executedPowerTransitions);
                    var result = transition.Action();
                    transition.Completion?.TrySetResult(result);
                    // D7（FAN-926R 裁决 §3）：`power.transition-complete` 只表示**回调动作已返回**，
                    // 不代表请求目标已达成。请求目标 / 实际状态 / 结果分开记，避免消费方把
                    // FaultLocked 读成 Ready；字段都在手（action 的返回值），不额外取锁。
                    var actualState = (result as HostState)?.State ?? "unknown";
                    var requestTarget = transition.Target.ToString();
                    diagnostics.Write("power.transition-complete", new
                    {
                        transition.Name,
                        stage = "action-returned",
                        requestTarget,
                        actualState,
                        outcome = string.Equals(actualState, requestTarget, StringComparison.OrdinalIgnoreCase)
                            ? "target-reached"
                            : "target-not-reached",
                        target = requestTarget,
                        generation = transition.Metadata.Generation,
                        source = transition.Metadata.Source,
                    });
                }
                catch (Exception ex)
                {
                    transition.Completion?.TrySetException(ex);
                    diagnostics.Write("power.transition-failure", new
                    {
                        transition.Name,
                        target = transition.Target.ToString(),
                        generation = transition.Metadata.Generation,
                        source = transition.Metadata.Source,
                        error = ExceptionText(ex),
                    });
                    Console.Error.WriteLine($"YeManFanHost {transition.Name} transition failed: {ex.GetType().Name}: {ex.Message}");
                }
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task WatchParentAsync(CancellationToken cancellationToken)
    {
        if (options.ParentPid is null && string.IsNullOrWhiteSpace(options.ParentProcessName)) return;
        // FAN-931 P1.3：**一次绑定可信父实例，然后等待它退出**。旧实现每 2 s 重新
        // Process.GetProcessById + 重读 HasExited/StartTime/MainModule，在整段会话里反复做
        // 同样的系统调用（也是本批确认可削减的重复工作之一）。
        var (bound, bindReason) = TryBindParentProcess();
        if (bound is null)
        {
            // 绑定失败（身份不可读 / 与启动时身份不符 / 同名单实例不成立 / 句柄不能打开）：
            // 与旧实现"读不到父身份即按结束处理"一致地保守收尾——不把 alive 永久缓存，也不
            // 静默继续持有 HC 会话。原因可判定、可事后核对。
            diagnostics.Write("parent-watchdog.bind-unavailable", new
            {
                reason = bindReason,
                parentPid = options.ParentPid,
                parentProcess = options.ParentProcessName,
                action = "conservative-handoff",
            });
            await HandoffForParentExitAsync(cancellationToken).ConfigureAwait(false);
            return;
        }
        using (bound)
        {
            try
            {
                await bound.WaitForExitAsync(cancellationToken).ConfigureAwait(false);
            }
            catch (OperationCanceledException) { return; }
            catch (Exception ex)
            {
                // 句柄不可等待（权限/平台差异）：退化为**同一句柄**上的有界轮询（只读 HasExited，
                // 不再重开句柄、不再重读映像），并如实记录降级原因，绝不静默失去退出保护。
                diagnostics.Write("parent-watchdog.wait-degraded", new { error = ExceptionText(ex) });
                if (!await PollBoundParentUntilExitAsync(bound, cancellationToken).ConfigureAwait(false)) return;
            }
        }
        await HandoffForParentExitAsync(cancellationToken).ConfigureAwait(false);
    }

    /** FAN-931 P1.3：父实例退出后的唯一收尾路径（显式父退出与看门狗共用同一条责任链）。 */
    private async Task HandoffForParentExitAsync(CancellationToken cancellationToken)
    {
        // Parent termination is a single HC lifecycle boundary. Do
        // not call Stop() on every watchdog tick: after one HC Close
        // timeout that would repeatedly re-enter the same serialized
        // ManagerFactory/ACPI gate and recreate the high-CPU loop seen
        // in the ROG log. The engine recovery timer is the sole
        // writer/retry owner; this watcher only observes its state.
        var handoff = engine.BeginParentExitHandoff();
        diagnostics.Write("parent-watchdog.handoff", handoff);
        // 2026-09-25 FAN-925 §2.1：交还后的收尾仍然有界，但异常情况下 20 s 只是
        // **升级处置点**——不得把尚未完成的恢复责任在 20 s 一并结束（旧实现即如此）。
        Interlocked.Increment(ref watchdogHandoffActive);
        try
        {
            await ObserveFinalizeBoundedAsync("parent-watchdog", cancellationToken).ConfigureAwait(false);
        }
        finally
        {
            Interlocked.Decrement(ref watchdogHandoffActive);
        }
    }

    /**
     * FAN-931 P1.3：父实例**一次绑定**。身份（启动时间 / 映像路径）在此比对一次，用于 PID 复用
     * 防护；绑定成功后不再周期性重开句柄或重读 MainModule。
     * 返回 (已绑定进程, 原因)；调用方负责释放返回的进程对象。
     */
    private (Process? Process, string Reason) TryBindParentProcess()
    {
        Process? process = null;
        var bound = false;
        try
        {
            // FAN-931 P0：父身份**读取次数**（改前=每 2 s 一次；改后=每次绑定一次）。
            Interlocked.Increment(ref FanPerfCounters.ParentIdentityReads);
            process = options.ParentPid is int pid
                ? Process.GetProcessById(pid)
                : GetUniqueNamedProcess(options.ParentProcessName);
            if (process is null) return (null, "parent-not-uniquely-resolvable");
            if (process.HasExited) return (null, "parent-already-exited");
            // If neither identity signal was readable at startup, continuing
            // would be a false-positive parent match. Recover conservatively.
            if (parentStartTimeUtc is null && string.IsNullOrWhiteSpace(parentExecutablePath))
                return (null, "parent-identity-unreadable-at-startup");
            if (parentStartTimeUtc is not null)
            {
                DateTime actualStart;
                try { actualStart = process.StartTime.ToUniversalTime(); }
                catch { return (null, "parent-start-time-unreadable"); }
                if (actualStart != parentStartTimeUtc.Value) return (null, "parent-start-time-mismatch");
            }
            if (!string.IsNullOrWhiteSpace(parentExecutablePath))
            {
                string? actualPath;
                try { actualPath = process.MainModule?.FileName; }
                catch { return (null, "parent-image-unreadable"); }
                if (!string.Equals(actualPath, parentExecutablePath, StringComparison.OrdinalIgnoreCase))
                    return (null, "parent-image-mismatch");
            }
            bound = true;
            return (process, "bound");
        }
        catch (ArgumentException) { return (null, "parent-not-found"); }
        catch (InvalidOperationException) { return (null, "parent-handle-invalid"); }
        catch (System.ComponentModel.Win32Exception) { return (null, "parent-handle-open-denied"); }
        catch (NotSupportedException) { return (null, "parent-handle-unsupported"); }
        finally
        {
            // 未绑定成功时立即释放句柄；成功时分支持有它（调用方负责释放）。
            if (!bound) process?.Dispose();
        }
    }

    /**
     * FAN-931 P1.3 降级路径：仅在 WaitForExitAsync 不可用时使用，且**只读已绑定句柄**的
     * HasExited（不重开句柄、不重读映像、不按名字全机搜索）。返回是否观察到退出。
     */
    private static async Task<bool> PollBoundParentUntilExitAsync(Process bound, CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try { if (bound.HasExited) return true; }
            catch { return true; }
            try { await Task.Delay(2000, cancellationToken).ConfigureAwait(false); }
            catch (OperationCanceledException) { return false; }
        }
        return false;
    }

    private static Process? GetUniqueNamedProcess(string? name)
    {
        if (string.IsNullOrWhiteSpace(name)) return null;
        var normalized = Path.GetFileNameWithoutExtension(name);
        var matches = Process.GetProcessesByName(normalized);
        var alive = matches.Where(p => { try { return !p.HasExited; } catch { return false; } }).ToArray();
        foreach (var process in matches.Where(p => !alive.Contains(p))) process.Dispose();
        if (alive.Length != 1)
        {
            foreach (var process in alive) process.Dispose();
            return null;
        }
        return alive[0];
    }

    private object CloseFromApi()
    {
        // Treat an API close as the same notification boundary as a process
        // close: late power callbacks must not enqueue a second Open/Close
        // while the single HC Close owner is running. If HC reports a failed
        // boundary, reopen only the ingress so the resident retry path can
        // observe a later real power edge.
        powerIngress.BeginClose();
        try
        {
            var state = engine.Close();
            powerIngress.CompleteClose();
            return new { ok = true, state };
        }
        catch
        {
            powerIngress.ReopenAfterFailedClose();
            throw;
        }
    }

    /**
     * FAN-204 Q1-b（2026-09-23 裁决）：/api/open 的**非阻塞准入**——取锁前先读已发布快照，
     * 过渡期（Resuming / 电源操作执行中）立即 409 POWER_RESUMING，**不排队等 gate**（真机
     * HC 打开就绪等待 10.22 s 期间，旧实现会在这里排队 10 s）。非过渡期才进入阻塞式 Open()
     * 建立会话（其 gate 内语义与既往一致）。
     */
    private object OpenFromApi()
    {
        // FAN-204 §31 R4（阶段 2）：与其它用户控制端点统一为**同一判据**（含错误优先级与结构化
        // 附加字段）。原 Q1-b 内联判定（State=="Resuming" || PowerOperationStatus in pending/executing）
        // 语义被完全覆盖、不放宽：判据仍只读 published snapshot，且不取 gate。
        engine.RejectUserControlDuringTransitionLockFree("open");
        return new { ok = true, state = engine.Open() };
    }

    private async Task<object> ExecutePowerTransitionFromApiAsync(
        string name,
        PowerIngressTarget target,
        PowerEventMetadata metadata,
        Func<object> action,
        Action? acceptedCallback = null)
    {
        var completion = new TaskCompletionSource<object?>(TaskCreationOptions.RunContinuationsAsynchronously);
        var result = QueuePowerTransition(name, target, metadata, action, completion, acceptedCallback);
        if (result == PowerPublishResult.Suppressed)
            return new { ok = true, deduplicated = true, state = engine.SnapshotForRead() };
        if (result == PowerPublishResult.Closed)
            throw new FanApiException(409, "POWER_CLOSE_PENDING", "Fan Host 正在关闭，已拒绝新的电源边沿");
        if (result == PowerPublishResult.Stale)
            throw new FanApiException(409, "POWER_EVENT_STALE", "已拒绝过时的跨代电源事件");
        if (result == PowerPublishResult.Rejected)
            throw new FanApiException(503, "POWER_QUEUE_REJECTED", "电源事件队列暂不可用，已保留当前边沿等待重试");
        var state = await completion.Task.ConfigureAwait(false);
        return new { ok = true, state };
    }

    private Task<object> SuspendFromApiAsync(JsonElement body)
    {
        RequireTaggedPowerCommand(body, "/api/suspend");
        RequireNativeSuspendAuthority(body);
        var metadata = MetadataFromPowerBody(PowerIngressTarget.Suspended, body, "api.suspend");
        // 第十五轮返修（统一准入协议）：删除"入队前宣布 + 异常回滚"——保护只在
        // 准入成功（Queued）后由共享准入操作发布（AnnounceSuspendPending 作为
        // "已接纳"回调）；Stale/Suppressed/Closed/Rejected 不产生任何版本、
        // 保护或写门副作用（写门亦仅随准入落位，失败精确回滚）。
        return ExecutePowerTransitionFromApiAsync(
            "suspend",
            PowerIngressTarget.Suspended,
            metadata,
            SuspendOnPowerWorker,
            acceptedCallback: engine.AnnounceSuspendPending);
    }

    private Task<object> ResumeFromApiAsync(JsonElement body)
    {
        RequireTaggedPowerCommand(body, "/api/resume");
        var metadata = MetadataFromPowerBody(PowerIngressTarget.Ready, body, "api.resume");
        // 第十三/二十二轮返修：在 API 接受点快照睡眠待办**授权**（值 + 归属代次，
        // 一次读取同一不可变记录）——随队列传递到实际执行；排队中的旧恢复因此无权
        // 消费"后来宣布"的新睡眠待办（授权已推进），也不得清其保护。
        var accepted = engine.SuspendProtectionAuthorizationSnapshot;
        return ResumeFromApiAndObserveAsync(metadata, accepted.Value, accepted.Stamp);
    }

    /**
     * Q1（FAN-204 s31 补充裁决 2026-09-23）：**接受与后台重建分离**。
     * 旧实现把 HTTP 请求挂在重建完成上（最多 15 s）——真机 HC 重建 ≈10.2 s 期间调用方
     * 只能拿到传输超时/500，无法区分"宿主忙"与"宿主不在"。新契约：
     * ① 接受动作只做准入并启动唯一 lifecycle owner 的后台重建，**快速**返回结构化状态
     *    （resumeAccepted / resumePhase / generation / retryAfterMs + 当前状态快照）；
     *    该响应只表示"已接纳"，**不**表示风扇已 Ready；
     * ② 调用方按同一 generation 有界读取状态（最多 15 s），只有 `Ready` 且
     *    `unknownState=false`、`hcCloseCleanupPending=false` 才算恢复完成；
     * ③ `Resuming`/`Suspended`/可解释的 409/202 都是"处理中"，不得显示成恢复完成，
     *    也不得显示成永久不可控（没有永久 409，也不并发第二个 Resume/Close/Restore）；
     * ④ no-op 与 superseded 保持原有显式终态（不伪装成功）；去重（Suppressed）只回报
     *    当前阶段现场——不等待、不借用任何进行中操作的收据。
     */
    private async Task<object> ResumeFromApiAndObserveAsync(PowerEventMetadata metadata, long acceptedPendingEpoch = 0, long acceptedPendingStamp = -1)
    {
        // 第二十一轮返修（P1，等待者隔离）：动作在队列 worker 上执行并写回本次调用的
        // 接受裁决（attempt/deferred/superseded/noop）。Q1 之后**只有接受**留在 HTTP
        // 路径上；重建由既有单飞 worker 在后台完成。
        var admission = ResumeAdmission.Unknown;
        await ExecutePowerTransitionFromApiAsync(
            "resume", PowerIngressTarget.Ready, metadata,
            () =>
            {
                admission = engine.ResumeForSystemPowerWithAdmission(
                    metadata.Generation, acceptedPendingEpoch, acceptedPendingStamp);
                return admission.Snapshot!;
            })
            .ConfigureAwait(false);
        // FAN-204 Q1-b：接受响应只读**已发布快照**（不排队等 gate）——真机 10.22 s 门内
        // 等待期间，旧实现会在这里把"快接受"变成 ~10 s 的慢接受（20:26 包 ⑤ 项）。
        var snapshot = engine.SnapshotForRead();
        switch (admission.Kind)
        {
            case "attempt":
            case "deferred":
                // 已接纳：重建（若有）在后台继续。gateway 只报告"已接纳 + 当前阶段"。
                return ShapeResumeAccepted(metadata.Generation, admission, snapshot);
            case "noop":
                // 未进入接受边界 = 未发生转换：立即返回**当前状态**（不等待、不借用
                // 任何进行中的操作）——这是"无事发生"的现场答案，不是历史收据。
                // 但故障锁定/未知态必须显式失败：不得把故障当成"无事发生"。
                if (snapshot.UnknownState || snapshot.State == "FaultLocked")
                    throw new FanApiException(409, "HC_RESUME_REBUILD_FAILED", "HC 风扇恢复未完成");
                return ShapeResumeResponse(true, snapshot.State == "Stopped" ? "host-stopped" : "not-suspended", snapshot);
            case "superseded":
                // 本请求的接受点绑定已被新睡眠取代：本次调用没有产生任何 attempt——
                // 立即以显式终态返回（不得转而等待后续新恢复的 completed）。
                throw FanHostEngine.ResumeSupersededError();
            default:
                // 未执行（去重 Suppressed / 关闭期跳过）：
                // - **同代次收据存在**：只回报当前阶段现场（Q1：调用方按状态自证成败），
                //   去重不被误报成新接受；
                // - **无同代次收据**（幻影/空转唤醒：代次比已观察的更新但没有对应入睡边沿）：
                //   保持原 fail-closed 语义 ⇒ 显式 `HC_RESUME_RESULT_EXPIRED`，绝不猜、绝不
                //   把"不可证明"软报成"现场正常"（沙箱 B4/B6 形态即此判据）。
                // FAN-204 Q1-b：先做零等待读（持锁期已含收据时立即答复）；**仅当收据缺失**才做
                // 有界等待——收据可能正在队列 worker 的动作里落位，纯非阻塞会在那个毫秒
                // 窗口里误报 expired（见 SnapshotForReadBounded 注释）。
                var current = engine.SnapshotForRead();
                if (current.PowerOperationAttempt <= 0 || current.PowerOperationGeneration != metadata.Generation)
                    current = engine.SnapshotForReadBounded(ResumeReceiptReadBudgetMs);
                if (current.PowerOperationAttempt > 0 && current.PowerOperationGeneration == metadata.Generation)
                    return ShapeResumeObserved(metadata.Generation, current);
                throw FanHostEngine.ResumeResultExpiredError();
        }
    }

    /**
     * 裁决 H4（2026-09-19）：/api/resume 响应成形的**唯一实现**。
     * - no-op：仍 ok:true（HTTP 200），额外携带 resumeNoop=true + reason（native 据此
     *   区分"真恢复/空转"，修 N18）；
     * - 真恢复/接续：只返回既有 ok + state，字段完全兼容（不新增、不改名）。
     */
    internal static object ShapeResumeResponse(bool resumeNoop, string? reason, object state) =>
        resumeNoop ? new { ok = true, resumeNoop, reason, state } : new { ok = true, state };

    /**
     * Q1（2026-09-23 补充裁决）：**已接纳**的快速应答成形（唯一实现）。字段语义：
     * - `resumeAccepted=true`：本代次的恢复边沿已被唯一 lifecycle owner 接纳；
     * - `resumePhase`：接纳瞬间的阶段真值（Resuming=重建在后台进行；同步完成的空恢复为
     *   `AwaitingControl`；被接受但已处于其他诚实状态时按名透传）；
     * - `generation`：本次接受绑定的电源代次（调用方按同一代次有界观察）；
     * - `retryAfterMs`：过渡期建议轮询间隔（Host 只建议，不强制）；
     * - `attempt`：本次接受产生的 attempt 身份（deferred=观察到的既有身份）；
     * - `state`：接纳瞬间的完整快照（既有字段完全兼容）。
     * 该响应**不**表示恢复完成：只有后续读取到 Ready 且无 unknownState/
     * hcCloseCleanupPending 才算恢复完成（native 侧 15 s 有界观察）。
     */
    internal static object ShapeResumeAccepted(long generation, ResumeAdmission admission, object state)
    {
        var snapshot = state as HostState;
        return new
        {
            ok = true,
            resumeAccepted = true,
            resumePhase = snapshot?.ResumePhase ?? "Resuming",
            generation,
            attempt = admission.AttemptId > 0 ? admission.AttemptId : admission.ObservedAttempt,
            retryAfterMs = snapshot?.ResumeRetryAfterMs ?? HostState.ResumePollRetryAfterMs,
            continuable = admission.Kind == "deferred",
            state,
        };
    }

    /**
     * Q1（2026-09-23 补充裁决）：**未产生新接受**（同代次去重/关闭期跳过）的现场应答。
     * 只回报当前阶段真值，不等待、不借用任何进行中操作的收据；调用方据阶段自证成败。
     */
    internal static object ShapeResumeObserved(long generation, object state)
    {
        var snapshot = state as HostState;
        return new
        {
            ok = true,
            resumeAccepted = false,
            deduplicated = true,
            resumePhase = snapshot?.ResumePhase ?? "Resuming",
            generation,
            retryAfterMs = snapshot?.ResumeRetryAfterMs ?? HostState.ResumePollRetryAfterMs,
            state,
        };
    }

    private static void RequireTaggedPowerCommand(JsonElement body, string endpoint)
    {
        if (body.ValueKind != JsonValueKind.Object ||
            !body.TryGetProperty("generation", out var generation) ||
            generation.ValueKind != JsonValueKind.Number ||
            !generation.TryGetInt64(out var value) || value <= 0 ||
            !body.TryGetProperty("source", out var source) ||
            source.ValueKind != JsonValueKind.String ||
            string.IsNullOrWhiteSpace(source.GetString()))
            throw new FanApiException(400, "POWER_GENERATION_REQUIRED",
                $"{endpoint} 必须携带有效 generation/source");
    }

    // F4 is native-owned. This makes stale renderer code fail before it can
    // enqueue a second CurrentDevice.Close transaction. selftest.native keeps
    // the in-process lifecycle oracle exercisable without opening a second
    // production authority.
    private static void RequireNativeSuspendAuthority(JsonElement body)
    {
        var source = body.GetProperty("source").GetString()?.Trim();
        if (!string.Equals(source, "native.power", StringComparison.Ordinal) &&
            !string.Equals(source, "selftest.native", StringComparison.Ordinal))
            throw new FanApiException(403, "F4_NATIVE_AUTHORITY_REQUIRED",
                "/api/suspend 仅接受 native.power 生命周期 authority");
    }

    private object BeginParentExitFromApi()
    {
        // Parent-exit is terminal for this Host generation. Keep the power
        // ingress closed while the resident recovery worker owns the HC Close
        // boundary; it must never be paired with a late Resume/Open.
        powerIngress.BeginClose();
        try { return engine.BeginParentExitHandoff(); }
        catch
        {
            powerIngress.ReopenAfterFailedClose();
            throw;
        }
    }

    private async Task HandleAsync(HttpListenerContext context)
    {
        var shutdownRequested = false;
        var pathForLog = context.Request.Url?.AbsolutePath.TrimEnd('/') ?? string.Empty;
        var methodForLog = context.Request.HttpMethod.ToUpperInvariant();
        var requestId = Guid.NewGuid().ToString("N");
        var requestStarted = Stopwatch.GetTimestamp();
        double RequestDurationMs() => Stopwatch.GetElapsedTime(requestStarted).TotalMilliseconds;
        context.Response.Headers["X-YeMan-Fan-Request-Id"] = requestId;
        try
        {
            if (!IsAuthorizedRequest(context.Request, out var rejectionCategory))
            {
                // §5.1：401 只表示"这次请求的凭据未获接受"。记录同类请求的**可核对**字段
                // （实例 / 凭据非秘密版本标识 / 类别），但**不**记录凭据值，也**不**据此宣布
                // 对方是"旧代"；下游不得以单个 401 作为强杀或许可绕过认证的依据。
                // 限频：同一 path+类别 30 s 内只写一条（并累计被抑制次数），避免异常客户端刷账本。
                diagnostics.Write("api.request-unauthorized", new { requestId, method = methodForLog, path = pathForLog, durationMs = RequestDurationMs(), httpStatus = 401, rejectionCategory, hostInstanceId = diagnostics.HostInstanceId });
                if (ShouldRecordAuthRejection(pathForLog, rejectionCategory, out var suppressedAuthRejections))
                {
                    diagnostics.Write("auth.rejected", new
                    {
                        requestId,
                        method = methodForLog,
                        path = pathForLog,
                        rejectionCategory,
                        hostInstanceId = diagnostics.HostInstanceId,
                        credentialVersionId = HostDiagnosticLog.CredentialVersionId(options.SessionToken),
                        credentialSource = string.IsNullOrWhiteSpace(options.SessionTokenPath) ? "argument" : "file",
                        suppliedLength = context.Request.Headers["X-YeMan-Fan-Session"]?.Length ?? 0,
                        suppressedSinceLast = suppressedAuthRejections,
                        throttleMs = AuthRejectionThrottleMs,
                        scope = "this-request-not-accepted; no bypass, no rotation, no second owner",
                    });
                }
                await WriteJsonAsync(context.Response, 401, new { ok = false, error = new { code = "API_SESSION_REQUIRED", message = "需要 Fan Host 会话令牌" } });
                return;
            }
            context.Response.Headers["Cache-Control"] = "no-store";
            context.Response.Headers["X-YeMan-Fan-Host"] = "2";
            var path = pathForLog;
            var method = methodForLog;
            // FAN-931 P0：请求入口计数（定长、无分配热点；调用者归类只是 UA 启发式诊断）。
            FanPerfCounters.RecordRequest(path, context.Request.UserAgent);
            object result;

            if (method == "GET" && path == "/health") result = new { ok = true, host = "YeManFanHost", protocolVersion = 2, sessionRequired = true, parentPid = options.ParentPid, parentProcess = options.ParentProcessName, state = engine.SnapshotForRead() };
            else if (method == "GET" && path == "/api/state") result = new { ok = true, state = engine.SnapshotForRead() };
            // FAN-931 P0：只读计数导出（认证入口已在上方判定；不含 token/lease 秘密）。
            // 带上非秘密的实例/进程身份与样本起点，使采集端能把"这份计数"绑到同一实例同一采集窗。
            else if (method == "GET" && path == "/api/perf-counters") result = new
            {
                ok = true,
                hostInstanceId = diagnostics.HostInstanceId,
                processId = Environment.ProcessId,
                processorCount = Environment.ProcessorCount,
                sampleTimestampUnixMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                counters = FanPerfCounters.Snapshot(),
            };
            else if (method == "POST" && path == "/api/handshake") result = engine.Handshake();
            else if (method == "POST" && path == "/api/suspend")
            {
                var body = await ReadJsonAsync(context.Request);
                result = await SuspendFromApiAsync(body).ConfigureAwait(false);
            }
            else if (method == "POST" && path == "/api/resume")
            {
                var body = await ReadJsonAsync(context.Request);
                result = await ResumeFromApiAsync(body).ConfigureAwait(false);
            }
            else
            {
                var body = await ReadJsonAsync(context.Request);
                result = (method, path) switch
                {
                    ("POST", "/api/open") => OpenFromApi(),
                    ("POST", "/api/open-events") => new { ok = true, state = engine.OpenEvents() },
                    ("POST", "/api/acquire-control") => new { ok = true, lease = engine.AcquireControl() },
                    ("POST", "/api/heartbeat") => new { ok = true, lease = engine.Heartbeat(RequiredString(body, "leaseId")) },
                    ("POST", "/api/enable") => new { ok = true, state = engine.Enable(body) },
                    ("POST", "/api/preset") => new { ok = true, state = engine.Preset(body) },
                    ("POST", "/api/disable") => new { ok = true, state = engine.Disable(body) },
                    ("POST", "/api/restore") => new { ok = true, state = engine.Restore(body) },
                    ("POST", "/api/release-control") => new { ok = true, state = engine.Release(body) },
                    ("POST", "/api/close") => CloseFromApi(),
                    ("POST", "/api/parent-exit") => BeginParentExitFromApi(),
                    ("POST", "/api/shutdown") => ShutdownResult(ref shutdownRequested),
                    _ => throw new FanApiException(404, "NOT_FOUND", "Fan API 路由不存在"),
                };
            }
            await WriteJsonAsync(context.Response, 200, result);
            // FAN-204 Q1-b：① 读路径不等待 gate（用已发布快照）；② 响应耗时在**响应写完处**
            // 取值——不再把诊断行的快照等待算进 durationMs（真机那条 10.24 s 伪影即此因）。
            var responseMs = RequestDurationMs();
            // Parent exit acknowledgement is intentionally lock-free. Do not
            // reacquire the engine lock merely to enrich its diagnostic record
            // or the native UI could wait behind the same wedged HC call that
            // it is trying to hand off to this resident Host.
            var responseState = path == "/api/parent-exit" ? "ParentExitRecovery" : engine.SnapshotForRead().State;
            diagnostics.Write("api.request-success", new { requestId, method, path, state = responseState, durationMs = responseMs, httpStatus = 200 });
            if (shutdownRequested)
            {
                _ = Task.Run(async () =>
                {
                    await Task.Delay(25);
                    Stop();
                });
            }
        }
        catch (FanApiException ex)
        {
            // FAN-204 Q1-b：读路径与耗时口径同上（失败行也不得再等 gate / 不得把快照等待算进 durationMs）。
            var failureMs = RequestDurationMs();
            var failureState = engine.SnapshotForRead();
            diagnostics.Write("api.request-failure", new { requestId, method = methodForLog, path = pathForLog, code = ex.Code, error = ex.Message, state = failureState.State, lastError = failureState.LastError, durationMs = failureMs, httpStatus = ex.StatusCode });
            // Q1-c：结构化拒绝的附加字段只在显式提供时出现（其余失败响应体形状不变）。
            var errorBody = ex.Details is null
                ? (object)new { code = ex.Code, message = ex.Message }
                : new { code = ex.Code, message = ex.Message, details = ex.Details };
            await WriteJsonAsync(context.Response, ex.StatusCode, new { ok = false, error = errorBody, state = failureState });
        }
        catch (JsonException ex)
        {
            diagnostics.Write("api.request-invalid-json", new { requestId, method = methodForLog, path = pathForLog, error = ex.Message, durationMs = RequestDurationMs(), httpStatus = 400 });
            await WriteJsonAsync(context.Response, 400, new { ok = false, error = new { code = "INVALID_JSON", message = ex.Message } });
        }
        catch (Exception ex)
        {
            // FAN-204 Q1-b：500 行同样用**非阻塞读**（否则持锁期写失败时还会再等一次 gate）。
            var hostErrorMs = RequestDurationMs();
            var hostErrorState = engine.SnapshotForRead();
            diagnostics.Write("api.request-host-error", new { requestId, method = methodForLog, path = pathForLog, error = ExceptionText(ex), state = hostErrorState.State, lastError = hostErrorState.LastError, durationMs = hostErrorMs, httpStatus = 500 });
            await WriteJsonAsync(context.Response, 500, new { ok = false, error = new { code = "HOST_ERROR", message = ex.Message }, state = hostErrorState });
        }
        finally { context.Response.Close(); }
    }

    private static string ExceptionText(Exception ex) => string.Join(" -> ", Unwrap(ex).Select(e => e.GetType().Name + ": " + e.Message));
    private static IEnumerable<Exception> Unwrap(Exception ex)
    {
        for (Exception? current = ex; current is not null; current = current.InnerException) yield return current;
    }

    /**
     * §5.1（FAN-925B）：认证判定 + **拒绝分类**。分类只描述"这次为什么没被接受"，
     * 不含任何凭据材料，也**不**宣称对方属于"旧代"（那需要独立证据）。
     */
    private bool IsAuthorizedRequest(HttpListenerRequest request, out string rejectionCategory)
    {
        rejectionCategory = "accepted";
        var token = options.SessionToken;
        if (string.IsNullOrWhiteSpace(token))
        {
            rejectionCategory = "host-credential-missing";
            return false;
        }
        var supplied = request.Headers["X-YeMan-Fan-Session"];
        if (string.IsNullOrWhiteSpace(supplied))
        {
            rejectionCategory = "request-credential-missing";
            return false;
        }
        if (!CryptographicOperations.FixedTimeEquals(
                Encoding.UTF8.GetBytes(supplied), Encoding.UTF8.GetBytes(token)))
        {
            rejectionCategory = supplied.Length != token.Length
                ? "credential-length-mismatch"
                : "credential-value-mismatch";
            return false;
        }
        return true;
    }

    /**
     * §5.1（FAN-925B）：`auth.rejected` 是**常开**事件，必须限频 —— 同一 path+类别
     * 至多每 {@link AuthRejectionThrottleMs} 写一条，并累计被抑制条数。返回 true 表示本次写。
     */
    internal const long AuthRejectionThrottleMs = 30_000;
    private readonly Dictionary<string, (long TickMs, long Suppressed)> authRejectionThrottle = new(StringComparer.Ordinal);

    private bool ShouldRecordAuthRejection(string path, string category, out long suppressedSinceLast)
    {
        suppressedSinceLast = 0;
        var key = path + "|" + category;
        var now = Environment.TickCount64;
        lock (authRejectionThrottle)
        {
            if (authRejectionThrottle.TryGetValue(key, out var last))
            {
                if (now - last.TickMs < AuthRejectionThrottleMs)
                {
                    authRejectionThrottle[key] = (last.TickMs, last.Suppressed + 1);
                    return false;
                }
                suppressedSinceLast = last.Suppressed;
                authRejectionThrottle[key] = (now, 0);
                return true;
            }
            authRejectionThrottle[key] = (now, 0);
            return true;
        }
    }

    private static object ShutdownResult(ref bool requested)
    {
        requested = true;
        return new { ok = true, shutdownRequested = true };
    }

    private static async Task<JsonElement> ReadJsonAsync(HttpListenerRequest request)
    {
        if (request.ContentLength64 > 1024 * 1024) throw new FanApiException(413, "BODY_TOO_LARGE", "请求体过大");
        if (request.HttpMethod == "GET" || request.ContentLength64 == 0) return JsonDocument.Parse("{}").RootElement.Clone();
        using var reader = new StreamReader(request.InputStream, Encoding.UTF8, leaveOpen: false);
        var raw = await reader.ReadToEndAsync();
        return JsonDocument.Parse(string.IsNullOrWhiteSpace(raw) ? "{}" : raw).RootElement.Clone();
    }

    private static string RequiredString(JsonElement body, string property)
    {
        if (!body.TryGetProperty(property, out var value) || value.ValueKind != JsonValueKind.String || string.IsNullOrWhiteSpace(value.GetString()))
            throw new FanApiException(400, "INVALID_REQUEST", $"缺少 {property}");
        return value.GetString()!;
    }

    private static async Task WriteJsonAsync(HttpListenerResponse response, int statusCode, object value)
    {
        var bytes = JsonSerializer.SerializeToUtf8Bytes(value, JsonDefaults.Options);
        response.StatusCode = statusCode;
        response.ContentType = "application/json; charset=utf-8";
        response.ContentLength64 = bytes.Length;
        await response.OutputStream.WriteAsync(bytes);
    }

    public void Dispose()
    {
        Stop();
        if (!stopCts.IsCancellationRequested) return;
        FinalizeWatchdogBeforeDispose();
        listener.Close();
        powerTransitions.Writer.TryComplete();
        stopCts.Dispose();
        watchdogFaultObserver = null;
    }

    private void FinalizeWatchdogBeforeDispose()
    {
        var task = watchdog;
        if (task is null) return;
        // 2026-09-30 FAN-934 R2-B5：收尾进行中（watchdogHandoffActive != 0）说明本 Dispose
        // 是在父退出收尾链路里被重入调用的——stopCts.Cancel() 同步内联推进了 RunAsync 续体，
        // 一路走到 Main 返回触发本 Dispose。此时 task 正是当前执行路径本身，task.Wait 即自等；
        // Task.CurrentId 对 async 续体不可靠（旧判别漏判，留下 5 s 自等与误导性的 pending 记录）。
        // 如实记为"自身在收尾路径上，故释放延后到进程退出由外部 watchdog 证明"。
        if (Volatile.Read(ref watchdogHandoffActive) != 0 ||
            (Task.CurrentId is int currentId && task.Id == currentId))
        {
            diagnostics.Write("parent-watchdog.dispose-deferred-self", new
            {
                inHandoff = Volatile.Read(ref watchdogHandoffActive) != 0,
                processExitEvidence = "external-watchdog-pid+start-time",
            });
            return;
        }

        try
        {
            if (!task.Wait(TimeSpan.FromSeconds(5)))
            {
                diagnostics.Write("parent-watchdog.dispose-deferred-pending", new
                {
                    status = task.Status.ToString(),
                    waitMilliseconds = 5000,
                });
                return;
            }
            if (task.IsFaulted)
            {
                var error = task.Exception?.GetBaseException();
                diagnostics.Write("parent-watchdog.fault-observed", new
                {
                    error = error is null ? "unknown" : ExceptionText(error),
                });
                _ = task.Exception;
            }
            else if (task.IsCanceled)
            {
                diagnostics.Write("parent-watchdog.canceled-observed", new { });
            }
        }
        catch (Exception ex)
        {
            // Never allow Task.Wait/GetResult to escape from Dispose. The
            // task remains referenced if it did not reach a terminal state.
            diagnostics.Write("parent-watchdog.finalize-failure", new { error = ExceptionText(ex) });
            return;
        }
        if (task.IsCompleted)
        {
            task.Dispose();
            watchdog = null;
        }
    }
}

internal sealed class FanApiException : Exception
{
    public int StatusCode { get; }
    public string Code { get; }
    /**
     * FAN-204 Q1-c（2026-09-24 裁决）：结构化拒绝的**附加可判定字段**（如 heartbeat 快速拒绝的
     * generation/resumePhase/retryAfterMs/controlAccepting/leaseRenewed）。默认 null ⇒ 既有失败
     * 响应体形状**完全不变**（不新增 `details` 键），只有显式带字段的路径才多出该键。
     */
    public object? Details { get; set; }
    public FanApiException(int statusCode, string code, string message) : base(message) { StatusCode = statusCode; Code = code; }
}

internal static class BoundedRecoveryRetrySelfTest
{
    private const int IntervalMs = 2_000;
    private const int MaxAttempts = 30;
    private const long WindowMs = 60_000;

    // Deterministic model of the resident Host timer.  It advances virtual
    // time instead of sleeping or touching HC, so the safety cap is tested in
    // every build without a real device or a background retry timer.
    private sealed class Model
    {
        private long? windowStarted;
        private bool timerOutstanding;
        private bool terminal;
        internal int Attempts { get; private set; }
        internal int LastDelayMs { get; private set; }
        internal bool Terminal => terminal;

        internal bool Schedule(long nowMs)
        {
            if (timerOutstanding || terminal) return false;
            windowStarted ??= nowMs;
            if (Attempts >= MaxAttempts || nowMs - windowStarted.Value >= WindowMs)
            {
                terminal = true;
                return false;
            }
            Attempts++;
            LastDelayMs = IntervalMs;
            timerOutstanding = true;
            return true;
        }

        internal void CompleteFailedAttempt() => timerOutstanding = false;

        internal void BeginExplicitRetry()
        {
            if (!timerOutstanding)
            {
                windowStarted = null;
                Attempts = 0;
                terminal = false;
            }
        }
    }

    internal static IReadOnlyList<string> RunSelfTest()
    {
        var checks = new List<string>();
        var model = new Model();
        for (var attempt = 0; attempt < MaxAttempts; attempt++)
        {
            var nowMs = (long)attempt * IntervalMs;
            if (!model.Schedule(nowMs) || model.LastDelayMs != IntervalMs)
                throw new InvalidOperationException($"bounded recovery schedule failed at attempt {attempt + 1}");
            model.CompleteFailedAttempt();
        }
        checks.Add("t2-recovery-2s-interval-30-attempts");

        if (model.Schedule(MaxAttempts * (long)IntervalMs))
            throw new InvalidOperationException("bounded recovery scheduled after the 60-second/30-attempt cap");
        if (!model.Terminal || model.Attempts != MaxAttempts)
            throw new InvalidOperationException("bounded recovery did not enter terminal FaultLocked model state");
        checks.Add("t2-recovery-window-terminal-after-60s");

        // A terminal automatic window cannot re-arm itself.  Only a separate,
        // explicit caller event is allowed to begin a fresh bounded window.
        if (model.Schedule(MaxAttempts * (long)IntervalMs + IntervalMs))
            throw new InvalidOperationException("terminal recovery window re-scheduled automatically");
        model.BeginExplicitRetry();
        if (!model.Schedule(0) || model.Attempts != 1)
            throw new InvalidOperationException("explicit recovery retry did not start a new bounded window");
        checks.Add("t2-recovery-single-owner-explicit-retry");

        // ── FAN-925 T0-X（合同 §2.1）：20 s 是升级处置点，不是退责许可；周期预算跨进程继承 ──
        // ① 20 s 升级必须落在同一个 60 s 周期内，不得自己去开新预算。
        if (FanHostEngine.ParentExitFinalizeBudgetMs >= WindowMs)
            throw new InvalidOperationException(
                "fan925: the 20s abnormal finalize escalation must stay inside the 60s fault-cycle budget");
        checks.Add("t2-fan925-escalation-20s-inside-cycle-60s");

        // ② 剩余预算 = 真实函数（非另写模型）：新鲜周期 ≈ 满窗；已过 20 s ≈ 剩 40 s。
        var now = DateTime.UtcNow;
        var fresh = FanHostEngine.RemainingRecoveryCycleMsForSelfTest(now, 0, false, false);
        if (fresh > WindowMs || fresh < WindowMs - 2_000)
            throw new InvalidOperationException($"fan925: a fresh cycle must expose the full window, got {fresh}ms");
        var after20s = FanHostEngine.RemainingRecoveryCycleMsForSelfTest(now.AddMilliseconds(-20_000), 10, false, false);
        if (after20s < 38_000 || after20s > 40_000)
            throw new InvalidOperationException(
                $"fan925: a replacement Host must inherit the remaining budget (~40000ms), got {after20s}ms");
        checks.Add("t2-fan925-replacement-inherits-remaining-budget");

        // ③ 终态 / 已完成 / 次数用满一律不再放行自动恢复（失败终态，不是 T0 通过）。
        if (FanHostEngine.RemainingRecoveryCycleMsForSelfTest(now, 5, true, false) != 0 ||
            FanHostEngine.RemainingRecoveryCycleMsForSelfTest(now, 5, false, true) != 0 ||
            FanHostEngine.RemainingRecoveryCycleMsForSelfTest(now, MaxAttempts, false, false) != 0 ||
            FanHostEngine.RemainingRecoveryCycleMsForSelfTest(now.AddMilliseconds(-(WindowMs + 1)), 5, false, false) != 0)
            throw new InvalidOperationException(
                "fan925: terminal/completed/attempt-exhausted/expired cycle must not permit further automatic recovery");
        checks.Add("t2-fan925-terminal-and-caps-refuse-auto-recovery");

        // ④ 接管判定（真实纯函数）：同一周期第二次自动接管必须被拒；显式重试是唯一豁免。
        // §4.2（FAN-926 P2）：同一未结算 episode **到期**后不得被当成"无历史"刷新 60 s。
        if (FanHostEngine.DecideRecoveryCycleAdoption(false, true, true, false, after20s, 0) !=
                FanHostEngine.RecoveryCycleAdoption.Inherit ||
            FanHostEngine.DecideRecoveryCycleAdoption(false, true, true, false, after20s, 1) !=
                FanHostEngine.RecoveryCycleAdoption.RefuseReplacementCap ||
            FanHostEngine.DecideRecoveryCycleAdoption(true, true, true, false, after20s, 1) !=
                FanHostEngine.RecoveryCycleAdoption.StartNew ||
            FanHostEngine.DecideRecoveryCycleAdoption(false, true, false, false, after20s, 0) !=
                FanHostEngine.RecoveryCycleAdoption.StartNew ||
            FanHostEngine.DecideRecoveryCycleAdoption(false, true, true, true, after20s, 0) !=
                FanHostEngine.RecoveryCycleAdoption.StartNew ||
            // 同一 episode、未结算、预算耗尽（到时/次数到限）⇒ 拒绝，**不是** StartNew。
            FanHostEngine.DecideRecoveryCycleAdoption(false, true, true, false, 0, 0) !=
                FanHostEngine.RecoveryCycleAdoption.RefuseExhaustedWithoutSettlement ||
            // 对照：从未发生过故障（无历史）仍然是合法的 StartNew。
            FanHostEngine.DecideRecoveryCycleAdoption(false, false, false, false, 0, 0) !=
                FanHostEngine.RecoveryCycleAdoption.StartNew)
            throw new InvalidOperationException("fan925: recovery-cycle adoption decision is wrong");
        checks.Add("t2-fan925-at-most-one-auto-replacement-per-cycle");
        checks.Add("t2-fan925-exhausted-unsettled-episode-is-refused-not-refreshed");

        // ⑤ §4.2 同一 episode 的父身份判定（真实纯函数）：**不能只比较 PID 数值**——
        // 同一映像的另一个进程实例仍是同一未结算 episode 的换实例接管。
        if (!FanHostEngine.SameEpisodeParentIdentity(5, 5, "a", "b") ||
            !FanHostEngine.SameEpisodeParentIdentity(7, 5, @"C:\x\YeManCC.exe", @"c:\X\yemancc.exe") ||
            FanHostEngine.SameEpisodeParentIdentity(7, 5, "a", "b") ||
            FanHostEngine.SameEpisodeParentIdentity(7, 5, null, null) ||
            FanHostEngine.SameEpisodeParentIdentity(0, 0, null, null) ||
            !FanHostEngine.SameEpisodeParentIdentity(0, 5, "same.exe", "same.exe"))
            throw new InvalidOperationException("fan926: same-episode parent identity rule is wrong");
        checks.Add("t2-fan926-same-episode-parent-identity-not-just-pid");
        return checks;
    }
}

/**
 * FAN-934 §4.A/§6：路线证据适用性的承重自测（纯函数 + 静态路由表，无需 HC 候选程序集）。
 * 目的：钉住"按实际机型/操作选择回执规则"这一修复——修前对 GPD/MSI 会套用
 * ASUS 收据判据 ⇒ 空收据 ⇒ unknown ⇒ FaultLocked。本组正反例必须能抓住该错误，
 * 同时保留 ROG 既有有效检查，且不得把全部空收据改成成功。
 */
internal static class FanRouteEvidenceSelfTest
{
    private static readonly string[] AsusRoutes =
    [
        "HandheldCompanion.Devices.ROGAlly", "HandheldCompanion.Devices.ROGAllyX",
        "HandheldCompanion.Devices.XboxROGAlly", "HandheldCompanion.Devices.XboxROGAllyX",
    ];

    /**
     * FAN-934 R2 §3-A.2：驱动**真实**前提判定的最小 mock 设备。`GetMember` 沿基类用
     * `DeclaredOnly` 反射 public 属性，故这里只需给出 HC 设备同名成员（UseOpenLib/IsOpen/IsSupported）。
     */
    private sealed class MockCompatDevice
    {
        public bool UseOpenLib { get; init; }
        public bool IsOpen { get; init; }
        public bool IsSupported { get; init; } = true;
        /**
         * FAN-936 §3/§5：MSI 结构化释放结论的替身（HC `ClawA1M.LastMsiFanRelease` 的反射形状）。
         * 未注入时为 null ⇒ 生产 `ReadMsiStructuredRelease` 必须 fail-closed 为 absent。
         */
        public object? LastMsiFanRelease { get; set; }
        /**
         * FAN-936 R4：Host 派发交还前写入的**本次操作令牌**（HC `ClawA1M.MsiReleaseOperationToken`
         * 的反射替身）。释放 sink 必须回显它，否则本次恢复不得被认成成功。
         */
        public string? MsiReleaseOperationToken { get; set; }
        /**
         * FAN-936 R1：HC `LastMsiFanTableWrite` / `LastMsiFanControlWrite` 的反射替身
         * （Host 消费其 `Status`）。未注入 ⇒ 生产 `EnsureMsiSoftwareControlEstablished`
         * 必须 fail-closed（不得建立软件控制成功态）。
         */
        public object? LastMsiFanTableWrite { get; set; }
        public object? LastMsiFanControlWrite { get; set; }
        /**
         * FAN-936 R2 section 2：HC 风扇专项释放例程（`ClawA1M.ReleaseMsiFanControl` 的反射替身）。
         * 生产 `RestoreOemCore` 交还走**窄接口**（`Invoke(device,"ReleaseMsiFanControl","oem-restore")`），
         * 不再经过完整 `PowerProfileManager_Applied` 回调，故 mock 必须提供该例程，并由工厂在调用时
         * 产出**回显本次操作令牌**的新收据（三态语义与旧 sink 一致）。`MsiReleaseFailure` 模拟 HC
         * 在例程内抛异常。
         */
        public Func<object?>? MsiReleaseReceiptFactory { get; set; }
        public Exception? MsiReleaseFailure { get; set; }
        public int ReleaseMsiFanControlInvocationCount { get; private set; }
        public string? LastMsiFanReleaseCause { get; private set; }
        public object? ReleaseMsiFanControl(string cause)
        {
            ReleaseMsiFanControlInvocationCount++;
            LastMsiFanReleaseCause = cause;
            if (MsiReleaseFailure is not null) throw MsiReleaseFailure;
            if (MsiReleaseReceiptFactory is not null) LastMsiFanRelease = MsiReleaseReceiptFactory();
            return LastMsiFanRelease;
        }
        /** FAN-934 R2 §3-B：记录生产 `Invoke(device,"Close")` 是否真的到达虚拟设备边界。 */
        public int CloseInvocationCount { get; private set; }
        /**
         * FAN-936 R2 section 1：HC 的 `ClawA1M.Close()` 内部会做一次**风扇交还**（`ReleaseMsiFanControl("hc-close")`）。
         * 默认按真机行为执行；置 false 可复现"Close 未做交还 / 无绑定本次操作的收据"⇒ 结算必须
         * 保持 `not-attempted`，不得把 Close 当成一次成功释放。
         */
        public bool ClosePerformsMsiHandback { get; set; } = true;
        public void Close()
        {
            CloseInvocationCount++;
            if (ClosePerformsMsiHandback) ReleaseMsiFanControl("hc-close");
        }
    }

    /**
     * FAN-934 R2 §3-A.2：一次走完**生产**判定链——`BeginAsusWriteScope`（内部调用真实
     * `EvaluateCompatCallbackPreconditions` 读 mock 设备成员）→ `SettleOperationEvidence` →
     * `ClassifyReleaseAction` → `IsOemReleaseSafe`。正反例不再手填布尔结论。
     */
    private static (string Kind, OemReleaseAction Action, bool Safe, string Detail) DrivePreconditionChain(
        RealHcBackend backend, FanRoute route, bool useOpenLib, bool deviceIsOpen,
        bool deviceIsSupported, bool backendOpen, bool callbackReturned)
    {
        var mock = new MockCompatDevice
        { UseOpenLib = useOpenLib, IsOpen = deviceIsOpen, IsSupported = deviceIsSupported };
        backend.InstallSelfTestRouteSessionForSelfTest(mock, route, backendOpen);
        var handle = backend.BeginAsusWriteScope("oem-restore");
        var verdict = backend.SettleOperationEvidence(handle, "oem-restore", callbackReturned);
        return (verdict.Kind, FanHostEngine.ClassifyReleaseAction(verdict.Kind),
            FanHostEngine.IsOemReleaseSafeForSelfTest(true, verdict.Kind), verdict.Detail);
    }

    /**
     * FAN-934 R2 §3-B：驱动**生产恢复入口**（`RestoreOem()` / `Close()`）的状态化 mock 会话。
     * mock 设备与 HC 边界都在 HC/OS 边界隔离（无候选程序集、无真实 EC/WMI）；由此得到的
     * 回调调用计数、关闭边界命中与释放证据，才是"GPD／微星实际恢复入口"的可执行证据，
     * 而不是手填的判定布尔值。
     */
    private static RealHcBackend NewRestoreEntryHarness(
        FanRoute route, bool useOpenLib, bool deviceIsOpen,
        out MockCompatDevice mock, out RealHcBackend.SelfTestHcBoundary boundary,
        object? msiStructuredRelease = null, bool msiStructuredReleaseSuppressed = false)
    {
        var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        boundary = new RealHcBackend.SelfTestHcBoundary();
        backend.InstallHcBoundaryForSelfTest(boundary);
        mock = new MockCompatDevice { UseOpenLib = useOpenLib, IsOpen = deviceIsOpen, IsSupported = true };
        // FAN-936 §3/§5 + R4：MSI 路线的释放证书只认 HC 侧结构化回读结论，且必须绑定**本次操作**。
        // 三态语义（`msiStructuredRelease` 保持 7 参位置以兼容探针调用）：
        //   · 传了 msiStructuredRelease ⇒ 冻结模式：预置一条**旧收据**且不再更新，复现"旧/陈旧/
        //     错设备收据不得冒充本次恢复结果"。
        //   · suppressed ⇒ 缺失模式：HC 没给出结构化结论（必须 fail-closed 为 unknown）。
        //   · 其余（null 且未抑制）⇒ 生产保真模式：给 mock 的窄接口释放例程装配**收据工厂**，
        //     在 `ReleaseMsiFanControl` 被真实调用时产出**回显当前操作令牌**的新收据，供
        //     `ReadMsiStructuredRelease` 绑定本次操作（R2 section 2 后 MSI 交还不再经过完整回调边界）。
        if (route.RestoreStrategy == FanRestoreStrategy.MsiHcDefaultRelease)
        {
            if (msiStructuredReleaseSuppressed)
            {
                // 缺失模式：不预置收据、不装配工厂。
            }
            else if (msiStructuredRelease is not null)
            {
                mock.LastMsiFanRelease = msiStructuredRelease;
            }
            else
            {
                // out 参数不能被 lambda 捕获：先落到局部变量再装配工厂。
                var receiptMock = mock;
                var receiptBoundary = boundary;
                receiptMock.MsiReleaseReceiptFactory = () => BuildMsiStructuredReleaseForSelfTest(
                    Status: receiptBoundary.ReleaseReceiptStatus,
                    FullSpeed152Status: receiptBoundary.ReleaseReceiptFullSpeedStatus,
                    SoftwareControl212Status: receiptBoundary.ReleaseReceiptSoftwareStatus,
                    BootIdentity: RealHcBackend.MachineBootIdentityForSelfTest,
                    OperationToken: receiptMock.MsiReleaseOperationToken);
            }
        }
        backend.InstallSelfTestRouteSessionForSelfTest(mock, route, backendOpen: true);
        return backend;
    }

    /**
     * FAN-936 §3/§5：构造 HC `MsiFanReleaseResult` 的反射形状替身（`GetMember` 按名读
     * `Status`/`FullSpeed152.Status`/`SoftwareControl212.Status`/`BootIdentity`/`HostInstanceId`/`Summary`）。
     */
    private static object BuildMsiStructuredReleaseForSelfTest(
        string Status = "ok", string FullSpeed152Status = "ok", string SoftwareControl212Status = "ok",
        string? BootIdentity = null, string? Summary = null, string? OperationToken = null) => new
    {
        ReaderVersion = "FAN-936/1",
        Cause = "selftest",
        Status,
        FullSpeed152 = new { Status = FullSpeed152Status },
        SoftwareControl212 = new { Status = SoftwareControl212Status },
        HostInstanceId = "selftest-host-instance",
        BootIdentity,
        // FAN-936 R4：释放证书必须回显 Host 派发交还时写入的本次操作令牌。
        OperationToken,
        Summary = Summary ?? $"selftest structured release status={Status}",
    };

    /**
     * FAN-936 R4：构造一条**陈旧/错设备**的 MSI 释放收据——绑定本次开机但回显一个非本次操作的令牌。
     * 预置它后驱动生产恢复入口，`ReadMsiStructuredRelease` 必须因操作令牌不匹配而 fail-closed 为
     * Unknown，从而复现"旧收据不得冒充本次恢复结果"。
     */
    private static object NewStaleMsiReleaseReceiptForSelfTest() => BuildMsiStructuredReleaseForSelfTest(
        BootIdentity: RealHcBackend.MachineBootIdentityForSelfTest,
        OperationToken: "stale-operation-token");

    /** FAN-934 R2 §3-B：捕获生产恢复入口的失败串（成功记 `<no-failure>`），原样保留异常消息。 */
    private static string CaptureRestoreFailure(RealHcBackend backend)
    {
        try { backend.RestoreOem(); return "<no-failure>"; }
        catch (Exception ex) { return ex.Message; }
    }

    /** FAN-934 R2 §3-B：捕获生产关闭入口的失败串。 */
    private static string CaptureCloseFailure(RealHcBackend backend)
    {
        try { backend.Close(); return "<no-failure>"; }
        catch (Exception ex) { return ex.Message; }
    }

    /**
     * FAN-936 §5：捕获生产授权门/绑定门的结构化拒绝——保留 `Code`/`StatusCode`，用于断言
     * fail-closed 的**类型**（而不仅是文案）。成功记 `(null, 0, "<no-failure>")`；非
     * `FanApiException` 记 `(null, -1, message)`，从而"被洗成普通异常"也会被抓到。
     */
    private static (string? Code, int Status, string Message) CaptureFanApiFailure(Action action)
    {
        try { action(); return (null, 0, "<no-failure>"); }
        catch (FanApiException ex) { return (ex.Code, ex.StatusCode, ex.Message); }
        catch (Exception ex) { return (null, -1, ex.Message); }
    }

    /**
     * FAN-934 R2 §3-B 第六条（变异发现的缺口）：ASUS 收据→判定的**生产汇总函数**
     * `CompleteAsusWriteScope` 此前只在 §19 用真实/候选 scope 驱动，§18 的"空收据"守卫却是
     * 手填 `AsusWriteVerdict` ⇒ 把空收据分支改成成功（承重变异 M4）无人能抓。这里用一个带
     * `TakeReceipts()` 的 mock scope 直接驱动生产汇总：收据枚举由测试给定，判定必须原样来自
     * 生产映射，而不是手填结论。
     */
    private sealed class MockAsusFanReceipt
    {
        public string CallKind { get; init; } = "Fan";
        public string Fan { get; init; } = "CPU";
        public string Status { get; init; } = "TransportedComplete";
        public int? Win32Error { get; init; }
    }

    private sealed class MockAsusScope
    {
        private readonly List<object> _receipts;
        public MockAsusScope(IEnumerable<object> receipts) => _receipts = [.. receipts];
        public string ScopeId => "mock-scope";
        public List<object> TakeReceipts() => [.. _receipts];
    }

    /** 生产汇总 → 生产结算 → 生产分类 → 生产安全判据（全程不手填 kind）。 */
    private static (string Kind, OemReleaseAction Action, bool Safe, string Detail) DriveAsusScopeChain(
        RealHcBackend backend, IEnumerable<object> receipts)
    {
        var handle = new RealHcBackend.AsusWriteScopeHandle
        {
            Scope = new MockAsusScope(receipts),
            Kind = "oem-restore",
            Mode = FanEvidenceMode.AsusScopeReceipts,
        };
        var verdict = backend.CompleteAsusWriteScope(handle, "oem-restore");
        var settled = RealHcBackend.DecideOperationEvidence(
            FanEvidenceMode.AsusScopeReceipts, "oem-restore", callbackReturned: true,
            compatPreconditionsOk: false, "n/a", verdict);
        // 闭环：分类器导出的动作串经消费端统一入口重解析后，仍给出一致的释放安全判据。
        var action = FanHostEngine.ClassifyReleaseAction(settled.Kind);
        return (settled.Kind, action,
            FanHostEngine.IsOemReleaseSafeForSelfTest(true, FanHostEngine.ReleaseActionKindName(action)),
            verdict.Detail);
    }

    public static IReadOnlyList<string> RunSelfTest()
    {
        var checks = new List<string>();
        var routes = RealHcBackend.FanRoutesForSelfTest;

        // ① ASUS 路线**唯一**适用 ASUS 作用域收据。负例：把 ROG 标成"不适用"（兼容回调）
        //    必须被本门抓住——那会把 ROG 的空收据误判成已释放。
        foreach (var asus in AsusRoutes)
            if (!routes.TryGetValue(asus, out var asusRoute) ||
                asusRoute.Evidence != FanEvidenceMode.AsusScopeReceipts)
                throw new InvalidOperationException(
                    $"FAN-934: ASUS route {asus} lost AsusScopeReceipts evidence (negative: ROG marked not-applicable must fail)");
        checks.Add("fan934-asus-routes-keep-scope-receipts");

        // ② 其余已登记路线一律声明已审阅的非 ASUS 兼容回调合同；声明过的路线**不得**退回
        //    fail-closed 的 UnsupportedNoScope（那会让合法操作长期停在 FaultLocked）。
        var nonAsus = routes.Where(pair => pair.Value.Evidence != FanEvidenceMode.AsusScopeReceipts).ToList();
        if (nonAsus.Count != routes.Count - AsusRoutes.Length)
            throw new InvalidOperationException(
                $"FAN-934: route evidence split is not ({AsusRoutes.Length} ASUS / rest compat): total={routes.Count} nonAsus={nonAsus.Count}");
        if (nonAsus.Any(pair => pair.Value.Evidence != FanEvidenceMode.CompatCallbackNoScope))
            throw new InvalidOperationException(
                "FAN-934: every registered non-ASUS route must declare CompatCallbackNoScope");
        checks.Add($"fan934-{nonAsus.Count}-non-asus-routes-declare-compat-callback-contract");

        // ③ 修前受害机型：GPD Win5 与 MSI Claw（A2VM，供应商命名空间与路由表不同）必须解析到
        //    兼容回调合同；未知机型必须解析为 null（fail-closed，不能靠相似前缀拿到写权）。
        foreach (var (factory, expectedStrategy) in new[]
                 {
                     ("HandheldCompanion.Devices.GPDWin5", FanRestoreStrategy.GpdWin5HcAutoRelease),
                     // 生产 FactoryType 是 MSI.ClawA2VM，路由表登记为 ClawA2VM ⇒ 走 className 后缀解析。
                     ("HandheldCompanion.Devices.MSI.ClawA2VM", FanRestoreStrategy.MsiHcDefaultRelease),
                 })
        {
            var resolved = RealHcBackend.ResolveRouteForSelfTest(factory);
            if (resolved is null ||
                resolved.Evidence != FanEvidenceMode.CompatCallbackNoScope ||
                resolved.RestoreStrategy != expectedStrategy)
                throw new InvalidOperationException(
                    $"FAN-934: victim route {factory} must resolve to a compat-callback contract ({expectedStrategy})");
        }
        if (RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.NotARegisteredDevice") is not null ||
            RealHcBackend.ResolveRouteForSelfTest(null) is not null)
            throw new InvalidOperationException(
                "FAN-934: an unregistered/unknown device class must not resolve to any route (fail-closed)");
        checks.Add("fan934-victim-models-resolve-to-compat-contract-unknown-fails-closed");

        // ④ 同一进程内顺序切换机型：适用性按 deviceClass 解析，不因程序集缓存串机型。
        var rog1 = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.ROGAlly");
        var msi = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.ClawA2VM");
        var gpd = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.GPDWin5");
        var rog2 = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.ROGAlly");
        if (rog1?.Evidence != FanEvidenceMode.AsusScopeReceipts ||
            msi?.Evidence != FanEvidenceMode.CompatCallbackNoScope ||
            gpd?.Evidence != FanEvidenceMode.CompatCallbackNoScope ||
            rog2?.Evidence != FanEvidenceMode.AsusScopeReceipts)
            throw new InvalidOperationException(
                "FAN-934: sequential ROG->MSI->GPD->ROG applicability must not smear across device classes");
        checks.Add("fan934-sequential-route-switch-does-not-smear-applicability");

        // ⑤ 非 ASUS 正例：前提成立 + 真实回调已返回 ⇒ 兼容回调合同证据（软件合同，不是物理成功）。
        var asusUnused = new RealHcBackend.AsusWriteVerdict("unsupported", "n/a", false, false, false, 0);
        var compatOk = RealHcBackend.DecideOperationEvidence(
            FanEvidenceMode.CompatCallbackNoScope, "enable-curve", callbackReturned: true,
            compatPreconditionsOk: true, "compat-callback-preconditions-ok", asusUnused);
        if (compatOk.Kind != "compat-route-without-scope" || compatOk.ExplicitFailure || compatOk.Unknown ||
            FanHostEngine.ClassifyReleaseAction(compatOk.Kind) != OemReleaseAction.CompatRouteWithoutScope ||
            !FanHostEngine.IsOemReleaseSafeForSelfTest(true, compatOk.Kind))
            throw new InvalidOperationException("FAN-934: reviewed non-ASUS compat callback must settle as a route contract");
        checks.Add("fan934-non-asus-compat-callback-settles-as-route-contract");

        // ⑥ 负例（变异守卫"未执行回调也兼容"）：回调未返回 ⇒ 失败，**绝不放行**释放。
        var compatNoCallback = RealHcBackend.DecideOperationEvidence(
            FanEvidenceMode.CompatCallbackNoScope, "oem-restore", callbackReturned: false,
            compatPreconditionsOk: true, "compat-callback-preconditions-ok", asusUnused);
        if (compatNoCallback.Kind != "compat-route-callback-not-returned" ||
            !compatNoCallback.ExplicitFailure ||
            FanHostEngine.ClassifyReleaseAction(compatNoCallback.Kind) != OemReleaseAction.Failed ||
            FanHostEngine.IsOemReleaseSafeForSelfTest(true, compatNoCallback.Kind))
            throw new InvalidOperationException("FAN-934: a non-returned callback must fail, never authorise release");
        checks.Add("fan934-non-returned-callback-fails-closed");

        // ⑦ 负例：前提不成立（HC 未 Open / UseOpenLib 未满足 / 错误会话或路线）⇒ unknown，
        //    即便回调"返回"也不得当成已释放。
        foreach (var precondition in new[]
                 {
                     "session-not-ready:hc-not-open",
                     "hc-device-is-open-false",
                     "route-evidence=AsusScopeReceipts",
                 })
        {
            var unsatisfied = RealHcBackend.DecideOperationEvidence(
                FanEvidenceMode.CompatCallbackNoScope, "enable-curve", callbackReturned: true,
                compatPreconditionsOk: false, precondition, asusUnused);
            if (unsatisfied.Kind != "compat-route-precondition-unsatisfied" || !unsatisfied.Unknown ||
                FanHostEngine.ClassifyReleaseAction(unsatisfied.Kind) != OemReleaseAction.Unknown ||
                FanHostEngine.IsOemReleaseSafeForSelfTest(true, unsatisfied.Kind))
                throw new InvalidOperationException(
                    $"FAN-934: unsatisfied compat precondition ({precondition}) must stay unknown and unsafe");
        }
        checks.Add("fan934-unsatisfied-compat-preconditions-stay-unknown-and-unsafe");

        // ⑧ ASUS 正例保留 + 变异守卫"非 ASUS 也期待 ASUS 收据"/"所有空收据当兼容"：
        //    ASUS 路线的空收据必须原样读成 unknown（不是兼容成功），明确失败读成失败。
        var asusEmpty = RealHcBackend.DecideOperationEvidence(
            FanEvidenceMode.AsusScopeReceipts, "oem-restore", callbackReturned: true,
            compatPreconditionsOk: false, "n/a",
            new RealHcBackend.AsusWriteVerdict("no-receipts", "d", false, true, true, 0));
        if (asusEmpty.Kind != "no-receipts" ||
            FanHostEngine.ClassifyReleaseAction(asusEmpty.Kind) != OemReleaseAction.Unknown ||
            FanHostEngine.IsOemReleaseSafeForSelfTest(true, asusEmpty.Kind))
            throw new InvalidOperationException(
                "FAN-934: ASUS empty receipts must remain unknown (never washed into a compat success)");
        var asusFailed = RealHcBackend.DecideOperationEvidence(
            FanEvidenceMode.AsusScopeReceipts, "oem-restore", callbackReturned: true,
            compatPreconditionsOk: false, "n/a",
            new RealHcBackend.AsusWriteVerdict("explicit-failure", "d", true, false, true, 1));
        if (FanHostEngine.ClassifyReleaseAction(asusFailed.Kind) != OemReleaseAction.Failed ||
            FanHostEngine.IsOemReleaseSafeForSelfTest(true, asusFailed.Kind))
            throw new InvalidOperationException("FAN-934: ASUS explicit failure must remain a failure");
        checks.Add("fan934-asus-empty-receipts-not-washed-into-success");

        // ⑧-b 变异守卫"ASUS 空收据改成功"（承重变异 M4）：用**生产汇总函数** `CompleteAsusWriteScope`
        //      从**原始收据**驱动判定（而不是手填 `AsusWriteVerdict`），使"空收据→成功"这类改法无处可藏。
        using (var asusBackend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>())))
        {
            foreach (var c in new (string Case, object[] Receipts, string Kind,
                         OemReleaseAction Action, bool Safe)[]
                     {
                         ("empty", [], "no-receipts", OemReleaseAction.Unknown, false),
                         ("all-transported",
                             [
                                 new MockAsusFanReceipt { Fan = "CPU", Status = "TransportedComplete" },
                                 new MockAsusFanReceipt { Fan = "GPU", Status = "TransportedShort" },
                             ],
                             "transported", OemReleaseAction.Proven, true),
                         ("partial",
                             [
                                 new MockAsusFanReceipt { Fan = "CPU", Status = "TransportedComplete" },
                                 new MockAsusFanReceipt { Fan = "Mid", Status = "InitiatedFailed", Win32Error = 31 },
                             ],
                             "partial", OemReleaseAction.Proven, true),
                         ("explicit-failure",
                             [new MockAsusFanReceipt { Fan = "CPU", Status = "InitiatedFailed", Win32Error = 31 }],
                             "explicit-failure", OemReleaseAction.Failed, false),
                         ("io-exception",
                             [new MockAsusFanReceipt { Fan = "CPU", Status = "IoException" }],
                             "io-exception-unknown", OemReleaseAction.Unknown, false),
                     })
            {
                var result = DriveAsusScopeChain(asusBackend, c.Receipts);
                if (result.Kind != c.Kind || result.Action != c.Action || result.Safe != c.Safe)
                    throw new InvalidOperationException(
                        $"FAN-934: ASUS receipt mapping case {c.Case} must be produced by the production " +
                        $"summariser (expected kind={c.Kind} action={c.Action} safe={c.Safe}; " +
                        $"got kind={result.Kind} action={result.Action} safe={result.Safe} detail={result.Detail})");
            }
        }
        checks.Add("fan934-asus-receipt-mapping-driven-through-production-completescope");

        // ⑨ 变异守卫"host.stopped 替代进程退出"：停监听必须按路径分列报告；结构上钉住
        //    该方法只接受 StopListenerPath 枚举（防止无声退回"一个 host.stopped 当进程已退出"）。
        var stopMethod = typeof(LocalFanHostServer).GetMethod(
            "StopListenerAfterConfirmedEngineClose",
            BindingFlags.Instance | BindingFlags.NonPublic);
        var stopPathType = typeof(LocalFanHostServer).GetNestedType(
            "StopListenerPath", BindingFlags.Public | BindingFlags.NonPublic);
        if (stopMethod is null || stopPathType is null ||
            stopMethod.GetParameters() is not [{ ParameterType: var p0 }] || p0 != stopPathType ||
            !Enum.GetNames(stopPathType).OrderBy(n => n, StringComparer.Ordinal)
                .SequenceEqual(new[] { "BoundedFinalizeSafe", "ConfirmedRelease", "FailureTerminal" }))
            throw new InvalidOperationException(
                "FAN-934: stop-listener must report its path distinctly (listener stopped / dispose deferred / failure terminal)");
        checks.Add("fan934-host-stopped-splits-listener-vs-process-exit-semantics");

        // ⑩ §6.1 修前必失败／修后通过的同一输入对照（含 ASUS 观察 API 的装配下，GPD/MSI 被当作
        //    ASUS 作用域时：空收据→Unknown→不放行＝原 FaultLocked；改正后＝兼容回调结算→放行）。
        foreach (var victim in new[] { "HandheldCompanion.Devices.GPDWin5", "HandheldCompanion.Devices.MSI.ClawA2VM" })
        {
            var victimRoute = RealHcBackend.ResolveRouteForSelfTest(victim)
                ?? throw new InvalidOperationException($"FAN-934: victim route {victim} is unregistered");
            // 修前（旧判据）：把该路线当 ASUS 作用域，收据只有空集 ⇒ no-receipts ⇒ Unknown ⇒ 不放行。
            var legacy = RealHcBackend.DecideOperationEvidence(
                FanEvidenceMode.AsusScopeReceipts, "oem-restore", callbackReturned: true,
                compatPreconditionsOk: false, "n/a",
                new RealHcBackend.AsusWriteVerdict("no-receipts", "legacy-non-asus-treated-as-asus", false, true, true, 0));
            // 修后（按路线证据）：兼容回调合同 + 前提成立 + 回调返回 ⇒ 放行（软件合同，非物理成功）。
            var fixedVerdict = RealHcBackend.DecideOperationEvidence(
                victimRoute.Evidence, "oem-restore", callbackReturned: true,
                compatPreconditionsOk: true, "compat-callback-preconditions-ok", legacy);
            var legacySafe = FanHostEngine.IsOemReleaseSafeForSelfTest(true, legacy.Kind);
            var fixedSafe = FanHostEngine.IsOemReleaseSafeForSelfTest(true, fixedVerdict.Kind);
            if (victimRoute.Evidence != FanEvidenceMode.CompatCallbackNoScope ||
                legacy.Kind != "no-receipts" || legacySafe ||
                fixedVerdict.Kind != "compat-route-without-scope" || !fixedSafe ||
                legacySafe == fixedSafe)
                throw new InvalidOperationException(
                    $"FAN-934: victim {victim} must fail under legacy ASUS-scope judgement and pass under its route contract " +
                    $"(legacy={legacy.Kind}/safe={legacySafe} fixed={fixedVerdict.Kind}/safe={fixedSafe})");
        }
        checks.Add("fan934-legacy-asus-scope-on-non-asus-fails-fixed-route-contract-passes");

        // ⑪ §6.5 恢复合同矩阵：用户口径"12 类恢复合同"= FanRestoreStrategy 枚举 12 值（合同类型全集）；
        //    注册表实际只用其中 11 类（GenericEcDutyRegister 目前未登记任何路线——口径差异单列，
        //    不得把"枚举有 12 值"读成"12 组都各有条目"）。且只有 ASUS 组声明 ASUS 作用域收据。
        if (Enum.GetValues<FanRestoreStrategy>().Length != 12)
            throw new InvalidOperationException("FAN-934: fan restore contract enum must expose 12 kinds");
        var byStrategy = routes.GroupBy(pair => pair.Value.RestoreStrategy)
            .ToDictionary(group => group.Key, group => group.ToList());
        var expectedStrategies = new[]
        {
            FanRestoreStrategy.GenericEcControl, FanRestoreStrategy.AyanEOCEiiModeRegister,
            FanRestoreStrategy.OneXAcpiFanMode, FanRestoreStrategy.GpdWin4HcRelease,
            FanRestoreStrategy.GpdWin5HcAutoRelease, FanRestoreStrategy.AynLokiMode,
            FanRestoreStrategy.MsiHcDefaultRelease, FanRestoreStrategy.LenovoHcDefaultTable,
            FanRestoreStrategy.LegionGo2EcRpmOverride, FanRestoreStrategy.AsusAcpiCurves,
            FanRestoreStrategy.None,
        };
        var missingGroups = expectedStrategies.Where(strategy => !byStrategy.ContainsKey(strategy)).ToArray();
        if (missingGroups.Length != 0)
            throw new InvalidOperationException(
                $"FAN-934: recovery-contract groups missing from the route registry: {string.Join(',', missingGroups)}");
        foreach (var (strategy, group) in byStrategy)
        {
            var wantAsus = strategy == FanRestoreStrategy.AsusAcpiCurves;
            if (group.Any(pair => (pair.Value.Evidence == FanEvidenceMode.AsusScopeReceipts) != wantAsus))
                throw new InvalidOperationException(
                    $"FAN-934: strategy {strategy} evidence mode is inconsistent (ASUS scope only belongs to AsusAcpiCurves)");
            if (group.Any(pair => pair.Value.Evidence == FanEvidenceMode.UnsupportedNoScope))
                throw new InvalidOperationException(
                    $"FAN-934: registered route under strategy {strategy} must not stay fail-closed unsupported");
        }
        // `None`（GPD WinMini 共用控制/占空地址 + SteamDeck ramp/IO6C）必须各有独立条目，
        // 既不当"一概放行"也不当"一概不支持"——两者都已审阅为兼容回调合同。
        var noneGroup = byStrategy[FanRestoreStrategy.None];
        if (noneGroup.Count < 2 ||
            noneGroup.Any(pair => pair.Value.Evidence != FanEvidenceMode.CompatCallbackNoScope))
            throw new InvalidOperationException(
                "FAN-934: RestoreStrategy.None (GPD WinMini + SteamDeck) needs its own reviewed compat-callback entries");
        checks.Add(
            $"fan934-registry-{byStrategy.Count}-registered-groups-of-12-contract-kinds " +
            $"(none={noneGroup.Count} asus={byStrategy[FanRestoreStrategy.AsusAcpiCurves].Count} " +
            $"unused={string.Join(',', Enum.GetValues<FanRestoreStrategy>().Except(byStrategy.Keys))})");

        // ⑫ §4.C 命令通道：按 provider 定义，不再对全部厂商硬填 CPU/GPU/Mid。
        //    变异守卫"所有厂商一律 CPU/GPU/Mid"：只有 ASUS 允许出现 Mid（第三命令点）；
        //    非 ASUS 出现 Mid 即视为捏造第三风扇，必须被门抓住。
        var channelExpectations = new (FanRestoreStrategy Strategy, string[] Expected)[]
        {
            (FanRestoreStrategy.AsusAcpiCurves, ["CPU", "GPU", "Mid"]),
            (FanRestoreStrategy.MsiHcDefaultRelease, ["CPU", "GPU"]),
            (FanRestoreStrategy.GpdWin4HcRelease, ["Fan1", "Fan2"]),
            (FanRestoreStrategy.GpdWin5HcAutoRelease, ["Fan1", "Fan2"]),
            (FanRestoreStrategy.LenovoHcDefaultTable, ["aggregate"]),
            (FanRestoreStrategy.LegionGo2EcRpmOverride, ["aggregate"]),
            (FanRestoreStrategy.GenericEcControl, ["aggregate"]),
            (FanRestoreStrategy.OneXAcpiFanMode, ["aggregate"]),
            (FanRestoreStrategy.AyanEOCEiiModeRegister, ["aggregate"]),
            (FanRestoreStrategy.AynLokiMode, ["aggregate"]),
            (FanRestoreStrategy.None, ["aggregate"]),
        };
        foreach (var (strategy, expected) in channelExpectations)
        {
            var actual = RealHcBackend.ResolveFanCommandChannelsForSelfTest(strategy);
            if (!actual.SequenceEqual(expected))
                throw new InvalidOperationException(
                    $"FAN-934: {strategy} command channels must be [{string.Join(',', expected)}] " +
                    $"(got [{string.Join(',', actual)}])");
        }
        if (!RealHcBackend.ResolveFanCommandChannelsForSelfTest(null).SequenceEqual(["aggregate"]))
            throw new InvalidOperationException(
                "FAN-934: an unknown/undeclared route must report the honest aggregate channel (fail-honest)");
        foreach (var strategy in Enum.GetValues<FanRestoreStrategy>())
        {
            if (strategy == FanRestoreStrategy.AsusAcpiCurves) continue;
            if (RealHcBackend.ResolveFanCommandChannelsForSelfTest(strategy).Contains("Mid", StringComparer.Ordinal))
                throw new InvalidOperationException(
                    $"FAN-934: non-ASUS strategy {strategy} must not fabricate a third 'Mid' fan channel");
        }
        checks.Add("fan934-command-channels-are-provider-defined-not-hardcoded-cpu-gpu-mid");

        // ⑬ FAN-934 R2 §3-A.2：按机型前提的**状态化**正反例——驱动**真实**生产判定链
        //    （Begin→Settle→Classify→IsOemReleaseSafe）。修前负例手填 `compatPreconditionsOk:false`
        //    抓不住"依赖 OpenLib 的路线未核 UseOpenLib"这一缺口；这里改为用 mock 设备的
        //    真实成员值让生产前提函数自行判定。
        foreach (var victim in new[] { "HandheldCompanion.Devices.GPDWin5", "HandheldCompanion.Devices.MSI.ClawA2VM" })
        {
            var victimRoute = RealHcBackend.ResolveRouteForSelfTest(victim)
                ?? throw new InvalidOperationException($"FAN-934: victim route {victim} is unregistered");
            var openLibFamily = victimRoute.Precondition == FanRoutePrecondition.OpenLibHandleOpen;
            using var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));

            // 正例：前提齐备 + 真实回调返回 ⇒ 兼容回调合同（软件合同，非物理成功），放行。
            var positive = DrivePreconditionChain(
                backend, victimRoute, useOpenLib: true, deviceIsOpen: true,
                deviceIsSupported: true, backendOpen: true, callbackReturned: true);
            if (positive.Kind != "compat-route-without-scope" ||
                positive.Action != OemReleaseAction.CompatRouteWithoutScope || !positive.Safe)
                throw new InvalidOperationException(
                    $"FAN-934: {victim} with its declared preconditions met must settle as a compat contract " +
                    $"(kind={positive.Kind} action={positive.Action} safe={positive.Safe} detail={positive.Detail})");

            // 反例①：设备句柄未打开（`IsOpen=false`）⇒ 前提不成立 ⇒ unknown，绝不放行。
            var handleClosed = DrivePreconditionChain(
                backend, victimRoute, useOpenLib: true, deviceIsOpen: false,
                deviceIsSupported: true, backendOpen: true, callbackReturned: true);
            if (handleClosed.Kind != "compat-route-precondition-unsatisfied" ||
                handleClosed.Action != OemReleaseAction.Unknown || handleClosed.Safe)
                throw new InvalidOperationException(
                    $"FAN-934: {victim} with a closed device handle must stay unknown/unsafe " +
                    $"(kind={handleClosed.Kind} action={handleClosed.Action} safe={handleClosed.Safe} detail={handleClosed.Detail})");

            // 反例②（F2 直指项）：backend 会话未就绪 ⇒ 前提不成立 ⇒ unknown。
            var sessionClosed = DrivePreconditionChain(
                backend, victimRoute, useOpenLib: true, deviceIsOpen: true,
                deviceIsSupported: true, backendOpen: false, callbackReturned: true);
            if (sessionClosed.Kind != "compat-route-precondition-unsatisfied" ||
                sessionClosed.Action != OemReleaseAction.Unknown || sessionClosed.Safe)
                throw new InvalidOperationException(
                    $"FAN-934: {victim} with an unready backend session must stay unknown/unsafe " +
                    $"(kind={sessionClosed.Kind} action={sessionClosed.Action} safe={sessionClosed.Safe})");

            // 反例③（F2 直指项）：依赖 OpenLib 的族在 `UseOpenLib=false` 时 HC 设备方法会**静默 return**，
            //   反射 Invoke 不抛异常 **不等于**回落执行。生产前提函数必须自行读出该缺口。
            if (openLibFamily)
            {
                var openLibMissing = DrivePreconditionChain(
                    backend, victimRoute, useOpenLib: false, deviceIsOpen: true,
                    deviceIsSupported: true, backendOpen: true, callbackReturned: true);
                if (openLibMissing.Kind != "compat-route-precondition-unsatisfied" ||
                    openLibMissing.Action != OemReleaseAction.Unknown || openLibMissing.Safe ||
                    !openLibMissing.Detail.Contains("useOpenLib=False", StringComparison.Ordinal))
                    throw new InvalidOperationException(
                        $"FAN-934: {victim} requires UseOpenLib (HC silently returns otherwise); a missing OpenLib " +
                        $"handle must be caught by the real precondition function, not hand-filled " +
                        $"(kind={openLibMissing.Kind} safe={openLibMissing.Safe} detail={openLibMissing.Detail})");
            }
        }
        checks.Add("fan934-real-precondition-chain-gpd-msi-positive-and-negative");

        // ⑬-b SteamDeck（`DeviceOpenAndSupported`）与 MSI（`DeviceOpen`）分层不同，不得一刀切：
        //     SteamDeck 还需 `IsSupported`；MSI WMI 表只需设备句柄打开。
        {
            using var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
            var steamDeck = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.SteamDeck")
                ?? throw new InvalidOperationException("FAN-934: SteamDeck route is unregistered");
            if (steamDeck.Precondition != FanRoutePrecondition.DeviceOpenAndSupported)
                throw new InvalidOperationException("FAN-934: SteamDeck must declare DeviceOpenAndSupported");
            var notSupported = DrivePreconditionChain(
                backend, steamDeck, useOpenLib: false, deviceIsOpen: true,
                deviceIsSupported: false, backendOpen: true, callbackReturned: true);
            if (notSupported.Kind != "compat-route-precondition-unsatisfied" || notSupported.Safe)
                throw new InvalidOperationException(
                    $"FAN-934: SteamDeck without IsSupported must stay unknown/unsafe (kind={notSupported.Kind})");
            var supported = DrivePreconditionChain(
                backend, steamDeck, useOpenLib: false, deviceIsOpen: true,
                deviceIsSupported: true, backendOpen: true, callbackReturned: true);
            if (supported.Kind != "compat-route-without-scope" || !supported.Safe)
                throw new InvalidOperationException(
                    $"FAN-934: SteamDeck with IsOpen&&IsSupported must settle as a compat contract (kind={supported.Kind})");

            // 未声明前提的路线（fail-closed 默认）即便 mock 全开也不得通过。
            var undeclared = new FanRoute(FanRouteKind.GenericDuty, "selftest-undeclared-precondition",
                true, true, FanRestoreStrategy.GenericEcControl, FanEvidenceMode.CompatCallbackNoScope,
                FanRoutePrecondition.Undeclared);
            var undeclaredResult = DrivePreconditionChain(
                backend, undeclared, useOpenLib: true, deviceIsOpen: true,
                deviceIsSupported: true, backendOpen: true, callbackReturned: true);
            if (undeclaredResult.Kind != "compat-route-precondition-unsatisfied" ||
                undeclaredResult.Action != OemReleaseAction.Unknown || undeclaredResult.Safe ||
                !undeclaredResult.Detail.Contains("compat-precondition-undeclared", StringComparison.Ordinal))
                throw new InvalidOperationException(
                    $"FAN-934: an undeclared-precondition route must fail closed even with an open device " +
                    $"(kind={undeclaredResult.Kind} detail={undeclaredResult.Detail})");
        }
        checks.Add("fan934-precondition-tiers-not-one-size-fits-all-and-undeclared-fails-closed");

        // ⑬-c ASUS 路线保留专属作用域收据检查：装配缺失（无候选程序集）时读不到操作作用域 API ⇒
        //     如实记 `receipt-api-fault`（unknown），**绝不**降成普通无 scope 兼容成功。
        {
            using var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
            var asusRoute = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.ROGAlly")
                ?? throw new InvalidOperationException("FAN-934: ROGAlly route is unregistered");
            var asus = DrivePreconditionChain(
                backend, asusRoute, useOpenLib: true, deviceIsOpen: true,
                deviceIsSupported: true, backendOpen: true, callbackReturned: true);
            if (asus.Kind != "receipt-api-fault" || asus.Action != OemReleaseAction.Unknown || asus.Safe)
                throw new InvalidOperationException(
                    $"FAN-934: an ASUS route without its scope API must stay unknown (never compat success) " +
                    $"(kind={asus.Kind} action={asus.Action} safe={asus.Safe})");
        }
        checks.Add("fan934-asus-scope-api-absent-stays-unknown-not-compat");

        // ⑭ FAN-934 R2 §3-B 承重门：GPD 与 MSI 各跑一条**生产恢复入口**（`RestoreOem()` /
        //     `Close()`）的状态化 mock 会话，覆盖 Open/Enable → 调节 → OEM Restore → 关闭 →
        //     重开 → 再调节，并如实记录生产代码经唯一 HC 回调边界的**实际调用计数**与关闭
        //     边界命中。整个会话在 HC/OS 边界隔离（无候选程序集、无真实 EC/WMI）。
        //     负例覆盖：回调抛异常／路线未声明回调能力（未调用）／已审阅前提不满足／错会话／
        //     Close 清理图不可读。
        foreach (var (factory, expectedPrecondition) in new[]
                 {
                     ("HandheldCompanion.Devices.GPDWin5", FanRoutePrecondition.OpenLibHandleOpen),
                     ("HandheldCompanion.Devices.MSI.ClawA2VM", FanRoutePrecondition.DeviceOpen),
                 })
        {
            var route = RealHcBackend.ResolveRouteForSelfTest(factory)
                ?? throw new InvalidOperationException($"FAN-934: {factory} route is unregistered");
            if (route.Precondition != expectedPrecondition)
                throw new InvalidOperationException(
                    $"FAN-934: {factory} precondition must be {expectedPrecondition} but was {route.Precondition}");
            // FAN-936 §3：MSI 走 HC 结构化释放证书，GPD 仍走软件回调合同；两条正向路径按此分流断言。
            var isMsiStructuredRoute = route.RestoreStrategy == FanRestoreStrategy.MsiHcDefaultRelease;
            // FAN-936 R2 section 2：MSI 交还改走 HC 窄接口 `ReleaseMsiFanControl`（**不**经过唯一回调
            // 边界），故 MSI 的回调计数只来自 enable/re-enable；GPD 每段调节都经过回调边界。正向三条
            // 计数断言按路线取期望值，避免把"MSI 少一次回调"误判成回归。
            var expectedCallbacksAfterRelease = isMsiStructuredRoute ? 1 : 2;

            // 正向全周期：Enable/调节 → OEM Restore → Close → 重开 → 再调节。
            using (var backend = NewRestoreEntryHarness(
                       route, useOpenLib: true, deviceIsOpen: true, out var mock, out var boundary))
            {
                var enableScope = backend.BeginAsusWriteScope("enable-curve");
                var enableProfile = backend.BuildPowerProfileForSelfTest(new[] { 30d, 40d, 50d }, software: true);
                backend.ApplyPowerProfileForSelfTest(enableProfile, "Background");
                var enableWrite = backend.SettleOperationEvidence(enableScope, "enable-curve", callbackReturned: true);
                if (enableWrite.Kind != "compat-route-without-scope" || boundary.CallbackInvocationCount != 1)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: enable must settle via the compat callback route " +
                        $"(kind={enableWrite.Kind} callbacks={boundary.CallbackInvocationCount})");

                var restoreFailure = CaptureRestoreFailure(backend);
                // FAN-936 §3：MSI 的合格证书是 HC 侧**结构化释放回读结论**（kind=proven-by-msi-structured-release，
                // evidence=hc-msi-structured-release-returned）；GPD 仍走已审阅路线的软件回调合同（compat）。
                // 两条路线都仍**不是**物理 RPM 确认，故 ownership 一律保持 physical-unknown。
                var expectedReleaseKind = isMsiStructuredRoute
                    ? "proven-by-msi-structured-release"
                    : "compat-route-without-scope";
                var expectedReleaseEvidence = isMsiStructuredRoute
                    ? "hc-msi-structured-release-returned"
                    : "hc-compat-route-callback-returned";
                if (restoreFailure != "<no-failure>" || boundary.CallbackInvocationCount != expectedCallbacksAfterRelease ||
                    !backend.OemRestoreVerified ||
                    backend.OemReleaseActionKind != expectedReleaseKind ||
                    backend.OemRestoreEvidence != expectedReleaseEvidence ||
                    backend.OemOwnershipStatus != "hc-callback-only-physical-unknown")
                    throw new InvalidOperationException(
                        $"FAN-936 {factory}: production RestoreOem must settle a verified route release " +
                        $"(failure={restoreFailure} callbacks={boundary.CallbackInvocationCount} " +
                        $"verified={backend.OemRestoreVerified} kind={backend.OemReleaseActionKind} " +
                        $"evidence={backend.OemRestoreEvidence} ownership={backend.OemOwnershipStatus})");

                var closeFailure = CaptureCloseFailure(backend);
                if (closeFailure != "<no-failure>" || mock.CloseInvocationCount != 1 ||
                    !backend.HcVirtualCloseReturned || !backend.HcManagerCleanupConfirmed ||
                    !backend.HcDeviceManagerStopCompleted || boundary.CallbackInvocationCount != expectedCallbacksAfterRelease)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: production Close must hit the virtual device boundary once and " +
                        $"confirm manager cleanup (failure={closeFailure} closeInvocations={mock.CloseInvocationCount} " +
                        $"virtualClose={backend.HcVirtualCloseReturned} cleanupConfirmed={backend.HcManagerCleanupConfirmed} " +
                        $"stopCompleted={backend.HcDeviceManagerStopCompleted} callbacks={boundary.CallbackInvocationCount})");

                backend.ReopenSelfTestSessionForSelfTest(mock, route, backendOpen: true);
                var reopenScope = backend.BeginAsusWriteScope("enable-curve");
                var reopenProfile = backend.BuildPowerProfileForSelfTest(new[] { 60d, 70d, 80d }, software: true);
                backend.ApplyPowerProfileForSelfTest(reopenProfile, "Background");
                var reopenWrite = backend.SettleOperationEvidence(reopenScope, "enable-curve", callbackReturned: true);
                if (reopenWrite.Kind != "compat-route-without-scope" ||
                    boundary.CallbackInvocationCount != expectedCallbacksAfterRelease + 1)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: reopen + re-enable must keep using the single compat callback boundary " +
                        $"(kind={reopenWrite.Kind} callbacks={boundary.CallbackInvocationCount})");
            }

            // 负例①（抛异常）：HC 释放例程/回调抛出 ⇒ 原异常 rethrow，本次释放留在 not-attempted，
            //     绝不置 verified。MSI 走窄接口（`ReleaseMsiFanControl` 抛），GPD 走完整回调边界抛。
            if (isMsiStructuredRoute)
            {
                using var backend = NewRestoreEntryHarness(
                    route, useOpenLib: true, deviceIsOpen: true, out var releaseMock, out _);
                var boom = new InvalidOperationException("selftest-msi-release-threw");
                releaseMock.MsiReleaseFailure = boom;
                var failure = CaptureRestoreFailure(backend);
                if (failure == "<no-failure>" || releaseMock.ReleaseMsiFanControlInvocationCount != 1 ||
                    releaseMock.LastMsiFanReleaseCause != "oem-restore" ||
                    backend.OemReleaseActionKind != "not-attempted" || backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: a throwing HC release routine must rethrow and never verify release " +
                        $"(failure={failure} releaseInvocations={releaseMock.ReleaseMsiFanControlInvocationCount} " +
                        $"kind={backend.OemReleaseActionKind} verified={backend.OemRestoreVerified})");
            }
            else
            {
                using var backend = NewRestoreEntryHarness(
                    route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary);
                var boom = new InvalidOperationException("selftest-hc-callback-threw");
                boundary.CallbackFailure = boom;
                var failure = CaptureRestoreFailure(backend);
                if (failure != boom.Message || boundary.CallbackInvocationCount != 1 ||
                    backend.OemReleaseActionKind != "not-attempted" || backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: a throwing HC callback must rethrow and never verify release " +
                        $"(failure={failure} callbacks={boundary.CallbackInvocationCount} " +
                        $"kind={backend.OemReleaseActionKind} verified={backend.OemRestoreVerified})");
            }

            // 负例②（未调用）：路线未声明 HC 回调能力 ⇒ 会话守卫先拦，回调一次都不发。
            using (var backend = NewRestoreEntryHarness(
                       route with { HcCallbackReady = false }, useOpenLib: true, deviceIsOpen: true,
                       out _, out var boundary))
            {
                var failure = CaptureRestoreFailure(backend);
                if (!failure.Contains("HC_SESSION_ROUTE_LOST", StringComparison.Ordinal) ||
                    !failure.Contains("route-baseline-marker-lost", StringComparison.Ordinal) ||
                    boundary.CallbackInvocationCount != 0 || backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: a route without callback capability must be stopped by the session guard " +
                        $"(failure={failure} callbacks={boundary.CallbackInvocationCount} verified={backend.OemRestoreVerified})");
            }

            // 负例③（前提不满足）：已审阅前提不成立 ⇒ 本次释放不得放行。GPD 核 OpenLib 句柄（设备仍开、
            //     回调仍会被调用一次，但结算必须停在 unknown）；MSI 核设备 IsOpen（更早的会话守卫先拦）。
            {
                var openLibRoute = route.Precondition == FanRoutePrecondition.OpenLibHandleOpen;
                using var backend = NewRestoreEntryHarness(
                    route,
                    useOpenLib: !openLibRoute,
                    deviceIsOpen: openLibRoute,
                    out _, out var boundary);
                var failure = CaptureRestoreFailure(backend);
                if (backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: an unsatisfied compat precondition must never verify release (failure={failure})");
                if (openLibRoute)
                {
                    if (boundary.CallbackInvocationCount != 1 ||
                        backend.OemReleaseActionKind != "unknown-release-action" ||
                        !failure.Contains("did not satisfy the route release contract", StringComparison.Ordinal))
                        throw new InvalidOperationException(
                            $"FAN-934 {factory}: GPD without a usable OpenLib handle must call the callback once " +
                            $"but settle unknown (callbacks={boundary.CallbackInvocationCount} " +
                            $"kind={backend.OemReleaseActionKind} failure={failure})");
                }
                else
                {
                    if (boundary.CallbackInvocationCount != 0 ||
                        !failure.Contains("hc-device-is-open-false", StringComparison.Ordinal))
                        throw new InvalidOperationException(
                            $"FAN-934 {factory}: MSI with a closed device must be stopped before the callback " +
                            $"(callbacks={boundary.CallbackInvocationCount} failure={failure})");
                }
            }

            // 负例④（错会话）：设备身份漂移 ⇒ 守卫拒绝，回调一次都不发。
            using (var backend = NewRestoreEntryHarness(
                       route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary))
            {
                backend.SwapDeviceForSelfTest(new object());
                var failure = CaptureRestoreFailure(backend);
                if (!failure.Contains("device-reference-marker-lost", StringComparison.Ordinal) ||
                    boundary.CallbackInvocationCount != 0 || backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: a drifted session device reference must be stopped by the guard " +
                        $"(failure={failure} callbacks={boundary.CallbackInvocationCount} verified={backend.OemRestoreVerified})");
            }

            // 负例⑤（关闭清理不可读）：Close 后 ManagerFactory 图不可读 ⇒ 不得确认清理，但虚拟 Close 边界
            //     的调用计数仍必须为 1（实测到达边界，只是清理证据未结算）。
            using (var backend = NewRestoreEntryHarness(
                       route, useOpenLib: true, deviceIsOpen: true, out var mock, out var boundary))
            {
                boundary.ManagerObservationAvailable = false;
                var failure = CaptureCloseFailure(backend);
                if (!failure.Contains("HC_CLOSE_PENDING", StringComparison.Ordinal) || mock.CloseInvocationCount != 1 ||
                    backend.HcManagerCleanupConfirmed || backend.HcDeviceManagerStopCompleted)
                    throw new InvalidOperationException(
                        $"FAN-934 {factory}: an unreadable manager graph must fail closed on close " +
                        $"(failure={failure} closeInvocations={mock.CloseInvocationCount} " +
                        $"confirmed={backend.HcManagerCleanupConfirmed} stopCompleted={backend.HcDeviceManagerStopCompleted})");
            }

            // FAN-936 §3/§5 负例（只在 MSI 路线跑）：结构化释放证书的三条反例都不得被洗成成功：
            //   ① HC 未给出结构化结论（缺失）⇒ Unknown，绝不回落 compat；
            //   ② 结论未绑定本次开机（陈旧 boot identity）⇒ Unknown；
            //   ③ 结论明确 Status=failed ⇒ Failed（不得记 success，也不得被 cleanup 顶替）。
            if (isMsiStructuredRoute)
            {
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out _,
                           msiStructuredReleaseSuppressed: true))
                {
                    var failure = CaptureRestoreFailure(backend);
                    if (backend.OemRestoreVerified ||
                        backend.OemReleaseActionKind != "unknown-release-action" ||
                        !failure.Contains("did not satisfy the route release contract", StringComparison.Ordinal))
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: an absent MSI structured release must fail closed as unknown " +
                            $"(failure={failure} verified={backend.OemRestoreVerified} kind={backend.OemReleaseActionKind})");
                }

                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out _,
                           msiStructuredRelease: BuildMsiStructuredReleaseForSelfTest(
                               BootIdentity: "1999-01-01T00:00:00Z")))
                {
                    var failure = CaptureRestoreFailure(backend);
                    if (backend.OemRestoreVerified ||
                        backend.OemReleaseActionKind != "unknown-release-action" ||
                        !failure.Contains("did not satisfy the route release contract", StringComparison.Ordinal))
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a stale-boot MSI structured release must fail closed as unknown " +
                            $"(failure={failure} verified={backend.OemRestoreVerified} kind={backend.OemReleaseActionKind})");
                }

                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary))
                {
                    // ③ 结论明确 Status=failed ⇒ Failed。用**生产保真**模式（窄接口释放例程回显本次操作
                    //    令牌），只把真实回调结论置为 failed——避免用冻结旧收据时先被 R4 令牌门拒成 unknown。
                    boundary.ReleaseReceiptStatus = "failed";
                    boundary.ReleaseReceiptFullSpeedStatus = "failed";
                    var failure = CaptureRestoreFailure(backend);
                    if (backend.OemRestoreVerified ||
                        backend.OemReleaseActionKind != "failed-release-action" ||
                        !failure.Contains("did not satisfy the route release contract", StringComparison.Ordinal))
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a failed MSI structured release must be recorded as failed " +
                            $"(failure={failure} verified={backend.OemRestoreVerified} kind={backend.OemReleaseActionKind})");
                }

                // FAN-936 R4 负例：预置一条**绑定本次开机但令牌陈旧/错设备**的旧收据，本次恢复不得更新它。
                // 生产入口必须因操作令牌不匹配而 fail-closed（verified=false），绝不把旧收据认成本次结果。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out var staleMock, out _,
                           msiStructuredRelease: NewStaleMsiReleaseReceiptForSelfTest()))
                {
                    var oldReceipt = staleMock.LastMsiFanRelease;
                    var failure = CaptureRestoreFailure(backend);
                    if (backend.OemRestoreVerified ||
                        backend.OemReleaseActionKind != "unknown-release-action" ||
                        !ReferenceEquals(oldReceipt, staleMock.LastMsiFanRelease) ||
                        !failure.Contains("did not satisfy the route release contract", StringComparison.Ordinal))
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a stale-operation MSI release receipt must be refused (fail-closed) " +
                            $"(failure={failure} verified={backend.OemRestoreVerified} " +
                            $"kind={backend.OemReleaseActionKind} receiptUnchanged={ReferenceEquals(oldReceipt, staleMock.LastMsiFanRelease)})");
                }

                // FAN-936 R1：MSI 软件控制成功态必须由 HC 侧结构化结论支撑（fail-closed），
                // 而不是"回调返回"。读取失败（fanTable≠ok）或未 latch（softwareControl∉{ok,skipped-already-target}）
                // 一律 409 FAN_CURVE_WRITE_FAILED，绝不建立控制成功态。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out var mock, out _))
                {
                    // 正例：表写 ok + 软件控制 ok ⇒ 建立成功（不抛）。
                    mock.LastMsiFanTableWrite = new { Status = "ok" };
                    mock.LastMsiFanControlWrite = new { Status = "ok" };
                    var ok = CaptureFanApiFailure(
                        () => backend.EnsureMsiSoftwareControlEstablishedForSelfTest("enable-curve"));
                    if (ok.Code is not null)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a verified MSI table+control must establish software control (message={ok.Message})");

                    // 正例：软件控制已在目标位（skipped-already-target）同样算建立。
                    mock.LastMsiFanControlWrite = new { Status = "skipped-already-target" };
                    if (CaptureFanApiFailure(
                            () => backend.EnsureMsiSoftwareControlEstablishedForSelfTest("enable-curve")).Code is not null)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: an already-at-target MSI software control must count as established");

                    // 反例①：风扇表读取失败（unknown）⇒ 不得建立软件控制成功态。
                    mock.LastMsiFanTableWrite = new { Status = "unknown" };
                    mock.LastMsiFanControlWrite = new { Status = "ok" };
                    var tableFail = CaptureFanApiFailure(
                        () => backend.EnsureMsiSoftwareControlEstablishedForSelfTest("enable-curve"));
                    if (tableFail.Code != "FAN_CURVE_WRITE_FAILED" || tableFail.Status != 409)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: an unreadable MSI fan table must fail closed with " +
                            $"FAN_CURVE_WRITE_FAILED/409 (code={tableFail.Code ?? "<none>"} status={tableFail.Status})");

                    // 反例②：软件控制未 latch（unknown）⇒ 不得建立软件控制成功态。
                    mock.LastMsiFanTableWrite = new { Status = "ok" };
                    mock.LastMsiFanControlWrite = new { Status = "unknown" };
                    var controlFail = CaptureFanApiFailure(
                        () => backend.EnsureMsiSoftwareControlEstablishedForSelfTest("enable-curve"));
                    if (controlFail.Code != "FAN_CURVE_WRITE_FAILED" || controlFail.Status != 409)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: an unlatched MSI software control must fail closed with " +
                            $"FAN_CURVE_WRITE_FAILED/409 (code={controlFail.Code ?? "<none>"} status={controlFail.Status})");

                    // 反例③：HC 结论缺失（未注入）⇒ 同样 fail-closed。
                    mock.LastMsiFanTableWrite = null;
                    mock.LastMsiFanControlWrite = null;
                    if (CaptureFanApiFailure(
                            () => backend.EnsureMsiSoftwareControlEstablishedForSelfTest("enable-curve")).Code
                        != "FAN_CURVE_WRITE_FAILED")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: an absent MSI table/control conclusion must fail closed");
                }
            }

            // FAN-936 R2 §5：基线绑定门已被收窄为 **MSI 专属**（R2 §1）。因此 fail-closed 负例只在
            // MSI 路线跑；ROG/GPD/Lenovo/通用路线**不**继承 FAN_BASELINE_BINDING_LOST（绑定判定仍
            // 如实报出失效原因，但准入门对其不生效）。非 MSI 的正例断言见本循环之后的豁免块。
            // 未捕获基线、跨控制周期、跨 boot identity、Host 实例漂移都不得消费旧快照；设备实例/
            // 类型漂移必须被绑定判定点名；延迟 WMI 未返回期间不得放行并发恢复。逐条断言"绑定判定
            // 原因"与"生产入口拒绝且零回调、绝不置 verified"。
            if (isMsiStructuredRoute)
            {
                // ① 未捕获基线：MSI 路线已准入但基线未落定 ⇒ baseline-not-captured，绑定门 409。
                {
                    using var backend = NewRestoreEntryHarness(
                        route, useOpenLib: true, deviceIsOpen: true, out _, out _);
                    backend.ClearBaselineCaptureForSelfTest();
                    if (backend.BaselineBindingStillValid(out var reason) || reason != "baseline-not-captured")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: an uncaptured MSI baseline must report baseline-not-captured (reason={reason})");
                    var gate = CaptureFanApiFailure(backend.EnsureBaselineBindingForControl);
                    if (gate.Code != "FAN_BASELINE_BINDING_LOST" || gate.Status != 409)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: an uncaptured baseline must fail closed with " +
                            $"FAN_BASELINE_BINDING_LOST/409 (code={gate.Code ?? "<none>"} status={gate.Status} message={gate.Message})");
                }

                // ② 正例：装好会话后绑定必须恰好为 bound（防止上面的负例靠"恒 false"蒙混）。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out _))
                {
                    if (!backend.BaselineBindingStillValid(out var reason) || reason != "bound")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a freshly installed session must be baseline-bound (reason={reason})");
                }

                // ③ 跨控制周期：旧周期快照必须在**任何回调之前**被绑定门拒掉，回调零次。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary))
                {
                    if (!backend.BaselineBindingStillValid(out var before) || before != "bound")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: the cross-cycle negative requires a bound precondition (reason={before})");
                    backend.ControlCycleId += 1;
                    if (backend.BaselineBindingStillValid(out var reason) || reason != "control-cycle-changed")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a bumped control cycle must invalidate the baseline (reason={reason})");
                    var failure = CaptureFanApiFailure(backend.RestoreOem);
                    if (failure.Code != "FAN_BASELINE_BINDING_LOST" || failure.Status != 409 ||
                        boundary.CallbackInvocationCount != 0 || backend.OemRestoreVerified)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a stale-cycle restore must be refused before any callback " +
                            $"(code={failure.Code ?? "<none>"} status={failure.Status} callbacks={boundary.CallbackInvocationCount} " +
                            $"verified={backend.OemRestoreVerified} message={failure.Message})");
                }

                // ④ 跨 boot identity：绑定其它开机的旧基线必须被拒，回调零次。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary))
                {
                    backend.ForceStaleBaselineBootIdentityForSelfTest();
                    if (backend.BaselineBindingStillValid(out var reason) || reason != "boot-identity-changed")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a baseline bound to another boot must be invalid (reason={reason})");
                    var failure = CaptureFanApiFailure(backend.RestoreOem);
                    if (failure.Code != "FAN_BASELINE_BINDING_LOST" || failure.Status != 409 ||
                        boundary.CallbackInvocationCount != 0 || backend.OemRestoreVerified)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a stale-boot baseline must be refused before any callback " +
                            $"(code={failure.Code ?? "<none>"} status={failure.Status} callbacks={boundary.CallbackInvocationCount} " +
                            $"verified={backend.OemRestoreVerified} message={failure.Message})");
                }

                // ⑤ 设备实例漂移（同类型新实例）：绑定判定必须为 device-instance-changed；生产入口另由
                //    会话守卫（device-reference-marker-lost）更早拦下，同样零回调、不置 verified。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary))
                {
                    backend.SwapDeviceForSelfTest(new MockCompatDevice { UseOpenLib = true, IsOpen = true });
                    if (backend.BaselineBindingStillValid(out var reason) || reason != "device-instance-changed")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a same-type device swap must invalidate the baseline (reason={reason})");
                    var failure = CaptureFanApiFailure(backend.RestoreOem);
                    if (boundary.CallbackInvocationCount != 0 || backend.OemRestoreVerified)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a drifted device instance must be refused before any callback " +
                            $"(code={failure.Code ?? "<none>"} callbacks={boundary.CallbackInvocationCount} " +
                            $"verified={backend.OemRestoreVerified} message={failure.Message})");
                }

                // ⑥ 设备类型漂移：绑定判定必须为 device-type-changed。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out _))
                {
                    backend.SwapDeviceForSelfTest(new object());
                    if (backend.BaselineBindingStillValid(out var reason) || reason != "device-type-changed")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a device-type change must invalidate the baseline (reason={reason})");
                }

                // ⑦ Host 实例漂移：绑定判定必须为 host-instance-changed；生产入口拒绝且零回调。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary))
                {
                    backend.ForceStaleBaselineHostInstanceForSelfTest();
                    if (backend.BaselineBindingStillValid(out var reason) || reason != "host-instance-changed")
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a baseline from another host instance must be invalid (reason={reason})");
                    var failure = CaptureFanApiFailure(backend.RestoreOem);
                    if (failure.Code != "FAN_BASELINE_BINDING_LOST" || failure.Status != 409 ||
                        boundary.CallbackInvocationCount != 0 || backend.OemRestoreVerified)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a stale-host-instance baseline must be refused before any callback " +
                            $"(code={failure.Code ?? "<none>"} status={failure.Status} callbacks={boundary.CallbackInvocationCount} " +
                            $"verified={backend.OemRestoreVerified} message={failure.Message})");
                }

                // ⑧ 延迟 WMI 未返回：不得放行并发恢复——生产入口 504，回调零次，绝不置 verified。
                using (var backend = NewRestoreEntryHarness(
                           route, useOpenLib: true, deviceIsOpen: true, out _, out var boundary))
                {
                    backend.MarkOperationTimedOutForSelfTest();
                    var failure = CaptureFanApiFailure(backend.RestoreOem);
                    if (failure.Code != "HC_OPERATION_TIMEOUT" || failure.Status != 504 ||
                        boundary.CallbackInvocationCount != 0 || backend.OemRestoreVerified)
                        throw new InvalidOperationException(
                            $"FAN-936 {factory}: a pending timed-out HC operation must refuse concurrent restore " +
                            $"(code={failure.Code ?? "<none>"} status={failure.Status} callbacks={boundary.CallbackInvocationCount} " +
                            $"verified={backend.OemRestoreVerified} message={failure.Message})");
                }
            }
        }
        checks.Add("fan934-gpd-msi-production-restore-cycle-callback-count-and-negatives");
        checks.Add("fan936-baseline-binding-fail-closed-and-delayed-wmi-not-concurrent");

        // FAN-936 R2 §5 正例（非 MSI 路线）：ROG 与 GPD 都**不**继承 MSI 专属的基线绑定拒绝门。
        // 绑定判定仍如实报出失效原因（`control-cycle-changed`），但 `EnsureBaselineBindingForControl`
        // 必须保持原行为、不得抛 FAN_BASELINE_BINDING_LOST——否则就是把 MSI 专属门泄漏到其它路线。
        foreach (var nonMsiFactory in new[]
                 {
                     "HandheldCompanion.Devices.GPDWin5",
                     "HandheldCompanion.Devices.ROGAlly",
                 })
        {
            var nonMsiRoute = RealHcBackend.ResolveRouteForSelfTest(nonMsiFactory)
                ?? throw new InvalidOperationException($"FAN-936 R2: {nonMsiFactory} route is unregistered");
            if (nonMsiRoute.RestoreStrategy == FanRestoreStrategy.MsiHcDefaultRelease)
                throw new InvalidOperationException(
                    $"FAN-936 R2: {nonMsiFactory} must not be on the MSI structured-release route");
            using var backend = NewRestoreEntryHarness(
                nonMsiRoute, useOpenLib: true, deviceIsOpen: true, out _, out _);
            backend.ControlCycleId += 1;
            if (backend.BaselineBindingStillValid(out var reason) || reason != "control-cycle-changed")
                throw new InvalidOperationException(
                    $"FAN-936 R2 {nonMsiFactory}: the binding determination must still report " +
                    $"control-cycle-changed (reason={reason})");
            var failure = CaptureFanApiFailure(backend.EnsureBaselineBindingForControl);
            if (failure.Code is not null)
                throw new InvalidOperationException(
                    $"FAN-936 R2 {nonMsiFactory}: a non-MSI route must not inherit FAN_BASELINE_BINDING_LOST " +
                    $"(code={failure.Code} status={failure.Status} message={failure.Message})");
        }
        checks.Add("fan936-r2-baseline-binding-gate-is-msi-only");

        // FAN-936 R2 section 1：Close 必须绑定并消费**自己的最新释放结果**——先前一次成功的
        // restore 不得掩盖随后 Close 交还的 failed/unknown；Close 无绑定本次操作的收据时保持
        // not-attempted、绝不把正常退出降级。释放结算（`HcCloseReleaseSettlementForSelfTest`）
        // 与清理确认（`HcManagerCleanupConfirmed`）**分开记账**。
        {
            var msiCloseRoute = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.MSI.ClawA2VM")
                ?? throw new InvalidOperationException("FAN-936 R2: MSI route is unregistered");
            if (msiCloseRoute.RestoreStrategy != FanRestoreStrategy.MsiHcDefaultRelease)
                throw new InvalidOperationException(
                    "FAN-936 R2: the close-release settlement covers the MSI structured-release route only");

            // 正例：restore 成功 → Close 自身交还 ok ⇒ 结算 proven、保持 verified；交还例程被调用
            // 两次（restore + close），Close 的 cause 必须为 hc-close。
            using (var backend = NewRestoreEntryHarness(
                       msiCloseRoute, useOpenLib: true, deviceIsOpen: true, out var okMock, out _))
            {
                if (CaptureRestoreFailure(backend) != "<no-failure>" || !backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        $"FAN-936 R2: the MSI restore must verify before the close-settlement check " +
                        $"(verified={backend.OemRestoreVerified})");
                var closeFailure = CaptureCloseFailure(backend);
                var (settlement, detail) = backend.HcCloseReleaseSettlementForSelfTest;
                if (closeFailure != "<no-failure>" || settlement != "proven" ||
                    !backend.OemRestoreVerified ||
                    backend.OemReleaseActionKind != "proven-by-msi-structured-release" ||
                    okMock.ReleaseMsiFanControlInvocationCount != 2 || okMock.LastMsiFanReleaseCause != "hc-close")
                    throw new InvalidOperationException(
                        $"FAN-936 R2: a Close that hands back ok must settle close-release proven and keep verified " +
                        $"(failure={closeFailure} settlement={settlement} detail={detail} " +
                        $"verified={backend.OemRestoreVerified} kind={backend.OemReleaseActionKind} " +
                        $"releaseInvocations={okMock.ReleaseMsiFanControlInvocationCount} cause={okMock.LastMsiFanReleaseCause})");
            }

            // 反例①/②：restore 成功之后 Close 自身交还返回 failed/unknown ⇒ Close 结算必须转
            // failed/unknown 并**清除**先前成功态（旧成功不得掩盖新失败）；同时清理确认仍独立成立，
            // 证明释放结算与清理记账是两笔账。
            foreach (var (receiptStatus, expectedSettlement, expectedKind) in new[]
                     {
                         ("failed", "failed", "failed-release-action"),
                         ("unknown", "unknown", "unknown-release-action"),
                     })
            {
                using var backend = NewRestoreEntryHarness(
                    msiCloseRoute, useOpenLib: true, deviceIsOpen: true, out _, out var boundary);
                if (CaptureRestoreFailure(backend) != "<no-failure>" || !backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        "FAN-936 R2: the MSI restore must verify before the close-settlement negative");
                boundary.ReleaseReceiptStatus = receiptStatus;
                var closeFailure = CaptureCloseFailure(backend);
                var (settlement, detail) = backend.HcCloseReleaseSettlementForSelfTest;
                if (closeFailure != "<no-failure>" || settlement != expectedSettlement ||
                    backend.OemRestoreVerified || backend.OemReleaseActionKind != expectedKind ||
                    !backend.HcManagerCleanupConfirmed)
                    throw new InvalidOperationException(
                        $"FAN-936 R2: a Close release status={receiptStatus} must clear the earlier success and " +
                        $"settle {expectedSettlement} separately from cleanup " +
                        $"(failure={closeFailure} settlement={settlement} detail={detail} " +
                        $"verified={backend.OemRestoreVerified} kind={backend.OemReleaseActionKind} " +
                        $"cleanupConfirmed={backend.HcManagerCleanupConfirmed})");
            }

            // 反例③：Close 未做交还（无绑定本次操作的收据）⇒ 结算保持 not-attempted，先前成功态保留，
            // 绝不把一次正常退出降级。
            using (var backend = NewRestoreEntryHarness(
                       msiCloseRoute, useOpenLib: true, deviceIsOpen: true, out var noHandbackMock, out _))
            {
                if (CaptureRestoreFailure(backend) != "<no-failure>" || !backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        "FAN-936 R2: the MSI restore must verify before the no-handback close check");
                noHandbackMock.ClosePerformsMsiHandback = false;
                var closeFailure = CaptureCloseFailure(backend);
                var (settlement, detail) = backend.HcCloseReleaseSettlementForSelfTest;
                if (closeFailure != "<no-failure>" || settlement != "not-attempted" ||
                    !backend.OemRestoreVerified)
                    throw new InvalidOperationException(
                        $"FAN-936 R2: a Close with no bound hand-back must stay not-attempted and preserve the " +
                        $"earlier success (failure={closeFailure} settlement={settlement} detail={detail} " +
                        $"verified={backend.OemRestoreVerified})");
            }
        }
        checks.Add("fan936-r2-close-release-settled-against-its-own-latest-result");

        // ⑭-b ASUS 对照：同一条生产恢复入口，在**缺作用域 API** 的装配下必须停在 unknown，
        //      绝不因为"走了同一入口"就被洗成 compat 成功。
        {
            using var backend = NewRestoreEntryHarness(
                RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.ROGAlly")
                    ?? throw new InvalidOperationException("FAN-934: ROGAlly route is unregistered"),
                useOpenLib: true, deviceIsOpen: true, out _, out var boundary);
            var failure = CaptureRestoreFailure(backend);
            if (!failure.Contains("did not satisfy the route release contract", StringComparison.Ordinal) ||
                backend.OemRestoreVerified || backend.OemReleaseActionKind != "unknown-release-action" ||
                boundary.CallbackInvocationCount != 1)
                throw new InvalidOperationException(
                    $"FAN-934: an ASUS route without its scope API must stay unknown through the production entry " +
                    $"(failure={failure} kind={backend.OemReleaseActionKind} " +
                    $"verified={backend.OemRestoreVerified} callbacks={boundary.CallbackInvocationCount})");
        }
        checks.Add("fan934-asus-production-restore-without-scope-api-stays-unknown");

        // ⑮ FAN-934 R2 §3-B 第三条：ASUS 专属回执路线**修默认分支后不得误伤**——用生产唯一判定链
        //     （`DecideOperationEvidence` → `ClassifyReleaseAction` → `ReleaseActionKindName` →
        //     `IsOemReleaseSafe`）跑出正常(transported)/部分(partial)对照，以及空收据／收据 API 缺失／
        //     I/O 未知／混合失败／明确失败负例。ASUS 证据模式原样透传收据判定，不受 F1 默认分支修正影响。
        foreach (var c in new (string Kind, string Detail, bool ExplicitFailure, bool Unknown,
                     bool NoneTransported, int Receipts,
                     OemReleaseAction ExpectedAction, string ExpectedEvidence, bool ExpectedSafe)[]
                 {
                     ("transported", "all-fans-transported", false, false, false, 3,
                         OemReleaseAction.Proven, "transported", true),
                     ("partial", "mid-explicit-failure-but-cpu-gpu-transported", false, true, false, 3,
                         OemReleaseAction.Proven, "partial-channel-evidence-not-success", true),
                     ("no-receipts", "no-this-operation-fan-receipts", false, true, true, 0,
                         OemReleaseAction.Unknown, "unknown-not-verified-no-receipts", false),
                     ("receipt-api-fault", "asus-scope-api-absent", false, true, true, 0,
                         OemReleaseAction.Unknown, "unknown-not-verified-receipt-api-fault", false),
                     ("io-exception-unknown", "fan1:IoException(是否发起未知)", false, true, true, 1,
                         OemReleaseAction.Unknown, "unknown-not-verified", false),
                     ("mixed-failed-unknown", "fan1:InitiatedFailed+fan2:IoException", true, true, true, 2,
                         OemReleaseAction.Failed, "failed-write-not-established", false),
                     ("explicit-failure", "fan1:InitiatedFailed", true, false, true, 1,
                         OemReleaseAction.Failed, "failed-write-not-established", false),
                 })
        {
            var verdict = new RealHcBackend.AsusWriteVerdict(
                c.Kind, c.Detail, c.ExplicitFailure, c.Unknown, c.NoneTransported, c.Receipts);
            var settled = RealHcBackend.DecideOperationEvidence(
                FanEvidenceMode.AsusScopeReceipts, "oem-restore", callbackReturned: true,
                compatPreconditionsOk: false, "n/a", verdict);
            var action = FanHostEngine.ClassifyReleaseAction(settled.Kind);
            var actionName = FanHostEngine.ReleaseActionKindName(action);
            var evidenceName = RealHcBackend.WriteEvidenceName(verdict);
            // 闭环：分类器导出的动作串经消费端统一入口重解析后，仍给出一致的释放安全判据。
            var safe = FanHostEngine.IsOemReleaseSafeForSelfTest(true, actionName);
            // 诚实对照：无写历史 ⇒ 释放不适用，任何收据口径都不得被读成"释放失败"。
            var safeWithoutWriteHistory = FanHostEngine.IsOemReleaseSafeForSelfTest(false, actionName);
            if (settled.Kind != c.Kind || action != c.ExpectedAction || evidenceName != c.ExpectedEvidence ||
                safe != c.ExpectedSafe || !safeWithoutWriteHistory)
                throw new InvalidOperationException(
                    $"FAN-934: ASUS {c.Kind} must settle as {c.ExpectedAction} (evidence={c.ExpectedEvidence}, " +
                    $"safe={c.ExpectedSafe}) via the single classifier chain " +
                    $"(kind={settled.Kind} action={action}/{actionName} evidence={evidenceName} safe={safe})");
        }
        checks.Add("fan934-asus-scope-receipt-chain-normal-partial-and-failure-negatives");

        // ⑯ FAN-934 R2 §3-B 第一条：以发布 DLL 反例为修前基线，修后跑**完整**判定链
        //     `Settle → ClassifyReleaseAction → ReleaseActionKindName → IsOemReleaseSafe` 的承重门。
        //     未登记／缺操作作用域／无收据／回调未返回／有写历史必须拒绝；
        //     已知兼容成功／ASUS 正常／无写历史正常关闭仍通过。
        {
            var noScopeVerdict = new RealHcBackend.AsusWriteVerdict(
                "receipt-api-fault", "asus-scope-api-absent", false, true, true, 0);
            var normalVerdict = new RealHcBackend.AsusWriteVerdict(
                "transported", "all-fans-transported", false, false, false, 3);
            var placeholder = new RealHcBackend.AsusWriteVerdict("unsupported", "n/a", false, false, false, 0);

            foreach (var c in new (string Case, string Kind, bool WriteHistory, bool ExpectedSafe)[]
                     {
                         ("unregistered-route", "unregistered-route-no-scope", true, false),
                         ("missing-scope-api", "receipt-api-fault", true, false),
                         ("no-receipts", "no-receipts", true, false),
                         ("callback-not-returned", "compat-route-callback-not-returned", true, false),
                         ("compat-success", "compat-route-without-scope", true, true),
                         ("asus-normal", "transported", true, true),
                         ("no-write-history-close", "unregistered-route-no-scope", false, true),
                     })
            {
                var action = FanHostEngine.ClassifyReleaseAction(c.Kind);
                var actionName = FanHostEngine.ReleaseActionKindName(action);
                var safe = FanHostEngine.IsOemReleaseSafeForSelfTest(c.WriteHistory, actionName);
                if (safe != c.ExpectedSafe)
                    throw new InvalidOperationException(
                        $"FAN-934: baseline case {c.Case} must be safe={c.ExpectedSafe} through the full chain " +
                        $"(kind={c.Kind} action={actionName} writeHistory={c.WriteHistory} safe={safe})");
            }

            // 反向核对：这些 kind 必须**由生产结算函数本身**产出，不是手填分类输入。
            if (RealHcBackend.DecideOperationEvidence(
                    FanEvidenceMode.UnsupportedNoScope, "oem-restore", callbackReturned: false,
                    compatPreconditionsOk: false, "n/a", placeholder).Kind != "unregistered-route-no-scope" ||
                RealHcBackend.DecideOperationEvidence(
                    FanEvidenceMode.AsusScopeReceipts, "oem-restore", callbackReturned: true,
                    compatPreconditionsOk: false, "n/a", noScopeVerdict).Kind != "receipt-api-fault" ||
                RealHcBackend.DecideOperationEvidence(
                    FanEvidenceMode.AsusScopeReceipts, "oem-restore", callbackReturned: true,
                    compatPreconditionsOk: false, "n/a", normalVerdict).Kind != "transported" ||
                RealHcBackend.DecideOperationEvidence(
                    FanEvidenceMode.CompatCallbackNoScope, "oem-restore", callbackReturned: false,
                    compatPreconditionsOk: true, "compat-ok", placeholder).Kind != "compat-route-callback-not-returned" ||
                RealHcBackend.DecideOperationEvidence(
                    FanEvidenceMode.CompatCallbackNoScope, "oem-restore", callbackReturned: true,
                    compatPreconditionsOk: true, "compat-ok", placeholder).Kind != "compat-route-without-scope")
                throw new InvalidOperationException(
                    "FAN-934: the published-DLL baseline kinds must be produced by the production settle function itself");
        }
        checks.Add("fan934-published-dll-baseline-full-chain-reject-and-pass");

        // ⑰ FAN-934 R2 §3-B 第七条：其他合同族按源码差异**参数化**覆盖——GPD WinMini 与 SteamDeck（Valve）
        //     虽同标 `RestoreStrategy.None`，恢复方法与前提不同（WinMini 依赖 OpenLib 句柄、Valve 需设备
        //     已支持），必须各自验证，不得被"同一个 None 组"一刀切。
        {
            using var backend = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
            foreach (var name in new[]
                     {
                         "HandheldCompanion.Devices.GPDWinMini", "HandheldCompanion.Devices.GPDWinMini_7640U",
                         "HandheldCompanion.Devices.GPDWinMini_8840U", "HandheldCompanion.Devices.GPDWinMini_HX370",
                     })
            {
                var mini = RealHcBackend.ResolveRouteForSelfTest(name)
                    ?? throw new InvalidOperationException($"FAN-934: {name} route is unregistered");
                if (mini.RestoreStrategy != FanRestoreStrategy.None ||
                    mini.Precondition != FanRoutePrecondition.OpenLibHandleOpen)
                    throw new InvalidOperationException(
                        $"FAN-934: {name} must declare None + OpenLibHandleOpen " +
                        $"(got {mini.RestoreStrategy}/{mini.Precondition})");
                var withOpenLib = DrivePreconditionChain(backend, mini, useOpenLib: true, deviceIsOpen: true,
                    deviceIsSupported: true, backendOpen: true, callbackReturned: true);
                var withoutOpenLib = DrivePreconditionChain(backend, mini, useOpenLib: false, deviceIsOpen: true,
                    deviceIsSupported: true, backendOpen: true, callbackReturned: true);
                if (withOpenLib.Kind != "compat-route-without-scope" || !withOpenLib.Safe ||
                    withoutOpenLib.Kind != "compat-route-precondition-unsatisfied" || withoutOpenLib.Safe)
                    throw new InvalidOperationException(
                        $"FAN-934: {name} must settle only with an open OpenLib handle " +
                        $"(withOpenLib={withOpenLib.Kind}/{withOpenLib.Safe} " +
                        $"withoutOpenLib={withoutOpenLib.Kind}/{withoutOpenLib.Safe})");
            }
            var valve = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.SteamDeck")
                ?? throw new InvalidOperationException("FAN-934: SteamDeck route is unregistered");
            // 与 GPD WinMini 同标 None 但前提不同：不得把 OpenLib 要求一刀切到 Valve（反之亦然）。
            if (valve.RestoreStrategy != FanRestoreStrategy.None ||
                valve.Precondition != FanRoutePrecondition.DeviceOpenAndSupported)
                throw new InvalidOperationException(
                    $"FAN-934: SteamDeck shares strategy None with GPD WinMini but must keep its own precondition " +
                    $"(got {valve.RestoreStrategy}/{valve.Precondition})");
        }
        checks.Add("fan934-none-family-gpd-mini-and-valve-verified-separately");

        return checks;
    }

    // ======================================================================
    // HC-SLIM-01 R3 §4.2：backend provider 风扇写入门（无硬件离线）。
    //
    // 复用最小承重检查（同输入曲线/默认表、CPU/GPU/Mid 序列、完整/短/null/throw/
    // 未发起/partial 收据及当前 scope、关闭/恢复中慢操作的取消与迟到结果），仅补
    // provider 选路与 backend 写入链的改动缺口。不安装 HC 边界（backend 路线不经
    // HC 回调），不使用真实 ACPI/EC/WMI：OS 边界由脚本化传输替身承担。
    // ======================================================================

    /** 脚本化 ACPI 传输每一步的结果（默认 SuccessComplete）。 */
    private enum AsusScriptStep { SuccessComplete, SuccessShort, Fail, Throw }

    /** 一次脚本化 DeviceIoControl 的实际入参形状（供断言封包/曲线/设备 ID 序列）。 */
    private sealed class ScriptedAsusAcpiCall
    {
        public uint IoControlCode { get; init; }
        public byte[] InBuffer { get; init; } = Array.Empty<byte>();
        public int OutCapacity { get; init; }
    }

    /**
     * 无硬件 ASUS ACPI 传输替身：脚本化每次 DeviceIoControl 的结果，并如实记录控制码/
     * 入包/输出容量。不改动叶组件的封包、曲线变换与钳制逻辑（它们仍走生产代码）。
     */
    private sealed class ScriptedAsusAcpiTransport : YeManFanBackend.Asus.IAsusAcpiTransport
    {
        private static readonly IntPtr ScriptedHandle = new(0x5150);
        private readonly Queue<AsusScriptStep> script = new();
        // HC-SLIM-01 R4 §4 H2：模拟"睡眠/关闭/驱动后旧句柄失效"——叶组件仍持有旧的
        // 数值句柄，但传输层不再认它有效；下一次 TryOpen 成功会取回新的有效句柄。
        private bool staleHandle;

        public bool OpenSucceeds { get; init; } = true;
        public int OpenCount { get; private set; }
        public int CloseCount { get; private set; }
        public List<ScriptedAsusAcpiCall> ControlCalls { get; } = new();

        public void Enqueue(params AsusScriptStep[] steps)
        {
            foreach (var step in steps) script.Enqueue(step);
        }

        /** 使当前句柄失效（不改变叶组件持有的数值），复现旧句柄被吞掉后不可用。 */
        public void InvalidateHandle() => staleHandle = true;

        public bool IsHandleValid(IntPtr handle) => !staleHandle && handle == ScriptedHandle;

        public bool TryOpen(out IntPtr handle, out int win32Error)
        {
            OpenCount++;
            if (OpenSucceeds) { handle = ScriptedHandle; win32Error = 0; staleHandle = false; return true; }
            handle = IntPtr.Zero; win32Error = 5; return false;
        }

        public bool Control(
            IntPtr handle, uint ioControlCode, byte[] inBuffer, byte[] outBuffer,
            out uint bytesReturned, out int win32Error)
        {
            ControlCalls.Add(new ScriptedAsusAcpiCall
            {
                IoControlCode = ioControlCode,
                InBuffer = (byte[])inBuffer.Clone(),
                OutCapacity = outBuffer.Length,
            });
            if (script.Count == 0)
                throw new InvalidOperationException("scripted ASUS transport has no step for this call");
            var step = script.Dequeue();
            switch (step)
            {
                case AsusScriptStep.Throw:
                    throw new IOException("scripted-asus-io");
                case AsusScriptStep.Fail:
                    Array.Clear(outBuffer);
                    bytesReturned = 0; win32Error = 31; return false;
                case AsusScriptStep.SuccessShort:
                    Array.Clear(outBuffer);
                    bytesReturned = 8; win32Error = 0; return true;
                default:
                    Array.Clear(outBuffer);
                    bytesReturned = (uint)outBuffer.Length; win32Error = 0; return true;
            }
        }

        public void Close(IntPtr handle) => CloseCount++;
    }

    /** 固定 16 字节曲线（占空 ≤99，避开叶组件 0..99 钳制，便于逐字比对写序）。 */
    private static readonly byte[] FixedAsusCurve =
        { 20, 30, 40, 50, 60, 70, 80, 90, 10, 20, 30, 40, 50, 60, 70, 80 };

    private static object? ReadProp(object? target, string name) =>
        target?.GetType().GetProperty(name, BindingFlags.Public | BindingFlags.Instance)?.GetValue(target);

    private static RealHcBackend NewFanBackendForSelfTest(string? provider = null) =>
        new(HostOptions.Parse(provider is null ? Array.Empty<string>() : new[] { "--fan-provider", provider }));

    private static FanRoute RequireAsusRoute()
    {
        var route = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.ROGAlly")
            ?? throw new InvalidOperationException("HC-SLIM-01: ROGAlly route is unregistered");
        if (route.RestoreStrategy != FanRestoreStrategy.AsusAcpiCurves ||
            route.Evidence != FanEvidenceMode.AsusScopeReceipts)
            throw new InvalidOperationException(
                $"HC-SLIM-01: ROGAlly route must be ASUS ACPI curves + scope receipts " +
                $"(got {route.RestoreStrategy}/{route.Evidence})");
        return route;
    }

    private static object NewFanProfile(double[] duties, string mode) =>
        new RealHcBackend.SelfTestHcProfile(new RealHcBackend.SelfTestHcFanProfile
        {
            fanSpeeds = (double[])duties.Clone(),
            fanMode = mode,
        });

    /** 归还 ACPI 句柄并复位注入（诊断 sink/全局收据）——每个门块 finally 必须调用。 */
    private static void ResetAsusTransportForSelfTest()
    {
        YeManFanBackend.Asus.AsusACPI.Close();
        YeManFanBackend.Asus.AsusACPI.SetTransportForInjection(null);
        YeManFanBackend.Asus.AsusACPI.DiagnosticSink = null;
        YeManFanBackend.Asus.AsusAcpiObservations.ClearReceipts();
    }

    /** 建 backend provider 会话（ROG 路线）并把叶组件 ACPI 传输接给脚本替身。 */
    private static RealHcBackend NewAsusBackendSessionForSelfTest(ScriptedAsusAcpiTransport scripted)
    {
        var backend = NewFanBackendForSelfTest("backend");
        var mock = new MockCompatDevice { UseOpenLib = true, IsOpen = true, IsSupported = true };
        backend.InstallSelfTestRouteSessionForSelfTest(mock, RequireAsusRoute(), backendOpen: true);
        YeManFanBackend.Asus.AsusACPI.SetTransportForInjection(scripted);
        return backend;
    }

    private static void RequireBytesEqual(byte[] actual, byte[] expected, string label)
    {
        if (!actual.SequenceEqual(expected))
            throw new InvalidOperationException(
                $"{label}: expected [{string.Join(",", expected.Select(b => b.ToString("X2")))}] " +
                $"got [{string.Join(",", actual.Select(b => b.ToString("X2")))}]");
    }

    private static void RequireVerdict(string expected, string actual, int calls, int expectedCalls, string label)
    {
        if (actual != expected)
            throw new InvalidOperationException($"{label}: expected verdict {expected} got {actual}");
        if (calls != expectedCalls)
            throw new InvalidOperationException($"{label}: expected {expectedCalls} transport calls got {calls}");
    }

    /**
     * 收据工况矩阵的一案：开作用域 → 可选开句柄 → 可选叶写（CPU/GPU/Mid 三写）→ 结算。
     * 全程只用脚本化传输，返回（判定 kind, 实际传输调用次数）。
     */
    private static (string Kind, int Calls) RunAsusVerdictCase(
        bool openBackend, bool leafWrite, params AsusScriptStep[] script)
    {
        var scripted = new ScriptedAsusAcpiTransport();
        scripted.Enqueue(script);
        var backend = NewAsusBackendSessionForSelfTest(scripted);
        object? scope = null;
        try
        {
            var handle = backend.BeginAsusWriteScope("enable-curve");
            scope = handle?.Scope;
            if (openBackend) YeManFanBackend.Asus.AsusACPI.Open();
            if (leafWrite)
                YeManFanBackend.Asus.AsusFanCurveWriter.ApplySoftwareCurve((byte[])FixedAsusCurve.Clone());
            var verdict = backend.SettleOperationEvidence(handle, "enable-curve", true);
            return (verdict.Kind, scripted.ControlCalls.Count);
        }
        finally
        {
            (scope as IDisposable)?.Dispose();
            ResetAsusTransportForSelfTest();
            backend.Dispose();
        }
    }

    internal static IReadOnlyList<string> RunFanBackendProviderSelfTest()
    {
        var checks = new List<string>();

        // 门 A：provider 内部选路（非法值 fail-closed；backend 只对 ASUS 路线生效；缺省保持 HC）。
        {
            try
            {
                using var invalid = NewFanBackendForSelfTest("bogus");
                throw new InvalidOperationException("HC-SLIM-01: illegal --fan-provider must fail closed");
            }
            catch (ArgumentException ex) when (ex.Message.Contains("Unsupported --fan-provider", StringComparison.Ordinal))
            {
                // 预期：非法 provider 由构造函数 fail-closed 拒绝（不静默回退第二 writer）。
            }
            checks.Add("hcslim01-backend-provider-illegal-value-fails-closed");
        }
        {
            using var backend = NewFanBackendForSelfTest("backend");
            backend.routeOverrideForSelfTest = RequireAsusRoute();
            if (backend.FanDispatchProviderNameForSelfTest != "backend" || !backend.UsesBackendFanWriterForSelfTest)
                throw new InvalidOperationException(
                    $"HC-SLIM-01: ROG route under --fan-provider backend must select backend " +
                    $"(provider={backend.FanDispatchProviderNameForSelfTest} writer={backend.UsesBackendFanWriterForSelfTest})");
            var gpd = RealHcBackend.ResolveRouteForSelfTest("HandheldCompanion.Devices.GPDWin5")
                ?? throw new InvalidOperationException("HC-SLIM-01: GPDWin5 route is unregistered");
            backend.routeOverrideForSelfTest = gpd;
            if (backend.FanDispatchProviderNameForSelfTest != "HC" || backend.UsesBackendFanWriterForSelfTest)
                throw new InvalidOperationException(
                    $"HC-SLIM-01: non-ASUS route must stay on the HC callback writer " +
                    $"(provider={backend.FanDispatchProviderNameForSelfTest} writer={backend.UsesBackendFanWriterForSelfTest})");
            checks.Add("hcslim01-backend-provider-binds-to-asus-route-only");
        }
        {
            using var backend = NewFanBackendForSelfTest();
            backend.routeOverrideForSelfTest = RequireAsusRoute();
            if (backend.FanDispatchProviderNameForSelfTest != "HC" || backend.UsesBackendFanWriterForSelfTest)
                throw new InvalidOperationException(
                    $"HC-SLIM-01: default provider must keep the HC writer " +
                    $"(provider={backend.FanDispatchProviderNameForSelfTest} writer={backend.UsesBackendFanWriterForSelfTest})");
            checks.Add("hcslim01-default-provider-keeps-hc-writer");
        }

        // 门 B：曲线变换与默认表等价（纯函数，逐字镜像 ROGAlly）。
        {
            RequireBytesEqual(
                YeManFanBackend.Asus.AsusFanCurveWriter.ToAsusCurve(
                    new double[] { 0, 0, 10, 20, 30, 40, 50, 60, 70, 60, 50 }),
                new byte[] { 20, 30, 40, 50, 60, 70, 80, 90, 10, 20, 30, 40, 50, 60, 70, 70 },
                "HC-SLIM-01 B1");
            RequireBytesEqual(
                YeManFanBackend.Asus.AsusFanCurveWriter.ToAsusCurve(
                    new double[] { 0, 0, -5, 150, 0, 0, 0, 0, 0, 0, 0 }),
                new byte[] { 20, 30, 40, 50, 60, 70, 80, 90, 0, 100, 100, 100, 100, 100, 100, 100 },
                "HC-SLIM-01 B2");
            var defCpu = YeManFanBackend.Asus.AsusFanCurveWriter.DefaultCpuCurve;
            var defGpu = YeManFanBackend.Asus.AsusFanCurveWriter.DefaultGpuCurve;
            if (!YeManFanBackend.Asus.AsusFanCurveWriter.ToAsusCurve(new double[10]).SequenceEqual(defCpu) ||
                !YeManFanBackend.Asus.AsusFanCurveWriter.ToAsusCurve(null).SequenceEqual(defCpu))
                throw new InvalidOperationException("HC-SLIM-01 B3: non-11-point input must hand back the default CPU table");
            RequireBytesEqual(defCpu,
                new byte[] { 0x3A, 0x3D, 0x40, 0x44, 0x48, 0x4D, 0x51, 0x62, 0x08, 0x11, 0x16, 0x1A, 0x22, 0x29, 0x30, 0x45 },
                "HC-SLIM-01 B4-cpu");
            RequireBytesEqual(defGpu,
                new byte[] { 0x3A, 0x3D, 0x40, 0x44, 0x48, 0x4D, 0x51, 0x62, 0x0C, 0x16, 0x1D, 0x1F, 0x26, 0x2D, 0x34, 0x4A },
                "HC-SLIM-01 B4-gpu");
            checks.Add("hcslim01-asus-curve-and-default-table-equivalence");
        }

        // 门 C：Software 生产链——真实 ApplyPowerProfile → 叶组件 CPU/GPU/Mid 三写，
        //        逐字校验封包形状（控制码/入包/输出容量/设备 ID 序列/曲线字节与 0..99 钳制）。
        {
            var scripted = new ScriptedAsusAcpiTransport();
            scripted.Enqueue(AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete);
            var backend = NewAsusBackendSessionForSelfTest(scripted);
            var diagnostics = new List<(string Name, object? Payload)>();
            backend.Diagnostic = (name, payload) => diagnostics.Add((name, payload));
            try
            {
                var handle = backend.BeginAsusWriteScope("enable-curve");
                backend.ApplyPowerProfileForSelfTest(
                    NewFanProfile(new double[] { 0, 0, 10, 20, 30, 40, 50, 60, 80, 100, 0 }, "Software"),
                    "Background");
                var verdict = backend.SettleOperationEvidence(handle, "enable-curve", true);
                if (verdict.Kind != "transported")
                    throw new InvalidOperationException($"HC-SLIM-01 C: expected transported got {verdict.Kind} ({verdict.Detail})");
                if (scripted.ControlCalls.Count != 3)
                    throw new InvalidOperationException($"HC-SLIM-01 C: expected 3 transport calls got {scripted.ControlCalls.Count}");
                var expectedCurve = new byte[] { 20, 30, 40, 50, 60, 70, 80, 90, 10, 20, 30, 40, 50, 60, 80, 99 };
                var expectedDeviceIds = new[]
                {
                    YeManFanBackend.Asus.AsusACPI.DevsCPUFanCurve,
                    YeManFanBackend.Asus.AsusACPI.DevsGPUFanCurve,
                    YeManFanBackend.Asus.AsusACPI.DevsMidFanCurve,
                };
                for (var i = 0; i < 3; i++)
                {
                    var call = scripted.ControlCalls[i];
                    if (call.IoControlCode != 0x0022240Cu)
                        throw new InvalidOperationException($"HC-SLIM-01 C[{i}]: ioctl 0x{call.IoControlCode:X8} != 0x0022240C");
                    if (call.OutCapacity != 16)
                        throw new InvalidOperationException($"HC-SLIM-01 C[{i}]: out capacity {call.OutCapacity} != 16");
                    if (call.InBuffer.Length != 28)
                        throw new InvalidOperationException($"HC-SLIM-01 C[{i}]: in buffer {call.InBuffer.Length} != 28");
                    if (BitConverter.ToUInt32(call.InBuffer, 0) != 0x53564544u)
                        throw new InvalidOperationException($"HC-SLIM-01 C[{i}]: method id must be DEVS");
                    if (BitConverter.ToUInt32(call.InBuffer, 4) != 20u)
                        throw new InvalidOperationException($"HC-SLIM-01 C[{i}]: args length must be 20");
                    if (BitConverter.ToUInt32(call.InBuffer, 8) != expectedDeviceIds[i])
                        throw new InvalidOperationException(
                            $"HC-SLIM-01 C[{i}]: device id 0x{BitConverter.ToUInt32(call.InBuffer, 8):X8} != 0x{expectedDeviceIds[i]:X8}");
                    RequireBytesEqual(call.InBuffer[12..28], expectedCurve, $"HC-SLIM-01 C[{i}] curve");
                }
                if (!YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException("HC-SLIM-01 C: ACPI handle must be open after the write chain");
                var frozen = diagnostics.Where(d => d.Name == "fan.provider.frozen").ToList();
                if (frozen.Count != 1)
                    throw new InvalidOperationException($"HC-SLIM-01 C: expected one fan.provider.frozen diagnostic got {frozen.Count}");
                if (Convert.ToString(ReadProp(frozen[0].Payload, "provider")) != "backend" ||
                    Convert.ToString(ReadProp(frozen[0].Payload, "component")) != "YeManFanBackend/1.0.0")
                    throw new InvalidOperationException("HC-SLIM-01 C: frozen provider/component identity mismatch");
                if (!diagnostics.Any(d => d.Name == "hc.fan-dispatch.begin") ||
                    !diagnostics.Any(d => d.Name == "hc.fan-dispatch.callback-returned"))
                    throw new InvalidOperationException("HC-SLIM-01 C: dispatch begin/returned diagnostics missing");
                checks.Add("hcslim01-backend-software-write-order-and-wire-shape");
            }
            finally
            {
                ResetAsusTransportForSelfTest();
                backend.Dispose();
            }
            if (scripted.OpenCount != 1 || scripted.CloseCount != 1)
                throw new InvalidOperationException(
                    $"HC-SLIM-01 C: expected exactly one open/close got open={scripted.OpenCount} close={scripted.CloseCount}");
        }

        // 门 D：Hardware 生产链——交还 ASUS 默认表（CPU/GPU/Mid = 默认CPU/默认GPU/默认CPU）。
        {
            var scripted = new ScriptedAsusAcpiTransport();
            scripted.Enqueue(AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete);
            var backend = NewAsusBackendSessionForSelfTest(scripted);
            try
            {
                var handle = backend.BeginAsusWriteScope("enable-curve");
                backend.ApplyPowerProfileForSelfTest(NewFanProfile(Array.Empty<double>(), "Hardware"), "Background");
                var verdict = backend.SettleOperationEvidence(handle, "enable-curve", true);
                if (verdict.Kind != "transported")
                    throw new InvalidOperationException($"HC-SLIM-01 D: expected transported got {verdict.Kind} ({verdict.Detail})");
                if (scripted.ControlCalls.Count != 3)
                    throw new InvalidOperationException($"HC-SLIM-01 D: expected 3 transport calls got {scripted.ControlCalls.Count}");
                var expected = new[]
                {
                    YeManFanBackend.Asus.AsusFanCurveWriter.DefaultCpuCurve,
                    YeManFanBackend.Asus.AsusFanCurveWriter.DefaultGpuCurve,
                    YeManFanBackend.Asus.AsusFanCurveWriter.DefaultCpuCurve,
                };
                for (var i = 0; i < 3; i++)
                    RequireBytesEqual(scripted.ControlCalls[i].InBuffer[12..28], expected[i], $"HC-SLIM-01 D[{i}] default curve");
                checks.Add("hcslim01-backend-hardware-default-table-handback");
            }
            finally
            {
                ResetAsusTransportForSelfTest();
                backend.Dispose();
            }
        }

        // 门 E：收据工况矩阵（完整/短/partial/throw/mixed/未发起/无收据）与当前 scope 归属。
        {
            var (kind, calls) = RunAsusVerdictCase(true, true, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete);
            RequireVerdict("transported", kind, calls, 3, "HC-SLIM-01 E-complete");
            checks.Add("hcslim01-backend-receipts-complete-transported");
        }
        {
            var (kind, calls) = RunAsusVerdictCase(true, true, AsusScriptStep.SuccessShort, AsusScriptStep.SuccessShort, AsusScriptStep.SuccessShort);
            RequireVerdict("transported", kind, calls, 3, "HC-SLIM-01 E-short");
            checks.Add("hcslim01-backend-receipts-short-still-transported");
        }
        {
            var (kind, calls) = RunAsusVerdictCase(true, true, AsusScriptStep.SuccessComplete, AsusScriptStep.Fail, AsusScriptStep.Fail);
            RequireVerdict("partial", kind, calls, 3, "HC-SLIM-01 E-partial");
            checks.Add("hcslim01-backend-receipts-partial-not-success");
        }
        {
            var (kind, calls) = RunAsusVerdictCase(true, true, AsusScriptStep.Throw, AsusScriptStep.Throw, AsusScriptStep.Throw);
            RequireVerdict("io-exception-unknown", kind, calls, 3, "HC-SLIM-01 E-throw");
            checks.Add("hcslim01-backend-receipts-throw-stays-unknown");
        }
        {
            var (kind, calls) = RunAsusVerdictCase(true, true, AsusScriptStep.Fail, AsusScriptStep.Throw, AsusScriptStep.Fail);
            RequireVerdict("mixed-failed-unknown", kind, calls, 3, "HC-SLIM-01 E-mixed");
            checks.Add("hcslim01-backend-receipts-mixed-failed-unknown");
        }
        {
            var (kind, calls) = RunAsusVerdictCase(false, true);
            RequireVerdict("explicit-failure", kind, calls, 0, "HC-SLIM-01 E-not-initiated");
            checks.Add("hcslim01-backend-receipts-not-initiated-explicit-failure");
        }
        {
            var (kind, calls) = RunAsusVerdictCase(false, false);
            RequireVerdict("no-receipts", kind, calls, 0, "HC-SLIM-01 E-empty-scope");
            checks.Add("hcslim01-backend-empty-scope-no-receipts");
        }

        // 门 F：句柄打不开 ⇒ fail-closed（不静默降级到 HC 第二 writer；零控制调用）。
        {
            var scripted = new ScriptedAsusAcpiTransport { OpenSucceeds = false };
            var backend = NewAsusBackendSessionForSelfTest(scripted);
            var handle = backend.BeginAsusWriteScope("enable-curve");
            try
            {
                var failedClosed = false;
                try
                {
                    backend.ApplyPowerProfileForSelfTest(
                        NewFanProfile(new double[] { 0, 0, 10, 20, 30, 40, 50, 60, 80, 100, 0 }, "Software"),
                        "Background");
                }
                catch (InvalidOperationException ex) when (ex.Message.Contains("FAN_BACKEND_ASUS_ACPI_OPEN_FAILED", StringComparison.Ordinal))
                {
                    failedClosed = true;
                }
                if (!failedClosed)
                    throw new InvalidOperationException("HC-SLIM-01 F: an openable-less ACPI handle must fail closed");
                if (scripted.ControlCalls.Count != 0)
                    throw new InvalidOperationException("HC-SLIM-01 F: fail-closed must issue zero control calls");
                if (YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException("HC-SLIM-01 F: handle must not be considered open");
                checks.Add("hcslim01-backend-open-failure-fails-closed");
            }
            finally
            {
                // 未结算的作用域必须归还，避免 AsyncLocal 作用域泄漏到后续门。
                (handle?.Scope as IDisposable)?.Dispose();
                ResetAsusTransportForSelfTest();
                backend.Dispose();
            }
            if (scripted.OpenCount != 1 || scripted.CloseCount != 0)
                throw new InvalidOperationException(
                    $"HC-SLIM-01 F: expected one open attempt and no close got open={scripted.OpenCount} close={scripted.CloseCount}");
        }

        // 门 G1：作用域归属——第二次空作用域不得消费上一次操作的收据。
        {
            var scripted = new ScriptedAsusAcpiTransport();
            scripted.Enqueue(AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete);
            var backend = NewAsusBackendSessionForSelfTest(scripted);
            try
            {
                var first = backend.BeginAsusWriteScope("enable-curve");
                YeManFanBackend.Asus.AsusACPI.Open();
                YeManFanBackend.Asus.AsusFanCurveWriter.ApplySoftwareCurve((byte[])FixedAsusCurve.Clone());
                var firstVerdict = backend.SettleOperationEvidence(first, "enable-curve", true);
                if (firstVerdict.Kind != "transported")
                    throw new InvalidOperationException($"HC-SLIM-01 G1: first scope expected transported got {firstVerdict.Kind}");
                var second = backend.BeginAsusWriteScope("enable-curve");
                var secondVerdict = backend.SettleOperationEvidence(second, "enable-curve", true);
                if (secondVerdict.Kind != "no-receipts")
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 G1: an empty scope must not consume the previous operation's receipts got {secondVerdict.Kind}");
                if (YeManFanBackend.Asus.AsusAcpiObservations.PeekReceipts().Length < 3)
                    throw new InvalidOperationException("HC-SLIM-01 G1: historical receipts must remain visible in the global queue");
                checks.Add("hcslim01-backend-scope-attribution-isolation");
            }
            finally
            {
                ResetAsusTransportForSelfTest();
                backend.Dispose();
            }
        }

        // 门 G2：作用域关闭后的迟到收据单独留存（不混入本操作判定，不静默丢弃）。
        {
            var scripted = new ScriptedAsusAcpiTransport();
            scripted.Enqueue(AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete);
            var backend = NewAsusBackendSessionForSelfTest(scripted);
            try
            {
                var handle = backend.BeginAsusWriteScope("late");
                var lateScope = (YeManFanBackend.Asus.AsusAcpiCallScope?)handle?.Scope
                    ?? throw new InvalidOperationException("HC-SLIM-01 G2: expected a concrete ASUS call scope");
                YeManFanBackend.Asus.AsusACPI.Open();
                using var go = new ManualResetEventSlim(false);
                using var done = new ManualResetEventSlim(false);
                var worker = Task.Run(() =>
                {
                    go.Wait(5000);
                    YeManFanBackend.Asus.AsusFanCurveWriter.ApplySoftwareCurve((byte[])FixedAsusCurve.Clone());
                    done.Set();
                });
                lateScope.Dispose();
                go.Set();
                if (!done.Wait(5000))
                    throw new InvalidOperationException("HC-SLIM-01 G2: late writer did not finish");
                worker.GetAwaiter().GetResult();
                if (lateScope.LateReceiptCount != 3 || lateScope.Count != 0)
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 G2: late receipts must be kept separately (late={lateScope.LateReceiptCount} in-scope={lateScope.Count})");
                checks.Add("hcslim01-backend-late-receipts-after-scope-close");
            }
            finally
            {
                ResetAsusTransportForSelfTest();
                backend.Dispose();
            }
        }

        // 门 H1（R4 §4）：正常关闭后重开并继续调节——leaf 自有 ACPI 句柄必须随既有 Close
        // 边界归还（CloseCount=1、IsOpen=false），重开同一会话后必须按真实句柄状态重新打开
        // 并继续三写。旧接线只关 HC 自己的句柄，leaf 句柄会残留（CloseCount=0、IsOpen=true）。
        {
            var scripted = new ScriptedAsusAcpiTransport();
            scripted.Enqueue(
                AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete,
                AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete);
            var route = RequireAsusRoute();
            var mock = new MockCompatDevice { UseOpenLib = true, IsOpen = true, IsSupported = true };
            var backend = new RealHcBackend(HostOptions.Parse(new[] { "--fan-provider", "backend" }));
            backend.InstallSelfTestRouteSessionForSelfTest(mock, route, backendOpen: true);
            YeManFanBackend.Asus.AsusACPI.SetTransportForInjection(scripted);
            try
            {
                // 首段：开句柄 → CPU/GPU/Mid 三写。
                var first = backend.BeginAsusWriteScope("enable-curve");
                backend.ApplyPowerProfileForSelfTest(
                    NewFanProfile(new double[] { 0, 0, 10, 20, 30, 40, 50, 60, 80, 100, 0 }, "Software"),
                    "Background");
                var firstVerdict = backend.SettleOperationEvidence(first, "enable-curve", true);
                if (firstVerdict.Kind != "transported")
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H1: first scope expected transported got {firstVerdict.Kind}");
                if (scripted.ControlCalls.Count != 3 || scripted.OpenCount != 1 ||
                    !YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H1: first segment must open once and write three " +
                        $"(calls={scripted.ControlCalls.Count} open={scripted.OpenCount} " +
                        $"isOpen={YeManFanBackend.Asus.AsusACPI.IsOpen})");

                // 关闭边界：装唯一 HC 边界让离线 ManagerFactory 观测闭环，Close 后 leaf 自有句柄
                // 必须被归还。边界只在 Close 期间装载——否则 ApplyPowerProfile 会改走 HC 回调而不是
                // backend 写入链。
                var closeBoundary = new RealHcBackend.SelfTestHcBoundary();
                backend.InstallHcBoundaryForSelfTest(closeBoundary);
                string closeFailure;
                try
                {
                    backend.Close();
                    closeFailure = "<no-failure>";
                }
                catch (Exception ex)
                {
                    closeFailure = ex.Message;
                }
                finally
                {
                    backend.InstallHcBoundaryForSelfTest(null!);
                }
                if (closeFailure != "<no-failure>")
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H1: close must complete in the offline gate ({closeFailure})");
                if (scripted.CloseCount != 1 || YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H1: close must hand the leaf-owned handle back " +
                        $"(close={scripted.CloseCount} isOpen={YeManFanBackend.Asus.AsusACPI.IsOpen})");
                if (!backend.HcManagerCleanupConfirmed || !backend.HcDeviceManagerStopCompleted)
                    throw new InvalidOperationException(
                        "HC-SLIM-01 H1: close must reach a confirmed manager cleanup in the offline gate");

                // 幂等：重复关闭（stopDeviceManager=false）不得再归还一次，也不得产生第二个 Close。
                backend.Close(false);
                if (scripted.CloseCount != 1)
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H1: a duplicate close must not release the handle twice " +
                        $"(close={scripted.CloseCount})");

                // 重开同一会话并继续调节：必须按真实句柄状态重开（不能被旧标记吞掉）。
                backend.ReopenSelfTestSessionForSelfTest(mock, route, backendOpen: true);
                var second = backend.BeginAsusWriteScope("enable-curve");
                backend.ApplyPowerProfileForSelfTest(
                    NewFanProfile(new double[] { 0, 0, 20, 30, 40, 50, 60, 70, 90, 100, 0 }, "Software"),
                    "Background");
                var secondVerdict = backend.SettleOperationEvidence(second, "enable-curve", true);
                if (secondVerdict.Kind != "transported")
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H1: re-open scope expected transported got {secondVerdict.Kind}");
                if (scripted.ControlCalls.Count != 6 || scripted.OpenCount != 2 ||
                    !YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H1: re-open must reopen the handle and write again " +
                        $"(calls={scripted.ControlCalls.Count} open={scripted.OpenCount} " +
                        $"isOpen={YeManFanBackend.Asus.AsusACPI.IsOpen})");
                checks.Add("hcslim01-backend-close-release-and-reopen-realigns-handle");
            }
            finally
            {
                ResetAsusTransportForSelfTest();
                backend.Dispose();
            }
        }

        // 门 H2（R4 §4）：旧句柄失效后必须重新打开，不能被旧布尔标记吞掉。首段三写后模拟睡眠/
        // 驱动令既有句柄失效（叶组件仍持旧数值句柄，但 IsHandleValid 已为假），再调节必须触发
        // 第二次 TryOpen 并真实三写。旧 Ensure（只看 backendAsusAcpiOpened）会直接跳过重开，
        // 第二段变成 NotInitiatedHandleInvalid、零真实传输。
        {
            var scripted = new ScriptedAsusAcpiTransport();
            scripted.Enqueue(
                AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete,
                AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete, AsusScriptStep.SuccessComplete);
            var backend = NewAsusBackendSessionForSelfTest(scripted);
            try
            {
                var first = backend.BeginAsusWriteScope("enable-curve");
                backend.ApplyPowerProfileForSelfTest(
                    NewFanProfile(new double[] { 0, 0, 10, 20, 30, 40, 50, 60, 80, 100, 0 }, "Software"),
                    "Background");
                var firstVerdict = backend.SettleOperationEvidence(first, "enable-curve", true);
                if (firstVerdict.Kind != "transported" || scripted.ControlCalls.Count != 3 ||
                    scripted.OpenCount != 1 || !YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H2: first segment must open once and write three " +
                        $"(kind={firstVerdict.Kind} calls={scripted.ControlCalls.Count} " +
                        $"open={scripted.OpenCount} isOpen={YeManFanBackend.Asus.AsusACPI.IsOpen})");

                // 旧句柄被睡眠/驱动失效：叶组件持有的数值句柄没变，但传输层不再认它。
                scripted.InvalidateHandle();
                if (YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException(
                        "HC-SLIM-01 H2: an invalidated handle must read as closed");

                var second = backend.BeginAsusWriteScope("enable-curve");
                backend.ApplyPowerProfileForSelfTest(
                    NewFanProfile(new double[] { 0, 0, 20, 30, 40, 50, 60, 70, 90, 100, 0 }, "Software"),
                    "Background");
                var secondVerdict = backend.SettleOperationEvidence(second, "enable-curve", true);
                if (secondVerdict.Kind != "transported")
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H2: a dead handle must be reopened, not swallowed by the old flag " +
                        $"(kind={secondVerdict.Kind} detail={secondVerdict.Detail})");
                if (scripted.ControlCalls.Count != 6 || scripted.OpenCount != 2 ||
                    !YeManFanBackend.Asus.AsusACPI.IsOpen)
                    throw new InvalidOperationException(
                        $"HC-SLIM-01 H2: expected a second open and three more writes " +
                        $"(calls={scripted.ControlCalls.Count} open={scripted.OpenCount} " +
                        $"isOpen={YeManFanBackend.Asus.AsusACPI.IsOpen})");
                checks.Add("hcslim01-backend-stale-handle-forces-reopen");
            }
            finally
            {
                ResetAsusTransportForSelfTest();
                backend.Dispose();
            }
        }

        return checks;
    }
}

internal static class FanHostSelfTest
{
    private static async Task WaitForPowerStateAsync(FanHostEngine engine, string expected)
    {
        for (var attempt = 0; attempt < 200; attempt++)
        {
            if (engine.Snapshot().State == expected) return;
            await Task.Delay(5).ConfigureAwait(false);
        }
        throw new InvalidOperationException($"power integration did not reach {expected}; current={engine.Snapshot().State}");
    }

    private static async Task<IReadOnlyList<string>> RunPowerCallbackQueueIntegrationSelfTestAsync()
    {
        var checks = new List<string>();
        // 2026-09-24 裁决卡 §6-A（有区分力的反例）：自测期间**无参**构造必须落到
        // run 级隔离根，绝不允许回到生产 %LOCALAPPDATA%\YeManCC\fan-host。
        // 该断言是结构性的——不依赖本次是否恰好触发故障事件，因此比"跑完看生产
        // 文件有没有变"更强：夹具一旦漏回默认目录，这里立刻失败。
        {
            var isolationProbe = new HostDiagnosticLog();
            var tempRoot = System.IO.Path.GetTempPath();
            if (!isolationProbe.Path.StartsWith(tempRoot, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException(
                    "selftest-log-isolation FAILED: default logger resolved outside TEMP: " + isolationProbe.Path);
            if (isolationProbe.Path.IndexOf("yemancc-selftest-", StringComparison.OrdinalIgnoreCase) < 0)
                throw new InvalidOperationException(
                    "selftest-log-isolation FAILED: default logger not under a run-scoped selftest root: " + isolationProbe.Path);
            checks.Add("selftest-log-isolation-default-root-isolated");
        }
        var options = HostOptions.Parse(new[] { "--port", "8798" });
        var diagnostics = new HostDiagnosticLog();
        var engine = new FanHostEngine(options, diagnostics);
        using var server = new LocalFanHostServer(engine, options, diagnostics);
        var worker = server.StartPowerWorkerForSelfTest();
        try
        {
            // API suspend -> Windows resume uses one announced edge state.
            _ = await server.SuspendForSelfTest().ConfigureAwait(false);
            await WaitForPowerStateAsync(engine, "Suspended").ConfigureAwait(false);
            server.InvokePowerModeChangedForSelfTest(PowerModes.Resume);
            await WaitForPowerStateAsync(engine, "AwaitingControl").ConfigureAwait(false);
            checks.Add("r2-callback-queue-api-suspend-windows-resume");

            // Windows suspend -> API resume uses that same state and queue.
            server.InvokePowerModeChangedForSelfTest(PowerModes.Suspend);
            await WaitForPowerStateAsync(engine, "Suspended").ConfigureAwait(false);
            _ = await server.ResumeForSelfTest().ConfigureAwait(false);
            await WaitForPowerStateAsync(engine, "AwaitingControl").ConfigureAwait(false);
            checks.Add("r2-callback-queue-windows-suspend-api-resume");

            // Duplicate Windows events create one accepted edge each.
            var acceptedBeforeDuplicate = server.AcceptedPowerTransitionsForSelfTest;
            server.InvokePowerModeChangedForSelfTest(PowerModes.Suspend);
            server.InvokePowerModeChangedForSelfTest(PowerModes.Suspend);
            await WaitForPowerStateAsync(engine, "Suspended").ConfigureAwait(false);
            var afterSuspendDuplicate = server.AcceptedPowerTransitionsForSelfTest;
            if (afterSuspendDuplicate - acceptedBeforeDuplicate != 1)
                throw new InvalidOperationException("duplicate Windows suspend was not suppressed at callback ingress");
            var acceptedBeforeResumeDuplicate = server.AcceptedPowerTransitionsForSelfTest;
            server.InvokePowerModeChangedForSelfTest(PowerModes.Resume);
            server.InvokePowerModeChangedForSelfTest(PowerModes.Resume);
            await WaitForPowerStateAsync(engine, "AwaitingControl").ConfigureAwait(false);
            if (server.AcceptedPowerTransitionsForSelfTest - acceptedBeforeResumeDuplicate != 1)
                throw new InvalidOperationException("duplicate Windows resume was not suppressed at callback ingress");
            checks.Add("r2-callback-duplicate-suspend-resume");

            // Stress the actual callback method; it must remain admission-only
            // and return without diagnostics/engine work or a monitor wait.
            var callbackStart = Stopwatch.GetTimestamp();
            var callbacks = Enumerable.Range(0, 256).Select(index => Task.Run(() =>
                server.InvokePowerModeChangedForSelfTest(index % 2 == 0 ? PowerModes.Suspend : PowerModes.Resume))).ToArray();
            Task.WaitAll(callbacks);
            if (Stopwatch.GetElapsedTime(callbackStart).TotalMilliseconds > 2000)
                throw new InvalidOperationException("power callback admission exceeded the safe bound");
            checks.Add("r2-callback-concurrent-admission");
        }
        finally
        {
            server.Dispose();
            try { await worker.ConfigureAwait(false); } catch (OperationCanceledException) { }
        }

        // A rejected callback queue retains a deferred target and does not
        // touch the engine suspend write gate.
        var rejectedEngine = new FanHostEngine(options, new HostDiagnosticLog());
        using (var rejectedServer = new LocalFanHostServer(rejectedEngine, options, new HostDiagnosticLog()))
        {
            rejectedServer.CompletePowerQueueForSelfTest();
            rejectedServer.InvokePowerModeChangedForSelfTest(PowerModes.Suspend);
            if (rejectedServer.DeferredPowerTargetForSelfTest != PowerIngressTarget.Suspended ||
                rejectedEngine.IsCloseWriteBlockedForPower || rejectedEngine.IsSystemSuspendPendingForSelfTest)
                throw new InvalidOperationException("rejected callback left a write gate or lost its deferred target");
            checks.Add("r2-callback-queue-rejection-reconciles");
        }

        // queued suspend -> failed close -> resume: the queued suspend must
        // not re-assert the write gate after the close owner has failed.
        var failedEngine = new FanHostEngine(options, new HostDiagnosticLog());
        using (var failedServer = new LocalFanHostServer(failedEngine, options, new HostDiagnosticLog()))
        {
            failedServer.InvokePowerModeChangedForSelfTest(PowerModes.Suspend);
            failedEngine.InjectUncertainStateForSelfTest();
            var closeFailed = false;
            try { _ = failedServer.CloseForSelfTest(); }
            catch (FanApiException ex) when (ex.Code == "OEM_RESTORE_FAILED") { closeFailed = true; }
            if (!closeFailed || failedServer.PowerIngressClosingForSelfTest)
                throw new InvalidOperationException("failed close did not reopen the power ingress");
            var failedWorker = failedServer.StartPowerWorkerForSelfTest();
            var resumeRejectedByFaultBoundary = false;
            try
            {
                _ = await failedServer.ResumeForSelfTest().ConfigureAwait(false);
            }
            catch (FanApiException ex) when (ex.Code == "HC_RESUME_REBUILD_FAILED" || ex.Code == "FAULT_LOCKED")
            {
                // A failed HC close leaves the session fault-locked. HC does
                // not reopen a half-closed device from a later resume edge;
                // the safe path is to keep writes blocked until close recovery
                // is explicitly resolved.
                resumeRejectedByFaultBoundary = true;
            }
            if (!resumeRejectedByFaultBoundary || !failedEngine.IsCloseWriteBlockedForPower || failedServer.DeferredPowerTargetForSelfTest is not null)
                throw new InvalidOperationException("failed close/resume reconciliation lost the close safety boundary");
            failedServer.ResolveUncertainStateForSelfTest();
            try { _ = failedServer.CloseForSelfTest(); } catch (FanApiException) { }
            failedServer.Dispose();
            try { await failedWorker.ConfigureAwait(false); } catch (OperationCanceledException) { }
            checks.Add("r2-queued-suspend-close-failure-resume");
        }

        // Concurrent close calls have one in-flight owner; a later call may
        // retry only after that owner has returned.
        var ownerEngine = new FanHostEngine(options, new HostDiagnosticLog());
        using (var ownerServer = new LocalFanHostServer(ownerEngine, options, new HostDiagnosticLog()))
        {
            ownerEngine.InjectUncertainStateForSelfTest();
            ownerServer.SetCloseOwnerDelayForSelfTest(100);
            var first = Task.Run(() =>
            {
                try { _ = ownerServer.CloseForSelfTest(); return "success"; }
                catch (FanApiException ex) { return ex.Code; }
            });
            for (var attempt = 0; attempt < 100 && !ownerEngine.CloseOwnerInFlightForSelfTest; attempt++)
                await Task.Delay(1).ConfigureAwait(false);
            var second = Task.Run(() =>
            {
                try { _ = ownerServer.CloseForSelfTest(); return "success"; }
                catch (FanApiException ex) { return ex.Code; }
            });
            var results = await Task.WhenAll(first, second).ConfigureAwait(false);
            if (!results.Contains("HC_CLOSE_PENDING") || results.Count(value => value == "OEM_RESTORE_FAILED") > 1)
                throw new InvalidOperationException($"close owner race was not serialized: {string.Join(',', results)}");
            ownerServer.ResolveUncertainStateForSelfTest();
            try { _ = ownerServer.CloseForSelfTest(); } catch (FanApiException) { }
            checks.Add("r2-single-close-owner");
        }
        return checks;
    }

    private static IReadOnlyList<string> RunFanOnlyLifecycleIntegrationSelfTest()
    {
        var checks = new List<string>();
        var options = HostOptions.Parse(new[] { "--port", "8797" });
        var engine = new FanHostEngine(options, new HostDiagnosticLog());

        // These are the actual safe FanHostEngine boundaries. The safe build
        // starts no HC manager and performs no hardware call, but it must still
        // preserve the fan-only device session order: Open -> OpenEvents ->
        // SystemPending virtual Close -> SystemReady Open/OpenEvents admission
        // -> process Close. Safe mode has no HC graph to observe; real mode
        // records the graph lifecycle after OpenEvents and before Close.
        _ = engine.Open();
        if (!engine.Snapshot().OpenCalled) throw new InvalidOperationException("safe fan Open boundary was not recorded");
        _ = engine.OpenEvents();
        var opened = engine.Snapshot();
        if (!opened.OpenEventsCalled || opened.HcManagerFactoryStarted || !opened.HcManagerFactoryIsolated ||
            opened.HcManagerFactoryLifecycle != "Unknown" ||
            opened.HcDeviceManagerLifecycle != "Unknown")
            throw new InvalidOperationException("safe fan-only OpenEvents did not preserve Unknown manager evidence");
        checks.Add("r1-fan-only-open-openevents-boundary");

        _ = engine.SuspendForSystemPower();
        if (engine.Snapshot().State != "Suspended" || engine.Snapshot().PowerState != "Suspended")
            throw new InvalidOperationException("safe fan SystemPending boundary did not reach Suspended");
        if (engine.Snapshot().HcDeviceManagerLifecycle != "Unknown" ||
            !engine.Snapshot().HcDeviceManagerStopCompleted)
            throw new InvalidOperationException("safe fan SystemPending reported an invalid manager cleanup outcome");
        checks.Add("r1-fan-only-system-pending-close-retains-manager");

        _ = engine.ResumeForSystemPower();
        var resumed = engine.Snapshot();
        if (resumed.State != "AwaitingControl" || resumed.OpenCalled || resumed.OpenEventsCalled ||
            resumed.HcManagerFactoryStarted || !resumed.HcManagerFactoryIsolated ||
            resumed.HcManagerFactoryLifecycle != "Unknown" ||
            resumed.HcDeviceManagerLifecycle != "Unknown")
            throw new InvalidOperationException("safe fan SystemReady boundary did not rebuild to AwaitingControl");
        checks.Add("r1-fan-only-system-ready-reopen-boundary");

        _ = engine.Close();
        var closed = engine.Snapshot();
        if (closed.State != "Stopped" || !closed.CloseCalled || closed.OpenCalled || closed.OpenEventsCalled ||
            closed.HcManagerFactoryStarted || !closed.HcManagerFactoryIsolated ||
            closed.HcManagerFactoryLifecycle != "Unknown" ||
            closed.HcDeviceManagerLifecycle != "Unknown")
            throw new InvalidOperationException("safe fan Window_Closed boundary did not stop exactly once");
        checks.Add("r4-fan-only-window-closed-single-owner");

        var suspendCloseEngine = new FanHostEngine(options, new HostDiagnosticLog());
        _ = suspendCloseEngine.Open();
        _ = suspendCloseEngine.OpenEvents();
        _ = suspendCloseEngine.SuspendForSystemPower();
        _ = suspendCloseEngine.Close();
        if (suspendCloseEngine.Snapshot().State != "Stopped")
            throw new InvalidOperationException("safe suspend-close race did not reach Stopped");
        checks.Add("r4.2-safe-suspend-close");

        var resumeCloseEngine = new FanHostEngine(options, new HostDiagnosticLog());
        _ = resumeCloseEngine.Open();
        _ = resumeCloseEngine.OpenEvents();
        _ = resumeCloseEngine.SuspendForSystemPower();
        _ = resumeCloseEngine.ResumeForSystemPower();
        if (resumeCloseEngine.Snapshot().State != "AwaitingControl")
            throw new InvalidOperationException("safe resume boundary did not reach AwaitingControl");
        _ = resumeCloseEngine.Close();
        if (resumeCloseEngine.Snapshot().State != "Stopped")
            throw new InvalidOperationException("safe resume-close race did not reach Stopped");
        checks.Add("r4.2-safe-resume-close");
        return checks;
    }

    private static int AcquireFreeTcpPort()
    {
        using var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        return ((IPEndPoint)probe.LocalEndpoint).Port;
    }

    private static async Task WaitForListenerStateAsync(LocalFanHostServer server, string expected, int timeoutMilliseconds = 6000)
    {
        var deadline = Environment.TickCount64 + timeoutMilliseconds;
        while (Environment.TickCount64 < deadline)
        {
            if (string.Equals(server.ListenerStateForSelfTest, expected, StringComparison.Ordinal)) return;
            await Task.Delay(25).ConfigureAwait(false);
        }
        throw new InvalidOperationException($"listener did not reach {expected}; current={server.ListenerStateForSelfTest}");
    }

    private static async Task WaitForParentHandoffAsync(FanHostEngine engine, int timeoutMilliseconds = 7000)
    {
        var deadline = Environment.TickCount64 + timeoutMilliseconds;
        while (Environment.TickCount64 < deadline)
        {
            if (engine.ParentExitHandoffQueuedForSelfTest) return;
            await Task.Delay(25).ConfigureAwait(false);
        }
        throw new InvalidOperationException("parent watchdog did not enqueue the recovery handoff");
    }

    private static async Task<IReadOnlyList<string>> RunR6R7SafetySelfTestAsync()
    {
        var checks = new List<string>();
        checks.AddRange(ListenerRetryBudget.RunSelfTest());

        // A port held for the whole finite budget must reach the explicit
        // terminal state. The holder is never killed by the Host.
        var heldPort = AcquireFreeTcpPort();
        using (var holder = new TcpListener(IPAddress.Loopback, heldPort))
        {
            holder.Start();
            var options = HostOptions.Parse(new[] { "--port", heldPort.ToString() });
            var engine = new FanHostEngine(options, new HostDiagnosticLog());
            var server = new LocalFanHostServer(engine, options, new HostDiagnosticLog());
            try
            {
                var run = server.RunAsync();
                var completed = await Task.WhenAny(run, Task.Delay(10000)).ConfigureAwait(false);
                if (completed != run) throw new InvalidOperationException("held listener did not terminate within its finite retry budget");
                await run.ConfigureAwait(false);
                if (server.ListenerStateForSelfTest != "ListenerFaultLocked" ||
                    server.ListenerRetryAttemptsForSelfTest != ListenerRetryBudget.MaxAttempts ||
                    server.ListenerCreateCountForSelfTest != ListenerRetryBudget.MaxAttempts ||
                    server.WatchdogStartCountForSelfTest != 1 ||
                    server.PowerWorkerStartCountForSelfTest != 1 ||
                    engine.CloseEntryCountForSelfTest != 1 ||
                    !engine.Snapshot().CloseCalled ||
                    !holder.Server.IsBound)
                    throw new InvalidOperationException("held listener terminal state/close-owner/holder evidence mismatch");
                checks.Add("r7-port-held-fault-locked-single-close-holder-preserved");
            }
            finally
            {
                server.Dispose();
            }
        }

        // Releasing the port before the budget expires must recreate exactly
        // one listener and return to Listening without a second watchdog.
        var releasedPort = AcquireFreeTcpPort();
        var releasedHolder = new TcpListener(IPAddress.Loopback, releasedPort);
        releasedHolder.Start();
        var releasedOptions = HostOptions.Parse(new[] { "--port", releasedPort.ToString() });
        var releasedEngine = new FanHostEngine(releasedOptions, new HostDiagnosticLog());
        var releasedServer = new LocalFanHostServer(releasedEngine, releasedOptions, new HostDiagnosticLog());
        Task releasedRun;
        try
        {
            releasedRun = releasedServer.RunAsync();
            await Task.Delay(450).ConfigureAwait(false);
            releasedHolder.Stop();
            releasedHolder.Dispose();
            await WaitForListenerStateAsync(releasedServer, "Listening").ConfigureAwait(false);
            if (releasedServer.ListenerCreateCountForSelfTest <= 1 ||
                releasedServer.ListenerCreateCountForSelfTest > ListenerRetryBudget.MaxAttempts ||
                releasedServer.WatchdogStartCountForSelfTest != 1 ||
                releasedServer.PowerWorkerStartCountForSelfTest != 1 ||
                releasedEngine.CloseEntryCountForSelfTest != 0)
                throw new InvalidOperationException("released listener did not recover exactly once");
            releasedServer.Stop();
            await releasedRun.ConfigureAwait(false);
            checks.Add("r7-port-release-within-window-recovers-once");
        }
        finally
        {
            try { releasedHolder.Stop(); } catch { }
            releasedHolder.Dispose();
            releasedServer.Dispose();
        }

        // Normal shutdown with an active watchdog must wait for its terminal
        // state before Dispose; this path must not emit an unhandled task.
        var normalPort = AcquireFreeTcpPort();
        var normalOptions = HostOptions.Parse(new[] { "--port", normalPort.ToString(), "--parent-pid", Environment.ProcessId.ToString() });
        var normalEngine = new FanHostEngine(normalOptions, new HostDiagnosticLog());
        var normalServer = new LocalFanHostServer(normalEngine, normalOptions, new HostDiagnosticLog());
        try
        {
            var normalRun = normalServer.RunAsync();
            await WaitForListenerStateAsync(normalServer, "Listening").ConfigureAwait(false);
            normalServer.Stop();
            await normalRun.ConfigureAwait(false);
            normalServer.Dispose();
            checks.Add("r6-watchdog-active-normal-stop-dispose");
        }
        finally { normalServer.Dispose(); }

        // A faulted watchdog task is observed and recorded before disposal;
        // no exception is allowed to escape the process-exit boundary.
        var faultPort = AcquireFreeTcpPort();
        var faultOptions = HostOptions.Parse(new[] { "--port", faultPort.ToString() });
        var faultServer = new LocalFanHostServer(new FanHostEngine(faultOptions, new HostDiagnosticLog()), faultOptions, new HostDiagnosticLog());
        try
        {
            faultServer.InjectWatchdogTaskForSelfTest(Task.FromException(new InvalidOperationException("selftest-watchdog-fault")));
            faultServer.Stop();
            faultServer.Dispose();
            if (!faultServer.WatchdogFaultObservedForSelfTest)
                throw new InvalidOperationException("faulted watchdog task was not observed before Dispose");
            checks.Add("r6-watchdog-fault-observed-no-unhandled");
        }
        finally { faultServer.Dispose(); }

        // Parent loss while the recovery timer is still pending must not
        // finalize the listener early. Once the safe recovery evidence is
        // supplied, exactly one watchdog owner completes the stop.
        var parentProcess = Process.Start(new ProcessStartInfo
        {
            FileName = Environment.GetEnvironmentVariable("ComSpec") ?? "cmd.exe",
            Arguments = "/c timeout /t 30 /nobreak >nul",
            CreateNoWindow = true,
            UseShellExecute = false,
        }) ?? throw new InvalidOperationException("could not start owned parent-watchdog test process");
        var parentPort = AcquireFreeTcpPort();
        var parentOptions = HostOptions.Parse(new[] { "--port", parentPort.ToString(), "--parent-pid", parentProcess.Id.ToString() });
        var parentEngine = new FanHostEngine(parentOptions, new HostDiagnosticLog());
        var parentServer = new LocalFanHostServer(parentEngine, parentOptions, new HostDiagnosticLog());
        try
        {
            var parentRun = parentServer.RunAsync();
            await WaitForListenerStateAsync(parentServer, "Listening").ConfigureAwait(false);
            parentEngine.InjectUncertainStateForSelfTest();
            try { if (!parentProcess.HasExited) parentProcess.Kill(entireProcessTree: true); } catch { }
            await WaitForParentHandoffAsync(parentEngine).ConfigureAwait(false);
            if (parentRun.IsCompleted)
                throw new InvalidOperationException("parent watchdog finalized before recovery evidence");
            parentEngine.ResolveUncertainStateForSelfTest();
            var parentCompleted = await Task.WhenAny(parentRun, Task.Delay(10000)).ConfigureAwait(false);
            if (parentCompleted != parentRun) throw new InvalidOperationException("parent recovery did not reach a terminal stop");
            await parentRun.ConfigureAwait(false);
            var parentSnapshot = parentEngine.Snapshot();
            if (parentSnapshot.State != "Stopped" || parentEngine.CloseEntryCountForSelfTest != 0)
                throw new InvalidOperationException("parent recovery used a duplicate Close owner or did not stop");
            parentServer.Dispose();
            checks.Add("r6-parent-loss-recovery-waits-then-finalizes");
        }
        finally
        {
            parentServer.Dispose();
            try { if (!parentProcess.HasExited) parentProcess.Kill(entireProcessTree: true); } catch { }
            parentProcess.Dispose();
        }

        return checks;
    }

    // ================================================================
    // 裁决 2026-09-19（P1 SystemPending 生命周期）Host-only 批次：T1–T10。
    // 覆盖 H1（未进入会话短路）、H2（C 族补做一次只读观测）、H3（令牌条件式释放 +
    // 错误码顺序）、H4（resume no-op 显式标注）、H5（免门白名单故障账本）。
    // T10 需要真机（真实风扇转速），本套件只固化操作法与断言，**不执行**。
    // ================================================================

    private static JsonElement ToJson(object value) =>
        JsonSerializer.SerializeToElement(value, JsonDefaults.Options);

    private static bool EventSeen(string eventName) =>
        HostDiagnosticLog.SelfTestCaptured.Any(entry => entry.Event == eventName);

    private static int EventCount(string eventName) =>
        HostDiagnosticLog.SelfTestCaptured.Count(entry => entry.Event == eventName);

    /** 按事件名 + 细节子串计数（同一进程内多个夹具引擎共用捕获时的定点判据）。 */
    private static int EventCountMatching(string eventName, string detailsNeedle) =>
        HostDiagnosticLog.SelfTestCaptured.Count(entry =>
            entry.Event == eventName &&
            !string.IsNullOrEmpty(entry.Details) &&
            entry.Details!.Contains(detailsNeedle, StringComparison.Ordinal));

    private static string EventDetails(string eventName) =>
        HostDiagnosticLog.SelfTestCaptured.FirstOrDefault(entry => entry.Event == eventName).Details ?? "{}";

    private static void RequireNoEvent(string eventName, string context)
    {
        if (EventSeen(eventName))
            throw new InvalidOperationException($"{context}: 不应出现事件 {eventName}（实际出现 {EventCount(eventName)} 次）");
    }

    /** T10 需要真机；此处把"必须怎么操作、必须断言什么"固化成可打印文本。 */
    internal const string T10RealMachineProcedure = """
        T10（重新接管并确认真实风扇转速）——需要真机（ROG Ally X + 真实 HC payload），本批次未执行：
          1. 冷启动掌机，打开 YMCC（**不碰任何风扇开关**）；
          2. 记录 /api/state：openCalled=false、openEventsCalled=false、hardwareWritesObserved=false、
             hcManagerCleanupEvidence="manager-graph-not-observed"；
          3. 按电源键睡眠 10 秒后唤醒；
          4. 断言（免门账本 %LOCALAPPDATA%\YeManCC\fan-host\logs\fan-host-fault.log 内应**无**新故障记录）：
             - runtime 日志出现 power.suspend-no-session-complete{result:"not-entered-no-cleanup-required"}；
             - **无** restore.close-hc-begin / hc-close.* / recovery.retry-scheduled / recovery.retry-terminal；
             - 唤醒后 /api/state 的 powerState 由 Suspended 回到 On、state=AwaitingControl；
             - /api/open 与 /api/open-events **不再**返回 POWER_SUSPENDING（若 FaultLocked 应为 FAULT_LOCKED）；
          5. 打开风扇控制（重新接管），断言 openCalled=true、openEventsCalled=true、IsOpen 生效；
          6. 确认真实风扇转速：以 HW 读数或听感/转速读数确认风扇随曲线变化（RPM 非 0、随档位变化），
             并确认 close 后 RPM 回到 OEM 默认表行为；
          7. 断言未出现 power.fault-locked（即本批次不引入新的卡死态）。
        """;

    private static async Task<IReadOnlyList<string>> RunP1AdjudicationSelfTestAsync()
    {
        var checks = new List<string>();
        var options = HostOptions.Parse(new[] { "--port", "8796" });
        var tempDir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "yemancc-selftest-fanlog-" + Guid.NewGuid().ToString("N"));
        HostDiagnosticLog.ResetSelfTestCapture();
        HostDiagnosticLog.SelfTestCaptureEnabled = true;
        try
        {
            // ---------------- T1：未进入会话睡眠（真机 01:16:07 指纹的 Safe 等价物） ----------------
            var t1Engine = new FanHostEngine(options, new HostDiagnosticLog(tempDir));
            if (!t1Engine.HcSessionNeverEnteredForSelfTest())
                throw new InvalidOperationException("T1: 默认态必须判定为 HcSessionNeverEntered");
            var t1Before = t1Engine.Snapshot();
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = t1Engine.Suspend(JsonDocument.Parse("{}").RootElement);
            var t1 = t1Engine.Snapshot();
            // ① 产生短路结果事件
            if (EventCount("power.suspend-no-session-complete") != 1)
                throw new InvalidOperationException("T1: 未产生 power.suspend-no-session-complete");
            if (!EventDetails("power.suspend-no-session-complete").Contains("not-entered-no-cleanup-required", StringComparison.Ordinal))
                throw new InvalidOperationException("T1: 结果名不是 not-entered-no-cleanup-required");
            if (!EventDetails("power.suspend-no-session-complete").Contains("\"sessionNeverEntered\":true", StringComparison.Ordinal))
                throw new InvalidOperationException("T1: 缺少 sessionNeverEntered:true");
            // ② 无 HC Close 链、③ 无 recovery retry
            RequireNoEvent("restore.close-hc-begin", "T1");
            RequireNoEvent("hc-close.virtual-device.begin", "T1");
            RequireNoEvent("power.suspend-hc-close-first-begin", "T1");
            RequireNoEvent("recovery.retry-scheduled", "T1");
            RequireNoEvent("recovery.retry-terminal", "T1");
            RequireNoEvent("hc-close.manager-cleanup-confirmed", "T1");
            // ④ 终态
            if (t1.State != "Suspended" || t1.PowerState != "Suspended" || t1.HcCloseCleanupPending)
                throw new InvalidOperationException($"T1: 终态错误 state={t1.State} powerState={t1.PowerState} cleanupPending={t1.HcCloseCleanupPending}");
            // ⑤ 禁止伪造证据：短路不得改动任何证据字段（与睡眠前逐字段相等）
            if (t1.HcVirtualCloseReturned || t1.OemRestoreConfirmed || t1.HcRestoreCallbackReturned ||
                t1.OemPhysicalOwnershipConfirmed || t1.HardwareWritesObserved)
                throw new InvalidOperationException("T1: 短路伪造了 HC virtual close / OEM restore / 物理交还证据");
            if (t1.HcVirtualCloseReturned != t1Before.HcVirtualCloseReturned ||
                t1.HcManagerCleanupEvidence != t1Before.HcManagerCleanupEvidence ||
                t1.HcDeviceManagerLifecycle != t1Before.HcDeviceManagerLifecycle ||
                t1.HcManagerFactoryLifecycle != t1Before.HcManagerFactoryLifecycle ||
                t1.HcDeviceManagerStopCompleted != t1Before.HcDeviceManagerStopCompleted ||
                t1.OemRestoreEvidence != t1Before.OemRestoreEvidence)
                throw new InvalidOperationException("T1: 短路改动了 manager/OEM 证据字段（禁止伪造 cleanup confirmed）");
            // ⑤b 真实后端下的期望取值（Gap2 闭环）：真机 01:16 样本的
            // `hcManagerCleanupEvidence="manager-graph-not-observed"` +
            // `hcDeviceManagerStopCompleted=false` 由派生函数确定给出，不依赖真机即可断言。
            if (RealHcBackend.ManagerCleanupEvidence(false, false) != "manager-graph-not-observed")
                throw new InvalidOperationException("T1: 未进入会话的 cleanup 证据必须为 manager-graph-not-observed");
            if (RealHcBackend.ManagerCleanupEvidence(false, true) != "post-close-manager-cleanup-unconfirmed" ||
                RealHcBackend.ManagerCleanupEvidence(true, true) != "post-close-no-active-manager-observed")
                throw new InvalidOperationException("T1: cleanup 证据派生与既有取值不一致");
            checks.Add("t1-no-session-suspend-short-circuit");

            // ---------------- T5：重复睡眠（幂等，命中既有去重门） ----------------
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = t1Engine.Suspend(JsonDocument.Parse("{}").RootElement);
            var t5 = t1Engine.Snapshot();
            if (EventCount("power.suspend-ignored-duplicate") != 1)
                throw new InvalidOperationException("T5: 第二次睡眠未命中既有去重门");
            RequireNoEvent("power.suspend-no-session-complete", "T5");
            RequireNoEvent("recovery.retry-scheduled", "T5");
            RequireNoEvent("hc-close.virtual-device.begin", "T5");
            if (t5.State != "Suspended" || t5.PowerState != "Suspended" || t5.HcCloseCleanupPending)
                throw new InvalidOperationException("T5: 重复睡眠后终态被改动");
            checks.Add("t5-no-session-duplicate-suspend-idempotent");

            // ---------------- T6：睡眠后唤醒（空曲线 ⇒ 既有同步完成支） ----------------
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = t1Engine.ResumeForSystemPower();
            var t6 = t1Engine.Snapshot();
            if (!EventSeen("power.resume-sync-completed"))
                throw new InvalidOperationException("T6: 未走既有同步完成支（power.resume-sync-completed）");
            if (EventSeen("power.resume-auto-rebuild.begin"))
                throw new InvalidOperationException("T6: 空曲线不应启动 rebuild");
            RequireNoEvent("recovery.retry-terminal", "T6");
            if (t6.PowerState != "On" || t6.State != "AwaitingControl")
                throw new InvalidOperationException($"T6: 唤醒终态错误 state={t6.State} powerState={t6.PowerState}");
            if (t6.PowerOperationOutcome != "await-user")
                throw new InvalidOperationException("T6: 空恢复 outcome 应为 await-user");
            // ④ 之后 /api/open 不再 POWER_SUSPENDING（令牌已被恢复消费）
            try { _ = t1Engine.Open(); }
            catch (FanApiException ex) when (ex.Code == "POWER_SUSPENDING" || ex.Code == "POWER_SUSPENDED")
            {
                throw new InvalidOperationException($"T6: 唤醒后仍被睡眠门拒绝: {ex.Code}");
            }
            checks.Add("t6-no-session-suspend-then-wake-sync-complete");

            // ═════════ R1（FAN-926R 唤醒租约裁决 §3）：恢复 worker 的临时租约 ═════════
            // 真机形态（2026-09-26 20:13:50 / 20:15:52）：自动恢复走完
            // Open/OpenEvents/AcquireControl/Enable 并成功重放曲线，却在 15 s 后被
            // **宿主自己铸造的占位租约**到期触发的 RestoreHardware(close:false) 撤回。
            // 本节用 `--mock-handshake` 的**受控真实 Host**（真实定时器、真实事件捕获）证明：
            //   ① 成功提交后该占位租约被**窄撤销**（不 RestoreHardware、不落 AwaitingControl）；
            //   ② 跨过原 15 s 占位 TTL（≥20 s）仍保持原曲线与宿主控制，且**没有**该租约触发的 restore；
            //   ③ 之后客户端真实调整仍然有效（下一个用户动作不被吞掉）；
            //   ④ 普通客户端租约**真正到期**仍执行原安全策略（不得靠延长 TTL 掩盖）；
            //   ⑤ 迟到/异身份的到期回调不得处置新租约，也不得改动新恢复周期。
            // 夹具说明：Safe（mock）构建没有真实 HC backend，无法表达"带写历史 + 活会话"的
            // 睡眠边界（那一段由 T1/T2/T4/T6 与真机卡覆盖）；这里用 T4 同形的**干净**睡眠
            // 边界 + `--mock-resume-rebuild-delay-ms`（沙箱专用）让恢复真的带曲线重建，
            // 以便把本节的判据集中在"恢复事务里的占位租约生命周期"上。
            var r1Options = HostOptions.Parse(new[] { "--port", "8799", "--mock-handshake", "--mock-resume-rebuild-delay-ms", "1" });
            var r1Engine = new FanHostEngine(r1Options, new HostDiagnosticLog(tempDir));
            _ = r1Engine.Open();
            _ = r1Engine.OpenEvents();
            _ = r1Engine.SuspendForSystemPower();
            var r1Suspended = r1Engine.Snapshot();
            if (r1Suspended.State != "Suspended")
                throw new InvalidOperationException($"L1: 夹具未进入 Suspended（state={r1Suspended.State} powerState={r1Suspended.PowerState} cleanupPending={r1Suspended.HcCloseCleanupPending} error={r1Suspended.LastError}）");
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = r1Engine.ResumeForSystemPower();
            var r1CommitDeadline = Stopwatch.StartNew();
            while (r1CommitDeadline.ElapsedMilliseconds < 15_000 && r1Engine.Snapshot().State == "Resuming")
                Thread.Sleep(25);
            if (!EventSeen("power.resume-placeholder-lease-created"))
                throw new InvalidOperationException("L1: 缺少临时租约创建证据");
            if (!EventSeen("power.resume-placeholder-lease-revoked"))
                throw new InvalidOperationException("L1: 成功提交后必须窄撤销本 worker 的临时租约");
            if (!EventSeen("power.resume-auto-rebuild.success"))
                throw new InvalidOperationException("L1: 真实提交分支必须记成功");
            var r1AfterCommit = r1Engine.SnapshotForRead();
            // 说明：`SnapshotForRead()` 同时把新鲜快照发布出去——真机上这一步由 UI 的
            // `/api/state` 轮询完成；无门快速拒绝路径读的是**已发布快照**，因此夹具必须
            // 像真机一样先读一次，才能测到"接管被放行"这一真实行为（而不是夹具自造的超时）。
            if (r1AfterCommit.State != "Ready" || r1AfterCommit.Lease is not null ||
                !r1AfterCommit.HardwareWritesEnabled || (r1AfterCommit.ActiveCurve?.Count ?? 0) == 0)
                throw new InvalidOperationException(
                    $"L1: 提交后必须保持 Ready + 已恢复曲线 + 硬件写授权，且不得留占位租约" +
                    $"(state={r1AfterCommit.State} lease={r1AfterCommit.Lease is not null} " +
                    $"writes={r1AfterCommit.HardwareWritesEnabled} nodes={r1AfterCommit.ActiveCurve?.Count ?? 0})");
            // ② 受控真实 Host ≥20 s：跨过原 15 s 占位 TTL。
            var r1CommittedNodes = r1AfterCommit.ActiveCurve?.Count ?? 0;
            var r1Hold = Stopwatch.StartNew();
            while (r1Hold.ElapsedMilliseconds < 20_000)
            {
                Thread.Sleep(100);
                _ = r1Engine.SnapshotForRead();   // 模拟 UI 的 /api/state 轮询（真机同形）
            }
            var r1Held = r1Engine.Snapshot();
            if (EventCountMatching("restore.mock-applied", "\"cause\":\"lease-expiry\"") != 0)
                throw new InvalidOperationException(
                    $"L1: 占位租约撤销后不得再有**租约到期来源**的释放" +
                    $"(lease-expiry release={EventCountMatching("restore.mock-applied", "\"cause\":\"lease-expiry\"")} " +
                    $"stale={EventCount("lease.expiry-callback-stale")} state={r1Held.State} " +
                    $"lease={r1Held.Lease is not null} writes={r1Held.HardwareWritesEnabled}）");
            if (r1Held.State != "Ready" || r1Held.Lease is not null ||
                !r1Held.HardwareWritesEnabled || (r1Held.ActiveCurve?.Count ?? 0) != r1CommittedNodes)
                throw new InvalidOperationException(
                    $"L1: 跨过占位 TTL 后必须仍保持原曲线与宿主控制，且不得有该租约触发的 restore" +
                    $"(state={r1Held.State} lease={r1Held.Lease is not null} " +
                    $"writes={r1Held.HardwareWritesEnabled} nodes={r1Held.ActiveCurve?.Count ?? 0} expected={r1CommittedNodes})");
            // ③ 之后客户端实际调整必须有效。
            FanLease r1ClientLease;
            try
            {
                r1ClientLease = r1Engine.AcquireControl();
            }
            catch (FanApiException ex)
            {
                var r1Reject = r1Engine.Snapshot();
                throw new InvalidOperationException(
                    $"L1: 等待后客户端接管被拒 code={ex.Code} state={r1Reject.State} opStatus={r1Reject.PowerOperationStatus} " +
                    $"attempt={r1Reject.PowerOperationAttempt} writes={r1Reject.HardwareWritesEnabled} " +
                    $"leases={EventCount("power.resume-placeholder-lease-created")}/{EventCount("power.resume-placeholder-lease-revoked")} " +
                    $"resumeBegin={EventCount("power.resume-auto-rebuild.begin")} success={EventCount("power.resume-auto-rebuild.success")} " +
                    $"superseded={EventCount("power.resume-commit-superseded")} failure={EventCount("power.resume-auto-rebuild.failure")} " +
                    $"syncCompleted={EventCount("power.resume-sync-completed")}", ex);
            }
            using (var r1AdjustBody = JsonDocument.Parse(JsonSerializer.Serialize(new
            {
                nodes = new[] { new FanNode(0, 5), new FanNode(40, 30), new FanNode(70, 75), new FanNode(100, 100) },
                leaseId = r1ClientLease.LeaseId,
            }, JsonDefaults.Options)))
            {
                _ = r1Engine.Enable(r1AdjustBody.RootElement);
            }
            if (r1Engine.Snapshot().State != "Ready" || r1Engine.Snapshot().ActiveCurve?.Count != 4)
                throw new InvalidOperationException("L1: 唤醒等待后客户端下一次调整必须有效");
            checks.Add("l1-resume-placeholder-lease-revoked-and-intent-kept-over-20s");

            // ④ 普通客户端租约**真正到期**仍执行原安全策略。
            var l2Engine = new FanHostEngine(r1Options, new HostDiagnosticLog(tempDir));
            _ = l2Engine.Open();
            _ = l2Engine.OpenEvents();
            _ = l2Engine.AcquireControl();
            HostDiagnosticLog.ResetSelfTestCapture();
            l2Engine.ExpireCurrentLeaseForSelfTest();
            if (EventCountMatching("restore.mock-applied", "\"cause\":\"lease-expiry\"") < 1 ||
                l2Engine.Snapshot().Lease is not null)
                throw new InvalidOperationException("L2: 普通客户端租约真正到期必须仍执行原释放策略（lease-expiry release）");
            checks.Add("l2-client-lease-real-expiry-keeps-original-safety-release");

            // ⑤ 迟到/异身份回调不得处置新租约；同租约但**未到期**的回调也不得提前释放。
            var l3Engine = new FanHostEngine(r1Options, new HostDiagnosticLog(tempDir));
            _ = l3Engine.Open();
            _ = l3Engine.OpenEvents();
            var l3Lease = l3Engine.AcquireControl();
            HostDiagnosticLog.ResetSelfTestCapture();
            l3Engine.ExpireLeaseWithStaleIdentityForSelfTest();
            if (!EventSeen("lease.expiry-callback-stale"))
                throw new InvalidOperationException("L2: 异身份到期回调必须被识别为 stale");
            if (l3Engine.Snapshot().Lease?.LeaseId != l3Lease.LeaseId ||
                l3Engine.Snapshot().State != "Ready")
                throw new InvalidOperationException("L2: 异身份到期回调不得撤销现有租约或改变状态");
            if (EventCountMatching("restore.mock-applied", "\"cause\":\"lease-expiry\"") != 0)
                throw new InvalidOperationException("L2: 异身份到期回调不得触发任何租约到期释放");
            checks.Add("l2-stale-expiry-callback-cannot-touch-current-lease-or-cycle");

            // ⑥ superseded 不记假成功（§3.2.7）：慢重建窗口内到达的新睡眠必须胜过旧恢复。
            var r2Options = HostOptions.Parse(new[] { "--port", "8798", "--mock-handshake", "--mock-resume-rebuild-delay-ms", "1500" });
            var supersedeEngine = new FanHostEngine(r2Options, new HostDiagnosticLog(tempDir));
            _ = supersedeEngine.Open();
            _ = supersedeEngine.OpenEvents();
            _ = supersedeEngine.SuspendForSystemPower();
            if (supersedeEngine.Snapshot().State != "Suspended")
                throw new InvalidOperationException($"L3: 夹具未进入 Suspended（state={supersedeEngine.Snapshot().State}）");
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = supersedeEngine.ResumeForSystemPower();
            Thread.Sleep(300);   // 让 worker 进入注入的慢重建窗口
            _ = supersedeEngine.SuspendForSystemPower();
            var supersedeDeadline = Stopwatch.StartNew();
            while (supersedeDeadline.ElapsedMilliseconds < 10_000 &&
                   supersedeDeadline.ElapsedMilliseconds < 10_000 && supersedeEngine.Snapshot().PowerState != "Suspended")
                Thread.Sleep(50);
            Thread.Sleep(1800);  // 覆盖注入的慢重建窗口：旧 worker 必须已结算且不得再记成功
            if (EventSeen("power.resume-auto-rebuild.success"))
                throw new InvalidOperationException("L3: 被新睡眠取代的恢复不得记成功");
            var supersedeFinal = supersedeEngine.Snapshot();
            if (supersedeFinal.PowerOperationStatus != "superseded")
                throw new InvalidOperationException(
                    $"L3: 被取代的恢复必须只结算自己的 attempt 为 superseded（opStatus={supersedeFinal.PowerOperationStatus}）");
            if (supersedeFinal.State != "Suspended")
                throw new InvalidOperationException($"L3: 新睡眠必须保有终态（state={supersedeFinal.State}）");
            checks.Add("l3-superseded-resume-reports-no-false-success");

            // ---------------- T2：Open 前置失败后睡眠（OpenCalled=true，未越过 HC 调用边界） ----------------
            var t2Engine = new FanHostEngine(options, new HostDiagnosticLog(tempDir));
            _ = t2Engine.Open();
            if (!t2Engine.Snapshot().OpenCalled)
                throw new InvalidOperationException("T2: 夹具未建立 OpenCalled=true");
            if (!t2Engine.HcSessionNeverEnteredForSelfTest())
                throw new InvalidOperationException("T2: Open 前置失败态必须仍判定为未进入会话");
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = t2Engine.Suspend(JsonDocument.Parse("{}").RootElement);
            var t2 = t2Engine.Snapshot();
            if (!EventDetails("power.suspend-no-session-complete").Contains("pre-open-check-failed", StringComparison.Ordinal))
                throw new InvalidOperationException("T2: reason 应为 pre-open-check-failed");
            if (t2.State != "Suspended" || t2.PowerState != "Suspended")
                throw new InvalidOperationException("T2: 未直接完成 Suspended");
            if (t2.LastError is not null && t2.LastError.Contains("HC_CLOSE_PENDING", StringComparison.Ordinal))
                throw new InvalidOperationException("T2: 不得出现 HC_CLOSE_PENDING");
            RequireNoEvent("recovery.retry-scheduled", "T2");
            RequireNoEvent("hc-close.virtual-device.begin", "T2");
            checks.Add("t2-preopen-failure-suspend-short-circuit");

            // ---------------- T4：正常 Open/OpenEvents 后睡眠（**不得**短路） ----------------
            var t4Engine = new FanHostEngine(options, new HostDiagnosticLog(tempDir));
            _ = t4Engine.Open();
            _ = t4Engine.OpenEvents();
            if (t4Engine.HcSessionNeverEnteredForSelfTest())
                throw new InvalidOperationException("T4: OpenEvents 之后不得判定为未进入会话");
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = t4Engine.SuspendForSystemPower();
            var t4 = t4Engine.Snapshot();
            if (!EventSeen("power.suspend-hc-close-first-begin"))
                throw new InvalidOperationException("T4: 正常会话必须走既有 close-first 路径");
            RequireNoEvent("power.suspend-no-session-complete", "T4");
            RequireNoEvent("recovery.retry-scheduled", "T4");
            if (t4.State != "Suspended" || t4.PowerState != "Suspended")
                throw new InvalidOperationException("T4: 正常会话睡眠终态错误");
            checks.Add("t4-normal-open-suspend-unchanged");

            // ---------------- T3：Open 已开始但 OpenEvents 失败（C 族契约，整链） ----------------
            // C 族在 Safe 构建不可达（openAttempted && hcOpenInvocationStarted 需要真实 HC
            // device 覆写）。此处覆盖 C 族的**完整判定链**（生产侧只调用这三个纯函数 +
            // ObserveManagerFactoryLifecycle，无第二份判定）：观测是否需要 → 观测结果分类
            // → 清理结论。**HcVirtualCloseReturned 单独不足以确认**由 ② 显式证明。
            if (!RealHcBackend.ShouldObserveManagerAfterClose(false, true))
                throw new InvalidOperationException("T3①: C 族（从未观测 + 虚拟 Close 已返回）必须允许补做一次只读观测");
            if (RealHcBackend.ShouldObserveManagerAfterClose(false, false))
                throw new InvalidOperationException("T3①: 虚拟 Close 未返回时不应补做观测");
            if (!RealHcBackend.ShouldObserveManagerAfterClose(true, false))
                throw new InvalidOperationException("T3①: 已观测过的会话必须保持既有重观测语义");
            // ② 观测不可读 + 虚拟 Close 已返回 ⇒ 仍必须 PendingCloseCleanup（不得用返回值代替确认）
            if (RealHcBackend.DecideManagerCleanupAfterClose(
                    false, true, RealHcBackend.ManagerObservationOutcome.Unreadable) !=
                RealHcBackend.ManagerCleanupOutcome.PendingCloseCleanup)
                throw new InvalidOperationException("T3②: 观测不可读时不得据 HcVirtualCloseReturned 确认清理");
            // ③ 观测到"无 Active manager" ⇒ Confirmed
            if (RealHcBackend.DecideManagerCleanupAfterClose(
                    false, true, RealHcBackend.ManagerObservationOutcome.ObservedClean) !=
                RealHcBackend.ManagerCleanupOutcome.Confirmed)
                throw new InvalidOperationException("T3③: 观测到无 Active manager 必须确认清理");
            // ④ Active / Faulted / NotAttempted ⇒ PendingCloseCleanup
            foreach (var bad in new[]
            {
                RealHcBackend.ManagerObservationOutcome.ObservedActive,
                RealHcBackend.ManagerObservationOutcome.ObservedFaulted,
                RealHcBackend.ManagerObservationOutcome.NotAttempted,
            })
            {
                if (RealHcBackend.DecideManagerCleanupAfterClose(false, true, bad) !=
                    RealHcBackend.ManagerCleanupOutcome.PendingCloseCleanup)
                    throw new InvalidOperationException($"T3④: {bad} 不得被确认为已清理");
            }
            // ⑤ 观测结果分类（真实 lifecycles → 分类）逐格验证
            if (RealHcBackend.DescribeManagerObservation("Started", "Started") !=
                    RealHcBackend.ManagerObservationOutcome.ObservedClean ||
                RealHcBackend.DescribeManagerObservation("Started", "Active") !=
                    RealHcBackend.ManagerObservationOutcome.ObservedActive ||
                RealHcBackend.DescribeManagerObservation("Faulted", "Started") !=
                    RealHcBackend.ManagerObservationOutcome.ObservedFaulted ||
                RealHcBackend.DescribeManagerObservation("Unknown", "Unknown") !=
                    RealHcBackend.ManagerObservationOutcome.ObservedFaulted)
                throw new InvalidOperationException("T3⑤: 观测结果分类与既有语义不一致（Unknown 必须 fail-closed）");
            // ⑥ 已确认过的会话重观测仍按既有语义（observed=true 时不看 Close 返回值）
            if (RealHcBackend.DecideManagerCleanupAfterClose(
                    true, false, RealHcBackend.ManagerObservationOutcome.ObservedClean) !=
                RealHcBackend.ManagerCleanupOutcome.Confirmed)
                throw new InvalidOperationException("T3⑥: 已观测会话的既有重观测语义被改动");
            checks.Add("t3-partial-open-cleanup-observation-contract");

            // ---------------- T9：FaultLocked 后令牌条件式释放（H3） ----------------
            var t9Engine = new FanHostEngine(options, new HostDiagnosticLog(tempDir));
            t9Engine.InjectUncertainStateForSelfTest();
            t9Engine.MarkSystemSuspendPending();
            if (!t9Engine.IsSystemSuspendPendingForSelfTest)
                throw new InvalidOperationException("T9: 夹具未发布睡眠保护令牌");
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = t9Engine.Suspend(JsonDocument.Parse("{}").RootElement);
            var t9 = t9Engine.Snapshot();
            if (t9.State != "FaultLocked")
                throw new InvalidOperationException($"T9: 夹具未进入 FaultLocked（state={t9.State}）");
            if (!EventSeen("power.fault-locked"))
                throw new InvalidOperationException("T9: 进入 FaultLocked 必须写免门故障记录 power.fault-locked");
            if (!EventSeen("power.suspend-protection-released-unresolvable"))
                throw new InvalidOperationException("T9: 无 Close 义务时必须释放滞留的睡眠保护令牌");
            if (t9Engine.IsSystemSuspendPendingForSelfTest)
                throw new InvalidOperationException("T9: 令牌未被释放（仍滞留 ⇒ 应用内无释放路径）");
            // H3 错误码：FaultLocked 判定必须先于令牌 ⇒ 必须是 FAULT_LOCKED 而非 POWER_SUSPENDING
            try
            {
                _ = t9Engine.Open();
                throw new InvalidOperationException("T9: FaultLocked 下 Open 必须被拒");
            }
            catch (FanApiException ex) when (ex.Code == "FAULT_LOCKED") { }
            catch (FanApiException ex)
            {
                throw new InvalidOperationException($"T9: 错误码应为 FAULT_LOCKED，实际 {ex.Code}");
            }
            // 守卫的拒绝方向（有 Close 义务 ⇒ 一律不得释放；非当前记录实例 ⇒ 不得释放）
            if (FanHostEngine.MayReleaseUnresolvableSuspendProtection(true, true))
                throw new InvalidOperationException("T9: 有 Close 义务时不得释放令牌");
            if (FanHostEngine.MayReleaseUnresolvableSuspendProtection(false, false))
                throw new InvalidOperationException("T9: 记录实例已不是本次睡眠那条时不得释放");
            if (!FanHostEngine.MayReleaseUnresolvableSuspendProtection(true, false))
                throw new InvalidOperationException("T9: 记录仍是本次实例且无 Close 义务时应允许释放");
            // 守卫的**端到端**拒绝方向（Gap5 闭环）：Safe 构建无 HC 后端 ⇒
            // HcCloseIsOwed 恒 false，故用注入"本 Host 仍欠一次 HC Close"的方式，
            // 在**同一生产释放方法**上证明：有义务 ⇒ 令牌必须存活；无义务 ⇒ 才释放。
            var t9bEngine = new FanHostEngine(options, new HostDiagnosticLog(tempDir));
            t9bEngine.InjectUncertainStateForSelfTest();
            t9bEngine.MarkSystemSuspendPending();
            _ = t9bEngine.Suspend(JsonDocument.Parse("{}").RootElement);
            if (t9bEngine.Snapshot().State != "FaultLocked")
                throw new InvalidOperationException("T9b: 夹具未进入 FaultLocked");
            t9bEngine.SetHcCloseOwedForSuspendReleaseForSelfTest(true);
            HostDiagnosticLog.ResetSelfTestCapture();
            _ = t9bEngine.Suspend(JsonDocument.Parse("{}").RootElement);
            if (!t9bEngine.IsSystemSuspendPendingForSelfTest)
                throw new InvalidOperationException("T9b: 有 Close 义务时令牌被释放（必须存活，留给真正的 Close 边界）");
            if (EventSeen("power.suspend-protection-released-unresolvable"))
                throw new InvalidOperationException("T9b: 有 Close 义务时不得写 released 事件");
            t9bEngine.SetHcCloseOwedForSuspendReleaseForSelfTest(false);
            _ = t9bEngine.Suspend(JsonDocument.Parse("{}").RootElement);
            if (t9bEngine.IsSystemSuspendPendingForSelfTest)
                throw new InvalidOperationException("T9b: 无 Close 义务时令牌必须被释放");
            checks.Add("t9-fault-locked-releases-protection-conditionally");

            // ---------------- T7：resume no-op（HTTP 200 + resumeNoop/reason） ----------------
            var t7Options = HostOptions.Parse(new[] { "--port", "8796" });
            var t7Engine = new FanHostEngine(t7Options, new HostDiagnosticLog(tempDir));
            using (var t7Server = new LocalFanHostServer(t7Engine, t7Options, new HostDiagnosticLog(tempDir)))
            {
                var worker = t7Server.StartPowerWorkerForSelfTest();
                try
                {
                    // --- 引擎级 no-op（H4 核心契约）：已不在 Suspended ⇒ 返回
                    // Kind="noop"、不抛错（HTTP 200 语义），并携带当前 state 快照。
                    var noopAdmission = t7Engine.ResumeForSystemPowerWithAdmission(99, -1, -1);
                    if (noopAdmission.Kind != "noop")
                        throw new InvalidOperationException($"T7: 未处于 Suspended 的恢复应为 noop，实际 Kind={noopAdmission.Kind}");
                    if (noopAdmission.Snapshot is null)
                        throw new InvalidOperationException("T7: no-op 必须携带当前 state 快照（HTTP 200 兼容）");
                    // 真恢复响应形状：保留既有 ok/state，且不得被标注为 no-op
                    var realShape = ToJson(LocalFanHostServer.ShapeResumeResponse(false, null, t7Engine.Snapshot()));
                    if (!realShape.TryGetProperty("ok", out var rk) || rk.GetBoolean() != true ||
                        !realShape.TryGetProperty("state", out _) ||
                        (realShape.TryGetProperty("resumeNoop", out var rn) && rn.GetBoolean()))
                        throw new InvalidOperationException("T7: 真恢复响应必须保留 ok/state 且不标注 resumeNoop");
                    // no-op 响应形状：ok:true + resumeNoop:true + reason + state（字段兼容）
                    var noopShape = ToJson(LocalFanHostServer.ShapeResumeResponse(true, "not-suspended", t7Engine.Snapshot()));
                    if (!noopShape.TryGetProperty("ok", out var nk) || nk.GetBoolean() != true ||
                        !noopShape.TryGetProperty("resumeNoop", out var nn) || nn.GetBoolean() != true ||
                        !noopShape.TryGetProperty("reason", out var nr) || nr.GetString() != "not-suspended" ||
                        !noopShape.TryGetProperty("state", out _))
                        throw new InvalidOperationException("T7: no-op 响应必须为 ok:true + resumeNoop:true + reason + state（HTTP 200 兼容）");

                    // --- 真 /api/resume 集成（真恢复路径字段兼容）：建立真实睡眠边沿后
                    // 走完整 HTTP 层；响应必须是既有 ok/state 且**不**被标注为 no-op。
                    _ = await t7Server.SuspendForSelfTest().ConfigureAwait(false);
                    if (t7Engine.Snapshot().State != "Suspended")
                        throw new InvalidOperationException("T7: 夹具未进入 Suspended");
                    var real = ToJson(await t7Server.ResumeForSelfTest().ConfigureAwait(false));
                    if (!real.TryGetProperty("ok", out var realOk) || realOk.GetBoolean() != true ||
                        !real.TryGetProperty("state", out _))
                        throw new InvalidOperationException("T7: 真恢复响应必须保留 ok/state");
                    if (real.TryGetProperty("resumeNoop", out var realNoop) && realNoop.GetBoolean())
                        throw new InvalidOperationException("T7: 真恢复不得被标注为 resumeNoop");

                    // --- HTTP 级 **真 no-op**（Gap3 闭环）：让 ingress 接受该边沿
                    // （announced=Suspended → target=Ready），而引擎已不在 Suspended ⇒
                    // admission.Kind=noop ⇒ 生产 HTTP 层必须返回 ok:true + resumeNoop=true
                    // + reason="not-suspended"（N18 的修复点，端到端）。
                    var nextGen = t7Server.ObservedPowerGenerationForSelfTest + 1;
                    _ = await t7Server.SuspendForSelfTest(nextGen).ConfigureAwait(false);
                    if (t7Engine.Snapshot().State != "Suspended")
                        throw new InvalidOperationException("T7: 第二次睡眠夹具未进入 Suspended");
                    // Host 自身 Windows 观察者先完成恢复（不改 ingress 的 announced 边沿）
                    _ = t7Engine.ResumeForSystemPower();
                    if (t7Engine.Snapshot().State == "Suspended")
                        throw new InvalidOperationException("T7: Host 侧恢复未完成");
                    var noopHttp = ToJson(await t7Server.ResumeForSelfTest().ConfigureAwait(false));
                    if (!noopHttp.TryGetProperty("ok", out var nok) || nok.GetBoolean() != true)
                        throw new InvalidOperationException("T7: no-op resume HTTP 必须仍返回 ok:true（200）");
                    if (!noopHttp.TryGetProperty("resumeNoop", out var nnoop) || nnoop.GetBoolean() != true)
                        throw new InvalidOperationException("T7: 真 no-op 响应必须标注 resumeNoop=true");
                    if (!noopHttp.TryGetProperty("reason", out var nreason) ||
                        nreason.GetString() != "not-suspended")
                        throw new InvalidOperationException($"T7: 真 no-op 的 reason 应为 not-suspended，实际 {nreason.GetString()}");
                    if (!noopHttp.TryGetProperty("state", out _))
                        throw new InvalidOperationException("T7: no-op 响应必须保留既有 state 字段（兼容）");
                    checks.Add("t7-resume-noop-explicit-200");

                    // --- Q1（2026-09-23 补充裁决）HTTP 级**接受契约**：接受与后台重建分离。
                    // 真实睡眠边沿之后调用 /api/resume：响应必须是"已接纳"形状
                    // （resumeAccepted=true + resumePhase + generation + retryAfterMs），
                    // 空曲线同步完成时阶段必须是 AwaitingControl（**绝不**撒谎成 Ready），
                    // 且响应携带带 resumePhase 的状态快照（调用方按同一代次有界观察）。
                    var acceptGen = t7Server.ObservedPowerGenerationForSelfTest + 1;
                    _ = await t7Server.SuspendForSelfTest(acceptGen).ConfigureAwait(false);
                    if (t7Engine.Snapshot().State != "Suspended")
                        throw new InvalidOperationException("Q1: 接受契约夹具未进入 Suspended");
                    var acceptedResp = ToJson(await t7Server.ResumeForSelfTest().ConfigureAwait(false));
                    if (!acceptedResp.TryGetProperty("resumeAccepted", out var acceptedFlag) || acceptedFlag.GetBoolean() != true)
                        throw new InvalidOperationException("Q1: /api/resume 接受响应必须携带 resumeAccepted=true");
                    if (acceptedResp.TryGetProperty("resumeNoop", out var acceptedNoop) && acceptedNoop.GetBoolean())
                        throw new InvalidOperationException("Q1: 已接纳的真实转换不得标注 resumeNoop");
                    if (!acceptedResp.TryGetProperty("resumePhase", out var acceptedPhase) || acceptedPhase.GetString() != "AwaitingControl")
                        throw new InvalidOperationException(
                            "Q1: 空曲线恢复的接受阶段应为 AwaitingControl，实际 " +
                            $"{acceptedPhase.GetString()} attempt={acceptedResp.GetProperty("attempt").GetInt64()} " +
                            $"continuable={acceptedResp.TryGetProperty("continuable", out var cont) && cont.GetBoolean()} " +
                            $"state={acceptedResp.GetProperty("state").GetProperty("state").GetString()} " +
                            $"powerState={acceptedResp.GetProperty("state").GetProperty("powerState").GetString()} " +
                            $"opStatus={acceptedResp.GetProperty("state").GetProperty("powerOperationStatus").GetString()}");
                    if (!acceptedResp.TryGetProperty("retryAfterMs", out var retryAfter) || retryAfter.GetInt32() <= 0)
                        throw new InvalidOperationException("Q1: 接受响应必须给出 retryAfterMs");
                    if (!acceptedResp.TryGetProperty("generation", out var acceptedGeneration) || acceptedGeneration.GetInt64() <= 0)
                        throw new InvalidOperationException("Q1: 接受响应必须回显 generation");
                    if (!acceptedResp.TryGetProperty("state", out var acceptedState) ||
                        !acceptedState.TryGetProperty("resumePhase", out var statePhase) ||
                        statePhase.GetString() != "AwaitingControl")
                        throw new InvalidOperationException("Q1: 接受响应必须携带带 resumePhase 的状态快照");
                    if (FanHostEngine.DeriveResumePhase(t7Engine.Snapshot()) != "AwaitingControl")
                        throw new InvalidOperationException("Q1: 同步完成的空恢复阶段必须是 AwaitingControl（不得写成 Ready）");
                    checks.Add("q1-resume-accept-separated-from-rebuild");
                }
                finally
                {
                    t7Server.Dispose();
                    try { await worker.ConfigureAwait(false); } catch (OperationCanceledException) { }
                }
            }

            // ---------------- T8：日志开关（免门白名单 + 门权威） ----------------
            // Host 侧可确定验证的部分：门关闭时白名单故障事件仍必须落盘，非白名单事件
            // 一律不落盘；门开启时普通事件进入 runtime 日志。native 侧"缺 enabled 键不得
            // 默认覆盖为 false"是 C++ 改动（main.cpp fanLog.setEnabled），由源码评审 +
            // 真机步骤验证，不在本 .NET 自测范围内（见交付说明）。
            var t8Dir = System.IO.Path.Combine(tempDir, "t8");
            Directory.CreateDirectory(t8Dir);
            var t8Log = new HostDiagnosticLog(t8Dir);
            t8Log.Write("recovery.retry-terminal", new { reason = "selftest-t8" });
            t8Log.Write("engine.created", new { selftest = true });
            var t8FaultPath = System.IO.Path.Combine(t8Dir, "fan-host-fault.log");
            var t8RuntimePath = System.IO.Path.Combine(t8Dir, "yeman-fan-host-runtime.log");
            if (!File.Exists(t8FaultPath) ||
                !File.ReadAllText(t8FaultPath).Contains("recovery.retry-terminal", StringComparison.Ordinal))
                throw new InvalidOperationException("T8: 门关闭时白名单故障事件未落 fan-host-fault.log");
            if (File.Exists(t8RuntimePath) &&
                File.ReadAllText(t8RuntimePath).Contains("engine.created", StringComparison.Ordinal))
                throw new InvalidOperationException("T8: 门关闭时非白名单事件不得落 runtime 日志");
            File.WriteAllText(System.IO.Path.Combine(t8Dir, "fan-logging-enabled.flag"), "enabled");
            t8Log.Write("engine.created", new { selftest = true });
            if (!File.Exists(t8RuntimePath) ||
                !File.ReadAllText(t8RuntimePath).Contains("engine.created", StringComparison.Ordinal))
                throw new InvalidOperationException("T8: 门开启后普通事件必须进入 runtime 日志");
            checks.Add("t8-gate-free-fault-ledger-and-gate-authority");

            // ---------------- Q1/Q2（2026-09-23 补充裁决）：阶段真值 + 写入收据口径（纯函数） ----------------
            // Q1 四态契约：Ready/Resuming/Suspended/FaultLocked 必须精确；Ready+待清理不得读成
            // Ready；其余状态按名透传（诚实）。
            HostState PhaseProbe(string st, string ps, bool unknown, bool pending, string? opStatus = null) => new HostState
            {
                State = st,
                PowerState = ps,
                UnknownState = unknown,
                HcCloseCleanupPending = pending,
                PowerOperationStatus = opStatus,
            };
            if (FanHostEngine.DeriveResumePhase(PhaseProbe("Ready", "On", false, false)) != "Ready" ||
                FanHostEngine.DeriveResumePhase(PhaseProbe("Resuming", "On", false, false, "executing")) != "Resuming" ||
                FanHostEngine.DeriveResumePhase(PhaseProbe("Ready", "On", false, false, "pending")) != "Resuming" ||
                FanHostEngine.DeriveResumePhase(PhaseProbe("Suspended", "Suspended", false, false)) != "Suspended" ||
                FanHostEngine.DeriveResumePhase(PhaseProbe("FaultLocked", "Unknown", true, false)) != "FaultLocked" ||
                FanHostEngine.DeriveResumePhase(PhaseProbe("ListenerFaultLocked", "On", false, false)) != "FaultLocked" ||
                FanHostEngine.DeriveResumePhase(PhaseProbe("AwaitingControl", "On", false, false)) != "AwaitingControl" ||
                FanHostEngine.DeriveResumePhase(PhaseProbe("Ready", "On", false, true)) == "Ready")
                throw new InvalidOperationException("Q1: 恢复阶段派生不符合四态契约");
            if (FanHostEngine.IsControlAccepting(PhaseProbe("Resuming", "On", false, false, "executing")) ||
                FanHostEngine.IsControlAccepting(PhaseProbe("FaultLocked", "Unknown", true, false)) ||
                FanHostEngine.IsControlAccepting(PhaseProbe("Ready", "On", false, true)) ||
                !FanHostEngine.IsControlAccepting(PhaseProbe("Ready", "On", false, false)) ||
                !FanHostEngine.IsControlAccepting(PhaseProbe("AwaitingControl", "On", false, false)))
                throw new InvalidOperationException("Q1: 控制可发送性派生不符合契约");
            checks.Add("q1-resume-phase-derivation");

            // Q2：partial/unknown 写入收据**不得**读成"完全成功"（enable/restore 同一映射）。
            if (RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("partial", "d", false, false, false, 2)) != "partial-channel-evidence-not-success" ||
                RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("transported", "d", false, false, false, 3)) != "transported" ||
                RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("no-receipts", "d", false, true, true, 0)) != "unknown-not-verified-no-receipts" ||
                RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("unsupported", "d", false, false, false, 0)) != "unsupported-no-scope-capability" ||
                RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("initiated-failed", "d", true, false, true, 1)) != "failed-write-not-established" ||
                new HostState().LastControlWriteEvidence != "none")
                throw new InvalidOperationException("Q2: partial/unknown 写入收据不得读成完全成功");
            checks.Add("q2-write-evidence-name-mapping");

            // Q2b（FAN-934 §4.A）：非 ASUS 兼容路线回调合同证据的命名必须显式标注"非物理确认"，
            // 且 ASUS 声明支持 scope 却读不到 API 的 `receipt-api-fault` 不得被洗成兼容成功。
            if (RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("compat-route-without-scope", "d", false, false, true, 0)) != "compat-route-callback-returned-no-scope" ||
                RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("compat-route-callback-not-returned", "d", true, false, true, 0)) != "failed-write-not-established" ||
                RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("compat-route-precondition-unsatisfied", "d", false, true, true, 0)) != "unknown-not-verified-compat-precondition" ||
                RealHcBackend.WriteEvidenceName(new RealHcBackend.AsusWriteVerdict("receipt-api-fault", "d", false, true, true, 0)) != "unknown-not-verified-receipt-api-fault")
                throw new InvalidOperationException("Q2b: 非 ASUS 回调合同/receipt-api-fault 证据命名不得冒充物理成功");
            checks.Add("q2b-compat-route-evidence-name-mapping");

            // ---------------- T10（未执行，只固化操作法与断言） ----------------
            checks.Add("t10-real-machine-procedure-documented-not-executed");

            // 原始输出（交付要求）：把本套件捕获到的关键事件逐条打印。
            Console.WriteLine("[P1-adjudication] captured events:");
            foreach (var entry in HostDiagnosticLog.SelfTestCaptured)
                Console.WriteLine($"  - {entry.Event} {entry.Details}");
            Console.WriteLine($"[T10] 真机操作法与断言（未执行）:{Environment.NewLine}{T10RealMachineProcedure}");
        }
        finally
        {
            HostDiagnosticLog.SelfTestCaptureEnabled = false;
            try { if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true); } catch { }
        }
        return checks;
    }

    /**
     * 裁决 P-4 C（2026-09-24）：**生产上限（2 MiB）的连续轮转 + 淘汰**读数。
     *
     * 与 `RunRuntimeLogRotationSelfTest` 的区别：那条用 4 KiB 的小上限（快、验语义），
     * 本条用**生产常量** `DefaultRuntimeMaxBytes = 2 MiB` 真实写盘到临时目录，连续写超过
     * **4 个 active 上限**的字节量，从而必然触发 ≥3 次轮转，用来证明：
     *   ① active ≤ 2 MiB（+单行容差）；
     *   ② 归档数恒 ≤ 3（RuntimeArchiveKeep）；
     *   ③ **超量会淘汰最旧归档**（写第 4 个归档时，第 1 个必须消失——既有自测只断言 ≤3）；
     *   ④ 全部归档仍是可读 JSONL，且归档序号单调递增（不复用/不覆盖）。
     * 不触发真实睡眠、不碰设备、不写用户 %LOCALAPPDATA% 日志（临时目录，结束即删）。
     */
    private static IReadOnlyList<string> RunRuntimeLogRotationProductionCapSelfTest()
    {
        var checks = new List<string>();
        var root = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "yemancc-selftest-p4cap-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var cap = HostDiagnosticLog.DefaultRuntimeMaxBytes;
        try
        {
            File.WriteAllText(System.IO.Path.Combine(root, "fan-logging-enabled.flag"), "enabled");
            var log = new HostDiagnosticLog(root, 0); // 0 ⇒ 用生产上限
            if (cap != 2 * 1024 * 1024) throw new InvalidOperationException($"P-4C: 生产上限常量异常 cap={cap}");
            // 受保护事件（/api/open）永不被降采样 ⇒ 每一行都会真实落盘。
            // 目标：写入 > 4×cap 的字节量 ⇒ 至少 4 次轮转 ⇒ 必然发生淘汰。
            var targetBytes = cap * 4 + cap / 2;
            var written = 0L; var index = 0;
            while (written < targetBytes)
            {
                index++;
                var marker = $"p4cap-{index:D6}";
                log.Write("api.request-success", new
                {
                    requestId = marker,
                    method = "POST",
                    path = "/api/open",
                    state = "Ready",
                    durationMs = 1.0,
                    httpStatus = 200,
                    // 填充到 ~700 B/行，使总写入量可控且每行都远小于上限。
                    padding = new string('x', 400),
                });
                written += 700;
            }
            var active = System.IO.Path.Combine(root, "yeman-fan-host-runtime.log");
            var activeBytes = new FileInfo(active).Length;
            var archives = Directory.EnumerateFiles(root, "yeman-fan-host-runtime.*.log").ToList();
            var all = Directory.EnumerateFiles(root, "yeman-fan-host-runtime*.log").ToList();
            var inventory = string.Join("; ", all.OrderBy(f => f, StringComparer.Ordinal)
                .Select(f => System.IO.Path.GetFileName(f) + "=" + new FileInfo(f).Length + "B"));
            if (activeBytes > cap + 1024)
                throw new InvalidOperationException($"P-4C①: active 超上限 active={activeBytes} cap={cap}");
            checks.Add($"p4-production-cap-active-within-limit activeBytes={activeBytes} cap={cap} written≈{written}");
            if (archives.Count != HostDiagnosticLog.RuntimeArchiveKeepForSelfTest)
                throw new InvalidOperationException($"P-4C②: 归档数不等于保留上限 archives={archives.Count} keep={HostDiagnosticLog.RuntimeArchiveKeepForSelfTest} assert=P4C-archives-at-keep-limit");
            checks.Add($"p4-production-cap-archives-at-keep-limit archives={archives.Count}");
            // ③ 淘汰：第一行标记必须已经从**所有**文件里消失（说明最旧归档被删了，而不是被保留）。
            var firstMarker = "p4cap-000001";
            var stillThere = all.Any(f => File.ReadAllText(f).Contains(firstMarker, StringComparison.Ordinal));
            if (stillThere)
                // 断言文本带 ASCII 标记：负例判定必须在**控制台编码损坏**时也能匹配（实测 .err 里中文会乱码）。
                throw new InvalidOperationException($"P-4C③: 超量轮转没有淘汰最旧归档（首个写入标记仍在盘上） evictedMarker={firstMarker} stillPresent=true archives={archives.Count}");
            checks.Add("p4-production-cap-oldest-archive-evicted");
            // ④ 归档序号单调递增且内容是可读 JSONL
            var indexes = archives.Select(f =>
            {
                var n = System.IO.Path.GetFileNameWithoutExtension(f);
                var dot = n.LastIndexOf('.');
                return int.Parse(n.Substring(dot + 1));
            }).OrderBy(v => v).ToArray();
            if (indexes.Distinct().Count() != indexes.Length || indexes.Length == 0)
                throw new InvalidOperationException($"P-4C④: 归档序号异常 [{string.Join(',', indexes)}]");
            foreach (var f in all)
                foreach (var line in File.ReadAllLines(f))
                    if (line.Length > 0 && !line.Contains("\"eventName\":\"api.request-success\"", StringComparison.Ordinal))
                        throw new InvalidOperationException($"P-4C④: 归档内容不是可读 JSONL: {System.IO.Path.GetFileName(f)}");
            checks.Add($"p4-production-cap-archive-indexes-monotonic [{string.Join(',', indexes)}]");
            Console.WriteLine($"[P-4C] production-cap rotation inventory: {inventory}");
            Console.WriteLine($"[P-4C] activeBytes={activeBytes} cap={cap} archives={archives.Count} keep={HostDiagnosticLog.RuntimeArchiveKeepForSelfTest} evicted={firstMarker}");
        }
        finally
        {
            try { Directory.Delete(root, recursive: true); } catch { }
        }
        return checks;
    }

    /**
     * FAN-931 P0：请求入口**有限计数**的形状与归类自测（承重）。
     * ① 调用者归类按 UA 启发式（bridge=WebView2/Edg、native=自建 WinHTTP UA、其余 other/unknown）；
     * ② 未知路径进 other 槽，矩阵不因新路径增长（仍固定 (KnownPaths+1)×4）；
     * ③ 快照含全部诊断字段，且**不含**任何 token/lease/凭据键。
     */
    internal static IReadOnlyList<string> RunPerfCountersSelfTest()
    {
        var checks = new List<string>();
        void Assert(bool ok, string message)
        {
            if (!ok) throw new InvalidOperationException("fan931-p0-selftest FAILED: " + message);
        }

        static long PathTotal(JsonElement root, string path)
        {
            foreach (var entry in root.GetProperty("paths").EnumerateArray())
                if (entry.GetProperty("path").GetString() == path) return entry.GetProperty("total").GetInt64();
            return -1;
        }

        static long PathClient(JsonElement root, string path, string client)
        {
            foreach (var entry in root.GetProperty("paths").EnumerateArray())
            {
                if (entry.GetProperty("path").GetString() != path) continue;
                return entry.GetProperty("byClient").TryGetProperty(client, out var value) ? value.GetInt64() : 0;
            }
            return -1;
        }

        var before = JsonSerializer.SerializeToElement(FanPerfCounters.Snapshot(), JsonDefaults.Options);
        FanPerfCounters.RecordRequest("/api/heartbeat", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Edg/131.0 WebView2/1.0");
        FanPerfCounters.RecordRequest("/api/heartbeat", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0 Safari/537.36");
        FanPerfCounters.RecordRequest("/api/unknown-route-xyz", "curl/8.0");
        FanPerfCounters.RecordRequest("/api/state", null);
        var after = JsonSerializer.SerializeToElement(FanPerfCounters.Snapshot(), JsonDefaults.Options);

        Assert(after.GetProperty("paths").GetArrayLength() == before.GetProperty("paths").GetArrayLength(),
            "the path table must be fixed-size and never grow with new routes");
        Assert(PathTotal(after, "/api/heartbeat") - PathTotal(before, "/api/heartbeat") == 2,
            "two heartbeat requests must be counted on the known path slot");
        Assert(PathClient(after, "/api/heartbeat", "bridge") - PathClient(before, "/api/heartbeat", "bridge") == 1 &&
               PathClient(after, "/api/heartbeat", "native") - PathClient(before, "/api/heartbeat", "native") == 1,
            "the WebView2 UA must classify as bridge and the self-built WinHTTP UA as native");
        Assert(PathClient(after, "/api/heartbeat", "other") - PathClient(before, "/api/heartbeat", "other") == 0,
            "a known path must not be double-counted into the other bucket");
        Assert(PathTotal(after, "other") - PathTotal(before, "other") == 1 &&
               PathClient(after, "other", "other") - PathClient(before, "other", "other") == 1,
            "an unknown path must land in the bounded other slot");
        Assert(PathClient(after, "/api/state", "unknown") - PathClient(before, "/api/state", "unknown") == 1,
            "a request without a User-Agent must classify as unknown");
        foreach (var field in new[]
        {
            "diagnosticContextBuilds", "staVerifyRequests", "parentIdentityReads", "loopStopAttempts",
            "loopStopRequests", "loopStopAlreadyPending", "runtimeSamplesRecorded", "runtimeSamplesSkipped",
            "runtimeStatusReads",
        })
            Assert(after.TryGetProperty(field, out _), $"the snapshot must expose {field}");
        // 只查**字段名**（路径值里 `release-control` 含 "lease" 是合法路由名，不是秘密字段）。
        static IEnumerable<string> KeyNames(JsonElement element)
        {
            switch (element.ValueKind)
            {
                case JsonValueKind.Object:
                    foreach (var property in element.EnumerateObject())
                    {
                        yield return property.Name;
                        foreach (var nested in KeyNames(property.Value)) yield return nested;
                    }
                    break;
                case JsonValueKind.Array:
                    foreach (var item in element.EnumerateArray())
                        foreach (var nested in KeyNames(item)) yield return nested;
                    break;
            }
        }
        foreach (var forbidden in new[] { "token", "lease", "credential", "secret", "password" })
            Assert(!KeyNames(after).Any(name => name.Contains(forbidden, StringComparison.OrdinalIgnoreCase)),
                $"the counters snapshot must never carry a '{forbidden}' field");
        checks.Add("fan931-p0-bounded-entry-counters-classify-and-leak-nothing");
        return checks;
    }

    /**
     * 裁决 P-4（2026-09-23）：runtime 详细日志"高频幂等成功轮询降采样 + 独立轮转"自测。
     * 覆盖：①同键成功轮询被降采样（首次/状态变化必记录）且高频成功超上限触发轮转、
     * 归档可读；②失败/超时事件不丢；③身份/生命周期事件不丢；④门关闭时只保留白名单；
     * ⑤跨 session 归档序号不复用/不覆盖。
     * 负例（⑥）由 **scratch 副本** 把 HostDiagnosticLog.PollingSuccessDownsampleEnabled
     * 改为 false 后重跑本套件实现：届时 ① 的降采样断言必然失败。
     */
    private static IReadOnlyList<string> RunRuntimeLogRotationSelfTest()
    {
        var checks = new List<string>();
        var root = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "yemancc-selftest-p4-" + Guid.NewGuid().ToString("N"));
        const int selfTestCap = 4096;
        Directory.CreateDirectory(root);

        static string[] RuntimeFiles(string dir) =>
            Directory.EnumerateFiles(dir, "yeman-fan-host-runtime*.log")
                .OrderBy(file => file, StringComparer.Ordinal).ToArray();

        static int CountRuntimeLines(string dir, string needle)
        {
            var total = 0;
            foreach (var file in RuntimeFiles(dir))
                foreach (var line in File.ReadAllLines(file))
                    if (line.Contains(needle, StringComparison.Ordinal)) total++;
            return total;
        }

        static int ArchiveCount(string dir) =>
            Directory.EnumerateFiles(dir, "yeman-fan-host-runtime.*.log").Count();

        static string Inventory(string dir) =>
            string.Join("; ", Directory.EnumerateFiles(dir, "yeman-fan-host-runtime*.log")
                .OrderBy(file => file, StringComparer.Ordinal)
                .Select(file => System.IO.Path.GetFileName(file) + "=" + new FileInfo(file).Length + "B"));

        static HostDiagnosticLog GateOpen(string dir, int cap)
        {
            Directory.CreateDirectory(dir);
            File.WriteAllText(System.IO.Path.Combine(dir, "fan-logging-enabled.flag"), "enabled");
            return new HostDiagnosticLog(dir, cap);
        }

        try
        {
            if (HostDiagnosticLog.DefaultRuntimeMaxBytes != 2 * 1024 * 1024)
                throw new InvalidOperationException($"P-4: 生产 runtime active 上限常量被改动值={HostDiagnosticLog.DefaultRuntimeMaxBytes} 期望=2097152");
            // ---------------- ① 降采样：同键成功轮询只留一条；状态变化必记录 ----------------
            var dirA = System.IO.Path.Combine(root, "a");
            var logA = GateOpen(dirA, 1024 * 1024);
            for (var i = 0; i < 8; i++)
                logA.Write("api.request-success", new { requestId = "p4-a" + i, method = "GET", path = "/api/state", state = "Ready", durationMs = 1.0, httpStatus = 200 });
            var pollLines = CountRuntimeLines(dirA, "\"path\":\"/api/state\"");
            if (pollLines != 1)
                throw new InvalidOperationException($"P-4①: 同键成功轮询未被降采样 runtime行数={pollLines} 期望=1（降采样守卫失效？）");
            logA.Write("api.request-success", new { requestId = "p4-a-state-change", method = "GET", path = "/api/state", state = "Suspended", httpStatus = 200 });
            if (CountRuntimeLines(dirA, "\"path\":\"/api/state\"") != 2)
                throw new InvalidOperationException("P-4①: 状态变化时必须再记录一条成功轮询");
            logA.Write("api.request-success", new { requestId = "p4-a-state-change-repeat", method = "GET", path = "/api/state", state = "Suspended", httpStatus = 200 });
            if (CountRuntimeLines(dirA, "\"path\":\"/api/state\"") != 2)
                throw new InvalidOperationException("P-4①: 状态未变时的重复成功轮询必须继续被降采样");
            // 受保护事件（enable/restore/resume/close/identity 等）的成功记录绝不能被采样吞掉。
            foreach (var protectedPath in new[] { "/api/enable", "/api/restore", "/api/resume", "/api/close", "/api/open", "/api/open-events", "/api/handshake", "/api/preset", "/api/disable", "/api/parent-exit" })
                for (var i = 0; i < 3; i++)
                    logA.Write("api.request-success", new { requestId = protectedPath + "#" + i, method = "POST", path = protectedPath, state = "Ready", httpStatus = 200 });
            foreach (var protectedPath in new[] { "/api/enable", "/api/restore", "/api/resume", "/api/close" })
            {
                var count = CountRuntimeLines(dirA, "\"path\":\"" + protectedPath + "\"");
                if (count != 3)
                    throw new InvalidOperationException($"P-4①: 受保护事件 {protectedPath} 的成功记录被采样吞掉 次数={count} 期望=3");
            }
            checks.Add("p4-downsample-same-key-success-single-record-and-state-change-recorded");

            // ---------------- ① 轮转：高频成功写入超上限触发轮转且归档可读 ----------------
            var dirB = System.IO.Path.Combine(root, "b");
            var logB = GateOpen(dirB, selfTestCap);
            for (var i = 0; i < 60; i++)
                logB.Write("api.request-success", new { requestId = "p4-b" + i, method = "GET", path = "/api/state", state = "S" + i, durationMs = 1.0, httpStatus = 200 });
            var archivesB = RuntimeFiles(dirB).Where(file => !file.EndsWith("yeman-fan-host-runtime.log", StringComparison.Ordinal)).ToArray();
            if (archivesB.Length == 0)
                throw new InvalidOperationException("P-4①: 高频成功写入超上限未触发轮转（无归档文件）");
            if (archivesB.Length > 3)
                throw new InvalidOperationException($"P-4①: 归档数超过保留上限 archives={archivesB.Length} keep=3 assert=P4-small-cap-archives-over-keep");
            foreach (var file in archivesB)
                foreach (var line in File.ReadAllLines(file))
                    if (line.Length > 0 && !line.Contains("\"eventName\":\"api.request-success\"", StringComparison.Ordinal))
                        throw new InvalidOperationException($"P-4①: 归档内容不是可读的既有 JSONL 记录: {System.IO.Path.GetFileName(file)}");
            var activeB = new FileInfo(System.IO.Path.Combine(dirB, "yeman-fan-host-runtime.log")).Length;
            if (activeB > selfTestCap * 2)
                throw new InvalidOperationException($"P-4①: active runtime 超出上限容差 active={activeB} cap={selfTestCap}");
            checks.Add($"p4-rotation-triggered-and-archives-readable archives={archivesB.Length} activeBytes={activeB} cap={selfTestCap}");
            Console.WriteLine($"[P-4] production cap pinned DefaultRuntimeMaxBytes={HostDiagnosticLog.DefaultRuntimeMaxBytes} keep=3");
            Console.WriteLine($"[P-4] runtime-log inventory (dirB cap={selfTestCap}): {Inventory(dirB)}");

            // ---------------- ② 失败/超时事件不丢 ----------------
            var dirC = System.IO.Path.Combine(root, "c");
            var logC = GateOpen(dirC, 1024 * 1024);
            for (var i = 0; i < 3; i++)
                logC.Write("api.request-failure", new { requestId = "p4-c" + i, method = "POST", path = "/api/enable", code = "FAULT_LOCKED", error = "x", state = "FaultLocked", httpStatus = 409 });
            for (var i = 0; i < 3; i++)
                logC.Write("api.request-host-error", new { requestId = "p4-c-h" + i, method = "POST", path = "/api/state", error = "boom", state = "Ready", httpStatus = 500 });
            logC.Write("power.transition-timeout", new { generation = "g1", timeoutMs = 2000 });
            if (CountRuntimeLines(dirC, "\"eventName\":\"api.request-failure\"") != 3)
                throw new InvalidOperationException("P-4②: 失败事件被丢弃/采样");
            if (CountRuntimeLines(dirC, "\"eventName\":\"api.request-host-error\"") != 3)
                throw new InvalidOperationException("P-4②: host-error 事件被丢弃/采样");
            if (CountRuntimeLines(dirC, "\"eventName\":\"power.transition-timeout\"") != 1)
                throw new InvalidOperationException("P-4②: 超时事件被丢弃/采样");
            checks.Add("p4-failure-and-timeout-events-never-sampled");

            // ---------------- ③ 身份/生命周期事件不丢 ----------------
            var dirD = System.IO.Path.Combine(root, "d");
            var logD = GateOpen(dirD, 1024 * 1024);
            for (var i = 0; i < 3; i++) logD.Write("host.identity", new { assemblyMvid = "mvid-" + i });
            logD.Write("host.starting", new { port = 1 });
            logD.Write("listener.ready", new { port = 1, realBackend = false });
            logD.Write("parent-exit-handoff.accepted");
            logD.Write("power.transition-complete", new { generation = "g1" });
            foreach (var name in new[] { "host.identity", "host.starting", "listener.ready", "parent-exit-handoff.accepted", "power.transition-complete" })
            {
                var expected = name == "host.identity" ? 3 : 1;
                var count = CountRuntimeLines(dirD, "\"eventName\":\"" + name + "\"");
                if (count != expected)
                    throw new InvalidOperationException($"P-4③: 身份/生命周期事件 {name} 丢失 次数={count} 期望={expected}");
            }
            checks.Add("p4-identity-and-lifecycle-events-never-sampled");

            // ---------------- ④ 门关闭时只保留白名单（故障账本） ----------------
            var dirE = System.IO.Path.Combine(root, "e");
            Directory.CreateDirectory(dirE);
            var logE = new HostDiagnosticLog(dirE, 1024 * 1024);
            logE.Write("api.request-success", new { requestId = "p4-e", method = "GET", path = "/api/state", state = "Ready", httpStatus = 200 });
            logE.Write("host.identity", new { assemblyMvid = "m" });
            logE.Write("engine.created", new { selftest = true });
            if (RuntimeFiles(dirE).Length != 0)
                throw new InvalidOperationException("P-4④: 门关闭时非白名单事件不得落 runtime 日志");
            logE.Write("recovery.retry-terminal", new { reason = "p4-selftest" });
            var faultE = System.IO.Path.Combine(dirE, "fan-host-fault.log");
            if (!File.Exists(faultE) || !File.ReadAllText(faultE).Contains("recovery.retry-terminal", StringComparison.Ordinal))
                throw new InvalidOperationException("P-4④: 门关闭时白名单故障事件未落 fan-host-fault.log");
            checks.Add("p4-gate-closed-whitelist-only-and-fault-ledger-intact");

            // ---------------- ⑤ 跨 session 不串（归档序号单调递增、旧归档不被覆盖） ----------------
            var dirF = System.IO.Path.Combine(root, "f");
            var logF1 = GateOpen(dirF, selfTestCap);
            for (var i = 0; i < 400 && ArchiveCount(dirF) < 1; i++)
                logF1.Write("api.request-success", new { requestId = "p4-f1-" + i, method = "GET", path = "/api/state", state = "F1-" + i, httpStatus = 200 });
            var archivesFirst = Directory.EnumerateFiles(dirF, "yeman-fan-host-runtime.*.log").OrderBy(file => file, StringComparer.Ordinal).ToArray();
            if (archivesFirst.Length != 1)
                throw new InvalidOperationException($"P-4⑤: 首个 session 归档数异常 archives={archivesFirst.Length} 期望=1");
            var firstArchivePath = archivesFirst[0];
            var firstArchiveText = File.ReadAllText(firstArchivePath);
            if (firstArchiveText.Length == 0 || !firstArchiveText.Contains("\"eventName\"", StringComparison.Ordinal))
                throw new InvalidOperationException("P-4⑤: 首个归档内容不可读");
            var logF2 = new HostDiagnosticLog(dirF, selfTestCap);
            for (var i = 0; i < 400 && ArchiveCount(dirF) < 2; i++)
                logF2.Write("api.request-success", new { requestId = "p4-f2-" + i, method = "GET", path = "/api/state", state = "F2-" + i, httpStatus = 200 });
            var archivesSecond = Directory.EnumerateFiles(dirF, "yeman-fan-host-runtime.*.log").OrderBy(file => file, StringComparer.Ordinal).ToArray();
            if (archivesSecond.Length != 2)
                throw new InvalidOperationException($"P-4⑤: 第二个 session 未新增归档且未覆盖旧归档 archives={archivesSecond.Length} 期望=2");
            if (File.ReadAllText(firstArchivePath) != firstArchiveText)
                throw new InvalidOperationException("P-4⑤: 新 session 覆盖了旧 session 的归档文件");
            if (System.IO.Path.GetFileName(firstArchivePath) != "yeman-fan-host-runtime.1.log" ||
                System.IO.Path.GetFileName(archivesSecond[1]) != "yeman-fan-host-runtime.2.log")
                throw new InvalidOperationException($"P-4⑤: 归档序号未跨 session 单调递增 [{System.IO.Path.GetFileName(firstArchivePath)}, {System.IO.Path.GetFileName(archivesSecond[1])}]");
            checks.Add($"p4-cross-session-archive-numbering [{System.IO.Path.GetFileName(firstArchivePath)},{System.IO.Path.GetFileName(archivesSecond[1])}] old-content-unchanged=true");
            Console.WriteLine($"[P-4] cross-session inventory (dirF cap={selfTestCap}): {Inventory(dirF)}");

            // ---------------- ⑥ FAN-931 P1.2：例行成功事件不再构造完整诊断上下文 ----------------
            var dirG = System.IO.Path.Combine(root, "g");
            var logG = GateOpen(dirG, 1024 * 1024);
            var contextCalls = 0;
            logG.SetContextProvider(() => { contextCalls++; return new { marker = "p12-context" }; });
            logG.Write("hc-operation.begin", new { operation = "hc-operation", phase = "Ready" });
            logG.Write("hc-operation.return", new { operation = "hc-operation", phase = "Ready", timedOut = false });
            logG.Write("api.request-success", new { requestId = "p12", method = "GET", path = "/api/heartbeat", state = "Ready", httpStatus = 200 });
            if (contextCalls != 0)
                throw new InvalidOperationException($"FAN-931-P1.2①: 例行成功事件仍构造了完整诊断上下文 calls={contextCalls} 期望=0");
            if (CountRuntimeLines(dirG, "\"context\":") != 0)
                throw new InvalidOperationException("FAN-931-P1.2①: 例行成功记录里仍带 context 块（应为轻量行）");
            if (CountRuntimeLines(dirG, "\"eventName\":\"hc-operation.begin\"") != 1 ||
                CountRuntimeLines(dirG, "\"eventName\":\"api.request-success\"") != 1)
                throw new InvalidOperationException("FAN-931-P1.2①: 例行成功事件本身必须仍然落盘（只是变轻）");
            logG.Write("api.request-failure", new { requestId = "p12-f", method = "POST", path = "/api/enable", code = "X", error = "y", state = "Ready", httpStatus = 409 });
            if (contextCalls != 1)
                throw new InvalidOperationException($"FAN-931-P1.2②: 需关联事件（失败/错误）必须继续带完整上下文 calls={contextCalls} 期望=1");
            if (CountRuntimeLines(dirG, "\"context\":") != 1)
                throw new InvalidOperationException("FAN-931-P1.2②: 需关联事件缺失 context 块");
            checks.Add($"fan931-p12-lightweight-context-for-routine-success contextCalls={contextCalls}");

            // ---------------- ⑦ FAN-931 P1.2：门关闭时不为注定不落盘的采样取数，loop 维护仍执行 ----------------
            var dirH = System.IO.Path.Combine(root, "h");
            Directory.CreateDirectory(dirH);
            var logH = new HostDiagnosticLog(dirH, 1024 * 1024); // 门未开启
            var engineH = new FanHostEngine(HostOptions.Parse(Array.Empty<string>()), logH);
            var maintenanceBefore = engineH.RuntimeLoopMaintenanceRunsForSelfTest;
            engineH.WriteRuntimeDiagnostics();
            var maintenanceAfter = engineH.RuntimeLoopMaintenanceRunsForSelfTest;
            if (maintenanceAfter != maintenanceBefore + 1)
                throw new InvalidOperationException($"FAN-931-P1.2③: 门关闭时 loop 维护未被调用（取数与维护必须解耦）before={maintenanceBefore} after={maintenanceAfter}");
            if (RuntimeFiles(dirH).Length != 0)
                throw new InvalidOperationException("FAN-931-P1.2③: 门关闭时不得产生 runtime 记录（采样取数应被跳过）");
            checks.Add("fan931-p12-gate-closed-sampling-decoupled-from-loop-maintenance");
        }
        finally
        {
            try { if (Directory.Exists(root)) Directory.Delete(root, recursive: true); } catch { }
        }
        return checks;
    }

    /**
     * 920-v1.3 §15.1：async void 未处理异常是否终止进程，必须在独立子进程中观察，
     * 不让异常影响主自测进程。本方法只启动子进程并判读它的退出码与输出，不做断言
     * ——“存活”与“终止”都是待记录的事实，不是本套件的通过条件。
     */
    #if YEMAN_ASYNC_BOUNDARY_TEST
    private static async Task<IReadOnlyList<string>> RunAsyncVoidThrowIsolationSelfTestAsync()
    {
        static string Clip(string text, int limit) =>
            text.Length <= limit ? text : text.Substring(0, limit);

        var executable = Environment.ProcessPath;
        if (string.IsNullOrEmpty(executable))
            throw new InvalidOperationException("async-boundary-child: cannot locate the Host executable");
        var startInfo = new ProcessStartInfo
        {
            FileName = executable,
            // 920-v1.4 §16.4：用显式命令行开关，不用环境变量；正常启动不会被改道。
            Arguments = "--async-boundary-crash-probe",
            UseShellExecute = false,
            CreateNoWindow = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        };
        using var child = Process.Start(startInfo)
            ?? throw new InvalidOperationException("async-boundary-child: could not start the isolation child process");
        try
        {
            // 920-v1.4 §16.4：先并发异步读取，再等待退出。原实现先同步 ReadToEnd
            // 两个管道再 WaitForExit(30000)，前面的读可能永久阻塞 ⇒ 30 秒上界不成立。
            var stdoutTask = child.StandardOutput.ReadToEndAsync();
            var stderrTask = child.StandardError.ReadToEndAsync();
            var exited = child.WaitForExit(30_000);
            if (!exited)
            {
                // 只清理本测试自己创建的子进程树。
                try { child.Kill(entireProcessTree: true); } catch { }
                child.WaitForExit(5_000);
            }
            var stdout = await ReadWithBoundAsync(stdoutTask).ConfigureAwait(false);
            var stderr = await ReadWithBoundAsync(stderrTask).ConfigureAwait(false);
            if (!exited)
                return new[] { $"hc-async-boundary-child[async-void-throw] survived=unknown boundedTimeoutExpired=true killedOwnChild=true stdout={Clip(stdout.Trim(), 160)}" };
            var survived = child.ExitCode == 0 &&
                stdout.Contains("process-survived-async-void-throw", StringComparison.Ordinal);
            var evidence = survived
                ? "survived=true handlesDeferredExceptionBeforeProcessExit"
                : $"survived=false exitCode={child.ExitCode} stderr={Clip(stderr.Trim(), 160)} stdout={Clip(stdout.Trim(), 160)}";
            return new[] { $"hc-async-boundary-child[async-void-throw] {evidence}" };
        }
        finally
        {
            if (!child.HasExited)
            {
                try { child.Kill(entireProcessTree: true); } catch { }
            }
        }
    }

    /** 读取已完成的管道任务；若管道未闭合则给一个有界等待，避免测试自身挂住。 */
    private static async Task<string> ReadWithBoundAsync(Task<string> read)
    {
        try
        {
            return await read.WaitAsync(TimeSpan.FromSeconds(5)).ConfigureAwait(false);
        }
        catch (TimeoutException)
        {
            return "<pipe-not-drained-within-5s>";
        }
    }
#endif

    /**
     * §4.5 / F07（FAN-925B）**结合场景**：UI 持续不可用 + route-lost。
     * 全程只让宿主**既有的**恢复重试路径工作：不调用任何 Enable / Open / Resume / Close 入口，
     * 也不产生任何页面回调。断言：
     *   ① 进入"等待重开"时绑定并记名唯一执行者；
     *   ② 有界等待预算用尽后**恰好一次**请求受控更换（既不无限等页面，也不反复换代）；
     *   ③ 依赖页面的副作用一个都没发生，且宿主不持有活跃写入权。
     */
    internal static async Task<IReadOnlyList<string>> RunUiUnavailableRouteLostScenarioAsync()
    {
        const long scenarioBudgetMs = 200;
        var checks = new List<string>();
        var diagnostics = new HostDiagnosticLog();
        var options = HostOptions.Parse(new[] { "--port", "8811" });
        var engine = new FanHostEngine(options, diagnostics);
        var previousBudget = FanHostEngine.ReopenBridgeWaitBudgetMsForSelfTest;
        FanHostEngine.ReopenBridgeWaitBudgetMsForSelfTest = scenarioBudgetMs;

        // 只统计**本场景开始之后**产生的事件（自测捕获是全程累积的，前面用例也会发 api.* 事件）。
        var mark = HostDiagnosticLog.SelfTestCaptured.Count;
        string Digest() => string.Join(
            ",",
            HostDiagnosticLog.SelfTestCaptured.Skip(mark)
                .Select(item => item.Event)
                .Where(name => name.StartsWith("recovery.", StringComparison.Ordinal)));

        try
        {
            // 干净起点：不要在别的用例留下的故障周期上跑。
            engine.ClearRecoveryCycleForSelfTest();
            engine.MarkReopenRequiredForSelfTest("ui-unavailable-route-lost");
            if (!engine.RecoveryReopenRequiredForSelfTest)
                throw new InvalidOperationException("f07-scenario: route-loss must leave the session reopen-required");
            if (string.IsNullOrEmpty(engine.ReopenBindingForSelfTest))
                throw new InvalidOperationException("f07-scenario: entering reopen-wait must bind this reopen");
            engine.EnterFaultLockedAndScheduleRecoveryForSelfTest();

            var deadline = Environment.TickCount64 + 12_000;
            while (Environment.TickCount64 < deadline && engine.ControlledReplacementRequestsForSelfTest == 0)
                await Task.Delay(50).ConfigureAwait(false);
            var requested = engine.ControlledReplacementRequestsForSelfTest;
            if (requested != 1)
                throw new InvalidOperationException(
                    $"f07-scenario: the bounded budget must escalate exactly once without any UI callback " +
                    $"(requested={requested} owner={engine.RecoveryOwnerForSelfTest} reopenRequired={engine.RecoveryReopenRequiredForSelfTest} " +
                    $"state={engine.Snapshot().State} events=[{Digest()}])");
            // 升级后执行者只允许是这两种有界状态之一；绝不允许停在"无限等页面"。
            if (engine.RecoveryOwnerForSelfTest is not (
                    "fan-host-requests-controlled-replacement" or
                    "fan-host-terminal-accounting;replacement-already-requested"))
                throw new InvalidOperationException(
                    $"f07-scenario: the sole fan recovery owner must move past 'awaiting-bridge-reopen' once the bounded budget elapses " +
                    $"(owner='{engine.RecoveryOwnerForSelfTest}')");

            // 再跨两轮既有重试：升级**不得**重复请求（至多一次/周期）。
            await Task.Delay(2_500).ConfigureAwait(false);
            if (engine.ControlledReplacementRequestsForSelfTest != 1)
                throw new InvalidOperationException(
                    $"f07-scenario: the controlled replacement must be requested at most once per cycle " +
                    $"(requested={engine.ControlledReplacementRequestsForSelfTest})");

            // §4.1（FAN-926 P2）：本断言按裁决**改写**。旧断言要求"UI 不可用时宿主不做任何
            // 页面相关动作"——那正是"永远等页面"的实现。新要求：宿主**自己**做一次有正式
            // 收据的同进程恢复（恰好一次），拿不到完整收据就如实升级；**绝不**宣称已恢复，
            // 也**绝不**因为只留下一个 requested 事件就算通过。
            if (engine.UiFreeSelfOpenAttemptsForSelfTest != 1)
                throw new InvalidOperationException(
                    $"f07-scenario: the host must attempt exactly one same-process recovery without the UI " +
                    $"(selfOpenAttempts={engine.UiFreeSelfOpenAttemptsForSelfTest})");
            if (engine.UiFreeReplacementRequestsForSelfTest != 1)
                throw new InvalidOperationException(
                    $"f07-scenario: at most one controlled replacement request per episode " +
                    $"(replacementRequests={engine.UiFreeReplacementRequestsForSelfTest})");
            if (FanHostEngine.UiFreeRecoveryComplete(formalReceiptAccepted: false, replacementRequested: true))
                throw new InvalidOperationException(
                    "f07-scenario: a requested-only outcome must never count as a completed recovery");
            if (engine.RecoveryOwnerForSelfTest == "fan-host-same-process-recovered")
                throw new InvalidOperationException(
                    "f07-scenario: without a formal HC receipt the host must not claim same-process recovery");

            checks.Add(
                $"f07-ui-unavailable-route-lost-scenario[binding={engine.ReopenBindingForSelfTest} " +
                $"owner={engine.RecoveryOwnerForSelfTest} replacementsRequested=1 selfOpenAttempts=1 " +
                $"noUiCallbackRequired=true claimedRecovery=false]");
        }
        finally
        {
            FanHostEngine.ReopenBridgeWaitBudgetMsForSelfTest = previousBudget;
            engine.ResetReopenStateForSelfTest();
            engine.Dispose();
        }
        return checks;
    }

    /**
     * §3（FAN-926 P1 / CP-07）：parent-exit **真实受理顺序**的 H 组用例。
     * - 每个分项用**自己的**引擎实例（`BeginParentExitHandoff` 会永久关闭写入口，不是可复用状态）；
     * - 全部走自测隔离日志根，`realBackend` 为 null ⇒ 不碰真实 EC/ACPI；
     * - 断言的是**行为**（谁绑定、谁执行、终态归谁、有没有被 gate 拖住），不是字段是否存在。
     */
    internal static async Task<IReadOnlyList<string>> RunParentExitAcceptanceSelfTestAsync()
    {
        var checks = new List<string>();
        var nextPort = 8840;

        FanHostEngine NewEngine(HostDiagnosticLog diagnostics) =>
            new(HostOptions.Parse(new[] { "--port", (nextPort++).ToString() }), diagnostics);

        static (bool Ack, string Host, string Cycle, bool Queued, string Phase, string Scope, string AcceptedAt) Parse(object response)
        {
            var payload = System.Text.Json.JsonSerializer.Serialize(response, JsonDefaults.Options);
            using var doc = System.Text.Json.JsonDocument.Parse(payload);
            var root = doc.RootElement;
            string Text(string name) =>
                root.TryGetProperty(name, out var value) && value.ValueKind == System.Text.Json.JsonValueKind.String
                    ? value.GetString() ?? string.Empty
                    : string.Empty;
            bool Flag(string name) =>
                root.TryGetProperty(name, out var value) && value.ValueKind == System.Text.Json.JsonValueKind.True;
            return (Flag("recoveryAccepted"), Text("acceptingHostInstanceId"), Text("acceptedRecoveryCycleId"),
                Flag("queuedNow"), Text("recoveryPhase"), Text("acceptanceScope"), Text("acceptedAtUtc"));
        }

        static async Task WaitForSettledAsync(FanHostEngine engine)
        {
            var deadline = Environment.TickCount64 + 15_000;
            while (Environment.TickCount64 < deadline && engine.RecoveryPhaseForSelfTest == "recovery-executing")
                await Task.Delay(25).ConfigureAwait(false);
        }

        // ── H1：干净首次 parent-exit 必须**先建立真实受理身份**，且 ACK / worker / 终态是同一条责任 ──
        // 负例内核就在同一段里：受理**之前** recoveryCycle 真的不存在 —— 旧实现正好读这一格，
        // 所以它当时必然回报空 cycle（= native 判 unbound 的那个真实产品缺口）。
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                if (engine.RecoveryCycleIdForReport is not null)
                    throw new InvalidOperationException(
                        "h1: a cleared cycle must really be absent before the handoff (otherwise the negative case is vacuous)");
                var acked = Parse(engine.BeginParentExitHandoff());
                if (!acked.Ack || string.IsNullOrEmpty(acked.Host) || string.IsNullOrEmpty(acked.Cycle))
                    throw new InvalidOperationException(
                        $"h1: a clean first parent-exit must bind host+cycle before the ACK " +
                        $"(ack={acked.Ack} host='{acked.Host}' cycle='{acked.Cycle}')");
                if (acked.Cycle != engine.RecoveryCycleIdForReport ||
                    acked.Cycle != engine.ParentExitAcceptanceCycleForSelfTest ||
                    acked.Host != engine.ParentExitAcceptanceHostForSelfTest)
                    throw new InvalidOperationException(
                        $"h1: the ACK must name the very responsibility the worker executes " +
                        $"(ack={acked.Cycle} engine={engine.RecoveryCycleIdForReport} " +
                        $"acceptance={engine.ParentExitAcceptanceCycleForSelfTest})");
                await WaitForSettledAsync(engine).ConfigureAwait(false);
                if (engine.RecoveryCycleIdForReport != acked.Cycle)
                    throw new InvalidOperationException(
                        "h1: settlement must stay on the accepted cycle (no silently swapped responsibility)");
                checks.Add($"h1-first-parent-exit-binds-real-cycle[host={acked.Host} cycle={acked.Cycle} " +
                           $"binding={engine.ParentExitAcceptanceBindingForSelfTest} " +
                           $"settledPhase={engine.RecoveryPhaseForSelfTest}]");
            }
            finally { engine.Dispose(); }
        }

        // ── H2：并发 + 重复请求 ⇒ 一个 owner / 一个 worker / 同一条责任 / 同一起点预算 ──
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                const int callers = 6;
                var results = new (bool Ack, string Host, string Cycle, bool Queued, string Phase, string Scope, string AcceptedAt)[callers];
                using var barrier = new Barrier(callers);
                var threads = new Thread[callers];
                for (var i = 0; i < callers; i++)
                {
                    var index = i;
                    threads[index] = new Thread(() =>
                    {
                        barrier.SignalAndWait();
                        results[index] = Parse(engine.BeginParentExitHandoff());
                    }) { IsBackground = true };
                    threads[index].Start();
                }
                foreach (var thread in threads)
                    if (!thread.Join(20_000))
                        throw new InvalidOperationException("h2: a concurrent handoff caller never returned (deadlock?)");
                var cycles = results.Select(item => item.Cycle).Distinct(StringComparer.Ordinal).ToArray();
                if (cycles.Length != 1 || cycles[0].Length == 0)
                    throw new InvalidOperationException(
                        $"h2: concurrent handoffs must share exactly one responsibility, got [{string.Join(",", cycles)}]");
                if (results.Any(item => !item.Ack))
                    throw new InvalidOperationException("h2: every concurrent caller must see the same real acceptance");
                var queuedCount = results.Count(item => item.Queued);
                if (queuedCount != 1)
                    throw new InvalidOperationException(
                        $"h2: exactly one caller may enqueue the worker, got {queuedCount}");
                // 同一条受理 = 同一个"受理时刻"：并发/重复不得各自重铸一份身份——否则 ACK 的
                // acceptedAtUtc 会漂移，"同一条责任"就只剩 cycle 字符串巧合。
                var stamps = results.Select(item => item.AcceptedAt).Distinct(StringComparer.Ordinal).ToArray();
                if (stamps.Length != 1 || stamps[0].Length == 0)
                    throw new InvalidOperationException(
                        $"h2: concurrent callers must reuse one acceptance record, got [{string.Join(",", stamps)}]");
                await WaitForSettledAsync(engine).ConfigureAwait(false);
                checks.Add($"h2-concurrent-and-repeat-handoff-share-one-responsibility[callers={callers} " +
                           $"queued={queuedCount} cycle={cycles[0]} oneAcceptanceStamp=true " +
                           $"settledPhase={engine.RecoveryPhaseForSelfTest}]");
            }
            finally { engine.Dispose(); }
        }

        // ── H3：已有 Close/cleanup owner ⇒ 只观察**同一条**责任，绝不开第二条 HC Close ──
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                _ = engine.Close();
                var entryAfterClose = engine.CloseEntryCountForSelfTest;
                var observed = Parse(engine.BeginParentExitHandoff());
                if (!observed.Ack || string.IsNullOrEmpty(observed.Cycle))
                    throw new InvalidOperationException(
                        "h3: an existing close owner must still bind exactly one responsibility");
                if (observed.Queued)
                    throw new InvalidOperationException(
                        "h3: a second recovery worker must never be queued while a close owner holds the boundary");
                if (engine.CloseEntryCountForSelfTest != entryAfterClose)
                    throw new InvalidOperationException(
                        $"h3: the handoff must not become a second HC Close " +
                        $"({entryAfterClose}->{engine.CloseEntryCountForSelfTest})");
                checks.Add($"h3-existing-close-owner-is-observed-not-replaced[cycle={observed.Cycle} " +
                           $"phase={observed.Phase} queuedNow=false closeEntries={engine.CloseEntryCountForSelfTest}]");
            }
            finally { engine.Dispose(); }
        }

        // ── H4：引擎 gate 被占用 ≥10 s ⇒ 受理仍在快速门内完成**且有绑定**（受理不靠抢锁赢）──
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                const int gateHoldMs = 10_000;
                var hold = Task.Run(() => engine.HoldGateForSelfTest(gateHoldMs));
                var engaged = Environment.TickCount64 + 3_000;
                while (Environment.TickCount64 < engaged && !engine.GateHeldForSelfTest)
                    await Task.Delay(10).ConfigureAwait(false);
                if (!engine.GateHeldForSelfTest)
                    throw new InvalidOperationException(
                        "h4: gate-hold fixture did not engage - the bounded-latency assertion would be vacuous");
                var started = System.Diagnostics.Stopwatch.GetTimestamp();
                var busy = Parse(engine.BeginParentExitHandoff());
                var acceptMs = System.Diagnostics.Stopwatch.GetElapsedTime(started).TotalMilliseconds;
                var released = hold.Wait(gateHoldMs + 5_000);
                if (acceptMs > 2_000)
                    throw new InvalidOperationException(
                        $"h4: acceptance must not follow the HC/ACPI gate hold (took {acceptMs:F0}ms)");
                if (!busy.Ack || string.IsNullOrEmpty(busy.Cycle))
                    throw new InvalidOperationException(
                        $"h4: acceptance must still be bound while the engine gate is busy " +
                        $"(ack={busy.Ack} cycle='{busy.Cycle}')");
                if (!released)
                    throw new InvalidOperationException("h4: gate-hold fixture never returned");
                checks.Add($"h4-acceptance-does-not-wait-on-busy-engine-gate[gateHoldMs={gateHoldMs} " +
                           $"acceptMs={acceptMs:F0} cycle={busy.Cycle} phase={busy.Phase}]");
            }
            finally { engine.Dispose(); }
        }

        // ── H5：已结算之后重复请求 ⇒ 幂等、同一条责任、不新开窗口、不伪装"仍在执行" ──
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                var first = Parse(engine.BeginParentExitHandoff());
                await WaitForSettledAsync(engine).ConfigureAwait(false);
                var settledPhase = engine.RecoveryPhaseForSelfTest;
                if (settledPhase == "recovery-executing")
                    throw new InvalidOperationException("h5: the first handoff never settled - assertion would be vacuous");
                var repeat = Parse(engine.BeginParentExitHandoff());
                if (!repeat.Ack || repeat.Cycle != first.Cycle)
                    throw new InvalidOperationException(
                        $"h5: a repeat request must be idempotent on the same cycle (first={first.Cycle} repeat={repeat.Cycle})");
                if (repeat.Queued)
                    throw new InvalidOperationException("h5: a settled cycle must not be re-queued (no fresh 60s window)");
                if (repeat.Phase == "recovery-executing")
                    throw new InvalidOperationException(
                        $"h5: a settled cycle must not be reported as still executing (phase='{repeat.Phase}')");
                checks.Add($"h5-settled-cycle-is-idempotent-and-does-not-reopen-window[cycle={repeat.Cycle} " +
                           $"settledPhase={settledPhase} repeatPhase={repeat.Phase} requeued=false]");
            }
            finally { engine.Dispose(); }
        }

        // ── H8：受理已建立但 worker 被 gate 挡住尚未执行 ⇒ 绝不出现"从未执行却已恢复成功" ──
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                const int gateHoldMs = 4_000;
                var hold = Task.Run(() => engine.HoldGateForSelfTest(gateHoldMs));
                var engaged = Environment.TickCount64 + 3_000;
                while (Environment.TickCount64 < engaged && !engine.GateHeldForSelfTest)
                    await Task.Delay(10).ConfigureAwait(false);
                if (!engine.GateHeldForSelfTest)
                    throw new InvalidOperationException("h8: gate-hold fixture did not engage");
                var acked = Parse(engine.BeginParentExitHandoff());
                if (!acked.Ack || !acked.Queued)
                    throw new InvalidOperationException(
                        $"h8: the acceptance itself must be real and the worker must be queued (ack={acked.Ack} queued={acked.Queued})");
                if (acked.Phase is "recovery-completed" or "recovery-terminal")
                    throw new InvalidOperationException(
                        $"h8: an accepted-but-not-yet-executed handoff must not claim a settled phase (phase='{acked.Phase}')");
                if (engine.RecoveryCycleIdForReport != acked.Cycle)
                    throw new InvalidOperationException(
                        "h8: the queued worker must own the very cycle the ACK named");
                hold.Wait(gateHoldMs + 5_000);
                checks.Add($"h8-acceptance-never-claims-execution-or-completion[phase={acked.Phase} " +
                           $"cycle={acked.Cycle} queuedNow={acked.Queued}]");
            }
            finally { engine.Dispose(); }
        }

        // ── H3b：已有 Close owner，但引擎**未进终态** ⇒ 只观察同一条责任，不排第二个 worker ──
        // 专测 `closeOwnerBusy` 这一项：若它被删掉，本项必须失败（H3 走的是 Close() 之后的
        // settled 捷径，无法单独区分这一项）。
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                engine.MarkCloseBoundaryClaimedForSelfTest();
                var observed = Parse(engine.BeginParentExitHandoff());
                if (!observed.Ack || string.IsNullOrEmpty(observed.Cycle))
                    throw new InvalidOperationException(
                        "h3b: a claimed close boundary must still bind exactly one responsibility");
                if (observed.Queued)
                    throw new InvalidOperationException(
                        "h3b: an in-flight close owner must not get a second recovery worker");
                if (observed.Phase is "host-stopped" or "recovery-completed" or "recovery-terminal")
                    throw new InvalidOperationException(
                        $"h3b: this case must not be satisfied merely by a settled engine (phase='{observed.Phase}')");
                if (engine.CloseEntryCountForSelfTest != 0)
                    throw new InvalidOperationException(
                        $"h3b: the handoff must not become a real HC Close (entries={engine.CloseEntryCountForSelfTest})");
                checks.Add($"h3b-claimed-close-boundary-is-observed-not-queued[cycle={observed.Cycle} " +
                           $"phase={observed.Phase} queuedNow=false]");
            }
            finally { engine.Dispose(); }
        }

        // ── H1 负例：责任无法绑定（本 episode 已终态）⇒ 必须 recoveryAccepted=false ──
        // 挡住"只要返回 200 就算交接被接受"，也挡住"拒绝了却仍排一个 worker"。
        {
            var engine = NewEngine(new HostDiagnosticLog());
            try
            {
                engine.ClearRecoveryCycleForSelfTest();
                engine.ForceTerminalRecoveryCycleForSelfTest("h1-negative");
                var refused = Parse(engine.BeginParentExitHandoff());
                if (refused.Ack || refused.Queued)
                    throw new InvalidOperationException(
                        $"h1-negative: an unbound responsibility must never be reported as accepted " +
                        $"(ack={refused.Ack} cycle='{refused.Cycle}' queued={refused.Queued})");
                if (refused.Phase != "recovery-terminal")
                    throw new InvalidOperationException(
                        $"h1-negative: the refusal must report the real phase (got '{refused.Phase}')");
                if (engine.ParentExitHandoffQueuedForSelfTest)
                    throw new InvalidOperationException("h1-negative: a refused acceptance must not queue a worker");
                checks.Add("h1-negative-unbound-responsibility-is-not-accepted[ack=false " +
                           $"phase={refused.Phase} queuedNow=false]");
            }
            finally { engine.Dispose(); }
        }

        return checks;
    }

    /**
     * §4.1（FAN-926 P2 场景三）：**预算耗尽 ⇒ 诚实失败，且只有 caller-visible 的显式重试
     * 能开新窗口**。此前这条只对手写 `BoundedRecoveryRetrySelfTest.Model` 断言（不是生产引擎），
     * 因此"检查数"并不能证明生产路径；这里用**真实引擎**跑真实路径。
     */
    internal static async Task<IReadOnlyList<string>> RunBudgetExhaustionAndExplicitRetrySelfTestAsync()
    {
        var checks = new List<string>();
        const long shortWindowMs = 1500;
        var previousWindow = FanHostEngine.RecoveryRetryWindowMsForSelfTest;
        var previousBridgeBudget = FanHostEngine.ReopenBridgeWaitBudgetMsForSelfTest;
        FanHostEngine.RecoveryRetryWindowMsForSelfTest = shortWindowMs;
        FanHostEngine.ReopenBridgeWaitBudgetMsForSelfTest = 200;
        var engine = new FanHostEngine(HostOptions.Parse(new[] { "--port", "8891" }), new HostDiagnosticLog());
        try
        {
            engine.ClearRecoveryCycleForSelfTest();
            engine.MarkReopenRequiredForSelfTest("budget-exhaustion");
            engine.EnterFaultLockedAndScheduleRecoveryForSelfTest();
            var deadline = Environment.TickCount64 + 15_000;
            while (Environment.TickCount64 < deadline && !engine.RecoveryRetryTerminalForSelfTest)
                await Task.Delay(50).ConfigureAwait(false);
            if (!engine.RecoveryRetryTerminalForSelfTest)
                throw new InvalidOperationException(
                    "h9: the REAL engine must reach an honest terminal once the cycle budget is exhausted " +
                    $"(terminal={engine.RecoveryRetryTerminalForSelfTest} phase={engine.RecoveryPhaseForSelfTest})");
            // 诚实失败：既不许宣称已恢复，也不许把周期说成已完成。
            if (engine.RecoveryPhaseForSelfTest is "recovery-completed" or "host-stopped")
                throw new InvalidOperationException(
                    $"h9: an exhausted budget must not be reported as a successful recovery (phase='{engine.RecoveryPhaseForSelfTest}')");
            var exhaustedState = engine.Snapshot();
            if (!string.Equals(exhaustedState.State, "FaultLocked", StringComparison.Ordinal))
                throw new InvalidOperationException(
                    $"h9: an exhausted budget must end FaultLocked, got '{exhaustedState.State}'");
            var attemptsAtTerminal = engine.RecoveryRetryAttemptForSelfTest;
            // 自动路径不得自己重新开窗口。
            await Task.Delay(800).ConfigureAwait(false);
            if (!engine.RecoveryRetryTerminalForSelfTest || engine.RecoveryRetryAttemptForSelfTest != attemptsAtTerminal)
                throw new InvalidOperationException(
                    "h9: a terminal recovery window must not re-arm itself automatically");
            // 只有 caller-visible 的显式重试才能开新窗口 —— 人工重试入口必须可达。
            try { _ = engine.Close(); } catch (FanApiException) { /* 终态下的关闭结果不影响窗口判定 */ }
            if (engine.RecoveryRetryTerminalForSelfTest)
                throw new InvalidOperationException(
                    "h9: a caller-visible explicit retry must be able to open a fresh bounded window");
            checks.Add("h9-budget-exhausted-is-honest-and-explicit-retry-opens-a-new-window" +
                       $"[terminalState=FaultLocked attempts={attemptsAtTerminal} windowMs={shortWindowMs} explicitRetryReopened=true]");
        }
        finally
        {
            FanHostEngine.RecoveryRetryWindowMsForSelfTest = previousWindow;
            FanHostEngine.ReopenBridgeWaitBudgetMsForSelfTest = previousBridgeBudget;
            engine.ResetReopenStateForSelfTest();
            engine.Dispose();
        }
        return checks;
    }

    public static async Task<SelfTestResult> RunAsync(FanHostEngine engine)
    {
        var checks = new List<string>();
        checks.AddRange(BoundedRecoveryRetrySelfTest.RunSelfTest());
        // FAN-925：异常收尾**有界取锁**（设备语料实测旧实现被 gate 挂住 +5.0s ⇒ "20s 预算"
        // 并非驻留上界）。夹具先确定持有 gate，再断言异常收尾在 gate 等待上界内返回。
        {
            var holdTask = Task.Run(() => engine.HoldGateForSelfTest(4000));
            var engaged = false;
            for (var spin = 0; spin < 100 && !engaged; spin++)
            {
                engaged = engine.GateHeldForSelfTest;
                if (!engaged) await Task.Delay(10).ConfigureAwait(false);
            }
            if (!engaged)
                throw new InvalidOperationException("fan925: gate-hold fixture did not engage - the bounded-lock test would be vacuous");
            var sw = System.Diagnostics.Stopwatch.StartNew();
            var busyRemaining = engine.EscalateAbnormalFinalize("selftest-gate-busy");
            sw.Stop();
            await holdTask.ConfigureAwait(false);
            if (sw.ElapsedMilliseconds < FanHostEngine.AbnormalFinalizeGateWaitMs - 400 ||
                sw.ElapsedMilliseconds > FanHostEngine.AbnormalFinalizeGateWaitMs + 1200)
                throw new InvalidOperationException(
                    $"fan925: abnormal finalize must be bounded by the gate wait ({FanHostEngine.AbnormalFinalizeGateWaitMs}ms), blocked {sw.ElapsedMilliseconds}ms");
            if (busyRemaining != 0)
                throw new InvalidOperationException(
                    "fan925: a gate-busy escalation must not claim an unprovable remaining budget");
            checks.Add($"t2-fan925-abnormal-finalize-bounded-gate-wait blockedMs={sw.ElapsedMilliseconds} remainingMs={busyRemaining}");
        }
        // FAN-925：故障周期记录的**真实磁盘往返**（跨进程继承的落盘格式 + 读回路径 +
        // 同父继承判定 + 清理生效）。走隔离根，不污染用户真实状态。
        {
            var started = DateTime.UtcNow.AddMilliseconds(-20_000);
            var path = engine.PersistRecoveryCycleForSelfTest(4242, started, 10);
            if (!File.Exists(path))
                throw new InvalidOperationException("fan925: recovery-cycle record was not persisted to disk");
            var read = engine.ReadRecoveryCycleForSelfTest();
            if (!read.Found || read.CycleId != "selftest-cycle" || read.Attempts != 10 ||
                read.RemainingMs < 38_000 || read.RemainingMs > 40_000)
                throw new InvalidOperationException(
                    $"fan925: recovery-cycle disk round-trip failed: found={read.Found} id={read.CycleId} " +
                    $"attempts={read.Attempts} remaining={read.RemainingMs}");
            if (FanHostEngine.DecideRecoveryCycleAdoption(false, read.Found, true, false, read.RemainingMs, read.Replacements)
                != FanHostEngine.RecoveryCycleAdoption.Inherit)
                throw new InvalidOperationException("fan925: a same-parent unexpired persisted cycle must be inherited");
            checks.Add($"t2-fan925-recovery-cycle-disk-roundtrip attempts={read.Attempts} remainingMs={read.RemainingMs}");
            engine.ClearRecoveryCycleForSelfTest();
            if (engine.ReadRecoveryCycleForSelfTest().Found)
                throw new InvalidOperationException("fan925: cleared recovery-cycle record still resolves on disk");
            checks.Add("t2-fan925-recovery-cycle-clear-verified");
        }
        // FAN-934 R2 §3-B第四条：**跨进程旧 journal → 新实例**的实测（纯生产入口驱动，无 seam）。
        // 场景：同一父 episode 的旧自动恢复周期已在磁盘上耗尽（次数到限）却**从未结算**；
        // 一个替代 Host 实例带着同一父身份启动。断言：
        //   ① 旧证据不得直接放行自动恢复（拒绝进入诚实终态，而非偷偷续期）；
        //   ②③ 拒绝不得删除账本、不得重置预算（仍是同一条 cycle、attempts=30、remaining=0）；
        //   ④ 用户显式 Close（唯一自动性豁免）必须能开出**有界**新周期；
        //   对照：与旧周期无关的新 episode 不得被过度拒绝，也不得盗用旧周期身份。
        {
            var legacyPath = engine.PersistRecoveryCycleForSelfTest(4242, DateTime.UtcNow.AddHours(-1), 30);
            if (!File.Exists(legacyPath))
                throw new InvalidOperationException("fan934: legacy exhausted journal was not persisted to disk");
            var legacy = engine.ReadRecoveryCycleForSelfTest();
            if (!legacy.Found || legacy.CycleId is null || legacy.Attempts != 30 || legacy.RemainingMs != 0)
                throw new InvalidOperationException(
                    "fan934: legacy fixture must be an exhausted, un-settled cycle: " +
                    $"found={legacy.Found} id={legacy.CycleId} attempts={legacy.Attempts} remaining={legacy.RemainingMs}");
            var legacyCycleId = legacy.CycleId!;
            var fullWindow = FanHostEngine.RemainingRecoveryCycleMsForSelfTest(DateTime.UtcNow, 0, false, false);

            var successor = new FanHostEngine(
                HostOptions.Parse(new[] { "--parent-pid", "4242" }), new HostDiagnosticLog());
            try
            {
                successor.EnterFaultLockedAndScheduleRecoveryForSelfTest();
                // ① 旧证据不得直接放行：拒绝自动恢复，进入诚实终态且不武装定时器。
                if (!successor.RecoveryRetryTerminalForSelfTest || successor.RecoveryRetryTimerActiveForSelfTest)
                    throw new InvalidOperationException(
                        "fan934: an exhausted un-settled journal must NOT be accredited into a fresh automatic window " +
                        $"(terminal={successor.RecoveryRetryTerminalForSelfTest} timer={successor.RecoveryRetryTimerActiveForSelfTest})");
                // ②③ 拒绝不得删除账本、不得重置预算。
                var refused = successor.ReadRecoveryCycleForSelfTest();
                if (!refused.Found || refused.CycleId != legacyCycleId || refused.Attempts != 30 ||
                    refused.Replacements != 0 || refused.RemainingMs != 0)
                    throw new InvalidOperationException(
                        "fan934: refusing an exhausted journal must keep the SAME cycle and remaining budget " +
                        "(not delete/reset it): " +
                        $"found={refused.Found} id={refused.CycleId} attempts={refused.Attempts} " +
                        $"replacements={refused.Replacements} remaining={refused.RemainingMs}");
                checks.Add(
                    $"fan934-old-exhausted-journal-refused-kept-and-bounded cycle={legacyCycleId} " +
                    $"attempts={refused.Attempts} remainingMs={refused.RemainingMs}");

                // ④ 用户显式 Close 必须开出有界新周期（而不是永久卡死在旧周期上）。
                successor.InjectUncertainStateForSelfTest();
                var raised = false;
                try { _ = successor.Close(); }
                catch (FanApiException) { raised = true; }
                if (!raised)
                    throw new InvalidOperationException(
                        "fan934: a Close with an un-proven OEM release must fail honestly, not report success");
                var reopened = successor.ReadRecoveryCycleForSelfTest();
                if (!reopened.Found || reopened.CycleId == legacyCycleId || reopened.Attempts != 0 ||
                    reopened.RemainingMs < fullWindow - 5_000 || reopened.Replacements > 1)
                    throw new InvalidOperationException(
                        "fan934: a caller-visible explicit retry must open a fresh BOUNDED cycle after an exhausted " +
                        "journal was refused: " +
                        $"found={reopened.Found} id={reopened.CycleId} attempts={reopened.Attempts} " +
                        $"remaining={reopened.RemainingMs} full={fullWindow} replacements={reopened.Replacements}");
                if (successor.RecoveryRetryTerminalForSelfTest)
                    throw new InvalidOperationException(
                        "fan934: an explicit retry that opened a new cycle must clear the terminal window flag");
                checks.Add(
                    $"fan934-explicit-retry-reopens-bounded-cycle attempts={reopened.Attempts} " +
                    $"remainingMs={reopened.RemainingMs} fullWindowMs={fullWindow} replacements={reopened.Replacements}");
            }
            finally
            {
                successor.ResolveUncertainStateForSelfTest();
                successor.Dispose();
            }

            // 对照：**不同**父 episode 的实例不得被旧周期过度拒绝，也不得盗用旧周期身份，
            // 而应开出自己的新周期（预算完整、零自动更换）。
            var other = new FanHostEngine(
                HostOptions.Parse(new[] { "--port", "8893" }), new HostDiagnosticLog());
            try
            {
                other.EnterFaultLockedAndScheduleRecoveryForSelfTest();
                if (other.RecoveryRetryTerminalForSelfTest)
                    throw new InvalidOperationException(
                        "fan934: a different parent episode must not be over-refused by an unrelated persisted cycle");
                var own = other.ReadRecoveryCycleForSelfTest();
                if (!own.Found || own.CycleId == legacyCycleId || own.Attempts != 0 || own.Replacements != 0)
                    throw new InvalidOperationException(
                        "fan934: a different episode must open its OWN fresh cycle (not inherit/reuse the refused one): " +
                        $"found={own.Found} id={own.CycleId} attempts={own.Attempts} replacements={own.Replacements}");
                checks.Add(
                    $"fan934-different-episode-starts-own-cycle-not-over-refused attempts={own.Attempts} " +
                    $"replacements={own.Replacements}");
            }
            finally
            {
                other.ResolveUncertainStateForSelfTest();
                other.Dispose();
            }

            engine.ClearRecoveryCycleForSelfTest();
            if (engine.ReadRecoveryCycleForSelfTest().Found)
                throw new InvalidOperationException("fan934: recovery journal cleanup failed");
        }
        // FAN-925 / HC 回函 D1+D3：不可宣称项必须是**显式字段**（不能靠文案）。
        {
            var json = engine.RecoveryClaimEvidenceJsonForSelfTest();
            foreach (var required in new[]
                     {
                         "\"oemPhysicalOwnershipMayBeClaimed\":false",
                         "\"virtualCloseIsNotPhysicalRelease\":true",
                         "\"managerStopFieldIsProductHardcoded\":true",
                         "\"routeLostRequiresBridgeReopen\":false",
                         "\"hcCloseCleanupPending\":false",
                     })
            {
                if (!json.Contains(required, StringComparison.Ordinal))
                    throw new InvalidOperationException(
                        $"fan925: recovery claim evidence missing/incorrect '{required}': {json}");
            }
            checks.Add("t2-fan925-recovery-claim-evidence-explicit");
        }
        // FAN-925 B4：route-lost 的**重开归属**（HC 回函 A1–A3）。
        // 首次 route-lost ⇒ 宿主进入"有界等待 bridge 重开"，不再空转被第五道门挡住的 restore；
        // 同一故障周期内第二次 ⇒ 重开环上限（纯函数判定 + 真实记账路径各验一半）。
        {
            if (FanHostEngine.ReopenLoopCapReached(1) || !FanHostEngine.ReopenLoopCapReached(2))
                throw new InvalidOperationException(
                    "fan925: reopen-loop cap must trip exactly on the second route-loss within one cycle");
            engine.MarkReopenRequiredForSelfTest("selftest-close-route-lost");
            if (!engine.RecoveryReopenRequiredForSelfTest || engine.RecoveryReopenCountForSelfTest != 1)
                throw new InvalidOperationException(
                    "fan925: a route-loss must mark the session reopen-required " +
                    $"(required={engine.RecoveryReopenRequiredForSelfTest} count={engine.RecoveryReopenCountForSelfTest})");
            checks.Add("t2-fan925-reopen-required-and-loop-cap");
            // 宿主在进入"等待重开"时必须绑定本次重开票据（§4）：hostInstance + 周期 + 会话代际 + 操作基线。
            var bindingText = engine.ReopenBindingForSelfTest;
            if (bindingText is null ||
                !bindingText.Contains("host=", StringComparison.Ordinal) ||
                !bindingText.Contains("gen=", StringComparison.Ordinal))
                throw new InvalidOperationException(
                    $"fan925: entering reopen-wait must bind this reopen to the host instance/cycle/session generation (binding='{bindingText}')");
            checks.Add($"t2-fan925-reopen-binding-recorded[{bindingText}]");
            // H4：重开收据判定 = Outcome==Completed ∧ 四位副作用齐全；任缺其一或非 Completed 一律不算。
            if (!FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, "None", "None") ||
                FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, false, "None", "None") ||
                FanHostEngine.ReopenReceiptAccepted("Completed", false, true, true, true, "None", "None") ||
                FanHostEngine.ReopenReceiptAccepted("Completed", true, false, true, true, "None", "None") ||
                FanHostEngine.ReopenReceiptAccepted("Completed", true, true, false, true, "None", "None") ||
                FanHostEngine.ReopenReceiptAccepted("Faulted", true, true, true, true, "None", "None") ||
                FanHostEngine.ReopenReceiptAccepted(null, true, true, true, true, "None", "None"))
                throw new InvalidOperationException(
                    "fan925: reopen receipt must require Outcome==Completed AND all four side-effects");
            checks.Add("t2-fan925-reopen-receipt-four-side-effects");
            // §4（FAN-925B）F05 反例：**结构化** Completed + 四位齐全，但 uncertainty/late 非空 ⇒ 必须拒绝。
            if (FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, "RemapInFlight", "None") ||
                FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, "None", "ReadLoopDrainPending") ||
                FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, "RemapInFlight", "ReadLoopDrainPending"))
                throw new InvalidOperationException(
                    "fan925: a Completed receipt with uncertain/late side effects must not count as the current reopen");
            // 字段语义（如实声明口径）：HC 收据**没有该成员**时（null）视为"契约未定义该副作用"，
            // 不当拒绝理由（否则会把真实但不含该字段的收据全部误杀）；只要成员存在就必须为 "None"，
            // 空串/未知值一律拒绝 —— "缺字段必须拒绝"由**绑定字段**（操作 id / 会话代际）强制。
            if (FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, "", "None") ||
                FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, "None", "<unknown>"))
                throw new InvalidOperationException(
                    "fan925: a present-but-not-None uncertainty/late field must be rejected");
            if (!FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, null, null))
                throw new InvalidOperationException(
                    "fan925: an HC contract without uncertainty/late members must not be auto-rejected");
            // 合法当前收据（Completed + 四位 + 两个副作用均为 None）必须被接受。
            if (!FanHostEngine.ReopenReceiptAccepted("Completed", true, true, true, true, "None", "None"))
                throw new InvalidOperationException("fan925: a fully clean current reopen receipt must be accepted");
            checks.Add("f05-reopen-receipt-uncertain-late-rejected-and-member-absent-tolerated");
            // §4 F05 绑定反例：旧 Completed / 跨实例 / 周期变化 / 未换代 / 缺操作 id 一律拒绝。
            const string hostA = "host-A";
            if (FanHostEngine.ReopenBindingRejection(hostA, hostA, "cycle-1", "cycle-1", 5, 6, "op-old", "op-old") is null ||
                FanHostEngine.ReopenBindingRejection(hostA, "host-B", "cycle-1", "cycle-1", 5, 6, "op-old", "op-new") is null ||
                FanHostEngine.ReopenBindingRejection(hostA, hostA, "cycle-1", "cycle-2", 5, 6, "op-old", "op-new") is null ||
                FanHostEngine.ReopenBindingRejection(hostA, hostA, "cycle-1", "cycle-1", 5, 5, "op-old", "op-new") is null ||
                FanHostEngine.ReopenBindingRejection(hostA, hostA, "cycle-1", "cycle-1", 5, 6, "op-old", null) is null)
                throw new InvalidOperationException(
                    "fan925: stale/cross-instance/cross-cycle/same-generation/missing-operation receipts must be rejected");
            // 正例：同实例、同周期、换代、且操作 id 不是重开前基线 ⇒ 通过。
            if (FanHostEngine.ReopenBindingRejection(hostA, hostA, "cycle-1", "cycle-1", 5, 6, "op-old", "op-new") is not null)
                throw new InvalidOperationException(
                    "fan925: a receipt that belongs to this reopen must pass the binding check");
            checks.Add($"f05-reopen-binding-rejects-stale-and-accepts-current");
            // §4.5 F07（FAN-925B）：页面持续不可用时，Fan 恢复执行者与升级路径必须**由纯判定给出**，
            // 不依赖任何 UI 回调；"永远等页面"必须能在这条判定上被识别为不可接受。
            if (FanHostEngine.ReopenOwnershipDecision(false, 999_999, 15_000, false) != "none" ||
                FanHostEngine.ReopenOwnershipDecision(true, 0, 15_000, false) !=
                    "fan-host-budgeted-supervision;awaiting-bridge-reopen" ||
                FanHostEngine.ReopenOwnershipDecision(true, 15_000, 15_000, false) !=
                    "fan-host-requests-controlled-replacement" ||
                FanHostEngine.ReopenOwnershipDecision(true, 600_000, 15_000, true) !=
                    "fan-host-terminal-accounting;replacement-already-requested")
                throw new InvalidOperationException(
                    "f07: reopen ownership decision must be bounded and must escalate exactly once without any UI callback");
            if (engine.RecoveryOwnerForSelfTest is not ("fan-host-budgeted-supervision;awaiting-bridge-reopen" or "none"))
                throw new InvalidOperationException(
                    $"f07: entering reopen-wait must record the sole fan recovery owner (owner='{engine.RecoveryOwnerForSelfTest}')");
            if (engine.ControlledReplacementRequestedForSelfTest)
                throw new InvalidOperationException("f07: replacement must not be requested before the bounded bridge-wait budget elapses");
            checks.Add($"f07-ui-unavailable-reopen-ownership[{engine.RecoveryOwnerForSelfTest}]");
            // §6 F02（FAN-925B）：**cleanup 不能冒充 release**。构造"有写历史 + HC 清理完整 +
            // 释放动作未证"的快照 ⇒ 收尾判据必须为 false；"本周期无写历史"的诚实对照仍为 true。
            var cleanupCompleteSnapshot = new HostState
            {
                State = "Stopped",
                UnknownState = false,
                HcCloseCleanupPending = false,
                HardwareWritesEnabled = false,
            };
            cleanupCompleteSnapshot.HcVirtualCloseReturned = true;
            cleanupCompleteSnapshot.HcDeviceManagerStopCompleted = true;
            cleanupCompleteSnapshot.HcManagerFactoryLifecycle = "Started";
            cleanupCompleteSnapshot.HcDeviceManagerLifecycle = "Started";
            // ① 诚实对照：本周期无写入历史 ⇒ 不适用释放 ⇒ 收尾安全。
            if (!LocalFanHostServer.ParentRecoveryIsSafeToFinalizeForSelfTest(cleanupCompleteSnapshot))
                throw new InvalidOperationException(
                    "f02: a clean close with no write history this cycle must still be safe to finalize");
            // ② 有写历史 + 仅 cleanup 完成（释放动作未证）⇒ 必须**不**安全（旧写法会安全）。
            cleanupCompleteSnapshot.HardwareWritesObserved = true;
            cleanupCompleteSnapshot.OemReleaseActionKind = "unknown-release-action";
            if (LocalFanHostServer.ParentRecoveryIsSafeToFinalizeForSelfTest(cleanupCompleteSnapshot))
                throw new InvalidOperationException(
                    "f02: hardware cleanup must NOT substitute for a proven release action");
            // ③ 有写历史 + 当次释放动作已证 ⇒ 安全。
            cleanupCompleteSnapshot.OemReleaseActionKind = "proven-by-scope-receipts";
            if (!LocalFanHostServer.ParentRecoveryIsSafeToFinalizeForSelfTest(cleanupCompleteSnapshot))
                throw new InvalidOperationException(
                    "f02: a proven release action with complete cleanup must be safe to finalize");
            checks.Add("f02-cleanup-does-not-substitute-for-release");
            // §6 F03/F04（FAN-925B）：收据 → 动作分类 + 主/回退合并。
            if (FanHostEngine.ClassifyReleaseAction("transported") != OemReleaseAction.Proven ||
                FanHostEngine.ClassifyReleaseAction("partial") != OemReleaseAction.Proven ||
                FanHostEngine.ClassifyReleaseAction("no-receipts") != OemReleaseAction.Unknown ||
                FanHostEngine.ClassifyReleaseAction("io-exception-unknown") != OemReleaseAction.Unknown ||
                FanHostEngine.ClassifyReleaseAction("receipt-api-fault") != OemReleaseAction.Unknown ||
                FanHostEngine.ClassifyReleaseAction("explicit-failure") != OemReleaseAction.Failed ||
                FanHostEngine.ClassifyReleaseAction("mixed-failed-unknown") != OemReleaseAction.Failed ||
                // FAN-934 R2 §3-A.1（修前反例 → 修后必过）：`unsupported` 只由旧 runtime"不支持
                // 作用域"产生，**不是**兼容证书；默认分支的"未登记/无 scope"也必须 fail-closed。
                FanHostEngine.ClassifyReleaseAction("unsupported") != OemReleaseAction.Unknown ||
                FanHostEngine.ClassifyReleaseAction("unregistered-route-no-scope") != OemReleaseAction.Unknown ||
                // FAN-934 §4.A：非 ASUS 回调合同证据 → 路线合同释放（非 ASUS 只有在本轮操作回调真实返回时才产出）；
                // 回调未返回 ⇒ 失败；回调前提不成立 ⇒ 未知。都不允许被洗成成功。
                FanHostEngine.ClassifyReleaseAction("compat-route-without-scope") != OemReleaseAction.CompatRouteWithoutScope ||
                FanHostEngine.ClassifyReleaseAction("compat-route-callback-not-returned") != OemReleaseAction.Failed ||
                FanHostEngine.ClassifyReleaseAction("compat-route-precondition-unsatisfied") != OemReleaseAction.Unknown)
                throw new InvalidOperationException(
                    "f03/f04: receipt kinds must classify to the documented release actions (partial is not a full success; unsupported/unregistered-no-scope are NOT compat certificates)");
            if (FanHostEngine.MergeReleaseActions(OemReleaseAction.Unknown, OemReleaseAction.Proven) != OemReleaseAction.Proven ||
                FanHostEngine.MergeReleaseActions(OemReleaseAction.Proven, OemReleaseAction.Failed) != OemReleaseAction.Proven ||
                FanHostEngine.MergeReleaseActions(OemReleaseAction.Unknown, OemReleaseAction.Unknown) != OemReleaseAction.Unknown ||
                FanHostEngine.MergeReleaseActions(OemReleaseAction.Failed, OemReleaseAction.Unknown) != OemReleaseAction.Failed ||
                FanHostEngine.MergeReleaseActions(OemReleaseAction.CompatRouteWithoutScope, OemReleaseAction.Unknown) != OemReleaseAction.CompatRouteWithoutScope)
                throw new InvalidOperationException(
                    "f03/f04: primary/fallback release evidence must merge without overwriting either side");
            // 异机型（无 scope 能力）不得被 ASUS 判据误伤；"已声明支持 scope 却读不到收据"不得降成兼容成功。
            // FAN-934 R2 §3-A.1：默认分支"未登记/无 scope"与旧 `unsupported` 都**不得**被判安全
            // （有写历史时它们不是合格释放证据）；无写历史仍按诚实对照放行。
            if (!FanHostEngine.IsOemReleaseSafeForSelfTest(true, "compat-route-without-scope") ||
                FanHostEngine.IsOemReleaseSafeForSelfTest(true, "unknown-release-action") ||
                FanHostEngine.IsOemReleaseSafeForSelfTest(true, "unsupported") ||
                FanHostEngine.IsOemReleaseSafeForSelfTest(true, "unregistered-route-no-scope") ||
                !FanHostEngine.IsOemReleaseSafeForSelfTest(false, "unregistered-route-no-scope") ||
                !FanHostEngine.IsOemReleaseSafeForSelfTest(false, "unsupported"))
                throw new InvalidOperationException(
                    "f04: scope-less reviewed routes keep their contract, but a claimed-scope route with unknown receipts must not be treated as success");
            // 新的默认分类（未登记/无 scope）必须以**独立** unknown kind 穿透生产判定链，而不是被
            // 旧 `unsupported` 兼容证书放行——直接用发布 DLL 的反例输入作基线。
            {
                var unregistered = RealHcBackend.DecideOperationEvidence(
                    FanEvidenceMode.UnsupportedNoScope, "oem-restore", callbackReturned: false,
                    compatPreconditionsOk: false, "n/a",
                    new RealHcBackend.AsusWriteVerdict("unsupported", "n/a", false, false, false, 0));
                var unregisteredKind = FanHostEngine.ReleaseActionKindName(
                    FanHostEngine.ClassifyReleaseAction(unregistered.Kind));
                if (unregistered.Kind != "unregistered-route-no-scope" || !unregistered.Unknown ||
                    FanHostEngine.ClassifyReleaseAction(unregistered.Kind) != OemReleaseAction.Unknown ||
                    FanHostEngine.IsOemReleaseSafeForSelfTest(true, unregistered.Kind))
                    throw new InvalidOperationException(
                        $"f04: an unregistered/no-scope default must settle as its own unknown and never authorise release " +
                        $"(kind={unregistered.Kind} action={unregisteredKind})");
                // 无写历史的正常关闭仍**允许**（诚实对照，不混为"有写责任已交还"）。
                if (!FanHostEngine.RouteLostCloseIsRelease(false, unregistered.Kind))
                    throw new InvalidOperationException(
                        "f04: a no-write-history close with no scope must still finalize honestly (no write responsibility)");
            }
            checks.Add("f03-f04-release-classification-and-merge");
            // §3.4 反例（反推补齐，2026-09-25；D4 2026-09-26 保留并加固）：
            // route-lost 的关闭边界**不得**成为"已释放"。有写历史 + 释放动作未证 ⇒ 必须 false。
            if (FanHostEngine.RouteLostCloseIsRelease(true, "unknown-release-action") ||
                FanHostEngine.RouteLostCloseIsRelease(true, "not-attempted") ||
                FanHostEngine.RouteLostCloseIsRelease(true, "failed-release-action"))
                throw new InvalidOperationException(
                    "f02: an unproven release must not be authorised by any close boundary (including complete HC cleanup)");
            if (!FanHostEngine.RouteLostCloseIsRelease(true, "proven-by-scope-receipts") ||
                !FanHostEngine.RouteLostCloseIsRelease(false, "not-attempted"))
                throw new InvalidOperationException(
                    "f02: a proven release (or an honest no-write cycle) must still be safe across the close boundary");
            // D4：清参**不得**移除保护——用签名钉守住"释放判定不接受清理/关闭边界入参"这一事实。
            var f02ReleaseSignature = typeof(FanHostEngine).GetMethod(
                nameof(FanHostEngine.RouteLostCloseIsRelease),
                BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public);
            if (f02ReleaseSignature is null || f02ReleaseSignature.GetParameters().Length != 2)
                throw new InvalidOperationException(
                    "f02: the release decision must not accept cleanup/close-boundary inputs (signature pin: exactly 2 parameters)");
            checks.Add("f02-route-lost-close-boundary-is-not-a-release");
            // §3.3 反例（反推补齐，2026-09-25）：回退路径必须由当次 scope 收据判定。
            if (FanHostEngine.AcpiFallbackProven("no-receipts") ||
                FanHostEngine.AcpiFallbackProven("unsupported") ||
                FanHostEngine.AcpiFallbackProven("io-exception-unknown") ||
                FanHostEngine.AcpiFallbackProven("explicit-failure"))
                throw new InvalidOperationException(
