            if (!FanHostEngine.AcpiFallbackProven("transported") || !FanHostEngine.AcpiFallbackProven("partial"))
                throw new InvalidOperationException(
                    "f04: a transmitted/partial fallback receipt must count as proof");
            checks.Add("f04-acpi-fallback-proof-requires-this-operation-receipt");
            // §6 F09（FAN-925B）：详细日志被显式关闭时，**最小责任事件**必须仍然落账。
            {
                var dirG = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "fan925b-f09-" + Guid.NewGuid().ToString("N"));
                System.IO.Directory.CreateDirectory(dirG);
                var logG = new HostDiagnosticLog(dirG, 1024 * 1024);
                logG.Write("host.instance-started", new { credentialVersionId = "deadbeef", credentialFormatOk = true });
                logG.Write("auth.rejected", new { rejectionCategory = "credential-value-mismatch" });
                logG.Write("parent-exit-handoff.accepted", new { acceptingHostInstanceId = "x" });
                var faultText = System.IO.File.Exists(System.IO.Path.Combine(dirG, "fan-host-fault.log"))
                    ? System.IO.File.ReadAllText(System.IO.Path.Combine(dirG, "fan-host-fault.log"))
                    : string.Empty;
                foreach (var name in new[] { "host.instance-started", "auth.rejected", "parent-exit-handoff.accepted" })
                    if (!faultText.Contains("\"eventName\":\"" + name + "\"", StringComparison.Ordinal))
                        throw new InvalidOperationException(
                            $"f09: minimal responsibility event '{name}' must survive an explicitly disabled detailed log");
                if (faultText.Contains("X-YeMan-Fan-Session", StringComparison.Ordinal) ||
                    faultText.Contains("deadbeef", StringComparison.Ordinal) == false)
                    throw new InvalidOperationException("f09: fault ledger must carry the non-secret credential version id and never the credential");
                checks.Add("f09-minimal-responsibility-events-survive-disabled-detailed-log");
            }
            engine.ResetReopenStateForSelfTest();
        }
