        // 未提供 --hc-candidate-assembly 时不注册该组（验收命令必须显式给出候选路径）。
        var candidateChecks = new List<string>();
        try
        {
            // 两组共用同一 sink（runner 直接写入并返回该列表）——不要 AddRange 返回值，否则会自我复制。
            Section18CandidateLifecycle.Run(engine, candidateChecks);
            Section19CandidateLifecycle.Run(engine, candidateChecks);
            Section20CandidateLifecycle.Run(engine, candidateChecks);
            Section21CandidateLifecycle.Run(engine, candidateChecks);
            Section22CandidateLifecycle.Run(engine, candidateChecks);
