            RealHcBackend.SessionRouteMarkerReadyForOpenEventsForSelfTest("route", "route", true, false, false) ||
            RealHcBackend.SessionRouteMarkerMatchesForSelfTest("route", "route", true, false, true))
            throw new InvalidOperationException("OpenEvents must admit HC's pre-open IsOpen marker, while post-open control must still reject it");
        checks.Add("hc-open-events-preopen-marker-ordering");
        checks.Add("hc-asus-setfancurve-return-ignored");
        var terminalCloseGate = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        terminalCloseGate.BlockWritesForClose();
        terminalCloseGate.AllowWritesAfterResume();
        if (!terminalCloseGate.TemperatureWritesBlockedForSelfTest)
            throw new InvalidOperationException("late resume reopened temperature writes after Host close");
        var resumableSuspendGate = new RealHcBackend(HostOptions.Parse(Array.Empty<string>()));
        resumableSuspendGate.BlockWritesForSuspend();
        resumableSuspendGate.AllowWritesAfterResume();
        if (resumableSuspendGate.TemperatureWritesBlockedForSelfTest)
            throw new InvalidOperationException("normal resume did not reopen the suspend-only temperature gate");
        checks.Add("close-write-gate-survives-resume");
        checks.Add("suspend-write-gate-reopens-only-on-resume");
        var handshake = engine.Handshake();
        checks.Add("handshake-safe");
        var state = engine.Open();
        checks.Add("open-no-write");
        _ = engine.OpenEvents();
        checks.Add("open-events-no-write");
        _ = engine.Restore(JsonDocument.Parse("{}").RootElement);
        checks.Add("restore-no-write");
        _ = engine.SuspendForSystemPower();
        checks.Add("system-power-suspend-no-write");
        _ = engine.ResumeForSystemPower();
        checks.Add("system-power-resume-no-write");
        _ = engine.Suspend(JsonDocument.Parse("{}").RootElement);
        checks.Add("suspend-no-write");
        _ = engine.Resume();
        _ = engine.Close();
        checks.Add("close-no-write");
        var guarded = new FanHostEngine(HostOptions.Parse(Array.Empty<string>()));
        guarded.InjectUncertainStateForSelfTest();
        var guardRejected = false;
        try { _ = guarded.Close(); }
        catch (FanApiException ex) when (ex.Code == "OEM_RESTORE_FAILED") { guardRejected = true; }
        var guardedState = guarded.Snapshot();
        checks.Add("close-failure-fault-locked");
        if (!guardRejected || guardedState.State != "FaultLocked" || guardedState.OemRestoreConfirmed)
            throw new InvalidOperationException("close failure did not remain fault-locked");
        var timeoutGuard = new FanHostEngine(HostOptions.Parse(Array.Empty<string>()));
        timeoutGuard.MarkOperationTimeoutForSelfTest();
        var timeoutState = timeoutGuard.Snapshot();
        if (timeoutState.State != "FaultLocked" || timeoutState.UnknownState != true)
            throw new InvalidOperationException("operation timeout did not fault-lock");
        checks.Add("operation-timeout-fault-lock");
        if (FanHostEngine.HasLiveHardwareSessionForSelfTest(false, false, false, false, false, false, true) ||
            !FanHostEngine.HasLiveHardwareSessionForSelfTest(false, true, false, false, false, false, false) ||
            !FanHostEngine.HasLiveHardwareSessionForSelfTest(false, false, true, false, false, false, false) ||
            !FanHostEngine.HasLiveHardwareSessionForSelfTest(false, false, false, true, false, false, false) ||
            !FanHostEngine.HasLiveHardwareSessionForSelfTest(true, false, false, false, false, false, false))
            throw new InvalidOperationException("historical HardwareWritesObserved bit was treated as live HC ownership");
        checks.Add("historical-write-bit-not-live-session");
        var leaseGuard = new FanHostEngine(HostOptions.Parse(Array.Empty<string>()));
        if (!leaseGuard.VerifyLeaseExclusivityForSelfTest())
            throw new InvalidOperationException("active lease was not protected from replacement");
        checks.Add("lease-exclusive");
        var presetLeaseGuard = new FanHostEngine(HostOptions.Parse(Array.Empty<string>()));
        if (!presetLeaseGuard.VerifyPresetLeasePropagationForSelfTest())
            throw new InvalidOperationException("preset request did not preserve the active lease");
        checks.Add("preset-lease-propagation");
        var expiredLeaseCleanupGuard = new FanHostEngine(HostOptions.Parse(Array.Empty<string>()));
        if (!expiredLeaseCleanupGuard.VerifyExpiredLeaseDoesNotBlockSafetyRestoreForSelfTest())
            throw new InvalidOperationException("expired lease blocked safety OEM restore");
        checks.Add("expired-lease-does-not-block-safety-restore");
        var expiredLeaseReleaseGuard = new FanHostEngine(HostOptions.Parse(Array.Empty<string>()));
        if (!expiredLeaseReleaseGuard.VerifyExpiredLeaseReleaseAfterRestoreForSelfTest())
            throw new InvalidOperationException("expired lease blocked safety release after restore");
        checks.Add("expired-lease-release-after-restore");

        // Preset regression: named profiles must become the same single
        // four-node request as a manual edit, while retaining the active
        // lease. This is the path that previously dropped leaseId and forced
        // an unnecessary recovery/disable on every dropdown selection.
        foreach (var presetName in new[] { "soft", "balanced", "aggressive" })
        {
            using var presetDocument = JsonDocument.Parse(
                FanHostEngine.BuildPresetPayloadForSelfTest(presetName, "selftest-lease"));
            var presetRoot = presetDocument.RootElement;
            if (presetRoot.GetProperty("leaseId").GetString() != "selftest-lease")
                throw new InvalidOperationException($"preset {presetName} lost the active lease");
            var presetNodes = presetRoot.GetProperty("nodes").EnumerateArray()
                .Select(node => new FanNode(node.GetProperty("tempC").GetDouble(), node.GetProperty("dutyPercent").GetDouble()))
                .ToArray();
            RealHcBackend.ValidateCurveForSelfTest(presetNodes);
            checks.Add($"preset-{presetName}-one-shot-lease");
        }

        // Boundary regression: node 1 is fixed at 0°C, but its duty is
        // intentionally editable.  HC's FanProfile accepts a non-zero first
        // duty and the value must survive expansion to the 11-point curve.
        var node1At50 = new[]
        {
            new FanNode(0, 50),
            new FanNode(40, 50),
            new FanNode(70, 75),
            new FanNode(100, 100),
        };
        var expanded50 = RealHcBackend.ExpandCurveForSelfTest(node1At50);
        var descending50 = false;
        for (var i = 1; i < expanded50.Length; i++)
            if (expanded50[i] < expanded50[i - 1]) descending50 = true;
        if (expanded50[0] != 50 || descending50)
            throw new InvalidOperationException("node 1 duty 50% was not accepted or produced a descending curve");
        checks.Add("node1-duty-50-accepted");

        var node1At100 = new[]
        {
            new FanNode(0, 100),
            new FanNode(40, 100),
            new FanNode(70, 100),
            new FanNode(100, 100),
        };
        var expanded100 = RealHcBackend.ExpandCurveForSelfTest(node1At100);
        if (expanded100.Any(value => value != 100))
            throw new InvalidOperationException("node 1 duty 100% was not accepted");
        checks.Add("node1-duty-100-accepted");

        var descendingRejected = false;
        try
        {
            RealHcBackend.ValidateCurveForSelfTest(new[]
            {
                new FanNode(0, 50), new FanNode(40, 49),
                new FanNode(70, 80), new FanNode(100, 100),
            });
        }
        catch (FanApiException ex) when (ex.Code == "INVALID_CURVE") { descendingRejected = true; }
        if (!descendingRejected) throw new InvalidOperationException("descending duty curve was not rejected");
        checks.Add("node1-monotonic-reject");

        var node4MinimumRejected = false;
        try
        {
            RealHcBackend.ValidateCurveForSelfTest(new[]
            {
                new FanNode(0, 0), new FanNode(40, 20),
                new FanNode(70, 45), new FanNode(100, 49),
            });
        }
        catch (FanApiException ex) when (ex.Code == "INVALID_CURVE") { node4MinimumRejected = true; }
        if (!node4MinimumRejected) throw new InvalidOperationException("node 4 below 50% was not rejected");
        checks.Add("node4-minimum-reject");

        var final = engine.Snapshot();
        var flagsSafe = !final.HardwareWritesEnabled && !final.HardwareWritesObserved && !final.HardwareWrites && !final.HardwareCapable;
        return new SelfTestResult(flagsSafe, checks, final, handshake, state);
    }
}

internal sealed record SelfTestResult(bool Ok, IReadOnlyList<string> Checks, HostState FinalState, object Handshake, object OpenState);
